function postCodeQuestion(path, values = {}) {
  return postResearch(path, {
    ...values,
    codeQuestionWorkspaceEnabled: codeQuestionWorkspaceEnabled()
  });
}

function enqueueCodeQuestionOfflineCommand(path, values = {}, options = {}) {
  requirePrivateWorkspaceWritable();
  const account = activeAccount();
  if (!account) {
    const error = new Error("Sign in before saving this question offline.");
    error.code = "CODE_QUESTION_SIGN_IN_REQUIRED";
    throw error;
  }
  const mutation = createCodeQuestionOfflineMutation({
    accountUserID: account.userID,
    projectID: options.projectID || values.projectID || activeProjectIDForCodeQuestions(),
    questionID: options.questionID || values.questionID || null,
    clientMutationID: options.clientMutationID,
    commandKind: options.commandKind,
    expectedVersion: options.expectedVersion,
    path,
    payload: values
  });
  const current = {
    ...readCodeQuestionAccountState(localStorage, account.userID),
    outbox: state.codeQuestionOutbox || [],
    conflicts: state.codeQuestionConflicts || []
  };
  const next = enqueueAccountCodeQuestionMutation(current, mutation);
  state.codeQuestionOutbox = next.outbox;
  state.codeQuestionConflicts = next.conflicts;
  persistCodeQuestionAccountState(account.userID);
  return mutation;
}

function acknowledgeCodeQuestionOfflineCommand(clientMutationID) {
  const account = activeAccount();
  if (!account) return false;
  const next = acknowledgeCodeQuestionMutation({
    ...readCodeQuestionAccountState(localStorage, account.userID),
    outbox: state.codeQuestionOutbox || [],
    conflicts: state.codeQuestionConflicts || []
  }, clientMutationID);
  state.codeQuestionOutbox = next.outbox;
  state.codeQuestionConflicts = next.conflicts;
  persistCodeQuestionAccountState(account.userID);
  return true;
}

function markCodeQuestionOfflineCommandConflict(clientMutationID, details = {}) {
  const account = activeAccount();
  if (!account) return false;
  const next = conflictCodeQuestionMutation({
    ...readCodeQuestionAccountState(localStorage, account.userID),
    outbox: state.codeQuestionOutbox || [],
    conflicts: state.codeQuestionConflicts || []
  }, clientMutationID, details);
  state.codeQuestionOutbox = next.outbox;
  state.codeQuestionConflicts = next.conflicts;
  persistCodeQuestionAccountState(account.userID);
  return true;
}

function codeQuestionIsOnline() {
  return navigator.onLine !== false && serverReachable;
}

function codeQuestionRequestContext(projectID = "", options = {}) {
  const account = activeAccount();
  return {
    accountUserID: account?.userID || "",
    sessionToken: account?.sessionToken || "",
    generation: codeQuestionAccountGeneration,
    projectID: String(projectID || "").trim(),
    trackProject: options.trackProject === true || Boolean(String(projectID || "").trim()),
    workspaceEnabled: codeQuestionWorkspaceEnabled()
  };
}

function codeQuestionRequestContextIsCurrent(context) {
  const account = activeAccount();
  return Boolean(
    context?.accountUserID &&
    context.accountUserID === account?.userID &&
    context.sessionToken === account?.sessionToken &&
    context.generation === codeQuestionAccountGeneration &&
    (!context.trackProject || context.projectID === activeProjectIDForCodeQuestions())
  );
}

function codeQuestionContextChangedError() {
  const error = new Error("The signed-in account or active Project changed before this question update completed.");
  error.code = "CODE_QUESTION_REQUEST_CONTEXT_CHANGED";
  return error;
}

function assertCodeQuestionRequestContext(context) {
  if (!codeQuestionRequestContextIsCurrent(context)) throw codeQuestionContextChangedError();
}

function postCodeQuestionForContext(context, path, values = {}) {
  assertCodeQuestionRequestContext(context);
  return postJSON(path, {
    ...values,
    auth: { accountUserID: context.accountUserID },
    codeQuestionWorkspaceEnabled: context.workspaceEnabled
  }, { token: context.sessionToken });
}

function invalidateCodeQuestionListHydration(projectID) {
  const suffix = `:${String(projectID || "").trim()}`;
  for (const key of codeQuestionListHydrationByProject.keys()) {
    if (key.endsWith(suffix)) codeQuestionListHydrationByProject.delete(key);
  }
}

function evictDeniedCodeQuestionCache(error, projectID, questionID = "", options = {}) {
  if (![401, 403, 404].includes(Number(error?.status))) return false;
  const account = activeAccount();
  if (!account) return false;
  if (Number(error.status) === 401) {
    codeQuestionUnauthorizedAccountUserID = account.userID;
    removeCodeQuestionAccountState(localStorage, account.userID);
    unloadCodeQuestionAccountState();
    return true;
  }
  persistCodeQuestionAccountState(account.userID);
  const cached = readCodeQuestionAccountState(localStorage, account.userID);
  const evicted = evictCodeQuestionProject(cached, projectID, {
    questionID: Number(error.status) === 404 && options.questionScoped ? questionID : "",
    conflictCode: error.payload?.code || (Number(error.status) === 403
      ? "CODE_QUESTION_ACCESS_REVOKED"
      : "CODE_QUESTION_RECORD_NOT_FOUND"),
    message: error.message
  });
  writeCodeQuestionAccountState(localStorage, evicted, account.userID);
  loadCodeQuestionAccountStateIntoWorkspace(account.userID);
  if (Number(error.status) === 403 || !options.questionScoped) {
    codeQuestionDeniedProjectIDs.add(projectID);
  }
  return true;
}

async function hydrateCodeQuestionList(projectID = activeProjectIDForCodeQuestions(), options = {}) {
  const id = String(projectID || "").trim();
  if (
    !id || !activeAccount() || !codeQuestionWorkspaceEnabled() || !codeQuestionIsOnline() ||
    codeQuestionDeniedProjectIDs.has(id)
  ) return null;
  const requestContext = codeQuestionRequestContext(id);
  const hydrationKey = `${requestContext.accountUserID}:${requestContext.generation}:${id}`;
  if (options.force) invalidateCodeQuestionListHydration(id);
  if (!codeQuestionListHydrationByProject.has(hydrationKey)) {
    const task = postCodeQuestion("/projects/code-questions/list", { projectID: id })
      .then(async (payload) => {
        if (!codeQuestionRequestContextIsCurrent(requestContext)) return null;
        const questions = codeQuestionListFromServer(payload);
        codeQuestionDeniedProjectIDs.delete(id);
        if (payload.access) codeQuestionAccessByProject.set(id, payload.access);
        const cq = codeQuestionWorkspaceState();
        setCodeQuestionWorkspaceState({
          ...cq,
          questionsByProjectID: {
            ...(cq.questionsByProjectID || {}),
            [id]: questions.map((question) => ({
              ...question,
              listLabel: deriveQuestionListLabel(question)
            }))
          }
        }, { activeProjectID: id });
        saveWorkspaceState();
        if (options.render !== false) await renderWorkspace();
        return questions;
      })
      .catch((error) => {
        codeQuestionListHydrationByProject.delete(hydrationKey);
        if (!codeQuestionRequestContextIsCurrent(requestContext)) return null;
        if (evictDeniedCodeQuestionCache(error, id)) {
          if (options.render !== false) void renderWorkspace();
          return null;
        }
        if (error?.status !== 401 && error?.status !== 403 && error?.status !== 404) {
          console.warn("Code Question list hydration failed.", error);
        }
        return null;
      });
    codeQuestionListHydrationByProject.set(hydrationKey, task);
  }
  return codeQuestionListHydrationByProject.get(hydrationKey);
}

async function hydrateCodeQuestionState(projectID, questionID, options = {}) {
  const pid = String(projectID || activeProjectIDForCodeQuestions() || "").trim();
  const qid = String(questionID || "").trim();
  if (
    !pid || !qid || !activeAccount() || !codeQuestionWorkspaceEnabled() || !codeQuestionIsOnline() ||
    codeQuestionDeniedProjectIDs.has(pid)
  ) return null;
  const requestContext = codeQuestionRequestContext(pid);
  const key = `${requestContext.accountUserID}:${requestContext.generation}:${pid}:${qid}`;
  if (options.force) codeQuestionStateHydrationByQuestion.delete(key);
  if (!codeQuestionStateHydrationByQuestion.has(key)) {
    const task = postCodeQuestion("/projects/code-questions/state", { projectID: pid, questionID: qid })
      .then(async (payload) => {
        if (!codeQuestionRequestContextIsCurrent(requestContext)) return null;
        codeQuestionDeniedProjectIDs.delete(pid);
        const local = {
          definition: getDefinitionForQuestion(qid),
          evidence: getEvidenceForQuestion(qid),
          analysis: getAnalysisForQuestion(qid),
          review: getReviewForQuestion(qid),
          issue: getIssueForQuestion(qid)
        };
        const models = codeQuestionViewModelsFromServer(payload, local);
        const cq = codeQuestionWorkspaceState();
        const currentQuestions = cq.questionsByProjectID?.[pid] || [];
        const questions = currentQuestions.map((question) =>
          question.id === qid
            ? { ...question, ...models.question, listLabel: deriveQuestionListLabel(models.question) }
            : question
        );
        if (!questions.some((question) => question.id === qid)) {
          questions.push({ ...models.question, listLabel: deriveQuestionListLabel(models.question) });
        }
        codeQuestionAccessByProject.set(pid, models.access);
        setCodeQuestionWorkspaceState({
          ...cq,
          questionsByProjectID: { ...(cq.questionsByProjectID || {}), [pid]: questions },
          definitionsByQuestionID: { ...(cq.definitionsByQuestionID || {}), [qid]: models.definition },
          evidenceByQuestionID: { ...(cq.evidenceByQuestionID || {}), [qid]: models.evidence },
          analysisByQuestionID: { ...(cq.analysisByQuestionID || {}), [qid]: models.analysis },
          reviewByQuestionID: { ...(cq.reviewByQuestionID || {}), [qid]: models.review },
          issueByQuestionID: { ...(cq.issueByQuestionID || {}), [qid]: models.issue }
        }, { activeProjectID: pid });
        if (
          codeQuestionWorkspaceState().activeQuestionID === qid &&
          state.researchConversationID === models.question.researchConversationID
        ) {
          alignResearchConversationWithCodeDecision(qid, models.question.researchConversationID);
        }
        if (codeQuestionWorkspaceState().activeQuestionID === qid && !researchQuestionDraft.trim()) {
          researchQuestionDraft = models.definition.questionText || "";
        }
        saveWorkspaceState();
        if (options.render !== false) await renderWorkspace();
        return models;
      })
      .catch((error) => {
        codeQuestionStateHydrationByQuestion.delete(key);
        if (!codeQuestionRequestContextIsCurrent(requestContext)) return null;
        if (evictDeniedCodeQuestionCache(error, pid, qid, { questionScoped: true })) {
          if (options.render !== false) void renderWorkspace();
          return null;
        }
        if (error?.status !== 401 && error?.status !== 403 && error?.status !== 404) {
          console.warn("Code Question state hydration failed.", error);
        }
        return null;
      });
    codeQuestionStateHydrationByQuestion.set(key, task);
  }
  return codeQuestionStateHydrationByQuestion.get(key);
}

async function executeCodeQuestionMutation(path, values, options = {}) {
  const clientMutationID = options.clientMutationID || globalThis.crypto?.randomUUID?.() || `cq-${Date.now()}`;
  const projectID = String(options.projectID || values.projectID || activeProjectIDForCodeQuestions() || "").trim();
  const questionID = String(options.questionID || values.questionID || "").trim();
  const requestContext = codeQuestionRequestContext(projectID);
  assertCodeQuestionRequestContext(requestContext);
  if (!codeQuestionIsOnline()) {
    const queued = enqueueCodeQuestionOfflineCommand(path, values, {
      ...options,
      projectID,
      questionID: questionID || null,
      clientMutationID
    });
    options.applyOptimistic?.(queued);
    saveWorkspaceState();
    return { queued: true, clientMutationID };
  }
  try {
    const payload = await postCodeQuestionForContext(requestContext, path, { ...values, clientMutationID });
    assertCodeQuestionRequestContext(requestContext);
    acknowledgeCodeQuestionOfflineCommand(clientMutationID);
    if (options.hydrate !== false && questionID) {
      await hydrateCodeQuestionState(projectID, questionID, { force: true, render: false });
      assertCodeQuestionRequestContext(requestContext);
    }
    return payload;
  } catch (error) {
    if (!codeQuestionRequestContextIsCurrent(requestContext)) {
      throw codeQuestionContextChangedError();
    }
    if (!error.status) {
      const queued = enqueueCodeQuestionOfflineCommand(path, values, {
        ...options,
        projectID,
        questionID: questionID || null,
        clientMutationID
      });
      options.applyOptimistic?.(queued);
      saveWorkspaceState();
      return { queued: true, clientMutationID };
    }
    if (evictDeniedCodeQuestionCache(error, projectID, questionID, {
      questionScoped: Boolean(questionID)
    })) {
      await renderWorkspace();
      throw error;
    }
    if (error.status === 409) {
      // Preserve the rejected local intent before converting it to a visible
      // conflict record. Direct online mutations are not otherwise in outbox.
      if (codeQuestionMutationIsOfflineSafe({ commandKind: options.commandKind, path })) {
        enqueueCodeQuestionOfflineCommand(path, values, { ...options, clientMutationID });
        markCodeQuestionOfflineCommandConflict(clientMutationID, {
          conflictCode: error.payload?.code,
          serverVersion: error.payload?.serverVersion || error.payload?.artifact?.version || null,
          lastError: error.message
        });
      }
    }
    throw error;
  }
}

async function flushCodeQuestionOutbox() {
  if (!activeAccount() || !codeQuestionIsOnline() || !(state.codeQuestionOutbox || []).length) return;
  const requestContext = codeQuestionRequestContext(activeProjectIDForCodeQuestions(), { trackProject: true });
  assertCodeQuestionRequestContext(requestContext);
  const affected = new Map();
  const blockedScopes = new Set();
  const mutationScope = (mutation) => `${mutation.projectID}:${mutation.questionID || "_project"}`;
  const queuedMutations = [...state.codeQuestionOutbox].filter((mutation) =>
    mutation.accountUserID === requestContext.accountUserID
  );
  for (const mutation of queuedMutations) {
    if (!codeQuestionRequestContextIsCurrent(requestContext)) return;
    const scope = mutationScope(mutation);
    if (blockedScopes.has(scope)) {
      markCodeQuestionOfflineCommandConflict(mutation.id, {
        conflictCode: "CODE_QUESTION_DEPENDENCY_CONFLICT",
        lastError: "A prior queued change for this question conflicted. This dependent change was held without replay."
      });
      continue;
    }
    try {
      await postCodeQuestionForContext(requestContext, mutation.path, {
        ...mutation.payload,
        clientMutationID: mutation.clientMutationID,
        idempotencyKey: mutation.payload?.idempotencyKey || mutation.clientMutationID
      });
      assertCodeQuestionRequestContext(requestContext);
      acknowledgeCodeQuestionOfflineCommand(mutation.id);
      if (mutation.questionID) {
        affected.set(mutation.id, {
          projectID: mutation.projectID,
          questionID: mutation.questionID
        });
      }
      else invalidateCodeQuestionListHydration(mutation.projectID);
    } catch (error) {
      if (!codeQuestionRequestContextIsCurrent(requestContext)) return;
      if (evictDeniedCodeQuestionCache(error, mutation.projectID, mutation.questionID || "", {
        questionScoped: Boolean(mutation.questionID)
      })) {
        await renderWorkspace();
        return;
      }
      if (error.status === 409) {
        markCodeQuestionOfflineCommandConflict(mutation.id, {
          conflictCode: error.payload?.code,
          serverVersion: error.payload?.serverVersion || error.payload?.artifact?.version || null,
          lastError: error.message
        });
        blockedScopes.add(scope);
        continue;
      }
      if (!error.status || error.status >= 500) break;
      markCodeQuestionOfflineCommandConflict(mutation.id, {
        conflictCode: error.payload?.code || "CODE_QUESTION_COMMAND_REJECTED",
        lastError: error.message
      });
    }
  }
  for (const { projectID, questionID } of affected.values()) {
    if (!codeQuestionRequestContextIsCurrent(requestContext)) return;
    await hydrateCodeQuestionState(projectID, questionID, { force: true, render: false });
    if (!codeQuestionRequestContextIsCurrent(requestContext)) return;
  }
  if (!codeQuestionRequestContextIsCurrent(requestContext)) return;
  saveWorkspaceState();
  await renderWorkspace();
}

function ensureCodeQuestionEvidenceWorkspace(questionID) {
  return getEvidenceForQuestion(questionID);
}

function ensureCodeQuestionShellForProject(project, options = {}) {
  if (!codeQuestionWorkspaceEnabled() || !project) return;
  const projectID = String(projectDetailKey(project) || "").trim();
  if (!projectID) return;
  const cq = codeQuestionWorkspaceState();
  const currentProjectPanes = (cq.openPanes || []).filter((pane) => pane.projectID === projectID);
  if (!currentProjectPanes.length || (cq.openPanes || []).some((pane) => pane.projectID !== projectID)) {
    setCodeQuestionWorkspaceState(
      switchCodeQuestionProject(cq, projectID, { openIndex: options.openIndex === true }),
      { activeProjectID: projectID, syncDeepLink: true }
    );
  } else if (
    cq.activeQuestionID &&
    currentProjectPanes.some((pane) => pane.paneRole === "research")
  ) {
    setCodeQuestionWorkspaceState(
      openCodeDecisionSurface(cq, {
        projectID,
        questionID: cq.activeQuestionID,
        questionText: getDefinitionForQuestion(cq.activeQuestionID)?.questionText
      }),
      { activeProjectID: projectID, syncDeepLink: true }
    );
  }
}

const webFreePlanLimits = Object.freeze({ savedItems: 0, notes: 0 });
let planLimitNoticePromise = null;

function webFreePlanUsage() {
  const summary = currentContentSummary();
  const noteTargets = new Set(
    (summary.annotations || [])
      .filter((annotation) => !annotation.deletedAt && String(annotation.noteBody || "").trim())
      .map((annotation) => [
        annotation.codeVersion || defaultSyncCodeVersion,
        annotation.sectionID || "",
        normalizeAnnotationBlockID(annotation.blockID)
      ].join(":"))
  );
  return {
    savedItems: (summary.savedItems || []).filter((item) => !item.deletedAt).length,
    notes: noteTargets.size
  };
}

function planUsageRows() {
  const usage = webFreePlanUsage();
  const rows = isProAccount()
    ? [
        { label: "Saved sections", value: "Unlimited" },
        { label: "Notes", value: "Unlimited" }
      ]
    : [
        {
          label: "Saved sections",
          value: "Requires Pro"
        },
        {
          label: "Notes",
          value: "Requires Pro"
        }
      ];
  if (hasCapability("research")) {
    rows.push({
      label: "Research",
      value: isProAccount()
        ? settingsResearchAllowanceSummary(researchUsage)
        : "Available with Pro"
    });
  } else if (isProAccount()) {
    rows.push({ label: "Research", value: "100 turns included monthly" });
  }
  return rows;
}

function researchUsageCopy(usage) {
  if (!usage) return "Research turn status is unavailable.";
  const included = Number(usage.includedRemaining) || 0;
  const purchased = Number(usage.purchasedRemaining) || 0;
  if (usage.totalRemaining === null) {
    return `${included.toLocaleString()} included turns remain this month. Continued access is available.`;
  }
  const additionalCopy = purchased > 0
    ? ` ${purchased.toLocaleString()} additional ${purchased === 1 ? "turn is" : "turns are"} also available.`
    : "";
  return `${included.toLocaleString()} included turns remain this month.${additionalCopy}`;
}

function hasAvailableWebResearchTurnPack(usage = researchUsage) {
  return Boolean((usage?.packs || []).some((pack) => pack.webAvailable));
}

function renderPlanUsageRows(container) {
  if (!container) return;
  clear(container);
  planUsageRows().forEach((row) => {
    const item = document.createElement("p");
    const label = document.createElement("span");
    label.textContent = row.label;
    const value = document.createElement("strong");
    value.textContent = row.value;
    item.append(label, value);
    container.append(item);
  });
  container.hidden = false;
  container.setAttribute("aria-hidden", "false");
}

function renderSavedPlanUsage(container) {
  if (!container) return;
  if (isProAccount()) {
    container.hidden = true;
    return;
  }
  const usage = webFreePlanUsage();
  container.textContent =
    "Saved work requires Pro. Existing saved work is preserved.";
  container.hidden = false;
}

function refreshVisiblePlanUsage() {
  document.querySelectorAll(".settings-plan-usage").forEach(renderPlanUsageRows);
  document.querySelectorAll(".saved-plan-usage").forEach(renderSavedPlanUsage);
}

function presentWorkspaceIssue(message, options = {}) {
  if (!workspaceIssue || !workspaceIssueCopy || !message) return;
  workspaceIssueCopy.textContent = message;
  activeWorkspaceIssueDismiss = options.onDismiss || null;
  activeWorkspaceIssueAction = typeof options.onAction === "function" ? options.onAction : null;
  if (workspaceIssueAction) {
    workspaceIssueAction.hidden = !activeWorkspaceIssueAction;
    workspaceIssueAction.textContent = options.actionLabel || "Review";
  }
  workspaceIssue.hidden = false;
}

function dismissWorkspaceIssue() {
  if (!workspaceIssue) return;
  try { activeWorkspaceIssueDismiss?.(); }
  catch {
    workspaceIssueCopy.textContent = "Dismissal could not be saved. Free browser storage and try again; older workspace data remains preserved.";
    return;
  }
  workspaceIssue.hidden = true;
  activeWorkspaceIssueAction = null;
  activeWorkspaceIssueDismiss = null;
}

workspaceIssueAction?.addEventListener("click", () => {
  activeWorkspaceIssueAction?.();
  dismissWorkspaceIssue();
});
workspaceIssueDismiss?.addEventListener("click", dismissWorkspaceIssue);

const pendingProSaveKey = "permitext.pendingProSave.v1";
const proUpgradeIntentKey = "permitext.proUpgradeIntent.v1";
const incomingProUpgrade = new URLSearchParams(location.search).get("intent") === "upgrade-pro";
let proUpgradeCaptured = false;

function clearProUpgradeIntent() {
  try { sessionStorage.removeItem(proUpgradeIntentKey); } catch { /* No stored intent. */ }
}

function readProUpgradeIntent() {
  try {
    const intent = JSON.parse(sessionStorage.getItem(proUpgradeIntentKey) || "null");
    if (!intent || !Number.isFinite(intent.expiresAt) || intent.expiresAt <= Date.now() ||
        (intent.accountID && intent.accountID !== activeAccount()?.userID)) {
      clearProUpgradeIntent();
      return null;
    }
    return intent;
  } catch { clearProUpgradeIntent(); return null; }
}

async function resumeProUpgradeIntent() {
  if (!proUpgradeCaptured) {
    proUpgradeCaptured = true;
    if (incomingProUpgrade) {
      try {
        sessionStorage.setItem(proUpgradeIntentKey, JSON.stringify({
          accountID: activeAccount()?.userID || null,
          expiresAt: Date.now() + 30 * 60 * 1000
        }));
      } catch { /* The account dialog can still be opened normally. */ }
      const url = new URL(location.href);
      url.searchParams.delete("intent");
      history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
    }
  }
  if (!readProUpgradeIntent()) return;
  const existing = document.querySelector(".account-dialog");
  if (existing?.open) return;
  existing?.remove();
  toggleAccountDialog({ upgrade: true });
}

let resumingProSave = false;

function clearPendingProSave() {
  try { sessionStorage.removeItem(pendingProSaveKey); } catch { /* Reading remains available. */ }
}

function preservePendingProSave(section) {
  const target = {};
  for (const key of ["sectionID", "codeVersion", "codePrefix", "chapterID", "chapterNumber", "sectionNumber", "title", "blockID", "selectedText", "text"]) {
    if (["string", "number"].includes(typeof section[key])) target[key] = section[key];
  }
  try {
    sessionStorage.setItem(pendingProSaveKey, JSON.stringify({
      target, accountID: activeAccount()?.userID || null, expiresAt: Date.now() + 2 * 60 * 60 * 1000
    }));
  } catch { /* The current Reader remains available if session storage is full. */ }
}

function readPendingProSave() {
  try {
    const intent = JSON.parse(sessionStorage.getItem(pendingProSaveKey) || "null");
    if (!intent) return null;
    if (!intent.target?.sectionID || !Number.isFinite(intent.expiresAt) || intent.expiresAt <= Date.now() ||
        (intent.accountID && intent.accountID !== activeAccount()?.userID)) {
      clearPendingProSave();
      return null;
    }
    return intent;
  } catch { clearPendingProSave(); return null; }
}

async function resumePendingProSave() {
  if (resumingProSave || !activeAccount() || !hasCapability("saved-work")) return false;
  const intent = readPendingProSave();
  if (!intent) return false;
  resumingProSave = true;
  try {
    // Resume a section save, never a guest Project membership or another account's work.
    if (await persistSectionBookmark(intent.target, true, { attachToWorkspaceProject: false })) {
      clearPendingProSave();
      presentWorkspaceIssue("Your section is saved. Pro is active.");
      return true;
    }
  } finally { resumingProSave = false; }
  return false;
}

function presentPlanLimitNotice(title, message) {
  if (planLimitNoticePromise) return planLimitNoticePromise;
  planLimitNoticePromise = (async () => {
    const accepted = await confirmWebWarning(title, message, { confirmLabel: "View Pro", cancelLabel: "Keep reading" });
    if (accepted) await focusUtility("settings");
    return accepted;
  })().finally(() => {
    planLimitNoticePromise = null;
  });
  return planLimitNoticePromise;
}

function entitlementSourceLabel(entitlement = currentEntitlement()) {
  if (!entitlement) return "Free";
  if (entitlement.source === "webSubscription") return "Web subscription";
  if (entitlement.source === "appleSubscription") return "Apple subscription";
  if (entitlement.source === "lifetimeGrant") return "Lifetime Pro";
  return entitlement.source || "Pro";
}

function storeAccountEntitlement(entitlement) {
  if (!state.account) return;
  const nextEntitlement = entitlement || null;
  if (clientValuesMatch(state.account.entitlement || null, nextEntitlement)) {
    void reconcileOfflineFeatureAccess(hasCapability("offline-access")).catch(() => {});
    return false;
  }
  state.account = { ...state.account, entitlement: nextEntitlement };
  if (syncedContent && syncedContent.userID === state.account.userID) {
    syncedContent = {
      ...syncedContent,
      entitlement: nextEntitlement,
      capabilityContract: null
    };
  }
  persistAccountSession();
  saveWorkspaceState();
  void reconcileOfflineFeatureAccess(hasCapability("offline-access")).catch(() => {});
  return true;
}

function delay(milliseconds) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, milliseconds);
  });
}

async function refreshEntitlementAfterCheckoutReturn() {
  const searchParams = new URLSearchParams(window.location.search);
  const account = activeAccount();
  if (searchParams.get("checkout") !== "success" || !account) return;
  const sessionID = searchParams.get("session_id");
  const checkoutPackage = searchParams.get("package") === "research" ? "research" : "pro";
  const checkoutActive = () => checkoutPackage === "research"
    ? hasCapability("research")
    : isProAccount();
  if (sessionID && !checkoutActive()) {
    try {
      const payload = await postJSON("/billing/stripe/restore", {
        auth: { accountUserID: account.userID },
        checkoutSessionID: sessionID
      }, { token: account.sessionToken });
      storeAccountEntitlement(payload.entitlement || null);
    } catch {
      // Fall through to webhook polling; Stripe may still deliver the entitlement.
    }
  }
  for (let attempt = 0; attempt < 8; attempt += 1) {
    await loadSyncedContent({ force: true });
    if (checkoutActive()) {
      clearCheckoutReturnURL();
      await renderWorkspace();
      return;
    }
    await delay(1500);
  }
  await renderWorkspace();
}

function clearCheckoutReturnURL() {
  const url = new URL(window.location.href);
  url.searchParams.delete("checkout");
  url.searchParams.delete("session_id");
  url.searchParams.delete("package");
  url.searchParams.delete("appleSignIn");
  const next = `${url.pathname}${url.search}${url.hash}`;
  window.history.replaceState({}, "", next || "/");
}

function browserCredentialID() {
  const existing = typeof state.browserCredentialID === "string" ? state.browserCredentialID.trim() : "";
  if (existing) return existing;
  state.browserCredentialID = crypto.randomUUID();
  saveWorkspaceState();
  return state.browserCredentialID;
}

async function repairAppleBrowserAccountLink(account, entitlement) {
  const browserID = typeof state.browserCredentialID === "string" ? state.browserCredentialID.trim() : "";
  if (!account || account.authProvider !== "apple" || entitlement || !browserID) {
    return null;
  }
  const payload = await postJSON("/account/link-browser", {
    auth: { accountUserID: account.userID },
    browserCredentialID: browserID
  }, { token: account.sessionToken });
  if (payload.account || payload.entitlement) {
    storeAccountEntitlement(payload.entitlement || null);
  }
  return payload;
}

function decodeJWTPart(value) {
  try {
    const normalized = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
    return JSON.parse(atob(padded));
  } catch {
    return {};
  }
}

function appleDisplayName(user = {}) {
  const name = user.name || {};
  const parts = [name.firstName, name.lastName].map((part) => String(part || "").trim()).filter(Boolean);
  return parts.join(" ");
}

async function appleWebSignInConfig() {
  if (!appleWebConfigPromise) {
    appleWebConfigPromise = api("/account/apple-web-config").catch((error) => {
      appleWebConfigPromise = null;
      throw error;
    });
  }
  return appleWebConfigPromise;
}

async function clerkWebSignInConfig() {
  if (!clerkWebConfigPromise) {
    clerkWebConfigPromise = api("/account/clerk/config").catch((error) => {
      clerkWebConfigPromise = null;
      throw error;
    });
  }
  return clerkWebConfigPromise;
}

function loadClerkComponentScript(config, path) {
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = `${config.frontendAPIURL}/npm/${path}`;
    script.async = true;
    script.crossOrigin = "anonymous";
    script.dataset.clerkPublishableKey = config.publishableKey;
    const fail = () => {
      window.clearTimeout(timeout);
      script.remove();
      reject(new Error("Could not load secure sign-in. Reload and try again."));
    };
    const timeout = window.setTimeout(fail, 15000);
    script.onload = () => { window.clearTimeout(timeout); resolve(); };
    script.onerror = fail;
    document.head.append(script);
  });
}

function loadClerkScript(config) {
  if (clerkScriptPromise) return clerkScriptPromise;
  clerkScriptPromise = (async () => {
    // ClerkJS 6 ships its prebuilt verification UI separately. Supply it on the
    // first load of the shared instance, as in Clerk's JavaScript quickstart.
    if (window.Clerk?.loaded && !window.Clerk.uiVersion) {
      throw new Error("Secure sign-in needs to reload before identity verification. Reload and try again.");
    }
    if (!window.__internal_ClerkUICtor) {
      await loadClerkComponentScript(config, "@clerk/ui@1/dist/ui.browser.js");
    }
    if (!window.__internal_ClerkUICtor) throw new Error("Secure sign-in UI did not initialize.");
    if (!window.Clerk) {
      await loadClerkComponentScript(config, "@clerk/clerk-js@6/dist/clerk.browser.js");
    }
    if (!window.Clerk) throw new Error("ClerkJS did not initialize.");
    await window.Clerk.load({ ui: { ClerkUI: window.__internal_ClerkUICtor } });
    return window.Clerk;
  })().catch((error) => {
    clerkScriptPromise = null;
    throw error;
  });
  return clerkScriptPromise;
}

async function completeClerkPermitextSignIn(config) {
  const requestIdentity = captureAccountRequest();
  const existingAccount = activeAccount();
  const clerk = await loadClerkScript(config);
  requireCurrentAccountRequest(requestIdentity);
  if (!clerk.isSignedIn || !clerk.session || !clerk.user?.id) return null;
  const clerkSession = clerk.session;
  const clerkUser = clerk.user;
  const sessionToken = await clerkSession.getToken();
  requireCurrentAccountRequest(requestIdentity);
  if (clerk.session !== clerkSession || clerk.user?.id !== clerkUser.id) throw accountContextChangedError();
  if (!sessionToken) throw new Error("Secure sign-in did not return a session token.");
  const targetUserID = `clerk:${clerkUser.id}`;
  const linkFrom = existingAccount && existingAccount.userID !== targetUserID
    ? { accountUserID: existingAccount.userID, sessionToken: existingAccount.sessionToken }
    : undefined;
  const displayName = clerkUser.fullName || clerkUser.firstName || "Permitext account";
  const completeSignIn = async () => {
    if (linkFrom) await requireAccountLinkWorkSaved(existingAccount, requestIdentity);
    requireCurrentAccountRequest(requestIdentity);
    const payload = await postJSON("/account/sign-in", {
      credential: {
        provider: "clerk",
        providerUserID: clerkUser.id,
        sessionToken,
        displayName,
        signedInAt: new Date().toISOString()
      },
      linkFrom
    }, { token: existingAccount?.sessionToken });
    requireCurrentAccountRequest(requestIdentity);
    return storeSignedInAccount(payload, displayName);
  };
  return linkFrom ? withAccountLinkWriteFence(requestIdentity, completeSignIn) : completeSignIn();
}

async function signOutCapturedClerkSession(account, requestIdentity) {
  requireCurrentAccountRequest(requestIdentity);
  if (account?.authProvider !== "clerk" && !account?.userID?.startsWith("clerk:")) return;
  // Reloaded workspaces restore the Permitext session before lazily loading
  // Clerk. An absent window.Clerk does not mean the provider is signed out.
  const config = await clerkWebSignInConfig();
  requireCurrentAccountRequest(requestIdentity);
  if (!config.available) throw new Error("Secure sign-out is unavailable. Reconnect and try again.");
  const clerk = await loadClerkScript(config);
  requireCurrentAccountRequest(requestIdentity);
  if (clerk.status !== "ready") throw new Error("Secure sign-out could not connect. Reconnect and try again.");
  let session = clerk.session;
  if (!session && !clerk.isSignedIn) return;
  if (!session?.id || `clerk:${clerk.user?.id}` !== account.userID) {
    // Another tab/origin can switch Clerk while this workspace keeps its own
    // backend session. Refresh and end only the captured owner's session.
    if (!clerk.client?.reload) throw new Error("Secure sign-out could not refresh. Reconnect and try again.");
    const client = await clerk.client.reload();
    requireCurrentAccountRequest(requestIdentity);
    if (clerk.status !== "ready" || !Array.isArray(client?.sessions)) {
      throw new Error("Secure sign-out could not refresh. Reconnect and try again.");
    }
    const matching = client.sessions.filter((candidate) =>
      candidate?.id && `clerk:${candidate.user?.id}` === account.userID &&
      ["active", "pending"].includes(candidate.status));
    if (matching.length > 1) throw new Error("Multiple secure sessions need review before signing out.");
    if (!matching.length) return; // This owner's provider session already ended.
    session = matching[0];
  }
  // Target only the captured provider session. The callback prevents provider
  // navigation from interrupting Permitext's remaining sign-out cleanup.
  await clerk.signOut(() => {}, { sessionId: session.id });
  requireCurrentAccountRequest(requestIdentity);
  if (clerk.session?.id === session.id) {
    throw new Error("Secure sign-out did not finish. Reconnect and try again.");
  }
}

async function signInWithClerkWeb(config, mode = "signIn") {
  const existingSession = await completeClerkPermitextSignIn(config);
  if (existingSession) return existingSession;
  const returnURL = new URL(window.location.href);
  returnURL.searchParams.set("clerk_return", "1");
  const authorizationURL = new URL(config.accountPortalSignInURL);
  if (mode === "signUp") authorizationURL.pathname = authorizationURL.pathname.replace(/\/sign-in\/?$/, "/sign-up");
  authorizationURL.searchParams.set("redirect_url", returnURL.toString());
  window.location.assign(authorizationURL.toString());
  return new Promise(() => {});
}

async function resumeClerkSignInReturn() {
  const currentURL = new URL(window.location.href);
  if (currentURL.searchParams.get("clerk_return") !== "1") return null;
  currentURL.searchParams.delete("clerk_return");
  window.history.replaceState({}, "", `${currentURL.pathname}${currentURL.search}${currentURL.hash}`);
  state.utilities.settings = true;
  saveWorkspaceState();
  try {
    const config = await clerkWebSignInConfig();
    if (!config.available) {
      throw new Error("Secure sign-in is not configured for this local app.");
    }
    const account = await completeClerkPermitextSignIn(config);
    if (!account) throw new Error("Secure sign-in did not create an active session.");
    clerkSignInReturnNotice = {
      message: "Signed in successfully.",
      isError: false
    };
    return account;
  } catch (error) {
    clerkSignInReturnNotice = {
      message: `Sign-in could not be completed. ${String(error?.message || "Please try again from Account.")}`,
      isError: true
    };
    console.warn("Could not complete secure sign-in return.", error);
    return null;
  }
}

function loadAppleIDScript() {
  if (window.AppleID?.auth) return Promise.resolve();
  if (appleIDScriptPromise) return appleIDScriptPromise;
  appleIDScriptPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://appleid.cdn-apple.com/appleauth/static/jsapi/appleid/1/en_US/appleid.auth.js";
    script.async = true;
    script.onload = () => resolve();
    script.onerror = () => {
      appleIDScriptPromise = null;
      reject(new Error("Could not load Sign in with Apple."));
    };
    document.head.append(script);
  });
  return appleIDScriptPromise;
}

function accountDisplayName(account = state.account) {
  return account?.displayName || account?.userID || "this browser";
}

function retargetQueuedMutation(mutation, sourceUserID, targetUserID) {
  const kind = mutation && typeof mutation === "object" ? Object.keys(mutation)[0] : null;
  const record = kind ? mutation[kind] : null;
  if (!kind || !record || typeof record !== "object") return mutation;
  const sourcePrefix = `${sourceUserID}:`;
  const recordID = typeof record.id === "string" && record.id.startsWith(sourcePrefix)
    ? `${targetUserID}:${record.id.slice(sourcePrefix.length)}`
    : record.id;
  return { [kind]: { ...record, id: recordID, userID: targetUserID } };
}

function retargetSyncOutbox(sourceUserID, targetUserID) {
  if (!sourceUserID || sourceUserID === targetUserID) return;
  state.syncOutbox = (state.syncOutbox || []).map((item) => {
    if (item.accountUserID !== sourceUserID) return item;
    const mutation = retargetQueuedMutation(item.mutation, sourceUserID, targetUserID);
    const recordID = syncMutationRecordID(mutation);
    return {
      ...item,
      id: `${targetUserID}:${recordID}`,
      accountUserID: targetUserID,
      recordID,
      mutation,
      queuedAt: new Date().toISOString(),
      attemptCount: 0,
      lastError: null
    };
  });
}

function storeSignedInAccount(payload, fallbackDisplayName = "Web browser") {
  const account = payload.account;
  if (!account?.appUserID || !account?.backendSessionToken) {
    throw new Error("Sign in did not return a backend session.");
  }
  codeQuestionUnauthorizedAccountUserID = "";
  const previousUserID = state.account?.userID;
  if (previousUserID) persistCodeQuestionAccountState(previousUserID);
  const confirmedRecoveries = [];
  if (payload.mergedAccount) {
    confirmedRecoveries.push(confirmedAccountLinkRecovery(payload.mergedAccount, previousUserID, account.appUserID));
  }
  // This fresh authenticated response reads the server-owned merge checkpoint,
  // which survives a lost response or a later link. Account metadata is not proof.
  // Never derive access from the previously open account, stored workspace
  // metadata, or an unconfirmed source-side recovery index.
  for (const sourceUserID of new Set(Array.isArray(payload.confirmedLinkedAccountIDs) ? payload.confirmedLinkedAccountIDs : [])) {
    if (typeof sourceUserID !== "string" || !sourceUserID.trim() || sourceUserID === account.appUserID) continue;
    confirmedRecoveries.push(confirmedAccountLinkRecovery(
      { sourceUserID, targetUserID: account.appUserID }, sourceUserID, account.appUserID
    ));
  }
  for (const recovery of new Map(confirmedRecoveries.map((entry) => [entry.sourceUserID, entry])).values()) {
    sessionAccountLinkRecoveries.set(`${account.appUserID}:${recovery.sourceUserID}`, recovery);
    try {
      recordConfirmedAccountLinkRecovery(localStorage, recovery, recovery.sourceUserID, account.appUserID);
    } catch (error) {
      // The server has already merged these identities. Keep its confirmation
      // available for immediate export even if this browser cannot write it.
      recovery.storageWarning = error.message || "The recovery index could not be saved. Export retained work before closing this page.";
    }
  }
  const nextAccount = {
    userID: account.appUserID,
    sessionToken: account.backendSessionToken,
    authProvider: account.authProvider || "web",
    displayName: account.displayName || fallbackDisplayName,
    email: account.email || null,
    publicUsername: account.publicUsername || null,
    entitlement: payload.entitlement || null
  };
  replaceActiveAccount(nextAccount);
  // Source namespaces and journals stay intact. Only synchronized server work
  // is loaded into the destination; retained local work is export-only.
  saveWorkspaceState();
  const identity = captureAccountRequest();
  void refreshNotebookPendingStatus(identity).catch(() => {});
  void reconcileOfflineFeatureAccess(hasCapability("offline-access")).catch(() => {});
  loadSyncedContent({ force: true })
    .then(() => { requireCurrentAccountRequest(identity); return flushSyncOutbox({ refresh: true }); })
    .then(() => { requireCurrentAccountRequest(identity); return flushCodeQuestionOutbox(); })
    .then(() => isCurrentAccountRequest(identity) && renderWorkspace())
    .catch(() => isCurrentAccountRequest(identity) && renderWorkspace());
  return state.account;
}

function linkedAccountRecoverySources(targetUserID = activeAccount()?.userID || "") {
  if (!targetUserID || targetUserID !== activeAccount()?.userID) return [];
  let saved = [];
  try { saved = accountLinkRecoverySources(localStorage, targetUserID); } catch { /* Session receipts still permit export. */ }
  const entries = [...saved, ...sessionAccountLinkRecoveries.values()]
    .filter((entry) => entry.targetUserID === targetUserID && entry.access === "export-only");
  return [...new Map(entries.map((entry) => [entry.sourceUserID, entry])).values()];
}

async function linkedAccountRecoveryBundle(sourceUserID, identity = captureAccountRequest()) {
  return accountLocalRecoveryBundle(sourceUserID, identity);
}

async function accountLocalRecoveryBundle(sourceUserID, identity = captureAccountRequest()) {
  requireCurrentAccountRequest(identity);
  if (!identity.userID || !sourceUserID) throw new Error("Sign in to the account that owns this retained work.");
  const receipt = linkedAccountRecoverySources(identity.userID).find((entry) => entry.sourceUserID === sourceUserID);
  if (sourceUserID !== identity.userID && !receipt) throw new Error("This account has no confirmed link to that retained source.");
  const offline = await offlineAccountRecoverySnapshot(sourceUserID);
  requireCurrentAccountRequest(identity);
  const images = await Promise.all(offline.images.map(async ({ blob, ...record }) => ({
    ...record, ...(blob ? { dataURL: await blobDataURL(blob) } : {})
  })));
  requireCurrentAccountRequest(identity);
  return {
    format: "permitext-account-local-recovery", version: 1, access: "export-only",
    sourceUserID, confirmedDestinationUserID: identity.userID, exportedAt: new Date().toISOString(),
    instructions: "Review this retained source work before copying any content into the destination. This file does not import or replay changes.",
    workspaces: { local: privateWorkspaceRecoverySnapshot(localStorage, sourceUserID),
      session: privateWorkspaceRecoverySnapshot(sessionStorage, sourceUserID) },
    codeQuestions: readCodeQuestionAccountState(localStorage, sourceUserID),
    offline: { ...offline, images }
  };
}

function recoverVerifiedLegacyWorkspace(identity, latestSummary) {
  if (!identity?.userID || !isCurrentAccountRequest(identity) || workspaceRestoreError || workspaceMigrationError) return;
  try {
    if (privateWorkspaceMigrationStatus(localStorage).status !== "quarantined") return;
    if (!legacyWorkspaceRecoveryReview(localStorage, identity.userID).ownershipVerified) return;
    if (legacyWorkspaceRestoreReceipt(localStorage, identity.userID)) return;
    requirePrivateWorkspaceWritable();
    saveWorkspaceState();
    const clearRecords = [...currentBulkClearRecords(), ...(latestSummary.codeVersionClears || [])];
    const plan = planLegacyWorkspaceRestore(localStorage, identity.userID, {
      summary: latestSummary,
      recordKey: (field, item) => field === "localSavedItems" ? savedEvidenceKey(item) :
        field === "localProjects" ? projectRecordID(item) : String(item.id || ""),
      allowLegacyNotes: !(clearRecords.length || Object.keys(state.sectionNotes || {}).length ||
        state.localAnnotations?.length || latestSummary.annotations?.length),
      acceptRecord: (field, item) => recordSurvivesBulkClear(item, clearRecords,
        field === "localProjects" ? ["folders"] : field === "localAnnotations" ? ["notes", "tags", "highlights"] : ["bookmarks", "folders"])
    });
    requireCurrentAccountRequest(identity);
    const restored = commitLegacyWorkspaceRestore(localStorage, plan);
    if (!plan.alreadyRestored) {
      Object.assign(state, plan.shared);
      workspaceRegistry = plan.registry;
      const hasOpenWork = workspaceLayoutHasVisiblePanes({ ...state,
        utilities: { ...state.utilities, settings: false },
        utilityInstances: (state.utilityInstances || []).filter(item => item.key !== "settings")
      });
      // Preserve an existing workspace; show recovered work automatically only
      // when the account has no open work to displace.
      if (!hasOpenWork) {
        const layout = loadWorkspaceSnapshot(restored.workspaceIDs[0]);
        if (layout) {
          activeWorkspaceID = restored.workspaceIDs[0];
          applyStoredWorkspaceLayout(layout);
          persistWorkspaceRegistry();
        }
      }
      renderWorkspaceTabs();
    }
  } catch {
    // A recovery failure must not make a successful server sync look offline.
    // Originals remain available and the next successful sync retries.
    if (isCurrentAccountRequest(identity)) {
      presentWorkspaceIssue("Some older work could not be recovered automatically. Your current account is available. Review older workspace data in Account → Data & Storage; avoid clearing site data.");
    }
  }
}

function appendLegacyWorkspaceRecoveryControls(container, identity = captureAccountRequest()) {
  if (privateWorkspaceMigrationStatus(localStorage).status !== "quarantined") return;
  const region = document.createElement("div");
  region.className = "settings-data-subsection legacy-workspace-recovery";
  const reviewButton = document.createElement("button");
  reviewButton.type = "button";
  reviewButton.className = "settings-secondary-button legacy-workspace-review";
  reviewButton.textContent = "Review older workspace data";
  reviewButton.setAttribute("aria-expanded", "false");
  const details = document.createElement("div");
  details.id = "legacy-workspace-recovery-details";
  details.hidden = true;
  reviewButton.setAttribute("aria-controls", details.id);
  reviewButton.addEventListener("click", () => {
    if (!isCurrentAccountRequest(identity)) return;
    details.hidden = !details.hidden;
    reviewButton.setAttribute("aria-expanded", String(!details.hidden));
    if (details.hidden) return;
    clear(details);
    const summary = document.createElement("p");
    summary.className = "settings-card-copy";
    const status = document.createElement("p");
    status.setAttribute("role", "status");
    try {
      const review = legacyWorkspaceRecoveryReview(localStorage, identity.userID);
      summary.textContent = !review.retainedEntries
        ? "The older records are no longer present in this browser. Recovery availability is unverified; support can review the diagnostic report."
        : `${review.retainedEntries} older browser storage records remain preserved. ` +
          (review.unreadableEntries ? `${review.unreadableEntries} could not be read; recovery may be partial. ` : "") +
          (review.ownershipVerified
            ? "Their recorded owner matches this account. Compatible work is recovered automatically after syncing. Current content takes priority. Conflicting records, older queued edits and unsupported content stay preserved for review; external images and server-only data are not included."
            : "Ownership could not be verified for this account. Sign in to the original account and review again, or contact support. Contents remain isolated. Avoid clearing site data.");
      details.append(summary);
      if (!review.signedIn && review.retainedEntries) {
        const signIn = document.createElement("button");
        signIn.type = "button";
        signIn.className = "settings-secondary-button";
        signIn.textContent = "Sign in to recover";
        signIn.addEventListener("click", async () => {
          if (!isCurrentAccountRequest(identity)) return;
          signIn.disabled = true;
          try {
            await signInCurrentBrowser();
            await setupAccountProfile();
            organizationWorkspace = null;
            organizationLoadPromise = null;
            await renderWorkspace();
            await focusUtility("settings", ".legacy-workspace-review");
            const reviewControl = document.querySelector(".legacy-workspace-review");
            if (reviewControl?.getAttribute("aria-expanded") === "false") reviewControl.click();
            startForegroundSyncLoop({ immediate: true });
          } catch (error) { status.textContent = error.message; }
          finally { signIn.disabled = false; }
        });
        details.append(signIn);
      }
      if (review.recovery === "export-available") {
        const restored = legacyWorkspaceRestoreReceipt(localStorage, identity.userID);
        if (restored) {
          status.textContent = `Automatically recovered ${restored.workspaceIDs.length} workspace(s) and ${restored.restoredRecords} saved record(s) in this browser. Current work was preserved. Any conflicting or unsupported records remain in the recovery copy.`;
          const open = document.createElement("button");
          open.type = "button";
          open.className = "settings-secondary-button";
          open.textContent = "Open recovered workspace";
          open.addEventListener("click", async () => {
            if (!isCurrentAccountRequest(identity)) return;
            try {
              if (!(await switchWorkspace(restored.workspaceIDs[0]))) status.textContent = "The recovered workspace is no longer available in the workspace menu. The original recovery copy is still preserved.";
            } catch (error) { status.textContent = error.message; }
          });
          details.append(open);
        } else {
          status.textContent = "Recovery runs automatically after your account finishes syncing. If you are offline, it will retry when you reconnect.";
        }
        const download = document.createElement("button");
        download.type = "button";
        download.className = "settings-secondary-button";
        download.textContent = "Download recovery copy";
        download.addEventListener("click", () => {
          try {
            requireCurrentAccountRequest(identity);
            const bundle = legacyWorkspaceRecoveryBundle(localStorage, identity.userID);
            downloadCodeMemoBlob(new Blob([JSON.stringify(bundle, null, 2)], { type: "application/json" }), "permitext-older-workspace-recovery.json");
            status.textContent = "Recovery copy downloaded. The original records and your current workspace are unchanged.";
          } catch (error) { status.textContent = error.message; }
        });
        details.append(download);
      }
      const diagnostic = document.createElement("button");
      diagnostic.type = "button";
      diagnostic.className = "settings-secondary-button";
      diagnostic.textContent = "Download diagnostic report";
      diagnostic.addEventListener("click", () => {
        try {
          requireCurrentAccountRequest(identity);
          const report = legacyWorkspaceRecoveryReview(localStorage, identity.userID);
          downloadCodeMemoBlob(new Blob([JSON.stringify(report, null, 2)], { type: "application/json" }), "permitext-workspace-recovery-diagnostic.json");
          status.textContent = "Diagnostic report downloaded. It contains no saved content or account identifiers. You can attach it when contacting support.";
        } catch (error) { status.textContent = error.message; }
      });
      const support = document.createElement("a");
      support.className = "settings-link-button";
      support.href = "/support";
      support.target = "_blank";
      support.rel = "noopener noreferrer";
      support.textContent = "Contact support about recovery";
      details.append(diagnostic, support, status);
    } catch {
      summary.textContent = "Browser storage could not be read. Recovery is unverified. Avoid clearing site data and contact support.";
      details.append(summary);
    }
  });
  region.append(reviewButton, details);
  container?.insertBefore(region, container.querySelector(":scope > .settings-delete-content"));
}

function appendLinkedAccountRecoveryControls(container, identity = captureAccountRequest()) {
  const sources = linkedAccountRecoverySources(identity.userID);
  if (!sources.length) return;
  const region = document.createElement("div");
  const heading = document.createElement("p");
  heading.className = "section-label";
  heading.textContent = "Retained work from connected accounts";
  const copy = document.createElement("p");
  copy.className = "settings-help-copy";
  copy.textContent = "Source-account drafts, images and workspace changes remain on this device. Export them for review; they are not automatically copied or synchronized into this account. Unattributed legacy work remains isolated.";
  region.append(heading, copy);
  sources.forEach((source, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "settings-secondary-button";
    button.textContent = sources.length === 1 ? "Export retained source work" : `Export retained source ${index + 1}`;
    const status = document.createElement("p");
    status.setAttribute("role", "status");
    if (source.storageWarning) status.textContent = "The recovery index could not be saved. Export this source work before closing this page.";
    button.addEventListener("click", async () => {
      if (!isCurrentAccountRequest(identity)) return;
      button.disabled = true;
      try {
        const bundle = await linkedAccountRecoveryBundle(source.sourceUserID, identity);
        requireCurrentAccountRequest(identity);
        downloadCodeMemoBlob(new Blob([JSON.stringify(bundle, null, 2)], { type: "application/json" }), "permitext-linked-account-recovery.json");
        status.textContent = "Recovery file downloaded. Source work remains on this device.";
      } catch (error) {
        if (isCurrentAccountRequest(identity)) status.textContent = `Export could not finish: ${error.message}`;
      } finally {
        if (isCurrentAccountRequest(identity)) button.disabled = false;
      }
    });
    region.append(button, status);
  });
  container?.append(region);
}

async function signInWithAppleWeb(config) {
  const requestIdentity = captureAccountRequest();
  const existingAccount = activeAccount();
  const linkFrom = existingAccount && state.account?.authProvider === "web"
    ? { accountUserID: existingAccount.userID, sessionToken: existingAccount.sessionToken }
    : undefined;
  const startSignIn = async () => {
    if (linkFrom) await requireAccountLinkWorkSaved(existingAccount, requestIdentity);
    requireCurrentAccountRequest(requestIdentity);
    return postJSON("/account/apple/start", {
      linkFrom,
      successURL: `${window.location.pathname}${window.location.search}`
    }, { token: existingAccount?.sessionToken });
  };
  const payload = linkFrom ? await withAccountLinkWriteFence(requestIdentity, startSignIn) : await startSignIn();
  requireCurrentAccountRequest(requestIdentity);
  if (!payload.authorizationURL) {
    throw new Error("Apple sign-in did not return an authorization URL.");
  }
  window.location.href = payload.authorizationURL;
  return new Promise(() => {});
}

async function signInWithBrowserFallback() {
  const payload = await postJSON("/account/sign-in", {
    credential: {
      provider: "web",
      providerUserID: browserCredentialID(),
      displayName: "Web browser",
      signedInAt: new Date().toISOString()
    }
  });
  return storeSignedInAccount(payload, "Web browser");
}

async function signInCurrentBrowser(mode = "signIn") {
  const requestIdentity = captureAccountRequest();
  const clerkConfig = await clerkWebSignInConfig().catch(() => null);
  requireCurrentAccountRequest(requestIdentity);
  if (clerkConfig?.available) {
    return signInWithClerkWeb(clerkConfig, mode);
  }
  const config = await appleWebSignInConfig();
  requireCurrentAccountRequest(requestIdentity);
  if (config.available) {
    return signInWithAppleWeb(config);
  }
  if (config.browserFallbackAllowed) {
    return signInWithBrowserFallback();
  }
  throw new Error("Apple web sign-in is not configured yet.");
}

function mutationKindAndRecord(mutation) {
  const [kind, record] = Object.entries(mutation || {})[0] || [];
  return { kind, record };
}

function mutationUpdatedAt(mutation) {
  const record = Object.values(mutation || {})[0] || {};
  const timestamp = Date.parse(record.updatedAt || 0);
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function retireProjectWorkboardSyncState() {
  const withoutWorkboards = (entries = []) => entries.filter((entry) =>
    mutationKindAndRecord(entry?.mutation).kind !== "workboard"
  );
  const nextOutbox = withoutWorkboards(state.syncOutbox);
  const nextConflicts = withoutWorkboards(state.syncConflicts);
  const changed = nextOutbox.length !== (state.syncOutbox || []).length ||
    nextConflicts.length !== (state.syncConflicts || []).length;
  if (!changed) return false;
  state.syncOutbox = nextOutbox;
  state.syncConflicts = nextConflicts;
  saveWorkspaceState();
  return true;
}

function syncedMutationSupersedesConflict(entry) {
  const recordID = entry?.recordID || syncMutationRecordID(entry?.mutation);
  if (!recordID) return false;
  const serverMutation = (syncedContent?.mutations || [])
    .filter((mutation) => syncMutationRecordID(mutation) === recordID)
    .sort((left, right) => mutationUpdatedAt(right) - mutationUpdatedAt(left))[0];
  if (!serverMutation) return false;
  const local = mutationKindAndRecord(entry.mutation);
  const server = mutationKindAndRecord(serverMutation);
  return mutationUpdatedAt(serverMutation) >= mutationUpdatedAt(entry.mutation) &&
    local.kind === server.kind &&
    syncConflictRecordsMatch(local.record, server.record);
}

async function convergeServerNewerSyncConflicts(account) {
  const requestIdentity = captureAccountRequest();
  const convergent = (state.syncConflicts || []).filter((entry) =>
    entry.accountUserID === account.userID && syncedMutationSupersedesConflict(entry)
  );
  if (!convergent.length || syncedContent?.status !== "connected") return false;

  const resolvedIDs = new Set();
  for (const entry of convergent) {
    requireCurrentAccountRequest(requestIdentity);
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    try {
      if (kind === "workboard") {
        const projectID = String(record?.projectID || "");
        await replaceLocalWorkboard(projectID, syncedWorkboardForProject(projectID));
      } else {
        discardLocalMutationOverlay(entry.mutation);
      }
      resolvedIDs.add(entry.id);
    } catch {
      // Keep the conflict visible if applying the authoritative server copy fails.
    }
  }
  requireCurrentAccountRequest(requestIdentity);
  if (!resolvedIDs.size) return false;
  state.syncConflicts = (state.syncConflicts || []).filter((entry) => !resolvedIDs.has(entry.id));
  saveWorkspaceState();
  return true;
}

function currentBulkClearRecords() {
  return [
    ...(syncedContent?.summary?.codeVersionClears || []),
    ...(state.localBulkClears || []),
    ...(state.syncConflicts || [])
      .map((entry) => mutationKindAndRecord(entry.mutation))
      .filter(({ kind }) => kind === "codeVersionClear")
      .map(({ record }) => record),
    ...(state.syncOutbox || [])
      .map((entry) => mutationKindAndRecord(entry.mutation))
      .filter(({ kind }) => kind === "codeVersionClear")
      .map(({ record }) => record)
  ].filter((record) => Boolean(bulkClearKey(record)));
}

function absorbBulkClearConflicts() {
  let changed = false;
  const latestLocalClears = new Map((state.localBulkClears || [])
    .map((record) => [bulkClearKey(record), record])
    .filter(([key]) => Boolean(key)));
  state.syncConflicts = (state.syncConflicts || []).filter((entry) => {
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    if (kind !== "codeVersionClear") {
      return true;
    }
    if (
      entry.rejectionCode === "SYNC_MUTATION_REJECTED" ||
      String(entry.lastError || "").includes("server could not accept this change")
    ) {
      // Keep generic server rejections so the upgraded client can retry the
      // clear after the server-side acceptance defect is repaired.
      return true;
    }
    const key = bulkClearKey(record);
    const existing = key ? latestLocalClears.get(key) : null;
    if (key && (!existing || Date.parse(record.updatedAt || 0) >= Date.parse(existing.updatedAt || 0))) {
      latestLocalClears.set(key, record);
    }
    changed = true;
    return false;
  });
  if (changed) state.localBulkClears = Array.from(latestLocalClears.values());
  return changed;
}

function retryRejectedDeletionConflictsOnce(account) {
  if (rejectedDeletionRecoveryAttempted) return false;
  rejectedDeletionRecoveryAttempted = true;
  const recoverable = (state.syncConflicts || []).filter((entry) => {
    if (entry.accountUserID !== account.userID) return false;
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    const isDeletion = Boolean(record?.deletedAt) && ["savedItem", "projectSection"].includes(kind);
    const isBulkClear = kind === "codeVersionClear";
    const genericRejection = entry.rejectionCode === "SYNC_MUTATION_REJECTED" ||
      String(entry.lastError || "").includes("server could not accept this change");
    return genericRejection && (isDeletion || isBulkClear);
  });
  if (!recoverable.length) return false;

  const operationGroupID = crypto.randomUUID();
  const baseTimestamp = Date.now();
  recoverable.forEach((entry, index) => {
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    const updatedAt = new Date(baseTimestamp + index).toISOString();
    enqueueSyncMutation({
      [kind]: {
        ...record,
        userID: account.userID,
        updatedAt,
        ...(record.deletedAt ? { deletedAt: updatedAt } : {})
      }
    }, account, { operationGroupID });
  });
  return true;
}

function summarizeMutations(mutations = []) {
  const sorted = [...mutations].sort((left, right) => mutationUpdatedAt(right) - mutationUpdatedAt(left));
  const latestByID = new Map();
  sorted.forEach((mutation) => {
    const id = syncMutationRecordID(mutation);
    if (id && !latestByID.has(id)) latestByID.set(id, mutation);
  });
  const projects = [];
  const savedItems = [];
  const annotations = [];
  const projectSections = [];
  const workboards = [];
  const codeVersionClears = new Map();
  let latestContinuity = null;

  latestByID.forEach((mutation) => {
    const { kind, record } = mutationKindAndRecord(mutation);
    if (kind !== "codeVersionClear" || !record) return;
    const key = bulkClearKey(record);
    const existing = key ? codeVersionClears.get(key) : null;
    if (key && (!existing || Date.parse(record.updatedAt || 0) >= Date.parse(existing.updatedAt || 0))) {
      codeVersionClears.set(key, record);
    }
  });

  latestByID.forEach((mutation) => {
    const { kind, record } = mutationKindAndRecord(mutation);
    if (!record || record.deletedAt) return;
    if (kind === "project" && recordSurvivesBulkClear(record, codeVersionClears, ["folders"])) projects.push(record);
    if (kind === "savedItem" && recordSurvivesBulkClear(record, codeVersionClears, ["bookmarks"])) savedItems.push(record);
    if (kind === "annotation") {
      const visibleAnnotation = annotationAfterBulkClears(record, codeVersionClears);
      if (visibleAnnotation) annotations.push(visibleAnnotation);
    }
    if (kind === "projectSection" && recordSurvivesBulkClear(record, codeVersionClears, ["bookmarks", "folders"])) projectSections.push(record);
    if (kind === "workboard") workboards.push(record);
    if (
      kind === "continuity" &&
      (!latestContinuity || mutationUpdatedAt(mutation) > Date.parse(latestContinuity.updatedAt || 0))
    ) {
      latestContinuity = record;
    }
  });

  return {
    projects,
    savedItems,
    annotations,
    projectSections,
    workboards,
    latestContinuity,
    codeVersionClears: Array.from(codeVersionClears.values())
  };
}

function currentContentSummary() {
  const summary = syncedContent?.userID === activeAccount()?.userID
    ? syncedContent?.summary || summarizeMutations([]) : summarizeMutations([]);
  const clearRecords = currentBulkClearRecords();
  // Always apply every durable clear to the cached remote summary. Incremental
  // pulls can refresh one clear scope without rebuilding the other scopes, so
  // trusting the cached summary here could resurrect records cleared moments
  // earlier by this browser or another device.
  const summarySavedItems = (summary.savedItems || [])
    .filter((item) => recordSurvivesBulkClear(item, clearRecords, ["bookmarks"]));
  const summaryAnnotations = (summary.annotations || [])
    .map((item) => annotationAfterBulkClears(item, clearRecords))
    .filter(Boolean);
  const localProjectSavedItems = (state.localProjectSections || [])
    .filter((item) => item && item.sectionID && !item.deletedAt &&
      recordSurvivesBulkClear(item, clearRecords, ["bookmarks", "folders"]))
    .map((item) => ({
      id: `web-saved-${safeAnnotationIDPart(syncCodeVersion(item.codeVersion))}-${item.sectionID}${normalizeAnnotationBlockID(item.blockID) ? `-${safeAnnotationIDPart(normalizeAnnotationBlockID(item.blockID))}` : ""}`,
      userID: item.userID || "local-web",
      codeVersion: syncCodeVersion(item.codeVersion),
      codePrefix: item.codePrefix || "BC",
      chapterID: item.chapterID || "",
      chapterNumber: item.chapterNumber || "",
      sectionID: Number(item.sectionID),
      blockID: normalizeAnnotationBlockID(item.blockID),
      sectionNumber: item.sectionNumber || "",
      title: item.title || "Section",
      updatedAt: item.updatedAt || new Date().toISOString()
    }));
  const localSavedItems = [...(state.localSavedItems || []), ...localProjectSavedItems]
    .filter((item) => recordSurvivesBulkClear(item, clearRecords, ["bookmarks"]));
  const savedItemsBySection = new Map(
    summarySavedItems.map((item) => [savedEvidenceKey(item), item])
  );
  localSavedItems.forEach((item) => {
    if (item?.sectionID) mergeNewestRecord(savedItemsBySection, savedEvidenceKey(item), item);
  });
  const annotationsByID = new Map(
    summaryAnnotations.map((item) => [String(item.id || ""), item])
  );
  (state.localAnnotations || []).forEach((item) => {
    const visibleAnnotation = annotationAfterBulkClears(item, clearRecords);
    if (visibleAnnotation?.id) {
      mergeNewestRecord(annotationsByID, String(visibleAnnotation.id), visibleAnnotation);
    }
  });
  const projectSectionIdentity = (item) => [
    syncCodeVersion(item.codeVersion),
    item.folderClientID || item.projectID || item.localFolderID || "project",
    item.sectionID || item.savedSectionID || item.itemID || item.id || "section",
    normalizeAnnotationBlockID(item.blockID)
  ].map(String).join(":");
  const projectSectionsByID = new Map(
    (summary.projectSections || [])
      .filter((item) => recordSurvivesBulkClear(item, clearRecords, ["bookmarks", "folders"]))
      .map((item) => [projectSectionIdentity(item), item])
  );
  (state.localProjectSections || []).forEach((item) => {
    if (item && recordSurvivesBulkClear(item, clearRecords, ["bookmarks", "folders"])) {
      mergeNewestRecord(projectSectionsByID, projectSectionIdentity(item), item);
    }
  });
  return {
    ...summary,
    savedItems: Array.from(savedItemsBySection.values()).filter((item) => !item.deletedAt),
    annotations: Array.from(annotationsByID.values()).filter((item) => !item.deletedAt),
    projectSections: Array.from(projectSectionsByID.values()).filter((item) => !item.deletedAt)
  };
}

async function loadSyncedContent(options = {}) {
  const account = activeAccount();
  const identity = captureAccountRequest();
  if (!account) {
    syncedContent = { status: "disconnected", mutations: [], summary: summarizeMutations([]) };
    return syncedContent;
  }
  if (syncLoadPromise && isCurrentAccountRequest(syncLoadPromise.accountIdentity) && !options.force) {
    return syncLoadPromise;
  }
  const baseline = ["connected", "offline"].includes(syncedContent?.status) && syncedContent?.userID === account.userID
    ? syncedContent
    : null;
  const requestedEventID = Number.isSafeInteger(baseline?.latestEventID) ? baseline.latestEventID : null;
  const request = postJSON("/sync/pull", {
    auth: { accountUserID: account.userID },
    sinceEventID: requestedEventID,
    contentMapVersion: Number(baseline?.contentMapVersion || 2),
    syncSchemaVersion: permitextSyncSchemaVersion,
    clientCapabilities: permitextClientCapabilities
  }, { token: account.sessionToken })
    .then(async (payload) => {
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      let entitlement = payload.entitlement || null;
      const repaired = await repairAppleBrowserAccountLink(account, entitlement);
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      if (repaired?.entitlement) {
        entitlement = repaired.entitlement;
      }
      const contentMapVersion = Number(payload.contentMapVersion || 0);
      const canMergeIncrementally = baseline && requestedEventID !== null &&
        contentMapVersion === Number(baseline.contentMapVersion || 0);
      const mutations = canMergeIncrementally
        ? mergeSyncedMutations(baseline.mutations || [], payload.mutations || [])
        : payload.mutations || [];
      syncedContent = {
        status: "connected",
        userID: account.userID,
        pulledAt: payload.pulledAt,
        latestEventID: payload.latestEventID ?? payload.syncRevision ?? requestedEventID,
        contentMapVersion,
        syncSchemaVersion: Number(payload.syncSchemaVersion || permitextSyncSchemaVersion),
        capabilityContract: payload.capabilityContract || null,
        entitlement,
        entitlementFingerprint: payload.entitlementFingerprint || "",
        mutations,
        summary: summarizeMutations(mutations)
      };
      await convergeServerNewerSyncConflicts(account);
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      reconcileSharedWorkspaceCatalog();
      await applyRemoteContinuityIfNewer();
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      recoverVerifiedLegacyWorkspace(identity, syncedContent.summary);
      await saveOfflineSyncSnapshot(account.userID, syncedContent).catch(() => {});
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      foregroundSyncLastFullPullAt = Date.now();
      broadcastForegroundSyncSignal("sync-complete", {
        latestEventID: syncedContent.latestEventID,
        pulledAt: syncedContent.pulledAt,
        contentMapVersion: syncedContent.contentMapVersion,
        entitlementFingerprint: syncedContent.entitlementFingerprint
      });
      storeAccountEntitlement(entitlement);
      syncedContent.workspacePresentationAccess = "verified";
      return syncedContent;
    })
    .catch(async (error) => {
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      if (isSessionAuthenticationError(error)) {
        clearExpiredAccountSession();
        return syncedContent;
      }
      const snapshot = baseline || await loadOfflineSyncSnapshot(account.userID).catch(() => null);
      if (!isCurrentAccountRequest(identity) || syncLoadPromise !== request) return syncedContent;
      const snapshotIdentityVerified = snapshot?.userID === account.userID;
      const snapshotProvenanceVerified = baseline
        ? ["verified", "permitted-offline"].includes(baseline.workspacePresentationAccess)
        : Boolean(snapshot);
      const workspacePresentationAccess = snapshotIdentityVerified && snapshotProvenanceVerified &&
        privateCacheFallbackAllowed(error) ? "permitted-offline" : "unavailable";
      const mutations = snapshot?.mutations || [];
      syncedContent = {
        ...(snapshot || {}),
        status: "offline",
        workspacePresentationAccess,
        userID: account.userID,
        error: error.message,
        mutations,
        summary: summarizeMutations(mutations)
      };
      return syncedContent;
    })
    .finally(() => {
      if (syncLoadPromise === request) syncLoadPromise = null;
    });
  request.accountIdentity = identity;
  syncLoadPromise = request;
  return request;
}

function mergeSyncedMutations(existing, incoming) {
  const byRecordID = new Map();
  [...existing, ...incoming].forEach((mutation) => {
    const recordID = syncMutationRecordID(mutation);
    if (recordID) byRecordID.set(recordID, mutation);
  });
  return Array.from(byRecordID.values());
}

async function ensureSyncedContentForRender() {
  if (!activeAccount()) {
    if (syncedContent?.status !== "disconnected") {
      syncedContent = { status: "disconnected", mutations: [], summary: summarizeMutations([]) };
    }
    return syncedContent;
  }
  const identity = captureAccountRequest();
  let pending = syncLoadPromise && isCurrentAccountRequest(syncLoadPromise.accountIdentity)
    ? syncLoadPromise : null;
  if (!pending) {
    if (syncedContent?.userID === activeAccount()?.userID && syncedContent?.status === "connected") return syncedContent;
    if (syncedContent?.userID === activeAccount()?.userID && syncedContent?.status === "offline" && (navigator.onLine === false || !serverReachable)) {
      return syncedContent;
    }
    pending = loadSyncedContent();
  }
  // A forced pull may supersede the one this render began awaiting. Follow the
  // current account's replacement through its complete post-pull chain.
  let result;
  while (pending) {
    result = await pending;
    if (!isCurrentAccountRequest(identity)) return syncedContent;
    const latest = syncLoadPromise;
    if (!latest || latest === pending || !isCurrentAccountRequest(latest.accountIdentity)) break;
    pending = latest;
  }
  return result;
}

function syncedWorkboardForProject(projectID) {
  return (syncedContent?.summary?.workboards || []).find((board) =>
    String(board.projectID || "") === String(projectID || "")
  ) || null;
}

async function loadSyncedWorkboard(projectID) {
  if (!activeAccount()) return null;
  await loadSyncedContent();
  return syncedWorkboardForProject(projectID);
}

async function saveSyncedWorkboard(board, options = {}) {
  const account = activeAccount();
  if (!account) throw new Error("Sign in to synchronize this Workboard.");
  if (!hasCapability("projects")) {
    void presentPlanLimitNotice("Workboards require Pro", "Upgrade to Pro to create or edit Project Workboards.");
    throw new Error("Workboards require Pro.");
  }
  const projectID = String(board?.id || board?.projectID || "").trim();
  if (!projectID) throw new Error("This Workboard is missing its project ID.");
  const updatedAt = board.updatedAt || new Date().toISOString();
  const record = {
    id: `${account.userID}:workboard:${projectID}`,
    userID: account.userID,
    codeVersion: defaultSyncCodeVersion,
    projectID,
    projectName: board.projectName || "Project",
    elements: board.elements || [],
    appState: board.appState || {},
    files: board.files || {},
    assets: board.assets || {},
    baseUpdatedAt: options.baseUpdatedAt || null,
    updatedAt
  };
  await pushMutation({ workboard: record });
  return syncedWorkboardForProject(projectID) || record;
}

async function deleteSyncedWorkboard(projectID) {
  const account = activeAccount();
  if (!account) return;
  const board = syncedWorkboardForProject(projectID);
  if (!board) return;
  const now = new Date().toISOString();
  await pushMutation({
    workboard: {
      id: `${account.userID}:workboard:${projectID}`,
      userID: account.userID,
      codeVersion: defaultSyncCodeVersion,
      projectID,
      projectName: board?.projectName || "Project",
      updatedAt: now,
      deletedAt: now
    }
  });
  const pathnames = Object.values(board?.assets || {}).map((asset) => asset?.pathname).filter(Boolean);
  if (!pathnames.length) return;
  const response = await fetch("/workboards/assets/delete", {
    method: "POST",
    headers: {
      authorization: `Bearer ${account.sessionToken}`,
      "content-type": "application/json"
    },
    body: JSON.stringify({
      auth: { accountUserID: account.userID },
      projectID,
      pathnames
    })
  });
  if (!response.ok && response.status !== 503) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(responseErrorMessage(payload, "Could not remove this Workboard's stored images."));
  }
}

async function replaceLocalWorkboard(projectID, board) {
  const module = await loadWorkboardModule();
  await module.replaceLocalWorkboard(projectID, board);
  const mounted = workboardMounts.get(projectID);
  disposeProjectWorkboardMount(mounted);
  workboardMounts.delete(projectID);
}

async function deleteLocalWorkboard(projectID) {
  // Workboard is retired; cleanup must not load its removed UI bundle or
  // prevent project deletion when legacy browser storage is unavailable.
  const id = String(projectID || "").trim();
  if (id && typeof indexedDB !== "undefined") {
    await new Promise((resolve) => {
      try {
        const request = indexedDB.open("permitext-workboards");
        request.onupgradeneeded = () => request.transaction.abort();
        request.onerror = request.onblocked = () => resolve();
        request.onsuccess = () => {
          const database = request.result;
          try {
            if (!database.objectStoreNames.contains("boards")) {
              database.close();
              resolve();
              return;
            }
            const transaction = database.transaction("boards", "readwrite");
            transaction.oncomplete = transaction.onerror = transaction.onabort = () => {
              database.close();
              resolve();
            };
            transaction.objectStore("boards").delete(id);
          } catch {
            database.close();
            resolve();
          }
        };
      } catch {
        resolve();
      }
    });
  }
  const mounted = workboardMounts.get(projectID);
  disposeProjectWorkboardMount(mounted);
  workboardMounts.delete(projectID);
}

function accountScopedWorkboardProjectIDs(account, sources = {}) {
  const accountUserID = String(account?.userID || "").trim();
  if (!accountUserID) return [];
  const summary = sources.summary ?? currentContentSummary();
  const localProjects = sources.localProjects ?? state.localProjects ?? [];
  const queueEntries = [
    ...(sources.syncOutbox ?? state.syncOutbox ?? []),
    ...(sources.syncConflicts ?? state.syncConflicts ?? [])
  ];
  const projectIDs = new Set();
  const addProjectID = (value) => {
    const projectID = String(value || "").trim();
    if (projectID && projectID.length <= 200) projectIDs.add(projectID);
  };
  const addProjectRecord = (project) => {
    addProjectID(project?.clientID || project?.id || project?.localFolderID);
  };
  (summary?.projects || []).forEach(addProjectRecord);
  (summary?.workboards || []).forEach((workboard) => addProjectID(workboard?.projectID));
  localProjects
    .filter((project) => String(project?.userID || "").trim() === accountUserID)
    .forEach(addProjectRecord);
  queueEntries
    .filter((entry) => String(entry?.accountUserID || "").trim() === accountUserID)
    .forEach((entry) => {
      const [kind, record] = Object.entries(entry?.mutation || {})[0] || [];
      if (!record || !["project", "workboard"].includes(kind)) return;
      const recordUserID = String(record.userID || "").trim();
      if (recordUserID && recordUserID !== accountUserID) return;
      if (kind === "project") {
        addProjectRecord(record);
        return;
      }
      const directProjectID = String(record.projectID || "").trim();
      if (directProjectID) {
        addProjectID(directProjectID);
        return;
      }
      const marker = ":workboard:";
      const recordID = String(record.id || "");
      const markerIndex = recordID.lastIndexOf(marker);
      if (markerIndex !== -1) addProjectID(recordID.slice(markerIndex + marker.length));
    });
  return Array.from(projectIDs);
}

function responseErrorMessage(payload, fallback) {
  return payload?.error?.message || payload?.message || payload?.error || fallback;
}

function canvasBlob(canvas, type, quality) {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("Could not optimize this Workboard image."));
    }, type, quality);
  });
}

async function optimizedWorkboardImageBlob(blob) {
  if (blob.type === "image/gif" || typeof createImageBitmap !== "function") return blob;
  const image = await createImageBitmap(blob);
  try {
    const maxDimension = 2048;
    const scale = Math.min(1, maxDimension / Math.max(image.width, image.height));
    if (scale === 1 && blob.size <= 1.5 * 1024 * 1024) return blob;
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.round(image.width * scale));
    canvas.height = Math.max(1, Math.round(image.height * scale));
    const context = canvas.getContext("2d", { alpha: true });
    if (!context) return blob;
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    return canvasBlob(canvas, "image/webp", 0.84);
  } finally {
    image.close();
  }
}

async function uploadWorkboardAsset(projectID, fileID, file) {
  const account = activeAccount();
  if (!account) throw new Error("Sign in to synchronize Workboard images.");
  if (typeof file?.dataURL !== "string" || !file.dataURL.startsWith("data:")) {
    throw new Error("This Workboard image has no uploadable data.");
  }
  const sourceBlob = await fetch(file.dataURL).then((response) => response.blob());
  const blob = await optimizedWorkboardImageBlob(sourceBlob);
  const url = new URL("/workboards/assets/upload", window.location.origin);
  url.searchParams.set("projectID", projectID);
  url.searchParams.set("fileID", fileID);
  const response = await fetch(url, {
    method: "POST",
    headers: {
      authorization: `Bearer ${account.sessionToken}`,
      "content-type": blob.type || file.mimeType || "application/octet-stream",
      "x-permitext-user-id": account.userID
    },
    body: blob
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(responseErrorMessage(payload, "Could not upload this Workboard image."));
  return payload.asset;
}

const notebookImageTypes = new Set(["image/png", "image/jpeg", "image/webp", "image/gif"]);
const maximumNotebookImageBytes = 8 * 1024 * 1024;

async function notebookImageDimensions(blob) {
  try {
    const image = await createImageBitmap(blob);
    try {
      return { width: image.width, height: image.height };
    } finally {
      image.close();
    }
  } catch {
    return { width: null, height: null };
  }
}

async function uploadPendingNotebookImage(record) {
  requirePrivateWorkspaceWritable();
  const account = activeAccount();
  const requestIdentity = captureAccountRequest();
  if (!account || account.userID !== record.accountUserID) return null;
  const dimensions = await notebookImageDimensions(record.blob);
  requireCurrentAccountRequest(requestIdentity);
  const url = new URL("/notebook/assets/upload", window.location.origin);
  url.searchParams.set("projectID", record.projectID);
  url.searchParams.set("assetID", record.assetID);
  let response;
  try {
    response = await fetch(url, {
      method: "POST",
      headers: {
        authorization: `Bearer ${account.sessionToken}`,
        "content-type": record.contentType,
        "x-permitext-user-id": account.userID,
        ...(dimensions.width ? { "x-permitext-image-width": String(dimensions.width) } : {}),
        ...(dimensions.height ? { "x-permitext-image-height": String(dimensions.height) } : {})
      },
      body: record.blob
    });
  } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    throw new Error(navigator.onLine === false
      ? "Upload is waiting for network connectivity."
      : `Notebook image upload failed: ${error.message}`);
  }
  requireCurrentAccountRequest(requestIdentity);
  const payload = await response.json().catch(() => ({}));
  requireCurrentAccountRequest(requestIdentity);
  if (!response.ok) throw new Error(responseErrorMessage(payload, "Could not upload this Notebook image."));
  await markNotebookImageUploaded(record.localURL, payload.asset);
  requireCurrentAccountRequest(requestIdentity);
  window.dispatchEvent(new CustomEvent("permitext:notebook-image-uploaded", {
    detail: { accountUserID: account.userID, generation: requestIdentity.generation, projectID: record.projectID, localURL: record.localURL, permanentURL: payload.asset.url }
  }));
  return payload.asset;
}

async function flushPendingNotebookImages() {
  const account = activeAccount();
  const requestIdentity = captureAccountRequest();
  if (!account || navigator.onLine === false) return [];
  const pending = await pendingNotebookImages(account.userID).catch(() => []);
  requireCurrentAccountRequest(requestIdentity);
  const uploaded = [];
  let firstError = null;
  for (const record of pending) {
    requireCurrentAccountRequest(requestIdentity);
    try {
      const asset = await uploadPendingNotebookImage(record);
      if (asset) uploaded.push(asset);
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      await markNotebookImageUploadError(record.localURL, error.message).catch(() => {});
      firstError ||= error;
      if (navigator.onLine === false) break;
    }
  }
  requireCurrentAccountRequest(requestIdentity);
  if (firstError && navigator.onLine !== false) {
    void showWebNotice("Notebook image not synchronized", firstError.message);
  }
  return uploaded;
}

async function refreshNotebookPendingStatus(requestIdentity = captureAccountRequest()) {
  if (!requestIdentity.userID) return;
  const drafts = await pendingNotebookDrafts(requestIdentity.userID);
  if (!isCurrentAccountRequest(requestIdentity)) return;
  notebookPendingDraftCount = drafts.length;
  updateConnectionStatus();
}

async function synchronizeNotebookDraft(draft, requestIdentity = captureAccountRequest(), options = {}) {
  requireCurrentAccountRequest(requestIdentity);
  if (draft.accountUserID !== requestIdentity.userID) throw accountContextChangedError();
  if (draft.recoveryConflict || (draft.scope && draft.scope !== "notebook-card")) return null;
  const pending = draft.pendingSave || draft;
  // Simple Notes leave stored legacy question metadata untouched. An existing
  // uncertain receipt is replayed byte-for-byte before ordinary saves resume.
  if (!Number.isSafeInteger(pending.baseVersion) || pending.baseVersion < 0 || !String(pending.title || "").trim()) return null;
  const document = await reconcileNotebookDocumentAssets(pending.document, pending.projectID, requestIdentity);
  requireCurrentAccountRequest(requestIdentity);
  if (notebookDocumentAssetURLs(document, "permitext-notebook-local:").length) return null;
  const submittedDraft = await beginNotebookDraftSave(requestIdentity.userID, draft.projectID, draft.cardID, draft.revision, { document, omitQuestionUpdates: true });
  requireCurrentAccountRequest(requestIdentity);
  const submittedDocument = submittedDraft.document;
  if (notebookDocumentAssetURLs(submittedDocument, "permitext-notebook-local:").length) return null;
  let payload;
  try { payload = await postResearch("/notebook/cards/save", {
    projectID: draft.projectID,
    cardID: submittedDraft.cardID || undefined,
    clientMutationID: submittedDraft.revision,
    expectedVersion: submittedDraft.baseVersion,
    cardType: submittedDraft.cardType || "finding",
    title: submittedDraft.title,
    document: submittedDocument,
    evidenceLinks: submittedDraft.evidenceLinks || [],
    ...(submittedDraft.openQuestions !== undefined ? {openQuestions: submittedDraft.openQuestions} : {})
  }); } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    let invalidLegacyQuestions = false;
    if (!submittedDraft.omitQuestionUpdates) {
      try { normalizeNotebookQuestions(submittedDraft.openQuestions || []); }
      catch { invalidLegacyQuestions = true; }
    }
    // Only a definitive rejection allows retiring an old invalid receipt.
    // Timeouts, conflicts and other uncertain outcomes keep the original body.
    if (error.status !== 400 || !invalidLegacyQuestions) throw error;
    const retained = await retireRejectedNotebookQuestionSave(requestIdentity.userID, draft.projectID,
      submittedDraft.cardID, submittedDraft.revision);
    return synchronizeNotebookDraft(retained, requestIdentity, options);
  }
  requireCurrentAccountRequest(requestIdentity);
  if (!options.deferAcknowledgement) {
    await acknowledgeNotebookDraft(requestIdentity.userID, draft.projectID, submittedDraft.cardID, submittedDraft.revision, payload.card);
    await saveNotebookCardSnapshot(requestIdentity.userID, draft.projectID, payload.card);
    requireCurrentAccountRequest(requestIdentity);
    await refreshNotebookPendingStatus(requestIdentity);
  }
  return { ...payload, submittedDraft };
}

async function flushPendingNotebookDrafts() {
  const requestIdentity = captureAccountRequest();
  if (!requestIdentity.userID || navigator.onLine === false || !isProAccount()) return;
  if (notebookDraftSyncPromise) return notebookDraftSyncPromise;
  const request = (async () => {
    const drafts = await pendingNotebookDrafts(requestIdentity.userID);
    requireCurrentAccountRequest(requestIdentity);
    for (const draft of drafts) {
      requireCurrentAccountRequest(requestIdentity);
      if (draft.recoveryConflict || (draft.scope && draft.scope !== "notebook-card")) continue;
      const mount = notebookMounts.get(draft.projectID);
      if (mount?.activeCardID?.() === (draft.cardID || "")) {
        await mount.syncDraft?.();
        continue;
      }
      try { await synchronizeNotebookDraft(draft, requestIdentity); }
      catch (error) {
        requireCurrentAccountRequest(requestIdentity);
        // Keep the original version and bytes until the user resolves a conflict or connectivity returns.
        if (error.payload?.code === "NOTEBOOK_VERSION_CONFLICT") continue;
        if (!error.status || error.status >= 500) break;
      }
    }
    await refreshNotebookPendingStatus(requestIdentity);
  })().finally(() => {
    if (notebookDraftSyncPromise === request) notebookDraftSyncPromise = null;
  });
  notebookDraftSyncPromise = request;
  return request;
}

function notebookDocumentAssetURLs(document, prefix) {
  const urls = [];
  const visit = (block) => {
    const url = block?.props?.url || block?.attrs?.src || block?.attrs?.url || "";
    if (block?.type === "image" && String(url).startsWith(prefix)) {
      urls.push(url);
    }
    const children = Array.isArray(block?.children)
      ? block.children
      : Array.isArray(block?.content) ? block.content : [];
    children.forEach(visit);
  };
  const roots = Array.isArray(document?.document)
    ? document.document
    : Array.isArray(document?.document?.content) ? document.document.content : [];
  roots.forEach(visit);
  return Array.from(new Set(urls));
}

function replaceNotebookDocumentAssetURL(document, fromURL, toURL) {
  const replace = (value) => {
    if (Array.isArray(value)) return value.map(replace);
    if (!value || typeof value !== "object") return value;
    const next = Object.fromEntries(
      Object.entries(value).map(([key, nested]) => [key, replace(nested)])
    );
    if (value.type !== "image") return next;
    if (value.props?.url === fromURL) next.props = { ...next.props, url: toURL };
    if (value.attrs?.src === fromURL) next.attrs = { ...next.attrs, src: toURL };
    if (value.attrs?.url === fromURL) next.attrs = { ...next.attrs, url: toURL };
    return next;
  };
  return replace(document);
}

async function pruneUnusedPendingNotebookImages(accountUserID, projectID, cardID, document) {
  const used = new Set(notebookDocumentAssetURLs(document, "permitext-notebook-local:"));
  const localImages = await notebookImagesForProject(accountUserID, projectID, cardID).catch(() => []);
  await Promise.all(localImages.filter((record) => !used.has(record.localURL)).map(async (record) => {
    if (record.uploadState === "uploaded" && record.remoteAsset?.assetID) {
      try {
        await postResearch("/notebook/assets/delete", {
          projectID,
          assetID: record.remoteAsset.assetID
        });
      } catch (error) {
        if (error.payload?.code === "NOTEBOOK_IMAGE_IN_USE") return;
        throw error;
      }
    }
    await deleteLocalNotebookImage(record.localURL);
  })).catch((error) => {
    void showWebNotice("Notebook image cleanup delayed", error.message);
  });
}

async function reconcileNotebookDocumentAssets(document, projectID, requestIdentity = captureAccountRequest()) {
  requireCurrentAccountRequest(requestIdentity);
  let reconciled = document;
  for (const localURL of notebookDocumentAssetURLs(document, "permitext-notebook-local:")) {
    const record = await notebookImageRecord(localURL).catch(() => null);
    requireCurrentAccountRequest(requestIdentity);
    if (record?.accountUserID === requestIdentity.userID && record?.projectID === projectID && record?.permanentURL) {
      reconciled = replaceNotebookDocumentAssetURL(reconciled, localURL, record.permanentURL);
    }
  }
  return reconciled;
}

async function uploadNotebookAsset(projectID, file, cardID = "", requestIdentity = captureAccountRequest()) {
  requirePrivateWorkspaceWritable();
  requireCurrentAccountRequest(requestIdentity);
  const account = activeAccount();
  if (!account) throw new Error("Sign in to upload Notebook images.");
  if (!(file instanceof File) || !notebookImageTypes.has(file.type)) {
    throw new Error("The Notebook accepts PNG, JPEG, WebP, and GIF images.");
  }
  if (file.size > maximumNotebookImageBytes) {
    throw new Error("Notebook images must be 8 MB or smaller.");
  }
  const blob = await optimizedWorkboardImageBlob(file);
  requireCurrentAccountRequest(requestIdentity);
  requirePrivateWorkspaceWritable();
  const record = await stageNotebookImage({
    accountUserID: account.userID,
    projectID,
    cardID,
    assetID: crypto.randomUUID(),
    blob,
    name: file.name
  });
  requireCurrentAccountRequest(requestIdentity);
  if (navigator.onLine !== false) {
    try {
      return (await uploadPendingNotebookImage(record)).url;
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      await markNotebookImageUploadError(record.localURL, error.message).catch(() => {});
      if (!/network|connectivity|failed to fetch/i.test(error.message)) throw error;
    }
  }
  return record.localURL;
}

async function resolveNotebookAsset(projectID, assetURL, requestIdentity = captureAccountRequest()) {
  requireCurrentAccountRequest(requestIdentity);
  const value = String(assetURL || "");
  if (value.startsWith("permitext-notebook-local:")) {
    const local = await notebookImageRecord(value);
    requireCurrentAccountRequest(requestIdentity);
    if (local?.accountUserID !== requestIdentity.userID || local?.projectID !== projectID || !local?.blob) throw new Error("This offline Notebook image is no longer available on this device.");
    return URL.createObjectURL(local.blob);
  }
  if (!value.startsWith("permitext-notebook-asset:")) return value;
  const account = activeAccount();
  if (!account) throw new Error("Sign in to load this Notebook image.");
  const identity = value.slice("permitext-notebook-asset:".length);
  let decodedIdentity = identity;
  try { decodedIdentity = decodeURIComponent(identity); } catch { /* use literal identity */ }
  const legacyPathname = decodedIdentity.startsWith("project-assets/") ? decodedIdentity : "";
  const response = await fetch("/notebook/assets/read", {
    method: "POST",
    headers: {
      authorization: `Bearer ${account.sessionToken}`,
      "content-type": "application/json"
    },
    body: JSON.stringify({
      auth: { accountUserID: account.userID },
      projectID,
      ...(legacyPathname ? { pathname: legacyPathname } : { assetID: identity })
    })
  });
  requireCurrentAccountRequest(requestIdentity);
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(responseErrorMessage(payload, "Could not load this Notebook image."));
  }
  const blob = await response.blob();
  requireCurrentAccountRequest(requestIdentity);
  return URL.createObjectURL(blob);
}

async function saveWorkboardPreview(projectID, blob, metadata = {}) {
  const account = activeAccount();
  if (!account) throw new Error("Sign in to synchronize Workboard previews.");
  if (!blob) {
    return postJSON("/workboards/previews/clear", {
      auth: { accountUserID: account.userID },
      projectID
    }, { token: account.sessionToken });
  }
  const url = new URL("/workboards/previews/upload", window.location.origin);
  url.searchParams.set("projectID", projectID);
  url.searchParams.set("workboardUpdatedAt", metadata.updatedAt || new Date().toISOString());
  url.searchParams.set("elementCount", String(metadata.elementCount || 0));
  const response = await fetch(url, {
    method: "POST",
    headers: {
      authorization: `Bearer ${account.sessionToken}`,
      "content-type": "image/png",
      "x-permitext-user-id": account.userID
    },
    body: blob
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(responseErrorMessage(payload, "Could not save the Workboard preview."));
  }
  return payload.preview;
}

function blobDataURL(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error || new Error("Could not read this Workboard image."));
    reader.readAsDataURL(blob);
  });
}

async function loadWorkboardAsset(asset) {
  const account = activeAccount();
  if (!account) throw new Error("Sign in to load synchronized Workboard images.");
  const response = await fetch("/workboards/assets/read", {
    method: "POST",
    headers: {
      authorization: `Bearer ${account.sessionToken}`,
      "content-type": "application/json"
    },
    body: JSON.stringify({
      auth: { accountUserID: account.userID },
      pathname: asset?.pathname,
      projectID: asset?.projectID
    })
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(responseErrorMessage(payload, "Could not load this Workboard image."));
  }
  return blobDataURL(await response.blob());
}

function swiftReferenceDateSeconds(date = new Date()) {
  return (date.getTime() - Date.UTC(2001, 0, 1)) / 1000;
}

function continuityRecentEntries(values = {}) {
  try {
    const parsed = JSON.parse(values.recentlyViewedSectionsJSON || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function recentViewCodePrefix(entry) {
  const explicitPrefix = String(entry?.codePrefix || "").trim().toUpperCase();
  if (codeOptions.some((option) => option.prefix === explicitPrefix)) return explicitPrefix;
  const codeSectionName = String(entry?.codeSectionName || "").trim();
  const nativeNames = { "building code": "BC", "general administrative code": "AC",
    "plumbing code": "PC", "mechanical code": "MC", "fuel gas code": "FGC",
    "zoning resolution": "ZR", "fire code": "FC", "housing maintenance code": "HMC",
    "energy conservation code": "ECC", "electrical code": "EC", "existing building code": "EBC" };
  const named = codeOptions.find((option) => option.label === codeSectionName)?.prefix ||
    nativeNames[codeSectionName.toLocaleLowerCase("en-US")];
  if (named) return named;
  // Only the construction-library category IDs shared by both clients are known.
  const version = recentViewSourceVersion(entry);
  if (version && version !== defaultSyncCodeVersion && version !== historicalConstructionSyncCodeVersion) return "";
  return ({ 1: "BC", 3: "AC", 4: "FGC", 5: "PC", 6: "MC" })[Number(entry?.codeSectionID)] || "";
}

function recentViewSourceVersion(entry) {
  const version = String(entry?.codeVersion || entry?.sourceVersion || "").trim();
  return version ? syncCodeVersion(version) : "";
}

function recentViewNavigationSource(entry) {
  const version = recentViewSourceVersion(entry);
  const detail = { ...entry };
  const prefix = recentViewCodePrefix(entry);
  if (prefix) detail.codePrefix = prefix;
  else delete detail.codePrefix;
  if (version) detail.codeVersion = version;
  else delete detail.codeVersion;
  return detail;
}

function recentViewSourceLabel(entry) {
  const version = recentViewSourceVersion(entry);
  const prefix = recentViewCodePrefix(entry);
  if (version && prefix && codeOptions.some(option => option.prefix === prefix && codeOptionVersion(option) === version)) {
    return codeDisplayLabel(prefix, version);
  }
  return `${prefix || "Code source"} · ${version ? "Source details unavailable" : "Edition not recorded"}`;
}

function recentViewIdentity(entry) {
  const sectionID = Number(entry?.sectionID);
  if (!Number.isSafeInteger(sectionID) || sectionID <= 0) return "";
  const version = recentViewSourceVersion(entry);
  // Section IDs are library-wide within an edition, as in native historyIdentity.
  if (version) return JSON.stringify([version, sectionID]);
  const category = recentViewCodePrefix(entry) || `category:${String(entry?.codeSectionID || entry?.codeSectionName || "unknown").trim().toLocaleLowerCase("en-US")}`;
  return JSON.stringify(["legacy", category, sectionID]);
}

function recentViewEntryForReader(reader, chapter = null) {
  const sectionID = Number(reader?.sectionID || 0);
  if (!Number.isSafeInteger(sectionID) || sectionID <= 0) return null;
  const codeVersion = recentViewSourceVersion(reader);
  if (!codeVersion) return null;
  const matchesEdition = (item) => item && recentViewSourceVersion(item) === codeVersion;
  const resolvedChapter = matchesEdition(chapter) ? chapter : chapters.find((item) =>
    String(item.id) === String(reader.chapterID || "") && matchesEdition(item));
  const codeOption = codeOptionFor(reader.codePrefix || resolvedChapter?.codePrefix || "BC", codeVersion);
  const entry = {
    codeVersion,
    sourceVersion: codeVersion,
    sectionID,
    sectionNumber: reader.sectionNumber || "",
    title: reader.title || "Section",
    chapterTitle: resolvedChapter?.fullTitle || resolvedChapter?.displayTitle || resolvedChapter?.title || "",
    codeSectionID: resolvedChapter?.codeSectionID || null,
    codeSectionName: codeOption?.label || reader.codePrefix || "",
    codePrefix: reader.codePrefix || resolvedChapter?.codePrefix || "BC",
    chapterID: reader.chapterID || resolvedChapter?.id || "",
    chapterNumber: resolvedChapter?.chapterNumber || "",
    previewText: "",
    viewedAt: swiftReferenceDateSeconds()
  };
  const identity = recentViewIdentity(entry);
  const previous = (state.recentlyViewedSections || []).find((item) => recentViewIdentity(item) === identity);
  if (previous?.previewText) entry.previewText = previous.previewText;
  return entry;
}

function mergeRecentlyViewedDetails(entries, options = {}) {
  const detailsByIdentity = new Map(
    (entries || [])
      .filter((entry) => recentViewIdentity(entry) && String(entry.previewText || "").trim())
      .map((entry) => [recentViewIdentity(entry), entry])
  );
  if (!detailsByIdentity.size) return false;
  let changed = false;
  const mergedEntries = (state.recentlyViewedSections || []).map((entry) => {
    const details = detailsByIdentity.get(recentViewIdentity(entry));
    if (!details || String(entry.previewText || "").trim() === String(details.previewText || "").trim()) return entry;
    changed = true;
    return {
      ...entry,
      ...details,
      viewedAt: entry.viewedAt || details.viewedAt
    };
  });
  const mergedIdentities = new Set(mergedEntries.map(recentViewIdentity).filter(Boolean));
  detailsByIdentity.forEach((details, identity) => {
    if (mergedIdentities.has(identity)) return;
    mergedEntries.push(details);
    mergedIdentities.add(identity);
    changed = true;
  });
  state.recentlyViewedSections = mergedEntries.slice(0, recentViewLimit);
  if (changed && options.persist !== false) saveWorkspaceState();
  return changed;
}

function cacheRecentlyViewedReaderPreview(reader, section) {
  if (!reader?.sectionID || !section) return;
  const entry = recentViewEntryForReader(reader);
  if (!entry) return;
  const sectionNumber = section.sectionNumber || entry.sectionNumber || "";
  const sectionTitle = section.title || entry.title || "Section";
  const rawPreview = sectionPlainText(section);
  const titleWithoutNumber = stripLeadingSectionNumber(sectionTitle, sectionNumber);
  const previewSource = rawPreview || titleWithoutNumber;
  const previewText = snippetWithoutDuplicateTitle({
    sectionNumber,
    title: sectionTitle,
    snippet: previewSource
  }).replace(/\s+/g, " ").trim().slice(0, 360);
  if (!previewText) return;
  const changed = mergeRecentlyViewedDetails([{
    ...entry,
    sectionNumber,
    title: sectionTitle,
    previewText
  }]);
  if (changed) scheduleRecentSearchContinuitySync(reader);
}

function continuityRecentSearches(values = {}) {
  try {
    const parsed = JSON.parse(values.recentSearchesJSON || "[]");
    return normalizeSearchHistory(Array.isArray(parsed) ? parsed : [], recentSearchLimit);
  } catch {
    return [];
  }
}

function continuityRecentSearchHistory(values = {}, fallbackTimestamp = 0) {
  try {
    const parsed = JSON.parse(values.recentSearchHistoryJSON || "[]");
    const explicit = normalizeRecentSearchHistory(parsed, recentSearchLimit);
    if (explicit.length) return explicit;
  } catch {
    // Fall through to the ordered legacy search list.
  }
  return continuityRecentSearches(values).map((query, index) => ({
    query,
    searchedAt: Math.max(0, fallbackTimestamp - index)
  }));
}

function outgoingRecentSearchHistory(existingValues, recentSearches) {
  const candidates = [
    ...normalizeRecentSearchHistory(state.recentSearchHistory, recentSearchLimit),
    ...continuityRecentSearchHistory(existingValues)
  ];
  const byQuery = new Map();
  candidates.forEach((entry) => {
    const key = entry.query.normalize("NFKC").toLocaleLowerCase("en-US");
    const current = byQuery.get(key);
    if (!current || entry.searchedAt > current.searchedAt) byQuery.set(key, entry);
  });
  const fallbackTimestamp = Date.now();
  return recentSearches.map((query, index) => {
    const key = query.normalize("NFKC").toLocaleLowerCase("en-US");
    return byQuery.get(key) || { query, searchedAt: fallbackTimestamp - index };
  });
}

function recordRecentlyViewedReader(reader) {
  const chapter = chapters.find((item) => String(item.id) === String(reader.chapterID || ""));
  const entry = recentViewEntryForReader(reader, chapter);
  if (!entry) return;
  const identity = recentViewIdentity(entry);
  state.recentlyViewedSections = [
    entry,
    ...(state.recentlyViewedSections || []).filter((item) => recentViewIdentity(item) !== identity)
  ].slice(0, recentViewLimit);
  state.recentActivityUpdatedAt = new Date().toISOString();
  saveWorkspaceState();
}

function continuityValuesForReader(reader, options = {}) {
  const account = activeAccount();
  const pendingRecord = [...(state.syncOutbox || [])].reverse()
    .filter((entry) => !account || entry.accountUserID === account.userID)
    .map((entry) => mutationKindAndRecord(entry.mutation))
    .find(({ kind }) => kind === "continuity")?.record;
  const existing = pendingRecord?.values || syncedContent?.summary?.latestContinuity?.values || {};
  const chapter = chapters.find((item) => String(item.id) === String(reader.chapterID || ""));
  const sectionID = Number(reader.sectionID || 0);
  const syncedRecentEntries = continuityRecentEntries(existing);
  const recentEntries = [...(state.recentlyViewedSections || [])];
  syncedRecentEntries.forEach((entry) => {
    if (!recentEntries.some((candidate) => recentViewIdentity(candidate) === recentViewIdentity(entry))) recentEntries.push(entry);
  });
  if (options.promoteReader !== false && Number.isSafeInteger(sectionID) && sectionID > 0) {
    const entry = recentViewEntryForReader(reader, chapter);
    const identity = recentViewIdentity(entry);
    recentEntries.splice(
      0,
      recentEntries.length,
      entry,
      ...recentEntries
        .filter((item) => recentViewIdentity(item) !== identity)
        .slice(0, recentViewLimit - 1)
    );
  }
  const recentSearches = normalizeSearchHistory(state.recentSearches, recentSearchLimit);
  const recentSearchHistory = outgoingRecentSearchHistory(existing, recentSearches);
  return {
    ...existing,
    selectedJurisdictionKey: "jurisdiction-1",
    selectedVersionFileName: defaultSyncCodeVersion,
    selectedCodeSectionID: chapter?.codeSectionID
      ? String(chapter.codeSectionID)
      : existing.selectedCodeSectionID || "",
    lastOpenedChapterID: reader.chapterID
      ? String(reader.chapterID)
      : existing.lastOpenedChapterID || "",
    recentlyViewedSectionsJSON: JSON.stringify(recentEntries.slice(0, recentViewLimit)),
    recentSearchesJSON: JSON.stringify(recentSearches),
    recentSearchHistoryJSON: JSON.stringify(recentSearchHistory)
  };
}

function scheduleContinuitySync(reader) {
  recordRecentlyViewedReader(reader);
  const account = activeAccount();
  if (!account || !reader?.chapterID) return;
  clearTimeout(continuityPushTimer);
  continuityPushTimer = window.setTimeout(() => {
    const updatedAt = new Date().toISOString();
    const mutation = {
      continuity: {
        userID: account.userID,
        codeVersion: defaultSyncCodeVersion,
        values: continuityValuesForReader(reader),
        updatedAt
      }
    };
    state.continuityAppliedAt = updatedAt;
    enqueueSyncMutation(mutation, account);
    flushSyncOutbox({ refresh: true }).catch(() => {});
  }, 500);
}

function scheduleRecentSearchContinuitySync(sourceReader = null) {
  const account = activeAccount();
  if (!account) return;
  clearTimeout(continuityPushTimer);
  continuityPushTimer = window.setTimeout(() => {
    const updatedAt = new Date().toISOString();
    const reader = sourceReader || state.readers[0] || {};
    state.continuityAppliedAt = updatedAt;
    enqueueSyncMutation({
      continuity: {
        userID: account.userID,
        codeVersion: defaultSyncCodeVersion,
        values: continuityValuesForReader(reader, { promoteReader: false }),
        updatedAt
      }
    }, account);
    flushSyncOutbox({ refresh: true }).catch(() => {});
  }, 500);
}

async function applyRemoteContinuityIfNewer() {
  const record = syncedContent?.summary?.latestContinuity;
  const remoteTimestamp = Date.parse(record?.updatedAt || 0);
  const appliedTimestamp = Date.parse(state.continuityAppliedAt || 0);
  const hasPendingContinuity = (state.syncOutbox || []).some((entry) =>
    mutationKindAndRecord(entry.mutation).kind === "continuity"
  );
  if (!record || !Number.isFinite(remoteTimestamp) || remoteTimestamp <= appliedTimestamp || hasPendingContinuity) return;

  state.continuityAppliedAt = record.updatedAt;
  const recentActivityTimestamp = Date.parse(state.recentActivityUpdatedAt || 0);
  if (!Number.isFinite(recentActivityTimestamp) || remoteTimestamp >= recentActivityTimestamp) {
    const remoteRecentEntries = continuityRecentEntries(record.values);
    const localDetails = new Map(
      (state.recentlyViewedSections || [])
        .filter((entry) => String(entry.previewText || "").trim())
        .map((entry) => [recentViewIdentity(entry), entry])
    );
    state.recentlyViewedSections = remoteRecentEntries.slice(0, recentViewLimit).map((entry) => {
      const local = localDetails.get(recentViewIdentity(entry));
      return !entry.previewText && local?.previewText
        ? { ...entry, previewText: local.previewText }
        : entry;
    });
    if (record.values?.recentSearchesJSON !== undefined) {
      state.recentSearches = continuityRecentSearches(record.values);
      state.recentSearchHistory = continuityRecentSearchHistory(record.values, remoteTimestamp);
    }
    state.recentActivityUpdatedAt = record.updatedAt;
  }
  // A device may share recents, but it must never steer another device's
  // active reader, selected code, open columns, or project. Those are local
  // workspace choices and changing them during a background pull caused the
  // reader to jump to whatever paragraph had just been saved on iOS.
  saveWorkspaceState();
}

function enqueueSyncMutation(mutation, account, options = {}) {
  requirePrivateWorkspaceWritable();
  const currentAccount = activeAccount();
  const { record } = mutationKindAndRecord(mutation);
  if (!account || currentAccount?.userID !== account.userID ||
      currentAccount?.sessionToken !== account.sessionToken ||
      (record?.userID && record.userID !== account.userID)) {
    throw accountContextChangedError();
  }
  const recordID = syncMutationRecordID(mutation);
  if (!recordID) throw new Error("Could not queue a sync record without an ID.");
  const entry = {
    id: `${account.userID}:${recordID}`,
    accountUserID: account.userID,
    recordID,
    mutation,
    operationGroupID: options.operationGroupID || null,
    queuedAt: new Date().toISOString(),
    attemptCount: 0,
    lastError: null
  };
  state.syncOutbox = [
    ...(state.syncOutbox || []).filter((item) => item.id !== entry.id),
    entry
  ];
  state.syncConflicts = (state.syncConflicts || []).filter((item) => item.id !== entry.id);
  saveWorkspaceState();
  markForegroundSyncActivity();
  return entry;
}

async function pushMutationBatch(mutations, options = {}) {
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!account || !mutations.length) return null;
  const operationGroupID = options.operationGroupID || crypto.randomUUID();
  const entries = mutations.map((mutation) => enqueueSyncMutation(mutation, account, { operationGroupID }));
  const result = await flushSyncOutbox({ refresh: true });
  requireCurrentAccountRequest(requestIdentity);
  const rejected = entries.find((entry) => result.rejectedMutationIDs.includes(entry.recordID));
  if (rejected) {
    const reason = result.payload?.rejectionReasons?.[rejected.recordID];
    throw new Error(reason?.message || "One or more destination changes could not be synced.");
  }
  entries
    .filter((entry) => result.acceptedMutationIDs.includes(entry.recordID))
    .forEach((entry) => discardLocalMutationOverlay(entry.mutation));
  saveWorkspaceState();
  return result.payload;
}

function recoverQueuedWorkboardProjectID(record = {}) {
  const direct = String(record.projectID || "").trim();
  if (direct && direct.length <= 200) return direct;
  const recordID = String(record.id || "");
  const markerIndex = recordID.lastIndexOf(":workboard:");
  const embedded = markerIndex === -1 ? "" : recordID.slice(markerIndex + ":workboard:".length).trim();
  if (embedded && embedded.length <= 200) return embedded;
  const matchingProject = visibleProjectRecords(syncedContent?.summary?.projects || []).find((project) =>
    String(project.name || project.title || "").trim() === String(record.projectName || "").trim()
  );
  const matchedID = workboardProjectID(matchingProject);
  return matchedID && matchedID.length <= 200 ? matchedID : "";
}

function prepareSyncOutboxForFlush(account) {
  const repairedEntries = [];
  const quarantinedEntries = [];
  let changed = false;
  (state.syncOutbox || []).forEach((entry) => {
    if (entry.accountUserID !== account.userID) {
      repairedEntries.push(entry);
      return;
    }
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    let mutation = entry.mutation;
    if (kind === "workboard") {
      const projectID = recoverQueuedWorkboardProjectID(record);
      if (!projectID) {
        changed = true;
        quarantinedEntries.push({
          ...entry,
          conflictedAt: new Date().toISOString(),
          lastError: "Workboard sync paused because its project identity is missing."
        });
        return;
      }
      const canonicalWorkboardID = `${account.userID}:workboard:${projectID}`;
      mutation = {
        workboard: {
          ...record,
          id: canonicalWorkboardID,
          userID: account.userID,
          projectID
        }
      };
    } else if (kind === "project") {
      mutation = {
        project: {
          ...record,
          clientID: syncProjectIdentity(record.clientID, account.userID) ||
            syncProjectIdentity(record.id, account.userID) ||
            record.localFolderID ||
            null
        }
      };
    } else if (kind === "projectSection") {
      mutation = {
        projectSection: {
          ...record,
          folderClientID: syncProjectIdentity(record.folderClientID, account.userID) || null
        }
      };
    }
    const canonicalID = syncMutationRecordID(mutation);
    if (!canonicalID) {
      changed = true;
      quarantinedEntries.push({
        ...entry,
        conflictedAt: new Date().toISOString(),
        lastError: "Sync paused because this record has no stable cross-device identity."
      });
      return;
    }
    const repaired = {
      ...entry,
      id: `${account.userID}:${canonicalID}`,
      recordID: canonicalID,
      mutation
    };
    if (
      repaired.id !== entry.id ||
      repaired.recordID !== entry.recordID ||
      repaired.mutation !== entry.mutation
    ) changed = true;
    repairedEntries.push(repaired);
  });
  if (!changed) return;
  state.syncOutbox = Array.from(new Map(repairedEntries.map((entry) => [entry.id, entry])).values());
  state.syncConflicts = [
    ...(state.syncConflicts || []).filter((entry) => !quarantinedEntries.some((invalid) => invalid.id === entry.id)),
    ...quarantinedEntries
  ];
  saveWorkspaceState();
}

function discardLocalMutationOverlay(mutation) {
  const { kind, record } = mutationKindAndRecord(mutation);
  const recordID = syncMutationRecordID(mutation);
  if (!recordID) return;
  if (kind === "savedItem") {
    state.localSavedItems = (state.localSavedItems || []).filter((item) =>
      String(item.id || "") !== String(record.id || "") &&
      savedEvidenceKey(item) !== savedEvidenceKey(record)
    );
    const localSavedKey = savedEvidenceKey(record);
    state.localSavedSectionIDs = (state.localSavedSectionIDs || [])
      .filter((sectionID) => String(sectionID) !== localSavedKey && String(sectionID) !== String(record.id || ""));
  } else if (kind === "annotation") {
    state.localAnnotations = (state.localAnnotations || []).filter((item) =>
      String(item.id || "") !== String(record.id || "") &&
      !(
        String(item.sectionID || "") === String(record.sectionID || "") &&
        normalizeAnnotationBlockID(item.blockID) === normalizeAnnotationBlockID(record.blockID)
      )
    );
  } else if (kind === "project") {
    state.localProjects = (state.localProjects || []).filter((item) => !projectDetailMatches(item, record));
  } else if (kind === "projectSection") {
    const identity = [
      syncCodeVersion(record.codeVersion),
      record.folderClientID || record.localFolderID || "",
      record.sectionID || "",
      normalizeAnnotationBlockID(record.blockID),
      record.scope || ""
    ].map(String).join(":");
    state.localProjectSections = (state.localProjectSections || []).filter((item) => [
      syncCodeVersion(item.codeVersion),
      item.folderClientID || item.localFolderID || "",
      item.sectionID || "",
      normalizeAnnotationBlockID(item.blockID),
      item.scope || ""
    ].map(String).join(":") !== identity);
  } else if (kind === "continuity") {
    state.continuityAppliedAt = null;
  }
}

async function resolveSyncConflict(entry, keepLocal) {
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!account || entry.accountUserID !== account.userID) return;
  if (keepLocal) {
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    if (!kind || !record) return;
    const resolvedRecord = kind === "annotation" && Object.prototype.hasOwnProperty.call(record, "noteBody")
      ? { ...record, noteBody: detailNoteValueForTarget(record) }
      : record;
    enqueueSyncMutation({
      [kind]: { ...resolvedRecord, userID: account.userID, updatedAt: new Date().toISOString() }
    }, account);
    await flushSyncOutbox({ refresh: true });
    requireCurrentAccountRequest(requestIdentity);
  } else {
    const { kind, record } = mutationKindAndRecord(entry.mutation);
    if (kind !== "workboard") discardLocalMutationOverlay(entry.mutation);
    state.syncConflicts = (state.syncConflicts || []).filter((item) => item.id !== entry.id);
    saveWorkspaceState();
    await loadSyncedContent({ force: true });
    requireCurrentAccountRequest(requestIdentity);
    if (kind === "workboard") {
      const projectID = String(record?.projectID || "");
      await replaceLocalWorkboard(projectID, syncedWorkboardForProject(projectID));
      requireCurrentAccountRequest(requestIdentity);
    }
  }
  await refreshSyncedWorkspaceInPlace({ accountUserID: requestIdentity.userID });
}

function scheduleSyncOutboxRetry(attemptCount = 1) {
  clearTimeout(syncRetryTimer);
  const exponent = Math.min(Math.max(Number(attemptCount) - 1, 0), 6);
  const delay = Math.min(5_000 * (2 ** exponent), 5 * 60_000);
  syncRetryTimer = window.setTimeout(() => {
    flushSyncOutbox({ refresh: true }).catch(() => {});
  }, delay);
}

async function flushSyncOutbox(options = {}) {
  const account = activeAccount();
  const identity = captureAccountRequest();
  if (!account) return { acceptedMutationIDs: [], rejectedMutationIDs: [] };
  if (syncFlushPromise) {
    const inFlightResult = await syncFlushPromise;
    requireCurrentAccountRequest(identity);
    const stillActiveAccount = activeAccount();
    const hasPending = stillActiveAccount && (state.syncOutbox || [])
      .some((item) => item.accountUserID === stillActiveAccount.userID);
    if (!hasPending) return inFlightResult;
    const followUpResult = await flushSyncOutbox(options);
    return {
      ...followUpResult,
      acceptedMutationIDs: Array.from(new Set([
        ...(inFlightResult.acceptedMutationIDs || []),
        ...(followUpResult.acceptedMutationIDs || [])
      ])),
      rejectedMutationIDs: Array.from(new Set([
        ...(inFlightResult.rejectedMutationIDs || []),
        ...(followUpResult.rejectedMutationIDs || [])
      ]))
    };
  }

  const request = (async () => {
    retryRejectedDeletionConflictsOnce(account);
    prepareSyncOutboxForFlush(account);
    const acceptedMutationIDs = [];
    const rejectedMutationIDs = [];
    let latestPayload = null;
    while (true) {
      requireCurrentAccountRequest(identity);
      const queuedEntries = (state.syncOutbox || [])
        .filter((item) => item.accountUserID === account.userID);
      let entries = queuedEntries.slice(0, 100);
      const boundaryGroupID = entries.at(-1)?.operationGroupID;
      if (boundaryGroupID) {
        entries = queuedEntries.filter((item, index) =>
          index < 100 || item.operationGroupID === boundaryGroupID
        );
      }
      if (!entries.length) break;

      try {
        const payload = await postJSON("/sync/push", {
          auth: { accountUserID: account.userID },
          syncSchemaVersion: permitextSyncSchemaVersion,
          clientCapabilities: permitextClientCapabilities,
          batch: {
            user: { id: account.userID },
            mutations: entries.map((item) => item.mutation)
          }
        }, { token: account.sessionToken });
        latestPayload = payload;
        const accepted = new Set(payload.acceptedMutationIDs || []);
        const rejected = new Set(payload.rejectedMutationIDs || []);
        acceptedMutationIDs.push(...accepted);
        rejectedMutationIDs.push(...rejected);
        const completedEntryIDs = new Set(entries
          .filter((item) => accepted.has(item.recordID) || rejected.has(item.recordID))
          .map((item) => item.id));
        const postedEntryVersions = new Map(entries.map((item) => [item.id, item.queuedAt]));
        const unknownEntries = entries.filter((item) =>
          !completedEntryIDs.has(item.id) &&
          (state.syncOutbox || []).some((current) => current.id === item.id && current.queuedAt === item.queuedAt)
        );
        const rejectedEntries = entries.filter((item) =>
          rejected.has(item.recordID) &&
          (state.syncOutbox || []).some((current) => current.id === item.id && current.queuedAt === item.queuedAt)
        );

        state.syncOutbox = (state.syncOutbox || [])
          .filter((item) =>
            (!completedEntryIDs.has(item.id) && !unknownEntries.some((entry) => entry.id === item.id)) ||
              postedEntryVersions.get(item.id) !== item.queuedAt
          );
        state.syncConflicts = [
          ...(state.syncConflicts || []).filter((item) =>
            !rejectedEntries.some((entry) => entry.id === item.id) &&
            !unknownEntries.some((entry) => entry.id === item.id)
          ),
          ...rejectedEntries.map((item) => ({
            ...item,
            conflictedAt: new Date().toISOString(),
            rejectionCode: payload.rejectionReasons?.[item.recordID]?.code || null,
            lastError: payload.rejectionReasons?.[item.recordID]?.message ||
              "Server has a newer version of this record."
          })),
          ...unknownEntries.map((item) => ({
            ...item,
            conflictedAt: new Date().toISOString(),
            lastError: "A legacy queued change could not be reconciled and was paused."
          }))
        ];
        absorbBulkClearConflicts();
        saveWorkspaceState();
        storeAccountEntitlement(payload.entitlement || null);
      } catch (error) {
        requireCurrentAccountRequest(identity);
        const entryVersions = new Map(entries.map((item) => [item.id, item.queuedAt]));
        let highestAttemptCount = 1;
        state.syncOutbox = (state.syncOutbox || []).map((item) => {
          if (entryVersions.get(item.id) !== item.queuedAt) return item;
          const attemptCount = Number(item.attemptCount || 0) + 1;
          highestAttemptCount = Math.max(highestAttemptCount, attemptCount);
          return { ...item, attemptCount, lastError: error.message || "Sync failed." };
        });
        saveWorkspaceState();
        scheduleSyncOutboxRetry(highestAttemptCount);
        throw error;
      }
    }

    clearTimeout(syncRetryTimer);
    syncRetryTimer = null;
    if (options.refresh !== false && latestPayload) {
      await loadSyncedContent({ force: true, skipOutbox: true });
    }
    requireCurrentAccountRequest(identity);
    if (acceptedMutationIDs.length > 0 && latestPayload) {
      markForegroundSyncActivity();
      broadcastForegroundSyncSignal("sync-invalidated", {
        latestEventID: latestPayload.latestEventID
      });
    }
    return { acceptedMutationIDs, rejectedMutationIDs, payload: latestPayload };
  })().finally(() => {
    if (syncFlushPromise === request) syncFlushPromise = null;
    if (isCurrentAccountRequest(identity)) updateConnectionStatus();
  });
  syncFlushPromise = request;
  updateConnectionStatus();
  return syncFlushPromise;
}

function syncResultChangesWorkspace(result) {
  return Boolean(
    result?.payload ||
    result?.acceptedMutationIDs?.length ||
    result?.rejectedMutationIDs?.length
  );
}

async function flushPendingSyncAndRender() {
  const accountUserID = activeAccount()?.userID || "";
  const result = await flushSyncOutbox({ refresh: true });
  if (syncResultChangesWorkspace(result)) {
    await refreshSyncedWorkspaceInPlace({ accountUserID });
  }
}

function visibleSyncedTargetKey(target) {
  return [
    syncCodeVersion(target?.codeVersion || defaultSyncCodeVersion),
    String(target?.sectionID || ""),
    normalizeAnnotationBlockID(target?.blockID)
  ].join(":");
}

function refreshVisibleSyncedDerivedState() {
  const targets = new Map();
  const addTarget = (target) => {
    if (!target?.sectionID) return;
    targets.set(visibleSyncedTargetKey(target), {
      ...target,
      codeVersion: syncCodeVersion(target.codeVersion || defaultSyncCodeVersion),
      blockID: normalizeAnnotationBlockID(target.blockID)
    });
  };

  track.querySelectorAll(".inline-comment[data-comment-section-id]").forEach((wrapper) => {
    addTarget({
      sectionID: wrapper.dataset.commentSectionId,
      blockID: wrapper.dataset.commentBlockId,
      codeVersion: wrapper.dataset.commentCodeVersion
    });
  });
  track.querySelectorAll(".section-detail-panel").forEach((element) => {
    addTarget(element.__annotationTarget);
  });

  const focusedElement = document.activeElement;
  targets.forEach((target) => {
    syncReaderNoteControls(
      target.sectionID,
      target.blockID,
      noteValueForTarget(target),
      { source: focusedElement, target }
    );
  });

  const visibleReaderSections = new Map();
  track.querySelectorAll(".reader-panel .chapter-section[data-section-id]").forEach((section) => {
    const target = {
      sectionID: section.dataset.sectionId,
      codeVersion: section.dataset.codeVersion || defaultSyncCodeVersion
    };
    visibleReaderSections.set(visibleSyncedTargetKey(target), target);
  });
  visibleReaderSections.forEach((target) => {
    syncReaderNoteBookmarkButtons(
      target.sectionID,
      isSectionSaved(target),
      target.codeVersion
    );
  });

  track.querySelectorAll(".section-detail-panel").forEach((panel) => {
    const target = panel.__annotationTarget;
    const sectionPayload = panel.__sectionPayload;
    if (!target?.sectionID || !sectionPayload?.sectionID) return;
    const notes = panel.querySelector(".section-detail-notes");
    notes?.dispatchEvent(new CustomEvent("permitext-folder-save", {
      detail: { saved: isSectionSaved(sectionPayload) }
    }));
    const textarea = notes?.querySelector("textarea");
    if (textarea && textarea !== focusedElement) textarea.value = detailNoteValueForTarget(target);
  });

  openProjectDetails().forEach((detail) => {
    const currentProject = visibleProjectRecords(currentContentSummary().projects || [])
      .find((project) => projectDetailMatches(project, detail));
    if (currentProject) refreshOpenProjectPaneTheme(currentProject);
  });
  refreshOpenAnnotationProjectEditors();
  refreshVisiblePlanUsage();
  updateConnectionStatus();
}

function workspacePaneHasFocusedEditor(paneID) {
  const focusedElement = document.activeElement;
  if (!focusedElement?.matches?.('input, textarea, select, [contenteditable="true"]')) return false;
  return Boolean(
    track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`)
      ?.contains(focusedElement)
  );
}

function reconcileOpenProjectIdentityAfterSync(projects = currentContentSummary().projects || []) {
  const previous = openProjectDetails()[0] || null;
  if (!previous) return { detail: null, status: "current" };
  if (syncedContent?.status !== "connected") return { detail: previous, status: "current" };
  const syncedProject = visibleProjectRecords(projects)
    .find((project) => projectDetailMatches(project, previous)) || null;
  if (!syncedProject) return { detail: previous, status: "unavailable" };

  const next = { ...previous, ...projectIdentity(syncedProject) };
  const nextIdentity = projectIdentity(next);
  const replaceIdentity = (items = []) => items.map((item) =>
    projectDetailMatches(item, previous) ? { ...item, ...nextIdentity } : item
  );
  setOpenProjectDetails([next]);
  state.workboards = replaceIdentity(openWorkboards());
  state.notebooks = replaceIdentity(openNotebooks());
  state.reportDrafts = replaceIdentity(openReportDrafts());
  state.coordinations = replaceIdentity(openCoordinations());
  state.coordinationThreads = replaceIdentity(openCoordinationThreads());
  state.detachedWorkboards = replaceIdentity(detachedWorkboards());
  return {
    detail: next,
    status: projectIsArchived(syncedProject)
      ? "archived"
      : folderIsProject(syncedProject) ? "current" : "unavailable"
  };
}

function refreshMountedProjectChrome(project) {
  if (!project) return;
  const identity = projectIdentity(project);
  const projectID = projectDetailKey(identity);
  const projectRecordIDs = new Set([
    projectID,
    projectRecordID(identity),
    String(identity.id || ""),
    String(identity.clientID || ""),
    String(identity.localFolderID || "")
  ].filter(Boolean));
  const projectName = identity.name || identity.title || "Project";
  refreshOpenProjectPaneTheme(identity);

  const paneIDs = new Set([
    paneIDForProjectDetail(identity),
    paneIDForProjectWorkboard(identity),
    paneIDForProjectNotebook(identity),
    paneIDForProjectReportDraft(identity),
    paneIDForProjectCoordination(identity),
    ...(openCoordinationThreadForProject(identity)
      ? [paneIDForProjectCoordinationThread(identity, openCoordinationThreadForProject(identity).threadID)]
      : [])
  ]);
  const panels = new Set(
    Array.from(track.querySelectorAll(`.workspace-panel[data-project-id="${CSS.escape(projectID)}"]`))
  );
  paneIDs.forEach((paneID) => {
    const panel = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
    if (panel) panels.add(panel);
  });

  panels.forEach((panel) => {
    panel.querySelectorAll(".project-tool-pane-drag-handle").forEach((handle) => {
      handle.title = `Reorder ${projectName} tools`;
      handle.setAttribute("aria-label", handle.title);
    });
    const reportEyebrow = panel.querySelector(".report-draft-eyebrow");
    if (reportEyebrow) reportEyebrow.textContent = projectName;
    const coordinationEyebrow = panel.querySelector(":scope > .coordination-header > div > span");
    if (coordinationEyebrow) coordinationEyebrow.textContent = projectName;
    const detailTitle = panel.querySelector(":scope > .project-detail-chrome .project-detail-heading > h2");
    if (detailTitle) detailTitle.textContent = projectName;
    panel.querySelectorAll(".coordination-thread-metadata dt").forEach((term) => {
      if (term.textContent === "Project" && term.nextElementSibling) {
        term.nextElementSibling.textContent = projectName;
      }
    });
  });

  track.querySelectorAll(".saved-project-tile[data-project-id]").forEach((tile) => {
    if (!projectRecordIDs.has(String(tile.dataset.projectId || ""))) return;
    tile.style.setProperty("--project-color", identity.color || projectColorOptions[0]);
    tile.style.setProperty("--project-on-color", projectForegroundColor(identity.color));
    tile.dataset.projectName = projectName;
    tile.dataset.defaultAriaLabel = `Open ${projectName}`;
    if (!tile.hasAttribute("aria-pressed")) tile.setAttribute("aria-label", tile.dataset.defaultAriaLabel);
    const title = tile.querySelector("strong");
    if (title) title.textContent = projectName;
  });
  (state.utilityInstances || [])
    .filter((instance) =>
      instance.key === "saved" && projectRecordIDs.has(String(instance.selectedFolderID || ""))
    )
    .forEach((instance) => {
      const panel = track.querySelector(
        `.saved-panel[data-pane-id="${CSS.escape(paneIDForUtilityInstance(instance))}"]`
      );
      if (!panel) return;
      panel.style.setProperty("--project-color", identity.color || projectColorOptions[0]);
      panel.querySelector(`.saved-folder-context[data-project-id="${CSS.escape(projectID)}"]`)
        ?.style.setProperty("--project-color", identity.color || projectColorOptions[0]);
      const menuLabel = panel.querySelector(".saved-projects-menu-toggle .code-filter-menu-label");
      if (menuLabel && !instance.projectsMenuOpen && !instance.projectsArchiveMode) {
        menuLabel.textContent = projectName;
      }
    });
  track
    .querySelectorAll(`.saved-folder-context.is-project[data-project-id="${CSS.escape(projectID)}"] .saved-project-tool-controls`)
    .forEach((controls) => controls.setAttribute("aria-label", `${projectName} tools`));
}

function updateOpenProjectSyncWarning(reconciliation) {
  track.querySelectorAll(".project-sync-stale-warning").forEach((warning) => warning.remove());
  track.querySelectorAll(".workspace-panel.has-stale-project-sync").forEach((panel) => {
    panel.classList.remove("has-stale-project-sync");
  });
  if (!reconciliation?.detail || reconciliation.status === "current") return;

  const detail = reconciliation.detail;
  const projectID = projectDetailKey(detail);
  const paneIDs = new Set([
    state.projectHostPaneID,
    paneIDForProjectDetail(detail),
    paneIDForProjectWorkboard(detail),
    paneIDForProjectNotebook(detail),
    paneIDForProjectReportDraft(detail),
    paneIDForProjectCoordination(detail),
    ...(openCoordinationThreadForProject(detail)
      ? [paneIDForProjectCoordinationThread(detail, openCoordinationThreadForProject(detail).threadID)]
      : [])
  ].filter(Boolean));
  const panels = new Set(
    Array.from(track.querySelectorAll(`.workspace-panel[data-project-id="${CSS.escape(projectID)}"]`))
  );
  paneIDs.forEach((paneID) => {
    const panel = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
    if (panel) panels.add(panel);
  });

  const archived = reconciliation.status === "archived";
  panels.forEach((panel) => {
    const warning = document.createElement("aside");
    warning.className = "project-studio-warning project-sync-stale-warning";
    warning.dataset.projectId = projectID;
    warning.setAttribute("role", "status");
    warning.setAttribute("aria-live", "polite");
    const heading = document.createElement("strong");
    heading.textContent = archived
      ? "Project archived on another device"
      : "Project no longer available after sync";
    const copy = document.createElement("p");
    copy.textContent = archived
      ? "This Project remains open so you can finish or copy work already in progress. Restore it before starting new Project changes."
      : "This Project remains open so you can copy work already in progress. It may have been deleted on another device or your access may have changed.";
    warning.append(heading, copy);
    const header = panel.querySelector(":scope > header");
    if (header) header.after(warning);
    else panel.prepend(warning);
    panel.classList.add("has-stale-project-sync");
  });
}

async function refreshBlankSearchHistoryPanes() {
  await Promise.all((state.utilityInstances || [])
    .filter((instance) => instance.key === "search" && !String(instance.query || "").trim())
    .map(async (instance) => {
      const paneID = paneIDForUtilityInstance(instance);
      const panel = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
      if (panel?.isConnected) await renderSearchHistory(panel, instance);
    }));
}

async function refreshSyncedWorkspaceInPlace(options = {}) {
  const expectedAccountUserID = options.accountUserID ?? activeAccount()?.userID ?? "";
  if ((activeAccount()?.userID || "") !== expectedAccountUserID) {
    await renderWorkspace();
    return false;
  }

  const syncedProjects = currentContentSummary().projects || [];
  const accessibleProjects = openProjectDetails().length
    ? await projectsWithOrganizationAccess(syncedProjects)
    : syncedProjects;
  if ((activeAccount()?.userID || "") !== expectedAccountUserID) {
    await renderWorkspace();
    return false;
  }
  const projectReconciliation = reconcileOpenProjectIdentityAfterSync(accessibleProjects);
  renderCodeQuestionShellChrome();
  const refreshPaneIDs = [
    ...(state.utilities.archive ? ["utility:archive"] : []),
    ...(state.utilities.settings && !workspacePaneHasFocusedEditor("utility:settings")
      ? ["utility:settings"]
      : [])
  ];
  await renderUtilityWorkspace({
    refreshPaneIDs,
    skipDeletedProjectCleanup: true,
    deferStateSave: true
  });

  if ((activeAccount()?.userID || "") !== expectedAccountUserID) {
    await renderWorkspace();
    return false;
  }
  await refreshBlankSearchHistoryPanes();
  await Promise.all(savedPaneIDs().map(async (paneID) => {
    if (workspacePaneHasFocusedEditor(paneID)) return false;
    return refreshSavedPanelInPlace(paneID, { reconcileProjectStudio: false }).catch(() => false);
  }));
  if ((activeAccount()?.userID || "") !== expectedAccountUserID) {
    await renderWorkspace();
    return false;
  }
  refreshVisibleSyncedDerivedState();
  refreshMountedProjectChrome(projectReconciliation.detail);
  updateOpenProjectSyncWarning(projectReconciliation);
  return true;
}

function canRunForegroundSync() {
  return Boolean(
    !detachedProjectWindow &&
    activeAccount() &&
    navigator.onLine &&
    document.visibilityState === "visible"
  );
}

function markForegroundSyncActivity() {
  foregroundSyncLastActivityAt = Date.now();
}

function foregroundSyncLeaseKey(accountUserID = activeAccount()?.userID || "") {
  return `${foregroundSyncLeaseKeyPrefix}${accountUserID}`;
}

function readForegroundSyncLease(accountUserID = activeAccount()?.userID || "") {
  if (!accountUserID) return null;
  try {
    return JSON.parse(localStorage.getItem(foregroundSyncLeaseKey(accountUserID)) || "null");
  } catch {
    return null;
  }
}

function claimForegroundSyncLeadership() {
  const accountUserID = activeAccount()?.userID || "";
  if (!accountUserID || !canRunForegroundSync()) return false;
  const now = Date.now();
  const existing = readForegroundSyncLease(accountUserID);
  if (!syncLeaderLeaseIsAvailable(existing, { accountUserID, tabID: foregroundSyncTabID, now })) {
    return false;
  }
  const lease = {
    accountUserID,
    tabID: foregroundSyncTabID,
    expiresAt: now + foregroundSyncSchedule.leaderLeaseMs
  };
  localStorage.setItem(foregroundSyncLeaseKey(accountUserID), JSON.stringify(lease));
  return readForegroundSyncLease(accountUserID)?.tabID === foregroundSyncTabID;
}

function isForegroundSyncLeader() {
  const accountUserID = activeAccount()?.userID || "";
  const lease = readForegroundSyncLease(accountUserID);
  return Boolean(
    accountUserID &&
    lease?.accountUserID === accountUserID &&
    lease?.tabID === foregroundSyncTabID &&
    Number(lease.expiresAt || 0) > Date.now()
  );
}

function releaseForegroundSyncLeadership() {
  const accountUserID = activeAccount()?.userID || "";
  if (!accountUserID) return;
  const key = foregroundSyncLeaseKey(accountUserID);
  if (readForegroundSyncLease(accountUserID)?.tabID === foregroundSyncTabID) {
    localStorage.removeItem(key);
    broadcastForegroundSyncSignal("leader-released");
  }
}

function visibleProjectArtifactIDs() {
  const consumerIDs = [];
  notebookMounts.forEach((mounted, projectID) => {
    if (mounted.panel?.isConnected) consumerIDs.push(projectID);
  });
  reportDraftMounts.forEach((mounted, projectID) => {
    if (mounted.panel?.isConnected) consumerIDs.push(projectID);
  });
  track.querySelectorAll(".workspace-panel[data-project-id], .saved-folder-context.is-project[data-project-id]")
    .forEach((element) => {
      if (element.isConnected) consumerIDs.push(element.dataset.projectId);
    });
  return uniqueProjectArtifactConsumerIDs(consumerIDs);
}

function researchArtifactConsumersVisible() {
  return Boolean(track.querySelector(
    ".research-list-panel.is-connected, .research-conversation-panel.is-connected"
  )) || Boolean(track.querySelector(".research-list-panel, .research-conversation-panel"));
}

function currentProjectArtifactScope() {
  const account = activeAccount();
  return {
    accountUserID: account?.userID || "",
    sessionToken: account?.sessionToken || "",
    accountGeneration: accountRuntimeGeneration,
    workspaceID: activeWorkspaceID,
    researchVisible: researchArtifactConsumersVisible(),
    visibleProjectIDs: new Set(visibleProjectArtifactIDs())
  };
}

async function refreshVisibleResearchArtifactConsumers() {
  const account = activeAccount();
  const workspaceID = activeWorkspaceID;
  const paneIDs = [];
  if (track.querySelector('.research-list-panel[data-pane-id="utility:analysis"]')) {
    paneIDs.push("utility:analysis");
  }
  const conversationIDs = [];
  if (
    researchConversationPaneIsOpen() &&
    track.querySelector(`.research-conversation-panel[data-pane-id="${CSS.escape(paneIDForResearchConversation())}"]`)
  ) {
    conversationIDs.push(state.researchConversationID);
  }
  supplementalResearchConversationIDs.forEach((conversationID) => {
    const paneID = paneIDForResearchConversation(conversationID);
    if (track.querySelector(`.research-conversation-panel[data-pane-id="${CSS.escape(paneID)}"]`)) {
      conversationIDs.push(conversationID);
    }
  });
  paneIDs.push(...conversationIDs.map((conversationID) => paneIDForResearchConversation(conversationID)));
  if (!account || !paneIDs.length) return false;
  const scrollPositions = new Map(paneIDs.map((paneID) => [
    paneID,
    track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`)?.scrollTop || 0
  ]));
  const refreshedConversations = await Promise.all(conversationIDs.map(async (conversationID) => {
    try {
      return [conversationID, await fetchAuthoritativeResearchConversation(conversationID)];
    } catch {
      return [conversationID, null];
    }
  }));
  if (
    activeAccount()?.userID !== account.userID ||
    activeAccount()?.sessionToken !== account.sessionToken ||
    activeWorkspaceID !== workspaceID ||
    !researchArtifactConsumersVisible()
  ) return false;
  refreshedConversations.forEach(([conversationID, conversation]) => {
    if (conversationID === state.researchConversationID) {
      activeResearchConversation = conversation;
    } else if (conversation) {
      supplementalResearchConversations.set(conversationID, conversation);
    } else {
      supplementalResearchConversations.delete(conversationID);
    }
  });
  const focusedDraftInput = document.activeElement?.matches?.(".research-question-input")
    ? document.activeElement
    : null;
  const focusedDraftPaneID = focusedDraftInput?.closest(".workspace-panel")?.dataset.paneId || "";
  const focusedDraftSelection = focusedDraftInput
    ? [focusedDraftInput.selectionStart, focusedDraftInput.selectionEnd]
    : null;
  const focusedDraftKey = focusedDraftInput?.dataset.researchDraftKey || "";
  await transitionWorkspace("utility", { refreshPaneIDs: paneIDs });
  if (activeAccount()?.userID !== account.userID ||
      activeAccount()?.sessionToken !== account.sessionToken ||
      activeWorkspaceID !== workspaceID) return false;
  // Each composer restores its own durable followup:<conversationID> draft.
  // Broadcasting researchQuestionDraft here overwrote unrelated panes (and
  // persisted an empty value after reload). Refresh must never synthesize input.

  if (focusedDraftPaneID) {
    const nextInput = track.querySelector(
      `.workspace-panel[data-pane-id="${CSS.escape(focusedDraftPaneID)}"] .research-question-input`
    );
    if (focusedDraftKey && nextInput?.dataset.researchDraftKey === focusedDraftKey) {
      nextInput.focus({ preventScroll: true });
      if (focusedDraftSelection) nextInput.setSelectionRange?.(...focusedDraftSelection);
    }
  }
  scrollPositions.forEach((scrollTop, paneID) => {
    const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
    if (pane) pane.scrollTop = Math.min(scrollTop, Math.max(0, pane.scrollHeight - pane.clientHeight));
  });
  return true;
}

async function applyAccountArtifactRevisionEnvelope(envelope) {
  const scope = currentProjectArtifactScope();
  const normalized = normalizeAccountArtifactRevisionEnvelope(envelope, scope);
  const key = accountArtifactRevisionKey(normalized);
  const result = reduceAccountArtifactRevision({
    envelope: normalized,
    revision: accountArtifactRevisions.get(key),
    scope
  });
  if (!result.accepted) return result;
  accountArtifactRevisions.set(key, result.accepted);
  if (result.refreshResearch) {
    await enqueueProjectArtifactConsumerRefresh(
      () => refreshVisibleResearchArtifactConsumers().catch(() => false)
    );
  }
  return result;
}

function projectArtifactRequestScopeIsCurrent(scope) {
  const current = currentProjectArtifactScope();
  return Boolean(
    canRunForegroundSync() &&
    scope.accountUserID &&
    current.accountUserID === scope.accountUserID &&
    current.sessionToken === scope.sessionToken &&
    current.accountGeneration === scope.accountGeneration &&
    current.workspaceID === scope.workspaceID
  );
}

function enqueueProjectArtifactConsumerRefresh(refresh) {
  const requestIdentity = captureAccountRequest();
  const scopedRefresh = () => isCurrentAccountRequest(requestIdentity) ? refresh() : false;
  const task = projectArtifactConsumerRefreshQueue.then(scopedRefresh, scopedRefresh);
  projectArtifactConsumerRefreshQueue = task.catch(() => false);
  return task;
}

async function refreshProjectArtifactConsumers(projectID, domains) {
  invalidateInitialProjectFoundation(projectID);
  const plan = projectArtifactRefreshPlan(domains);
  if (projectTransitionHubMatches(projectTransitionHubEntry, projectID)) {
    projectTransitionHubEntry = null;
  }
  if (plan.notebookCards) {
    await notebookMounts.get(projectID)?.refreshCards?.().catch(() => false);
  }
  await refreshProjectSourceConsumers([projectID], {
    refreshNotebookCards: false,
    refreshNotebookReferences: plan.notebookReferences,
    refreshNotebookFoundation: plan.notebookFoundation,
    refreshNotebookReportStatus: plan.notebookReportStatus,
    refreshReportArtifacts: plan.reportArtifacts,
    refreshReportSources: plan.reportSources
  });
  if (plan.notebookFoundation || plan.summaries) {
    refreshMountedResearchProjectContext(projectID);
  }
  if (plan.summaries) {
    await refreshVisibleProjectArtifactSummaries(projectID).catch(() => false);
  }
}

async function applyProjectArtifactRevisionEnvelopes(envelopes = [], options = {}) {
  const scope = currentProjectArtifactScope();
  const result = reduceProjectArtifactRevisions({
    envelopes,
    revisions: projectArtifactRevisions,
    scope
  });
  projectArtifactRevisions.clear();
  result.nextRevisions.forEach((value, key) => projectArtifactRevisions.set(key, value));
  if (options.broadcast === true && result.accepted.length) {
    broadcastForegroundSyncSignal("project-artifact-revisions", {
      workspaceID: scope.workspaceID,
      envelopes: result.accepted
    });
  }
  // The server checkpoint exposes the cumulative domain union for a Project,
  // not a per-revision delta. Refreshes can therefore include an older domain,
  // but remain bounded to connected consumers for the affected Project.
  await enqueueProjectArtifactConsumerRefresh(() => Promise.all(
    result.refreshes.map(({ projectID, domains }) =>
      refreshProjectArtifactConsumers(projectID, domains).catch(() => false)
    )
  ));
  return result;
}

function observeLocalProjectArtifactRevisions(payload) {
  const projects = payload?.projects;
  const scope = currentProjectArtifactScope();
  const accountEnvelope = payload?.account
    ? normalizeAccountArtifactRevisionEnvelope({
        ...payload.account,
        storageOwnerUserID: payload.account.storageOwnerUserID || payload.storageOwnerUserID
      }, scope)
    : null;
  if (accountEnvelope?.storageOwnerUserID) {
    const key = accountArtifactRevisionKey(accountEnvelope);
    const previous = accountArtifactRevisions.get(key);
    if (!previous || accountEnvelope.revision > Number(previous.revision || 0)) {
      accountArtifactRevisions.set(key, accountEnvelope);
    }
  }
  const envelopes = (Array.isArray(projects) ? projects : []).map((project) => normalizeProjectArtifactRevisionEnvelope({
    ...project,
    storageOwnerUserID: project.storageOwnerUserID || payload.storageOwnerUserID
  }, scope));
  envelopes.forEach((envelope) => {
    if (!envelope.storageOwnerUserID || !envelope.projectID) return;
    const key = [
      envelope.accountUserID,
      envelope.workspaceID,
      envelope.storageOwnerUserID,
      envelope.projectID
    ].join("::");
    const previous = projectArtifactRevisions.get(key);
    if (!previous || envelope.revision > Number(previous.revision || 0)) {
      projectArtifactRevisions.set(key, envelope);
    }
  });
  if (!accountEnvelope && !envelopes.length) return;
  broadcastForegroundSyncSignal("project-artifact-revisions", {
    workspaceID: scope.workspaceID,
    accountEnvelope,
    envelopes
  });
}

async function checkVisibleProjectArtifactRevisions() {
  if (!canRunForegroundSync()) return null;
  if (projectArtifactCheckpointPromise) {
    projectArtifactCheckpointPending = true;
    return projectArtifactCheckpointPromise;
  }
  const requestIdentity = captureAccountRequest();
  const scope = currentProjectArtifactScope();
  const projectIDs = Array.from(scope.visibleProjectIDs);
  if (!scope.accountUserID || !scope.workspaceID || (!projectIDs.length && !scope.researchVisible)) return null;
  const request = (async () => {
    const payload = await postResearch("/projects/artifacts/checkpoint", {
      projectIDs,
      includeAccountResearch: scope.researchVisible
    });
    if (!isCurrentAccountRequest(requestIdentity) || !projectArtifactRequestScopeIsCurrent(scope)) return null;
    const currentVisible = new Set(visibleProjectArtifactIDs());
    const envelopes = (payload.projects || [])
      .filter((project) => currentVisible.has(String(project?.projectID || "")))
      .map((project) => normalizeProjectArtifactRevisionEnvelope(project, scope));
    const accountResult = payload.account && researchArtifactConsumersVisible()
      ? await applyAccountArtifactRevisionEnvelope(payload.account)
      : { accepted: null, refreshResearch: false };
    requireCurrentAccountRequest(requestIdentity);
    const projectResult = await applyProjectArtifactRevisionEnvelopes(envelopes);
    requireCurrentAccountRequest(requestIdentity);
    if (accountResult.accepted || projectResult.accepted.length) {
      broadcastForegroundSyncSignal("project-artifact-revisions", {
        workspaceID: scope.workspaceID,
        accountEnvelope: accountResult.accepted,
        envelopes: projectResult.accepted
      });
    }
    return { account: accountResult, projects: projectResult };
  })().finally(() => {
    if (projectArtifactCheckpointPromise !== request) return;
    projectArtifactCheckpointPromise = null;
    if (!isCurrentAccountRequest(requestIdentity)) return;
    if (projectArtifactCheckpointPending) {
      projectArtifactCheckpointPending = false;
      startProjectArtifactCheckpointLoop({ immediate: true });
    } else {
      startProjectArtifactCheckpointLoop();
    }
  });
  projectArtifactCheckpointPromise = request;
  return request;
}

function stopProjectArtifactCheckpointLoop() {
  clearTimeout(projectArtifactCheckpointTimer);
  projectArtifactCheckpointTimer = null;
  projectArtifactCheckpointPending = false;
}

function startProjectArtifactCheckpointLoop(options = {}) {
  if (
    !canRunForegroundSync() ||
    (!visibleProjectArtifactIDs().length && !researchArtifactConsumersVisible())
  ) {
    stopProjectArtifactCheckpointLoop();
    return;
  }
  if (options.immediate) {
    clearTimeout(projectArtifactCheckpointTimer);
    projectArtifactCheckpointTimer = null;
    if (projectArtifactCheckpointPromise) {
      projectArtifactCheckpointPending = true;
      return;
    }
    void checkVisibleProjectArtifactRevisions().catch(() => {});
    return;
  }
  if (projectArtifactCheckpointTimer || projectArtifactCheckpointPromise) return;
  projectArtifactCheckpointTimer = window.setTimeout(() => {
    projectArtifactCheckpointTimer = null;
    void checkVisibleProjectArtifactRevisions().catch(() => {
      startProjectArtifactCheckpointLoop();
    });
  }, projectArtifactCheckpointDelay({ lastActivityAt: foregroundSyncLastActivityAt }));
}

function broadcastForegroundSyncSignal(type, details = {}) {
  const accountUserID = activeAccount()?.userID || "";
  if (!accountUserID) return;
  const message = {
    type,
    accountUserID,
    sourceTabID: foregroundSyncTabID,
    sentAt: Date.now(),
    ...details
  };
  foregroundSyncChannel?.postMessage(message);
  try {
    localStorage.setItem(foregroundSyncSignalKey, JSON.stringify(message));
  } catch {
    // BroadcastChannel remains the primary signal when storage is unavailable.
  }
}

async function handleForegroundSyncSignal(message) {
  const requestIdentity = captureAccountRequest();
  const accountUserID = activeAccount()?.userID || "";
  if (
    !message ||
    message.accountUserID !== accountUserID ||
    message.sourceTabID === foregroundSyncTabID
  ) return;
  if (message.type === "project-artifact-revisions") {
    if (message.workspaceID !== activeWorkspaceID) return;
    if (message.accountEnvelope) {
      await applyAccountArtifactRevisionEnvelope(message.accountEnvelope);
    }
    requireCurrentAccountRequest(requestIdentity);
    await applyProjectArtifactRevisionEnvelopes(message.envelopes || []);
    return;
  }
  if (["leader-released", "sync-invalidated"].includes(message.type)) {
    startForegroundSyncLoop({
      immediate: true,
      forceFull: message.type === "sync-invalidated"
    });
    return;
  }
  if (message.type !== "sync-complete" || isForegroundSyncLeader()) return;
  const currentEventID = Number(syncedContent?.latestEventID || 0);
  const checkpointChanged =
    Number(message.latestEventID || 0) !== currentEventID ||
    Number(message.contentMapVersion || 0) !== Number(syncedContent?.contentMapVersion || 0) ||
    String(message.entitlementFingerprint || "") !== String(syncedContent?.entitlementFingerprint || "");
  if (!checkpointChanged) return;
  const snapshot = await loadOfflineSyncSnapshot(accountUserID).catch(() => null);
  if (
    !snapshot ||
    !isCurrentAccountRequest(requestIdentity) ||
    Number(snapshot?.latestEventID || 0) < Number(message.latestEventID || 0)
  ) return;
  syncedContent = snapshot;
  foregroundSyncLastFullPullAt = Date.parse(snapshot.pulledAt || "") || Date.now();
  await refreshSyncedWorkspaceInPlace({ accountUserID });
}

function ensureForegroundSyncChannel() {
  if (foregroundSyncChannel || typeof BroadcastChannel !== "function") return;
  foregroundSyncChannel = new BroadcastChannel("permitext-sync");
  foregroundSyncChannel.addEventListener("message", (event) => {
    void handleForegroundSyncSignal(event.data);
  });
}

function scheduleForegroundSyncLeaderHeartbeat() {
  clearTimeout(foregroundSyncLeaderTimer);
  foregroundSyncLeaderTimer = window.setTimeout(() => {
    if (!canRunForegroundSync() || !claimForegroundSyncLeadership()) {
      startForegroundSyncLoop();
      return;
    }
    scheduleForegroundSyncLeaderHeartbeat();
  }, foregroundSyncSchedule.leaderHeartbeatMs);
}

function stopForegroundSyncLoop() {
  clearTimeout(foregroundSyncTimer);
  clearTimeout(foregroundSyncLeaderTimer);
  foregroundSyncTimer = null;
  foregroundSyncLeaderTimer = null;
  stopProjectArtifactCheckpointLoop();
  releaseForegroundSyncLeadership();
}

async function performForegroundSync(options = {}) {
  if (!canRunForegroundSync()) return null;
  if (foregroundSyncPromise) return foregroundSyncPromise;

  const requestIdentity = captureAccountRequest();
  const request = (async () => {
    const accountUserID = activeAccount()?.userID || "";
    const previousStatus = syncedContent?.status || "";
    const previousEventID = Number(syncedContent?.latestEventID || 0);
    await flushPendingNotebookImages();
    requireCurrentAccountRequest(requestIdentity);
    await flushPendingNotebookDrafts();
    requireCurrentAccountRequest(requestIdentity);
    const pushResult = await flushSyncOutbox({ refresh: false });
    requireCurrentAccountRequest(requestIdentity);
    if (!canRunForegroundSync()) return null;

    if (syncLoadPromise) await syncLoadPromise;
    requireCurrentAccountRequest(requestIdentity);
    let content = syncedContent;
    const forceFull = Boolean(
      options.forceFull ||
      syncResultChangesWorkspace(pushResult) ||
      !content ||
      Date.now() - foregroundSyncLastFullPullAt >= foregroundSyncSchedule.maximumStalenessMs
    );
    let checkpoint = null;
    if (!forceFull) {
      const account = activeAccount();
      checkpoint = await postJSON("/sync/checkpoint", {
        auth: { accountUserID },
        sinceEventID: Number(content?.latestEventID || 0),
        contentMapVersion: Number(content?.contentMapVersion || 0),
        entitlementFingerprint: content?.entitlementFingerprint || ""
      }, { token: account.sessionToken });
    }
    if (forceFull || syncCheckpointRequiresFullPull({
      checkpoint,
      latestEventID: content?.latestEventID,
      contentMapVersion: content?.contentMapVersion,
      entitlementFingerprint: content?.entitlementFingerprint,
      lastFullPullAt: foregroundSyncLastFullPullAt
    })) {
      content = await loadSyncedContent({ force: true, skipOutbox: true });
    }
    requireCurrentAccountRequest(requestIdentity);
    if (!canRunForegroundSync() || content?.status === "error") return content;
    if (await migrateLegacyArchivedProjects()) {
      content = await loadSyncedContent({ force: true, skipOutbox: true });
    }

    requireCurrentAccountRequest(requestIdentity);
    const nextEventID = Number(content?.latestEventID || 0);
    if (
      syncResultChangesWorkspace(pushResult) ||
      content?.status !== previousStatus ||
      nextEventID !== previousEventID
    ) {
      await refreshSyncedWorkspaceInPlace({ accountUserID });
    }
    return content;
  })().finally(() => {
    if (foregroundSyncPromise === request) foregroundSyncPromise = null;
    if (isCurrentAccountRequest(requestIdentity)) updateConnectionStatus();
  });
  foregroundSyncPromise = request;
  updateConnectionStatus();
  return request;
}

function startForegroundSyncLoop(options = {}) {
  clearTimeout(foregroundSyncTimer);
  clearTimeout(foregroundSyncLeaderTimer);
  foregroundSyncTimer = null;
  foregroundSyncLeaderTimer = null;
  if (!canRunForegroundSync()) return;
  ensureForegroundSyncChannel();
  startProjectArtifactCheckpointLoop({ immediate: options.immediate === true });
  if (!claimForegroundSyncLeadership()) {
    foregroundSyncLeaderTimer = window.setTimeout(
      () => startForegroundSyncLoop(options),
      foregroundSyncSchedule.leaderHeartbeatMs
    );
    return;
  }
  scheduleForegroundSyncLeaderHeartbeat();
  const requestIdentity = captureAccountRequest();
  foregroundSyncTimer = window.setTimeout(async () => {
    if (!isCurrentAccountRequest(requestIdentity)) return;
    try {
      await performForegroundSync({ forceFull: options.forceFull });
    } catch {
      // The durable outbox and its exponential retry retain pending local changes.
    } finally {
      if (isCurrentAccountRequest(requestIdentity)) startForegroundSyncLoop();
    }
  }, options.immediate ? 0 : foregroundSyncDelay({ lastActivityAt: foregroundSyncLastActivityAt }));
}

async function pushMutation(mutation) {
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!account) {
    throw new Error("Sign in from Account before saving from the web.");
  }
  const entry = enqueueSyncMutation(mutation, account);
  let result = await flushSyncOutbox({ refresh: true });
  requireCurrentAccountRequest(requestIdentity);
  if ((state.syncOutbox || []).some((item) => item.id === entry.id && item.queuedAt === entry.queuedAt)) {
    const followUp = await flushSyncOutbox({ refresh: true });
    requireCurrentAccountRequest(requestIdentity);
    result = {
      ...followUp,
      acceptedMutationIDs: [...result.acceptedMutationIDs, ...followUp.acceptedMutationIDs],
      rejectedMutationIDs: [...result.rejectedMutationIDs, ...followUp.rejectedMutationIDs]
    };
  }
  if (result.rejectedMutationIDs.includes(entry.recordID)) {
    const reason = result.payload?.rejectionReasons?.[entry.recordID];
    throw new Error(reason?.message || "The server has a newer version of this record. Review the synced copy before retrying.");
  }
  if (!result.acceptedMutationIDs.includes(entry.recordID)) {
    throw new Error("This change remains queued for sync.");
  }
  return result.payload;
}

function savedMutationForReader(reader) {
  return savedMutationForSection({
    codeVersion: reader.codeVersion || syncCodeVersionForPrefix(reader.codePrefix),
    codePrefix: reader.codePrefix || "BC",
    chapterID: reader.chapterID || "",
    chapterNumber: reader.chapterNumber || "",
    sectionID: reader.sectionID,
    sectionNumber: reader.sectionNumber,
    title: reader.title
  });
}

function savedMutationForSection(section) {
  const account = activeAccount();
  const now = new Date().toISOString();
  return {
    savedItem: savedRecordForSection(section, account?.userID || "local-web", now)
  };
}

function savedRecordForSection(section, userID = "local-web", updatedAt = new Date().toISOString()) {
  const codePrefix = section.codePrefix || "BC";
  const codeVersion = syncCodeVersion(section.codeVersion || syncCodeVersionForPrefix(codePrefix));
  const blockID = normalizeAnnotationBlockID(section.blockID);
  return {
    id: blockID
      ? `web-saved-${safeAnnotationIDPart(codeVersion)}-${section.sectionID}-${safeAnnotationIDPart(blockID)}`
      : `web-saved-${section.sectionID}`,
    userID,
    codeVersion,
    codePrefix,
    chapterID: section.chapterID || "",
    chapterNumber: section.chapterNumber || "",
    sectionID: Number(section.sectionID),
    blockID,
    sectionNumber: section.sectionNumber,
    title: section.title,
    updatedAt
  };
}

function savedEvidenceKey(value, codeVersion = "") {
  const record = value && typeof value === "object" ? value : { sectionID: value, codeVersion };
  const sectionID = String(record.sectionID || record.savedSectionID || record.itemID || "");
  const version = syncCodeVersion(record.codeVersion || codeVersion || defaultSyncCodeVersion);
  const blockID = normalizeAnnotationBlockID(record.blockID || record.anchorID || record.contentBlockID);
  return `${version}:${sectionID}:${blockID}`;
}

function savedCodeGroupKey(item) {
  const prefix = String(item?.codePrefix || item?.code || "BC").toUpperCase();
  const version = syncCodeVersion(item?.codeVersion || syncCodeVersionForPrefix(prefix));
  return `${prefix}::${version}`;
}

function projectEvidenceCount(projectSections, project, savedItems = currentContentSummary().savedItems || []) {
  const savedTargets = new Set((savedItems || []).map((item) => savedEvidenceKey(item)));
  return new Set((projectSections || [])
    .filter((item) => projectSectionBelongsToProject(item, project))
    .map((item) => savedEvidenceKey(item))
    .filter((key) => key && savedTargets.has(key))).size;
}

function projectSectionRecordForSection(project, sectionPayload) {
  const account = activeAccount();
  const now = new Date().toISOString();
  const sectionID = String(sectionPayload.sectionID || "");
  const blockID = normalizeAnnotationBlockID(sectionPayload.blockID);
  const folderClientID = project.clientID || project.id || project.localFolderID || "";
  return {
    id: `web-project-section-${folderClientID}-${sectionID}${blockID ? `-${safeAnnotationIDPart(blockID)}` : ""}`,
    userID: account?.userID || "local-web",
    codeVersion: syncCodeVersion(
      sectionPayload.codeVersion || syncCodeVersionForPrefix(sectionPayload.codePrefix)
    ),
    codePrefix: sectionPayload.codePrefix || "BC",
    chapterID: sectionPayload.chapterID || "",
    chapterNumber: sectionPayload.chapterNumber || "",
    folderClientID,
    folderType: folderType(project),
    localFolderID: numericLocalFolderID(project) || null,
    sectionID: Number(sectionID),
    blockID,
    blockLabel: sectionPayload.blockLabel || "",
    sectionNumber: sectionPayload.sectionNumber || "",
    title: sectionPayload.title || "Section",
    scope: "manual",
    updatedAt: now
  };
}

function projectSectionMutationForSection(project, sectionPayload) {
  const record = projectSectionRecordForSection(project, sectionPayload);
  return {
    projectSection: {
      id: record.id,
      userID: record.userID,
      codeVersion: record.codeVersion,
      folderClientID: record.folderClientID,
      folderType: record.folderType,
      localFolderID: record.localFolderID,
      sectionID: record.sectionID,
      blockID: record.blockID || null,
      scope: record.scope,
      updatedAt: record.updatedAt
    }
  };
}

function deletedProjectSectionMutationForItem(project, item) {
  const now = new Date().toISOString();
  const record = projectSectionRecordForSection(project, item);
  return {
    projectSection: {
      id: item.projectSectionID || item.id || record.id,
      userID: activeAccount()?.userID || item.userID || "local-web",
      codeVersion: syncCodeVersion(item.codeVersion),
      folderClientID: item.folderClientID || record.folderClientID,
      folderType: item.folderType || record.folderType,
      localFolderID: item.localFolderID || record.localFolderID,
      sectionID: Number(item.sectionID || item.savedSectionID || item.itemID),
      blockID: normalizeAnnotationBlockID(item.blockID) || null,
      scope: item.scope || record.scope,
      updatedAt: now,
      deletedAt: now
    }
  };
}

function savedItemForSection(section) {
  const sectionKey = savedEvidenceKey(section);
  return [...(state.localSavedItems || []), ...(syncedContent?.summary?.savedItems || [])]
    .filter((item) => savedEvidenceKey(item) === sectionKey)
    .sort((left, right) => Date.parse(right.updatedAt || 0) - Date.parse(left.updatedAt || 0))[0] || null;
}

function deletedSavedMutationForSection(section, existingRecord = null) {
  const account = activeAccount();
  const now = new Date().toISOString();
  const existing = existingRecord || savedItemForSection(section) || {};
  return {
    savedItem: {
      id: existing.id || savedRecordForSection(section, account?.userID || existing.userID || "local-web", now).id,
      userID: account?.userID || existing.userID || "local-web",
      codeVersion: syncCodeVersion(existing.codeVersion || section.codeVersion),
      sectionID: Number(section.sectionID),
      blockID: normalizeAnnotationBlockID(existing.blockID || section.blockID) || null,
      sectionNumber: section.sectionNumber || existing.sectionNumber || "",
      title: section.title || existing.title || "Section",
      updatedAt: now,
      deletedAt: now
    }
  };
}

function projectColor(project) {
  // `colorHex` is the native iOS storage field and the canonical sync value.
  // Legacy web aliases remain as fallbacks for records created before sync.
  return project?.colorHex || project?.color || project?.tintColor || projectColorOptions[0];
}

function folderType(folder) {
  return String(folder?.folderType || folder?.type || "project").toLowerCase() === "reference"
    ? "reference"
    : "project";
}

function folderTypeLabel(folder) {
  return folderType(folder) === "reference" ? "Saved collection" : "Project";
}

function folderRecordCountLabel(folders = []) {
  const projectCount = folders.filter((folder) => folderIsProject(folder)).length;
  const collectionCount = folders.length - projectCount;
  return [
    projectCount ? `${projectCount} ${projectCount === 1 ? "Project" : "Projects"}` : "",
    collectionCount ? `${collectionCount} saved ${collectionCount === 1 ? "collection" : "collections"}` : ""
  ].filter(Boolean).join(" and ") || "0 records";
}

function folderIsProject(folder) {
  return folderType(folder) === "project";
}

function readableProjectName(project) {
  const name = String(project?.name || project?.title || "Project").trim() || "Project";
  if (name !== name.toLocaleUpperCase() || name === name.toLocaleLowerCase()) return name;
  return name.toLocaleLowerCase().replace(/(^|[\s-])\p{L}/gu, (match) => match.toLocaleUpperCase());
}

function projectForegroundColor(color) {
  const match = String(color || "").trim().match(/^#([0-9a-f]{6})$/i);
  if (!match) return "#ffffff";
  const channels = [0, 2, 4].map((offset) => parseInt(match[1].slice(offset, offset + 2), 16) / 255);
  const [red, green, blue] = channels.map((channel) =>
    channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4
  );
  const luminance = (0.2126 * red) + (0.7152 * green) + (0.0722 * blue);
  return luminance > 0.179 ? "#111111" : "#ffffff";
}

function numericLocalFolderID(project) {
  const value = Number(project?.localFolderID);
  return Number.isInteger(value) && value > 0 ? value : 0;
}

function normalizeProjectStructuredFact(fact) {
  if (!fact || typeof fact !== "object") return null;
  const key = String(fact.key || fact.id || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  const label = String(fact.label || "").trim();
  const value = String(fact.value || "").trim();
  if (!key || !label || !value) return null;
  const status = projectStructuredFactStatuses.has(String(fact.status || "").toLowerCase())
    ? String(fact.status).toLowerCase()
    : "stated";
  return {
    id: String(fact.id || `project-fact:${key}`),
    key,
    label,
    value,
    status,
    source: String(fact.source || "description"),
    sourceText: String(fact.sourceText || "").trim().slice(0, 500),
    updatedAt: fact.updatedAt || null
  };
}

function projectStructuredFacts(project) {
  return (Array.isArray(project?.structuredFacts) ? project.structuredFacts : [])
    .map(normalizeProjectStructuredFact)
    .filter(Boolean);
}

const projectStructuredFactGroups = [
  {
    key: "buildingCode",
    label: "Building & code",
    fields: [
      { key: "occupancy", label: "Occupancy" },
      { key: "construction-type", label: "Construction Type" },
      { key: "stories-above-grade", label: "Stories Above Grade" },
      { key: "levels-below-grade", label: "Levels Below Grade" },
      { key: "building-height", label: "Building Height" },
      { key: "sprinkler-protection", label: "Sprinkler Protection" },
      { key: "project-status", label: "Project Status" },
      { key: "work-filing-type", label: "Work / Filing Type" },
      { key: "code-basis", label: "Code Basis" },
      { key: "building-area", label: "Building Area" },
      { key: "building-count", label: "Number of Buildings" },
      { key: "residential-units", label: "Residential Units" },
      { key: "total-units", label: "Total Units" },
      { key: "year-built", label: "Year Built" },
      { key: "years-altered", label: "Year(s) Altered" },
      { key: "building-class", label: "Building Class" }
    ]
  },
  {
    key: "zoning",
    label: "Zoning",
    fields: [
      { key: "address", label: "Address", projectAddress: true },
      { key: "bbl", label: "BBL" },
      { key: "borough", label: "Borough" },
      { key: "block", label: "Block" },
      { key: "tax-lots", label: "Tax Lot(s)" },
      { key: "zip-code", label: "ZIP Code" },
      { key: "tax-lot-area", label: "Tax Lot Area" },
      { key: "land-use-code", label: "Land Use Code" },
      { key: "zoning-lot-composition", label: "Zoning Lot Composition" },
      { key: "zoning-districts", label: "Zoning District(s)" },
      { key: "commercial-overlays", label: "Commercial Overlay(s)" },
      { key: "special-purpose-district", label: "Special Purpose District(s)" },
      { key: "zoning-map", label: "Zoning Map" },
      { key: "community-district", label: "Community District" },
      { key: "zoning-lot-area", label: "Zoning Lot Area" },
      { key: "lot-width", label: "Lot Width" },
      { key: "lot-depth", label: "Lot Depth" },
      { key: "lot-type", label: "Lot Type" },
      { key: "street-frontages", label: "Street Frontage(s)" },
      { key: "transit-zone", label: "Transit Zone (Legacy Record)" },
      ...nycMappedFactFields
    ]
  }
];

// Presentation groups retain the canonical fact keys used by sync, imports,
// Assistant context and report exports.
function projectFactPresentationGroups(groups = projectStructuredFactGroups) {
  const fields = groups.flatMap(group => group.fields);
  const property = new Set(["address", "bbl", "borough", "block", "tax-lots", "zip-code", "tax-lot-area", "land-use-code", "community-district"]);
  const work = new Set(["project-status", "work-filing-type", "code-basis"]);
  const building = new Set(groups.find(group => group.key === "buildingCode")?.fields.map(field => field.key));
  const special = new Set(["special-purpose-district", ...nycMappedFactFields.map(field => field.key)]);
  const sections = [
    { key: "property", label: "Property", fields: [] },
    { key: "building", label: "Building", fields: [] },
    { key: "work", label: "Work & code basis", fields: [] },
    { key: "zoning", label: "Zoning", fields: [] },
    { key: "designations", label: "Special designations", fields: [] }
  ];
  for (const field of fields) {
    const index = property.has(field.key) ? 0 : work.has(field.key) ? 2 : building.has(field.key) ? 1 : special.has(field.key) ? 4 : 3;
    sections[index].fields.push(field);
  }
  return sections;
}

const projectStructuredFactAliases = new Map([
  ["stories", ["stories-above-grade", "Stories Above Grade"]],
  ["sprinkler-status", ["sprinkler-protection", "Sprinkler Protection"]],
  ["work-type", ["work-filing-type", "Work / Filing Type"]]
]);

function migratedProjectStructuredFacts(project) {
  const facts = projectStructuredFacts(project);
  const migrated = [];
  const seenKeys = new Set();
  const canonicalKeys = new Set(facts.filter((fact) => !projectStructuredFactAliases.has(fact.key)).map((fact) => fact.key));
  facts.forEach((fact) => {
    const [key, label] = projectStructuredFactAliases.get(fact.key) || [fact.key, fact.label];
    if (key !== fact.key && canonicalKeys.has(key)) return;
    if (seenKeys.has(key)) return;
    seenKeys.add(key);
    migrated.push({
      ...fact,
      id: key === fact.key ? fact.id : `project-fact:${key}`,
      key,
      label,
      status: fact.status,
      source: fact.source,
      sourceText: fact.sourceText
    });
  });
  return migrated;
}

function projectMutationForRecord(project, accountOverride = null) {
  const account = accountOverride || activeAccount();
  const now = project.updatedAt || new Date().toISOString();
  const color = projectColor(project);
  return {
    project: {
      id: project.id,
      clientID: project.clientID || project.id,
      localFolderID: numericLocalFolderID(project),
      userID: account?.userID || "local-web",
      codeVersion: syncCodeVersion(project.codeVersion),
      name: project.name || "Project",
      title: project.title || project.name || "Project",
      address: project.address || "",
      description: project.description || "",
      structuredFacts: projectStructuredFacts(project),
      recordsChecklist: project.recordsChecklist || [],
      folderType: folderType(project),
      color,
      colorHex: color,
      sortOrder: Number.isFinite(Number(project.sortOrder)) ? Number(project.sortOrder) : 0,
      sortMode: project.sortMode || "Code order",
      createdAt: project.createdAt || now,
      updatedAt: now,
      archivedAt: project.archivedAt || null
    }
  };
}

function deletedProjectMutationForRecord(project, accountOverride = null) {
  const account = accountOverride || activeAccount();
  const now = new Date().toISOString();
  return {
    project: {
      ...projectMutationForRecord(project, account).project,
      updatedAt: now,
      deletedAt: now
    }
  };
}

function projectRecordsFromMutations(mutations = []) {
  return summarizeMutations(mutations).projects;
}

function projectRecordID(project) {
  return String(project?.id || project?.clientID || project?.localFolderID || "");
}

function projectSortOrder(project) {
  const value = Number(project?.sortOrder);
  return Number.isFinite(value) && value >= 0 ? value : 0;
}

function compareProjectOrder(left, right) {
  const orderDifference = projectSortOrder(left) - projectSortOrder(right);
  if (orderDifference) return orderDifference;
  const createdDifference = Date.parse(left?.createdAt || 0) - Date.parse(right?.createdAt || 0);
  if (Number.isFinite(createdDifference) && createdDifference) return createdDifference;
  return String(left?.name || left?.title || "").localeCompare(
    String(right?.name || right?.title || ""),
    undefined,
    { numeric: true, sensitivity: "base" }
  );
}

function archivedProjectIDSet() {
  state.archivedProjectIDs = Array.isArray(state.archivedProjectIDs) ? state.archivedProjectIDs.map(String) : [];
  return new Set(state.archivedProjectIDs);
}

function projectIsArchived(project) {
  return Boolean(project?.archivedAt) || archivedProjectIDSet().has(projectRecordID(project));
}

async function migrateLegacyArchivedProjects() {
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!account || syncedContent?.status !== "connected") return false;
  const legacyArchivedIDs = archivedProjectIDSet();
  const projects = visibleProjectRecords(syncedContent.summary?.projects || [])
    .filter((project) => legacyArchivedIDs.has(projectRecordID(project)) && !project.archivedAt);
  if (!projects.length) return false;

  for (const project of projects) {
    const archivedAt = new Date().toISOString();
    const archivedProject = { ...project, archivedAt, updatedAt: archivedAt };
    const id = projectRecordID(project);
    state.localProjects = [
      ...(state.localProjects || []).filter((item) => projectRecordID(item) !== id),
      archivedProject
    ];
    saveWorkspaceState();
    try {
      await pushMutation(projectMutationForRecord(archivedProject, account));
      requireCurrentAccountRequest(requestIdentity);
      state.localProjects = (state.localProjects || []).filter((item) => projectRecordID(item) !== id);
      saveWorkspaceState();
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
      return false;
    }
  }
  return true;
}

function visibleProjectRecords(syncedProjects = []) {
  const byIdentity = new Map();
  syncedProjects.forEach((project) => {
    const identity = projectDetailKey(project);
    if (identity) byIdentity.set(identity, project);
  });
  const clearRecords = currentBulkClearRecords();
  (state.localProjects || [])
    .filter((project) => recordSurvivesBulkClear(project, clearRecords, ["folders"]))
    .forEach((project) => {
      const identity = projectDetailKey(project);
      // Keep offline edits visible only while they are actually newer. A
      // synced project wins ties and any legacy undated browser overlay, so
      // names and colors cannot drift after another device updates them.
      if (identity) mergeNewestRecord(byIdentity, identity, project);
    });
  return Array.from(byIdentity.values())
    .filter((project) => !project.deletedAt)
    .sort(compareProjectOrder);
}

function activeProjectRecords(syncedProjects = []) {
  return visibleProjectRecords(syncedProjects).filter((project) =>
    !projectIsArchived(project) && folderIsProject(project)
  );
}

function activeFolderRecords(syncedProjects = []) {
  return visibleProjectRecords(syncedProjects).filter((project) => !projectIsArchived(project));
}

function archivedProjectRecords(syncedProjects = []) {
  return visibleProjectRecords(syncedProjects).filter(projectIsArchived);
}

function nextProjectName() {
  const existing = visibleProjectRecords(projectRecordsFromMutations(syncedContent?.mutations || []));
  const usedNumbers = new Set();
  existing.forEach((project) => {
    const match = String(project.name || project.title || "").trim().match(/^P(\d+)$/i);
    if (match) usedNumbers.add(Number(match[1]));
  });
  let index = 1;
  while (usedNumbers.has(index)) index += 1;
  return `P${index}`;
}

function nextProjectSortOrder() {
  const projects = activeFolderRecords(currentContentSummary().projects || []);
  return projects.reduce((maximum, project) => Math.max(maximum, projectSortOrder(project)), -1) + 1;
}

async function createProjectFolder(details = {}) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const requestedType = String(details.folderType || "project").toLowerCase() === "reference"
    ? "reference"
    : "project";
  if (!hasCapability("projects")) {
    void presentPlanLimitNotice("Projects require Pro", "Upgrade to Pro to create Project workspaces and organize saved code by job.");
    return null;
  }
  const now = new Date().toISOString();
  const localFolderID = Date.now();
  const id = `web-project-${localFolderID.toString(36)}`;
  const fallbackName = nextProjectName();
  const name = String(details.name || "").trim() || fallbackName;
  const description = String(details.description || "").trim();
  const address = String(details.address || "").trim();
  const type = requestedType;
  const account = activeAccount();
  const project = {
    id,
    clientID: id,
    localFolderID,
    userID: account?.userID || "local-web",
    codeVersion: defaultSyncCodeVersion,
    name,
    title: name,
    address,
    description,
    structuredFacts: projectStructuredFacts({ structuredFacts: details.structuredFacts }),
    folderType: type,
    color: details.color || projectColorOptions[0],
    sortOrder: nextProjectSortOrder(),
    sortMode: "Code order",
    createdAt: now,
    updatedAt: now
  };
  state.localProjects = [...(state.localProjects || []), project];
  saveWorkspaceState();

  if (!account) return project;

  try {
    await pushMutation(projectMutationForRecord(project, account));
    requireCurrentAccountRequest(requestIdentity);
    state.localProjects = (state.localProjects || []).filter((item) => item.id !== project.id);
    saveWorkspaceState();
  } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
    // The local project and queued mutation remain available while sync recovers.
  }
  requireCurrentAccountRequest(requestIdentity);
  return project;
}

async function persistProjectOrder(projects, paneID) {
  if (!hasCapability("projects")) return;
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  const now = Date.now();
  const updates = projects.map((project, index) => ({
    ...project,
    sortOrder: index,
    updatedAt: new Date(now + index).toISOString()
  }));
  const updateIDs = new Set(updates.map(projectRecordID));
  state.localProjects = [
    ...(state.localProjects || []).filter((project) => !updateIDs.has(projectRecordID(project))),
    ...updates
  ];
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
  requireCurrentAccountRequest(requestIdentity);
  if (!account) return;
  const syncedIDs = new Set();
  for (const project of updates) {
    if (project.sharedOnly) continue;
    try {
      await pushMutation(projectMutationForRecord(project, account));
      requireCurrentAccountRequest(requestIdentity);
      syncedIDs.add(projectRecordID(project));
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
    }
  }
  if (!syncedIDs.size) return;
  state.localProjects = (state.localProjects || []).filter(
    (project) => !syncedIDs.has(projectRecordID(project))
  );
  saveWorkspaceState();
}

async function updateProjectFolder(project, details = {}) {
  if (!hasCapability("projects")) {
    void presentPlanLimitNotice("Projects require Pro", "Upgrade to Pro to edit Projects and saved collections. Existing work is preserved.");
    return false;
  }
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const id = projectRecordID(project);
  if (!id) return;
  // Independent Context and Facts editors patch the latest Project record.
  project = visibleProjectRecords(currentContentSummary().projects || []).find(item => projectDetailMatches(item, project)) || project;
  const nextFolderType = details.folderType ? folderType(details) : folderType(project);
  if (nextFolderType === "project" && folderType(project) === "reference" && !hasCapability("projects")) {
    void presentPlanLimitNotice("Projects require Pro", "Upgrade to convert this saved collection into a Project workspace.");
    return false;
  }
  const now = new Date(Math.max(Date.now(), (Date.parse(project.updatedAt || "") || 0) + 1)).toISOString();
  const name = String(details.name || "").trim() || project.name || project.title || "Project";
  const color = details.color || projectColor(project);
  const hasAddress = Object.prototype.hasOwnProperty.call(details, "address");
  const hasDescription = Object.prototype.hasOwnProperty.call(details, "description");
  const hasStructuredFacts = Object.prototype.hasOwnProperty.call(details, "structuredFacts");
  const address = String(hasAddress ? details.address : project.address || "").trim();
  const updated = {
    ...project,
    id: project.id || id,
    clientID: project.clientID || id,
    localFolderID: project.localFolderID || id,
    codeVersion: syncCodeVersion(project.codeVersion),
    name,
    title: name,
    address,
    description: String(hasDescription ? details.description : project.description || "").trim(),
    structuredFacts: hasStructuredFacts
      ? projectStructuredFacts({ structuredFacts: details.structuredFacts })
      : projectStructuredFacts(project),
    recordsChecklist: Object.prototype.hasOwnProperty.call(details, "recordsChecklist")
      ? normalizeRecordsChecklist(details.recordsChecklist) : project.recordsChecklist || [],
    folderType: nextFolderType,
    color,
    colorHex: color,
    tintColor: color,
    updatedAt: now
  };
  const localProjects = state.localProjects || [];
  const localIndex = localProjects.findIndex((item) => projectRecordID(item) === id);
  const account = activeAccount();
  const nextProjects = [...localProjects];

  if (localIndex >= 0) {
    nextProjects[localIndex] = { ...nextProjects[localIndex], ...updated };
  } else {
    nextProjects.push(updated);
  }
  state.localProjects = nextProjects;
  const localRevision = JSON.stringify(nextProjects.find(item => projectRecordID(item) === id));
  setOpenProjectDetails(openProjectDetails().map((detail) => projectDetailMatches(project, detail) ? projectIdentity(updated) : detail));
  saveWorkspaceState();
  refreshOpenProjectPaneTheme(updated);
  let projectUpdatePersisted = !account;

  if (account) {
    try {
      await pushMutation(projectMutationForRecord(updated, account));
      requireCurrentAccountRequest(requestIdentity);
      state.localProjects = (state.localProjects || []).filter((item) =>
        projectRecordID(item) !== id || JSON.stringify(item) !== localRevision);
      saveWorkspaceState();
      projectUpdatePersisted = true;
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
      // Keep the local edit visible while the durable sync queue recovers.
    }
  }
  requireCurrentAccountRequest(requestIdentity);
  const updatedProjectID = projectDetailKey(projectIdentity(updated));
  if (visibleProjectArtifactIDs().includes(updatedProjectID)) {
    refreshMountedResearchProjectContext(updatedProjectID);
    if (projectUpdatePersisted && account) {
      await refreshProjectSourceConsumers([updatedProjectID], {
        refreshNotebookFoundation: true,
        refreshNotebookReferences: true,
        refreshReportSources: true
      });
      requireCurrentAccountRequest(requestIdentity);
    }
  }
  return true;
}

function workspaceSavedEvidenceKeys(summary = currentContentSummary()) {
  const project = workspaceProject(summary.projects || []);
  return new Set(project ? (summary.projectSections || [])
    .filter((item) => projectSectionBelongsToProject(item, project))
    .map((item) => savedEvidenceKey(item)) : []);
}

function isSectionSaved(section, codeVersion = "", savedKeys = null) {
  return (savedKeys || workspaceSavedEvidenceKeys()).has(savedEvidenceKey(section, codeVersion));
}

function savedSectionRecord(section, codeVersion = "") {
  const sectionKey = savedEvidenceKey(section, codeVersion);
  const rawSectionID = String(section && typeof section === "object" ? section.sectionID : section);
  const localRecord = [...(state.localSavedItems || [])].reverse()
    .find((item) => savedEvidenceKey(item) === sectionKey);
  if (localRecord) return localRecord.deletedAt ? null : localRecord;
  const localSavedSectionKeys = (state.localSavedSectionIDs || []).map(String);
  if (localSavedSectionKeys.includes(sectionKey)) {
    return {
      sectionID: rawSectionID,
      codeVersion: syncCodeVersion(codeVersion || section?.codeVersion || defaultSyncCodeVersion),
      blockID: ""
    };
  }
  if (
    syncCodeVersion(codeVersion || section?.codeVersion || defaultSyncCodeVersion) === defaultSyncCodeVersion &&
    localSavedSectionKeys.includes(rawSectionID)
  ) return { sectionID: rawSectionID, codeVersion: defaultSyncCodeVersion, blockID: "" };
  const savedItems = syncedContent?.summary?.savedItems || [];
  return savedItems.find((item) => savedEvidenceKey(item) === sectionKey) || null;
}

function setLocalSectionSaved(section, saved, codeVersion = defaultSyncCodeVersion) {
  requirePrivateWorkspaceWritable();
  const record = section && typeof section === "object" ? section : { sectionID: section, codeVersion };
  const sectionKey = String(record.sectionID || "");
  if (!sectionKey) return;
  const current = new Set((state.localSavedSectionIDs || []).map(String));
  const exactKey = savedEvidenceKey(record, codeVersion);
  if (saved) current.add(exactKey);
  else {
    current.delete(exactKey);
    if (!normalizeAnnotationBlockID(record.blockID)) current.delete(sectionKey);
  }
  state.localSavedSectionIDs = Array.from(current);
  saveWorkspaceState();
}

let pendingProjectChoice = null;
let cancelPendingProjectChoice = null;

async function chooseProjectForSaving() {
  if (workspaceProject()) return workspaceProject();
  if (!hasCapability("projects")) return null;
  if (pendingProjectChoice) return pendingProjectChoice;
  const identity = captureAccountRequest();
  const returnFocus = document.activeElement;
  const backdrop = document.createElement("div");
  backdrop.className = "web-warning-backdrop";
  const dialog = document.createElement("section");
  dialog.className = "web-warning-dialog project-save-dialog";
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-modal", "true");
  dialog.setAttribute("aria-label", "Choose a Project");
  const title = document.createElement("h2");
  title.textContent = "Choose a Project";
  const list = document.createElement("div");
  list.className = "project-save-options";
  const status = document.createElement("p");
  status.setAttribute("role", "status");
  const form = document.createElement("form");
  form.hidden = true;
  const input = document.createElement("input");
  input.placeholder = "Project name";
  input.setAttribute("aria-label", "Project name");
  input.required = true;
  const create = document.createElement("button");
  create.type = "submit";
  create.textContent = "Create Project";
  form.append(input, create);
  const newProject = document.createElement("button");
  newProject.type = "button";
  newProject.textContent = "New Project…";
  newProject.addEventListener("click", () => {
    form.hidden = false;
    newProject.hidden = true;
    input.focus();
  });
  const cancel = document.createElement("button");
  cancel.type = "button";
  cancel.textContent = "Cancel";
  dialog.append(title, list, newProject, form, status, cancel);
  backdrop.append(dialog);
  let resolveChoice;
  let busy = false;
  let settled = false;
  const setBusy = value => {
    busy = value;
    dialog.querySelectorAll("button, input").forEach(control => { control.disabled = value; });
  };
  const choice = new Promise(resolve => { resolveChoice = resolve; });
  pendingProjectChoice = choice;
  const finish = (project) => {
    if (settled) return;
    settled = true;
    cancelPendingProjectChoice = null;
    backdrop.remove();
    if (pendingProjectChoice === choice) pendingProjectChoice = null;
    resolveChoice(project);
    if (returnFocus?.isConnected && isCurrentAccountRequest(identity)) returnFocus.focus({ preventScroll: true });
  };
  cancelPendingProjectChoice = () => finish(null);
  const select = async (project) => {
    if (settled) return;
    setBusy(true);
    try {
      requireCurrentAccountRequest(identity);
      reconcileProjectWorkspaces();
      const live = activeFolderRecords(currentContentSummary().projects || []).find(item =>
        folderIsProject(item) && projectDetailMatches(item, project));
      if (!live) throw new Error("That Project is no longer available.");
      const linked = workspaceRegistry.workspaces.find(item => item.projectID === projectRecordID(live));
      if (!linked || !await switchWorkspace(linked.id, { focus: false })) {
        finish(null);
        return;
      }
      requireCurrentAccountRequest(identity);
      finish(workspaceProject());
    } catch (error) {
      if (!isCurrentAccountRequest(identity)) { finish(null); return; }
      status.textContent = error.message || "The Project could not be opened. Please try again.";
    } finally {
      if (!settled) setBusy(false);
    }
  };
  activeFolderRecords(currentContentSummary().projects || []).filter(folderIsProject).forEach(project => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = project.name || project.title || "Untitled Project";
    button.addEventListener("click", () => { if (!busy) void select(project); });
    list.append(button);
  });
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (busy || settled || !input.value.trim()) return;
    setBusy(true);
    try {
      requireCurrentAccountRequest(identity);
      const project = await createProjectFolder({ name: input.value.trim(), folderType: "project" });
      requireCurrentAccountRequest(identity);
      if (project && !settled) await select(project);
    } catch (error) {
      if (!isCurrentAccountRequest(identity)) { finish(null); return; }
      status.textContent = error.message || "The Project could not be created. Please try again.";
    } finally { if (!settled) setBusy(false); }
  });
  cancel.addEventListener("click", () => { if (!busy) finish(null); });
  backdrop.addEventListener("click", event => { if (event.target === backdrop && !busy) finish(null); });
  dialog.addEventListener("keydown", event => {
    if (event.key === "Escape" && !busy) { event.preventDefault(); finish(null); }
    else trapWebModalFocus(dialog, event);
  });
  document.body.append(backdrop);
  (list.querySelector("button") || newProject).focus();
  return choice;
}

function bookmarkActionLabel(saved) {
  if (!saved) return "Save passage";
  const project = workspaceProject();
  return project
    ? `Remove from project: ${project.name || project.title || "Untitled project"}`
    : "Remove from Evidence";
}

function showBookmarkUndo(payload, projects, requestIdentity, workspaceID, paneID) {
  const panel = track.querySelector(`[data-pane-id="${CSS.escape(paneID || '')}"]`);
  if (!panel || panel.classList.contains("section-detail-panel")) return;
  const notice = document.createElement("div");
  notice.className = "bookmark-undo-notice";
  notice.setAttribute("role", "status");
  let expiry;
  const undo = document.createElement("button");
  undo.type = "button";
  undo.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/></svg><span>Undo</span>';
  undo.addEventListener("click", async () => {
    if (!isCurrentAccountRequest(requestIdentity) || activeWorkspaceID !== workspaceID) { notice.remove(); return; }
    window.clearTimeout(expiry);
    notice.style.animation = "none";
    undo.disabled = true;
    try {
      const restored = await persistSectionBookmark(payload, true);
      if (restored === false) { undo.disabled = false; return; }
      for (const project of projects) {
        requireCurrentAccountRequest(requestIdentity);
        await persistSectionInProject(project, payload);
      }
      syncReaderNoteBookmarkButtons(payload.sectionID, true, payload.codeVersion);
      await refreshOpenSavedPanes();
      notice.remove();
    } catch {
      undo.title = "Could not restore. Try again.";
      undo.disabled = false;
    }
  });
  notice.append(undo);
  let tray = panel.querySelector(':scope > .bookmark-undo-tray');
  if (!tray) { tray = document.createElement('div'); tray.className = 'bookmark-undo-tray'; panel.append(tray); }
  tray.append(notice);
  expiry = window.setTimeout(() => notice.remove(), 10000);
}

async function persistSectionBookmark(sectionPayload, saved, options = {}) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  let targetProject = workspaceProject();
  const existingRecord = savedItemForSection(sectionPayload);
  const undoWorkspaceID = activeWorkspaceID;
  const undoPaneID = options.undoPaneID || document.activeElement?.closest(".workspace-panel")?.dataset.paneId || primarySavedPaneID();
  const undoProjects = !saved ? (currentContentSummary().projects || []).filter((project) =>
    (!targetProject || projectRecordID(project) === projectRecordID(targetProject)) &&
    (currentContentSummary().projectSections || []).some((link) =>
      savedEvidenceKey(link) === savedEvidenceKey(sectionPayload) && projectSectionBelongsToProject(link, project))) : [];
  const offerUndo = () => showBookmarkUndo({ ...sectionPayload }, undoProjects, requestIdentity, undoWorkspaceID, undoPaneID);

  if (!saved && targetProject) {
    const links = (currentContentSummary().projectSections || []).filter((item) =>
      savedEvidenceKey(item) === savedEvidenceKey(sectionPayload) && projectSectionBelongsToProject(item, targetProject));
    for (const link of links) await removeSectionFromProject(targetProject, link);
    if (links.length) offerUndo();
    return true;
  }
  if (
    saved &&
    !hasCapability("saved-work")
  ) {
    preservePendingProSave(sectionPayload);
    void presentPlanLimitNotice(
      "Saving requires Pro",
      "Upgrade to Pro to save this section. Your place in the code will be kept."
    ).then(accepted => { if (!accepted) clearPendingProSave(); });
    return false;
  }
  if (saved) {
    targetProject = targetProject || await chooseProjectForSaving();
    requireCurrentAccountRequest(requestIdentity);
    if (!targetProject || !workspaceProject() ||
        projectRecordID(targetProject) !== projectRecordID(workspaceProject())) return false;
  }
  if (syncCodeVersion(sectionPayload.codeVersion) === defaultSyncCodeVersion) {
    setLocalSectionSaved(sectionPayload, saved, sectionPayload.codeVersion);
  }
  const sectionKey = savedEvidenceKey(sectionPayload);
  const record = saved
    ? savedRecordForSection(sectionPayload, activeAccount()?.userID || "local-web")
    : {
        ...savedRecordForSection(sectionPayload, activeAccount()?.userID || "local-web"),
        ...(existingRecord || {}),
        updatedAt: new Date().toISOString()
      };
  const localRecord = saved ? record : { ...record, deletedAt: record.updatedAt };
  const mutation = saved
    ? savedMutationForSection(sectionPayload)
    : deletedSavedMutationForSection(sectionPayload, existingRecord);
  state.localSavedItems = [
    ...(state.localSavedItems || []).filter((item) => savedEvidenceKey(item) !== sectionKey),
    localRecord
  ];
  saveWorkspaceState();
  if (!saved) {
    syncReaderNoteBookmarkButtons(sectionPayload.sectionID, false, sectionPayload.codeVersion);
  }
  if (!saved && options.removeProjectLinks !== false) {
    await removeSectionFromAllProjects(sectionPayload, {
      refreshPanes: options.refreshProjectPanes !== false
    });
    requireCurrentAccountRequest(requestIdentity);
  }
  // Persist the outbox before any rendering/network await can interrupt this save.
  if (account) enqueueSyncMutation(mutation, account);
  if (saved && targetProject) await persistSectionInProject(targetProject, sectionPayload);
  if (options.refreshSavedPanes !== false) void refreshOpenSavedPanes().catch(() => {});
  requireCurrentAccountRequest(requestIdentity);
  if (!account) {
    if (!saved) offerUndo();
    return true;
  }
  try {
    await pushMutation(mutation);
    requireCurrentAccountRequest(requestIdentity);
    state.localSavedItems = (state.localSavedItems || []).filter((item) => savedEvidenceKey(item) !== sectionKey);
    saveWorkspaceState();
  } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
    // Keep the local record and queued mutation available while sync recovers.
  }
  requireCurrentAccountRequest(requestIdentity);
  if (!saved) offerUndo();
  return true;
}

async function persistSectionInProject(project, sectionPayload) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!hasCapability("projects")) {
    void presentPlanLimitNotice("Project organization requires Pro", "Upgrade to Pro to add saved code to Projects.");
    return false;
  }
  const record = projectSectionRecordForSection(project, sectionPayload);
  const mutation = projectSectionMutationForSection(project, sectionPayload);
  const current = (state.localProjectSections || []).filter((item) => item.id !== record.id);
  state.localProjectSections = [...current, record];
  if (account) enqueueSyncMutation(mutation, account);
  saveWorkspaceState();
  void refreshProjectMembershipPanes(project).catch(() => {});
  requireCurrentAccountRequest(requestIdentity);
  if (!account) return true;
  try {
    await pushMutation(mutation);
    requireCurrentAccountRequest(requestIdentity);
    state.localProjectSections = (state.localProjectSections || []).filter((item) => item.id !== record.id);
    saveWorkspaceState();
  } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
    // Keep the local project link and queued mutation available while sync recovers.
  }
  requireCurrentAccountRequest(requestIdentity);
  void refreshProjectSourceConsumers([project]).catch(() => {});
  requireCurrentAccountRequest(requestIdentity);
  return true;
}

async function persistSectionFolderSelection(sectionPayload, selectedFolders, visibleFolders) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  const selectedByID = new Map(selectedFolders.map((folder) => [projectRecordID(folder), folder]));
  if (!selectedByID.size || !selectedFolders.some(folderIsProject)) return { saved: false, changed: false, queued: false };
  if (
    !hasCapability("saved-work")
  ) {
    preservePendingProSave(sectionPayload);
    void presentPlanLimitNotice(
      "Saving requires Pro",
      "Upgrade to Pro to save this section. Your place in the code will be kept."
    ).then(accepted => { if (!accepted) clearPendingProSave(); });
    return { saved: false, changed: false, queued: false };
  }
  if (selectedFolders.some(folderIsProject) && !hasCapability("projects")) {
    void presentPlanLimitNotice("Projects require Pro", "Upgrade to Pro to organize evidence in Projects and saved collections.");
    return { saved: false, changed: false, queued: false };
  }

  const summary = currentContentSummary();
  const sectionKey = savedEvidenceKey(sectionPayload);
  const visibleFolderIDs = new Set(visibleFolders.map(projectRecordID));
  const visibleLinks = (summary.projectSections || []).filter((link) =>
    savedEvidenceKey(link) === sectionKey &&
    visibleFolders.some((folder) => projectSectionBelongsToProject(link, folder))
  );
  const linkedFolderIDs = new Set(visibleLinks.map((link) => {
    const folder = visibleFolders.find((candidate) => projectSectionBelongsToProject(link, candidate));
    return folder ? projectRecordID(folder) : "";
  }).filter(Boolean));
  const additions = selectedFolders.filter((folder) => !linkedFolderIDs.has(projectRecordID(folder)));
  const removals = visibleLinks.filter((link) => {
    const folder = visibleFolders.find((candidate) => projectSectionBelongsToProject(link, candidate));
    return folder && visibleFolderIDs.has(projectRecordID(folder)) && !selectedByID.has(projectRecordID(folder));
  });
  const touchedProjects = [
    ...selectedFolders,
    ...removals.map((link) => visibleFolders.find((candidate) => projectSectionBelongsToProject(link, candidate)))
  ].filter(Boolean);
  const wasSaved = isSectionSaved(sectionPayload);
  const mutations = [];

  const existingSavedRecord = savedSectionRecord(sectionPayload);
  const savedTargetChanged = wasSaved &&
    normalizeAnnotationBlockID(existingSavedRecord?.blockID) !== normalizeAnnotationBlockID(sectionPayload.blockID);
  if (!wasSaved || savedTargetChanged) {
    const savedRecord = savedRecordForSection(sectionPayload, activeAccount()?.userID || "local-web");
    state.localSavedItems = [
      ...(state.localSavedItems || []).filter((item) => savedEvidenceKey(item) !== sectionKey),
      savedRecord
    ];
    if (!wasSaved && syncCodeVersion(sectionPayload.codeVersion) === defaultSyncCodeVersion) {
      setLocalSectionSaved(sectionPayload, true, sectionPayload.codeVersion);
    }
    mutations.push(savedMutationForSection(sectionPayload));
  }

  additions.forEach((folder) => {
    const record = projectSectionRecordForSection(folder, sectionPayload);
    state.localProjectSections = [
      ...(state.localProjectSections || []).filter((item) => item.id !== record.id),
      record
    ];
    mutations.push(projectSectionMutationForSection(folder, sectionPayload));
  });
  removals.forEach((link) => {
    const folder = visibleFolders.find((candidate) => projectSectionBelongsToProject(link, candidate));
    if (!folder) return;
    const deletion = deletedProjectSectionMutationForItem(folder, link);
    const matches = (candidate) =>
      savedEvidenceKey(candidate) === sectionKey && projectSectionBelongsToProject(candidate, folder);
    state.localProjectSections = [
      ...(state.localProjectSections || []).filter((candidate) => !matches(candidate)),
      deletion.projectSection
    ];
    mutations.push(deletion);
  });
  saveWorkspaceState();
  // Reflect the local membership overlay in every open Project/Saved column
  // before waiting for the network round-trip. The authoritative hydration
  // below will reconcile the same rows after sync completes.
  await refreshProjectMembershipPanes(selectedFolders[0] || null);
  requireCurrentAccountRequest(requestIdentity);

  let queued = false;
  if (account && mutations.length) {
    try {
      await pushMutationBatch(mutations);
      requireCurrentAccountRequest(requestIdentity);
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      queued = true;
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
    }
  }
  requireCurrentAccountRequest(requestIdentity);
  await refreshOpenSavedPanes();
  requireCurrentAccountRequest(requestIdentity);
  await refreshProjectSourceConsumers(touchedProjects);
  requireCurrentAccountRequest(requestIdentity);
  return {
    saved: true,
    changed: !wasSaved || additions.length > 0 || removals.length > 0,
    queued
  };
}

async function removeSectionFromAllProjects(sectionPayload, options = {}) {
  const requestIdentity = captureAccountRequest();
  const sectionID = String(sectionPayload.sectionID || sectionPayload.savedSectionID || sectionPayload.itemID || "");
  if (!sectionID) return;
  const summary = currentContentSummary();
  const projects = summary.projects || [];
  const links = (summary.projectSections || []).filter((item) =>
    savedEvidenceKey(item) === savedEvidenceKey(sectionPayload)
  );

  for (const link of links) {
    const project = projects.find((candidate) => projectSectionBelongsToProject(link, candidate)) || {
      clientID: link.folderClientID || "",
      localFolderID: link.localFolderID || ""
    };
    await removeSectionFromProject(project, link, {
      removeBookmark: false,
      refreshPanes: options.refreshPanes !== false
    });
    requireCurrentAccountRequest(requestIdentity);
  }
}

async function removeSectionFromProject(project, item, options = {}) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  const sectionID = String(item.sectionID || item.savedSectionID || item.itemID || "");
  const blockID = normalizeAnnotationBlockID(item.blockID);
  const projectID = projectRecordID(project);
  if (!sectionID || !projectID) return;

  const matches = (candidate) =>
    String(candidate.id || "") === String(item.projectSectionID || item.id || "") ||
    (
      String(candidate.sectionID || candidate.savedSectionID || candidate.itemID || "") === sectionID &&
      syncCodeVersion(candidate.codeVersion) === syncCodeVersion(item.codeVersion) &&
      normalizeAnnotationBlockID(candidate.blockID) === blockID &&
      projectSectionBelongsToProject(candidate, project)
    );

  const deletion = deletedProjectSectionMutationForItem(project, item);
  state.localProjectSections = [
    ...(state.localProjectSections || []).filter((candidate) => !matches(candidate)),
    deletion.projectSection
  ];
  saveWorkspaceState();
  if (options.refreshPanes !== false) await refreshProjectMembershipPanes(project);
  requireCurrentAccountRequest(requestIdentity);

  if (account) {
    try {
      await pushMutation(deletion);
      requireCurrentAccountRequest(requestIdentity);
      state.localProjectSections = (state.localProjectSections || []).filter((candidate) => !matches(candidate));
      saveWorkspaceState();
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
      // Keep the local project-membership tombstone while sync recovers.
    }
  }
  requireCurrentAccountRequest(requestIdentity);

  if (options.removeBookmark === true) {
    await persistSectionBookmark(item, false, { refreshSavedPanes: false });
    requireCurrentAccountRequest(requestIdentity);
    syncReaderNoteBookmarkButtons(sectionID, false, item.codeVersion);
  }
  if (options.refreshPanes !== false) await refreshProjectSourceConsumers([project]);
  requireCurrentAccountRequest(requestIdentity);
}

async function deleteSavedEvidenceBatch(items, project = null, onProgress = () => {}) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!account) throw new Error("Sign in before deleting saved evidence.");
  // Finish durable local saves before the server decides which destinations remain.
  await flushSyncOutbox({ refresh: false });
  requireCurrentAccountRequest(requestIdentity);
  if ((state.syncOutbox || []).some(entry => entry.accountUserID === account.userID) ||
      (state.syncConflicts || []).some(entry => entry.accountUserID === account.userID)) {
    throw new Error("Finish syncing or resolve pending sync conflicts before deleting saved evidence.");
  }
  const projectID = project ? syncProjectIdentity(project.clientID || project.id, account.userID) ||
    (project.localFolderID == null ? null : `legacy-project-${project.localFolderID}`) : null;
  if (project && !projectID) throw new Error("Refresh the Project before deleting saved evidence.");
  let deletedCount = 0;
  for (let offset = 0; offset < items.length; offset += 200) {
    requireCurrentAccountRequest(requestIdentity);
    const payload = await postJSON("/saved/evidence/delete-batch", {
      auth: { accountUserID: account.userID },
      projectID,
      items: items.slice(offset, offset + 200).map(item => ({
        codeVersion: syncCodeVersion(item.codeVersion),
        sectionID: Number(item.sectionID),
        blockID: normalizeAnnotationBlockID(item.blockID)
      }))
    }, { token: account.sessionToken });
    requireCurrentAccountRequest(requestIdentity);
    const mutations = mergeSyncedMutations(syncedContent?.mutations || [], payload.mutations || []);
    // Keep the previous sync cursor: unrelated concurrent changes must still pull.
    syncedContent = { ...syncedContent, mutations, summary: summarizeMutations(mutations) };
    for (const mutation of payload.mutations || []) {
      const { kind, record } = mutationKindAndRecord(mutation);
      const field = kind === "savedItem" ? "localSavedItems" : kind === "projectSection" ? "localProjectSections" : null;
      if (field) state[field] = (state[field] || []).filter(local =>
        String(local.id) !== String(record.id) || Date.parse(local.updatedAt || 0) > Date.parse(record.updatedAt));
      if (kind === "savedItem") {
        setLocalSectionSaved(record, false, record.codeVersion);
        syncReaderNoteBookmarkButtons(record.sectionID, false, record.codeVersion);
      }
    }
    saveWorkspaceState();
    deletedCount += Number(payload.deletedCount || 0);
    onProgress(deletedCount);
  }
  await loadSyncedContent({ force: true });
  requireCurrentAccountRequest(requestIdentity);
  return deletedCount;
}

async function unlinkEvidenceFromFolder(folder, item, container = null, options = {}) {
  const requestIdentity = captureAccountRequest();
  const remainingLinks = (currentContentSummary().projectSections || []).filter((candidate) =>
    savedEvidenceKey(candidate) === savedEvidenceKey(item) &&
    !projectSectionBelongsToProject(candidate, folder)
  );
  if (!remainingLinks.length) {
    const confirmed = options.confirmedFinalDestinationRemoval === true || await openWebWarning({
      title: "Remove final destination?",
      message: "This is the last destination containing this evidence. Removing it will also delete the saved record. Notes, source metadata, and evidence history are not silently reassigned.",
      confirmLabel: "Remove and delete",
      container
    });
    requireCurrentAccountRequest(requestIdentity);
    if (!confirmed) return false;
    await removeSectionFromProject(folder, item, {
      removeBookmark: true,
      refreshPanes: options.refreshPanes !== false
    });
    requireCurrentAccountRequest(requestIdentity);
    return true;
  }
  await removeSectionFromProject(folder, item, {
    removeBookmark: false,
    refreshPanes: options.refreshPanes !== false
  });
  requireCurrentAccountRequest(requestIdentity);
  return true;
}

function normalizeAnnotationBlockID(value) {
  return String(value || "").trim();
}

function safeAnnotationIDPart(value) {
  return String(value || "")
    .trim()
    .replace(/[^a-z0-9_-]+/gi, "-")
    .replace(/^-+|-+$/g, "") || "section";
}

function annotationRecordID(target) {
  const codeVersion = syncCodeVersion(target.codeVersion);
  const sectionID = String(target.sectionID || "");
  const blockID = normalizeAnnotationBlockID(target.blockID);
  return `web-annotation-${codeVersion}-${sectionID}-${safeAnnotationIDPart(blockID)}`;
}

function normalizeAnnotationTags(tags = []) {
  const seen = new Set();
  return tags
    .map((tag) => String(tag || "").normalize("NFKC").trim().replace(/\s+/g, " "))
    .filter(Boolean)
    .filter((tag) => {
      const key = tag.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function annotationRecordsForTarget(target, blockID = "", codeVersion = "", snapshot = null) {
  const sectionKey = String(target && typeof target === "object" ? target.sectionID : target || "");
  const blockKey = normalizeAnnotationBlockID(
    target && typeof target === "object" ? target.blockID : blockID
  );
  const versionKey = syncCodeVersion(
    (target && typeof target === "object" ? target.codeVersion : codeVersion) || defaultSyncCodeVersion
  );
  const localIDs = snapshot?.localIDs ?? new Set((state.localAnnotations || []).map((annotation) => String(annotation?.id || "")));
  return (snapshot?.annotations ?? currentContentSummary().annotations)
    .filter((annotation) =>
      String(annotation?.sectionID || "") === sectionKey &&
      syncCodeVersion(annotation?.codeVersion) === versionKey &&
      normalizeAnnotationBlockID(annotation?.blockID || annotation?.anchorID || annotation?.contentBlockID) === blockKey
    )
    .sort((left, right) => {
      const timestampDifference = Date.parse(right.updatedAt || 0) - Date.parse(left.updatedAt || 0);
      if (timestampDifference) return timestampDifference;
      const leftIsLocal = localIDs.has(String(left.id || ""));
      const rightIsLocal = localIDs.has(String(right.id || ""));
      return leftIsLocal === rightIsLocal ? 0 : leftIsLocal ? -1 : 1;
    });
}

function annotationForTarget(target, blockID = "", codeVersion = "", snapshot = null) {
  const records = annotationRecordsForTarget(target, blockID, codeVersion, snapshot);
  let noteBody = "";
  let tags = [];
  let noteResolved = false;
  let tagsResolved = false;
  const clearRecords = snapshot?.clearRecords ?? currentBulkClearRecords();

  for (const record of records) {
    const updatedAt = Date.parse(record.updatedAt || "");
    const noteClearTimestamp = bulkClearTimestamp(clearRecords, record.codeVersion, "notes");
    const tagsClearTimestamp = bulkClearTimestamp(clearRecords, record.codeVersion, "tags");
    const noteWasCleared = noteClearTimestamp > 0 &&
      (!Number.isFinite(updatedAt) || noteClearTimestamp >= updatedAt);
    const tagsWereCleared = tagsClearTimestamp > 0 &&
      (!Number.isFinite(updatedAt) || tagsClearTimestamp >= updatedAt);
    if (noteWasCleared && !noteResolved) {
      noteBody = "";
      noteResolved = true;
    }
    if (tagsWereCleared && !tagsResolved) {
      tags = [];
      tagsResolved = true;
    }
    if (record.deletedAt && !noteResolved) {
      noteBody = "";
      noteResolved = true;
    }
    if (!record.deletedAt && record.noteBody !== undefined && record.noteBody !== null && !noteResolved) {
      noteBody = String(record.noteBody);
      noteResolved = true;
    }
    if (!record.deletedAt && Array.isArray(record.tags) && !tagsResolved) {
      tags = normalizeAnnotationTags(record.tags);
      tagsResolved = true;
    }
  }

  return { noteBody, tags };
}

function noteValueForTarget(sectionID, blockID = "") {
  const target = sectionID && typeof sectionID === "object" ? sectionID : null;
  const blockKey = normalizeAnnotationBlockID(target ? target.blockID : blockID);
  const targetVersion = syncCodeVersion(target?.codeVersion || defaultSyncCodeVersion);
  if (!blockKey && targetVersion === defaultSyncCodeVersion) {
    const legacyNote = state.sectionNotes?.[sectionNoteKey(target ? target.sectionID : sectionID)];
    if (legacyNote !== undefined) return legacyNote;
  }
  return annotationForTarget(target || sectionID, blockKey).noteBody;
}

function tagsForTarget(sectionID, blockID = "") {
  return annotationForTarget(sectionID, blockID).tags;
}

function annotationRecordForTarget(target, values = {}) {
  const existing = annotationForTarget(target);
  const now = values.updatedAt || new Date().toISOString();
  const blockID = normalizeAnnotationBlockID(target.blockID);
  const noteBody = values.noteBody !== undefined ? values.noteBody : existing.noteBody;
  const tags = values.tags !== undefined ? normalizeAnnotationTags(values.tags) : existing.tags;
  return {
    id: annotationRecordID(target),
    userID: activeAccount()?.userID || "local-web",
    codeVersion: syncCodeVersion(target.codeVersion),
    codePrefix: target.codePrefix || "BC",
    chapterID: target.chapterID || "",
    chapterNumber: target.chapterNumber || "",
    sectionID: Number(target.sectionID),
    sectionNumber: target.sectionNumber || "",
    title: target.title || "Section",
    blockID,
    blockLabel: target.blockLabel || "",
    noteBody,
    tags,
    syncFields: values.syncFields || ["noteBody", "tags"],
    updatedAt: now,
    deletedAt: values.deletedAt || null
  };
}

function upsertLocalAnnotation(record) {
  requirePrivateWorkspaceWritable();
  const annotations = (state.localAnnotations || []).filter((item) => String(item.id || "") !== String(record.id || ""));
  state.localAnnotations = [...annotations, record];
  if (!record.blockID) {
    state.sectionNotes = state.sectionNotes && typeof state.sectionNotes === "object" ? state.sectionNotes : {};
    delete state.sectionNotes[sectionNoteKey(record.sectionID)];
  }
  saveWorkspaceState();
}

function annotationMutationForRecord(record) {
  const account = activeAccount();
  const fields = new Set(Array.isArray(record.syncFields) ? record.syncFields : ["noteBody", "tags"]);
  const annotation = {
    id: record.id,
    userID: account?.userID || record.userID || "local-web",
    codeVersion: syncCodeVersion(record.codeVersion),
    sectionID: Number(record.sectionID),
    blockID: normalizeAnnotationBlockID(record.blockID) || null,
    updatedAt: record.updatedAt || new Date().toISOString(),
    deletedAt: record.deletedAt || null
  };
  if (fields.has("noteBody")) annotation.noteBody = record.deletedAt ? null : record.noteBody ?? "";
  if (fields.has("tags")) annotation.tags = record.deletedAt ? null : normalizeAnnotationTags(record.tags || []);
  return {
    annotation
  };
}

function scheduleAnnotationPush(record, onStatus = () => {}) {
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  onStatus("local");
  if (!account) return;
  const mutation = annotationMutationForRecord(record);
  enqueueSyncMutation(mutation, account);
  const timerKey = String(record.id || "");
  clearTimeout(annotationPushTimers.get(timerKey));
  annotationPushTimers.set(timerKey, window.setTimeout(async () => {
    try {
      requireCurrentAccountRequest(requestIdentity);
      await pushMutation(mutation);
      requireCurrentAccountRequest(requestIdentity);
      state.localAnnotations = (state.localAnnotations || []).filter((item) =>
        String(item.id || "") !== timerKey || String(item.updatedAt || "") !== String(record.updatedAt || "")
      );
      saveWorkspaceState();
      onStatus("synced");
      if ((record.syncFields || []).includes("noteBody")) {
        await refreshProjectSourceConsumers([], { refreshNotebookReferences: false }).catch(() => false);
      }
    } catch {
      if (isCurrentAccountRequest(requestIdentity)) onStatus("error");
      // The local annotation and durable outbox entry remain available for retry.
    } finally {
      if (!isCurrentAccountRequest(requestIdentity)) return;
      annotationPushTimers.delete(timerKey);
      if ((record.syncFields || []).includes("noteBody")) {
        await refreshOpenSavedPanes().catch(() => {});
        if (!isCurrentAccountRequest(requestIdentity)) return;
        refreshVisibleSyncedDerivedState();
      }
    }
  }, 650));
}

function pendingAnnotationNoteForTarget(target, entries = state.syncOutbox) {
  const account = activeAccount();
  if (!account || !target?.sectionID) return null;
  return (entries || []).find((entry) => {
    const annotation = entry.mutation?.annotation;
    return entry.accountUserID === account.userID && annotation?.userID === account.userID &&
      Object.prototype.hasOwnProperty.call(annotation, "noteBody") &&
      syncCodeVersion(annotation.codeVersion) === syncCodeVersion(target.codeVersion) &&
      String(annotation.sectionID) === String(target.sectionID) &&
      normalizeAnnotationBlockID(annotation.blockID) === normalizeAnnotationBlockID(target.blockID);
  }) || null;
}

function detailNoteValueForTarget(target) {
  const recovery = pendingAnnotationNoteForTarget(target, state.syncConflicts) || pendingAnnotationNoteForTarget(target);
  if (!recovery) return noteValueForTarget(target);
  const original = recovery.mutation.annotation;
  const newerLocal = (state.localAnnotations || []).find((item) =>
    item.userID === original.userID && item.id === original.id &&
    Date.parse(item.updatedAt) > Date.parse(original.updatedAt));
  return String((newerLocal || original).noteBody || "");
}

function setAnnotationNoteValue(target, value, onStatus = () => {}) {
  if (!target?.sectionID) return false;
  const currentNote = noteValueForTarget(target);
  const nextNote = String(value || "");
  if (
    !hasCapability("notes") && nextNote.trim()
  ) {
    void presentPlanLimitNotice(
      "Notes require Pro",
      "Upgrade to Pro to add or edit notes. Existing notes are preserved."
    );
    return false;
  }
  const project = workspaceProject();
  if (nextNote.trim() && !project) {
    const identity = captureAccountRequest();
    void chooseProjectForSaving().then(chosen => {
      if (chosen && isCurrentAccountRequest(identity)) setAnnotationNoteValue(target, nextNote, onStatus);
    });
    return false;
  }
  if (nextNote.trim() && project && !projectLinkForAnnotationTarget(project, target)) {
    const link = projectSectionRecordForSection(project, target);
    state.localProjectSections = [...(state.localProjectSections || []).filter(item => item.id !== link.id), link];
    const account = activeAccount();
    if (account) enqueueSyncMutation(projectSectionMutationForSection(project, target), account);
  }
  const existingTags = tagsForTarget(target);
  const deleteEmptyAnnotation = !nextNote.trim() && existingTags.length === 0;
  const record = annotationRecordForTarget(target, {
    noteBody: nextNote,
    tags: existingTags,
    syncFields: ["noteBody"],
    deletedAt: deleteEmptyAnnotation ? new Date().toISOString() : null
  });
  upsertLocalAnnotation(record);
  scheduleAnnotationPush(record, onStatus);
  refreshVisiblePlanUsage();
  return true;
}

function projectLinkForAnnotationTarget(project, target) {
  const sectionID = String(target.sectionID || "");
  const targetBlockID = normalizeAnnotationBlockID(target.blockID);
  return currentContentSummary().projectSections.find((item) =>
    String(item.sectionID || item.savedSectionID || item.itemID || "") === sectionID &&
    syncCodeVersion(item.codeVersion) === syncCodeVersion(target.codeVersion) &&
    normalizeAnnotationBlockID(item.blockID || item.anchorID || item.contentBlockID) === targetBlockID &&
    projectSectionBelongsToProject(item, project)
  );
}

function renderAnnotationProjectEditor(container, target, sectionPayload, options = {}) {
  if (!container || !target?.sectionID) return;
  const projectListWasOpen = container.dataset.projectListOpen === "true";
  clear(container);

  const header = document.createElement("div");
  header.className = "annotation-projects-header";

  const projectListMotion = document.createElement("div");
  projectListMotion.className = "annotation-project-list-motion";
  const chips = document.createElement("div");
  chips.className = "annotation-project-chips annotation-project-list";
  chips.id = `annotation-project-list-${crypto.randomUUID()}`;
  projectListMotion.append(chips);
  const projects = activeFolderRecords(currentContentSummary().projects || []);
  const selectedProjects = projects.filter((project) => projectLinkForAnnotationTarget(project, target));
  const primarySelectedProjectName = selectedProjects[0]?.name || selectedProjects[0]?.title || "Project";
  const projectListLabel = selectedProjects.length === 0
    ? "Projects"
    : selectedProjects.length === 1
      ? primarySelectedProjectName
      : "MULTIPLE PROJECTS";

  const setProjectListOpen = (open, { focusToggle = false } = {}) => {
    container.dataset.projectListOpen = String(open);
    projectListMotion.classList.toggle("is-open", open);
    projectListToggle.setAttribute("aria-expanded", String(open));
    projectListToggle.setAttribute("aria-label", `${open ? "Hide" : "Show"} projects`);
    chips.inert = !open;
    chips.setAttribute("aria-hidden", String(!open));
    if (focusToggle) projectListToggle.focus({ preventScroll: true });
  };

  const projectListToggle = document.createElement("button");
  projectListToggle.type = "button";
  projectListToggle.className = "annotation-project-list-toggle annotation-editor-label";
  projectListToggle.textContent = projectListLabel;
  projectListToggle.setAttribute("aria-controls", chips.id);
  projectListToggle.addEventListener("click", () => {
    setProjectListOpen(!projectListMotion.classList.contains("is-open"));
  });
  header.append(projectListToggle);

  if (container.classList.contains("section-detail-projects")) {
    const addButton = document.createElement("button");
    addButton.type = "button";
    addButton.className = "annotation-project-add";
    addButton.title = "New Project";
    addButton.setAttribute("aria-label", "New Project");
    addButton.innerHTML = `
      <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <path d="M12 5v14"></path>
        <path d="M5 12h14"></path>
      </svg>
    `;
    addButton.addEventListener("click", () => {
      const panel = container.closest(".workspace-panel");
      if (!panel) return;
      showProjectCreateSheet(panel, null, {
        onCreated: async (project) => {
          const saved = await persistSectionBookmark(sectionPayload, true, { refreshSavedPanes: false });
          if (!saved) return;
          syncReaderNoteBookmarkButtons(sectionPayload.sectionID, true, sectionPayload.codeVersion);
          await persistSectionInProject(project, { ...sectionPayload, ...target });
          options.onChange?.();
        }
      });
    });
    header.append(addButton);
  }

  if (!projects.length) {
    const empty = document.createElement("span");
    empty.className = "annotation-projects-empty";
    empty.textContent = "No Projects or saved collections";
    chips.append(empty);
  } else {
    projects.forEach((project) => {
      const existingLink = projectLinkForAnnotationTarget(project, target);
      const button = document.createElement("button");
      button.type = "button";
      button.className = "annotation-project-chip";
      button.classList.toggle("is-selected", Boolean(existingLink));
      button.style.setProperty("--project-color", projectColor(project));
      button.setAttribute("aria-pressed", String(Boolean(existingLink)));
      button.setAttribute(
        "aria-label",
        `${existingLink ? "Remove from" : "Add to"} ${project.name || project.title || "project"}`
      );
      const projectName = document.createElement("span");
      projectName.textContent = project.name || project.title || "Project";
      const selectedMark = document.createElement("span");
      selectedMark.className = "annotation-project-selected-mark";
      selectedMark.setAttribute("aria-hidden", "true");
      selectedMark.textContent = existingLink ? "✓" : "";
      button.append(projectName, selectedMark);
      button.title = folderTypeLabel(project);
      if (!existingLink && folderIsProject(project) && !hasCapability("projects")) {
        button.disabled = true;
        button.title = "Projects require Pro";
      }
      button.addEventListener("click", async () => {
        button.disabled = true;
        try {
          const currentLink = projectLinkForAnnotationTarget(project, target);
          if (currentLink) {
            const removed = await unlinkEvidenceFromFolder(
              project,
              currentLink,
              container.closest(".workspace-panel")
            );
            if (!removed) return;
          } else {
            const saved = await persistSectionBookmark(sectionPayload, true, { refreshSavedPanes: false });
            if (!saved) return;
            syncReaderNoteBookmarkButtons(sectionPayload.sectionID, true, sectionPayload.codeVersion);
            await persistSectionInProject(project, { ...sectionPayload, ...target });
          }
          container.dataset.projectListOpen = "true";
          renderAnnotationProjectEditor(container, target, sectionPayload, options);
          options.onChange?.();
        } finally {
          button.disabled = false;
        }
      });
      chips.append(button);
    });
  }

  projectListToggle.hidden = !projects.length;
  setProjectListOpen(projectListWasOpen && projects.length > 0);
  chips.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    setProjectListOpen(false, { focusToggle: true });
  });
  container.append(header, projectListMotion);
}

function refreshOpenAnnotationProjectEditors() {
  track.querySelectorAll(".section-detail-panel").forEach((panel) => {
    const target = panel.__annotationTarget;
    const sectionPayload = panel.__sectionPayload;
    const container = panel.querySelector(".section-detail-projects");
    if (!target?.sectionID || !sectionPayload?.sectionID || !container) return;
    renderAnnotationProjectEditor(container, target, sectionPayload);
  });
}

function annotationTargetForSection(section, reader = null, overrides = {}) {
  const codePrefix = reader?.codePrefix || section.codePrefix || "BC";
  return {
    codeVersion: syncCodeVersion(
      reader?.codeVersion || section.codeVersion || syncCodeVersionForPrefix(codePrefix)
    ),
    codePrefix,
    chapterID: reader?.chapterID || section.chapterID || "",
    chapterNumber: reader?.chapterNumber || section.chapterNumber || "",
    sectionID: section.id || section.sectionID,
    sectionNumber: section.sectionNumber || "",
    title: section.title || "Section",
    blockID: normalizeAnnotationBlockID(overrides.blockID),
    blockLabel: overrides.blockLabel || ""
  };
}

function annotationTargetForBlock(section, block, reader = null, index = 0) {
  const blockID = normalizeAnnotationBlockID(block?.id || block?.tableID || block?.imageID || `block-${index + 1}`);
  return annotationTargetForSection(section, reader, {
    blockID,
    blockLabel: block?.caption || block?.plainText?.slice(0, 80) || `Paragraph ${index + 1}`
  });
}

function annotatedBlocksForSection(section) {
  const sourceBlocks = Array.isArray(section.blocks) ? section.blocks : [];
  const organizedBlocks = organizedSpecialtyProvisionBlocks(section, sourceBlocks);
  const blocks = organizedBlocks.flatMap((block, blockIndex) => splitAnnotatedCodeBlock(block, blockIndex));
  const isZoningSection =
    String(section?.codePrefix || "").toUpperCase() === zoningCodePrefix ||
    Boolean(section?.zoning) ||
    sourceBlocks.some((block) => String(block?.id || "").startsWith("zr-"));
  return isZoningSection ? blocks.filter(codeBlockHasVisibleContent) : blocks;
}

function normalizedSpecialtySectionRoot(sectionNumber) {
  const value = String(sectionNumber || "")
    .replace(/^§\s*/i, "")
    .replace(/\.$/, "")
    .trim()
    .toUpperCase();
  if (/^ARTICLE-\d+$/.test(value)) return `28-${value.slice("ARTICLE-".length)}`;
  if (/^ASHRAE-\d+$/.test(value)) return value.slice("ASHRAE-".length);
  return value;
}

function specialtyProvisionMarker(line, sectionRoot, allowSubdivisions) {
  const value = String(line || "").replace(/\s+/g, " ").trim();
  const numbered = value.match(
    /^(§\s*)?([A-Z]?\d+(?:-\d+)?(?:\.\d+)+(?:\([A-Za-z0-9]+\))*)\s+([A-Z][\s\S]*)$/
  );
  if (numbered) {
    const number = numbered[2].toUpperCase();
    const belongsToSection =
      number === sectionRoot ||
      number.startsWith(`${sectionRoot}.`) ||
      number.startsWith(`${sectionRoot}(`);
    if (belongsToSection) {
      return {
        displayNumber: `${numbered[1] || ""}${numbered[2]}`.trim(),
        bodyStart: numbered[3]
      };
    }
  }
  if (allowSubdivisions) {
    const subdivision = value.match(/^(\([A-Z]\))\s+([A-Z][\s\S]*)$/);
    if (subdivision) {
      return {
        displayNumber: subdivision[1],
        bodyStart: subdivision[2]
      };
    }
  }
  return null;
}

function specialtyProvisionHeading(segmentText, marker) {
  const normalized = String(segmentText || "").replace(/\s+/g, " ").trim();
  const markerPattern = new RegExp(
    `^(?:§\\s*)?${escapeRegExp(marker.displayNumber.replace(/^§\\s*/i, ""))}\\s+`,
    "i"
  );
  const remainder = normalized.replace(markerPattern, "");
  const titleMatch = remainder.match(/^(.{1,160}?\.)($|\s+)([\s\S]*)$/);
  if (!titleMatch) return null;
  return {
    heading: `${marker.displayNumber} ${titleMatch[1]}`.trim(),
    body: String(titleMatch[3] || "").trim()
  };
}

function specialtyProvisionHTML(heading, body) {
  const paragraph = document.createElement("p");
  paragraph.className = "specialty-provision";
  const strong = document.createElement("strong");
  strong.className = "specialty-provision-heading";
  strong.textContent = heading;
  paragraph.append(strong);
  if (body) paragraph.append(document.createTextNode(` ${body}`));
  return paragraph.outerHTML;
}

function organizedSpecialtyProvisionBlocks(section, sourceBlocks) {
  const codePrefix = String(section?.codePrefix || "").toUpperCase();
  if (!["ECC", "EC"].includes(codePrefix) || sourceBlocks.length !== 1) return sourceBlocks;
  const source = sourceBlocks[0];
  if (source.kind !== "html" || !String(source.plainText || "").trim()) return sourceBlocks;

  const sectionRoot = normalizedSpecialtySectionRoot(section.sectionNumber);
  if (!sectionRoot || sectionRoot.includes("APPENDIX")) return sourceBlocks;
  const lines = String(source.plainText).split(/\r?\n/);
  const starts = [];
  lines.forEach((line, index) => {
    const marker = specialtyProvisionMarker(line, sectionRoot, codePrefix === "EC");
    if (marker) starts.push({ index, marker });
  });
  if (!starts.length) return sourceBlocks;

  const blocks = [];
  const appendPlainBlock = (text, suffix) => {
    const plainText = String(text || "").replace(/\s+/g, " ").trim();
    if (!plainText) return;
    const paragraph = document.createElement("p");
    paragraph.textContent = plainText;
    blocks.push({
      ...source,
      id: `${source.id || `specialty-${section.id}`}-${suffix}`,
      html: paragraph.outerHTML,
      plainText
    });
  };

  if (starts[0].index > 0) {
    appendPlainBlock(lines.slice(0, starts[0].index).join("\n"), "preamble");
  }
  starts.forEach((entry, markerIndex) => {
    const end = starts[markerIndex + 1]?.index ?? lines.length;
    const segmentText = lines.slice(entry.index, end).join("\n");
    const provision = specialtyProvisionHeading(segmentText, entry.marker);
    if (!provision) {
      appendPlainBlock(segmentText, `provision-${markerIndex + 1}`);
      return;
    }
    blocks.push({
      ...source,
      id: `${source.id || `specialty-${section.id}`}-provision-${markerIndex + 1}`,
      html: specialtyProvisionHTML(provision.heading, provision.body),
      plainText: String(segmentText).replace(/\s+/g, " ").trim()
    });
  });
  return blocks.length ? blocks : sourceBlocks;
}

function normalizedReaderProvisionText(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u00ad\u200b-\u200d\ufeff]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function readerSectionsWithoutRepeatedCatalogAliases(sections) {
  const rendered = [];
  let latestBodySection = null;
  let latestBodyText = "";

  for (const section of sections || []) {
    const blocks = annotatedBlocksForSection(section);
    if (blocks.length > 0) {
      const renderedSection = {
        ...section,
        readerAliasSectionIDs: []
      };
      rendered.push(renderedSection);
      latestBodySection = renderedSection;
      latestBodyText = normalizedReaderProvisionText(sectionPlainText(section));
      continue;
    }

    const catalogTitle = normalizedReaderProvisionText(section.title);
    if (catalogTitle && latestBodySection && latestBodyText.includes(catalogTitle)) {
      latestBodySection.readerAliasSectionIDs.push(String(section.id));
      continue;
    }

    rendered.push({
      ...section,
      readerAliasSectionIDs: []
    });
    latestBodySection = null;
    latestBodyText = "";
  }

  return rendered;
}

function codeBlockHasVisibleContent(block) {
  if (!block) return false;
  if (block.kind === "image" || block.kind === "table") return true;
  if (String(block.plainText || block.text || "").replace(/\u00a0/g, " ").trim()) return true;
  if (!block.html) return false;
  if (typeof document === "undefined") return /<(?:img|table)\b/i.test(block.html);
  const wrapper = document.createElement("div");
  wrapper.innerHTML = rewriteCodeHTML(block.html);
  return Boolean(
    String(wrapper.textContent || "").replace(/\u00a0/g, " ").trim() ||
    wrapper.querySelector("img, table")
  );
}

function splitAnnotatedCodeBlock(block, blockIndex = 0) {
  if (block?.kind !== "html" || !block.html || typeof document === "undefined") return [block];
  const wrapper = document.createElement("div");
  wrapper.innerHTML = rewriteCodeHTML(block.html);
  const hasReadableCodeNodeContent = (node) => Boolean(
    String(node.textContent || "").trim() || node.querySelector("img, table")
  );
  const paragraphBlocks = Array.from(wrapper.querySelectorAll(".Normal-Level[id]"))
    .filter(hasReadableCodeNodeContent);
  const noteBlocks = paragraphBlocks.length
    ? paragraphBlocks
    : Array.from(wrapper.querySelectorAll(".rbox[id]"))
      .filter(hasReadableCodeNodeContent);
  if (noteBlocks.length === 0) return [block];
  return noteBlocks.map((node, nodeIndex) => ({
    ...block,
    id: node.id || `${block.id || `block-${blockIndex + 1}`}-${nodeIndex + 1}`,
    html: node.outerHTML,
    plainText: String(node.textContent || "").replace(/\s+/g, " ").trim()
  }));
}

// Selector resolution fills an omitted chapter or maps a source chapter to its
// navigation chapter. That is still the same requested Reader load. Keep its
// identity stable only while its fields equal this internally resolved snapshot;
// an explicit navigation change immediately produces a different identity.
const readerResolvedWorkspaceIdentities = new WeakMap();
const resolvedReaderSourceNavigations = new WeakMap();

function workspaceReaderContentIdentity(reader) {
  const value = JSON.stringify([reader.id, reader.codePrefix, reader.codeVersion, reader.chapterID, reader.sectionID]);
  const resolved = readerResolvedWorkspaceIdentities.get(reader);
  return resolved?.value === value ? resolved.identity : value;
}

function setResolvedReaderChapter(reader, chapterID) {
  const identity = workspaceReaderContentIdentity(reader);
  reader.chapterID = chapterID;
  const value = JSON.stringify([reader.id, reader.codePrefix, reader.codeVersion, reader.chapterID, reader.sectionID]);
  readerResolvedWorkspaceIdentities.set(reader, { value, identity });
}

async function populateReaderSelectors(panel, reader, navigationToken = panel.dataset.readerNavigationToken) {
  const chapterSelect = panel.querySelector(".chapter-select");
  const sectionSelect = panel.querySelector(".section-select");
  clear(chapterSelect);
  clear(sectionSelect);
  reader.codePrefix = reader.codePrefix || "BC";

  const readerChapters = await fetchChapterList(reader.codePrefix, reader.codeVersion, { signal: panel._readerNavigationAbort?.signal });
  if (panel.dataset.readerNavigationToken !== navigationToken) return false;
  if (!reader.chapterID) {
    setResolvedReaderChapter(reader, readerChapters[0]?.id || "");
  } else {
    setResolvedReaderChapter(reader, resolveReaderNavigationChapterID(reader, readerChapters));
  }
  readerChapters.forEach((chapter) => {
    const option = document.createElement("option");
    option.value = chapter.id;
    option.textContent = chapter.fullTitle || chapter.displayTitle || `Chapter ${chapter.chapterNumber}`;
    option.title = option.textContent;
    option.dataset.sourceChapterId = String(chapter.sourceChapterID || chapter.id);
    option.dataset.hierarchyKind = chapter.hierarchyKind || "source-chapter";
    option.dataset.sectionCount = String(chapter.sectionCount || 0);
    chapterSelect.append(option);
  });
  chapterSelect.value = reader.chapterID || "";

  if (!reader.chapterID) {
    const blankSection = document.createElement("option");
    blankSection.value = "";
    blankSection.textContent = "Select a section";
    sectionSelect.append(blankSection);
    return true;
  }

  const chapter = await fetchChapter(reader.chapterID, { signal: panel._readerNavigationAbort?.signal });
  if (panel.dataset.readerNavigationToken !== navigationToken) return false;
  const blankSection = document.createElement("option");
  blankSection.value = "";
  blankSection.textContent = "Select a section";
  sectionSelect.append(blankSection);
  readerNavigationSections(chapter).forEach((section) => {
    const option = document.createElement("option");
    option.value = section.id;
    option.textContent = sectionDisplayTitle(section.sectionNumber, section.title);
    sectionSelect.append(option);
  });
  sectionSelect.value = reader.sectionID || "";
  return true;
}

function readerTargetSectionIndex(sections, reader) {
  const sectionID = String(reader.sectionID || "");
  const sectionNumber = String(reader.sectionNumber || "");
  return sections.findIndex((section) =>
    (sectionID && String(section.id) === sectionID) ||
    (sectionID && section.readerAliasSectionIDs.includes(sectionID)) ||
    (sectionNumber && String(section.sectionNumber || "") === sectionNumber)
  );
}

function readerSectionWithWindowBody(section, windowChapter) {
  const bodySection = (windowChapter.sections || []).find((candidate) =>
    String(candidate.id) === String(section.id)
  );
  return bodySection && Array.isArray(bodySection.blocks)
    ? { ...section, blocks: bodySection.blocks }
    : section;
}

function readerSectionPayload(section, reader, blockID = "") {
  const target = annotationTargetForSection(section, reader);
  return {
    codeVersion: target.codeVersion,
    sectionID: section.id,
    sectionNumber: section.sectionNumber,
    title: section.title,
    codePrefix: reader?.codePrefix || "BC",
    chapterID: reader?.chapterID || "",
    chapterNumber: section.chapterNumber || "",
    blockID: normalizeAnnotationBlockID(blockID),
    blockLabel: ""
  };
}

function readerSectionIdentityValues(section) {
  return new Set([
    section?.id,
    section?.sectionID,
    ...(section?.readerAliasSectionIDs || [])
  ].filter(Boolean).map(String));
}

function readerProjectsForSection(section) {
  const sectionIDs = readerSectionIdentityValues(section);
  const summary = currentContentSummary();
  const links = (summary.projectSections || []).filter((item) =>
    sectionIDs.has(String(item.sectionID || item.savedSectionID || item.itemID || ""))
  );
  const seen = new Set();
  return visibleProjectRecords(summary.projects || []).filter((project) => {
    const key = projectDetailKey(project);
    if (!key || seen.has(key) || !links.some((link) => projectSectionBelongsToProject(link, project))) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function readerSectionHasNote(section) {
  const sectionIDs = readerSectionIdentityValues(section);
  if ([...sectionIDs].some((sectionID) => noteValueForSection(sectionID).trim())) return true;
  return (currentContentSummary().annotations || []).some((annotation) =>
    sectionIDs.has(String(annotation.sectionID || "")) &&
    String(annotation.noteBody || "").trim()
  );
}

// Access callbacks belong to DOM nodes, not to the long-lived workspace gate.
// The gate retains only weak references; one observer eagerly removes subscriptions
// after mounted controls disappear. Explicit disposal covers abandoned renders.
const workspaceNodeAccessRecords = new Set();
const workspaceNodeAccessCallbacks = new WeakMap();
let workspaceNodeAccessObserver = null;
const workspaceNodeAccessFinalizer = typeof FinalizationRegistry === "function"
  ? new FinalizationRegistry((record) => releaseWorkspaceNodeAccess(record)) : null;

function releaseWorkspaceNodeAccess(record) {
  if (!workspaceNodeAccessRecords.delete(record)) return;
  record.unsubscribe?.();
  workspaceNodeAccessFinalizer?.unregister(record);
  const owner = record.owner.deref();
  if (owner) workspaceNodeAccessCallbacks.get(owner)?.delete(record);
}

function sweepWorkspaceNodeAccess() {
  for (const record of workspaceNodeAccessRecords) {
    const owner = record.owner.deref();
    const root = record.root.deref();
    if (!owner || !root) { releaseWorkspaceNodeAccess(record); continue; }
    if (owner.isConnected) {
      record.seenConnected = true;
      record.rootWasConnected ||= root.isConnected;
      continue;
    }
    // Detached construction stays live until its root mounts or is explicitly
    // discarded. An already-live root cannot retain removed result/block nodes.
    if (record.seenConnected || record.rootWasConnected || root.isConnected) releaseWorkspaceNodeAccess(record);
  }
}

function disposeWorkspaceNodeAccess(root) {
  for (const record of workspaceNodeAccessRecords) {
    const owner = record.owner.deref();
    if (record.root.deref() === root || owner === root || (owner && root?.contains?.(owner))) releaseWorkspaceNodeAccess(record);
  }
}

function workspaceNodeAccessListener(record) {
  // Separate lexical scope: no control node or update closure can be captured.
  return () => {
    const node = record.owner.deref();
    if (!node) { releaseWorkspaceNodeAccess(record); return; }
    return workspaceNodeAccessCallbacks.get(node)?.get(record)?.();
  };
}

function subscribeWorkspaceNodeAccess(owner, gate, callback, root = owner) {
  if (!owner || !gate) return () => {};
  const record = { owner: new WeakRef(owner), root: new WeakRef(root || owner), seenConnected: owner.isConnected,
    rootWasConnected: Boolean(root?.isConnected), unsubscribe: null };
  let callbacks = workspaceNodeAccessCallbacks.get(owner);
  if (!callbacks) { callbacks = new Map(); workspaceNodeAccessCallbacks.set(owner, callbacks); }
  callbacks.set(record, callback);
  workspaceNodeAccessRecords.add(record);
  // Do not capture callback/owner/root in the gate's listener closure.
  record.unsubscribe = gate.subscribe(workspaceNodeAccessListener(record));
  workspaceNodeAccessFinalizer?.register(owner, record, record);
  if (!workspaceNodeAccessObserver && typeof MutationObserver === "function" && document.documentElement) {
    workspaceNodeAccessObserver = new MutationObserver(sweepWorkspaceNodeAccess);
    workspaceNodeAccessObserver.observe(document.documentElement, { childList: true, subtree: true });
  }
  return releaseWorkspaceNodeAccess.bind(null, record);
}

function readerPrivateContentAllowed(panel) {
  return !panel?.__workspaceAccessGate || panel.__workspaceAccessGate.allowed;
}

function renderReaderSectionProjectContext(host, section, reader, panel) {
  if (!host) return;
  clear(host);
  if (!readerPrivateContentAllowed(panel)) {
    host.hidden = true;
    const gate = panel.__workspaceAccessGate;
    if (host.__workspaceAccessGate !== gate) {
      host.__workspaceAccessGate = gate;
      subscribeWorkspaceNodeAccess(host, gate, () => {
        if (panel.__workspaceAccessGate !== gate || !gate.allowed) return;
        renderReaderSectionProjectContext(host, section, reader, panel);
      }, panel);
    }
    return;
  }
  const selectedSectionID = String(reader?.sectionID || "");
  if (!selectedSectionID || !readerSectionIdentityValues(section).has(selectedSectionID)) {
    host.hidden = true;
    return;
  }
  const projects = readerProjectsForSection(section);
  const saved = [...readerSectionIdentityValues(section)].some((sectionID) =>
    isSectionSaved({ sectionID, codeVersion: reader?.codeVersion })
  );
  if (!saved && projects.length === 0) {
    host.hidden = true;
    return;
  }
  host.hidden = false;
  const label = document.createElement("span");
  label.className = "reader-section-project-context-label";
  label.textContent = "Saved in";
  host.append(label);
  const hasNote = readerSectionHasNote(section);
  if (!projects.length) {
    const status = document.createElement("span");
    status.className = "reader-section-project-context-status";
    status.textContent = hasNote ? "Saved evidence · Note" : "Saved evidence · Choose a destination";
    host.append(status);
    return;
  }
  projects.forEach((project) => {
    const projectButton = document.createElement("button");
    projectButton.type = "button";
    projectButton.className = "reader-section-project-chip";
    projectButton.style.setProperty("--project-color", projectColor(project));
    const archived = projectIsArchived(project);
    projectButton.textContent = `${project.name || project.title || folderTypeLabel(project)} · ${folderTypeLabel(project)}${archived ? " · Archived" : ""}`;
    projectButton.title = folderIsProject(project) ? "Open Project" : "Open saved collection";
    projectButton.addEventListener("click", () => {
      if (folderIsProject(project)) void openProjectDetail(project, { sourcePaneID: paneIDForReader(reader) });
    });
    host.append(projectButton);
  });
  const status = document.createElement("span");
  status.className = "reader-section-project-context-status";
  status.textContent = hasNote ? "Saved evidence · Note" : "Saved evidence";
  host.append(status);
}

function refreshReaderSectionProjectContexts(sectionID = "") {
  const sectionKey = String(sectionID || "");
  track.querySelectorAll(".reader-section-project-context").forEach((host) => {
    const context = host.__readerProjectContext;
    if (!context || (sectionKey && !readerSectionIdentityValues(context.section).has(sectionKey))) return;
    renderReaderSectionProjectContext(host, context.section, context.reader, context.panel);
  });
}

function readerSectionResearchSelection(sectionWrapper, passageElement = sectionWrapper) {
  if (!sectionWrapper) return;
  const range = document.createRange();
  range.selectNodeContents(passageElement);
  const selectedText = researchSelectionTextFromRange("", range);
  if (!selectedText) return;
  const passage = {
    sectionID: sectionWrapper.dataset.researchSectionId,
    sectionNumber: sectionWrapper.dataset.researchSectionNumber,
    title: sectionWrapper.dataset.researchSectionTitle,
    codePrefix: sectionWrapper.dataset.researchCodePrefix,
    savedItemID: sectionWrapper.dataset.researchSavedItemId || "",
    selectedText,
    codeEdition: sectionWrapper.dataset.researchCodeEdition || "",
    codeVersion: sectionWrapper.dataset.researchCodeVersion || "",
    sourceLibraryVersion: sectionWrapper.dataset.researchSourceLibraryVersion || "",
    prefix: "",
    suffix: "",
    start: 0,
    end: normalizedPassageAnchorText(selectedText).length
  };
  const panel = sectionWrapper.closest(".workspace-panel");
  const projectID = researchCreationProjectID(selectedOpenProjectID() || panel?.dataset.projectId);
  return {
    ...passage,
    passages: [passage],
    projectID,
    originPaneID: panel?.dataset.paneId || ""
  };
}

function researchConversationTitle(conversation, fallback = "New Research") {
  const title = String(conversation?.title || "").trim();
  const question = String(conversation?.starterQuestion || "").replace(/\s+/g, " ").trim();
  const automaticTitle = !title || /^(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d{1,2},\s+\d{4}\s*·/.test(title);
  if (automaticTitle && question) return question;
  if (automaticTitle && !(conversation?.messageCount || conversation?.messages?.length)) {
    return Number(conversation?.sourceCount || conversation?.sources?.length) > 0 ? "Draft with selected evidence" : "Research draft";
  }
  return String(conversation?.title || conversation?.starterQuestion || fallback).trim() || fallback;
}

function openResearchSelectionDestinations() {
  const ids = [...new Set([
    ...(researchConversationPaneIsOpen() ? [state.researchConversationID] : []),
    ...supplementalResearchConversationIDs,
    ...(state.utilityInstances || []).filter((item) => item.key === "analysis").map((item) => item.conversationID)
  ].filter(Boolean))];
  return ids.map((id) => {
    const conversation = activeResearchConversation?.id === id ? activeResearchConversation
      : supplementalResearchConversations.get(id) || researchConversationList.find((item) => item.id === id);
    return conversation && researchConversationInWorkspace(conversation)
      ? { id, title: researchConversationTitle(conversation), paneID: paneIDForResearchConversation(id) } : null;
  }).filter((item) => item && track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(item.paneID)}"]`));
}

function openResearchDestinationMenu(anchor, selection) {
  if (!selection) return;
  document.querySelector('.research-destination-menu')?._close?.();
  const workspaceID = activeWorkspaceID;
  const identity = captureAccountRequest();
  const menu = document.createElement('div');
  menu.className = 'column-group-menu research-destination-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'Research this passage');
  const controller = new AbortController();
  anchor.setAttribute('aria-haspopup', 'menu');
  anchor.setAttribute('aria-expanded', 'true');
  const close = () => {
    controller.abort();
    menu.remove();
    anchor.setAttribute('aria-expanded', 'false');
    if (anchor.isConnected) anchor.focus({ preventScroll: true });
  };
  menu._close = close;
  const add = (label, conversationID = '') => {
    const button = document.createElement('button');
    button.type = 'button';
    button.setAttribute('role', 'menuitem');
    button.textContent = label;
    button.addEventListener('click', async () => {
      close();
      if (workspaceID !== activeWorkspaceID || !isCurrentAccountRequest(identity)) return;
      anchor.disabled = true;
      try {
        if (conversationID) {
          // A destination can be closed while its menu is open.
          if (!openResearchSelectionDestinations().some((item) => item.id === conversationID)) {
            throw new Error('This Research conversation is no longer open. Reopen the menu to choose a destination.');
          }
          const conversation = await addResearchSelectionToCurrent(selection, conversationID);
          if (conversation && workspaceID === activeWorkspaceID && isCurrentAccountRequest(identity)) {
            presentWorkspaceIssue(`Added to ${researchConversationTitle(conversation)}.`, {
              actionLabel: 'View research',
              onAction: () => {
                if (workspaceID === activeWorkspaceID && isCurrentAccountRequest(identity)) {
                  scrollPaneIntoView(paneIDForResearchConversation(conversationID));
                }
              }
            });
          }
        } else {
          await startNewResearchFromSelection(selection);
        }
      } catch (error) {
        if (workspaceID === activeWorkspaceID && isCurrentAccountRequest(identity)) {
          await showWebNotice(conversationID ? 'Research evidence not added' : 'Research not started', error.message);
        }
      } finally {
        if (anchor.isConnected) anchor.disabled = false;
      }
    });
    menu.append(button);
  };
  add('＋ Start new research');
  const destinations = openResearchSelectionDestinations();
  if (destinations.length) {
    const heading = document.createElement('div');
    heading.className = 'research-destination-heading';
    heading.textContent = 'Add to existing research';
    menu.append(heading);
    destinations.forEach(({ id, title }, index) => {
      const duplicates = destinations.filter((item) => item.title === title).length > 1;
      add(`${title}${duplicates ? ` · Column ${index + 1}` : ''}${id === state.researchConversationID ? ' · Current' : ''}`, id);
    });
  }
  document.body.append(menu);
  const rect = anchor.getBoundingClientRect();
  menu.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - menu.offsetWidth - 8))}px`;
  menu.style.top = `${Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - menu.offsetHeight - 8))}px`;
  menu.addEventListener('keydown', (event) => {
    const items = [...menu.querySelectorAll('button')];
    if (event.key === 'Escape') { event.preventDefault(); close(); }
    if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
      event.preventDefault();
      const index = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1
        : (items.indexOf(document.activeElement) + (event.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length;
      items[index]?.focus();
    }
    if (event.key === 'Tab') close();
  });
  document.addEventListener('pointerdown', (event) => {
    if (!menu.contains(event.target) && event.target !== anchor) close();
  }, { signal: controller.signal });
  window.addEventListener('resize', close, { signal: controller.signal });
  menu.querySelector('button')?.focus();
}

function renderReaderChapterSection(panel, reader, section, groupLabelsByFirstSection, options = {}) {
  const sectionWrapper = document.createElement("section");
  sectionWrapper.className = "chapter-section";
  sectionWrapper.dataset.sectionId = String(section.id);
  sectionWrapper.dataset.codeVersion = syncCodeVersion(reader.codeVersion || syncCodeVersionForPrefix(reader.codePrefix));
  sectionWrapper.dataset.sectionNumber = String(section.sectionNumber || "");
  if (section.readerAliasSectionIDs.length > 0) {
    sectionWrapper.dataset.sectionAliases = section.readerAliasSectionIDs.join(" ");
  }
  markResearchSelectable(sectionWrapper, {
    sectionID: section.id,
    sectionNumber: section.sectionNumber,
    title: section.title,
    codePrefix: reader.codePrefix,
    chapterID: reader.chapterID,
    codeVersion: sectionWrapper.dataset.codeVersion,
    sourceLibraryVersion: sectionWrapper.dataset.codeVersion
  });

  const groupLabel = groupLabelsByFirstSection.get(String(section.id));
  if (groupLabel) {
    sectionWrapper.classList.add("starts-group");
    const groupHeading = document.createElement("div");
    groupHeading.className = "authored-section-label";
    groupHeading.dataset.researchSelectionExclude = "true";
    groupHeading.textContent = groupLabel;
    sectionWrapper.append(groupHeading);
  }

  const sectionHeading = document.createElement("h3");
  sectionHeading.className = "reader-section-title";
  sectionHeading.dataset.researchSelectionExclude = "true";
  sectionHeading.textContent = sectionDisplayTitle(section.sectionNumber, section.title);
  const headingRow = document.createElement("div");
  headingRow.className = "reader-section-heading-row";
  headingRow.dataset.researchSelectionExclude = "true";
  const blocks = annotatedBlocksForSection(section);
  // This render is synchronous. Share one fresh snapshot across its controls,
  // without retaining private state for later access-gate or bookmark updates.
  const privateContentAllowed = readerPrivateContentAllowed(panel);
  const savedKeys = privateContentAllowed ? workspaceSavedEvidenceKeys() : null;
  const savedWholeSectionRecord = privateContentAllowed && isSectionSaved({
    sectionID: section.id,
    codeVersion: reader.codeVersion,
    blockID: ""
  }, "", savedKeys);
  const savedSection = Boolean(savedWholeSectionRecord);
  const savedMarker = renderInlineCommentBox(section, reader, annotationTargetForSection(section, reader), {
    showBookmark: savedSection, bookmarkStateResolved: true, panel, accessGate: panel.__workspaceAccessGate, sectionMarker: true
  }).querySelector('.inline-bookmark-toggle');
  savedMarker.classList.add('reader-section-saved-marker');
  savedMarker.setAttribute('aria-label', savedSection ? 'Remove section from Evidence' : 'Save section');
  savedMarker.title = savedSection ? 'Remove section from Evidence' : 'Save section';
  headingRow.append(sectionHeading, savedMarker);
  sectionWrapper.append(headingRow);

  const appendBlock = (block, index) => {
    const target = annotationTargetForBlock(section, block, reader, index);
    const savedBlockRecord = privateContentAllowed && isSectionSaved({
      sectionID: target.sectionID,
      codeVersion: target.codeVersion,
      blockID: target.blockID
    }, "", savedKeys);
    const node = renderAnnotatedCodeBlock(block, section, reader, target, {
      showBookmark: Boolean(savedBlockRecord), bookmarkStateResolved: true, panel, accessGate: panel.__workspaceAccessGate
    });
    sectionWrapper.append(node);
    if (blocks.length > 96) {
      linkInlineCodeReferences(node, panel, reader);
      decorateReaderDefinitions(node, reader);
    }
  };
  if (blocks.length > 96) {
    sectionWrapper.classList.add("reader-large-section");
    linkInlineCodeReferences(sectionWrapper, panel, reader);
    sectionWrapper._readerBlocksReady = renderReaderBlockBatches(blocks, appendBlock, options.isCurrent || (() => true));
    return sectionWrapper;
  }
  blocks.forEach(appendBlock);
  linkInlineCodeReferences(sectionWrapper, panel, reader);
  decorateReaderDefinitions(sectionWrapper, reader);
  return sectionWrapper;
}

function collapseRepeatedReaderCatalogAliases(content) {
  let latestBodySection = null;
  let latestBodyText = "";
  content.querySelectorAll(".chapter-section").forEach((section) => {
    if (section.previousElementSibling?.classList.contains("reader-section-placeholder")) {
      latestBodySection = null;
      latestBodyText = "";
    }
    const blocks = section.querySelectorAll(".annotated-code-block");
    if (blocks.length > 0) {
      latestBodySection = section;
      latestBodyText = normalizedReaderProvisionText(
        Array.from(blocks).map((block) => block.textContent || "").join(" ")
      );
      return;
    }
    const title = normalizedReaderProvisionText(
      section.querySelector(".reader-section-title")?.textContent || ""
    );
    if (!title || !latestBodySection || !latestBodyText.includes(title)) {
      latestBodySection = null;
      latestBodyText = "";
      return;
    }
    const aliasID = String(section.dataset.sectionId || "").trim();
    const aliases = new Set(
      String(latestBodySection.dataset.sectionAliases || "").split(/\s+/).filter(Boolean)
    );
    if (aliasID) aliases.add(aliasID);
    if (aliases.size > 0) {
      latestBodySection.dataset.sectionAliases = Array.from(aliases).join(" ");
    }
    section.remove();
  });
}

function stopReaderProgressiveHydration(content) {
  content?._readerProgressiveCleanup?.();
  if (content) {
    delete content._readerProgressiveCleanup;
    cancelReaderScrollRestore(content);
  }
}

function cancelReaderPanelRequests(panel) {
  panel._readerNavigationAbort?.abort();
  cancelReaderInternalSearch(panel);
  const token = crypto.randomUUID();
  panel.dataset.readerNavigationToken = token;
  panel.dataset.readerRenderToken = token;
  panel.dataset.readerSearchToken = token;
  stopReaderProgressiveHydration(panel.querySelector(".reader-content"));
  disposeWorkspaceNodeAccess(panel);
}

async function progressivelyRenderReaderChapter(
  panel,
  reader,
  content,
  sections,
  groupLabelsByFirstSection,
  initialStart,
  initialEnd,
  renderToken,
  chapter = null
) {
  const requestController = new AbortController();
  let extent = null;
  let hydrationInFlight = false;
  let hydrationCompleted = false;
  let scrollFrame = 0;
  let connectionTimer = 0;
  let connectionWaitCount = 0;
  let stopped = false;
  const status = document.createElement("p");
  status.className = "reader-progressive-status reader-extent-status";
  status.hidden = true;
  status.dataset.researchSelectionExclude = "true";
  status.setAttribute("role", "status");
  content.append(status);

  const cleanup = () => {
    stopped = true;
    requestController.abort();
    content.removeEventListener("scroll", onScroll);
    content.removeEventListener("wheel", onScroll);
    content.removeEventListener("touchmove", onScroll);
    if (scrollFrame) cancelAnimationFrame(scrollFrame);
    if (connectionTimer) window.clearTimeout(connectionTimer);
    resizeObserver?.disconnect();
    if (content._readerChapterExtent === extent) delete content._readerChapterExtent;
    status.remove();
    scrollFrame = 0;
    connectionTimer = 0;
  };
  content._readerProgressiveCleanup = cleanup;
  const resizeObserver = new ResizeObserver(() => onScroll());
  resizeObserver.observe(content);

  const scheduleConnectionCheck = () => {
    if (connectionTimer) return;
    connectionTimer = window.setTimeout(() => {
      connectionTimer = 0;
      maybeHydrate();
    }, 16);
  };

  const updateStatus = (loading = false) => {
    const loadedCount = extent?.loadedCount ?? initialEnd - initialStart;
    status.hidden = !loading;
    status.textContent = loading
      ? `Loading nearby sections… ${loadedCount} of ${sections.length} loaded`
      : `${loadedCount} of ${sections.length} sections loaded · scroll to continue`;
  };

  const hydrateWindow = async ({ start, end }) => {
    if (hydrationInFlight) return;
    hydrationInFlight = true;
    hydrationCompleted = false;
    updateStatus(true);
    try {
      const windowChapter = await fetchChapterBodyWindow(reader.chapterID, start, end - start, chapter, { signal: requestController.signal });
      if (stopped || !panel.isConnected || panel.dataset.readerRenderToken !== renderToken) return;
      const nodes = sections.slice(start, end).map((section) =>
        renderReaderChapterSection(
          panel,
          reader,
          readerSectionWithWindowBody(section, windowChapter),
          groupLabelsByFirstSection,
          { isCurrent: () => !stopped && panel.isConnected && panel.dataset.readerRenderToken === renderToken }
        )
      );
      await Promise.all(nodes.map(node => node._readerBlocksReady));
      if (stopped || !panel.isConnected || panel.dataset.readerRenderToken !== renderToken) return;
      extent.replace(start, nodes, () => collapseRepeatedReaderCatalogAliases(content));
      hydrationCompleted = true;
      if (extent.loadedCount === sections.length) {
        content.dataset.chapterFullyLoaded = "true";
        cleanup();
        delete content._readerProgressiveCleanup;
      } else {
        updateStatus();
      }
      restorePendingReaderScrollPosition(panel);
      requestAnimationFrame(() => updateReaderScrollIndicator(panel));
    } catch (error) {
      if (!stopped && panel.isConnected && panel.dataset.readerRenderToken === renderToken) {
        if (error.code === "CHAPTER_WINDOW_MISMATCH") {
          const scrollPosition = captureReaderScrollPositions().get(panel.dataset.paneId);
          const recovery = renderSectionContent(panel, reader, { scrollPosition, corpusRecoveryAttempt: true });
          const recoveryToken = panel.dataset.readerRenderToken;
          try {
            await recovery;
          } catch {
            if (panel.isConnected && panel.dataset.readerRenderToken === recoveryToken) {
              emptyReader(content, "Couldn’t refresh this chapter", "Check your connection and select the chapter again.");
            }
          }
          return;
        }
        status.hidden = false;
        status.textContent = "Nearby sections could not be loaded. Scroll again to retry.";
        console.warn("Reader chapter hydration paused.", error);
      }
    } finally {
      hydrationInFlight = false;
      if (hydrationCompleted && status.isConnected) maybeHydrate();
    }
  };

  const maybeHydrate = () => {
    scrollFrame = 0;
    if (stopped) return;
    if (!panel.isConnected) {
      if (connectionWaitCount < 120) {
        connectionWaitCount += 1;
        scheduleConnectionCheck();
      } else {
        cleanup();
      }
      return;
    }
    connectionWaitCount = 0;
    if (panel.dataset.readerRenderToken !== renderToken) {
      cleanup();
      return;
    }
    if (!content.clientWidth || !content.clientHeight) return;
    if (!extent) {
      extent = createReaderChapterExtent(content, sections, initialStart, initialEnd, chapter);
      content._readerChapterExtent = extent;
      // Selected middle/end sections now have reserved space before them.
      // Their existing navigation/restoration callbacks align the actual text.
    }
    if (hydrationInFlight) return;
    const threshold = Math.max(320, content.clientHeight * 0.6);
    const window = extent.nextWindow(readerProgressiveSectionBatchSize, threshold);
    if (window) void hydrateWindow(window);
    else if (extent.loadedCount === sections.length) {
      content.dataset.chapterFullyLoaded = "true";
      cleanup();
      delete content._readerProgressiveCleanup;
    }
  };

  function onScroll() {
    if (stopped || scrollFrame) return;
    scrollFrame = requestAnimationFrame(maybeHydrate);
  }

  content.addEventListener("scroll", onScroll, { passive: true });
  // Retrying must also work at a scroll boundary where a wheel/touch gesture
  // cannot change scrollTop and therefore produces no scroll event.
  content.addEventListener("wheel", onScroll, { passive: true });
  content.addEventListener("touchmove", onScroll, { passive: true });
  updateStatus();
  maybeHydrate();
}

async function renderSectionContent(panel, reader, options = {}) {
  cancelReaderInternalSearch(panel);
  delete panel._readerSearchReturnPosition;
  panel.dataset.readerSearchToken = `reader:${crypto.randomUUID()}`;
  panel.dataset.workspacePaneIdentity = workspaceReaderContentIdentity(reader);
  const content = panel.querySelector(".reader-content");
  stopReaderProgressiveHydration(content);
  content?.classList.remove("is-searching-reader");
  delete panel.dataset.readerContentKey;
  delete panel.dataset.readerPublicCorpusGeneration;
  if (content) delete content.dataset.chapterFullyLoaded;
  if (!reader.chapterID) {
    blankReader(content);
    return;
  }

  const renderToken = crypto.randomUUID();
  panel.dataset.readerRenderToken = renderToken;
  clear(content);
  emptyReader(content, "Loading section", "Opening the selected code text first.");
  let chapter = await fetchChapter(reader.chapterID, { signal: panel._readerNavigationAbort?.signal });
  if (panel.dataset.readerRenderToken !== renderToken) return;
  if (options.expectedCorpusRevision && chapter.corpusRevision !== options.expectedCorpusRevision) {
    for (const key of chapterCache.keys()) {
      if (key.startsWith(`${reader.chapterID}:`)) chapterCache.delete(key);
    }
    chapter = await fetchChapter(reader.chapterID, { signal: panel._readerNavigationAbort?.signal });
    if (panel.dataset.readerRenderToken !== renderToken) return;
    if (chapter.corpusRevision !== options.expectedCorpusRevision) {
      emptyReader(content, "Code text changed", "Search this chapter again to open a match in the updated text.");
      return;
    }
  }
  if ((chapter.codePrefix && chapter.codePrefix !== reader.codePrefix) ||
      (chapter.codeVersion && syncCodeVersion(chapter.codeVersion) !==
        syncCodeVersion(reader.codeVersion || syncCodeVersionForPrefix(reader.codePrefix)))) {
    const error = new Error("The chapter does not belong to the selected code source.");
    error.code = "READER_SOURCE_MISMATCH";
    throw error;
  }
  setReaderDefinitionContext(reader, chapter, syncCodeVersion(reader.codeVersion || syncCodeVersionForPrefix(reader.codePrefix)));
  // Window offsets belong to the complete manifest. Collapsing aliases before
  // hydration shifts those offsets when a full-body chapter is already cached.
  // DOM alias collapse still runs after rendering the hydrated sections.
  const sections = (chapter.sections || []).map((section) => ({
    ...section,
    blocks: [],
    readerAliasSectionIDs: [],
    codePrefix: section.codePrefix || chapter.codePrefix
  }));
  if (!sections.length) {
    emptyReader(content, "No sections", "This chapter does not contain readable sections.");
    return;
  }
  const scrollPosition = readerScrollPositionFor(reader, options.scrollPosition, sections);
  const resolvedTarget = readerTargetSectionIndex(sections, reader);
  if (options.corpusRecoveryAttempt && reader.sectionID && resolvedTarget < 0) {
    emptyReader(content, "Section changed", "The selected section is no longer in this chapter. Choose it again from the chapter list.");
    return;
  }
  const targetIndex = scrollPosition?.sectionIndex ?? Math.max(0, resolvedTarget);
  const maximumInitialStart = Math.max(0, sections.length - readerInitialSectionWindowSize);
  const initialStart = Math.min(
    Math.max(0, targetIndex - Math.floor(readerInitialSectionWindowSize / 2)),
    maximumInitialStart
  );
  const initialEnd = Math.min(sections.length, initialStart + readerInitialSectionWindowSize);
  let initialChapter;
  try {
    initialChapter = await fetchChapterBodyWindow(
      reader.chapterID, initialStart, initialEnd - initialStart, chapter,
      { signal: panel._readerNavigationAbort?.signal }
    );
  } catch (error) {
    if (panel.dataset.readerRenderToken !== renderToken) return;
    if (error.code === "CHAPTER_WINDOW_MISMATCH" && !options.corpusRecoveryAttempt) {
      return renderSectionContent(panel, reader, { ...options, corpusRecoveryAttempt: true });
    }
    throw error;
  }
  if (panel.dataset.readerRenderToken !== renderToken) return;
  const acceptedPublicGeneration = publicCodeRevision.generation;
  const groupLabelsByFirstSection = groupLabelsForChapter(chapter);
  clear(content);
  const initialSections = sections.slice(initialStart, initialEnd).map((section) =>
    readerSectionWithWindowBody(section, initialChapter)
  );
  const initialNodes = initialSections.map((section) => {
    const node = renderReaderChapterSection(
        panel,
        reader,
        section,
        groupLabelsByFirstSection,
        { isCurrent: () => panel.dataset.readerRenderToken === renderToken && !panel._readerNavigationAbort?.signal.aborted }
      );
    content.append(node);
    return node;
  });
  await Promise.all(initialNodes.map(node => node._readerBlocksReady));
  if (panel.dataset.readerRenderToken !== renderToken) return;
  cacheRecentlyViewedReaderPreview(reader, initialSections[targetIndex - initialStart]);
  collapseRepeatedReaderCatalogAliases(content);
  panel.dataset.readerContentKey = readerContentScrollKey(reader);
  panel.dataset.readerPublicCorpusGeneration = String(acceptedPublicGeneration);

  if (reader.sectionID && !scrollPosition) {
    requestAnimationFrame(() => {
      if (panel.dataset.readerRenderToken !== renderToken) return;
      const behavior = reader.shouldSmoothScrollToSection ? "smooth" : "auto";
      const highlightQuery = reader.pendingSearchHighlightQuery || panel.dataset.pendingSearchHighlightQuery || "";
      const highlightBlockID = reader.pendingSearchHighlightBlockID || panel.dataset.pendingSearchHighlightBlockId || "";
      if (!highlightBlockID) {
        scrollReaderContentToSection(content, reader.sectionID, behavior, reader.sectionNumber);
      }
      if (highlightQuery) {
        reader.pendingSearchHighlightQuery = "";
        reader.pendingSearchHighlightBlockID = "";
        delete panel.dataset.pendingSearchHighlightQuery;
        delete panel.dataset.pendingSearchHighlightBlockId;
        window.setTimeout(() => {
          if (panel.dataset.readerRenderToken !== renderToken) return;
          flashSearchMatchInSection(content, reader.sectionID, reader.sectionNumber, highlightQuery, highlightBlockID);
        }, highlightBlockID ? 0 : (behavior === "smooth" ? 520 : 0));
      }
      reader.shouldSmoothScrollToSection = false;
    });
  }
  void progressivelyRenderReaderChapter(
    panel,
    reader,
    content,
    sections,
    groupLabelsByFirstSection,
    initialStart,
    initialEnd,
    renderToken,
    chapter
  );
}

function scrollReaderContentToSection(content, sectionID, behavior = "auto", sectionNumber = "") {
  const idSelector = sectionID ? `[data-section-id="${CSS.escape(String(sectionID))}"]` : "";
  const aliasSelector = sectionID ? `[data-section-aliases~="${CSS.escape(String(sectionID))}"]` : "";
  const numberSelector = sectionNumber ? `[data-section-number="${CSS.escape(String(sectionNumber))}"]` : "";
  const target = (idSelector ? content?.querySelector(idSelector) : null) ||
    (aliasSelector ? content?.querySelector(aliasSelector) : null) ||
    (numberSelector ? content?.querySelector(numberSelector) : null);
  if (!content || !target) return;
  stabilizeReaderSectionAtHeader(content, target, behavior);
}

function savedReaderTarget(content, item, options = {}) {
  if (!content || !item) return null;
  const sectionID = String(item.sectionID || item.id || "").trim();
  const sectionNumber = String(item.sectionNumber || "").trim();
  const blockID = normalizeAnnotationBlockID(item.blockID || item.annotationBlockID);
  const idSelector = sectionID
    ? `.chapter-section[data-section-id="${CSS.escape(sectionID)}"]`
    : "";
  const aliasSelector = sectionID
    ? `.chapter-section[data-section-aliases~="${CSS.escape(sectionID)}"]`
    : "";
  const numberSelector = sectionNumber
    ? `.chapter-section[data-section-number="${CSS.escape(sectionNumber)}"]`
    : "";
  const sectionTarget = (idSelector ? content.querySelector(idSelector) : null) ||
    (aliasSelector ? content.querySelector(aliasSelector) : null) ||
    (numberSelector ? content.querySelector(numberSelector) : null);
  // Whole-section bookmarks target the heading and all of its content.
  // Paragraph bookmarks continue through the exact block lookup below.
  if (!blockID && sectionTarget && !options.preferPassage) return sectionTarget;
  if (blockID) {
    const sectionBlockSelector = sectionID
      ? `.annotated-code-block[data-section-id="${CSS.escape(sectionID)}"][data-block-id="${CSS.escape(blockID)}"]`
      : "";
    const blockSelector = `.annotated-code-block[data-block-id="${CSS.escape(blockID)}"]`;
    const blockTarget = (sectionBlockSelector ? content.querySelector(sectionBlockSelector) : null) ||
      content.querySelector(blockSelector);
    if (blockTarget) return blockTarget;
  }
  const savedTitle = String(item.title || "").replace(/\s+/g, " ").trim().toLocaleLowerCase();
  // Catalog title aliases can name a numbered list item inside a larger source
  // section. Its authored HTML generates the list number outside textContent.
  const passageTitle = options.preferPassage && sectionTarget?.dataset.sectionAliases?.split(/\s+/).includes(sectionID)
    ? savedTitle.replace(/^\d+(?:\.\d+)*\.?\s+/, "") : savedTitle;
  const sectionTitle = String(
    readerSectionTitleNode(sectionTarget)?.textContent || sectionTarget?.dataset.sectionTitle || ""
  ).replace(/\s+/g, " ").trim().toLocaleLowerCase();
  if (
    sectionTarget &&
    savedTitle.length >= 12 &&
    sectionTitle.length >= 12 &&
    (sectionTitle.includes(savedTitle) || savedTitle.includes(sectionTitle))
  ) {
    return readerSectionTitleNode(sectionTarget);
  }
  if (savedTitle.length >= 12) {
    const exactTextBlock = Array.from(
      (sectionTarget || content).querySelectorAll(".annotated-code-block")
    ).find((candidate) => {
      const codeBody = candidate.querySelector(
        ":scope > .section-block, :scope > .section-html, :scope > .code-table, :scope > .code-media"
      ) || candidate;
      const candidateText = String(codeBody.textContent || "").replace(/\s+/g, " ").trim().toLocaleLowerCase();
      return candidateText.length >= 12 && passageTitle.length >= 12 &&
        (candidateText.includes(passageTitle) || passageTitle.includes(candidateText));
    });
    if (exactTextBlock) return exactTextBlock;
  }
  return sectionTarget;
}

function alignSavedReaderTargetAtTop(reader, item) {
  const paneID = paneIDForReader(reader);
  [0, 80, 220].forEach((delay) => {
    window.setTimeout(() => {
      const panel = track.querySelector(
        `.reader-panel[data-pane-id="${CSS.escape(paneID)}"]`
      );
      const content = panel?.querySelector(".reader-content");
      const target = savedReaderTarget(content, item);
      if (!content || !target) return;
      scrollReaderContentToNode(content, target, "auto");
    }, delay);
  });
}

function alignReaderSectionAfterLayout(reader) {
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const panel = track.querySelector(
        `.reader-panel[data-pane-id="${CSS.escape(paneIDForReader(reader))}"]`
      );
      const content = panel?.querySelector(".reader-content");
      if (!content) return;
      scrollReaderContentToSection(content, reader.sectionID, "auto", reader.sectionNumber);
    });
  });
}

async function navigateReaderToSection(panel, reader, behavior = "auto") {
  panel.dataset.workspacePaneIdentity = workspaceReaderContentIdentity(reader);

  setTitle(panel, reader);
  const sectionSelect = panel.querySelector(".section-select");
  if (sectionSelect) sectionSelect.value = reader.sectionID || "";

  const content = panel.querySelector(".reader-content");
  const isSearchMode = content?.classList.contains("is-searching-reader");
  const hasRenderedTarget = reader.sectionID && (
    content?.querySelector(`[data-section-id="${CSS.escape(String(reader.sectionID))}"]`) ||
    content?.querySelector(`[data-section-aliases~="${CSS.escape(String(reader.sectionID))}"]`) ||
    (reader.sectionNumber
      ? content?.querySelector(`[data-section-number="${CSS.escape(String(reader.sectionNumber))}"]`)
      : null)
  );
  if (!content || isSearchMode || (reader.sectionID && !hasRenderedTarget)) {
    await renderSectionContent(panel, reader);
    return;
  }
  panel.dataset.readerContentKey = readerContentScrollKey(reader);
  scrollReaderContentToSection(content, reader.sectionID, behavior, reader.sectionNumber);
}

function renderAnnotatedCodeBlock(block, section, reader, target, options = {}) {
  const wrapper = document.createElement("div");
  wrapper.className = "annotated-code-block";
  wrapper.dataset.sectionId = String(target.sectionID || "");
  wrapper.dataset.sectionNumber = target.sectionNumber || "";
  wrapper.dataset.sectionTitle = target.title || "";
  wrapper.dataset.blockId = target.blockID || "";
  wrapper.dataset.blockLabel = target.blockLabel || "";
  wrapper.append(renderCodeBlock(block), renderInlineCommentBox(section, reader, target, options));
  return wrapper;
}

function readerPassagePayload(section, reader, target) {
  return {
    codeVersion: target.codeVersion,
    sectionID: section.id,
    sectionNumber: section.sectionNumber,
    title: section.title,
    codePrefix: reader?.codePrefix || "BC",
    chapterID: reader?.chapterID || "",
    chapterNumber: section.chapterNumber || "",
    blockID: normalizeAnnotationBlockID(target.blockID),
    blockLabel: target.blockLabel || ""
  };
}

function closeSectionSaveProjectSheet(panel, focusTarget = null) {
  panel?.__sectionProjectMenu?._close?.();
  panel?.querySelector(".section-save-project-sheet")?.remove();
  if (focusTarget?.isConnected) focusTarget.focus({ preventScroll: true });
}

function showSectionProjectAssignment(panel, sectionPayload, focusTarget = null, options = {}) {
  if (!readerPrivateContentAllowed(panel)) return;
  if (!hasCapability("projects")) {
    void presentPlanLimitNotice("Projects require Pro", "Upgrade to Pro to organize saved work in Projects.");
    return;
  }
  if (!panel || !sectionPayload?.sectionID) return;
  if (!options.chooseDestination && workspaceProject()) {
    void persistSectionInProject(workspaceProject(), sectionPayload);
    return;
  }
  if (panel.classList.contains("section-detail-panel")) {
    showSectionDetailProjectMenu(panel, sectionPayload, focusTarget);
    return;
  }
  closeSectionSaveProjectSheet(panel);
  const sheet = document.createElement("section");
  sheet.className = "section-save-project-sheet";
  sheet.setAttribute("role", "region");
  sheet.setAttribute("aria-label", "Add saved evidence to a Project or saved collection");
  sheet.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    closeSectionSaveProjectSheet(panel, focusTarget);
  });
  panel.append(sheet);
  showReaderNotesProjectPicker(sheet, sectionPayload, {
    onClose: () => {
      if (panel.querySelector(".section-save-project-sheet") !== sheet) return;
      closeSectionSaveProjectSheet(panel, focusTarget);
    }
  });
}

function showReaderSaveConfirmation(panel, sectionPayload, options = {}) {
  if (!panel) return;
  panel.querySelector(".reader-save-confirmation")?.remove();
  const confirmation = document.createElement("div");
  confirmation.className = "reader-save-confirmation";
  const message = document.createElement("span");
  message.setAttribute("role", "status");
  message.setAttribute("aria-live", "polite");
  message.textContent = "Saved";
  const projectButton = document.createElement("button");
  projectButton.type = "button";
  projectButton.textContent = "Add to Project";
  const project = workspaceProject();
  const savedInProject = project && (currentContentSummary().projectSections || []).some((link) =>
    savedEvidenceKey(link) === savedEvidenceKey(sectionPayload) && projectSectionBelongsToProject(link, project));
  if (savedInProject) {
    message.textContent = `Saved to ${project.name || project.title || "Project"}`;
    projectButton.textContent = "Manage Projects";
  }
  const queued = (state.syncOutbox || []).some(entry => {
    const {kind, record} = mutationKindAndRecord(entry.mutation);
    return ["savedItem", "projectSection"].includes(kind) && savedEvidenceKey(record) === savedEvidenceKey(sectionPayload);
  });
  if (queued) message.textContent = "Saved on this device · waiting to sync";
  confirmation.append(message, projectButton);
  panel.append(confirmation);
  let removeTimer = null;
  const dismissConfirmation = () => {
    if (!confirmation.isConnected || confirmation.classList.contains("is-leaving")) return;
    confirmation.classList.add("is-leaving");
    removeTimer = window.setTimeout(() => confirmation.remove(), 180);
  };
  const dismissTimer = window.setTimeout(dismissConfirmation, 5020);
  projectButton.addEventListener("click", () => {
    window.clearTimeout(dismissTimer);
    window.clearTimeout(removeTimer);
    confirmation.remove();
    showSectionProjectAssignment(panel, sectionPayload, options.focusTarget || null);
  });
}

async function saveReaderPassage(panel, section, reader, target, options = {}) {
  if (!readerPrivateContentAllowed(panel)) return false;
  const payload = readerPassagePayload(section, reader, target);
  if (!hasCapability("saved-work")) return persistSectionBookmark(payload, true);
  const alreadySaved = isSectionSaved(payload);
  if (!alreadySaved) {
    const saved = await persistSectionBookmark(payload, true, { refreshSavedPanes: false });
    if (!saved) return false;
    await refreshOpenSavedPanes();
    syncReaderNoteBookmarkButtons(section.id, true, target.codeVersion);
  }
  showReaderSaveConfirmation(panel, payload, options);
  return true;
}

async function addPassageToNotebook(anchor, source, exact) {
  const project = workspaceProject();
  if (!project) throw new Error("Create a Project before adding a passage to a Note.");
  if (!String(exact || "").trim()) throw new Error("The passage is still loading. Try again.");
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const generation = state.workflowNavigationGeneration || 0;
  const current = () => isCurrentAccountRequest(identity) && anchor.isConnected && activeWorkspaceID === workspaceID &&
    generation === (state.workflowNavigationGeneration || 0);
  const projectID = researchProjectID(project);
  const mount = notebookMounts.get(projectID);
  const target = mount?.insertionTarget?.();
  const destination = await openWebWarning({ title: "Add to note", message: "Keep a link to this exact passage and its code edition.",
    confirmLabel: "Add to note", choiceLabel: "Destination Note", container: anchor.closest(".workspace-panel"),
    choices: [...(target ? [{ value: "current", label: target.title || "Untitled Note" }] : []), { value: "new", label: "New Note" }] });
  if (!destination || !current()) return;
  const label = `${source.codePrefix} · ${researchCodeEdition(source)} · § ${source.sectionNumber} · ${source.title}`;
  const link = { id: crypto.randomUUID(), label, relationshipRole: "context", projectID,
    source: { ...source, sourceID: String(source.sectionID), sectionID: String(source.sectionID),
      sectionTitle: source.title, codeEdition: researchCodeEdition(source), sourceLibraryVersion: source.codeVersion },
    passages: [{ exact: String(exact).trim() }], createdAt: new Date().toISOString() };
  const reference = { referenceKind: "selectedPassage", referenceID: link.id, label };
  if (destination === "current") {
    await mount.insertLinkedReference(target.id, reference, link);
    return;
  }
  if (navigator.onLine === false) throw new Error("Reconnect to create a Note.");
  const document = emptyNotebookDocument();
  document.document = [{ type: "paragraph", content: [{ type: "permitextReference", props: reference }] }];
  const payload = await postResearch("/notebook/cards/save", { projectID, clientMutationID: `passage-note:${link.id}`,
    expectedVersion: 0, cardType: "finding", title: source.title.slice(0, 300), document, evidenceLinks: [link] });
  requireCurrentAccountRequest(identity);
  await saveNotebookCardSnapshot(identity.userID, projectID, payload.card);
  if (!current()) return;
  const paneID = paneIDForProjectNotebook(project);
  requestLinkedPanePlacement(anchor.closest(".workspace-panel")?.dataset.paneId, paneID);
  if (!await openProjectNotebook(project) || !current()) return;
  if (!await whenWorkspacePaneReady(paneID) || !current()) return;
  const destinationMount = notebookMounts.get(projectID);
  await destinationMount?.refreshCards?.();
  if (current()) await destinationMount?.focusCard?.(payload.card.id);
}

function renderInlineCommentBox(section, reader, target = annotationTargetForSection(section, reader), options = {}) {
  const gate = options.accessGate || options.panel?.__workspaceAccessGate || null;
  const allowed = () => (!gate || gate.allowed) &&
    (!options.panel || options.panel.__workspaceAccessGate === gate || (!gate && !options.panel.__workspaceAccessGate));
  const wrapper = document.createElement("section");
  wrapper.className = "inline-comment";
  wrapper.dataset.commentSectionId = String(section.id);
  wrapper.dataset.commentCodeVersion = syncCodeVersion(target.codeVersion);
  wrapper.dataset.commentBlockId = target.blockID || "";
  wrapper.dataset.researchSelectionExclude = "true";

  // Keep stable control nodes even while pending: section headings extract the
  // bookmark from this wrapper before their public text is mounted.
  const bookmarkButton = document.createElement("button");
  bookmarkButton.type = "button";
  bookmarkButton.className = "inline-bookmark-toggle";
  const researchButton = document.createElement("button");
  researchButton.type = "button";
  researchButton.className = "inline-research-toggle";
  const noteButton = document.createElement("button");
  noteButton.type = "button";
  noteButton.className = "inline-note-toggle";
  noteButton.innerHTML = noteAddIconSVG();
  noteButton.setAttribute("aria-label", "Add to note");
  noteButton.title = "Add this passage to a Note";
  noteButton.addEventListener("click", async () => {
    if (!allowed() || noteButton.disabled) return;
    noteButton.disabled = true;
    try {
      const passage = noteButton.closest(".annotated-code-block") || noteButton.closest(".chapter-section");
      const copy = passage?.cloneNode(true);
      copy?.querySelectorAll("[data-research-selection-exclude], .inline-bookmark-toggle").forEach(node => node.remove());
      await addPassageToNotebook(noteButton, readerPassagePayload(section, reader, target), copy?.textContent);
    } catch (error) {
      if (allowed()) await showWebNotice("Passage not added", error.message);
    } finally { noteButton.disabled = !allowed(); }
  });
  const updateResearchControl = () => {
    if (!allowed()) return;
    researchButton.innerHTML = researchActionIconSVG();
    researchButton.setAttribute("aria-label", "Research this passage");
    researchButton.setAttribute("aria-haspopup", "menu");
    researchButton.title = "Start research or add this passage to an open conversation";
    researchButton.disabled = false;
  };
  let subscribingToAccess = true;
  const updatePrivateControls = (initialRender = false) => {
    const permitted = allowed();
    noteButton.hidden = !permitted || !hasCapability("notebook");
    noteButton.disabled = !permitted;
    bookmarkButton.hidden = !permitted;
    bookmarkButton.disabled = !permitted;
    researchButton.hidden = !permitted;
    researchButton.disabled = !permitted;
    if (!permitted) return;
    const saved = gate && !(options.bookmarkStateResolved && (initialRender === true || subscribingToAccess)) ? Boolean(isSectionSaved({
      sectionID: target.sectionID || section.id,
      codeVersion: target.codeVersion,
      blockID: target.blockID || ""
    })) : Boolean(options.showBookmark);
    wrapper.classList.toggle("has-saved-section", saved);
    bookmarkButton.classList.toggle("is-saved", saved);
    bookmarkButton.innerHTML = bookmarkIconSVG(saved);
    const bookmarkLabel = options.sectionMarker
      ? (saved ? "Remove section from Evidence" : "Save section")
      : bookmarkActionLabel(saved);
    bookmarkButton.setAttribute("aria-label", bookmarkLabel);
    bookmarkButton.title = bookmarkLabel;
    updateResearchControl();
  };
  updatePrivateControls(true);
  if (gate) subscribeWorkspaceNodeAccess(bookmarkButton, gate, updatePrivateControls, options.panel || wrapper);
  subscribingToAccess = false;

  bookmarkButton.addEventListener("click", async () => {
    if (!allowed() || bookmarkButton.disabled) return;
    const removingSavedPassage = bookmarkButton.classList.contains("is-saved");
    bookmarkButton.disabled = true;
    bookmarkButton.setAttribute("aria-busy", "true");
    bookmarkButton.title = removingSavedPassage ? "Removing…" : "Saving…";
    try {
      if (removingSavedPassage) {
        const payload = readerPassagePayload(section, reader, target);
        await persistSectionBookmark(payload, false, { undoPaneID: bookmarkButton.closest(".workspace-panel")?.dataset.paneId });
        if (allowed()) syncReaderNoteBookmarkButtons(section.id, false, target.codeVersion);
        return;
      }
      const panel = options.panel || bookmarkButton.closest(".reader-panel");
      const savedPassage = await saveReaderPassage(panel, section, reader, target, { focusTarget: bookmarkButton });
      if (!savedPassage || !allowed()) return;
      bookmarkButton.classList.add("is-saved");
      bookmarkButton.innerHTML = bookmarkIconSVG(true);
      const label = options.sectionMarker ? "Remove section from Evidence" : bookmarkActionLabel(true);
      bookmarkButton.setAttribute("aria-label", label);
      bookmarkButton.title = label;
    } catch (error) {
      if (allowed()) presentWorkspaceIssue(error.message || "Could not save this passage. Try again.");
    } finally {
      bookmarkButton.removeAttribute("aria-busy");
      bookmarkButton.disabled = !allowed();
    }
  });

  researchButton.addEventListener("click", () => {
    if (!allowed() || researchButton.disabled) return;
    const sectionWrapper = researchButton.closest(".chapter-section");
    if (!sectionWrapper) return;
    const passage = researchButton.closest(".annotated-code-block") || sectionWrapper;
    openResearchDestinationMenu(researchButton, readerSectionResearchSelection(sectionWrapper, passage));
  });
  wrapper.append(bookmarkButton, researchButton, noteButton);
  return wrapper;
}

function sectionNoteKey(sectionID) {
  return String(sectionID || "");
}

function noteValueForSection(sectionID) {
  return noteValueForTarget(sectionID, "");
}

function setSectionNoteValue(sectionID, value) {
  return setAnnotationNoteValue({ sectionID, codeVersion: defaultSyncCodeVersion, blockID: "" }, value);
}

function syncReaderNoteControls(sectionID, blockID, value, options = {}) {
  const sectionKey = sectionNoteKey(sectionID);
  if (!sectionKey) return;
  const bookmarkCodeVersion = options.codeVersion || options.target?.codeVersion || defaultSyncCodeVersion;
  // Bookmark refresh derives its exact target after checking each panel gate.
  syncReaderNoteBookmarkButtons(sectionID, false, bookmarkCodeVersion);
}

function removeReaderNotesProjectPicker(sheet) {
  sheet?.querySelector(".reader-notes-project-picker")?.remove();
}

function showSectionDetailProjectMenu(panel, sectionPayload, anchor, options = {}) {
  const wasOpen = Boolean(panel.__sectionProjectMenu);
  closeSectionSaveProjectSheet(panel);
  if (wasOpen || !anchor?.isConnected) return;
  document.querySelector(".section-detail-project-menu")?._close?.();
  closeWorkspaceContextMenu();
  document.querySelector(".column-group-menu")?._close?.();
  const workspaceID = activeWorkspaceID;
  const identity = captureAccountRequest();
  const menu = document.createElement("div");
  menu.className = "workspace-context-menu section-detail-project-menu";
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-label", "Add to Project");
  const controller = new AbortController();
  const observer = new MutationObserver(() => {
    if (!isCurrent()) close();
  });
  const isCurrent = () => panel.isConnected && menu.isConnected &&
    workspaceID === activeWorkspaceID && isCurrentAccountRequest(identity) && readerPrivateContentAllowed(panel);
  const close = (restoreFocus = false) => {
    controller.abort();
    observer.disconnect();
    menu.remove();
    if (panel.__sectionProjectMenu === menu) delete panel.__sectionProjectMenu;
    anchor.setAttribute("aria-expanded", "false");
    if (restoreFocus && anchor.isConnected) anchor.focus({ preventScroll: true });
  };
  menu._close = close;
  const position = () => {
    if (!isCurrent()) { close(); return; }
    const rect = anchor.getBoundingClientRect();
    const panelRect = panel.getBoundingClientRect();
    const width = menu.offsetWidth;
    const fitsColumn = panelRect.width >= width + 16;
    const leftLimit = Math.max(8, fitsColumn ? panelRect.left + 8 : 8);
    const rightLimit = Math.min(window.innerWidth - 8, fitsColumn ? panelRect.right - 8 : window.innerWidth - 8);
    menu.style.left = `${Math.max(8, Math.min(Math.max(leftLimit, rect.right - width), rightLimit - width))}px`;
    menu.style.top = `${Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - menu.offsetHeight - 8))}px`;
  };
  document.body.append(menu);
  panel.__sectionProjectMenu = menu;
  anchor.setAttribute("aria-expanded", "true");
  showSectionDetailProjectPicker(menu, sectionPayload, {
    ...options,
    menu: true,
    detailPanel: panel,
    isCurrent,
    onClose: () => close(true),
    onLayoutChange: () => {
      const editing = Boolean(menu.querySelector("form"));
      menu.setAttribute("role", editing ? "dialog" : "menu");
      menu.setAttribute("aria-label", editing ? "New Project" : "Add to Project");
      position();
    }
  });
  position();
  menu.addEventListener("keydown", event => {
    if (event.key === "Escape") { event.preventDefault(); close(true); return; }
    if (menu.querySelector("form")) return;
    const items = [...menu.querySelectorAll("button:not(:disabled)")];
    if (items.length && ["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      const index = event.key === "Home" ? 0 : event.key === "End" ? items.length - 1
        : (items.indexOf(document.activeElement) + (event.key === "ArrowDown" ? 1 : items.length - 1)) % items.length;
      items[index]?.focus();
    }
    if (event.key === "Tab") close(true);
  });
  document.addEventListener("pointerdown", event => {
    if (!menu.contains(event.target) && !anchor.contains(event.target)) close();
  }, { signal: controller.signal });
  window.addEventListener("resize", () => close(), { signal: controller.signal });
  track.addEventListener("scroll", () => close(), { capture: true, signal: controller.signal });
  observer.observe(track, { childList: true, subtree: true });
}

function showSectionDetailProjectPicker(sheet, sectionPayload, options = {}) {
  removeReaderNotesProjectPicker(sheet);
  const projects = activeFolderRecords(currentContentSummary().projects || []).filter(folderIsProject);
  const picker = document.createElement("section");
  picker.className = "reader-notes-project-picker section-detail-project-picker";
  picker.setAttribute("aria-label", "Choose a Project");
  const projectList = document.createElement("div");
  projectList.className = "reader-notes-project-options";
  projectList.setAttribute("role", "group");
  projectList.setAttribute("aria-label", "Projects");
  const status = document.createElement("p");
  status.className = "reader-notes-project-status";
  status.setAttribute("role", "status");
  const detailPanel = options.detailPanel || sheet.closest(".section-detail-panel");
  const bookmark = detailPanel?.querySelector(".section-detail-save");
  const isCurrent = () => !options.isCurrent || options.isCurrent();
  let busy = false;
  const setBusy = (value) => {
    busy = value;
    picker.querySelectorAll("button, input").forEach((control) => { control.disabled = value; });
    if (bookmark) bookmark.disabled = value || !readerPrivateContentAllowed(detailPanel);
  };
  const addToProject = async (project) => {
    if (busy || !isCurrent()) return;
    setBusy(true);
    status.textContent = "Adding…";
    try {
      // Only the chosen Project is visible to this additive operation, so
      // links to other Projects and existing collections remain intact.
      const result = options.onAssign
        ? await options.onAssign(project)
        : await persistSectionFolderSelection(sectionPayload, [project], [project]);
      if (!result.saved) {
        status.textContent = "The passage could not be added. Please try again.";
        return;
      }
      if (!isCurrent()) return;
      syncReaderNoteBookmarkButtons(sectionPayload.sectionID, true, sectionPayload.codeVersion);
      sheet.dispatchEvent(new CustomEvent("permitext-folder-save", {
        detail: { saved: true, folders: [project] }
      }));
      refreshOpenAnnotationProjectEditors();
      removeReaderNotesProjectPicker(sheet);
      options.onClose?.({ saved: true, folders: [project] });
    } catch (error) {
      status.textContent = error.message || "The passage could not be added. Please try again.";
    } finally {
      setBusy(false);
    }
  };
  const appendProject = (project) => {
    const button = document.createElement("button");
    button.type = "button";
    if (options.menu) button.setAttribute("role", "menuitem");
    button.className = "section-detail-project-option";
    button.textContent = project.name || project.title || "Untitled Project";
    button.setAttribute("aria-label", `Add passage to ${button.textContent}`);
    button.addEventListener("click", () => { void addToProject(project); });
    projectList.append(button);
  };
  projects.forEach(appendProject);
  const createProject = document.createElement("button");
  createProject.type = "button";
  createProject.className = "reader-notes-new-project section-detail-project-create";
  createProject.textContent = "New Project…";
  if (options.menu) createProject.setAttribute("role", "menuitem");
  createProject.addEventListener("click", () => {
    if (busy || !isCurrent() || picker.querySelector("form")) return;
    createProject.hidden = true;
    const form = document.createElement("form");
    form.className = "reader-notes-new-project-form section-detail-project-create";
    const input = document.createElement("input");
    input.type = "text";
    input.placeholder = "Project name";
    input.setAttribute("aria-label", "New Project name");
    const createButton = document.createElement("button");
    createButton.type = "submit";
    createButton.textContent = "Create and add";
    form.append(input, createButton);
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (busy || !isCurrent() || !input.value.trim()) return;
      setBusy(true);
      status.textContent = "Creating…";
      let project;
      try {
        project = await createProjectFolder({ name: input.value.trim(), folderType: "project" });
        if (!isCurrent()) return;
        if (!project) {
          status.textContent = "The Project could not be created. Please try again.";
          return;
        }
        appendProject(project);
        form.remove();
        createProject.hidden = false;
        options.onLayoutChange?.();
      } catch (error) {
        status.textContent = error.message || "The Project could not be created. Please try again.";
      } finally {
        setBusy(false);
      }
      if (project) await addToProject(project);
    });
    createProject.after(form);
    options.onLayoutChange?.();
    input.focus();
  });
  const actions = document.createElement("div");
  actions.className = "reader-notes-project-picker-actions";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.textContent = "Cancel";
  cancelButton.addEventListener("click", () => {
    if (busy) return;
    removeReaderNotesProjectPicker(sheet);
    options.onClose?.({ saved: false, folders: [] });
  });
  actions.append(cancelButton);
  picker.append(projectList, createProject, status);
  if (!options.menu) picker.append(actions);
  sheet.prepend(picker);
  requestAnimationFrame(() => {
    if (!sheet.isConnected) return;
    (projectList.querySelector("button") || createProject).focus({ preventScroll: true });
  });
}

function showReaderNotesProjectPicker(sheet, sectionPayload, options = {}) {
  removeReaderNotesProjectPicker(sheet);
  if (sheet.getBoundingClientRect().height < 440) {
    sheet.style.setProperty("--reader-notes-height", "440px");
  }
  const projects = activeProjectRecords(currentContentSummary().projects || []);
  const existingLinks = (currentContentSummary().projectSections || []).filter((item) =>
    savedEvidenceKey(item) === savedEvidenceKey(sectionPayload)
  );
  const selectedFolderIDs = new Set(projects
    .filter((project) => existingLinks.some((link) => projectSectionBelongsToProject(link, project)))
    .map(projectRecordID));
  const picker = document.createElement("section");
  picker.className = "reader-notes-project-picker";
  picker.setAttribute("aria-label", "Choose save destinations");

  if (!options.hideIntroduction) {
    const pickerHeader = document.createElement("header");
    pickerHeader.className = "reader-notes-project-picker-header";
    const label = document.createElement("strong");
    label.textContent = isSectionSaved(sectionPayload) ? "Organize saved evidence" : "Save evidence";
    const instruction = document.createElement("p");
    instruction.className = "reader-notes-project-instruction";
    instruction.textContent = "Select Projects for this saved passage.";
    pickerHeader.append(label);
    picker.append(pickerHeader, instruction);
  }

  const status = document.createElement("p");
  status.className = "reader-notes-project-status";
  status.setAttribute("role", "status");

  const destinationList = document.createElement("div");
  destinationList.className = "reader-notes-project-options";
  destinationList.setAttribute("role", "listbox");
  destinationList.setAttribute("aria-label", "Save destinations");
  destinationList.setAttribute("aria-multiselectable", "true");

  const setProjectButtonState = (button, selected) => {
    button.classList.toggle("is-selected", selected);
    button.setAttribute("aria-pressed", String(selected));
    button.setAttribute("aria-selected", String(selected));
    const check = button.querySelector(".reader-notes-project-check");
    if (check) check.textContent = selected ? "✓" : "";
  };

  const confirmButton = document.createElement("button");
  confirmButton.type = "button";
  confirmButton.className = "reader-notes-project-confirm";
  const syncConfirmState = () => {
    const selected = projects.filter((project) => selectedFolderIDs.has(projectRecordID(project)));
    confirmButton.disabled = selected.length === 0;
    confirmButton.textContent = isSectionSaved(sectionPayload)
      ? `Update ${selected.length || ""} ${selected.length === 1 ? "destination" : "destinations"}`.replace("Update  destinations", "Choose a destination")
      : `Save to ${selected.length || ""} ${selected.length === 1 ? "destination" : "destinations"}`.replace("Save to  destinations", "Choose a destination");
  };

  const appendFolderOption = (project) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "reader-notes-project-option";
    button.setAttribute("role", "option");
    button.dataset.folderId = projectRecordID(project);
    if (folderIsProject(project)) button.style.setProperty("--project-color", projectColor(project));
    const name = document.createElement("span");
    name.textContent = project.name || project.title || "Project";
    const type = document.createElement("small");
    type.textContent = folderTypeLabel(project);
    const check = document.createElement("span");
    check.className = "reader-notes-project-check";
    check.setAttribute("aria-hidden", "true");
    button.append(name, type, check);
    setProjectButtonState(button, selectedFolderIDs.has(projectRecordID(project)));
    button.addEventListener("click", () => {
      const folderID = projectRecordID(project);
      if (selectedFolderIDs.has(folderID)) selectedFolderIDs.delete(folderID);
      else selectedFolderIDs.add(folderID);
      setProjectButtonState(button, selectedFolderIDs.has(folderID));
      syncConfirmState();
      status.textContent = selectedFolderIDs.size
        ? `${selectedFolderIDs.size} ${selectedFolderIDs.size === 1 ? "destination" : "destinations"} selected.`
        : "Choose at least one destination.";
    });
    destinationList.append(button);
  };
  destinationList.addEventListener("keydown", (event) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    const options = Array.from(destinationList.querySelectorAll('[role="option"]:not([disabled])'));
    if (!options.length) return;
    event.preventDefault();
    const currentIndex = options.indexOf(document.activeElement);
    const nextIndex = event.key === 'Home'
      ? 0
      : event.key === 'End'
        ? options.length - 1
        : event.key === 'ArrowDown'
          ? Math.min(options.length - 1, Math.max(0, currentIndex + 1))
          : Math.max(0, currentIndex <= 0 ? 0 : currentIndex - 1);
    options[nextIndex]?.focus({ preventScroll: true });
    options[nextIndex]?.scrollIntoView({ block: 'nearest' });
  });

  if (!projects.length) {
    const empty = document.createElement("p");
    empty.className = "reader-notes-project-empty";
    empty.textContent = "No Projects yet. Create one below.";
    destinationList.append(empty);
  }
  projects.forEach(appendFolderOption);
  picker.append(destinationList);

  const newFolderActions = document.createElement("div");
  newFolderActions.className = "reader-notes-new-folder-actions";
  const showNewFolderForm = (folderTypeValue) => {
    newFolderActions.querySelectorAll("button").forEach((button) => { button.hidden = true; });
    const form = document.createElement("form");
    form.className = "reader-notes-new-project-form";
    const input = document.createElement("input");
    input.type = "text";
    input.placeholder = folderTypeValue === "reference" ? "Saved collection name" : "Project name";
    input.setAttribute("aria-label", folderTypeValue === "reference" ? "New saved collection name" : "New Project name");
    const createButton = document.createElement("button");
    createButton.type = "submit";
    createButton.textContent = "Create and select";
    form.append(input, createButton);
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (!input.value.trim()) return;
      createButton.disabled = true;
      try {
        const project = await createProjectFolder({ name: input.value.trim(), folderType: folderTypeValue });
        if (!project) {
          createButton.disabled = false;
          return;
        }
        projects.push(project);
        selectedFolderIDs.add(projectRecordID(project));
        destinationList.querySelector(".reader-notes-project-empty")?.remove();
        appendFolderOption(project);
        form.remove();
        newFolderActions.querySelectorAll("button").forEach((button) => { button.hidden = false; });
        syncConfirmState();
        status.textContent = `${project.name || project.title} created and selected. Confirm below to save.`;
        refreshOpenAnnotationProjectEditors();
      } catch (error) {
        const message = error.message || "Could not create the project.";
        createButton.disabled = false;
        createButton.title = message;
        presentWorkspaceIssue(message);
      }
    });
    picker.append(form);
    input.focus();
  };
  [["project", "New Project…"]].forEach(([type, text]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "reader-notes-new-project";
    button.textContent = text;
    if (type === "project" && !hasCapability("projects")) {
      button.disabled = true;
      button.title = "Projects require Pro";
    }
    button.addEventListener("click", () => showNewFolderForm(type));
    newFolderActions.append(button);
  });

  const actions = document.createElement("div");
  actions.className = "reader-notes-project-picker-actions";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "reader-notes-project-cancel";
  cancelButton.textContent = "Cancel";
  cancelButton.addEventListener("click", () => {
    removeReaderNotesProjectPicker(sheet);
    options.onClose?.({ saved: false, folders: [] });
  });
  confirmButton.addEventListener("click", async () => {
    const selectedFolders = projects.filter((project) => selectedFolderIDs.has(projectRecordID(project)));
    if (!selectedFolders.length) return;
    confirmButton.disabled = true;
    cancelButton.disabled = true;
    destinationList.querySelectorAll("button").forEach((button) => { button.disabled = true; });
    try {
      const result = await persistSectionFolderSelection(sectionPayload, selectedFolders, projects);
      if (!result.saved) {
        confirmButton.disabled = false;
        cancelButton.disabled = false;
        destinationList.querySelectorAll("button").forEach((button) => { button.disabled = false; });
        return;
      }
      syncReaderNoteBookmarkButtons(sectionPayload.sectionID, true, sectionPayload.codeVersion);
      const names = selectedFolders.map((folder) => folder.name || folder.title || folderTypeLabel(folder));
      status.textContent = `${result.queued ? "Saved locally; sync pending" : "Saved"} to ${new Intl.ListFormat(undefined, { style: "long", type: "conjunction" }).format(names)}.`;
      sheet.dispatchEvent(new CustomEvent("permitext-folder-save", {
        detail: { saved: true, folders: selectedFolders }
      }));
      refreshOpenAnnotationProjectEditors();
      window.setTimeout(() => {
        removeReaderNotesProjectPicker(sheet);
        options.onClose?.({ saved: true, folders: selectedFolders });
      }, 900);
    } catch (error) {
      status.textContent = error.message || "The evidence could not be saved.";
      presentWorkspaceIssue(status.textContent);
      confirmButton.disabled = false;
      cancelButton.disabled = false;
      destinationList.querySelectorAll("button").forEach((button) => { button.disabled = false; });
    }
  });
  actions.append(cancelButton, confirmButton);
  picker.append(newFolderActions, status, actions);
  syncConfirmState();

  sheet.prepend(picker);
  requestAnimationFrame(() => {
    const firstOption = destinationList.querySelector('button[role="option"]');
    (firstOption || cancelButton).focus({ preventScroll: true });
  });
}

function syncReaderNoteBookmarkButtons(sectionID, saved, codeVersion = defaultSyncCodeVersion) {
  const sectionKey = sectionNoteKey(sectionID);
  if (!sectionKey) return;
  const exactCodeVersion = syncCodeVersion(codeVersion);
  const wrappers = Array.from(track.querySelectorAll(`.inline-comment[data-comment-section-id="${CSS.escape(sectionKey)}"]`))
    .filter((wrapper) => wrapper.dataset.commentCodeVersion === exactCodeVersion);
  wrappers.forEach((wrapper) => {
    if (!readerPrivateContentAllowed(wrapper.closest(".reader-panel"))) return;
    const wrapperBlockID = normalizeAnnotationBlockID(wrapper.dataset.commentBlockId);
    const savedRecord = isSectionSaved({
      sectionID,
      codeVersion: exactCodeVersion,
      blockID: wrapperBlockID
    });
    const button = wrapper.querySelector(".inline-bookmark-toggle");
    const showBookmark = Boolean(savedRecord && wrapperBlockID);
    wrapper.classList.toggle("has-saved-section", showBookmark);
    if (!button) return;
    button.classList.toggle("is-saved", showBookmark);
    button.setAttribute("aria-label", bookmarkActionLabel(showBookmark));
    button.innerHTML = bookmarkIconSVG(showBookmark);
    button.title = bookmarkActionLabel(showBookmark);
  });
  track.querySelectorAll(`.reader-panel .chapter-section[data-section-id="${CSS.escape(sectionKey)}"]`).forEach((section) => {
    if (section.dataset.codeVersion !== exactCodeVersion || !readerPrivateContentAllowed(section.closest(".reader-panel"))) return;
    const marker = section.querySelector(".reader-section-saved-marker");
    if (!marker) return;
    const showSectionMarker = Boolean(isSectionSaved({
      sectionID,
      codeVersion: exactCodeVersion,
      blockID: ""
    }));
    syncImmediateBookmarkButton(marker, showSectionMarker);
    marker.setAttribute("aria-label", showSectionMarker ? "Remove section from Evidence" : "Save section");
    marker.title = showSectionMarker ? "Remove section from Evidence" : "Save section";
  });
}

function sectionElementForInlineComment(commentWrapper) {
  return commentWrapper.closest(".chapter-section");
}

function beginReaderNavigation(panel, { clearContent = true } = {}) {
  panel._readerNavigationAbort?.abort();
  panel._readerNavigationAbort = new AbortController();
  cancelReaderInternalSearch(panel);
  delete panel._readerSearchReturnPosition;
  const token = crypto.randomUUID();
  panel.dataset.readerNavigationToken = token;
  delete panel.dataset.readerContentKey;
  if (clearContent) {
    // Invalidate body, search and hydration work before waiting for a new catalog.
    panel.dataset.readerRenderToken = token;
    panel.dataset.readerSearchToken = token;
    const content = panel.querySelector(".reader-content");
    stopReaderProgressiveHydration(content);
    content?.classList.remove("is-searching-reader");
    clear(content);
    emptyReader(content, "Loading chapter", "Opening the selected code text.");
  }
  return token;
}

async function changeReaderCode(panel, reader, selectedCode) {
  reader.codePrefix = selectedCode.prefix;
  reader.codeVersion = codeOptionVersion(selectedCode);
  reader.chapterID = "";
  reader.sectionID = "";
  reader.sectionNumber = "";
  reader.title = "Reader";
  // refreshReaderContent starts the new navigation synchronously. An old chapter
  // must never remain visible beneath the newly selected code and edition.
  if (await refreshReaderContent(panel, reader)) {
    saveWorkspaceState();
    scheduleContinuitySync(reader);
  }
}

async function prefetchReaderSourceWindow(source, signal) {
  const chapter = await fetchChapter(source.chapterID, {signal});
  if (chapter.codePrefix !== source.codePrefix || chapter.codeVersion !== source.codeVersion) return;
  const sections = (chapter.sections || []).map(section => ({...section, readerAliasSectionIDs: []}));
  const target = readerTargetSectionIndex(sections, source);
  if (target < 0) return;
  const start = Math.min(Math.max(0, target - Math.floor(readerInitialSectionWindowSize / 2)),
    Math.max(0, sections.length - readerInitialSectionWindowSize));
  await fetchChapterBodyWindow(source.chapterID, start, Math.min(readerInitialSectionWindowSize, sections.length - start), chapter, {signal});
}

async function refreshReaderContent(panel, reader, options = {}) {
  panel.dataset.workspacePaneIdentity = workspaceReaderContentIdentity(reader);
  const navigationToken = beginReaderNavigation(panel);
  const saveButton = panel.querySelector(".reader-save");
  applyCodeTheme(panel, reader);
  renderReaderTrust(panel, reader);
  populateCodeSelect(panel, reader);
  resetEnhancedSelects(panel);
  if (saveButton) saveButton.disabled = true;
  try {
    const sourceNavigation = resolvedReaderSourceNavigations.get(reader);
    const exactSource = sourceNavigation && sourceNavigation.chapterID === reader.chapterID &&
      sourceNavigation.sectionID === reader.sectionID && sourceNavigation.codePrefix === reader.codePrefix &&
      sourceNavigation.codeVersion === reader.codeVersion;
    if (exactSource) {
      // Warm the exact text in parallel. Publication still waits for the catalog
      // to accept its navigation chapter and for the normal edition checks.
      void prefetchReaderSourceWindow(sourceNavigation, panel._readerNavigationAbort?.signal).catch(() => {});
    }
    if (!await populateReaderSelectors(panel, reader, navigationToken)) return false;
    await renderSectionContent(panel, reader, options);
  } catch (error) {
    if (panel.dataset.readerNavigationToken !== navigationToken) return false;
    if (error.name === "AbortError") return false;
    const transient = error.code === "PUBLIC_CORPUS_CHANGED" || error.isNetworkFailure ||
      [500, 502, 503, 504].includes(error.status);
    if (transient && !options.openingRetry) {
      await new Promise(resolve => window.setTimeout(resolve, 150));
      if (panel.dataset.readerNavigationToken !== navigationToken) return false;
      return refreshReaderContent(panel, reader, { ...options, openingRetry: true });
    }
    console.warn("Reader opening failed", { code: error.code || error.name, status: error.status,
      chapterID: reader.chapterID, codePrefix: reader.codePrefix });
    const content = panel.querySelector(".reader-content");
    clear(content);
    emptyReader(content, "Couldn’t open this chapter", "Check your connection and try again.");
    const retry = document.createElement("button");
    retry.type = "button";
    retry.className = "ghost-button search-empty-action";
    retry.textContent = "Try again";
    retry.addEventListener("click", async () => {
      if (panel.dataset.readerNavigationToken !== navigationToken) return;
      if (await refreshReaderContent(panel, reader)) {
        saveWorkspaceState();
        scheduleContinuitySync(reader);
      }
    });
    content.querySelector(".reader-empty")?.append(retry);
    panel.querySelectorAll("select").forEach(enhanceSelect);
    return false;
  }
  if (panel.dataset.readerNavigationToken !== navigationToken) return false;
  setTitle(panel, reader);
  preparePaneCollapse(panel);
  panel.querySelectorAll("select").forEach(enhanceSelect);
  if (saveButton) {
    saveButton.hidden = !reader.sectionID;
    saveButton.disabled = !reader.sectionID;
  }
  return true;
}

function updateReaderScrollIndicator(panel) {
  if (!readerPanelIntersectsTrack(panel)) {
    panel?.classList.remove("is-scrolling");
    const offscreenToTopButton = panel?.querySelector(".reader-to-top");
    offscreenToTopButton?.classList.remove("is-visible");
    offscreenToTopButton?.setAttribute("aria-hidden", "true");
    if (offscreenToTopButton) offscreenToTopButton.tabIndex = -1;
    return;
  }
  const content = panel.querySelector(".reader-content");
  const toTopButton = panel.querySelector(".reader-to-top");
  if (!content) return;
  const scrollable = Math.max(0, content.scrollHeight - content.clientHeight);
  const showToTop = scrollable > 1 &&
    content.scrollTop > Math.min(240, Math.max(120, content.clientHeight * 0.25));
  if (toTopButton) {
    toTopButton.classList.toggle("is-visible", showToTop);
    toTopButton.setAttribute("aria-hidden", String(!showToTop));
    toTopButton.tabIndex = showToTop ? 0 : -1;
  }
}

function bindReaderScrollIndicator(panel) {
  const content = panel.querySelector(".reader-content");
  const toTopButton = panel.querySelector(".reader-to-top");
  if (!content || panel.dataset.scrollIndicatorBound === "true") return;
  panel.dataset.scrollIndicatorBound = "true";
  let hideTimer = null;
  const update = () => updateReaderScrollIndicator(panel);
  const reveal = () => {
    panel.classList.add("is-scrolling");
    update();
    if (hideTimer) window.clearTimeout(hideTimer);
    hideTimer = window.setTimeout(() => panel.classList.remove("is-scrolling"), 700);
  };
  content.addEventListener("scroll", reveal, { passive: true });
  toTopButton?.addEventListener("click", () => {
    content.scrollTo({ top: 0, behavior: "smooth" });
  });
  requestAnimationFrame(update);
}

function readerPanelIntersectsTrack(panel) {
  if (!panel?.isConnected) return false;
  const panelBounds = panel.getBoundingClientRect();
  const trackBounds = track.getBoundingClientRect();
  return panelBounds.width > 0
    && panelBounds.right > trackBounds.left
    && panelBounds.left < trackBounds.right;
}

let visibleReaderMetricsFrame = null;

function scheduleVisibleReaderScrollIndicatorUpdates() {
  if (visibleReaderMetricsFrame !== null) return;
  visibleReaderMetricsFrame = requestAnimationFrame(() => {
    visibleReaderMetricsFrame = null;
    track.querySelectorAll(".reader-panel").forEach(updateReaderScrollIndicator);
  });
}

function bindAllReaderScrollIndicators() {
  track.querySelectorAll(".reader-panel").forEach((panel) => {
    bindReaderScrollIndicator(panel);
    updateReaderScrollIndicator(panel);
  });
}

function codeFigureURL(fileName, assetRevision = "") {
  const pin = /^[a-f0-9]{64}$/.test(assetRevision) ? `assetRevision=${assetRevision}` : `v=${offlineFeatureMetadata.assetVersion}`;
  return `/code/assets/${encodeURIComponent(fileName)}?${pin}`;
}

function rewriteCodeHTML(html, assetRevision = "") {
  return rewriteStructuredCodeLinks(html)
    .replace(/\b(src|href)=(["'])(?:(?:\.\.\/)+assets\/|\/code\/assets\/)([^"']+)\2/gi, (_match, attribute, quote, rawName) => {
      let fileName = rawName.split(/[?#]/, 1)[0];
      try { fileName = decodeURIComponent(fileName); } catch { /* Preserve legacy literal names. */ }
      return `${attribute}=${quote}${codeFigureURL(fileName, assetRevision)}${quote}`;
    })
    .replace(/<\s*\/?\s*(annotationdrawer|codeoptions)\b[^>]*>/gi, "");
}

function renderCodeBlock(block) {
  if (block.kind === "image") {
    const figure = document.createElement("figure");
    figure.className = "code-media code-image";
    if (block.html) {
      figure.innerHTML = rewriteCodeHTML(block.html, block.assetRevision);
    } else if (block.imageID) {
      const image = document.createElement("img");
      image.src = codeFigureURL(block.imageID, block.assetRevision);
      figure.append(image);
    }
    decorateCodeHTML(figure);
    return figure;
  }

  if (block.kind === "table" || /<table\b/i.test(block.html || "")) {
    const wrapper = document.createElement("div");
    wrapper.className = "code-table";
    wrapper.innerHTML = rewriteCodeHTML(block.html || "", block.assetRevision);
    decorateCodeHTML(wrapper);
    wrapper.setAttribute("role", "region");
    wrapper.setAttribute("aria-label", "Code table");
    return wrapper;
  }

  if (block.kind === "html" && block.html) {
    const wrapper = document.createElement("div");
    wrapper.className = "section-block section-html";
    wrapper.innerHTML = rewriteCodeHTML(block.html, block.assetRevision);
    decorateCodeHTML(wrapper);
    if (!wrapper.textContent.trim() && !wrapper.querySelector("img, table")) {
      wrapper.textContent = block.plainText || "";
    }
    return wrapper;
  }

  const paragraph = document.createElement("p");
  paragraph.className = "section-block";
  paragraph.textContent = block.plainText || "";
  promoteAuthoredSectionLabels(paragraph);
  return paragraph;
}

function markResearchSelectable(element, source = {}) {
  if (!element || !source.sectionID || String(source.codePrefix || "").toUpperCase() === "ZR") {
    return element;
  }
  element.classList.add("research-selectable-text");
  element.dataset.researchSectionId = String(source.sectionID);
  element.dataset.researchSectionNumber = String(source.sectionNumber || "");
  element.dataset.researchSectionTitle = String(source.title || "Section");
  element.dataset.researchCodePrefix = String(source.codePrefix || "BC");
  element.dataset.researchCodeVersion = String(
    source.codeVersion || syncCodeVersionForPrefix(source.codePrefix || "BC") || ""
  );
  element.dataset.researchCodeEdition = researchCodeEdition(source);
  element.dataset.researchSourceLibraryVersion = String(source.sourceLibraryVersion || "");
  element.dataset.researchChapterId = String(source.chapterID || "");
  if (source.researchSavedItemID) {
    element.dataset.researchSavedItemId = String(source.researchSavedItemID);
  }
  return element;
}

function linkInlineCodeReferences(root, panel, reader) {
  if (!root || root.dataset.inlineReferencesLinked === "true") return;
  root.dataset.inlineReferencesLinked = "true";

  root.querySelectorAll("[data-code-jump-anchor]").forEach((reference) => {
    if (reference.dataset.codeJumpBound === "true") return;
    reference.dataset.codeJumpBound = "true";
    reference.addEventListener("click", (event) => {
      openStructuredCodeReference(reader, reference.dataset.codeJumpAnchor, reference, { restoreFocus: event.detail === 0 });
    });
  });

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue?.trim() || inlineCodeReferencePhrases(node.nodeValue).length === 0) {
        return NodeFilter.FILTER_REJECT;
      }
      if (node.parentElement?.closest("a, button, input, textarea, select, script, style, .reader-note-control, .authored-section-label, .reader-section-title")) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);

  textNodes.forEach((textNode) => {
    const text = textNode.nodeValue || "";
    const phrases = inlineCodeReferencePhrases(text);
    if (!phrases.length) return;
    let cursor = 0;
    const fragment = document.createDocumentFragment();
    phrases.forEach((phrase) => {
      if (phrase.start > cursor) fragment.append(document.createTextNode(text.slice(cursor, phrase.start)));
      let phraseCursor = phrase.start;
      const codePrefix = phrase.codePrefix || reader.codePrefix || "BC";
      phrase.references.forEach((target) => {
        if (target.start > phraseCursor) {
          fragment.append(document.createTextNode(text.slice(phraseCursor, target.start)));
        }
        const reference = document.createElement("button");
        reference.type = "button";
        reference.className = "inline-code-reference";
        reference.textContent = text.slice(target.start, target.end);
        reference.setAttribute("aria-label", `Open ${codePrefix} Section ${target.sectionNumber}`);
        reference.addEventListener("click", (event) => {
          openInlineCodeReference(reader, codePrefix, target.sectionNumber, reference, { restoreFocus: event.detail === 0 });
        });
        fragment.append(reference);
        phraseCursor = target.end;
      });
      if (phraseCursor < phrase.end) {
        fragment.append(document.createTextNode(text.slice(phraseCursor, phrase.end)));
      }
      cursor = phrase.end;
    });
    if (cursor < text.length) fragment.append(document.createTextNode(text.slice(cursor)));
    textNode.replaceWith(fragment);
  });
}

function normalizedInlineSectionNumber(value) {
  return String(value || "").replace(/^Section\s+/i, "").replace(/\([^)]+\)/g, "").trim().toLowerCase();
}

function inlineReferenceSearchResult(results, codePrefix, sectionNumber) {
  const targetNumber = normalizedInlineSectionNumber(sectionNumber);
  const codeResults = (results || []).filter((item) =>
    String(item.codePrefix || "BC").toUpperCase() === codePrefix
  );
  const exact = codeResults.find((item) => normalizedInlineSectionNumber(item.sectionNumber) === targetNumber);
  if (exact) return exact;
  return codeResults
    .filter((item) => normalizedInlineSectionNumber(item.sectionNumber).startsWith(`${targetNumber}.`))
    .sort((left, right) =>
      normalizedInlineSectionNumber(left.sectionNumber).length - normalizedInlineSectionNumber(right.sectionNumber).length ||
      String(left.sectionNumber).localeCompare(String(right.sectionNumber), undefined, { numeric: true, sensitivity: "base" })
    )[0] || null;
}

async function resolveInlineCodeSection(codePrefix, sectionNumber, codeVersion = "") {
  const params = new URLSearchParams({
    q: sectionNumber,
    code: codePrefix,
    limit: "25",
    version: syncCodeVersion(codeVersion || syncCodeVersionForPrefix(codePrefix))
  });
  const payload = await api(`/code/search?${params}`);
  return inlineReferenceSearchResult(payload.results, codePrefix, sectionNumber);
}

async function openReferenceInAdjacentReader(sourceReader, detail) {
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const original = JSON.stringify([sourceReader.codePrefix, sourceReader.codeVersion, sourceReader.chapterID, sourceReader.sectionID]);
  const isCurrent = () => isCurrentAccountRequest(identity) && activeWorkspaceID === workspaceID &&
    state.readers.includes(sourceReader) &&
    JSON.stringify([sourceReader.codePrefix, sourceReader.codeVersion, sourceReader.chapterID, sourceReader.sectionID]) === original;
  let context;
  try {
    if (detail.sectionID || detail.id || detail.sectionNumber) {
      const resolved = await resolveReaderSource(detail, {isCurrent});
      if (!resolved) return;
      detail = resolved;
      context = resolved.__activeCodeSourceContext;
    } else {
      const access = await guardReaderChapterSource(detail, isCurrent);
      if (!access) return;
      detail = access.target;
      context = access.context;
    }
  } catch (error) {
    if (isCurrent() && error.code !== "STALE_CONTEXT") await showWebNotice("Source could not be opened", error.message);
    return;
  }
  if (!isCurrent() || !activeCodeSourcesController.isCurrent(context)) return;
  let targetReader = state.readers.find((reader) =>
    reader.id !== sourceReader.id &&
    reader.referenceSourceReaderID === sourceReader.id
  );
  const canAddReader = isProAccount() || state.readers.length < 2;
  if (!targetReader && canAddReader) {
    targetReader = newReaderState({
      ...readerFieldsForSectionDetail(detail),
      referenceSourceReaderID: sourceReader.id
    });
    state.readers.push(targetReader);
  } else {
    targetReader = targetReader ||
      state.readers.find((reader) => reader.id !== sourceReader.id) ||
      sourceReader;
    Object.assign(targetReader, readerFieldsForSectionDetail(detail), {
      referenceSourceReaderID: sourceReader.id,
      savedSourcePaneID: "",
      projectSavedSourceKey: ""
    });
    Object.keys(searchLinkedReadersBySearch()).forEach((searchID) => {
      if (state.searchLinkedReaders[searchID] === targetReader.id) {
        delete state.searchLinkedReaders[searchID];
      }
    });
  }
  placePaneAfter(paneIDForReader(sourceReader), paneIDForReader(targetReader));
  if (targetReader.sectionID) updateBrowserSectionURL(targetReader.sectionID);
  scheduleContinuitySync(targetReader);
  saveWorkspaceState();
  const targetIdentity = JSON.stringify([targetReader.codePrefix, targetReader.codeVersion, targetReader.chapterID, targetReader.sectionID]);
  const presentationIsCurrent = () => isCurrentAccountRequest(identity) && activeWorkspaceID === workspaceID &&
    activeCodeSourcesController.isCurrent(context) && state.readers.includes(targetReader) &&
    JSON.stringify([targetReader.codePrefix, targetReader.codeVersion, targetReader.chapterID, targetReader.sectionID]) === targetIdentity &&
    (targetReader === sourceReader || isCurrent());
  await transitionWorkspace("utility", { refreshPaneIDs: [paneIDForReader(targetReader)] });
  if (!presentationIsCurrent()) return;
  if (!await whenWorkspacePaneReady(paneIDForReader(targetReader)) || !presentationIsCurrent()) return;
  if (targetReader.sectionID) alignReaderSectionAfterLayout(targetReader);
  scrollPaneIntoView(paneIDForReader(targetReader));
}

function captureReferenceFocusRestoration(reader, trigger, enabled) {
  if (!enabled || document.activeElement !== trigger) return () => {};
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const sourceContext = activeCodeSourcesController.captureContext();
  const readerIdentity = JSON.stringify([reader.codePrefix, reader.codeVersion, reader.chapterID, reader.sectionID]);
  let focusMoved = false;
  const observeFocus = (event) => {
    if (event.target !== trigger && event.target !== document.body) focusMoved = true;
  };
  document.addEventListener("focusin", observeFocus);
  return () => {
    document.removeEventListener("focusin", observeFocus);
    if (!focusMoved && trigger.isConnected && document.activeElement === document.body &&
        isCurrentAccountRequest(identity) && activeWorkspaceID === workspaceID &&
        activeCodeSourcesController.isCurrent(sourceContext) && state.readers.includes(reader) &&
        JSON.stringify([reader.codePrefix, reader.codeVersion, reader.chapterID, reader.sectionID]) === readerIdentity) {
      trigger.focus({ preventScroll: true });
    }
  };
}

async function openInlineCodeReference(reader, codePrefix, sectionNumber, trigger, options = {}) {
  if (!sectionNumber || !trigger) return;
  const normalizedPrefix = String(codePrefix || reader.codePrefix || "BC").toUpperCase();
  const restoreFocus = captureReferenceFocusRestoration(reader, trigger, options.restoreFocus);
  trigger.disabled = true;
  trigger.setAttribute("aria-busy", "true");
  try {
    await openReferenceInAdjacentReader(reader, {
      codePrefix: normalizedPrefix, codeVersion: reader.codeVersion, sectionNumber
    });
  } finally {
    if (trigger.isConnected) {
      trigger.disabled = false;
      trigger.removeAttribute("aria-busy");
    }
    restoreFocus();
  }
}

async function openStructuredCodeReference(reader, anchor, trigger, options = {}) {
  const target = parseCodeJumpAnchor(anchor);
  if (!target || !trigger) return;
  if (target.kind === "section") {
    await openInlineCodeReference(reader, target.codePrefix, target.sectionNumber, trigger, options);
    return;
  }

  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const sourceContext = activeCodeSourcesController.captureContext();
  const sourceVersion = reader.codeVersion;
  const sourceChapterID = reader.chapterID;
  const restoreFocus = captureReferenceFocusRestoration(reader, trigger, options.restoreFocus);
  trigger.disabled = true;
  trigger.setAttribute("aria-busy", "true");
  try {
    const referenceChapters = await fetchChapterList(target.codePrefix, sourceVersion);
    const chapter = referenceChapters.find((item) =>
      String(item.codePrefix || "").toUpperCase() === target.codePrefix &&
      syncCodeVersion(item.codeVersion || syncCodeVersionForPrefix(target.codePrefix)) === syncCodeVersion(sourceVersion) &&
      String(item.chapterNumber || "").trim().toUpperCase() === target.chapterNumber
    );
    if (!chapter) {
      trigger.title = `${codeDisplayLabel(target.codePrefix)} ${target.targetKind === "appendix" ? "Appendix" : "Chapter"} ${target.chapterNumber} was not found.`;
      return;
    }
    if (!isCurrentAccountRequest(identity) || activeWorkspaceID !== workspaceID ||
        !activeCodeSourcesController.isCurrent(sourceContext) ||
        reader.codeVersion !== sourceVersion || reader.chapterID !== sourceChapterID || !state.readers.includes(reader)) return;
    await openReferenceInAdjacentReader(reader, {
      codePrefix: target.codePrefix,
      codeVersion: reader.codeVersion,
      chapterID: chapter.id,
      chapterNumber: chapter.chapterNumber,
      sectionID: "",
      sectionNumber: "",
      title: chapter.fullTitle || chapter.displayTitle || chapter.title || "Reader"
    });
  } finally {
    if (trigger.isConnected) {
      trigger.disabled = false;
      trigger.removeAttribute("aria-busy");
    }
    restoreFocus();
  }
}

function plainTextFromHTML(html) {
  const wrapper = document.createElement("div");
  wrapper.innerHTML = rewriteCodeHTML(html || "");
  return wrapper.textContent || "";
}

function plainTextForSearchBlock(block) {
  if (block?.plainText) return block.plainText;
  if (block?.html) return plainTextFromHTML(block.html);
  return "";
}


function cancelReaderInternalSearch(panel) {
  panel._readerSearchAbort?.abort();
  delete panel._readerSearchAbort;
  clearTimeout(readerSearchTimers.get(panel.dataset.readerId));
  readerSearchTimers.delete(panel.dataset.readerId);
  panel.dataset.readerSearchToken = `cancelled:${crypto.randomUUID()}`;
}

async function restoreReaderAfterSearch(panel, reader) {
  const scrollPosition = panel._readerSearchReturnPosition;
  await renderSectionContent(panel, reader, { scrollPosition });
  if (scrollPosition) restoreReaderScrollPositions(new Map([[paneIDForReader(reader), scrollPosition]]));
}

async function fetchReaderChapterSearch(reader, query, signal) {
  const codeVersion = syncCodeVersion(reader.codeVersion || syncCodeVersionForPrefix(reader.codePrefix));
  const params = new URLSearchParams({ bodyContract: "2", readerSearch: query.trim() });
  const path = `/code/chapters/${encodeURIComponent(reader.chapterID)}?${params}`;
  let payload;
  let availabilityFailure = false;
  try {
    payload = await publicCodeRevision.read(path, { signal }, async (requestPath, onPublicResponse) => {
      availabilityFailure = false;
      let response;
      try {
        response = await fetch(requestPath, { signal });
      } catch (error) {
        availabilityFailure = true;
        throw error;
      }
      if (!response.ok) {
        availabilityFailure = response.status >= 500;
        const error = new Error(`Chapter search failed: ${response.status}`);
        error.status = response.status;
        throw error;
      }
      const result = await response.json();
      signal.throwIfAborted();
      onPublicResponse(response);
      return result;
    });
  } catch (error) {
    if (signal.aborted || error.name === "AbortError" || error.code === "PUBLIC_CORPUS_CHANGED" || (Number.isFinite(error.status) && error.status < 500)) throw error;
    if (!availabilityFailure || !hasCapability("offline-access")) throw error;
    // Only the atomically installed, complete offline chapter is eligible.
    // Rendered windows and partial online caches must never stand in for it.
    const offline = await offlineAPI(path).catch(() => null);
    if (signal.aborted) throw new DOMException("Search cancelled", "AbortError");
    if (!offline?.chapter || String(offline.chapter.id) !== String(reader.chapterID)) throw error;
    const chapter = offline.chapter;
    const range = chapter.bodyRange;
    if (syncCodeVersion(chapter.codeVersion) !== codeVersion || !Array.isArray(chapter.sections) ||
        !range?.complete || range.start !== 0 || range.end !== chapter.sections.length ||
        range.total !== chapter.sections.length || chapter.sections.some(section => !Array.isArray(section.blocks))) throw error;
    const sections = (chapter.sections || []).map(section => ({
      ...section,
      displayTitle: sectionDisplayTitle(section.sectionNumber, section.title),
      blocks: annotatedBlocksForSection(section)
        .map((block, index) => ({
          blockID: normalizeAnnotationBlockID(block?.id || block?.tableID || block?.imageID || `block-${index + 1}`),
          text: plainTextForSearchBlock(block).replace(/\s+/g, " ").trim()
        }))
    }));
    const matches = searchReaderTextSections(sections, query);
    return /^[a-f0-9]{64}$/.test(chapter.corpusRevision || "")
      ? matches.map(item => ({ ...item, corpusRevision: chapter.corpusRevision })) : matches;
  }
  if (signal.aborted) throw new DOMException("Search cancelled", "AbortError");
  const result = payload?.readerSearch;
  if (!result || String(result.chapterID) !== String(reader.chapterID) || result.codeVersion !== codeVersion ||
      !/^[a-f0-9]{64}$/.test(result.corpusRevision || "") ||
      result.query !== query.trim() || !Array.isArray(result.results) || result.total !== result.results.length) {
    throw new Error("Chapter search identity mismatch");
  }
  return result.results.map(item => ({ ...item, corpusRevision: result.corpusRevision }));
}

async function renderReaderInternalSearchResults(panel, reader, query) {
  const content = panel.querySelector(".reader-content");
  if (!content) return;
  cancelReaderInternalSearch(panel);
  const needle = query.trim().toLowerCase();
  const searchToken = `search:${crypto.randomUUID()}`;
  panel.dataset.readerSearchToken = searchToken;
  if (needle.length < 2 || !reader.chapterID) {
    if (content.classList.contains("is-searching-reader")) await restoreReaderAfterSearch(panel, reader);
    return;
  }
  if (!content.classList.contains("is-searching-reader")) {
    panel._readerSearchReturnPosition ||= captureReaderScrollPositions().get(panel.dataset.paneId);
  }
  const controller = new AbortController();
  panel._readerSearchAbort = controller;
  panel.dataset.readerRenderToken = searchToken;
  stopReaderProgressiveHydration(content);
  clear(content);
  content.classList.add("is-searching-reader");
  content.scrollTop = 0;
  emptyReader(content, "Searching this chapter", "Finding matching sections in the code text.");
  let matches;
  try {
    matches = await fetchReaderChapterSearch(reader, query, controller.signal);
  } catch {
    if (panel.isConnected && panel.dataset.readerSearchToken === searchToken) {
      emptyReader(content, "Search could not load", "Try again, or close find to return to the code text.");
      const retry = document.createElement("button");
      retry.type = "button";
      retry.className = "ghost-button search-empty-action";
      retry.textContent = "Try again";
      retry.addEventListener("click", () => void renderReaderInternalSearchResults(panel, reader, query));
      content.querySelector(".reader-empty")?.append(retry);
    }
    return;
  }
  if (!panel.isConnected || panel.dataset.readerSearchToken !== searchToken) return;
  clear(content);

  const results = document.createElement("section");
  results.className = "reader-internal-results";
  if (!matches.length) {
    emptyReader(content, "No match in this chapter", "Try a shorter phrase, or use Search to look across codes.");
    return;
  }

  matches.forEach((result) => {
    const row = document.createElement("button");
    row.className = "reader-internal-result";
    row.type = "button";

    const heading = document.createElement("strong");
    appendHighlighted(heading, result.heading, result.headingHighlight);

    const snippet = document.createElement("p");
    appendHighlighted(snippet, result.snippet, result.snippetHighlight);

    row.append(heading, snippet);
    row.addEventListener("click", async () => {
      const searchBox = panel.querySelector(".reader-internal-search");
      const searchButton = panel.querySelector(".reader-internal-search-toggle");
      panel.dataset.readerSearchToken = `selected:${Date.now()}`;
      reader.sectionID = result.sectionID;
      reader.sectionNumber = result.sectionNumber || "";
      reader.title = result.title || "Reader";
      reader.internalSearchQuery = query;
      reader.pendingSearchHighlightQuery = result.matchText;
      reader.pendingSearchHighlightBlockID = result.blockID || "";
      panel.dataset.pendingSearchHighlightQuery = result.matchText;
      panel.dataset.pendingSearchHighlightBlockId = result.blockID || "";
      reader.shouldSmoothScrollToSection = true;
      updateBrowserSectionURL(reader.sectionID);
      scheduleContinuitySync(reader);
      if (searchBox) searchBox.hidden = true;
      searchButton?.setAttribute("aria-pressed", "false");
      saveWorkspaceState();
      await renderSectionContent(panel, reader, { expectedCorpusRevision: result.corpusRevision });
    });
    results.append(row);
  });

  content.append(results);
}

function decorateCodeHTML(root) {
  root.querySelectorAll("script, style, annotationdrawer, codeoptions").forEach((node) => node.remove());
  normalizeCodeTables(root);
  promoteAuthoredSectionLabels(root);
  root.querySelectorAll("img").forEach((image, index) => {
    image.loading = "lazy";
    image.decoding = "async";
    const authoredAlt = image.getAttribute("alt")?.trim();
    const accessibleLabel = image.getAttribute("aria-label")?.trim();
    const caption = image.closest("figure")?.querySelector("figcaption")?.textContent?.trim();
    const title = image.getAttribute("title")?.trim();
    const sourceName = String(image.getAttribute("src") || "").split("/").pop()?.split(/[?#]/)[0]
      .replace(/%[0-9a-f]{2}/gi, " ")
      .replace(/\.[a-z0-9]+$/i, "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    image.alt = authoredAlt || accessibleLabel || caption || title || (sourceName
      ? `Official code figure: ${sourceName}`
      : `Official code figure ${index + 1}`);
  });
  root.querySelectorAll("br").forEach((breakElement) => {
    if (breakElement.textContent) {
      breakElement.textContent = "";
    }
  });
}

function groupLabelsForChapter(chapter) {
  const labels = new Map();
  (chapter.groups || []).forEach((group) => {
    const firstSection = (group.sections || [])[0];
    if (!firstSection?.id || !group.headerLine) return;
    const label = [group.headerLine, group.headingLine].filter(Boolean).join(": ");
    labels.set(String(firstSection.id), label.toUpperCase());
  });
  return labels;
}

function promoteAuthoredSectionLabels(root) {
  const labelPattern = /(^|\n)\s*((?:section)\s+(?:BC|AC|PC|MC|FGC)\s+\d+[A-Z]?(?::\s*[^\n]+)?)/gi;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  let currentNode = walker.nextNode();
  while (currentNode) {
    if (labelPattern.test(currentNode.nodeValue || "")) {
      textNodes.push(currentNode);
    }
    labelPattern.lastIndex = 0;
    currentNode = walker.nextNode();
  }

  textNodes.forEach((textNode) => {
    const text = textNode.nodeValue || "";
    const fragment = document.createDocumentFragment();
    let lastIndex = 0;
    text.replace(labelPattern, (match, lineBreak, label, offset) => {
      if (offset > lastIndex) {
        fragment.append(document.createTextNode(text.slice(lastIndex, offset)));
      }
      if (lineBreak) {
        fragment.append(document.createTextNode(lineBreak));
      }
      lastIndex = offset + match.length;
      return match;
    });
    if (lastIndex < text.length) {
      fragment.append(document.createTextNode(text.slice(lastIndex)));
    }
    textNode.replaceWith(fragment);
  });
}

function normalizeCodeTables(root) {
  root.querySelectorAll("scrolltable").forEach((scrollTable) => {
    const bodyTable =
      scrollTable.querySelector(".xsl-table--body table") ||
      scrollTable.querySelector(".xsl-table:not(.xsl-table--header) table") ||
      Array.from(scrollTable.querySelectorAll("table")).at(-1);

    if (bodyTable) {
      scrollTable.replaceWith(bodyTable);
    } else {
      scrollTable.replaceWith(...Array.from(scrollTable.childNodes));
    }
  });

  root.querySelectorAll(".xsl-table--header").forEach((headerTable) => headerTable.remove());
  root.querySelectorAll(".xsl-table--body, .xsl-table").forEach((tableShell) => {
    const nestedTable = tableShell.matches("table") ? tableShell : tableShell.querySelector(":scope > table");
    if (nestedTable) {
      tableShell.replaceWith(nestedTable);
    } else if (!tableShell.textContent.trim()) {
      tableShell.remove();
    }
  });

  root.querySelectorAll("table").forEach((table) => {
    removeEmptyTableFooters(table);
    removeRepeatedLeadingRows(table);
  });
}

function removeEmptyTableFooters(table) {
  Array.from(table.tFoot?.rows || []).forEach((row) => {
    const hasContent = Array.from(row.cells || []).some((cell) => normalizeTableCellText(cell.textContent));
    if (!hasContent) {
      row.remove();
    }
  });
  if (table.tFoot && !table.tFoot.rows.length) {
    table.tFoot.remove();
  }
}

function removeRepeatedLeadingRows(table) {
  const rows = Array.from(table.rows || []);
  if (rows.length < 2) return;

  for (let groupSize = Math.min(6, Math.floor(rows.length / 2)); groupSize >= 1; groupSize -= 1) {
    const firstGroup = rows.slice(0, groupSize);
    const secondGroup = rows.slice(groupSize, groupSize * 2);
    if (!firstGroup.length || !secondGroup.length) continue;
    if (!firstGroup.some(isHeaderLikeTableRow)) continue;

    const firstSignature = firstGroup.map(tableRowSignature).join("||");
    const secondSignature = secondGroup.map(tableRowSignature).join("||");
    if (firstSignature !== secondSignature) continue;

    firstGroup.forEach((row) => row.remove());
    return;
  }
}

function tableRowSignature(row) {
  return Array.from(row.cells || [])
    .map((cell) => {
      const text = normalizeTableCellText(cell.textContent);
      return `${cell.tagName}:${cell.colSpan || 1}:${cell.rowSpan || 1}:${text}`;
    })
    .join("|");
}

function normalizeTableCellText(text) {
  return String(text || "").replace(/\s+/g, " ").trim().toLowerCase();
}

function isHeaderLikeTableRow(row) {
  const cells = Array.from(row.cells || []);
  if (!cells.length) return false;
  if (cells.some((cell) => cell.tagName === "TH")) return true;
  return cells.every((cell) => {
    const text = normalizeTableCellText(cell.textContent);
    return text && text.length <= 90 && !/^\d+(?:\.\d+)*\b/.test(text);
  });
}

async function renderReader(reader, options = {}) {
  options = { ...options, scrollPosition: options.scrollPosition || pendingGroupReaderPositions.get(reader.id) };
  pendingGroupReaderPositions.delete(reader.id);
  const panel = readerTemplate.content.firstElementChild.cloneNode(true);
  panel.__workspaceAccessGate = options.accessGate || null;
  const selector = panel.querySelector(".selector-stack");
  const closeButton = panel.querySelector(".reader-close");
  const dragHandle = panel.querySelector(".pane-drag-handle");
  const referenceSourceButton = panel.querySelector(".reader-reference-source");
  const internalSearchButton = panel.querySelector(".reader-internal-search-toggle");
  const internalSearchBox = panel.querySelector(".reader-internal-search");
  const internalSearchInput = panel.querySelector(".reader-internal-search-input");
  const internalSearchClearButton = panel.querySelector(".reader-internal-search-clear");
  const codeSelect = panel.querySelector(".code-select");
  const chapterSelect = panel.querySelector(".chapter-select");
  const sectionSelect = panel.querySelector(".section-select");
  const recentlyViewedSearchID = String(reader.recentlyViewedSourceSearchID || "").trim();
  const isRecentlyViewedLinkedReader = Boolean(
    recentlyViewedSearchID &&
    searchLinkedReadersBySearch()[recentlyViewedSearchID] === reader.id
  );
  const referenceSourceReader = state.readers.find((item) => item.id === reader.referenceSourceReaderID);

  if (reader.searchPreviewPaneID || reader.pinnedSearchPaneID || reader.pinnedDetailSourceID || searchIDForLinkedReaderPane(`reader:${reader.id}`)) {
    const keepButton = document.createElement("button");
    keepButton.type = "button";
    keepButton.className = "icon-button reader-keep-open";
    const pinned = Boolean(reader.pinnedSearchPaneID || reader.pinnedDetailSourceID);
    keepButton.title = pinned ? "Unpin this reader" : "Keep this reader open";
    keepButton.setAttribute("aria-label", keepButton.title);
    keepButton.setAttribute("aria-pressed", String(pinned));
    keepButton.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 9V4l1-1H7l1 1v5l-3 3v2h14v-2z"/><path d="M12 14v7"/></svg>';
    keepButton.addEventListener("click", () => {
      const current = state.readers.find((candidate) => candidate.id === reader.id);
      if (!current) return;
      const refreshPaneIDs = [paneIDForReader(current)];
      if (searchIDForLinkedReaderPane(`reader:${current.id}`)) {
        keepDerivedReader(current);
      } else if (current.pinnedDetailSourceID) {
        const sourceID = current.pinnedDetailSourceID;
        if (!sectionDetailsBySearch()[sourceID] || columnGroupForPane(paneIDForReader(current))) return;
        const previousID = searchLinkedReadersBySearch()[sourceID];
        const previous = state.readers.find((item) => item.id === previousID);
        if (previous && previous.id !== current.id) {
          keepDerivedReader(previous);
          refreshPaneIDs.push(paneIDForReader(previous));
        }
        state.searchLinkedReaders[sourceID] = current.id;
        current.pinnedDetailSourceID = "";
      } else if (current.pinnedSearchPaneID) {
        const searchPaneID = current.pinnedSearchPaneID;
        const previous = reusableSearchReader(state.readers, searchPaneID);
        if (previous && previous.id !== current.id) {
          previous.pinnedSearchPaneID = searchPaneID;
          previous.searchPreviewPaneID = "";
          refreshPaneIDs.push(paneIDForReader(previous));
        }
        current.searchPreviewPaneID = searchPaneID;
        current.pinnedSearchPaneID = "";
      } else {
        current.pinnedSearchPaneID = current.searchPreviewPaneID;
        current.searchPreviewPaneID = "";
      }
      saveWorkspaceState();
      for (const paneID of refreshPaneIDs) {
        const livePanel = [...track.querySelectorAll(".reader-panel")].find((node) => node.dataset.paneId === paneID);
        const liveReader = state.readers.find((item) => paneIDForReader(item) === paneID);
        if (!livePanel || !liveReader) continue;
        const linked = Boolean(searchIDForLinkedReaderPane(paneID));
        livePanel.classList.toggle("is-search-derived-reader", Boolean(liveReader.searchPreviewPaneID || linked));
        livePanel.classList.toggle("is-recently-viewed-linked-reader", Boolean(liveReader.recentlyViewedSourceSearchID && linked));
        const pin = livePanel.querySelector(".reader-keep-open");
        if (pin) {
          const canToggle = Boolean(liveReader.searchPreviewPaneID || liveReader.pinnedSearchPaneID || liveReader.pinnedDetailSourceID || linked);
          pin.hidden = !canToggle;
          pin.title = (liveReader.pinnedSearchPaneID || liveReader.pinnedDetailSourceID) ? "Unpin this reader" : "Keep this reader open";
          pin.setAttribute("aria-label", pin.title);
          pin.setAttribute("aria-pressed", String(Boolean(liveReader.pinnedSearchPaneID || liveReader.pinnedDetailSourceID)));
        }
        if (!linked) {
          livePanel.querySelector(".reader-internal-search-toggle")?.removeAttribute("hidden");
          livePanel.querySelector(".pane-drag-handle")?.removeAttribute("hidden");
        }
      }
    });
    closeButton.before(keepButton);
  }

  panel.classList.toggle("is-search-derived-reader", Boolean(reader.searchPreviewPaneID || searchIDForLinkedReaderPane(`reader:${reader.id}`)));
  panel.dataset.readerId = reader.id;
  panel.classList.toggle("is-recently-viewed-linked-reader", isRecentlyViewedLinkedReader);
  reader.codePrefix = reader.codePrefix || "BC";
  applyCodeTheme(panel, reader);
  renderReaderTrust(panel, reader);
  applyPaneWeight(panel, paneIDForReader(reader, options));
  applyReaderTextSize(panel, reader);
  applyReaderSpacing(panel, reader);
  selector.hidden = false;
  setTitle(panel, reader);
  referenceSourceButton.hidden = !referenceSourceReader;
  if (referenceSourceReader) {
    referenceSourceButton.title = "Return to source Reader";
    referenceSourceButton.addEventListener("click", () => {
      const sourcePaneID = paneIDForReader(referenceSourceReader);
      scrollPaneIntoView(sourcePaneID);
      track
        .querySelector(`.workspace-panel[data-pane-id="${CSS.escape(sourcePaneID)}"] .code-select`)
        ?.focus({ preventScroll: true });
    });
  }
  internalSearchButton.hidden = isRecentlyViewedLinkedReader;
  dragHandle.hidden = isRecentlyViewedLinkedReader;
  internalSearchBox.hidden = true;
  internalSearchInput.value = reader.internalSearchQuery || "";
  internalSearchClearButton.hidden = !internalSearchInput.value.trim();
  if (options.isSearchResult) {
    closeButton.hidden = false;
  } else {
    closeButton.hidden = false;
  }

  populateCodeSelect(panel, reader);
  codeSelect.addEventListener("change", async () => {
    const selectedCode = codeOptions.find((option) => codeOptionValue(option) === codeSelect.value) || codeOptions[0];
    try {
      const projection = await enabledReaderBrowseProjection([selectedCode]);
      if (!panel.isConnected || !activeCodeSourcesController.isCurrent(projection.token)) return;
      if (!projection.codes.length) {
        codeSelect.value = readerCodeSelectionKey(reader);
        if (codeSelect._customSelectMenu) renderReaderSourceRecovery(codeSelect._customSelectMenu);
        return;
      }
      await changeReaderCode(panel, reader, selectedCode);
    } catch (error) {
      codeSelect.value = readerCodeSelectionKey(reader);
      if (codeSelect._customSelectMenu) renderReaderSourceRecovery(codeSelect._customSelectMenu, error.message);
    }
  });

  internalSearchButton.addEventListener("click", async () => {
    const willOpen = internalSearchBox.hidden;
    if (willOpen) panel._readerSearchReturnPosition = captureReaderScrollPositions().get(panel.dataset.paneId);
    internalSearchBox.hidden = !willOpen;
    internalSearchButton.setAttribute("aria-pressed", String(willOpen));
    if (willOpen) {
      internalSearchInput.value = reader.internalSearchQuery || "";
      internalSearchClearButton.hidden = !internalSearchInput.value.trim();
      internalSearchInput.focus();
      await renderReaderInternalSearchResults(panel, reader, internalSearchInput.value);
      return;
    }
    await restoreReaderAfterSearch(panel, reader);
  });

  panel.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || event.key !== "Escape" || internalSearchBox.hidden) return;
    event.preventDefault();
    event.stopPropagation();
    internalSearchButton.click();
    internalSearchButton.focus({ preventScroll: true });
  });

  internalSearchInput.addEventListener("input", () => {
    cancelReaderInternalSearch(panel);
    reader.internalSearchQuery = internalSearchInput.value;
    internalSearchClearButton.hidden = !internalSearchInput.value.trim();
    saveWorkspaceState();
    clearTimeout(readerSearchTimers.get(reader.id));
    readerSearchTimers.set(reader.id, window.setTimeout(() => {
      renderReaderInternalSearchResults(panel, reader, internalSearchInput.value);
    }, readerInternalSearchDelayMS));
  });

  internalSearchClearButton.addEventListener("click", () => {
    reader.internalSearchQuery = "";
    internalSearchInput.value = "";
    internalSearchClearButton.hidden = true;
    saveWorkspaceState();
    void renderReaderInternalSearchResults(panel, reader, "");
    internalSearchInput.focus();
  });

  closeButton.addEventListener("click", () => {
    beginReaderNavigation(panel);
    if (options.isSearchResult) {
      state.searchResultReader = null;
      state.sectionDetail = null;
      state.sectionDetails = {};
    } else {
      state.readers = state.readers.filter((item) => item.id !== reader.id);
      state.readers.forEach((item) => {
        if (item.referenceSourceReaderID === reader.id) item.referenceSourceReaderID = "";
      });
      Object.keys(searchLinkedReadersBySearch()).forEach((searchID) => {
        if (state.searchLinkedReaders[searchID] === reader.id) delete state.searchLinkedReaders[searchID];
      });
    }
    saveWorkspaceState();
    void transitionWorkspace("utility");
  });

  chapterSelect.addEventListener("change", async () => {
    await selectReaderNavigation(panel, reader, { chapterID: chapterSelect.value });
  });

  sectionSelect.addEventListener("change", async () => {
    await selectReaderNavigation(panel, reader, { sectionID: sectionSelect.value });
  });

  const cancelConstruction = () => {
    panel._readerNavigationAbort?.abort();
    panel.dataset.readerNavigationToken = `cancelled:${crypto.randomUUID()}`;
    panel.dataset.readerRenderToken = panel.dataset.readerNavigationToken;
    stopReaderProgressiveHydration(panel.querySelector(".reader-content"));
  };
  if (options.signal?.aborted) throw new DOMException("Reader cancelled", "AbortError");
  options.signal?.addEventListener("abort", cancelConstruction, { once: true });
  try {
    if (options.isSearchResult && !reader.sectionID) {
      blankReader(panel.querySelector(".reader-content"));
    } else {
      await refreshReaderContent(panel, reader, { scrollPosition: options.scrollPosition });
    }
    return panel;
  } finally {
    options.signal?.removeEventListener("abort", cancelConstruction);
  }
}

function renderSearchPlaceholder(results, message) {
  clear(results);
  const wrapper = document.createElement("section");
  wrapper.className = "reader-empty";
  const heading = document.createElement("h3");
  heading.textContent = message.title;
  const paragraph = document.createElement("p");
  paragraph.textContent = message.body;
  wrapper.append(heading, paragraph);
  results.append(wrapper);
}

function recordRecentSearch(query) {
  const trimmed = String(query || "").trim();
  if (!trimmed) return;
  const searchedAt = Date.now();
  state.recentSearches = normalizeSearchHistory([
    trimmed,
    ...(state.recentSearches || []).filter((item) => item.localeCompare(trimmed, undefined, { sensitivity: "accent" }) !== 0)
  ], recentSearchLimit);
  state.recentSearchHistory = normalizeRecentSearchHistory([
    { query: trimmed, searchedAt },
    ...(state.recentSearchHistory || []).filter((item) =>
      item.query.localeCompare(trimmed, undefined, { sensitivity: "accent" }) !== 0
    )
  ], recentSearchLimit);
  state.recentActivityUpdatedAt = new Date().toISOString();
  saveWorkspaceState();
  scheduleRecentSearchContinuitySync();
}

function isSearchPinned(query) {
  const trimmed = String(query || "").trim();
  return Boolean(trimmed) && (state.pinnedSearches || []).some((item) => item.localeCompare(trimmed, undefined, { sensitivity: "accent" }) === 0);
}

function unpinSearch(query) {
  const trimmed = String(query || "").trim();
  state.pinnedSearches = (state.pinnedSearches || []).filter((item) => item.localeCompare(trimmed, undefined, { sensitivity: "accent" }) !== 0);
  saveWorkspaceState();
}

function removeRecentSearch(query) {
  const trimmed = String(query || "").trim();
  state.recentSearches = (state.recentSearches || []).filter((item) => item.localeCompare(trimmed, undefined, { sensitivity: "accent" }) !== 0);
  state.recentSearchHistory = (state.recentSearchHistory || []).filter((item) =>
    item.query.localeCompare(trimmed, undefined, { sensitivity: "accent" }) !== 0
  );
  state.recentActivityUpdatedAt = new Date().toISOString();
  saveWorkspaceState();
  scheduleRecentSearchContinuitySync();
}

function searchRecentlyViewedEntries() {
  const account = activeAccount();
  const pendingRecord = [...(state.syncOutbox || [])].reverse()
    .filter((entry) => !account || entry.accountUserID === account.userID)
    .map((entry) => mutationKindAndRecord(entry.mutation))
    .find(({ kind }) => kind === "continuity")?.record;
  const syncedEntries = continuityRecentEntries(pendingRecord?.values || syncedContent?.summary?.latestContinuity?.values || {});
  const entries = [...(state.recentlyViewedSections || [])];
  syncedEntries.forEach((entry) => {
    if (!entries.some((candidate) => recentViewIdentity(candidate) === recentViewIdentity(entry))) entries.push(entry);
  });
  return entries
    .filter((entry) => Number(entry?.sectionID) > 0)
    .map((entry) => ({ ...entry, codePrefix: recentViewCodePrefix(entry) }))
    .slice(0, recentViewLimit);
}

function searchProgressLabel(count, options = {}) {
  if (options.status === "unavailable") return "Search unavailable";
  if (options.status === "typing") return "Keep typing";
  if (options.status === "idle") return "";
  if (count === null || count === undefined || options.status === "searching") return "Searching…";
  const loaded = Math.max(0, Number(count) || 0);
  const loadedLabel = loaded.toLocaleString();
  if (options.failed) return `${loadedLabel} loaded · more could not be loaded`;
  if (options.hasMore) {
    const knownTotal = Number(options.totalResults);
    if (Number.isFinite(knownTotal) && knownTotal > loaded) {
      return `${loadedLabel} loaded · ${knownTotal.toLocaleString()} matches`;
    }
    return `${loadedLabel} loaded · more available`;
  }
  if (loaded === 0) return "No matches";
  const matchLabel = loaded === 1 ? "Match" : "Matches";
  return `${loadedLabel} ${matchLabel}`;
}

function searchSummaryStatus(count, options = {}) {
  if (options.status === "unavailable") return "unavailable";
  if (options.status === "typing") return "typing";
  if (options.status === "idle") return "idle";
  if (count === null || count === undefined || options.status === "searching") return "searching";
  if (options.failed) return "incomplete";
  if (options.hasMore) return "partial";
  return "complete";
}

function searchGroupCountText(count, hasMore) {
  const loaded = Math.max(0, Number(count) || 0);
  const loadedLabel = loaded.toLocaleString();
  return hasMore ? `${loadedLabel} loaded` : loadedLabel;
}

function refreshSearchGroupCounts(results) {
  if (!results) return;
  results.querySelectorAll(".search-result-group").forEach((group) => {
    const hasMore = (group.dataset.searchHasMore ?? results.dataset.searchHasMore) === "true";
    const count = group.querySelector(".search-result-group-count");
    if (!count) return;
    const loaded = group.querySelectorAll(".result-row").length;
    count.textContent = searchGroupCountText(loaded, hasMore);
    count.title = hasMore
      ? `${loaded.toLocaleString()} loaded. More results may be in this edition.`
      : `${loaded.toLocaleString()} ${loaded === 1 ? "result" : "results"}`;
  });
}

function updateSearchDock(panel, instance, resultCount = null, options = {}) {
  const query = String(instance?.query || "").trim();
  const summary = panel.querySelector(".search-result-summary");
  const summaryCopy = panel.querySelector(".search-result-summary-copy");
  const clearButton = panel.querySelector(".search-clear-button");
  clearButton.hidden = !query;
  summary.hidden = !query;
  if (!query) {
    summary.dataset.searchStatus = "idle";
    summaryCopy.setAttribute("aria-live", "off");
    summaryCopy.textContent = "";
    return;
  }
  const resolvedOptions = resultCount === null && !options.status && query.length < 2
    ? { ...options, status: "typing" }
    : options;
  const nextStatus = searchSummaryStatus(resultCount, resolvedOptions);
  const announce = nextStatus !== (summary.dataset.searchStatus || "") &&
    nextStatus !== "typing" &&
    nextStatus !== "idle";
  summary.dataset.searchStatus = nextStatus;
  summaryCopy.setAttribute("aria-live", announce ? "polite" : "off");
  summaryCopy.textContent = searchProgressLabel(resultCount, resolvedOptions);
}

async function hydrateSearchRecentlyViewedEntries(entries, options = {}) {
  const hydratedEntries = await Promise.all(entries.map(async (entry) => {
    // Legacy history has no trustworthy edition. Keep it intact until an explicit
    // open resolves its canonical section through the source navigation guard.
    if (!recentViewSourceVersion(entry)) return entry;
    if (recentlyViewedPreviewHasEnactedText(entry)) return entry;
    try {
      const detail = recentViewNavigationSource(entry);
      const { chapter, section } = await resolveSectionDetail(detail);
      const rawPreview = sectionPlainText(section);
      const sectionNumber = section?.sectionNumber || detail.sectionNumber || entry.sectionNumber || "";
      const sectionTitle = section?.title || detail.title || entry.title || "";
      const titleWithoutNumber = stripLeadingSectionNumber(sectionTitle, sectionNumber);
      const isNestedListParagraph = !rawPreview && Boolean(titleWithoutNumber);
      const previewSource = rawPreview || (
        isNestedListParagraph
          ? titleWithoutNumber
          : entry.previewText || ""
      );
      const hydratedEntry = {
        ...entry,
        codePrefix: detail.codePrefix || chapter?.codePrefix || entry.codePrefix || "BC",
        chapterID: detail.chapterID || chapter?.id || entry.chapterID || "",
        chapterNumber: detail.chapterNumber || chapter?.chapterNumber || entry.chapterNumber || "",
        sectionNumber,
        title: sectionTitle || "Section",
        isNestedListParagraph,
        previewText: (isNestedListParagraph ? previewSource : snippetWithoutDuplicateTitle({
          sectionNumber,
          title: sectionTitle,
          snippet: previewSource
        })).replace(/\s+/g, " ").trim().slice(0, 360)
      };
      options.onEntry?.(hydratedEntry);
      return hydratedEntry;
    } catch {
      return entry;
    }
  }));
  const changed = mergeRecentlyViewedDetails(hydratedEntries);
  if (changed) scheduleRecentSearchContinuitySync();
  return hydratedEntries;
}

function updateVisibleSearchHistoryEntry(panel, entry) {
  const identity = recentViewIdentity(entry);
  if (!identity) return;
  const tile = panel.querySelector(
    `.search-jump-tile[data-recent-view-identity="${CSS.escape(identity)}"]`
  );
  const preview = tile?.querySelector(".search-jump-preview");
  if (!preview || !entry.previewText) return;
  preview.textContent = entry.previewText;
  markResearchSelectable(preview, entry);
}

async function openRecentlyViewedInReader(searchInstance, entry) {
  if (!searchInstance?.id || !entry) return;
  try {
    await openSourceInReader(recentViewNavigationSource(entry), paneIDForUtilityInstance(searchInstance), {
      sourceSurface: "search"
    });
  } catch (error) {
    console.warn("Could not open recently viewed section.", error);
    presentWorkspaceIssue(error?.message || "This section could not be loaded. Try opening it again.");
  }
}

function setSearchRecentPopoverOpen(panel, requestedOpen) {
  const input = panel.querySelector(".search-input");
  const popover = panel.querySelector(".search-recent-popover");
  if (!input || !popover) return;
  const open = Boolean(
    requestedOpen &&
    !String(input.value || "").trim() &&
    popover.dataset.hasItems === "true"
  );
  window.clearTimeout(popover.hideTimer);
  input.setAttribute("aria-expanded", String(open));
  if (open) {
    popover.hidden = false;
    requestAnimationFrame(() => popover.classList.add("is-open"));
    return;
  }
  popover.classList.remove("is-open");
  popover.hideTimer = window.setTimeout(() => {
    if (!popover.classList.contains("is-open")) popover.hidden = true;
  }, 280);
}

function renderSearchRecentPopover(panel, instance) {
  const input = panel.querySelector(".search-input");
  const popover = panel.querySelector(".search-recent-popover");
  if (!input || !popover) return;
  const wasOpen = popover.classList.contains("is-open");
  if (panel.__workspaceAccessGate && !panel.__workspaceAccessGate.allowed) {
    clear(popover);
    setSearchRecentPopoverOpen(panel, false);
    return;
  }
  const queries = normalizeSearchHistory(state.recentSearches, recentSearchPopoverLimit);
  clear(popover);
  popover.dataset.hasItems = String(queries.length > 0);
  popover.id = `search-recent-popover-${instance.id}`;
  input.setAttribute("aria-controls", popover.id);
  input.setAttribute("aria-haspopup", "true");
  input.setAttribute("aria-expanded", String(wasOpen && queries.length > 0));
  if (!queries.length) {
    setSearchRecentPopoverOpen(panel, false);
    return;
  }
  const list = document.createElement("div");
  list.className = "search-recent-popover-list";
  queries.forEach((query) => {
    const row = document.createElement("article");
    row.className = "search-history-row";
    const applyButton = document.createElement("button");
    applyButton.type = "button";
    applyButton.className = "search-history-apply";
    applyButton.innerHTML = "<span></span>";
    applyButton.querySelector("span").textContent = query;
    applyButton.addEventListener("click", () => {
      instance.query = query;
      input.value = query;
      recordRecentSearch(query);
      setSearchRecentPopoverOpen(panel, false);
      updateSearchDock(panel, instance);
      renderSearchResults(panel, instance);
    });
    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "search-history-action";
    removeButton.setAttribute("aria-label", `Remove ${query} from recent searches`);
    removeButton.innerHTML = circleXIconSVG();
    removeButton.addEventListener("click", () => {
      removeRecentSearch(query);
      renderSearchRecentPopover(panel, instance);
      input.focus({ preventScroll: true });
      setSearchRecentPopoverOpen(panel, true);
    });
    row.append(applyButton, removeButton);
    list.append(row);
  });
  popover.append(list);
  if (wasOpen) setSearchRecentPopoverOpen(panel, true);
}

async function renderSearchHistory(panel, instance, options = {}) {
  const results = panel.querySelector(".search-results");
  if (panel.__workspaceAccessGate && !panel.__workspaceAccessGate.allowed) {
    renderSearchPlaceholder(results, { title: "Search code text", body: "Enter a word or section number to search." });
    return;
  }
  const recentEntries = searchRecentlyViewedEntries();
  const recentSections = options.hydrate === false
    ? recentEntries
    : await hydrateSearchRecentlyViewedEntries(recentEntries, {
      onEntry: (entry) => updateVisibleSearchHistoryEntry(panel, entry)
    });
  if (String(instance?.query || "").trim()) return;
  clear(results);
  results.classList.add("is-history");
  results.classList.remove("is-split");
  results.style.removeProperty("--search-history-upper-size");

  let jumpSection = null;
  if (recentSections.length) {
    const section = document.createElement("section");
    section.className = "search-history-section search-jump-section";
    section.id = `search-jump-${instance.id}`;
    const list = document.createElement("div");
    list.className = "search-history-list search-history-scroll-list search-jump-list";
    recentSections.forEach((entry) => {
      const tile = document.createElement("article");
      tile.className = `search-jump-tile code-theme-${codeTheme(entry.codePrefix || "BC")}`;
      tile.dataset.recentViewIdentity = recentViewIdentity(entry);
      const openButton = document.createElement("button");
      openButton.type = "button";
      openButton.className = "search-jump-open";
      const code = document.createElement("span");
      code.className = "search-jump-code";
      code.textContent = recentViewSourceLabel(entry);
      const title = document.createElement("strong");
      title.textContent = entry.isNestedListParagraph
        ? String(entry.sectionNumber || "Paragraph").trim()
        : sectionDisplayTitle(entry.sectionNumber, entry.title, "Section");
      const preview = document.createElement("span");
      preview.className = "search-jump-preview";
      preview.textContent = entry.previewText || "";
      if (entry.previewText) markResearchSelectable(preview, entry);
      openButton.append(code, title, preview);
      openButton.addEventListener("click", () => {
        if (window.getSelection && String(window.getSelection()).trim()) return;
        void openRecentlyViewedInReader(instance, entry);
      });
      const openNewButton = document.createElement("button");
      openNewButton.type = "button";
      openNewButton.className = "search-open-new-reader workflow-action workflow-action-secondary";
      openNewButton.textContent = "New reader";
      openNewButton.title = "Open this source in an additional Reader beside Search";
      openNewButton.addEventListener("click", () => {
        void openSourceInReader(recentViewNavigationSource(entry), paneIDForUtilityInstance(instance), {
          sourceSurface: "search", forceNewReader: true
        });
      });
      const actions = document.createElement("div");
      actions.className = "saved-row-actions search-row-actions";
      actions.append(openNewButton);
      tile.append(openButton, actions);
      list.append(tile);
    });
    section.append(list);
    jumpSection = section;
  }

  if (jumpSection) {
    results.append(jumpSection);
    const list = jumpSection.querySelector(".search-jump-list");
    requestAnimationFrame(() => {
      if (!list.isConnected || String(instance.query || "").trim()) return;
      list.scrollTop = Math.max(0, Number(instance.historyScrollTop) || 0);
    });
  }
  renderSearchRecentPopover(panel, instance);
}

function hydrateSearchPanelWhenConnected(panel, searchInstance, attempt = 0) {
  if (!panel.isConnected) {
    if (attempt < 120) {
      requestAnimationFrame(() => hydrateSearchPanelWhenConnected(panel, searchInstance, attempt + 1));
    }
    return;
  }
  void (async () => {
    const hasQuery = Boolean(String(searchInstance?.query || "").trim());
    const syncPromise = loadSyncedContent();
    await renderSearchResults(panel, searchInstance);
    if (!panel.isConnected) return;
    await syncPromise;
    if (!panel.isConnected || hasQuery) return;
    await renderSearchResults(panel, searchInstance);
  })();
}

function bindSearchHistoryDivider(results, divider, instance) {
  const applyRatio = (value) => {
    const ratio = normalizeSearchHistorySplitRatio(value);
    instance.historySplitRatio = ratio;
    results.style.setProperty("--search-history-upper-size", `${ratio * 100}%`);
    divider.setAttribute("aria-valuemin", "20");
    divider.setAttribute("aria-valuemax", "80");
    divider.setAttribute("aria-valuenow", String(Math.round(ratio * 100)));
  };
  applyRatio(instance.historySplitRatio);

  const resize = (event) => {
    const bounds = results.getBoundingClientRect();
    if (!bounds.height) return;
    applyRatio((event.clientY - bounds.top) / bounds.height);
  };
  const endResize = (event) => {
    divider.classList.remove("is-dragging");
    document.body.classList.remove("is-resizing-search-history");
    divider.releasePointerCapture?.(event.pointerId);
    saveWorkspaceState();
    window.removeEventListener("pointermove", resize);
    window.removeEventListener("pointerup", endResize);
    window.removeEventListener("pointercancel", endResize);
  };

  divider.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    divider.setPointerCapture?.(event.pointerId);
    divider.classList.add("is-dragging");
    document.body.classList.add("is-resizing-search-history");
    resize(event);
    window.addEventListener("pointermove", resize);
    window.addEventListener("pointerup", endResize);
    window.addEventListener("pointercancel", endResize);
  });
  divider.addEventListener("keydown", (event) => {
    const direction = event.key === "ArrowUp" ? -1 : event.key === "ArrowDown" ? 1 : 0;
    if (!direction && event.key !== "Home" && event.key !== "End") return;
    event.preventDefault();
    const ratio = event.key === "Home"
      ? 0.2
      : event.key === "End"
        ? 0.8
        : normalizeSearchHistorySplitRatio(instance.historySplitRatio) + direction * 0.04;
    applyRatio(ratio);
    saveWorkspaceState();
  });
}

function bindHorizontalWheelScroll(element, options = {}) {
  if (!element || element.dataset.horizontalWheelBound === "true") return;
  element.dataset.horizontalWheelBound = "true";
  element.addEventListener(
    "wheel",
    (event) => {
      if (event.defaultPrevented || event.ctrlKey || event.metaKey) return;
      let delta = event.deltaX;
      if (options.shiftWheel && event.shiftKey) {
        delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
      } else {
        if (Math.abs(event.deltaX) <= Math.abs(event.deltaY)) return;
      }
      const canScroll = element.scrollWidth > element.clientWidth;
      if (!canScroll) return;
      if (!delta) return;
      if (event.deltaMode === 1) delta *= 16;
      if (event.deltaMode === 2) delta *= element.clientWidth;
      const nextLeft = element.scrollLeft + delta;
      const maxLeft = element.scrollWidth - element.clientWidth;
      const isAtStart = element.scrollLeft <= 0;
      const isAtEnd = element.scrollLeft >= maxLeft - 1;
      if (!options.contain && ((delta < 0 && isAtStart) || (delta > 0 && isAtEnd))) return;
      event.preventDefault();
      element.scrollLeft = Math.max(0, Math.min(maxLeft, nextLeft));
    },
    { passive: false }
  );
}


function createSearchResultSaveButton(panel, detail, options = {}) {
  const saveButton = document.createElement("button");
  saveButton.type = "button";
  saveButton.className = "search-result-save";
  saveButton.dataset.savedEvidenceKey = savedEvidenceKey(detail);
  let initializing = true;
  let initialized = false;
  const initialize = () => {
    if (initializing && initialized) return;
    if (panel.__workspaceAccessGate && !panel.__workspaceAccessGate.allowed) return;
    saveButton.hidden = false;
    saveButton.disabled = false;
    const saved = initializing && options.bookmarkStateResolved ? options.showBookmark : isSectionSaved(detail);
    syncImmediateBookmarkButton(saveButton, Boolean(saved));
    initialized = true;
  };
  saveButton.hidden = Boolean(panel.__workspaceAccessGate && !panel.__workspaceAccessGate.allowed);
  saveButton.disabled = saveButton.hidden;
  if (panel.__workspaceAccessGate) subscribeWorkspaceNodeAccess(saveButton, panel.__workspaceAccessGate, initialize, panel);
  if (!saveButton.hidden) initialize();
  initializing = false;
  saveButton.addEventListener("click", async () => {
    if (saveButton.disabled || (panel.__workspaceAccessGate && !panel.__workspaceAccessGate.allowed)) return;
    const shouldRemove = saveButton.classList.contains("is-saved");
    saveButton.disabled = true;
    saveButton.classList.remove("has-error");
    try {
      const persisted = await persistSectionBookmark(detail, !shouldRemove, {
        refreshSavedPanes: false
      });
      if (persisted === false) return;
      await refreshOpenSavedPanes();
      syncReaderNoteBookmarkButtons(detail.sectionID, !shouldRemove, detail.codeVersion);
      syncSearchResultBookmarkButtons(detail, !shouldRemove);
      if (!shouldRemove) {
        showReaderSaveConfirmation(panel, detail, {
          focusTarget: saveButton
        });
      }
      refreshVisibleSyncedDerivedState();
    } catch (error) {
      saveButton.classList.add("has-error");
      await showWebNotice(
        shouldRemove ? "Saved passage not removed" : "Passage not saved",
        error.message || "This saved passage could not be updated."
      );
    } finally {
      if (saveButton.isConnected) saveButton.disabled = false;
    }
  });

  return saveButton;
}

function installSearchQueryInputHandlers(panel, searchInstance, input, paneID) {
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  let composing = false;
  const current = () => isCurrentAccountRequest(identity) && workspaceID === activeWorkspaceID;
  const update = (event = {}) => {
    if (!current()) return;
    searchInstance.query = input.value;
    cancelSearchPanelRequest(panel);
    clearTimeout(searchTimers.get(paneID));
    scheduleSearchQueryPersistence();
    updateSearchDock(panel, searchInstance);
    if (composing || event.isComposing) return;
    const details = sectionDetailsBySearch();
    if (!searchInstance.query.trim() && details[searchInstance.id]) {
      delete details[searchInstance.id];
      void transitionWorkspace("utility");
    }
    searchTimers.set(paneID, setTimeout(() => {
      if (current() && panel.isConnected) void renderSearchResults(panel, searchInstance);
    }, 250));
    setSearchRecentPopoverOpen(panel, !searchInstance.query.trim());
  };
  input.addEventListener("compositionstart", () => {
    composing = true;
    clearTimeout(searchTimers.get(paneID));
    cancelSearchPanelRequest(panel);
  });
  input.addEventListener("compositionend", () => { composing = false; update(); });
  input.addEventListener("input", update);
  input.addEventListener("blur", () => { if (current()) flushSearchQueryPersistence(); });
  input.addEventListener("keydown", (event) => {
    if (!current() || composing || event.isComposing || event.keyCode === 229) return;
    if (event.key === "Enter") {
      flushSearchQueryPersistence();
      recordRecentSearch(searchInstance.query);
    }
    if (event.key === "Escape") {
      event.preventDefault();
      setSearchRecentPopoverOpen(panel, false);
    }
    if (event.key === "ArrowDown" && input.getAttribute("aria-expanded") === "true") {
      event.preventDefault();
      panel.querySelector(".search-recent-popover .search-history-apply")?.focus({ preventScroll: true });
    }
  });
}

async function renderSearch(instance, options = {}) {
  const searchInstance = normalizeSearchInstance(instance);
  const hadRetiredFilters = normalizeSearchCodeFilters(searchInstance.codeFilters).length > 0 ||
    searchInstance.searchEdition !== "all" || Boolean(searchInstance.codeFilterMenuOpen);
  searchInstance.codeFilters = [];
  searchInstance.searchEdition = "all";
  searchInstance.codeFilterMenuOpen = false;
  if (hadRetiredFilters) saveWorkspaceState();
  const paneID = paneIDForUtilityInstance(searchInstance);
  const panel = searchTemplate.content.firstElementChild.cloneNode(true);
  panel.__workspaceAccessGate = options.accessGate || null;
  const input = panel.querySelector(".search-input");
  const matchControl = panel.querySelector(".search-match-control");
  const matchLabel = panel.querySelector(".search-match-mode");
  const matchAlternative = panel.querySelector(".search-match-alternative");
  const updateMatchLabels = () => {
    const exact = searchInstance.matchMode === "exact";
    matchLabel.textContent = exact ? "Exact phrase" : "All words";
    matchLabel.setAttribute("aria-label", `Search matching: ${matchLabel.textContent}`);
    matchAlternative.querySelector("span").textContent = exact ? "All words" : "Exact phrase";
  };
  updateMatchLabels();
  matchAlternative.addEventListener("click", () => {
    searchInstance.matchMode = searchInstance.matchMode === "exact" ? "words" : "exact";
    updateMatchLabels();
    matchControl.open = false;
    matchLabel.focus({ preventScroll: true });
    saveWorkspaceState();
    void renderSearchResults(panel, searchInstance);
  });
  matchControl.addEventListener("keydown", event => {
    if (event.key === "Escape" && matchControl.open) {
      event.preventDefault();
      event.stopPropagation();
      matchControl.open = false;
      matchLabel.focus({ preventScroll: true });
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      event.stopPropagation();
      matchControl.open = true;
      matchAlternative.focus({ preventScroll: true });
    } else if (event.key === "ArrowUp" && event.target !== matchLabel) {
      event.preventDefault();
      event.stopPropagation();
      matchLabel.focus({ preventScroll: true });
    }
  });
  matchControl.addEventListener("focusout", event => {
    if (!matchControl.contains(event.relatedTarget)) matchControl.open = false;
  });
  const sourcesButton = panel.querySelector(".search-sources-button");
  sourcesButton.setAttribute("aria-expanded", "false");
  sourcesButton.setAttribute("aria-haspopup", "menu");
  sourcesButton.addEventListener("click", () => openSearchCodeSourceSettings(panel));
  const clearButton = panel.querySelector(".search-clear-button");
  applyPaneWeight(panel, paneID);
  input.value = searchInstance.query || "";
  const resultsScroller = panel.querySelector(".search-results");
  let scrollSaveTimer;
  resultsScroller.addEventListener("scroll", (event) => {
    if (resultsScroller.dataset.restoringSearch === "true") return;
    if (event.target.matches?.(".search-jump-list")) {
      searchInstance.historyScrollTop = event.target.scrollTop;
    } else if (event.target === resultsScroller && String(searchInstance.query || "").trim()) {
      searchPositionState(searchInstance).scrollTop = resultsScroller.scrollTop;
    } else return;
    clearTimeout(scrollSaveTimer);
    scrollSaveTimer = setTimeout(() => saveWorkspaceState(), 150);
  }, { passive: true, capture: true });
  updateSearchDock(panel, searchInstance);
  renderSearchRecentPopover(panel, searchInstance);

  const closeRecentPopoverFromOutside = (event) => {
    if (!panel.isConnected) {
      document.removeEventListener("pointerdown", closeRecentPopoverFromOutside, true);
      return;
    }
    if (!panel.querySelector(".search-dock")?.contains(event.target)) {
      setSearchRecentPopoverOpen(panel, false);
    }
  };
  document.addEventListener("pointerdown", closeRecentPopoverFromOutside, true);

  const openRecentPopover = () => setSearchRecentPopoverOpen(panel, true);
  input.addEventListener("focus", openRecentPopover);
  input.addEventListener("click", openRecentPopover);

  installSearchQueryInputHandlers(panel, searchInstance, input, paneID);

  clearButton.addEventListener("click", () => {
    cancelSearchPanelRequest(panel);
    clearTimeout(searchTimers.get(paneID));
    searchInstance.query = "";
    input.value = "";
    saveWorkspaceState();
    updateSearchDock(panel, searchInstance);
    renderSearchHistory(panel, searchInstance);
    input.focus();
    setSearchRecentPopoverOpen(panel, true);
  });

  if (String(searchInstance.query || "").trim()) {
    renderSearchPlaceholder(panel.querySelector(".search-results"), {
      title: "Searching",
      body: "Checking section titles and code text."
    });
  } else {
    await renderSearchHistory(panel, searchInstance, { hydrate: false });
  }
  if (panel.__workspaceAccessGate) {
    subscribeWorkspaceNodeAccess(panel, panel.__workspaceAccessGate, () => {
      if (!panel.__workspaceAccessGate.allowed) return;
      renderSearchRecentPopover(panel, searchInstance);
      if (!String(searchInstance.query || "").trim()) void renderSearchHistory(panel, searchInstance);
    });
  }
  requestAnimationFrame(() => hydrateSearchPanelWhenConnected(panel, searchInstance));
  return panel;
}

function renderSearchCodeFilter(filterRail, panel, instance) {
  const searchInstance = normalizeSearchInstance(instance);
  clear(filterRail);
  const options = searchCodeFilterOptions();
  const validPrefixes = new Set(options.map((option) => option.prefix));
  const normalizedFilters = normalizeSearchCodeFilters(searchInstance.codeFilters);
  searchInstance.codeFilters = normalizedFilters.filter((prefix) => validPrefixes.has(prefix));
  if (searchInstance.codeFilters.length !== normalizedFilters.length) {
    saveWorkspaceState();
  }
  const editionLabel = document.createElement("label");
  editionLabel.textContent = "Search editions ";
  const editionSelect = document.createElement("select");
  editionSelect.setAttribute("aria-label", "Search editions");
  for (const [value, label] of [["all", "All editions"], [historicalConstructionSyncCodeVersion, "2014 construction codes"]]) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    editionSelect.append(option);
  }
  editionSelect.value = searchInstance.searchEdition || "all";
  editionSelect.addEventListener("change", () => {
    searchInstance.searchEdition = editionSelect.value;
    saveWorkspaceState();
    void renderSearchResults(panel, searchInstance);
  });
  editionLabel.append(editionSelect);
  filterRail.append(editionLabel);
  const appendChip = (option, parent) => {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "search-filter-chip";
    chip.title = [option.label, option.detail].filter(Boolean).join(" · ");
    const chipTitle = document.createElement("span");
    chipTitle.className = "search-filter-chip-title";
    chipTitle.textContent = option.label;
    chip.append(chipTitle);
    if (option.detail) {
      const chipDetail = document.createElement("small");
      chipDetail.className = "search-filter-chip-detail";
      chipDetail.textContent = option.detail;
      chip.append(chipDetail);
    }
    chip.dataset.prefix = option.prefix;
    if (option.prefix !== "ALL") {
      chip.classList.add(`code-theme-${codeTheme(option.prefix)}`);
    }
    const isAll = option.prefix === "ALL";
    const isSelected = isAll ? searchInstance.codeFilters.length === 0 : searchInstance.codeFilters.includes(option.prefix);
    chip.setAttribute("aria-pressed", String(isSelected));
    chip.addEventListener("click", () => {
      if (isAll) {
        searchInstance.codeFilters = [];
      } else {
        const selected = new Set(normalizeSearchCodeFilters(searchInstance.codeFilters));
        if (selected.has(option.prefix)) {
          selected.delete(option.prefix);
        } else {
          selected.add(option.prefix);
        }
        searchInstance.codeFilters = Array.from(selected);
      }
      saveWorkspaceState();
      updateSearchCodeFilterStates(filterRail, searchInstance);
      updateCodeFilterMenu(filterRail, searchInstance);
      updateSearchDock(panel, searchInstance);
      renderSearchResults(panel, searchInstance);
    });
    parent.append(chip);
  };

  appendChip(options[0], filterRail);
  const groupedOptions = new Map();
  options.slice(1).forEach((option) => {
    const groupName = option.group || "Other Codes";
    if (!groupedOptions.has(groupName)) groupedOptions.set(groupName, []);
    groupedOptions.get(groupName).push(option);
  });
  groupedOptions.forEach((groupOptions, groupName) => {
    const group = document.createElement("section");
    group.className = "search-code-filter-group";
    const heading = document.createElement("h3");
    heading.className = "search-code-filter-group-title";
    heading.textContent = groupName;
    group.append(heading);
    groupOptions.forEach((option) => appendChip(option, group));
    filterRail.append(group);
  });
}

function updateSearchCodeFilterStates(filterRail, instance) {
  const selectedFilters = normalizeSearchCodeFilters(instance?.codeFilters);
  filterRail.querySelectorAll(".search-filter-chip").forEach((chip) => {
    const prefix = chip.dataset.prefix || "ALL";
    const isSelected = prefix === "ALL" ? selectedFilters.length === 0 : selectedFilters.includes(prefix);
    chip.setAttribute("aria-pressed", String(isSelected));
  });
}

function syncImmediateBookmarkButton(button, saved) {
  if (!button) return;
  button.classList.toggle("is-saved", Boolean(saved));
  button.setAttribute("aria-pressed", String(Boolean(saved)));
  button.setAttribute("aria-label", bookmarkActionLabel(saved));
  button.title = bookmarkActionLabel(saved);
  button.innerHTML = bookmarkIconSVG(Boolean(saved));
}

function syncSearchResultBookmarkButtons(sectionPayload, saved) {
  const sectionKey = savedEvidenceKey(sectionPayload);
  track.querySelectorAll(".search-result-save[data-saved-evidence-key]").forEach((button) => {
    const gate = button.closest(".search-panel")?.__workspaceAccessGate;
    if (gate && !gate.allowed) return;
    if (button.dataset.savedEvidenceKey === sectionKey) {
      syncImmediateBookmarkButton(button, saved);
    }
  });
}

function cancelSearchPanelRequest(panel) {
  panel?.__searchRequestController?.abort();
  if (!panel) return;
  panel.__searchRequestController = null;
  const results = panel.querySelector(".search-results");
  if (results) {
    delete results.dataset.searchRenderToken;
    results.dataset.restoringSearch = "false";
    results.searchLoadMore = null;
    results.searchGroupPages = null;
  }
}

async function renderSearchResults(panel, instance) {
  cancelSearchPanelRequest(panel);
  const searchInstance = normalizeSearchInstance(instance);
  const results = panel.querySelector(".search-results");
  const query = searchInstance.query.trim();
  const matchMode = searchInstance.matchMode || "exact";
  const selectedPrefixes = normalizeSearchCodeFilters(searchInstance.codeFilters);
  const position = searchPositionState(searchInstance);
  const restorePages = (Number.isSafeInteger(position.loadedPages) && position.loadedPages > 0 ? Math.min(position.loadedPages, 1000) : 1);
  const restoreScrollTop = Math.max(0, Number(position.scrollTop) || 0);
  const renderToken = crypto.randomUUID();
  const controller = new AbortController();
  panel.__searchRequestController = controller;
  const edition = searchInstance.searchEdition || "all";
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  let sourceScope = null;
  const isCurrent = () => (sourceScope === null || isCurrentActiveCodeSourceContext(sourceScope.token)) && !controller.signal.aborted && panel.isConnected &&
    panel.__searchRequestController === controller && isCurrentAccountRequest(identity) &&
    activeWorkspaceID === workspaceID && results.dataset.searchRenderToken === renderToken &&
    searchInstance.query.trim() === query && (searchInstance.matchMode || "exact") === matchMode && (searchInstance.searchEdition || "all") === edition &&
    normalizeSearchCodeFilters(searchInstance.codeFilters).join(",") === selectedPrefixes.join(",");
  results.dataset.searchRenderToken = renderToken;
  results.dataset.restoringSearch = "true";
  results.searchLoadMore = null;
  results.searchGroupPages = null;
  results.classList.remove("is-history");
  if (query.length < 2) {
    results.dataset.searchHasMore = "false";
    updateSearchDock(panel, searchInstance, null, { status: query ? "typing" : "idle" });
    if (!query) await renderSearchHistory(panel, searchInstance);
    else renderSearchPlaceholder(results, { title: "Keep typing", body: "Enter at least two characters to search the code text." });
    if (isCurrent()) results.dataset.restoringSearch = "false";
    return;
  }

  updateSearchDock(panel, searchInstance, null, { status: "searching" });
  renderSearchPlaceholder(results, { title: "Searching", body: "Checking section titles and code text." });
  const codeQuery = selectedPrefixes.length ? `&code=${encodeURIComponent(selectedPrefixes.join(","))}` : "";
  let payload;
  try {
    sourceScope = await prepareActiveCodeSearchScope();
    if (!isCurrent()) return;
    if (sourceScope.enabledSourceCount === 0) {
      results.dataset.restoringSearch = "false";
      results.dataset.searchHasMore = "false";
      updateSearchDock(panel, searchInstance, 0, { hasMore: false });
      renderSearchPlaceholder(results, { title: "All code sources are off",
        body: "Enable a code source to search its text. Your query and search history are still here." });
      const manage = document.createElement("button");
      manage.type = "button";
      manage.className = "ghost-button search-empty-action";
      manage.textContent = "Manage code sources";
      manage.addEventListener("click", () => { if (isCurrent()) openSearchCodeSourceSettings(panel); });
      results.append(manage);
      return;
    }
    payload = await api(
      `/code/search?q=${encodeURIComponent(query)}${codeQuery}&version=${encodeURIComponent(edition)}&match=${matchMode}&readerSourceMetadata=1&limit=${searchResultPageSize}&offset=0&candidateOffset=0&grouped=true${sourceScope.querySuffix}`, { signal: controller.signal }
    );
  } catch (error) {
    if (!isCurrent()) return;
    results.dataset.restoringSearch = "false";
    results.dataset.searchHasMore = "false";
    updateSearchDock(panel, searchInstance, null, { status: "unavailable" });
    renderSearchPlaceholder(results, { title: "Search unavailable", body: error?.message || "Your query is still here. Try again when the connection returns." });
    const retry = document.createElement("button");
    retry.type = "button";
    retry.textContent = "Try again";
    retry.addEventListener("click", () => { void renderSearchResults(panel, searchInstance); });
    results.append(retry);
    return;
  }
  if (!isCurrent()) return;
  clear(results);

  const filteredResults = (payload.results || []).filter((result) =>
    (selectedPrefixes.length === 0 || selectedPrefixes.includes(result.codePrefix || "BC")) &&
    (matchMode === "words" || searchResultMatchesExactQuery(result, query))
  );

  if (filteredResults.length === 0 && !payload.hasMore) {
    results.dataset.restoringSearch = "false";
    results.dataset.searchHasMore = "false";
    updateSearchDock(panel, searchInstance, 0, { hasMore: false });
    const scoped = Boolean(sourceScope?.querySuffix);
    const scope = selectedPrefixes.length
      ? `${scoped ? "enabled sources within " : ""}${selectedPrefixes.join(", ")}`
      : scoped ? "your enabled code sources" : "all codes";
    const terms = [...new Set(query.match(/[\p{L}\p{N}][\p{L}\p{N}.-]*/gu) || [])]
      .filter((term) => term.length >= 2 && !/^(a|an|and|are|as|at|be|by|for|from|in|is|it|of|on|or|the|to|with)$/i.test(term))
      .filter((term) => term.toLowerCase() !== query.toLowerCase())
      .slice(0, 4);
    renderSearchPlaceholder(results, {
      title: matchMode === "words" ? "No matches for all words" : "No exact match",
      body: matchMode === "words" ? `No section containing all these words was found in ${scope}. Try fewer words or a section number.` : `Search looks for this phrase together in section titles or code text. It was not found in ${scope}. Try a shorter phrase or a section number${terms.length ? ", or search one term below." : "."}`
    });
    for (const term of terms) {
      const termButton = document.createElement("button");
      termButton.type = "button";
      termButton.className = "ghost-button search-empty-action";
      termButton.textContent = `Search “${term}”`;
      termButton.addEventListener("click", () => {
        searchInstance.query = term;
        panel.querySelector(".search-input").value = term;
        clearTimeout(searchTimers.get(paneIDForUtilityInstance(searchInstance)));
        saveWorkspaceState();
        setSearchRecentPopoverOpen(panel, false);
        void renderSearchResults(panel, searchInstance);
      });
      results.querySelector(".reader-empty")?.append(termButton);
    }
    if (selectedPrefixes.length) {
      const showAllButton = document.createElement("button");
      showAllButton.type = "button";
      showAllButton.className = "ghost-button search-empty-action";
      showAllButton.textContent = scoped ? "Search all enabled sources" : "Search all codes";
      showAllButton.addEventListener("click", () => {
        searchInstance.codeFilters = [];
        saveWorkspaceState();
        updateSearchCodeFilterStates(panel.querySelector(".search-code-filter"), searchInstance);
        updateSearchDock(panel, searchInstance);
        renderSearchResults(panel, searchInstance);
      });
      results.querySelector(".reader-empty")?.append(showAllButton);
    }
    return;
  }

  position.loadedPages = 1;
  results.dataset.loadedSearchPages = "1";
  results.dataset.searchHasMore = payload.hasMore ? "true" : "false";
  const resultCount = filteredResults.length;
  const totalResults = Number.isFinite(Number(payload.totalResults)) && Number(payload.totalResults) > resultCount
    ? Number(payload.totalResults)
    : null;
  updateSearchDock(panel, searchInstance, resultCount, {
    hasMore: Boolean(payload.hasMore),
    totalResults
  });
  if (applyInitialSearchGroupExpansion(searchInstance, filteredResults, sourceScope, { hasMore: Boolean(payload.hasMore) })) saveWorkspaceState();
  appendSearchResultGroups(results, filteredResults, query, searchInstance);
  if (Array.isArray(payload.groups)) {
    const options = { query, matchMode, searchInstance, panel, edition, controller, isCurrent, sourceScope };
    const restoreGroups = position.groupScope === sourceScope.querySuffix ? { ...position.groupPages } : {};
    position.groupScope = sourceScope.querySuffix;
    position.groupPages = {};
    results.searchGroupPages = new Map();
    for (const source of payload.groups) {
      const key = `${source.codePrefix}|${source.codeVersion}`;
      const group = results.querySelector(`.search-result-group[data-source-key="${CSS.escape(key)}"]`);
      if (!group) continue;
      const page = { ...source, key, group, loadedPages: 1, candidateOffset: source.nextCandidateOffset || 0 };
      results.searchGroupPages.set(key, page);
      const desiredPages = Number.isSafeInteger(restoreGroups[key]) && restoreGroups[key] > 0 ? Math.min(restoreGroups[key], 1000) : 1;
      position.groupPages[key] = desiredPages;
      appendSearchGroupLoadMore(results, page, options);
    }
    refreshSearchGroupCounts(results);
    for (const page of results.searchGroupPages.values()) {
      const desiredPages = position.groupPages[page.key];
      let failed = false;
      while (page.loadedPages < desiredPages && page.hasMore && isCurrent()) {
        if (!(await page.loadMore())) { failed = true; break; }
      }
      if (!isCurrent()) return;
      if (!failed) position.groupPages[page.key] = page.loadedPages;
    }
    requestAnimationFrame(() => {
      if (!isCurrent()) return;
      results.scrollTop = restoreScrollTop;
      results.dataset.restoringSearch = "false";
    });
    return;
  }
  // Older servers keep their original cursor while cached clients transition.
  appendSearchLoadMore(results, {
    query,
    matchMode,
    selectedPrefixes,
    nextOffset: Number(payload.nextOffset) || (payload.results || []).length,
    candidateOffset: Number(payload.nextCandidateOffset) || 0,
    totalResults,
    hasMore: Boolean(payload.hasMore),
    searchInstance,
    panel,
    renderToken, edition, controller, isCurrent, sourceScope
  });
  for (let page = 1; page < restorePages && results.searchLoadMore; page += 1) {
    if (!isCurrent()) return;
    if (!(await results.searchLoadMore())) {
      if (!isCurrent()) return;
      position.loadedPages = restorePages;
      break;
    }
  }
  if (!isCurrent()) return;
  requestAnimationFrame(() => {
    if (!isCurrent()) return;
    results.scrollTop = restoreScrollTop;
    results.dataset.restoringSearch = "false";
  });
}

// Choose once from the first available matches, never from a later pagination update.
// The request suffix describes the durable enabled-source scope; context tokens are
// intentionally excluded because they change on reload without changing the scope.
function applyInitialSearchGroupExpansion(instance, matches, sourceScope, { hasMore = false } = {}) {
  const decisionKey = JSON.stringify(["explicit-edition-v2", String(instance.query || "").trim(),
    normalizeSearchCodeFilters(instance.codeFilters), instance.searchEdition || "all",
    sourceScope?.querySuffix || ""]);
  if (!matches.length || instance.searchExpansionDecisionKey === decisionKey) return false;
  instance.searchExpansionDecisionKey = decisionKey;
  instance.defaultExpandedResultSource = "";
  const sourceKey = (result) => `${result.codePrefix || "BC"}|${result.codeVersion || defaultSyncCodeVersion}`;
  const expanded = new Set(normalizeSearchResultSources(instance.expandedResultSources));
  if (!matches.some((result) => expanded.has(sourceKey(result)))) {
    const explicitlyScopedEdition = instance.searchEdition && instance.searchEdition !== "all";
    const completeSingleSource = !hasMore && new Set(matches.map(sourceKey)).size === 1;
    if (explicitlyScopedEdition || completeSingleSource) instance.defaultExpandedResultSource = sourceKey(matches[0]);
  }
  return true;
}

function appendSearchResultGroups(results, searchResults, query, searchInstance) {
  const panel = results.closest(".search-panel");
  // This append is synchronous; use one fresh Project snapshot for its results.
  // Later pages and access notifications resolve their own current state.
  const privateContentAllowed = !panel.__workspaceAccessGate || panel.__workspaceAccessGate.allowed;
  const savedKeys = privateContentAllowed ? workspaceSavedEvidenceKeys() : null;
  const groups = new Map();
  const resultGroupsAreCollapsible = true;
  searchResults.forEach((result) => {
    const prefix = result.codePrefix || "BC";
    const key = `${prefix}|${result.codeVersion || defaultSyncCodeVersion}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(result);
  });

  Array.from(groups.entries()).forEach(([sourceKey, groupResults]) => {
    const prefix = groupResults[0].codePrefix || "BC";
    const sourceVersion = groupResults[0].codeVersion || defaultSyncCodeVersion;
    const familyKey = prefix === "BC68" ? "BC" : prefix;
    let family = results.querySelector(`.search-family-card[data-family="${CSS.escape(familyKey)}"]`);
    if (!family) {
      family = document.createElement("section");
      family.className = "search-family-card";
      family.dataset.family = familyKey;
      const heading = document.createElement("h3");
      heading.className = "search-family-title";
      heading.textContent = codeDisplayLabel(familyKey).replace(/\s*\([^)]*\)/g, "");
      family.append(heading);
      results.append(family);
    }
    let group = results.querySelector(
      `.search-result-group[data-source-key="${CSS.escape(sourceKey)}"]`
    );
    if (!group) {
      group = document.createElement("section");
      group.className = "search-result-group";
      group.classList.add(`code-theme-${codeTheme(prefix)}`);
      group.dataset.codePrefix = prefix;
      group.dataset.sourceKey = sourceKey;
      group.dataset.sourceVersion = sourceVersion;
      const groupBody = document.createElement("div");
      groupBody.className = "search-result-group-body";
      groupBody.id = `search-result-group-${crypto.randomUUID()}`;
      const label = document.createElement(resultGroupsAreCollapsible ? "button" : "p");
      label.className = "section-label search-group-label";
      const labelText = document.createElement("span");
      labelText.className = "search-group-label-text";
      labelText.textContent = researchCodeEdition({ codePrefix: prefix, codeVersion: sourceVersion }) + (prefix === "EBC" ? " · effective July 17" : "");
      label.append(labelText);
      if (resultGroupsAreCollapsible) {
        label.type = "button";
        label.classList.add("search-result-group-toggle");
        label.setAttribute("aria-controls", groupBody.id);
        const meta = document.createElement("span");
        meta.className = "search-result-group-meta";
        const count = document.createElement("span");
        count.className = "search-result-group-count";
        meta.append(count);
        label.append(meta);
        const initiallyCollapsed = searchInstance.defaultExpandedResultSource !== sourceKey &&
          !normalizeSearchResultSources(searchInstance.expandedResultSources).includes(sourceKey);
        const syncToggleLabel = (expanded) => {
          label.setAttribute("aria-label", `${expanded ? "Collapse" : "Expand"} ${codeDisplayLabel(prefix, sourceVersion)} results`);
        };
        syncToggleLabel(!initiallyCollapsed);
        group.setSearchExpanded = wireProjectSectionMotion(group, groupBody, [label], codeDisplayLabel(prefix, sourceVersion), !initiallyCollapsed, {
          onChange: (expanded) => {
            if (searchInstance.defaultExpandedResultSource === sourceKey) searchInstance.defaultExpandedResultSource = "";
            const expandedSources = new Set(normalizeSearchResultSources(searchInstance.expandedResultSources));
            if (expanded) expandedSources.add(sourceKey);
            else expandedSources.delete(sourceKey);
            searchInstance.expandedResultSources = Array.from(expandedSources);
            syncToggleLabel(expanded);
            saveWorkspaceState();
          }
        });
      }
      group.append(label, groupBody);
      family.append(group);
    }
    const groupBody = group.querySelector(".search-result-group-body") || group;
    const existingKeys = new Set([...groupBody.querySelectorAll(".result-row-main")]
      .map(button => button.dataset.searchResultKey));
    groupResults.forEach((result) => {
      const positionKey = searchResultPositionKey(result);
      if (existingKeys.has(positionKey)) return;
      existingKeys.add(positionKey);
      const detail = searchResultDetail(result);
      const row = document.createElement("article");
      row.className = "result-row";
      const mainButton = document.createElement("button");
      mainButton.className = "result-row-main";
      mainButton.type = "button";
      mainButton.dataset.searchResultKey = positionKey;
      if (searchPositionState(searchInstance).selectedResult === positionKey) mainButton.setAttribute("aria-current", "true");
      const presentation = searchResultPresentation(result, query);
      const citation = document.createElement("span");
      citation.className = "result-chapter";
      citation.id = `search-result-citation-${crypto.randomUUID()}`;
      citation.textContent = presentation.citation;
      mainButton.setAttribute("aria-describedby", citation.id);
      const heading = document.createElement("strong");
      heading.className = "result-heading";
      const title = document.createElement("span");
      title.className = "result-title";
      appendHighlighted(title, presentation.heading, query);
      heading.append(title);
      const snippetText = presentation.excerpt;
      const snippet = document.createElement("p");
      appendHighlighted(snippet, snippetText, query);
      markResearchSelectable(snippet, detail);
      mainButton.append(heading);
      if (snippetText) mainButton.append(snippet);
      mainButton.addEventListener("click", () => {
        if (window.getSelection && String(window.getSelection()).trim()) return;
        searchPositionState(searchInstance).selectedResult = positionKey;
        results.querySelectorAll(".result-row-main[aria-current]").forEach((button) => button.removeAttribute("aria-current"));
        mainButton.setAttribute("aria-current", "true");
        saveWorkspaceState();
        recordRecentSearch(query);
        void openSourceInReader(detail, paneIDForUtilityInstance(searchInstance), {
          sourceSurface: "search"
        });
      });

      const saveButton = createSearchResultSaveButton(panel, detail, {
        bookmarkStateResolved: true,
        showBookmark: privateContentAllowed && isSectionSaved(detail, "", savedKeys)
      });

      const openNewButton = document.createElement("button");
      openNewButton.type = "button";
      openNewButton.className = "search-open-new-reader workflow-action workflow-action-secondary";
      openNewButton.textContent = "New reader";
      openNewButton.title = "Open this source in an additional Reader beside Search";
      openNewButton.addEventListener("click", () => {
        recordRecentSearch(query);
        void openSourceInReader(detail, paneIDForUtilityInstance(searchInstance), {
          sourceSurface: "search", forceNewReader: true
        });
      });
      const actions = document.createElement("div");
      actions.className = "saved-row-actions search-row-actions";
      actions.append(openNewButton);
      const header = document.createElement("div");
      header.className = "result-row-header";
      header.append(citation, actions, saveButton);
      row.append(header, mainButton);
      groupBody.append(row);
    });
    const count = group.querySelector(".search-result-group-count");
    if (count) {
      const loadedGroupCount = groupBody.querySelectorAll(".result-row").length;
      count.textContent = searchGroupCountText(loadedGroupCount, results.dataset.searchHasMore === "true");
    }
  });
  // Keep family/edition order stable as additional pages arrive.
  const familyOrder = ["BC", "EBC", "FGC", "MC", "PC", "ECC", "EC", "FC", "ZR", "HMC", "AC", "T24", "T25", "T26", "T28", "LL"];
  Array.from(results.querySelectorAll(".search-family-card"))
    .sort((a, b) => familyOrder.indexOf(a.dataset.family) - familyOrder.indexOf(b.dataset.family))
    .forEach((family) => {
      Array.from(family.querySelectorAll(".search-result-group"))
        .sort((a, b) => Number.parseInt(researchCodeEdition({codePrefix:b.dataset.codePrefix, codeVersion:b.dataset.sourceVersion}), 10) - Number.parseInt(researchCodeEdition({codePrefix:a.dataset.codePrefix, codeVersion:a.dataset.sourceVersion}), 10))
        .forEach((group) => family.append(group));
      results.append(family);
    });
  refreshSearchGroupCounts(results);
}

function appendSearchGroupLoadMore(results, page, options) {
  const group = page.group;
  const body = group.querySelector(".search-result-group-body");
  body.querySelector(".search-load-more")?.remove();
  group.dataset.searchHasMore = page.hasMore ? "true" : "false";
  page.loadMore = null;
  if (!page.hasMore) return;
  const footer = document.createElement("section");
  footer.className = "search-load-more";
  const status = document.createElement("p");
  status.hidden = true;
  status.setAttribute("role", "status");
  const button = document.createElement("button");
  button.type = "button";
  button.className = "search-load-more-button";
  button.textContent = "Load more matches";
  button.setAttribute("aria-label", `Load more ${page.codePrefix} ${researchCodeEdition({ codePrefix: page.codePrefix, codeVersion: page.codeVersion })} matches`);
  page.loadMore = async () => {
    if (!options.isCurrent() || button.disabled) return false;
    button.disabled = true;
    button.textContent = "Loading matches…";
    status.hidden = true;
    try {
      const source = encodeURIComponent(JSON.stringify({ codePrefix: page.codePrefix, codeVersion: page.codeVersion }));
      const payload = await api(`/code/search?q=${encodeURIComponent(options.query)}` +
        `&code=${encodeURIComponent(page.codePrefix)}&version=all&resultSource=${source}&match=${options.matchMode || "exact"}` +
        `&readerSourceMetadata=1&limit=${searchResultPageSize}&offset=${page.nextOffset}` +
        `${page.cursorKind === "candidate" ? `&candidateOffset=${page.candidateOffset}` : ""}${options.sourceScope.querySuffix}`,
        { signal: options.controller.signal });
      if (!options.isCurrent()) return false;
      if ((payload.results || []).some(result => result.codePrefix !== page.codePrefix || result.codeVersion !== page.codeVersion)) {
        throw new Error("The returned matches belong to a different code edition.");
      }
      const matches = (payload.results || []).filter(result => (options.matchMode === "words" || searchResultMatchesExactQuery(result, options.query)));
      const hadFocus = footer.contains(document.activeElement);
      footer.remove();
      appendSearchResultGroups(results, matches, options.query, options.searchInstance);
      page.nextOffset = Number(payload.nextOffset) || page.nextOffset + (payload.results || []).length;
      page.candidateOffset = Number(payload.nextCandidateOffset) || 0;
      page.cursorKind = payload.cursorKind || "offset";
      page.hasMore = Boolean(payload.hasMore);
      page.totalResults = payload.totalResults;
      page.loadedPages += 1;
      appendSearchGroupLoadMore(results, page, options);
      const hasMore = [...results.searchGroupPages.values()].some(item => item.hasMore);
      results.dataset.searchHasMore = hasMore ? "true" : "false";
      const loaded = results.querySelectorAll(".result-row").length;
      updateSearchDock(options.panel, options.searchInstance, loaded, { hasMore });
      refreshSearchGroupCounts(results);
      if (results.dataset.restoringSearch !== "true") {
        searchPositionState(options.searchInstance).groupPages[page.key] = page.loadedPages;
        saveWorkspaceState();
      }
      if (hadFocus) {
        const firstNew = matches.length && [...body.querySelectorAll(".result-row-main")]
          .find(item => item.dataset.searchResultKey === searchResultPositionKey(matches[0]));
        (firstNew || body.querySelector(".search-load-more-button") || group.querySelector(".search-result-group-toggle"))
          ?.focus({ preventScroll: true });
      }
      return true;
    } catch {
      if (!options.isCurrent()) return false;
      button.disabled = false;
      button.textContent = "Try again";
      status.hidden = false;
      status.textContent = "More matches could not be loaded for this edition.";
      return false;
    }
  };
  button.addEventListener("click", () => { void page.loadMore(); });
  footer.append(status, button);
  body.append(footer);
}

function appendSearchLoadMore(results, options) {
  results.querySelector(".search-load-more")?.remove();
  results.searchLoadMore = null;
  if (!options.hasMore) return;
  const footer = document.createElement("section");
  footer.className = "search-load-more";
  const status = document.createElement("p");
  status.hidden = true;
  const button = document.createElement("button");
  button.type = "button";
  button.className = "search-load-more-button";
  button.textContent = "Load more matches";
  const loadMore = async () => {
    if (!options.isCurrent()) return false;
    if (button.disabled) return false;
    button.disabled = true;
    button.textContent = "Loading matches…";
    const codeQuery = options.selectedPrefixes.length
      ? `&code=${encodeURIComponent(options.selectedPrefixes.join(","))}`
      : "";
    try {
      const payload = await api(
        `/code/search?q=${encodeURIComponent(options.query)}${codeQuery}&version=${encodeURIComponent(options.edition)}&match=${options.matchMode || "exact"}` +
        `&readerSourceMetadata=1&limit=${searchResultPageSize}&offset=${encodeURIComponent(String(options.nextOffset))}` +
        `&candidateOffset=${encodeURIComponent(String(options.candidateOffset))}${options.sourceScope.querySuffix}`,
        { signal: options.controller.signal }
      );
      if (!options.isCurrent()) return false;
      const nextResults = (payload.results || []).filter((result) =>
        (options.selectedPrefixes.length === 0 || options.selectedPrefixes.includes(result.codePrefix || "BC")) &&
        (options.matchMode === "words" || searchResultMatchesExactQuery(result, options.query))
      );
      const loadedPages = (Number(results.dataset.loadedSearchPages) || 1) + 1;
      results.dataset.loadedSearchPages = String(loadedPages);
      searchPositionState(options.searchInstance).loadedPages = loadedPages;
      footer.remove();
      results.dataset.searchHasMore = payload.hasMore ? "true" : "false";
      if (applyInitialSearchGroupExpansion(options.searchInstance, nextResults, options.sourceScope, { hasMore: true })) saveWorkspaceState();
      appendSearchResultGroups(results, nextResults, options.query, options.searchInstance);
      const nextVisibleCount = results.querySelectorAll(".result-row").length;
      const pageTotal = Number(payload.totalResults);
      const totalResults = Number.isFinite(pageTotal) && pageTotal > nextVisibleCount
        ? pageTotal
        : options.totalResults;
      updateSearchDock(options.panel, options.searchInstance, nextVisibleCount, {
        hasMore: Boolean(payload.hasMore),
        totalResults
      });
      appendSearchLoadMore(results, {
        ...options,
        nextOffset: Number(payload.nextOffset) || (options.nextOffset + (payload.results || []).length),
        candidateOffset: Number(payload.nextCandidateOffset) || options.candidateOffset,
        totalResults,
        hasMore: Boolean(payload.hasMore)
      });
      if (results.dataset.restoringSearch !== "true") saveWorkspaceState();
      return true;
    } catch {
      if (!options.isCurrent()) return false;
      button.disabled = false;
      button.textContent = "Try again";
      status.hidden = false;
      status.textContent = "More results could not be loaded.";
      const loadedCount = results.querySelectorAll(".result-row").length;
      updateSearchDock(options.panel, options.searchInstance, loadedCount, {
        hasMore: true,
        failed: true
      });
      return false;
    }
  };
  results.searchLoadMore = loadMore;
  button.addEventListener("click", () => { void loadMore(); });
  footer.append(status, button);
  results.append(footer);
}

const sectionDetailOpeningAttempts = new Map();

async function openSectionDetail(searchID, section, options = {}) {
  const attempt = {};
  sectionDetailOpeningAttempts.set(searchID, attempt);
  try {
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const isCurrent = () => sectionDetailOpeningAttempts.get(searchID) === attempt &&
    (options.isCurrent?.() ?? true) && isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === workspaceID;
  const resolved = section.__activeCodeSourceContext && isCurrentActiveCodeSourceContext(section.__activeCodeSourceContext)
    ? section : await resolveReaderSource(section, { isCurrent });
  if (!resolved || !isCurrent() || !isCurrentActiveCodeSourceContext(resolved.__activeCodeSourceContext)) return;
  section = resolved;
  const sectionID = String(section.sectionID || section.id || "");
  if (!sectionID) return;
  const details = sectionDetailsBySearch();
  const anchors = sectionDetailAnchorsBySearch();
  const publishedDetail = details[searchID] = {
    codeSource: section.codeSource,
    codePrefix: section.codePrefix || "BC",
    codeVersion: syncCodeVersion(section.codeVersion || syncCodeVersionForPrefix(section.codePrefix || "BC")),
    chapterID: section.navigationChapterID || section.chapterID || "",
    chapterNumber: section.chapterNumber || "",
    sectionID,
    sectionNumber: section.sectionNumber || "",
    title: section.title || "Section",
    blockID: normalizeAnnotationBlockID(section.blockID || section.annotationBlockID || section.contentBlockID),
    blockLabel: section.blockLabel || "",
    headerLine: section.headerLine || "",
    headingLine: section.headingLine || "",
    evidenceAnchor: options.evidenceAnchor || null
  };
  if (options.anchorPaneID) {
    anchors[searchID] = options.anchorPaneID;
  } else {
    delete anchors[searchID];
  }
  state.searchResultReader = null;
  if (options.updateURL !== false) {
    updateBrowserSectionURL(sectionID);
  }
  if (options.updateLinkedReader !== false) {
    scheduleContinuitySync(newReaderState(readerFieldsForSectionDetail(details[searchID])));
  }
  placeSectionDetailAfterPane(searchID, anchors[searchID] || paneIDForUtilityInstance({ key: "search", id: searchID }));
  const linkedReader = options.updateLinkedReader === false ? null : updateLinkedReaderForSearch(searchID, details[searchID]);
  const liveContent = linkedReader && track.querySelector(`.reader-panel[data-pane-id="${CSS.escape(paneIDForReader(linkedReader))}"] .reader-content`);
  const canReuseReader = Boolean(liveContent && liveContent.querySelector(
    `.chapter-section[data-section-id="${CSS.escape(sectionID)}"][data-code-version="${CSS.escape(details[searchID].codeVersion)}"]`
  ));
  if (canReuseReader) linkedReader.shouldSmoothScrollToSection = false;
  saveWorkspaceState();
  await transitionWorkspace("utility", {
    refreshPaneIDs: [
      paneIDForSectionDetail(searchID),
      ...(linkedReader && !canReuseReader ? [paneIDForReader(linkedReader)] : [])
    ]
  });
  if (!isCurrent() || details[searchID] !== publishedDetail || !isCurrentActiveCodeSourceContext(resolved.__activeCodeSourceContext)) return;
  if (linkedReader && await whenWorkspacePaneReady(paneIDForReader(linkedReader)) &&
      isCurrent() && details[searchID] === publishedDetail && isCurrentActiveCodeSourceContext(resolved.__activeCodeSourceContext)) {
    revealReaderSourceTarget(linkedReader, details[searchID], options.evidenceAnchor);
  }
  } finally {
    if (sectionDetailOpeningAttempts.get(searchID) === attempt) sectionDetailOpeningAttempts.delete(searchID);
  }
}

function annotationForSection(sectionID) {
  return annotationForTarget(sectionID, "");
}

function sectionRecordMatchesRequestedEdition(detail, record) {
  const requested = String(detail?.codeVersion || "").trim();
  if (!requested || !record) return true;
  const resolvedVersion = String(record.codeVersion || record.sourceLibraryVersion || "").trim();
  if (!resolvedVersion) return true;
  return syncCodeVersion(resolvedVersion) === syncCodeVersion(requested);
}

async function resolveSectionDetail(detail) {
  let chapter = null;
  let section = null;
  if (detail.sectionID) {
    for (let attempt = 0; attempt < 3 && !section; attempt += 1) {
      try {
        const payload = await api(`/code/sections/${encodeURIComponent(detail.sectionID)}`);
        const resolvedSection = payload.section;
        if (resolvedSection && !sectionRecordMatchesRequestedEdition(detail, resolvedSection)) break;
        if (resolvedSection) {
          detail.chapterID = resolvedSection.navigationChapterID || resolvedSection.chapterID || detail.chapterID || "";
          detail.navigationChapterID = resolvedSection.navigationChapterID || detail.chapterID || "";
          detail.codePrefix = resolvedSection.codePrefix || detail.codePrefix || "BC";
          detail.chapterNumber = resolvedSection.chapterNumber || detail.chapterNumber || "";
          detail.sectionNumber = resolvedSection.sectionNumber || detail.sectionNumber || "";
          detail.title = resolvedSection.title || detail.title || "Section";
          if (detail.chapterID) {
            chapter = await fetchChapter(detail.chapterID);
          }
          section = {
            ...resolvedSection,
            id: resolvedSection.id || resolvedSection.sectionID || Number(detail.sectionID)
          };
        }
      } catch (error) {
        if (attempt >= 2) break;
        await new Promise((resolve) => window.setTimeout(resolve, 180 * (attempt + 1)));
      }
    }
  }
  if (!section && detail.chapterID) {
    try {
      const loadedChapter = await fetchChapter(detail.chapterID, { includeBody: true });
      if (sectionRecordMatchesRequestedEdition(detail, loadedChapter)) {
        chapter = loadedChapter;
        section = sectionTitleFromID(detail.sectionID, chapter);
      }
    } catch {
      chapter = null;
    }
  }
  if (!section) {
    try {
      const requestedVersion = String(detail.codeVersion || "").trim();
      const versionQuery = requestedVersion
        ? `&version=${encodeURIComponent(syncCodeVersion(requestedVersion))}`
        : "";
      const search = await api(`/code/search?q=${encodeURIComponent(detail.sectionNumber || detail.sectionID)}${versionQuery}`);
      const matchesSection = (item) =>
        String(item.id) === String(detail.sectionID) || String(item.sectionID) === String(detail.sectionID);
      const exact = (search.results || []).find((item) =>
        matchesSection(item) && sectionRecordMatchesRequestedEdition(detail, item)
      );
      const result = exact || (requestedVersion ? null : search.results?.[0]);
      if (result?.chapterID && sectionRecordMatchesRequestedEdition(detail, result)) {
        detail.chapterID = result.chapterID;
        detail.codePrefix = result.codePrefix || detail.codePrefix || "BC";
        detail.chapterNumber = result.chapterNumber || detail.chapterNumber || "";
        detail.sectionNumber = result.sectionNumber || detail.sectionNumber || "";
        detail.title = result.title || detail.title || "Section";
        detail.headerLine = result.headerLine || detail.headerLine || "";
        detail.headingLine = result.headingLine || detail.headingLine || "";
        chapter = await fetchChapter(result.chapterID, { includeBody: true });
        section = sectionTitleFromID(detail.sectionID, chapter);
      }
    } catch (error) {
      throw new Error("This section could not be loaded. Try opening it again.", { cause: error });
    }
  }
  return { chapter, section };
}

function appendDetailIconButton(container, options) {
  const button = document.createElement("button");
  button.className = options.className || "section-detail-icon";
  button.type = "button";
  button.title = options.title;
  button.setAttribute("aria-label", options.label || options.title);
  button.innerHTML = options.svg;
  container.append(button);
  return button;
}

