function makeSectionPayloadFromDetail(detail, section) {
  const codePrefix = detail.codePrefix || section?.codePrefix || "BC";
  return {
    codeVersion: syncCodeVersion(
      detail.codeVersion || section?.codeVersion || syncCodeVersionForPrefix(codePrefix)
    ),
    codePrefix,
    chapterID: detail.chapterID || section?.chapterID || "",
    chapterNumber: detail.chapterNumber || section?.chapterNumber || "",
    sectionID: detail.sectionID,
    sectionNumber: section?.sectionNumber || detail.sectionNumber || "",
    title: section?.title || detail.title || "Section",
    blockID: normalizeAnnotationBlockID(detail.blockID || detail.annotationBlockID || detail.contentBlockID),
    blockLabel: detail.blockLabel || ""
  };
}

function notebookEvidenceTextMap(root) {
  const chars = [];
  const map = [];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      if (node.parentElement?.closest(
        "button:not(.inline-code-reference), input, textarea, script, style, [data-research-selection-exclude='true']"
      )) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  let node;
  while ((node = walker.nextNode())) {
    if (chars.length && chars.at(-1) !== " ") {
      chars.push(" ");
      map.push({ node, offset: 0 });
    }
    let pendingSpace = false;
    for (let offset = 0; offset < node.nodeValue.length; offset += 1) {
      const character = node.nodeValue[offset];
      if (/\s/.test(character)) {
        pendingSpace = chars.length > 0 && chars.at(-1) !== " ";
        continue;
      }
      if (pendingSpace) {
        chars.push(" ");
        map.push({ node, offset: Math.max(0, offset - 1) });
        pendingSpace = false;
      }
      chars.push(character);
      map.push({ node, offset });
    }
  }
  while (chars.at(-1) === " ") {
    chars.pop();
    map.pop();
  }
  return { text: chars.join(""), map };
}

function notebookEvidenceMatchIndex(text, selector) {
  const exact = normalizedPassageAnchorText(selector?.normalizedExact || selector?.exact);
  if (!exact) return -1;
  const candidates = [];
  let cursor = text.indexOf(exact);
  while (cursor >= 0) {
    candidates.push(cursor);
    cursor = text.indexOf(exact, cursor + 1);
  }
  if (!candidates.length) return -1;
  const prefix = normalizedPassageAnchorText(selector?.prefix).slice(-120);
  const suffix = normalizedPassageAnchorText(selector?.suffix).slice(0, 120);
  const scored = candidates.map((index) => {
    const before = text.slice(Math.max(0, index - prefix.length), index);
    const after = text.slice(index + exact.length, index + exact.length + suffix.length);
    let score = 0;
    if (prefix && before.endsWith(prefix)) score += 2;
    if (suffix && after.startsWith(suffix)) score += 2;
    if (Number.isInteger(selector?.start)) score -= Math.min(1, Math.abs(selector.start - index) / 10_000);
    return { index, score };
  }).sort((left, right) => right.score - left.score);
  if (scored.length > 1 && scored[0].score === scored[1].score) return -1;
  return scored[0].index;
}

function markNotebookEvidenceRange(root, selector) {
  const { text, map } = notebookEvidenceTextMap(root);
  const exact = normalizedPassageAnchorText(selector?.normalizedExact || selector?.exact);
  const start = notebookEvidenceMatchIndex(text, selector);
  if (start < 0 || !exact) return [];
  const selectedMap = map.slice(start, start + exact.length);
  const byNode = new Map();
  selectedMap.forEach(({ node, offset }) => {
    if (!byNode.has(node)) byNode.set(node, []);
    byNode.get(node).push(offset);
  });
  const marks = [];
  [...byNode.entries()].reverse().forEach(([textNode, offsets]) => {
    const from = Math.min(...offsets);
    const to = Math.max(...offsets) + 1;
    if (to <= from || to > textNode.nodeValue.length) return;
    const range = document.createRange();
    range.setStart(textNode, from);
    range.setEnd(textNode, to);
    const mark = document.createElement("mark");
    mark.className = "notebook-evidence-highlight";
    range.surroundContents(mark);
    marks.push(mark);
  });
  return marks.reverse();
}

function revealNotebookEvidencePassages(root, evidenceLink) {
  const marks = (evidenceLink?.passages || []).flatMap((selector) =>
    markNotebookEvidenceRange(root, selector)
  );
  if (marks.length) {
    marks[0].scrollIntoView({ block: "center", behavior: "smooth" });
    return;
  }
  const status = document.createElement("p");
  status.className = "section-detail-evidence-status";
  status.textContent = "The linked passage could not be relocated safely. The enacted section is shown without a passage highlight.";
  root.before(status);
}

async function renderSectionDetail(searchID, detail) {
  const panel = document.createElement("article");
  panel.className = "workspace-panel section-detail-panel";
  panel.dataset.paneId = paneIDForSectionDetail(searchID);
  panel.classList.add(`code-theme-${codeTheme(detail.codePrefix || "BC")}`);
  const detailOwner = (state.utilityInstances || []).find((instance) => instance.id === searchID);
  const isSavedEvidenceDetail = detailOwner?.key === "sdc";
  panel.classList.toggle("is-saved-evidence-detail", isSavedEvidenceDetail);
  panel.dataset.projectId = String(detailOwner?.projectID || "");
  applyProjectDerivedPaneTheme(panel, detailOwner?.projectID);
  applyPaneWeight(panel, paneIDForSectionDetail(searchID));

  const { chapter, section } = await resolveSectionDetail(detail);
  const sectionPayload = makeSectionPayloadFromDetail(detail, section);
  sectionPayload.chapterID ||= chapter?.id || "";
  sectionPayload.chapterNumber ||= chapter?.chapterNumber || "";
  const sectionTarget = {
    ...sectionPayload,
    blockID: normalizeAnnotationBlockID(sectionPayload.blockID)
  };
  const saved = isSectionSaved(sectionTarget);
  const noteBody = detailNoteValueForTarget(sectionTarget);
  const bodyText = sectionPlainText(section);
  const accessibleHeading = document.createElement("h2");
  accessibleHeading.className = "panel-title";
  accessibleHeading.textContent = sectionDisplayTitle(
    section?.sectionNumber || detail.sectionNumber,
    sectionTitleWithoutNumber(section) || detail.title,
    "Section detail"
  );
  panel.append(accessibleHeading);

  const chrome = document.createElement("header");
  chrome.className = "panel-header section-detail-chrome";
  const detailTitle = document.createElement("p");
  detailTitle.className = "eyebrow panel-kind";
  detailTitle.textContent = isSavedEvidenceDetail ? "Evidence detail" : "Section detail";
  const backButton = appendDetailIconButton(chrome, {
    title: "Close",
    label: "Close saved item",
    className: "section-detail-icon section-detail-close workflow-action-icon",
    svg: circleXIconSVG()
  });
  const saveButton = appendDetailIconButton(chrome, {
    title: bookmarkActionLabel(saved),
    label: bookmarkActionLabel(saved),
    className: `section-detail-icon section-detail-save workflow-action-icon${saved ? " is-saved" : ""}`,
    svg: bookmarkIconSVG(saved)
  });
  syncImmediateBookmarkButton(saveButton, saved);
  const actions = document.createElement("div");
  actions.className = "panel-actions";
  const projectButton = document.createElement("button");
  projectButton.type = "button";
  projectButton.className = "section-detail-project-add";
  projectButton.textContent = "Add to Project";
  projectButton.setAttribute("aria-haspopup", "menu");
  projectButton.setAttribute("aria-expanded", "false");
  projectButton.hidden = !hasCapability("projects");
  actions.append(saveButton, projectButton, backButton);
  chrome.append(detailTitle, actions);

  const content = document.createElement("section");
  content.className = "section-detail-content";

  const codeLabelElement = document.createElement("p");
  codeLabelElement.className = "section-detail-code-label";
  codeLabelElement.textContent = readerCodeOptionLabel(codeOptionFor(
    detail.codePrefix || "BC", sectionPayload.codeVersion || detail.codeVersion || ""
  )).toUpperCase();

  const chapterLabel = document.createElement("p");
  chapterLabel.className = "section-detail-chapter";
  chapterLabel.textContent = chapter?.fullTitle || chapter?.displayTitle || detail.headerLine ||
    (sectionPayload.chapterNumber ? `Chapter ${sectionPayload.chapterNumber}` : "");
  chapterLabel.hidden = !chapterLabel.textContent;

  const heading = document.createElement("button");
  heading.className = "section-detail-heading";
  heading.type = "button";
  const number = document.createElement("span");
  number.className = "section-detail-number";
  number.textContent = section?.sectionNumber || detail.sectionNumber || "";
  const headingText = document.createElement("span");
  headingText.textContent = sectionTitleWithoutNumber(section) || detail.title || "Section";
  const jumpIcon = document.createElement("span");
  jumpIcon.className = "section-detail-jump";
  jumpIcon.innerHTML = jumpIconSVG();
  heading.append(number, headingText, jumpIcon);
  heading.title = "Open in Reader";
  heading.setAttribute("aria-label", `Open ${number.textContent} ${headingText.textContent} in Reader`);

  const chapterTitle = document.createElement("p");
  chapterTitle.className = "section-detail-chapter";
  chapterTitle.textContent = detail.headingLine || "";
  chapterTitle.hidden = !chapterTitle.textContent;

  const body = document.createElement("section");
  body.className = "section-detail-body";
  markResearchSelectable(body, {
    sectionID: sectionPayload.sectionID,
    sectionNumber: sectionPayload.sectionNumber,
    title: sectionPayload.title,
    codePrefix: sectionPayload.codePrefix,
    chapterID: sectionPayload.chapterID,
    codeVersion: sectionPayload.codeVersion,
    sourceLibraryVersion: detail.evidenceAnchor?.source?.sourceLibraryVersion || ""
  });
  const detailBlocks = section?.blocks?.length ? annotatedBlocksForSection(section) : [];
  if (detailBlocks.length) {
    detailBlocks.forEach((block, index) => {
      const blockTarget = annotationTargetForBlock(section, block, sectionPayload, index);
      const renderedBlock = renderCodeBlock(block);
      renderedBlock.dataset.annotationBlockId = blockTarget.blockID;
      body.append(renderedBlock);
    });
  } else if (bodyText) {
    const normalizedBodyText = bodyText.replace(/\s+/g, " ").trim().toLocaleLowerCase();
    const normalizedTitles = [section?.title, detail.title]
      .map((value) => String(value || "").replace(/\s+/g, " ").trim().toLocaleLowerCase())
      .filter(Boolean);
    if (!normalizedTitles.includes(normalizedBodyText)) {
      const paragraph = document.createElement("p");
      paragraph.textContent = bodyText;
      body.append(paragraph);
    }
  }

  if (detail.evidenceAnchor) {
    requestAnimationFrame(() => revealNotebookEvidencePassages(body, detail.evidenceAnchor));
  } else if (sectionTarget.blockID && detailBlocks.length > 1) {
    requestAnimationFrame(() => {
      const savedBlock = body.querySelector(
        `[data-annotation-block-id="${CSS.escape(sectionTarget.blockID)}"]`
      );
      if (!savedBlock) {
        revealNotebookEvidencePassages(body, { passages: [] });
        return;
      }
      const exact = normalizedPassageAnchorText(savedBlock.textContent);
      const marks = exact ? markNotebookEvidenceRange(savedBlock, { exact }) : [];
      if (marks.length) marks[0].scrollIntoView({ block: "center", behavior: "smooth" });
    });
  }

  const notes = document.createElement("section");
  notes.className = "section-detail-notes";
  notes.hidden = !hasCapability("notes");
  const notesHeader = document.createElement("div");
  notesHeader.className = "section-detail-notes-header";
  const commentScope = sectionTarget.blockID ? "Passage comment" : "Section comment";
  const notesTitle = document.createElement("h3");
  notesTitle.textContent = commentScope;
  const saveState = document.createElement("span");
  saveState.className = "section-detail-note-state";
  saveState.setAttribute("role", "status");
  notesHeader.append(notesTitle, saveState);
  const textareaWrap = document.createElement("label");
  textareaWrap.className = "section-detail-note-box";
  const textarea = document.createElement("textarea");
  textarea.value = noteBody;
  textarea.placeholder = sectionTarget.blockID ? "Add a comment on the highlighted passage" : "Add a comment on this section";
  textarea.setAttribute("aria-label", `${commentScope} for ${sectionDisplayTitle(sectionPayload.sectionNumber, sectionPayload.title)}`);
  const noteResizeHandle = document.createElement("div");
  noteResizeHandle.className = "section-detail-note-resize-handle";
  noteResizeHandle.setAttribute("role", "separator");
  noteResizeHandle.setAttribute("aria-label", "Resize comment");
  noteResizeHandle.setAttribute("aria-orientation", "horizontal");
  noteResizeHandle.tabIndex = 0;
  const resizeNoteTo = (height) => {
    const maximumHeight = Math.min(window.innerHeight * 0.7, 760);
    textarea.style.height = `${Math.max(118, Math.min(maximumHeight, height))}px`;
  };
  noteResizeHandle.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    const startY = event.clientY;
    const startHeight = textarea.getBoundingClientRect().height;
    noteResizeHandle.setPointerCapture(event.pointerId);
    const resize = (moveEvent) => resizeNoteTo(startHeight + moveEvent.clientY - startY);
    const finish = () => {
      window.removeEventListener("pointermove", resize);
      window.removeEventListener("pointerup", finish);
      window.removeEventListener("pointercancel", finish);
    };
    window.addEventListener("pointermove", resize);
    window.addEventListener("pointerup", finish);
    window.addEventListener("pointercancel", finish);
  });
  noteResizeHandle.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
    event.preventDefault();
    const direction = event.key === "ArrowDown" ? 1 : -1;
    resizeNoteTo(textarea.getBoundingClientRect().height + direction * (event.shiftKey ? 40 : 16));
  });
  textareaWrap.append(textarea, noteResizeHandle);
  notes.append(notesHeader, textareaWrap);
  panel.__annotationTarget = sectionTarget;
  panel.__sectionPayload = sectionPayload;
  const syncDetailBookmark = (event) => {
    const nextSaved = event.detail?.saved === true;
    syncImmediateBookmarkButton(saveButton, nextSaved);
    syncSearchResultBookmarkButtons(sectionPayload, nextSaved);
  };
  notes.addEventListener("permitext-folder-save", syncDetailBookmark);
  projectButton.addEventListener("click", () => {
    showSectionProjectAssignment(panel, sectionPayload, projectButton, { chooseDestination: true });
    panel.__sectionProjectMenu?.addEventListener("permitext-folder-save", syncDetailBookmark);
  });

  backButton.addEventListener("click", () => {
    removeSectionDetail(searchID);
    saveWorkspaceState();
    void transitionWorkspace("utility");
  });

  saveButton.addEventListener("click", async () => {
    const shouldRemove = saveButton.classList.contains("is-saved");
    saveButton.disabled = true;
    saveButton.classList.remove("has-error");
    closeSectionSaveProjectSheet(panel);
    try {
      if (!shouldRemove) {
        const persisted = await persistSectionBookmark(sectionPayload, true, {
          refreshSavedPanes: false
        });
        if (persisted === false) return;
        await refreshOpenSavedPanes();
        syncImmediateBookmarkButton(saveButton, true);
        syncReaderNoteBookmarkButtons(sectionPayload.sectionID, true, sectionPayload.codeVersion);
        syncSearchResultBookmarkButtons(sectionPayload, true);
        refreshVisibleSyncedDerivedState();
        return;
      }
      const persisted = await persistSectionBookmark(sectionPayload, false, { undoPaneID: panel.dataset.paneId });
      if (persisted === false) {
        return;
      }
      syncImmediateBookmarkButton(saveButton, false);
      syncSearchResultBookmarkButtons(sectionPayload, false);
      refreshVisibleSyncedDerivedState();
    } catch (error) {
      saveButton.classList.add("has-error");
      const message = error.message || "Could not update this saved section.";
      saveButton.title = message;
      saveButton.setAttribute("aria-label", message);
      presentWorkspaceIssue(message);
    } finally {
      saveButton.disabled = false;
    }
  });

  heading.addEventListener("click", async () => {
    const reader = await openOrUpdateLinkedReaderForSearch(searchID, detail, {
      chapterID: detail.chapterID || chapter?.id || "",
      sectionNumber: sectionPayload.sectionNumber,
      title: sectionPayload.title,
      shouldSmoothScrollToSection: false
    });
    if (!reader) return;
    saveWorkspaceState();
    await transitionWorkspace("utility", { refreshPaneIDs: [paneIDForReader(reader)] });
    if (!await whenWorkspacePaneReady(paneIDForReader(reader))) return;
    revealReaderSourceTarget(reader, detail, detail.evidenceAnchor || null);
    scrollPaneIntoView(paneIDForReader(reader), "auto");
  });

  let noteRevision = 0;
  let statusTimer = null;
  const renderNoteStatus = (status, revision = noteRevision) => {
    saveState.replaceChildren();
    const conflict = pendingAnnotationNoteForTarget(sectionTarget, state.syncConflicts);
    if (conflict) {
      textarea.value = detailNoteValueForTarget(sectionTarget);
      textarea.readOnly = true;
      saveState.append("Save conflict · ");
      const review = document.createElement("button");
      review.type = "button";
      review.textContent = "Review conflict";
      review.addEventListener("click", toggleAccountDialog);
      saveState.append(review);
      return;
    }
    if (status === "error" || status === "pending") {
      saveState.append(status === "error" ? "Couldn’t sync · " : "Changes pending · ");
      const retry = document.createElement("button");
      retry.type = "button";
      retry.textContent = "Retry";
      retry.addEventListener("click", retryQueuedNote);
      saveState.append(retry);
    } else {
      saveState.textContent = status === "synced" ? "Synced" : "Saved on this device";
      if (status === "synced") statusTimer = window.setTimeout(() => {
        if (revision === noteRevision && panel.isConnected) saveState.textContent = "";
      }, 2000);
    }
  };
  const retryQueuedNote = async () => {
    if (pendingAnnotationNoteForTarget(sectionTarget, state.syncConflicts)) {
      renderNoteStatus("conflict");
      return;
    }
    const pending = pendingAnnotationNoteForTarget(sectionTarget);
    // A user edit owns its newer draft; never replay an older body over it.
    if (!pending || String(pending.mutation.annotation.noteBody || "") !== textarea.value) {
      persistNote();
      return;
    }
    const revision = ++noteRevision;
    const identity = captureAccountRequest();
    clearTimeout(statusTimer);
    saveState.replaceChildren();
    saveState.textContent = "Saving…";
    try {
      // Retry the durable entry itself, preserving its original record/body.
      if (pending) await flushSyncOutbox({ refresh: true });
      requireCurrentAccountRequest(identity);
      if (revision !== noteRevision || !panel.isConnected) return;
      if (pendingAnnotationNoteForTarget(sectionTarget) || (state.syncConflicts || []).some((entry) =>
        entry.accountUserID === identity.userID && entry.recordID === pending.recordID)) {
        renderNoteStatus("error", revision);
        return;
      }
      if (pending) {
        const annotation = pending.mutation.annotation;
        state.localAnnotations = (state.localAnnotations || []).filter((item) =>
          String(item.id || "") !== String(annotation.id) || String(item.updatedAt || "") !== String(annotation.updatedAt || ""));
        saveWorkspaceState();
      }
      renderNoteStatus("synced", revision);
    } catch {
      if (revision === noteRevision && panel.isConnected && isCurrentAccountRequest(identity)) renderNoteStatus("error", revision);
    }
  };
  const persistNote = () => {
    if (pendingAnnotationNoteForTarget(sectionTarget, state.syncConflicts)) {
      renderNoteStatus("conflict");
      return;
    }
    const revision = ++noteRevision;
    clearTimeout(statusTimer);
    saveState.textContent = "Saving…";
    const onStatus = (status) => {
      if (revision !== noteRevision || !panel.isConnected) return;
      renderNoteStatus(status, revision);
    };
    try {
      if (!setAnnotationNoteValue(sectionTarget, textarea.value, onStatus)) {
        textarea.value = noteValueForTarget(sectionTarget);
        saveState.textContent = "";
        return;
      }
      syncReaderNoteControls(sectionTarget.sectionID, "", textarea.value, { source: textarea, target: sectionTarget });
    } catch {
      saveState.textContent = "Couldn’t save on this device";
    }
  };
  textarea.addEventListener("focus", () => {
    if (!workspaceProject()) void chooseProjectForSaving();
  });
  textarea.addEventListener("input", persistNote);
  const restoredPendingNote = pendingAnnotationNoteForTarget(sectionTarget);
  if (pendingAnnotationNoteForTarget(sectionTarget, state.syncConflicts)) renderNoteStatus("conflict");
  else if (restoredPendingNote) renderNoteStatus(restoredPendingNote.lastError ? "error" : "pending");

  const addNote = document.createElement("button");
  addNote.type = "button";
  addNote.className = "workflow-action workflow-action-secondary";
  addNote.textContent = "Add to note";
  addNote.hidden = !hasCapability("notebook");
  addNote.addEventListener("click", async () => {
    if (!readerPrivateContentAllowed(panel)) return;
    addNote.disabled = true;
    try {
      const passage = sectionTarget.blockID
        ? body.querySelector(`[data-annotation-block-id="${CSS.escape(sectionTarget.blockID)}"]`) : body;
      await addPassageToNotebook(addNote, sectionPayload, passage?.textContent);
    } catch (error) {
      if (panel.isConnected && readerPrivateContentAllowed(panel)) await showWebNotice("Passage not added", error.message);
    } finally { addNote.disabled = false; }
  });
  content.append(codeLabelElement, chapterLabel, heading, chapterTitle, body, addNote, notes);
  panel.append(chrome, content);
  return panel;
}

function renderTemplate(template) {
  return template.content.firstElementChild.cloneNode(true);
}

function renderUtility(template, paneID) {
  const panel = renderTemplate(template);
  applyPaneWeight(panel, paneID);
  return panel;
}

async function closeUtilityInstance(instance) {
  const paneID = paneIDForUtilityInstance(instance);
  const detailID = instance.key === "search" ? paneIDForSectionDetail(instance.id) : "";
  const closingProjectHost = instance.key === "saved" && paneID === state.projectHostPaneID;
  const keepProjectTools = Boolean(workspaceProject());
  const successor = closingProjectHost
    ? (state.utilityInstances || []).find((candidate) => candidate.key === "saved" && candidate.id !== instance.id) || null
    : null;
  let successorFolder = null;
  if (successor?.selectedFolderID) {
    const folders = await projectsWithOrganizationAccess(currentContentSummary().projects || []);
    successorFolder = activeFolderRecords(folders).find((folder) =>
      projectRecordID(folder) === String(successor.selectedFolderID)
    ) || null;
  }
  if (instance.key === "analysis") {
    const index = supplementalResearchConversationIDs.indexOf(instance.conversationID);
    if (index >= 0) supplementalResearchConversationIDs.splice(index, 1);
  }
  if (instance.key === "search") closeLinkedReaderForSearch(instance.id);
  if (instance.key === "saved") {
    savedItemOpeningAttempts.delete(paneID);
    if (closingProjectHost && !keepProjectTools) {
      const current = openProjectDetails()[0] || null;
      if (current && !(await deactivateProjectStudio(current, { transition: false }))) return false;
    }
    closeLinkedReaderForSavedPane(paneID, {
      includeDetailReaders: Boolean(instance.unassignedInbox || (!instance.selectedFolderID && instance.organizeUnassigned))
    });
    closeSavedItemDetailsForPane(paneID);
  }
  state.utilityInstances = (state.utilityInstances || []).filter((pane) => pane.id !== instance.id);
  if (closingProjectHost) {
    state.projectHostPaneID = successor ? paneIDForUtilityInstance(successor) : "";
    if (successor && successor.selectedFolderID && !successorFolder) successor.selectedFolderID = "";
    if (!keepProjectTools && successorFolder && folderIsProject(successorFolder)) {
      const activated = await activateProjectStudio(successorFolder, {
        sourcePaneID: state.projectHostPaneID,
        focusSaved: false,
        transition: false
      });
      if (!activated) {
        state.projectHostPaneID = "";
        successor.selectedFolderID = "";
      }
    }
  }
  if (instance.key === "search") {
    delete sectionDetailsBySearch()[instance.id];
    delete sectionDetailAnchorsBySearch()[instance.id];
  }
  delete state.paneWeights[paneID];
  if (detailID) delete state.paneWeights[detailID];
  state.paneOrder = (state.paneOrder || []).filter((id) => id !== paneID && id !== detailID);
  saveWorkspaceState();
  await transitionWorkspace("utility");
  return true;
}

function wireUtilityInstanceActions(panel, instance) {
  const closeButton = panel?.querySelector(".utility-close");
  if (!closeButton || closeButton.dataset.utilityCloseBound === instance.id) return;
  closeButton.dataset.utilityCloseBound = instance.id;
  closeButton.addEventListener("click", () => void closeUtilityInstance(instance));
}

function appendResearchList(container, title, items) {
  if (!items?.length) return;
  const heading = document.createElement("h4");
  heading.className = "research-result-subheading";
  heading.textContent = title;
  const list = document.createElement("ul");
  list.className = "research-result-list";
  items.forEach((item) => {
    const row = document.createElement("li");
    row.textContent = researchDisplayText(item);
    list.append(row);
  });
  container.append(heading, list);
}

function researchDisplayText(value) {
  return String(value || "")
    .replace(/\s*[\[(][^)\]]*\b(?:SECTION_ID|PASSAGE_IDS?)\b[^)\]]*[\])]/gi, "")
    .replace(/\s*(?:[;,]\s*)?\b(?:SECTION_ID|PASSAGE_IDS?)\s*:?\s*[A-Za-z0-9._:-]+(?:\s*,\s*[A-Za-z0-9._:-]+)*/gi, "")
    .replace(/\s+([,.;:!?])/g, "$1")
    .replace(/[;,]\s*$/, "")
    .trim();
}

function researchAnswerHasVerificationRecovery(answer) {
  return answer?.mode === "clarification" && answer.model === "permitext-conversation-clarification" &&
    answer.verification?.status === "clarification" && answer.verification.pass === false &&
    researchSystemRecoveryReasons.includes(answer.verification.reason);
}

function researchRecoveryQuestionForMessage({ message, conversation, conversationID } = {}) {
  if (!message || message.role !== "assistant" || !Array.isArray(conversation?.messages) ||
      conversationID && String(conversation.id) !== String(conversationID)) return "";
  const positions = conversation.messages.flatMap((candidate, index) =>
    candidate === message || message.id && candidate.id === message.id && candidate.role === "assistant" ? [index] : []);
  if (positions.length !== 1) return "";
  const index = positions[0], stored = conversation.messages[index];
  if (String(stored.requestID || "") !== String(message.requestID || "")) return "";
  if (stored.answer?.recoveryPresentation &&
      stored.answer.recoveryPresentation.requestID !== String(stored.requestID || "")) return "";
  const preceding = conversation.messages.slice(0, index);
  const matching = stored.requestID
    ? preceding.filter(candidate => candidate.role === "user" && candidate.requestID === stored.requestID)
    : preceding.at(-1)?.role === "user" && !preceding.at(-1).requestID ? [preceding.at(-1)] : [];
  if (matching.length !== 1) return "";
  const earlier = preceding.slice(0, preceding.indexOf(matching[0]));
  const humanContext = stored.answer?.recoveryPresentation?.humanContext;
  if (humanContext && (!Array.isArray(humanContext) || humanContext.some(bound =>
      bound.role !== "user" || earlier.filter(candidate => candidate.role === "user" && candidate.id === bound.id &&
        String(candidate.requestID || "") === bound.requestID &&
        String(candidate.question || "").replace(/\s+/g, " ").trim() === bound.question).length !== 1))) return "";
  return String(matching[0].question || "");
}

function researchVerificationRecoveryText(answer, question = "", includeAction = true) {
  if (!researchAnswerHasVerificationRecovery(answer)) return "";
  // Presentation only: historical stored answers and verification stay intact.
  const text = researchVerificationRecoveryTextForReason(answer.verification.reason, question, answer.recoveryPresentation);
  return includeAction ? text : text.split("\n\n")[0];
}

function researchAnswerNarrativeText(result, question = "") {
  const recoveryText = researchVerificationRecoveryText(result, question);
  if (recoveryText) return recoveryText;
  const adaptiveAnswer = researchDisplayText(result?.answerText);
  if (result?.mode === "clarification" && result?.model === "permitext-conversation-clarification" && result?.verification?.status === "clarification") {
    // Presentation only: retain the original saved answer and its verification state.
    const legacyLeads = [
      "I couldn’t verify the explanation well enough to give you a reliable answer yet.",
      "I need more source information to explain this accurately."
    ];
    for (const lead of legacyLeads) {
      const prefix = `${lead} We can continue in this conversation.`;
      if (adaptiveAnswer.startsWith(prefix) && adaptiveAnswer.slice(prefix.length).trim()) {
        return adaptiveAnswer.slice(prefix.length).trim();
      }
    }
  }
  if (adaptiveAnswer) return adaptiveAnswer;
  return [result?.conclusion, result?.explanation]
    .map(researchDisplayText)
    .filter(Boolean)
    .join("\n\n");
}

function researchApplicabilityStatusLabel(value) {
  const status = String(value || "").trim().toLowerCase();
  if (status === "current-enacted-edition") return "Current enacted edition";
  if (status === "historical") return "Historical";
  if (status === "prior-edition-case-specific") return "Prior edition — applicability is project-specific";
  if (status === "future-effective") return "Future effective";
  if (!status) return "Applicability status not provided";
  return status.replace(/[-_]+/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function researchCorpusMetadataLines(codeBasis) {
  const entries = [
    ...(Array.isArray(codeBasis?.searchedCorpora) ? codeBasis.searchedCorpora : [])
      .map((corpus) => ({ kind: "Searched", corpus })),
    ...(Array.isArray(codeBasis?.pinnedCorpora) ? codeBasis.pinnedCorpora : [])
      .map((corpus) => ({ kind: "Explicit evidence", corpus }))
  ];
  return entries.map(({ kind, corpus }) => [
    kind,
    corpus.label || corpus.id || "Research corpus",
    corpus.codeEdition ? `Edition: ${corpus.codeEdition}` : "Edition not provided",
    `Applicability: ${researchApplicabilityStatusLabel(corpus.applicabilityStatus)}`
  ].join(" · "));
}

function researchAnswerCopyText(result, question = "") {
  const answer = researchAnswerNarrativeText(result, question);
  const followUp = researchDisplayList(result?.followUpQuestions)[0];
  return !researchAnswerHasVerificationRecovery(result) && followUp && !answer.includes(followUp)
    ? `${answer}\n\n${followUp}` : answer;
}

function appendResearchInlineFormatting(container, value) {
  const text = String(value || "");
  const pattern = /\[([^\]\n]+)\]\(([^\s)]+)\)|\*\*([^*\n]+)\*\*|\*([^*\n]+)\*/g;
  let cursor = 0;
  for (const match of text.matchAll(pattern)) {
    const index = match.index ?? 0;
    if (index > cursor) container.append(document.createTextNode(text.slice(cursor, index)));
    let element;
    if (match[1]) {
      // Maintained DOB navigation and the official site-investigation datasets
      // can be opened here. Code citations retain their separate verification.
      const officialPropertyRecord = /^https:\/\/data\.cityofnewyork\.us\/resource\/(?:64uk-42ks|i38t-6if2|sif6-3bej)\.json\?bbl=[1-5]\d{9}(?:&(?:%24|\$)limit=100)?$/.test(match[2]);
      if (match[2] === "https://www.nyc.gov/site/buildings/dob/find-building-data.page" || officialPropertyRecord) {
        element = document.createElement("a");
        element.href = match[2];
        element.target = "_blank";
        element.rel = "noopener noreferrer";
        element.textContent = match[1];
      } else {
        element = document.createTextNode(match[0]);
      }
    } else {
      element = document.createElement(match[3] ? "strong" : "em");
      element.textContent = match[3] || match[4];
    }
    container.append(element);
    cursor = index + match[0].length;
  }
  if (cursor < text.length) container.append(document.createTextNode(text.slice(cursor)));
}

function appendResearchInlineLines(container, value) {
  String(value || "").split("\n").forEach((line, index) => {
    if (index) container.append(document.createElement("br"));
    appendResearchInlineFormatting(container, line);
  });
}

function researchAnswerTable(block) {
  const lines = String(block || "").split("\n").map((line) => line.trim()).filter(Boolean);
  const cells = (line) => {
    const normalized = line.replace(/^\|/, "").replace(/\|$/, "");
    return normalized.split("|").map((cell) => cell.trim());
  };
  if (lines.length < 3 || !lines.every((line) => line.includes("|"))) return null;
  const header = cells(lines[0]);
  const separator = cells(lines[1]);
  if (
    header.length < 2 ||
    separator.length !== header.length ||
    !separator.every((cell) => /^:?-{3,}:?$/.test(cell))
  ) return null;
  const rows = lines.slice(2).map(cells);
  if (rows.some((row) => row.length !== header.length)) return null;
  return { header, rows };
}

function researchAnswerDisplayMarkdown(value) {
  const text = String(value || "");
  // Display only. Do not reinterpret quoted source text or code as prose lists.
  if (/```|~~~/.test(text)) return text;
  return text.split(/(\n\s*\n)/).map((block, index) => {
    if (index % 2 || /^(?: {4}|\t)/.test(block) || /[\r\n`"“”‘|]/.test(block) || /(?:^|[\s:(])'[^']+'/.test(block) ||
      /^\s*(?:#{1,6}\s|>|[-*+•]\s|\d+[.)]\s)/.test(block)) return block;
    const markers = Array.from(block.matchAll(/\(([1-9]\d*)\)\s+/g));
    if (markers.length < 2 || markers.length > 20 ||
      markers.some((marker, ordinal) => Number(marker[1]) !== ordinal + 1) ||
      !/:\s*$/.test(block.slice(0, markers[0].index))) return block;
    const items = [];
    let conjunction = "";
    for (let ordinal = 0; ordinal < markers.length - 1; ordinal += 1) {
      const start = markers[ordinal].index + markers[ordinal][0].length;
      const next = markers[ordinal + 1].index;
      const separator = block.slice(start, next).match(/;\s*(?:(and|or)\s+)?$/i);
      if (!separator) return block;
      items.push(conjunction + block.slice(start, next - separator[0].length + 1).trim());
      conjunction = separator[1] ? `${separator[1]} ` : "";
    }
    let last = block.slice(markers.at(-1).index + markers.at(-1)[0].length).trim();
    let suffix = "";
    let depth = 0;
    for (let cursor = 0; cursor < last.length; cursor += 1) {
      if (last[cursor] === "(" || last[cursor] === "[") depth += 1;
      if (last[cursor] === ")" || last[cursor] === "]") depth -= 1;
      if (depth < 0) return block;
      if (depth || !/[.!?]/.test(last[cursor]) ||
        !/^\s+(?:[A-Z]|\d)/.test(last.slice(cursor + 1))) continue;
      const remainder = last.slice(cursor + 1).trim();
      // Only detach prose explicitly referring back to the numbered methods.
      // A dependent qualification such as "It must..." remains ambiguous.
      if (!/^For (?:methods?|options?|items?|alternatives?) \d+\b/.test(remainder)) return block;
      suffix = remainder;
      last = last.slice(0, cursor + 1);
      break;
    }
    items.push(conjunction + last);
    if (depth || items.some((item) => (item.match(/\b[A-Za-z]{3,}\b/g) || []).length < 2)) return block;
    const introduction = block.slice(0, markers[0].index).trimEnd();
    return `${introduction}\n\n${items.map((item, ordinal) => `${ordinal + 1}. ${item}`).join("\n")}${suffix ? `\n\n${suffix}` : ""}`;
  }).join("");
}

function appendResearchAnswerNarrative(container, result, question = "", includeRecoveryAction = true) {
  const recovery = researchVerificationRecoveryText(result, question, includeRecoveryAction);
  const text = recovery || researchAnswerDisplayMarkdown(researchAnswerNarrativeText(result, question));
  if (!text) return;
  const narrative = document.createElement("div");
  narrative.className = "research-answer-narrative";
  if (recovery) {
    // The quoted original question is plain text, including Markdown symbols.
    for (const block of recovery.split("\n\n")) {
      const paragraph = document.createElement("p"); paragraph.className = "research-answer-paragraph";
      paragraph.textContent = block; narrative.append(paragraph);
    }
    container.append(narrative); return;
  }
  text.split(/\n\s*\n/).map((block) => block.trim()).filter(Boolean).forEach((block) => {
    const lines = block.split("\n").map((line) => line.trim()).filter(Boolean);
    const tableValue = researchAnswerTable(block);
    if (tableValue) {
      const scroller = document.createElement("div");
      scroller.className = "research-answer-table-scroll";
      scroller.setAttribute("role", "region");
      scroller.setAttribute("aria-label", "Assistant answer table");
      const table = document.createElement("table");
      table.className = "research-answer-table";
      const head = document.createElement("thead");
      const headRow = document.createElement("tr");
      tableValue.header.forEach((value) => {
        const cell = document.createElement("th");
        cell.scope = "col";
        appendResearchInlineFormatting(cell, value);
        headRow.append(cell);
      });
      head.append(headRow);
      const body = document.createElement("tbody");
      tableValue.rows.forEach((values) => {
        const row = document.createElement("tr");
        values.forEach((value) => {
          const cell = document.createElement("td");
          appendResearchInlineFormatting(cell, value);
          row.append(cell);
        });
        body.append(row);
      });
      table.append(head, body);
      scroller.append(table);
      narrative.append(scroller);
      return;
    }
    if (lines.length === 1 && /^#{2,4}\s+/.test(lines[0])) {
      const heading = document.createElement("h3");
      heading.className = "research-answer-heading";
      appendResearchInlineFormatting(heading, lines[0].replace(/^#{2,4}\s+/, ""));
      narrative.append(heading);
      return;
    }
    if (lines.length && lines.every((line) => /^>\s?/.test(line))) {
      const quote = document.createElement("blockquote");
      quote.className = "research-answer-quote";
      appendResearchInlineLines(quote, lines.map((line) => line.replace(/^>\s?/, "")).join("\n"));
      narrative.append(quote);
      return;
    }
    let paragraph = null;
    let list = null;
    lines.forEach((line) => {
      const marker = line.match(/^(?:([-*+•])\s+|(\d+)[.)]\s+)(.+)$/);
      if (marker) {
        const kind = marker[2] ? "ol" : "ul";
        if (!list || list.localName !== kind) {
          list = document.createElement(kind);
          list.className = "research-answer-list";
          if (kind === "ol") list.start = Number(marker[2]);
          narrative.append(list);
        }
        paragraph = null;
        const item = document.createElement("li");
        appendResearchInlineFormatting(item, marker[3]);
        list.append(item);
      } else {
        list = null;
        if (!paragraph) {
          paragraph = document.createElement("p");
          paragraph.className = "research-answer-paragraph";
          narrative.append(paragraph);
        } else {
          paragraph.append(document.createElement("br"));
        }
        appendResearchInlineFormatting(paragraph, line);
      }
    });
  });
  container.append(narrative);
}

function researchDisplayList(values) {
  return (values || []).map(researchDisplayText).filter(Boolean);
}

function appendResearchProjectContextDisclosure(container, result) {
  const analysis = result?.structuredEvidenceAnalysis || {};
  const used = researchDisplayList(analysis.projectFactsUsed || result?.projectFactsUsed || []);
  const usage = result?.factUsage || {};
  const storedConversationFacts = [
    ...(result?.conversationFacts?.establishedFacts || []),
    ...(result?.conversationFacts?.hypotheticalFacts || [])
  ].map((fact) => researchDisplayText(fact?.statement)).filter(Boolean);
  const storedConversationFactSet = new Set(storedConversationFacts);
  const conversation = researchDisplayList(
    usage.conversation || used.filter((fact) => storedConversationFactSet.has(fact))
  );
  const conversationSet = new Set(conversation);
  const projectContext = researchDisplayList(
    usage.projectContext || used.filter((fact) => !conversationSet.has(fact))
  );
  const other = researchDisplayList(usage.other || []);
  const needed = researchDisplayList(analysis.unresolvedProjectFacts || []);
  if (!used.length && !needed.length) return;

  const details = document.createElement("details");
  details.className = "research-project-context-used";
  const summary = document.createElement("summary");
  summary.textContent = "Context used";
  const body = document.createElement("section");
  body.className = "research-project-context-used-body";
  const appendGroup = (label, values) => {
    if (!values.length) return;
    const group = document.createElement("p");
    const heading = document.createElement("strong");
    heading.textContent = `${label}: `;
    const content = document.createElement("span");
    content.textContent = values.join(" · ");
    group.append(heading, content);
    body.append(group);
  };
  if (projectContext.length || conversation.length || other.length) {
    appendGroup("Project context", projectContext);
    appendGroup("Research conversation", conversation);
    appendGroup("Other supplied facts", other);
  } else {
    appendGroup("Supplied facts", used);
  }
  appendGroup("Still needed", needed);
  details.append(summary, body);
  container.append(details);
  wireResearchDetailsMotion(details, body);
}

function appendResearchSupportedPoints(container, points) {
  if (!points?.length) return;
  const heading = document.createElement("h4");
  heading.className = "research-result-subheading";
  heading.textContent = "What the cited evidence establishes";
  const list = document.createElement("ol");
  list.className = "research-supported-points";
  points.forEach((point) => {
    const row = document.createElement("li");
    const title = document.createElement("strong");
    title.textContent = [
      point.evidenceRole === "contextual" ? "Context —" : "",
      researchDisplayText(point.heading)
    ].filter(Boolean).join(" ");
    row.append(title);
    const explanationText = researchDisplayText(point.explanation);
    if (explanationText) {
      const explanation = document.createElement("p");
      explanation.textContent = explanationText;
      row.append(explanation);
    }
    list.append(row);
  });
  container.append(heading, list);
}

function appendResearchUnresolved(container, result) {
  const limits = [...new Set(researchDisplayList(result.evidenceLimitations))];
  const facts = [...new Set(researchDisplayList(result.missingFacts))];
  const needed = [...new Set(researchDisplayList(result.additionalEvidenceNeeded))];
  appendResearchList(container, "Scope and source notes", limits);
  appendResearchList(container, "Sources still needed", needed);
  appendResearchList(container, "Project details that may affect the answer", facts);
}

function researchFeedbackUserStatus(feedback) {
  if (!feedback) return "";
  const status = String(
    feedback.userStatus || feedback.resolutionStatus || feedback.triageStatus || feedback.status || ""
  ).trim().toLowerCase().replace(/[^a-z0-9]+/g, "_");
  if (["reviewing", "under_review", "evaluation_candidate", "in_progress"].includes(status)) {
    return "Under review";
  }
  if (["resolved", "corrected", "complete", "completed"].includes(status)) {
    return "Resolved";
  }
  if (["closed", "dismissed", "rejected"].includes(status)) {
    return "Closed";
  }
  return "";
}

function renderResearchFeedback(container, message, conversationID) {
  if (!message?.id || !conversationID) return;
  const verificationRecovery = researchAnswerHasVerificationRecovery(message.answer);
  const form = document.createElement("form");
  form.className = "research-feedback";
  const compact = document.createElement("div");
  compact.className = "research-feedback-compact";
  const helpfulButton = document.createElement("button");
  helpfulButton.type = "button";
  helpfulButton.className = "research-feedback-icon";
  helpfulButton.title = "Helpful";
  helpfulButton.setAttribute("aria-label", "Mark this answer as helpful");
  helpfulButton.innerHTML = researchThumbIconSVG("up");
  const problemButton = document.createElement("button");
  problemButton.type = "button";
  problemButton.className = "research-feedback-icon";
  problemButton.title = "Report a problem";
  problemButton.setAttribute("aria-label", "Report a problem with this answer");
  if (verificationRecovery) {
    problemButton.className = "ghost-button research-feedback-report";
    problemButton.textContent = "Report this issue";
    problemButton.title = "Report this Research issue";
    problemButton.setAttribute("aria-label", "Report this Research issue");
  } else problemButton.innerHTML = researchThumbIconSVG("down");
  const status = document.createElement("span");
  status.className = "research-feedback-status";
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  const detailsButton = document.createElement("button");
  detailsButton.type = "button";
  detailsButton.className = "ghost-button research-feedback-add-details";
  detailsButton.textContent = "Add feedback details";
  if (!verificationRecovery) compact.append(helpfulButton);
  compact.append(problemButton, detailsButton, status);

  const details = document.createElement("section");
  details.className = "research-feedback-details";
  details.id = `research-feedback-details-${String(message.id).replace(/[^a-zA-Z0-9_-]/g, "-")}`;
  details.hidden = true;
  problemButton.setAttribute("aria-controls", details.id);
  problemButton.setAttribute("aria-expanded", "false");
  const choices = document.createElement("div");
  choices.className = "research-feedback-choices";
  const categories = [
    ["helpful", "Helpful"],
    ["too_slow", "Too slow"],
    ["too_verbose", "Too much explanation"],
    ["incorrect_misleading", "Incorrect or misleading"],
    ["missing_information", "Missing information"],
    ["citation_problem", "Citation problem"],
    ["other", "Other feedback"]
  ];
  let selectedCategory = message.feedback?.category || "";
  categories.forEach(([value, label]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "research-feedback-choice";
    button.textContent = label;
    button.setAttribute("aria-pressed", String(selectedCategory === value));
    button.addEventListener("click", () => {
      selectedCategory = value;
      choices.querySelectorAll("button").forEach((item) => item.setAttribute("aria-pressed", String(item === button)));
      syncCompactState();
      submit.disabled = false;
    });
    choices.append(button);
  });
  const comment = document.createElement("textarea");
  comment.rows = 2;
  comment.maxLength = 2000;
  comment.placeholder = "Tell us more (optional)…";
  comment.setAttribute("aria-label", "Feedback details (optional)");
  comment.value = message.feedback?.userComment || "";
  const optionalContext = document.createElement("details");
  optionalContext.className = "research-feedback-context";
  optionalContext.open = Boolean(
    comment.value ||
    message.feedback?.professionalRole
  );
  const optionalSummary = document.createElement("summary");
  optionalSummary.textContent = "More details (optional)";
  const professionalRole = document.createElement("select");
  professionalRole.className = "research-feedback-role-select";
  professionalRole.setAttribute("aria-label", "Professional role");
  [
    ["", "Professional role (optional)"],
    ["architect_designer", "Architect or designer"],
    ["engineer", "Engineer"],
    ["code_zoning_consultant", "Code or zoning consultant"],
    ["expeditor_filing_representative", "Expeditor or filing representative"],
    ["contractor", "Contractor"],
    ["owner_operator", "Owner or operator"],
    ["student", "Student"],
    ["other", "Other"]
  ].forEach(([value, label]) => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    professionalRole.append(option);
  });
  professionalRole.value = message.feedback?.professionalRole || "";
  const ratingSelect = (label, field, options) => {
    const wrapper = document.createElement("label");
    wrapper.textContent = label;
    const select = document.createElement("select");
    select.className = "research-feedback-rating-select";
    select.setAttribute("aria-label", label);
    options.forEach(([value, text]) => { const option = document.createElement("option"); option.value = value; option.textContent = text; select.append(option); });
    select.value = message.feedback?.[field] || "";
    wrapper.append(select);
    return { wrapper, select };
  };
  const usefulness = ratingSelect("Could you use this answer?", "usefulness", [["", "Not rated"], ["usable_as_is", "Yes, as written"], ["needed_correction", "After corrections"], ["not_usable", "No"]]);
  const checking = ratingSelect("Outside checking required", "outsideChecking", [["", "Not rated"], ["none", "None"], ["brief", "Brief checking"], ["substantial", "Substantial checking"]]);
  const reference = document.createElement("input");
  reference.placeholder = "Supporting section or official source (optional)";
  reference.setAttribute("aria-label", "Supporting section or official source");
  reference.maxLength = 500;
  reference.value = message.feedback?.supportingReference || "";
  optionalContext.append(optionalSummary, usefulness.wrapper, checking.wrapper, professionalRole, reference);

  const submit = document.createElement("button");
  submit.type = "submit";
  submit.className = "ghost-button";
  submit.textContent = message.feedback ? "Update feedback" : "Send feedback";
  submit.disabled = !selectedCategory;
  const cancel = document.createElement("button");
  cancel.type = "button";
  cancel.className = "ghost-button research-feedback-cancel";
  cancel.textContent = "Cancel";
  const actions = document.createElement("div");
  actions.className = "research-feedback-actions";
  actions.append(submit, cancel);
  const setDetailsOpen = (open) => {
    details.hidden = !open;
    problemButton.setAttribute("aria-expanded", String(open));
    detailsButton.setAttribute("aria-expanded", String(open));
  };
  const syncCompactState = () => {
    helpfulButton.setAttribute("aria-pressed", String(selectedCategory === "helpful"));
    problemButton.setAttribute("aria-pressed", String(Boolean(selectedCategory && selectedCategory !== "helpful")));
    detailsButton.hidden = !selectedCategory;
    status.textContent = researchFeedbackUserStatus(message.feedback);
  };
  const setBusy = (busy) => {
    helpfulButton.disabled = busy;
    problemButton.disabled = busy;
    submit.disabled = busy || !selectedCategory;
    cancel.disabled = busy;
  };
  const saveFeedback = async (category, fields = {}) => {
    setBusy(true);
    status.textContent = "Saving…";
    try {
      const payload = await postResearch("/research/feedback", {
        conversationID,
        answerID: message.id,
        category,
        comment: fields.comment ?? comment.value,
        professionalRole: fields.professionalRole ?? professionalRole.value,
        supportingReference: reference.value,
        usefulness: usefulness.select.value,
        outsideChecking: checking.select.value
      });
      message.feedback = payload.feedback;
      selectedCategory = payload.feedback.category;
      submit.textContent = "Update feedback";
      syncCompactState();
      setDetailsOpen(false);
    } catch (error) {
      status.textContent = error.message;
    } finally {
      setBusy(false);
    }
  };
  helpfulButton.addEventListener("click", () => {
    comment.value = "";
    professionalRole.value = "";
    professionalRole._syncCustomSelect?.();
    void saveFeedback("helpful", { comment: "", professionalRole: "" });
  });
  detailsButton.addEventListener("click", () => setDetailsOpen(details.hidden));
  problemButton.addEventListener("click", () => {
    setDetailsOpen(details.hidden);
  });
  cancel.addEventListener("click", () => setDetailsOpen(false));
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (!selectedCategory) return;
    await saveFeedback(selectedCategory);
  });
  const feedbackHeading = document.createElement("h4");
  feedbackHeading.className = "research-feedback-heading";
  feedbackHeading.textContent = verificationRecovery ? "Report this Research issue" : "How was this answer?";
  details.append(feedbackHeading, choices, comment, optionalContext, actions);
  const evidenceReviewed = container.lastElementChild?.querySelector(":scope > .research-evidence-reviewed");
  if (evidenceReviewed) {
    const reviewRow = document.createElement("div");
    reviewRow.className = "research-answer-review-row";
    evidenceReviewed.replaceWith(form);
    const copyRow = container.lastElementChild?.querySelector(".research-answer-copy-row");
    reviewRow.append(evidenceReviewed);
    if (copyRow) reviewRow.append(copyRow);
    reviewRow.append(compact);
    form.append(reviewRow, details);
  } else {
    form.append(compact, details);
    container.append(form);
  }
  enhanceSelect(professionalRole);
  enhanceSelect(usefulness.select);
  enhanceSelect(checking.select);
  syncCompactState();
}

function renderResearchInterpretation(container, result, options = {}) {
  clear(container);
  if (!result) return;
  const recoveryQuestion = options.message ? researchRecoveryQuestionForMessage(options) : options.recordQuestion || "";

  const card = document.createElement("article");
  card.className = "analysis-card research-result-card";
  const metadata = document.createElement("section");
  metadata.className = "research-answer-metadata";
  if (result.authorityLabel) {
    const authority = document.createElement("p");
    authority.className = "research-authority-status";
    authority.dataset.authorityStatus = result.authorityStatus || "";
    const standardEnactedSupport = result.authorityStatus === "supported_by_enacted_text" &&
      result.authorityLabel === "Supported by enacted text";
    authority.textContent = standardEnactedSupport
      ? "Enacted text supports the cited points"
      : result.authorityLabel;
    metadata.append(authority);
  }
  const reportMessage = options.message || options.recordMessage;
  appendResearchAnswerNarrative(card, result, recoveryQuestion, Boolean(reportMessage?.id && options.conversationID));
  const nextQuestion = researchDisplayList(result.followUpQuestions)[0];
  if (!researchAnswerHasVerificationRecovery(result) && nextQuestion && !researchAnswerNarrativeText(result).includes(nextQuestion)) {
    const followUp = document.createElement("p");
    followUp.className = "research-answer-paragraph research-answer-follow-up";
    followUp.textContent = nextQuestion;
    card.append(followUp);
  }

  const codeBasis = result.codeBasis || null;
  const codeBasisText = String(
    codeBasis?.disclosure ||
    (result.codeEdition ? `Code basis: ${result.codeEdition}` : "")
  ).trim();
  const basisLimitation = String(codeBasis?.limitation || "").trim();
  const parsedSourceAsOf = result.sourceAsOf ? new Date(result.sourceAsOf) : null;
  const sourceAsOf = parsedSourceAsOf && Number.isFinite(parsedSourceAsOf.getTime())
    ? parsedSourceAsOf.toISOString().slice(0, 10)
    : "";
  if (codeBasisText || basisLimitation || sourceAsOf) {
    const codeDisclosure = document.createElement("p");
    codeDisclosure.className = "research-answer-code-basis";
    codeDisclosure.textContent = [
      codeBasisText,
      sourceAsOf ? `Research basis captured ${sourceAsOf}` : ""
    ]
      .filter(Boolean)
      .join(" · ");
    metadata.append(codeDisclosure);
  }
  const corpusMetadataLines = researchCorpusMetadataLines(codeBasis);
  if (corpusMetadataLines.length) {
    const corpusMetadata = document.createElement("ul");
    corpusMetadata.className = "research-answer-corpus-metadata";
    corpusMetadata.setAttribute("aria-label", "Research corpus editions and applicability");
    corpusMetadataLines.forEach((line) => {
      const item = document.createElement("li");
      item.textContent = line;
      corpusMetadata.append(item);
    });
    metadata.append(corpusMetadata);
  }

  if (basisLimitation) {
    const limitation = document.createElement("p");
    limitation.className = "research-answer-limitation";
    limitation.textContent = basisLimitation;
    card.append(limitation);
  }


  const evidenceReviewed = document.createElement("details");
  evidenceReviewed.className = "research-evidence-reviewed";
  evidenceReviewed.open = Boolean(options.detailsOpen);
  const evidenceReviewedSummary = document.createElement("summary");
  evidenceReviewedSummary.className = "research-details-icon";
  evidenceReviewedSummary.title = "Sources & details";
  evidenceReviewedSummary.setAttribute("aria-label", "Sources & details");
  evidenceReviewedSummary.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/></svg>';
  const evidenceReviewedBody = document.createElement("section");
  evidenceReviewedBody.className = "research-evidence-reviewed-body";


  if (result.citations?.length) {
    const answerSources = options.message && options.conversation
      ? researchSourcesForAnswer(options.conversation, options.message)
      : [];
    const citationRow = document.createElement("nav");
    citationRow.className = "research-answer-citation-chips";
    citationRow.setAttribute("aria-label", "Sources cited in this answer");
    result.citations.forEach((citation) => {
      const citationButton = document.createElement("button");
      citationButton.type = "button";
      citationButton.textContent = [
        citation.evidenceRole === "contextual"
          ? "Context"
          : citation.evidenceRole === "supporting"
            ? "Supporting"
            : "Governing",
        citation.codePrefix,
        citation.sectionNumber ? `§ ${citation.sectionNumber}` : citation.title
      ].filter(Boolean).join(" ");
      citationButton.title = [citation.corpusLabel, citation.codeEdition].filter(Boolean).join(" · ");
      citationButton.addEventListener("click", () => {
        const sourceIDs = new Set((citation.sourceIDs || []).map(String));
        const exactSource = answerSources.find((source) =>
          sourceIDs.has(String(source.id || "")) ||
          sourceIDs.has(String(source.sourceID || "")) ||
          String(source.sectionID || "") === String(citation.sectionID || "")
        );
        if (exactSource) {
          void openSourceInReader(exactSource, options.anchorPaneID || "", {
            projectID: options.conversation?.primaryProjectID || ""
          });
          return;
        }
        if (citation.sectionID || citation.sectionNumber) {
          void openSourceInReader(citation, options.anchorPaneID || "", {
            projectID: options.conversation?.primaryProjectID || ""
          });
          return;
        }
        const sourceDetails = container.querySelector(".research-answer-source-text");
        if (!sourceDetails) return;
        if (sourceDetails.setResearchExpanded) sourceDetails.setResearchExpanded(true);
        else sourceDetails.open = true;
        sourceDetails.scrollIntoView({ block: "nearest", behavior: "smooth" });
      });
      citationRow.append(citationButton);
    });
    const sourcesHeading = document.createElement("h4");
    sourcesHeading.className = "research-result-subheading";
    sourcesHeading.textContent = "Sources cited";
    evidenceReviewedBody.append(sourcesHeading, citationRow);
  }

  const missingFactCount = result.missingFacts?.length || 0;
  const evidenceNoteCount = result.evidenceLimitations?.length || 0;
  const neededSourceCount = result.additionalEvidenceNeeded?.length || 0;
  const sourceSummary = result.sourceSummary || {};
  const enactedCount = Number(sourceSummary.enactedProvisionCount || 0);
  const contextualCount = Number(sourceSummary.contextualProvisionCount || 0);
  const citedProvisionCount = Number(sourceSummary.citedProvisionCount || 0);
  const supportingCitationCount = Number(sourceSummary.supportingCitationCount || 0);
  const reviewedOnlyProvisionCount = Number(sourceSummary.reviewedOnlyProvisionCount || 0);
  const projectFactCount = Number(sourceSummary.projectFactCount || 0);
  const distinctSupportingSourceCount = new Set(
    (result.supportingSources || [])
      .map((source) => String(source?.id || source?.url || "").trim())
      .filter(Boolean)
  ).size;
  const supportingWebSourceCount = distinctSupportingSourceCount || Number(sourceSummary.supportingWebSourceCount || 0);
  const officialGuidanceOnly = result.authorityStatus === "official_supporting_guidance";
  const sourceScope = officialGuidanceOnly
    ? [
        supportingWebSourceCount
          ? `Based on ${supportingWebSourceCount} approved official supporting ${supportingWebSourceCount === 1 ? "source" : "sources"}`
          : "Based on approved official supporting guidance",
        "No enacted provision cited"
      ].join(" · ")
    : result.mode === "project_context" && projectFactCount
    ? `Based on ${projectFactCount} saved Project ${projectFactCount === 1 ? "fact" : "facts"}`
    : citedProvisionCount
    ? [
        `Cited ${citedProvisionCount} enacted ${citedProvisionCount === 1 ? "provision" : "provisions"}`,
        supportingCitationCount
          ? `${supportingCitationCount} supporting ${supportingCitationCount === 1 ? "citation" : "citations"}`
          : "",
        reviewedOnlyProvisionCount
          ? `${reviewedOnlyProvisionCount} additional ${reviewedOnlyProvisionCount === 1 ? "provision" : "provisions"} reviewed`
          : ""
      ].filter(Boolean).join(" · ")
    : enactedCount
    ? [
        `Based on ${enactedCount} enacted ${enactedCount === 1 ? "provision" : "provisions"}`,
        sourceSummary.userPinnedCount ? `${sourceSummary.userPinnedCount} pinned by you` : "",
        sourceSummary.permitextDiscoveredCount ? `${sourceSummary.permitextDiscoveredCount} identified by Permitext` : "",
        sourceSummary.crossReferenceCount ? `${sourceSummary.crossReferenceCount} cross-references reviewed` : ""
      ].filter(Boolean).join(" · ")
    : researchAnswerHasVerificationRecovery(result)
    ? "No answer completed"
    : "Grounded in the cited Research sources";
  const boundary = document.createElement("p");
  boundary.className = "research-answer-boundary";
  boundary.textContent = [
    sourceScope,
    contextualCount && !citedProvisionCount && !officialGuidanceOnly
      ? `${contextualCount} contextual ${contextualCount === 1 ? "provision" : "provisions"} reviewed separately`
      : "",
    missingFactCount ? `${missingFactCount} project ${missingFactCount === 1 ? "fact remains" : "facts remain"} unresolved` : "No unresolved project facts identified",
    evidenceNoteCount ? `${evidenceNoteCount} scope/source ${evidenceNoteCount === 1 ? "note" : "notes"}` : "No scope/source notes listed",
    neededSourceCount ? `${neededSourceCount} ${neededSourceCount === 1 ? "source still" : "sources still"} needed` : ""
  ].filter(Boolean).join(" · ");
  metadata.append(boundary);

  const details = document.createElement("details");
  details.className = "research-answer-details";
  details.open = false;
  const summary = document.createElement("summary");
  summary.textContent = "Research details";
  const detailsBody = document.createElement("section");
  detailsBody.className = "research-answer-details-body";
  detailsBody.append(metadata);
  appendResearchSupportedPoints(detailsBody, result.supportedPoints);
  appendResearchList(detailsBody, "Assumptions used", result.assumptions);
  const authorityNote = metadata.querySelector(".research-authority-status");
  if (authorityNote) evidenceReviewedBody.append(authorityNote);
  appendResearchUnresolved(evidenceReviewedBody, result);
  appendResearchProjectContextDisclosure(evidenceReviewedBody, result);
  const supportingSources = result.supportingSources || [];
  if (supportingSources.length) {
    const supportingHeading = document.createElement("h4");
    supportingHeading.className = "research-result-subheading";
    supportingHeading.textContent = "Supporting context — noncontrolling";
    const supportingList = document.createElement("ul");
    supportingList.className = "research-result-list";
    supportingSources.forEach((source) => {
      const item = document.createElement("li");
      const title = source.title || source.publisher || "Supporting source";
      let linked = false;
      try {
        const rawURL = String(source.url || "").trim();
        const url = rawURL ? new URL(rawURL) : null;
        if (url?.protocol === "https:" && url.hostname) {
          const link = document.createElement("a");
          link.href = url.href;
          link.target = "_blank";
          link.rel = "noopener noreferrer";
          link.textContent = title;
          item.append(link);
          linked = true;
        }
      } catch {
        // Keep the source visible as plain text if its URL is unavailable.
      }
      if (!linked) item.append(document.createTextNode(title));
      if (source.claim) item.append(document.createTextNode(`: ${source.claim}`));
      supportingList.append(item);
    });
    detailsBody.append(supportingHeading, supportingList);
  }
  details.append(summary, detailsBody);
  evidenceReviewedBody.append(details);
  wireResearchDetailsMotion(details, detailsBody);
  evidenceReviewed.append(evidenceReviewedSummary, evidenceReviewedBody);
  card.append(evidenceReviewed);
  const copyRow = document.createElement("div");
  copyRow.className = "research-answer-copy-row";
  const copyButton = document.createElement("button");
  copyButton.type = "button";
  copyButton.className = "ghost-button research-answer-copy";
  copyButton.title = "Copy answer";
  copyButton.setAttribute("aria-label", "Copy answer");
  copyButton.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h4"/></svg>';
  const copyStatus = document.createElement("span");
  copyStatus.className = "research-answer-copy-status sr-only";
  copyStatus.setAttribute("role", "status");
  copyStatus.setAttribute("aria-live", "polite");
  const copyIcon = copyButton.innerHTML;
  copyButton.addEventListener("click", async () => {
    copyButton.disabled = true;
    const answerText = [...card.querySelectorAll(":scope > .research-answer-narrative, :scope > .research-answer-follow-up")]
      .map((node) => node.innerText.trim()).filter(Boolean).join("\n\n");
    const copied = await copyTextToClipboard(answerText || researchAnswerCopyText(result, recoveryQuestion));
    copyStatus.textContent = copied
      ? "Answer copied"
      : "Copy unavailable";
    copyButton.innerHTML = copied
      ? '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>'
      : copyIcon;
    copyButton.title = copied ? "Copied" : "Copy unavailable";
    copyButton.disabled = false;
    window.setTimeout(() => {
      if (copyStatus.isConnected) {
        copyStatus.textContent = "";
        copyButton.innerHTML = copyIcon;
        copyButton.title = "Copy answer";
      }
    }, 2_000);
  });
  copyRow.append(copyButton, copyStatus);
  card.append(copyRow);
  const disclaimer = document.createElement("p");
  disclaimer.className = "research-answer-disclaimer";
  disclaimer.textContent = String(
    result.disclaimer || "AI-generated research assistance, not an official code determination."
  ).trim();
  detailsBody.append(disclaimer);
  const nextStep = document.createElement("p");
  nextStep.className = "research-answer-disclaimer research-answer-next-step";
  nextStep.textContent = researchAnswerHasVerificationRecovery(result)
    ? "Use Report this issue to open the feedback form. Nothing is sent until you choose Send feedback."
    : "Review cited provisions and Project facts. Record your own conclusion in a Project Note before adding it to a Report.";
  if (!researchAnswerHasVerificationRecovery(result) || reportMessage?.id && options.conversationID) detailsBody.append(nextStep);
  container.append(card);
  wireResearchDetailsMotion(evidenceReviewed, evidenceReviewedBody);
  if (reportMessage) renderResearchFeedback(container, reportMessage, options.conversationID);
}

async function renderUtilityInstance(instance, options = {}) {
  const paneID = paneIDForUtilityInstance(instance);
  let panel = null;
  if (instance.key === "search") {
    panel = await renderSearch(instance, options);
  } else if (instance.key === "saved") {
    panel = await renderSaved(instance, options);
  } else if (instance.key === "analysis") {
    panel = await renderResearch(paneID);
  }
  wireUtilityInstanceActions(panel, instance);
  return panel;
}

function researchRequestBody(values = {}) {
  const account = activeAccount();
  return {
    auth: { accountUserID: account?.userID || "" },
    ...values
  };
}

function researchWorkspaceProjectID() {
  const project = workspaceProject();
  return project ? String(projectDetailKey(project) || "").trim() : "";
}

function researchCreationProjectID(requestedProjectID = "") {
  const projectID = researchWorkspaceProjectID();
  if (!projectID && activeWorkspaceRecord()?.projectID) {
    throw new Error("The workspace’s project is still loading. Try again once its project context is available.");
  }
  return projectID || String(requestedProjectID || "").trim();
}

function researchConversationInWorkspace(conversation, projectID = researchWorkspaceProjectID()) {
  if (!projectID && activeWorkspaceRecord()?.projectID) return false;
  return String(conversation?.primaryProjectID || "").trim() === projectID;
}

function workspaceResearchConversations() {
  return researchConversationList.filter(conversation => researchConversationInWorkspace(conversation));
}

async function postResearch(path, values = {}) {
  const account = activeAccount();
  const identity = captureAccountRequest();
  if (!account) throw new Error("Sign in from Account to use private research conversations.");
  const creationWorkspaceID = activeWorkspaceID;
  if (path === "/research/conversations/create") {
    values = { ...values, projectID: researchCreationProjectID(values.projectID) };
    if (values.projectID) await ensureResearchProjectSynced(values.projectID, account);
    if (creationWorkspaceID !== activeWorkspaceID) throw codeQuestionContextChangedError();
  }
  requireCurrentAccountRequest(identity);
  const payload = await postJSON(path, { ...values, auth: { accountUserID: account.userID } }, { token: account.sessionToken });
  requireCurrentAccountRequest(identity);
  if (path.startsWith("/research/conversations/") && !["/research/conversations/list", "/research/conversations/get"].includes(path)) {
    readResearchConversationList.invalidate();
    researchHistoryPageReaders.forEach((read) => read.invalidate());
    refreshResearchUsage.invalidate();
  }
  if (payload?.artifactRevisions) observeLocalProjectArtifactRevisions(payload.artifactRevisions);
  return payload;
}

async function ensureResearchProjectSynced(projectID, account = activeAccount()) {
  const requestIdentity = captureAccountRequest();
  const normalizedProjectID = String(projectID || "").trim();
  if (!normalizedProjectID) return;
  const pendingProject = (state.localProjects || []).find((project) =>
    researchProjectID(project) === normalizedProjectID
  );
  if (!pendingProject) return;
  if (!account) {
    throw new Error("Sign in and sync this Project before starting assigned Research.");
  }

  const pendingUpdatedAt = pendingProject.updatedAt || null;
  await pushMutation(projectMutationForRecord(pendingProject, account));
  requireCurrentAccountRequest(requestIdentity);
  state.localProjects = (state.localProjects || []).filter((project) =>
    researchProjectID(project) !== normalizedProjectID ||
    (project.updatedAt || null) !== pendingUpdatedAt
  );
  saveWorkspaceState();
}

async function postResearchWithProgress(values, { signal, onProgress } = {}) {
  const account = activeAccount();
  const identity = captureAccountRequest();
  if (!account) throw new Error("Sign in from Account to use private research conversations.");
  let response;
  try {
    response = await fetch("/research/conversations/message", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${account.sessionToken}`
      },
      body: JSON.stringify(researchRequestBody({ ...values, progressStream: "ndjson" })),
      signal
    });
    requireCurrentAccountRequest(identity);
    serverReachable = response.status < 500;
  } catch (error) {
    requireCurrentAccountRequest(identity);
    serverReachable = false;
    updateConnectionStatus();
    if (error.name !== "AbortError" && typeof error.code !== "string") {
      const interrupted = new Error("The Research connection ended before a completed response.", { cause: error });
      interrupted.code = "RESEARCH_INTERRUPTED";
      throw interrupted;
    }
    throw error;
  }
  updateConnectionStatus();
  const contentType = String(response.headers.get("content-type") || "");
  if (!contentType.includes("application/x-ndjson") || !response.body) {
    const payload = await response.json().catch(() => ({}));
    requireCurrentAccountRequest(identity);
    if (!response.ok) {
      const error = new Error(payload.error || `Request failed: ${response.status}`);
      error.status = response.status;
      error.code = payload.code || null;
      error.payload = payload;
      throw error;
    }
    return payload;
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let result = null;
  const consumeLine = (line) => {
    requireCurrentAccountRequest(identity);
    if (!line.trim()) return;
    const event = JSON.parse(line);
    if (event.type === "progress") {
      onProgress?.(event.progress);
      return;
    }
    if (event.type === "result") {
      result = event.payload;
      return;
    }
    if (event.type === "error") {
      const error = new Error(event.error?.message || "Research request failed.");
      error.status = Number(event.error?.status || 500);
      error.code = event.error?.code || null;
      error.payload = event.error || {};
      throw error;
    }
  };
  while (true) {
    let chunk;
    try { chunk = await reader.read(); }
    catch (error) {
      requireCurrentAccountRequest(identity);
      if (error.name !== "AbortError" && typeof error.code !== "string") {
        const interrupted = new Error("The Research connection ended before a completed response.", { cause: error });
        interrupted.code = "RESEARCH_INTERRUPTED";
        throw interrupted;
      }
      throw error;
    }
    const { value, done } = chunk;
    requireCurrentAccountRequest(identity);
    buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";
    lines.forEach(consumeLine);
    if (done) break;
  }
  consumeLine(buffer);
  if (!result) {
    const error = new Error("Research ended before returning a completed response.");
    error.code = "RESEARCH_INTERRUPTED";
    throw error;
  }
  return result;
}

async function fetchAuthoritativeResearchConversation(conversationID) {
  const account = activeAccount();
  if (!account) throw new Error("Sign in from Account to open private Research conversations.");
  const payload = await postJSON("/research/conversations/get", {
    auth: { accountUserID: account.userID },
    conversationID: String(conversationID || "").trim()
  }, { token: account.sessionToken });
  const current = activeAccount();
  if (current?.userID !== account.userID || current?.sessionToken !== account.sessionToken) {
    throw codeQuestionContextChangedError();
  }
  return payload.conversation;
}

function researchOpenContextIsCurrent(context, options = {}) {
  const account = activeAccount();
  return Boolean(
    context?.generation === researchOpenGeneration &&
    context.accountUserID === (account?.userID || "") &&
    context.sessionToken === (account?.sessionToken || "") &&
    context.projectID === activeProjectIDForCodeQuestions() &&
    (!options.requireConversationID || state.researchConversationID === context.conversationID)
  );
}

async function loadOrganizationWorkspace(options = {}) {
  if (!releaseSurfaceVisibility.firmCollaboration) {
    organizationWorkspace = { organizations: [] };
    return organizationWorkspace;
  }
  const account = activeAccount();
  const identity = captureAccountRequest();
  if (!account) {
    organizationWorkspace = { organizations: [] };
    return organizationWorkspace;
  }
  if (options.force) {
    organizationWorkspace = null;
    organizationLoadPromise = null;
  }
  if (organizationWorkspace) return organizationWorkspace;
  if (!organizationLoadPromise) {
    const request = postResearch("/organizations/list")
      .then((payload) => {
        if (!isCurrentAccountRequest(identity) || organizationLoadPromise !== request) return null;
        organizationWorkspace = {
          organizations: Array.isArray(payload.organizations) ? payload.organizations : []
        };
        return organizationWorkspace;
      })
      .catch((error) => {
        if (!isCurrentAccountRequest(identity) || organizationLoadPromise !== request) return null;
        organizationWorkspace = { organizations: [], error: error.message };
        return organizationWorkspace;
      })
      .finally(() => {
        if (organizationLoadPromise === request) organizationLoadPromise = null;
      });
    organizationLoadPromise = request;
  }
  return organizationLoadPromise;
}

function sharedProjectsFromOrganizations(workspace = organizationWorkspace) {
  return (workspace?.organizations || []).flatMap((organization) =>
    (organization.projects || []).map((project) => ({
      ...project,
      id: project.id,
      clientID: project.id,
      sharedOrganizationID: organization.id,
      sharedOrganizationName: organization.name,
      sharedRole: project.role || organization.role,
      sharedPermissions: project.permissions || organization.permissions || [],
      sharedOnly: true
    }))
  );
}

function mergeProjectsWithOrganizationAccess(projects = [], workspace = organizationWorkspace) {
  if (!releaseSurfaceVisibility.firmCollaboration) return projects;
  const sharedProjects = sharedProjectsFromOrganizations(workspace);
  const sharedByID = new Map(sharedProjects.map((project) => [String(project.id), project]));
  const localIDs = new Set();
  const combined = projects.map((project) => {
    const identity = projectDetailKey(project);
    localIDs.add(identity);
    const shared = sharedByID.get(identity);
    return shared ? { ...project, ...shared, sharedOnly: false } : project;
  });
  sharedProjects.forEach((project) => {
    if (!localIDs.has(projectDetailKey(project))) combined.push(project);
  });
  return combined;
}

async function projectsWithOrganizationAccess(projects = []) {
  const workspace = await loadOrganizationWorkspace();
  return mergeProjectsWithOrganizationAccess(projects, workspace);
}

async function readProjectReportFile(projectID, file, title = "Permitext Project Report") {
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  if (!account) throw new Error("Sign in from Account to download private Project Reports.");
  const response = await fetch("/reports/files/read", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${account.sessionToken}`
    },
    body: JSON.stringify({
      auth: { accountUserID: account.userID },
      projectID,
      generatedReportID: file.generatedReportID
    })
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(payload.error || "The Report PDF could not be downloaded.");
  }
  const blob = await response.blob();
  requireCurrentAccountRequest(requestIdentity);
  const safeTitle = String(title || "Permitext Project Report")
    .replace(/[^a-z0-9]+/gi, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "Permitext-Project-Report";
  return { pdfBlob: blob, filename: `${safeTitle}-v${file.reportVersion || 1}-${file.format || "report"}.pdf` };
}

async function downloadProjectReportFile(projectID, file, title = "Permitext Project Report") {
  const packet = await readProjectReportFile(projectID, file, title);
  const url = URL.createObjectURL(packet.pdfBlob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = packet.filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 2_000);
}

// Share reads within an account, but let explicit refreshes supersede older
// snapshots. A late request follows the current attempt instead of publishing it.
function createResearchRefresh(load, publish) {
  let scope = null;
  const currentScope = () => {
    const account = activeAccount();
    const key = account ? JSON.stringify(captureAccountRequest()) : "";
    if (!scope || scope.key !== key) scope = { key, generation: 0, flight: null, loadedAt: 0, value: null };
    return scope;
  };
  const read = ({ reuseRecent = false } = {}) => {
    const owner = currentScope();
    if (!owner.key) return Promise.reject(codeQuestionContextChangedError());
    if (reuseRecent && owner.flight) return owner.flight;
    if (reuseRecent && owner.loadedAt && Date.now() - owner.loadedAt < 1500) return Promise.resolve(owner.value);
    const generation = ++owner.generation;
    const request = Promise.resolve().then(load).then((value) => {
      if (currentScope() !== owner) throw codeQuestionContextChangedError();
      if (owner.generation !== generation) return read({ reuseRecent: true });
      publish(value);
      owner.value = value;
      owner.loadedAt = Date.now();
      return value;
    }, (error) => {
      if (currentScope() !== owner) throw codeQuestionContextChangedError();
      if (owner.generation !== generation) return read({ reuseRecent: true });
      throw error;
    }).finally(() => {
      if (owner.flight === request) owner.flight = null;
    });
    owner.flight = request;
    return request;
  };
  read.invalidate = () => {
    const owner = currentScope();
    owner.generation += 1;
    owner.flight = null;
    owner.loadedAt = 0;
  };
  return read;
}

const refreshResearchUsage = createResearchRefresh(
  () => postResearch("/research/usage"),
  (payload) => { researchUsage = payload.usage || null; }
);
const readResearchConversationList = createResearchRefresh(
  () => postResearch("/research/conversations/list"),
  (payload) => {
    researchConversationList = (payload.conversations || []).slice().sort((left, right) =>
      String(right.createdAt || "").localeCompare(String(left.createdAt || "")) ||
      String(left.id || "").localeCompare(String(right.id || ""))
    );
  }
);

// Bounded, account-scoped page sharing keeps multiple history columns cheap.
const researchHistoryPageReaders = new Map();
function boundedResearchHistoryQuery(value) {
  const text = String(value || "");
  if (text.length <= 200) return text;
  const segments = typeof Intl.Segmenter === "function"
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(text)
    : Array.from(text, (segment) => ({ segment }));
  let bounded = "";
  for (const { segment } of segments) {
    if (bounded.length + segment.length > 200) break;
    bounded += segment;
  }
  return bounded;
}

function readResearchHistoryPage(filters, options = {}) {
  const values = { limit: 30, q: boundedResearchHistoryQuery(String(filters.q || "").trim()),
    ...(filters.projectID !== "*" ? { projectID: String(filters.projectID || "") } : {}),
    ...(filters.cursor ? { cursor: filters.cursor } : {}) };
  const key = JSON.stringify(values);
  if (!researchHistoryPageReaders.has(key)) {
    if (researchHistoryPageReaders.size >= 40) researchHistoryPageReaders.delete(researchHistoryPageReaders.keys().next().value);
    researchHistoryPageReaders.set(key, createResearchRefresh(
      () => postResearch("/research/conversations/list", values), () => {}
    ));
  }
  return researchHistoryPageReaders.get(key)({ reuseRecent: true, ...options });
}

async function openResearchHistoryConversation(conversation, instance) {
  const identity = captureAccountRequest();
  if (!researchConversationInWorkspace(conversation)) {
    reconcileProjectWorkspaces();
    const projectID = String(conversation.primaryProjectID || "");
    const project = researchProjects().find((item) => researchProjectID(item) === projectID);
    const target = workspaceRegistry.workspaces.find((workspace) =>
      projectID ? workspace.projectID === (project ? projectRecordID(project) : projectID) : !workspace.projectID
    );
    if (!target) {
      await showWebNotice("Project unavailable", "Restore this conversation's Project before opening its Research. Its history and source records are preserved.");
      return;
    }
    if (!await switchWorkspace(target.id, { focus: false })) return;
    if (!isCurrentAccountRequest(identity)) return;
    instance = (state.utilityInstances || []).filter((item) => item.key === "analysis").at(-1);
    if (!instance) {
      await openNewResearchColumn();
      if (!isCurrentAccountRequest(identity)) return;
      instance = (state.utilityInstances || []).filter((item) => item.key === "analysis").at(-1);
    }
  }
  return openResearchConversation(conversation.id, { instance });
}

async function refreshResearchConversationList(options = {}) {
  if (!activeAccount()) {
    researchConversationList = [];
    activeResearchConversation = null;
    researchUsage = null;
    return [];
  }
  // Allowance is secondary metadata: its failure must not hide readable history.
  void refreshResearchUsage(options).catch(() => {});
  await readResearchConversationList(options);
  return researchConversationList;
}

function closeCodeQuestionDownstreamPanes({ clearSelection = false } = {}) {
  if (!codeQuestionWorkspaceEnabled()) return;
  const current = codeQuestionWorkspaceState();
  const openPanes = (current.openPanes || []).filter((pane) => pane.paneRole === "question-index");
  setCodeQuestionWorkspaceState({
    ...current,
    openPanes,
    questionIndexOpen: openPanes.length > 0,
    moreMenuOpen: false,
    ...(clearSelection ? { activeQuestionID: "", deepLink: null } : {})
  }, {
    activeProjectID: activeProjectIDForCodeQuestions(),
    syncDeepLink: true
  });
}

async function closeResearchWorkspace() {
  researchOpenGeneration += 1;
  researchConversationPaneOpened = false;
  const projectPaneIDs = openProjectDetails().map((detail) => paneIDForProjectDetail(detail));
  state.utilities.analysis = false;
  state.researchConversationID = "";
  activeResearchConversation = null;
  supplementalResearchConversationIDs.splice(0);
  supplementalResearchConversations.clear();
  closeCodeQuestionDownstreamPanes({ clearSelection: true });
  delete state.paneWeights["utility:analysis"];
  Object.keys(state.paneWeights).filter((id) => id.startsWith("research:conversation:")).forEach((id) => delete state.paneWeights[id]);
  state.paneOrder = (state.paneOrder || []).filter((id) => id !== "utility:analysis" && !id.startsWith("research:conversation:"));
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: projectPaneIDs });
}

async function closeResearchConversation(conversationIDOverride = "") {
  const requestedConversationID = String(conversationIDOverride || "").trim();
  const supplementalIndex = supplementalResearchConversationIDs.indexOf(requestedConversationID);
  if (supplementalIndex !== -1) {
    supplementalResearchConversationIDs.splice(supplementalIndex, 1);
    supplementalResearchConversations.delete(requestedConversationID);
    const supplementalPaneID = paneIDForResearchConversation(requestedConversationID);
    delete state.paneWeights[supplementalPaneID];
    state.paneOrder = (state.paneOrder || []).filter((id) => id !== supplementalPaneID);
    saveWorkspaceState();
    await transitionWorkspace("utility");
    return;
  }
  researchOpenGeneration += 1;
  researchConversationPaneOpened = false;
  const conversationID = String(state.researchConversationID || "").trim();
  const conversation = activeResearchConversation?.id === conversationID
    ? activeResearchConversation
    : researchConversationList.find((item) => item.id === conversationID) || null;
  if (
    conversation?.linkedCodeDecisionID &&
    conversation.primaryProjectID === activeProjectIDForCodeQuestions()
  ) {
    dismissedLinkedResearchDecisionKeys.add(
      linkedResearchDecisionDismissalKey(conversation.linkedCodeDecisionID, conversation.primaryProjectID)
    );
  }
  const paneID = paneIDForResearchConversation(conversationID);
  const projectPaneIDs = openProjectDetails().map((detail) => paneIDForProjectDetail(detail));
  state.researchConversationID = "";
  activeResearchConversation = null;
  closeCodeQuestionDownstreamPanes({ clearSelection: true });
  if (paneID) delete state.paneWeights[paneID];
  state.paneOrder = (state.paneOrder || []).filter((id) => id !== paneID);
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: ["utility:analysis", ...projectPaneIDs] });
}

async function openSupplementalResearchConversation(conversationID) {
  const requestIdentity = captureAccountRequest();
  const normalizedConversationID = String(conversationID || "").trim();
  if (!normalizedConversationID) return null;
  if (normalizedConversationID === state.researchConversationID) {
    scrollPaneIntoView(paneIDForResearchConversation(normalizedConversationID));
    return activeResearchConversation;
  }
  let conversation;
  try {
    conversation = await fetchAuthoritativeResearchConversation(normalizedConversationID);
  } catch (error) {
    if (!isCurrentAccountRequest(requestIdentity)) return null;
    await showWebNotice("Could not open Research", error.message || "The conversation could not be loaded.");
    return null;
  }
  if (!isCurrentAccountRequest(requestIdentity)) return null;
  supplementalResearchConversations.set(normalizedConversationID, conversation);
  if (!supplementalResearchConversationIDs.includes(normalizedConversationID)) {
    supplementalResearchConversationIDs.push(normalizedConversationID);
  }
  restoreAssistantConversationOwners();
  const paneID = paneIDForResearchConversation(normalizedConversationID);
  state.paneWeights[paneID] ||= defaultPaneWidthForID(paneID);
  state.paneOrder = (state.paneOrder || []).filter((id) => id !== paneID);
  const openConversationIDs = openResearchConversationPaneIDs();
  const lastConversationIndex = state.paneOrder.reduce((last, id, index) =>
    openConversationIDs.includes(id) ? index : last, -1
  );
  state.paneOrder.splice(lastConversationIndex === -1 ? state.paneOrder.length : lastConversationIndex + 1, 0, paneID);
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
  if (!isCurrentAccountRequest(requestIdentity)) return null;
  scrollPaneIntoView(paneID);
  return conversation;
}

function researchAssistantContentIdentity(instance = null) {
  return JSON.stringify(instance
    ? [instance.id, instance.key, instance.projectID || "", instance.conversationID || ""]
    : ["analysis", state.researchConversationID || "", researchHistoryShowing, researchConversationPaneOpened]);
}

async function refreshResearchConversationInPlace(paneID, conversationID, instance = null) {
  const panel = track.querySelector(`.assistant-workspace[data-pane-id="${CSS.escape(paneID)}"]`);
  const body = panel?.querySelector(":scope > .assistant-body");
  if (!body || panel.dataset.workspacePaneLoading || !hasCapability("research")) return "unavailable";
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const workflowGeneration = state.workflowNavigationGeneration || 0;
  const generation = (panel._researchConversationRefreshGeneration || 0) + 1;
  panel._researchConversationRefreshGeneration = generation;
  const current = () => panel.isConnected && panel.parentNode === track &&
    isCurrentAccountRequest(identity) && workspaceID === activeWorkspaceID &&
    workflowGeneration === (state.workflowNavigationGeneration || 0) &&
    generation === panel._researchConversationRefreshGeneration &&
    !researchDraftPaneIDs.has(paneID) && hasCapability("research") &&
    conversationID === (instance
      ? (state.utilityInstances || []).find(item => item.key === "analysis" && item.id === instance.id)?.conversationID
      : state.researchConversationID);
  const conversation = await renderResearchConversation(conversationID, {
    embedded: true, supplemental: Boolean(instance), ownerInstance: instance, paneID
  });
  if (!current()) return "stale";
  // Publish a complete conversation in one swap; history, filters and focus stay mounted.
  body.replaceChildren(conversation);
  body.hidden = false;
  panel.classList.remove("has-research-composer", "is-new-research-chat", "is-history-only");
  panel.classList.add("has-inline-conversation");
  applyPaneWeight(panel, paneID);
  notifyWorkspaceLayoutChange();
  panel.dataset.workspacePaneIdentity = researchAssistantContentIdentity(instance);
  panel.querySelectorAll(".assistant-history-rail .research-conversation-row").forEach(row => {
    const selected = row.dataset.conversationId === conversationID;
    row.classList.toggle("is-active", selected);
    const button = row.querySelector(".research-conversation-open");
    if (selected) button?.setAttribute("aria-current", "true");
    else button?.removeAttribute("aria-current");
  });
  return "updated";
}

async function openResearchConversation(conversationID, options = {}) {
  const normalizedConversationID = String(conversationID || "").trim();
  if (!normalizedConversationID) return null;
  const workflowGeneration = state.workflowNavigationGeneration || 0;
  const workflowIsCurrent = () => workflowGeneration === (state.workflowNavigationGeneration || 0);
  researchDraftPaneIDs.delete(options.instance ? paneIDForUtilityInstance(options.instance) : "utility:analysis");
  if (options.instance) {
    const instanceID = options.instance.id;
    const workspaceID = activeWorkspaceID;
    const identity = captureAccountRequest();
    const attemptKey = `${workspaceID}:${instanceID}`;
    const attempt = {};
    researchConversationOpeningAttempts.set(attemptKey, attempt);
    const conversation = await fetchAuthoritativeResearchConversation(normalizedConversationID);
    if (!workflowIsCurrent() || workspaceID !== activeWorkspaceID || !isCurrentAccountRequest(identity) ||
        researchDraftPaneIDs.has(paneIDForUtilityInstance(options.instance)) ||
        researchConversationOpeningAttempts.get(attemptKey) !== attempt) return null;
    const instance = (state.utilityInstances || []).find((item) => item.key === "analysis" && item.id === instanceID);
    if (!instance) return null;
    const previousConversationID = instance.conversationID;
    if (instance.conversationID && instance.draft) researchNewChatDrafts.set(`followup:${instance.conversationID}`, instance.draft);
    instance.draft = researchNewChatDrafts.get(`followup:${normalizedConversationID}`) || "";
    instance.conversationID = normalizedConversationID;
    instance.historyShowing = false;
    // Replacing this column must not turn its former chat into a standalone
    // column. Keep it registered only when another visible owner still uses it.
    if (previousConversationID && previousConversationID !== normalizedConversationID &&
        !(researchConversationPaneIsOpen() && previousConversationID === state.researchConversationID) &&
        !(state.utilityInstances || []).some(item => item.key === "analysis" && item.conversationID === previousConversationID)) {
      const previousIndex = supplementalResearchConversationIDs.indexOf(previousConversationID);
      if (previousIndex !== -1) supplementalResearchConversationIDs.splice(previousIndex, 1);
      supplementalResearchConversations.delete(previousConversationID);
      const previousPaneID = `research:conversation:${previousConversationID}`;
      state.paneOrder = (state.paneOrder || []).filter(id => id !== previousPaneID);
      delete state.paneWeights[previousPaneID];
    }
    supplementalResearchConversations.set(normalizedConversationID, conversation);
    if (!supplementalResearchConversationIDs.includes(normalizedConversationID)) supplementalResearchConversationIDs.push(normalizedConversationID);
    saveWorkspaceState();
    const paneID = paneIDForUtilityInstance(instance);
    const refreshed = await refreshResearchConversationInPlace(paneID, normalizedConversationID, instance);
    if (refreshed === "stale") return null;
    await transitionWorkspace("utility", { refreshPaneIDs: refreshed === "updated" ? [] : [paneID] });
    return conversation;
  }
  const showResearchList = options.showResearchList !== false;
  const researchListScrollTop = track.querySelector(
    '.workspace-panel[data-pane-id="utility:analysis"] .analysis-content'
  )?.scrollTop ?? 0;
  const openingAccount = activeAccount();
  const openingContext = {
    generation: ++researchOpenGeneration,
    accountUserID: openingAccount?.userID || "",
    sessionToken: openingAccount?.sessionToken || "",
    projectID: activeProjectIDForCodeQuestions(),
    conversationID: normalizedConversationID
  };
  let conversation = null;
  try {
    conversation = await fetchAuthoritativeResearchConversation(normalizedConversationID);
  } catch (error) {
    if (!workflowIsCurrent() || !researchOpenContextIsCurrent(openingContext)) return null;
    await showWebNotice("Could not open Research", error.message || "The conversation could not be loaded.");
    return null;
  }
  if (!workflowIsCurrent() || !researchOpenContextIsCurrent(openingContext) || researchDraftPaneIDs.has("utility:analysis")) return null;
  // Every explicit entry point (including Note references) must reveal the
  // conversation. Setting only its ID loads History but leaves the answer hidden.
  researchConversationPaneOpened = true;
  activeResearchConversation = conversation;
  researchHistoryShowing = false;
  const codeQuestionProjectID = openingContext.projectID;
  const linkedQuestionID = String(conversation.linkedCodeDecisionID || "").trim();
  const sameProject = Boolean(
    codeQuestionProjectID && conversation.primaryProjectID === codeQuestionProjectID
  );
  if (codeQuestionWorkspaceEnabled() && linkedQuestionID && sameProject) {
    await hydrateCodeQuestionList(codeQuestionProjectID, { force: true, render: false });
    if (!workflowIsCurrent() || !researchOpenContextIsCurrent(openingContext)) return null;
  }
  const linkedQuestion = questionsForActiveProject().find((item) => item.id === linkedQuestionID);
  const exactLinkedDecision = Boolean(
    linkedQuestionID && sameProject && linkedQuestion?.researchConversationID === normalizedConversationID
  );
  if (codeQuestionWorkspaceEnabled() && codeQuestionProjectID) {
    if (exactLinkedDecision) {
      dismissedLinkedResearchDecisionKeys.delete(
        linkedResearchDecisionDismissalKey(linkedQuestionID, codeQuestionProjectID)
      );
      setCodeQuestionWorkspaceState(
        openCodeDecisionSurface(codeQuestionWorkspaceState(), {
          projectID: codeQuestionProjectID,
          questionID: linkedQuestionID,
          questionText: conversation.starterQuestion || "",
          researchConversationID: normalizedConversationID,
          resumeResearch: true,
          preserveResearchIntent: true
        }),
        { activeProjectID: codeQuestionProjectID, syncDeepLink: true }
      );
    } else if (codeQuestionWorkspaceState().activeQuestionID) {
      // An unlinked or other-Project conversation may still be opened, but it
      // must not appear to belong to the Code Decision currently on screen.
      setCodeQuestionWorkspaceState(
        switchCodeQuestionProject(codeQuestionWorkspaceState(), codeQuestionProjectID),
        { activeProjectID: codeQuestionProjectID, syncDeepLink: true }
      );
    }
  }
  const previousConversationPaneID = "utility:analysis";
  const previousConversationWidth = previousConversationPaneID
    ? state.paneWeights[previousConversationPaneID]
    : null;
  state.utilities.analysis = showResearchList;
  state.researchConversationID = normalizedConversationID;
  if (showResearchList) {
    state.paneWeights["utility:analysis"] ||= defaultPaneWidthForID("utility:analysis");
    if (options.anchorPaneID) {
      placePaneAfter(options.anchorPaneID, "utility:analysis");
    }
  }
  const conversationPaneID = "utility:analysis";
  if (previousConversationPaneID && previousConversationPaneID !== conversationPaneID) {
    delete state.paneWeights[previousConversationPaneID];
  }
  state.paneWeights[conversationPaneID] = Number.isFinite(Number(previousConversationWidth))
    ? Number(previousConversationWidth)
    : defaultPaneWidthForID(conversationPaneID);
  appendPaneIfMissing(conversationPaneID);
  saveWorkspaceState();
  const projectPaneIDs = openProjectDetails().map((detail) => paneIDForProjectDetail(detail));
  const refreshed = await refreshResearchConversationInPlace(conversationPaneID, normalizedConversationID);
  if (refreshed === "stale") return null;
  await transitionWorkspace("utility", {
    refreshPaneIDs: [
      ...(refreshed === "updated" ? [] : [conversationPaneID]),
      ...projectPaneIDs
    ]
  });
  const refreshedResearchList = track.querySelector(
    '.workspace-panel[data-pane-id="utility:analysis"] .analysis-content'
  );
  if (showResearchList && refreshedResearchList) {
    refreshedResearchList.scrollTop = Math.min(
      researchListScrollTop,
      Math.max(0, refreshedResearchList.scrollHeight - refreshedResearchList.clientHeight)
    );
  }
  if (!workflowIsCurrent() || !researchOpenContextIsCurrent(openingContext, { requireConversationID: true })) return null;
  scrollPaneIntoView(conversationPaneID);
  requestAnimationFrame(() => {
    if (!workflowIsCurrent() || !researchOpenContextIsCurrent(openingContext, { requireConversationID: true })) return;
    const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(conversationPaneID)}"]`);
    const focusTarget = pane?.querySelector(".research-question-input:not(:disabled), .panel-title");
    focusTarget?.focus({ preventScroll: true });
  });
  return conversation;
}

function researchRelativeDate(value) {
  const timestamp = Date.parse(value);
  if (!Number.isFinite(timestamp)) return "";
  return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(new Date(timestamp));
}

function researchConversationDate(value) {
  const timestamp = Date.parse(value);
  if (!Number.isFinite(timestamp)) return "";
  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric"
  }).format(new Date(timestamp));
}

function researchHistoryDayIndex(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (!Number.isFinite(date.getTime())) return null;
  return Math.floor(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / 86_400_000);
}

function researchConversationHistoryGroups(conversations = [], now = new Date()) {
  const todayIndex = researchHistoryDayIndex(now);
  const currentYear = now.getFullYear();
  const monthFormatter = new Intl.DateTimeFormat(undefined, { month: "long", year: "numeric" });
  const groups = new Map();
  const orderedConversations = [...conversations].sort((left, right) =>
    String(right.createdAt || "").localeCompare(String(left.createdAt || ""))
  );
  const drafts = [];
  orderedConversations.forEach((conversation) => {
    // Group by known submission count, never infer that local text/evidence is empty.
    if (typeof conversation.messageCount === "number" && conversation.messageCount === 0) {
      drafts.push(conversation);
      return;
    }
    const created = new Date(conversation.createdAt);
    const createdDayIndex = researchHistoryDayIndex(created);
    const ageInDays = todayIndex === null || createdDayIndex === null
      ? Number.POSITIVE_INFINITY
      : Math.max(0, todayIndex - createdDayIndex);
    let id;
    let label;
    let defaultExpanded = false;
    if (ageInDays < 7) {
      id = "last-7-days";
      label = "7 days";
      defaultExpanded = true;
    } else if (ageInDays < 14) {
      id = "previous-7-days";
      label = "Previous 7 days";
    } else if (ageInDays < 30) {
      id = "previous-30-days";
      label = "Previous 30 days";
    } else if (Number.isFinite(created.getTime()) && created.getFullYear() === currentYear) {
      id = `month-${created.getFullYear()}-${String(created.getMonth() + 1).padStart(2, "0")}`;
      label = monthFormatter.format(created);
    } else if (Number.isFinite(created.getTime())) {
      id = `year-${created.getFullYear()}`;
      label = String(created.getFullYear());
    } else {
      id = "older";
      label = "Older";
    }
    if (!groups.has(id)) groups.set(id, { id, label, defaultExpanded, conversations: [] });
    groups.get(id).conversations.push(conversation);
  });
  const result = Array.from(groups.values());
  if (drafts.length) result.push({ id: "drafts", label: "Drafts", defaultExpanded: true, collapsible: false, conversations: drafts });
  return result;
}

function researchProjects() {
  return activeProjectRecords(currentContentSummary().projects || []);
}

function researchProjectID(project) {
  return project ? projectDetailKey(project) : "";
}

function researchProjectName(projectID) {
  const project = visibleProjectRecords(currentContentSummary().projects || [])
    .find((item) => researchProjectID(item) === String(projectID || ""));
  return project ? readableProjectName(project) : "Unassigned";
}

function applyProjectDerivedPaneTheme(panel, projectID) {
  const normalizedProjectID = String(projectID || "");
  if (!normalizedProjectID) return false;
  const project = visibleProjectRecords(currentContentSummary().projects || [])
    .find((item) => researchProjectID(item) === normalizedProjectID);
  if (!project) return false;
  panel.classList.add("project-derived-panel");
  panel.dataset.projectId = normalizedProjectID;
  panel.style.setProperty("--project-color", projectColor(project));
  return true;
}

function preferredResearchProjectID(conversation = activeResearchConversation) {
  if (workspaceProject()) return projectDetailKey(workspaceProject());
  if (conversation?.primaryProjectID) return conversation.primaryProjectID;
  const projects = researchProjects();
  const openProjectIDs = openProjectDetails().map((detail) => projectDetailKey(detail));
  return openProjectIDs.find((projectID) =>
    projects.some((project) => researchProjectID(project) === projectID)
  ) || "";
}

function selectedOpenProjectID() {
  const projects = researchProjects();
  return openProjectDetails().map((detail) => projectDetailKey(detail)).find((projectID) =>
    projects.some((project) => researchProjectID(project) === projectID)
  ) || "";
}

function researchProjectChoices({
  value = "",
  includeUnassigned = true,
  unassignedLabel = "Unassigned — no Project context"
} = {}) {
  const choices = [];
  if (includeUnassigned) {
    choices.push({ value: "", label: unassignedLabel, category: "unassigned" });
  }
  const projects = activeProjectRecords(currentContentSummary().projects || []);
  projects.forEach((project) => {
    choices.push({
      value: researchProjectID(project),
      label: readableProjectName(project),
      category: "project"
    });
  });
  if (value && !choices.some((choice) => choice.value === value)) {
    const historicalProject = visibleProjectRecords(currentContentSummary().projects || [])
      .find((project) => folderIsProject(project) && researchProjectID(project) === value);
    if (historicalProject) {
      choices.push({
        value,
        label: `${readableProjectName(historicalProject)} (Archived)`,
        category: "project"
      });
    }
  }
  return choices;
}

function createResearchProjectSelect({
  value = "",
  includeUnassigned = true,
  unassignedLabel = "Unassigned — no Project context",
  ariaLabel = "Project"
} = {}) {
  const select = document.createElement("select");
  select.className = "research-project-select";
  select.setAttribute("aria-label", ariaLabel);
  const activeProject = workspaceProject();
  const choices = activeProject
    ? [{ value: projectDetailKey(activeProject), label: activeProject.name }]
    : researchProjectChoices({ value, includeUnassigned, unassignedLabel });
  if (activeProject) value = projectDetailKey(activeProject);
  choices.forEach((choice) => {
    const option = document.createElement("option");
    option.value = choice.value;
    option.textContent = choice.label;
    select.append(option);
  });
  select.value = value && choices.some((choice) => choice.value === value) ? value : "";
  return select;
}

async function assignResearchConversationProject(conversation, targetProjectID, options = {}) {
  try {
    return await postResearch("/research/conversations/assign-project", {
      conversationID: conversation.id,
      projectID: targetProjectID
    });
  } catch (error) {
    if (error.payload?.code !== "RESEARCH_PROJECT_REVIEW_REQUIRED") throw error;
    const currentProjectName = conversation.primaryProjectID
      ? researchProjectName(conversation.primaryProjectID)
      : "its current Project";
    const targetProjectName = targetProjectID
      ? researchProjectName(targetProjectID)
      : "";
    const confirmed = await confirmWebWarning(
      targetProjectID
        ? `Move this conversation to ${targetProjectName}?`
        : `Remove this conversation from ${currentProjectName}?`,
      targetProjectID
        ? `The entire conversation will move from ${currentProjectName} to ${targetProjectName}. Its existing answers and citations will not change. Future questions will use the current Project facts from ${targetProjectName}.`
        : `The conversation will no longer appear in ${currentProjectName}. Its existing answers and citations will not change, but it will not use or add Project-specific facts until you assign it to another Project.`,
      {
        confirmLabel: targetProjectID ? "Move conversation" : "Remove from Project",
        container: options.warningContainer
      }
    );
    if (!confirmed) return null;
    return postResearch("/research/conversations/assign-project", {
      conversationID: conversation.id,
      projectID: targetProjectID,
      confirmMove: true
    });
  }
}

async function deleteResearchConversationFromList(conversation, button) {
  const confirmed = await confirmWebWarning(
    "Delete research conversation?",
    `“${conversation.title}” and its private message history will be permanently deleted. ${conversation.linkedCodeDecisionID ? "The linked analysis record, approved evidence, and conclusions will be preserved." : ""}`,
    { confirmLabel: "Delete" }
  );
  if (!confirmed) return;
  button.disabled = true;
  try {
    await postResearch("/research/conversations/delete", { conversationID: conversation.id });
    activeResearchProgress.get(conversation.id)?.controller?.abort();
    activeResearchProgress.delete(conversation.id);
    removeResearchRequestRecovery(localStorage, {
      accountUserID: activeAccount()?.userID || "",
      conversationID: conversation.id
    });
    if (state.researchConversationID === conversation.id) {
      researchOpenGeneration += 1;
      state.researchConversationID = "";
      activeResearchConversation = null;
    }
    if (state.researchEvidenceSplitRatios) {
      delete state.researchEvidenceSplitRatios[conversation.id];
    }
    await refreshResearchConversationList();
    if (conversation.linkedCodeDecisionID && conversation.primaryProjectID) {
      await Promise.all([
        hydrateCodeQuestionList(conversation.primaryProjectID, { force: true, render: false }),
        hydrateCodeQuestionState(
          conversation.primaryProjectID,
          conversation.linkedCodeDecisionID,
          { force: true, render: false }
        )
      ]);
    }
    await refreshProjectSourceConsumers([conversation.primaryProjectID], {
      refreshNotebookFoundation: true
    });
    saveWorkspaceState();
    const projectPaneIDs = openProjectDetails().map((detail) => paneIDForProjectDetail(detail));
    await transitionWorkspace("utility", {
      refreshPaneIDs: ["utility:analysis", ...projectPaneIDs]
    });
  } catch (error) {
    button.disabled = false;
    await showWebNotice("Conversation not deleted", error.message);
  }
}

async function clearResearchConversationHistory(button, selectedConversations = researchConversationList, options = {}) {
  const conversations = [...selectedConversations];
  if (!conversations.length) return;
  const confirmed = await confirmWebWarning(
    "Remove selected Research history?",
    `${conversations.length} selected ${conversations.length === 1 ? "conversation" : "conversations"} will disappear from Research history and the Project’s Saved conversation list. Unassigned chats will be deleted. Project-linked conversations, saved Research answers, and professional analysis records will be preserved.`,
    {
      confirmLabel: conversations.length === 1 ? "Remove conversation" : `Remove ${conversations.length}`,
      container: button.closest(".workspace-panel")
    }
  );
  if (!confirmed) return false;

  button.disabled = true;
  button.setAttribute("aria-busy", "true");
  const removalAnimation = animateResearchConversationRows(options.rows || []);
  try {
    await Promise.all([
      postResearch("/research/conversations/clear-history", {
        conversationIDs: conversations.map((conversation) => conversation.id)
      }),
      removalAnimation
    ]);
    const clearedIDs = new Set(conversations.map((conversation) => conversation.id));
    clearedIDs.forEach((conversationID) => {
      activeResearchProgress.get(conversationID)?.controller?.abort();
      activeResearchProgress.delete(conversationID);
      removeResearchRequestRecovery(localStorage, {
        accountUserID: activeAccount()?.userID || "",
        conversationID
      });
    });
    if (clearedIDs.has(String(state.researchConversationID || ""))) {
      researchOpenGeneration += 1;
      state.researchConversationID = "";
      activeResearchConversation = null;
    }
    if (state.researchEvidenceSplitRatios) {
      clearedIDs.forEach((conversationID) => delete state.researchEvidenceSplitRatios[conversationID]);
    }
    await refreshResearchConversationList();
    saveWorkspaceState();
    if (typeof options.onCleared === "function") options.onCleared();
    await refreshResearchProjectAssignmentConsumers(conversations.map(conversation => conversation.primaryProjectID));
    return true;
  } catch (error) {
    button.disabled = false;
    button.removeAttribute("aria-busy");
    await transitionWorkspace("utility", { refreshPaneIDs: ["utility:analysis"] });
    await showWebNotice("Research history not cleared", error.message, {
      container: button.closest(".workspace-panel")
    });
    return false;
  }
}

async function animateResearchConversationRows(rows) {
  const connectedRows = [...rows].filter((row) => row?.isConnected);
  if (!connectedRows.length) return;
  const panel = connectedRows[0].closest(".research-list-panel");
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reducedMotion || connectedRows.some((row) => typeof row.animate !== "function")) {
    connectedRows.forEach((row) => row.remove());
  } else {
    const animations = connectedRows.map((row) => {
      const height = row.getBoundingClientRect().height;
      row.style.overflow = "hidden";
      row.classList.add("is-removing");
      return row.animate([
        { height: `${height}px`, opacity: 1, transform: "translateY(0)" },
        { height: "0px", opacity: 0, transform: "translateY(-6px)" }
      ], {
        duration: 240,
        easing: "cubic-bezier(0.22, 1, 0.36, 1)",
        fill: "forwards"
      }).finished.catch(() => {});
    });
    await Promise.all(animations);
    connectedRows.forEach((row) => row.remove());
  }
  panel?.querySelectorAll(".research-history-group").forEach((group) => {
    if (!group.querySelector(".research-conversation-row")) group.remove();
  });
}

function evidenceCandidateCitation(candidate) {
  return `${candidate.codePrefix || "BC"} § ${candidate.sectionNumber || candidate.sectionID}`;
}

function formattedByteLength(value) {
  const bytes = Number(value || 0);
  if (!Number.isFinite(bytes) || bytes <= 0) return "size unavailable";
  if (bytes >= 1_000_000) return `${(bytes / 1_000_000).toFixed(1)} MB`;
  if (bytes >= 1_000) return `${Math.round(bytes / 1_000).toLocaleString()} KB`;
  return `${bytes.toLocaleString()} bytes`;
}

function evidenceCandidateVisualRequirement(candidate) {
  return candidate.sourceReviewRequirements?.find((item) => item.kind === "visual-source") || null;
}

function evidenceCandidatePreparationReady(candidate) {
  const requirements = candidate.sourceReviewRequirements || [];
  if (requirements.some((item) => item.kind !== "visual-source")) return false;
  const visualRequirement = evidenceCandidateVisualRequirement(candidate);
  if (!visualRequirement) return candidate.preparationEligible !== false;
  const selected = Array.isArray(candidate.selectedVisualSourceIDs)
    ? candidate.selectedVisualSourceIDs
    : [];
  const maximumSelections = Number(visualRequirement.maximumSelections || 4);
  return (
    selected.length >= 1 &&
    selected.length <= maximumSelections &&
    candidate.visualReviewConfirmed === true
  );
}

function comparableCandidateExcerptCharacter(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u00AD\u200B-\u200D\uFEFF]/g, "")
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"');
}

function candidateExcerptTextMap(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const positions = [];
  let text = "";
  let node = walker.nextNode();
  while (node) {
    const value = String(node.nodeValue || "");
    if (text && !text.endsWith(" ") && value && !/^\s/.test(value)) {
      text += " ";
      positions.push({ node, start: 0, end: 0 });
    }
    for (let offset = 0; offset < value.length; offset += 1) {
      const character = comparableCandidateExcerptCharacter(value[offset]);
      for (const normalizedCharacter of character) {
        if (/\s/.test(normalizedCharacter)) {
          if (!text || text.endsWith(" ")) continue;
          text += " ";
        } else {
          text += normalizedCharacter;
        }
        positions.push({ node, start: offset, end: offset + 1 });
      }
    }
    node = walker.nextNode();
  }
  return { text: text.trim(), positions };
}

function formattedCandidatePlainText(value) {
  return String(value || "")
    .replace(/\s+(?=["“']?\([A-Za-z0-9]+\)\s)/g, "\n")
    .trim();
}

function renderEvidenceCandidateExcerpt(candidate) {
  const quote = document.createElement("blockquote");
  quote.className = "evidence-candidate-excerpt";
  if (!candidate.displayBlock?.html) {
    quote.textContent = formattedCandidatePlainText(candidate.selectedText);
    return quote;
  }
  const source = renderCodeBlock(candidate.displayBlock);
  const mapped = candidateExcerptTextMap(source);
  const target = comparableCandidateExcerptCharacter(candidate.selectedText)
    .replace(/\s+/g, " ")
    .trim();
  const start = mapped.text.indexOf(target);
  const startPosition = start >= 0 ? mapped.positions[start] : null;
  const endPosition = start >= 0 ? mapped.positions[start + target.length - 1] : null;
  if (!startPosition || !endPosition) {
    quote.textContent = formattedCandidatePlainText(candidate.selectedText);
    return quote;
  }
  const range = document.createRange();
  // Preserve the Reader's canonical markup without expanding the governed
  // candidate beyond its exact selectedText passage.
  range.setStart(startPosition.node, startPosition.start);
  range.setEnd(endPosition.node, endPosition.end);
  const content = document.createElement("div");
  content.className = "section-block section-html evidence-candidate-structured-excerpt";
  content.append(range.cloneContents());
  if (!content.querySelector("p, ul, ol, li, table, div, blockquote, br")) {
    quote.textContent = formattedCandidatePlainText(candidate.selectedText);
    return quote;
  }
  quote.append(content);
  return quote;
}

function rejectedResearchCandidateIDs(conversation = activeResearchConversation) {
  return new Set(
    (conversation?.candidateDispositions || [])
      .filter((item) => item.disposition === "rejected")
      .map((item) => String(item.candidateID || "").trim())
      .filter(Boolean)
  );
}

async function persistResearchCandidateDisposition(candidate, disposition, question) {
  const projectID = activeProjectIDForCodeQuestions();
  const questionID = String(codeQuestionWorkspaceState().activeQuestionID || "").trim();
  if (!projectID || !questionID) {
    throw new Error("Open a Project question before saving candidate review choices.");
  }
  let conversationID = String(state.researchConversationID || "").trim();
  if (!conversationID) {
    const conversation = await startLinkedResearchForCodeDecision(questionID, { open: false });
    conversationID = String(conversation?.id || "").trim();
  }
  if (!conversationID) throw new Error("Permitext could not open the linked Research conversation.");
  state.researchConversationID = conversationID;
  const dispositionAccount = activeAccount();
  const dispositionContext = {
    generation: researchOpenGeneration,
    accountUserID: dispositionAccount?.userID || "",
    sessionToken: dispositionAccount?.sessionToken || "",
    projectID,
    conversationID
  };
  const payload = await postResearch("/research/conversations/candidate-disposition", {
    conversationID,
    projectID,
    questionID,
    question,
    candidateID: candidate.id,
    disposition
  });
  if (
    !researchOpenContextIsCurrent(dispositionContext, { requireConversationID: true }) ||
    String(codeQuestionWorkspaceState().activeQuestionID || "").trim() !== questionID
  ) {
    throw codeQuestionContextChangedError();
  }
  activeResearchConversation = payload.conversation;
  return payload;
}

function renderEvidenceDiscovery(container) {
  if (
    !hasCapability("evidence-discovery") &&
    researchUsage?.evidenceDiscoveryEnabled !== true
  ) return;
  if (
    activeEvidenceDiscovery &&
    activeEvidenceDiscovery.accountUserID !== activeAccount()?.userID
  ) {
    activeEvidenceDiscovery = null;
  }

  const section = document.createElement("section");
  section.className = "evidence-discovery";
  const form = document.createElement("form");
  form.className = "evidence-discovery-form";
  const questionLabel = document.createElement("label");
  const question = document.createElement("textarea");
  question.rows = 4;
  question.maxLength = 2_000;
  question.setAttribute("aria-label", "Project question");
  question.placeholder = "Example: Can a six-story R-2 building use one exit stair?";
  const activeDecisionQuestionID = codeQuestionWorkspaceState().activeQuestionID;
  const activeDecisionQuestion = activeDecisionQuestionID
    ? getDefinitionForQuestion(activeDecisionQuestionID)?.questionText ||
      questionsForActiveProject().find((item) => item.id === activeDecisionQuestionID)?.title ||
      ""
    : "";
  const usesActiveDecisionQuestion = Boolean(activeDecisionQuestion.trim());
  question.value = activeDecisionQuestion || activeEvidenceDiscovery?.question || researchQuestionDraft;
  questionLabel.append(question);
  const controls = document.createElement("div");
  controls.className = "evidence-discovery-form-controls";
  const scopedProjectID = String(activeProjectIDForCodeQuestions() || "").trim();
  const projectSelect = createResearchProjectSelect({
    value: scopedProjectID || activeEvidenceDiscovery?.projectID || preferredResearchProjectID(),
    includeUnassigned: !scopedProjectID,
    unassignedLabel: "General",
    ariaLabel: "Project for candidate evidence"
  });
  const findButton = document.createElement("button");
  findButton.className = "evidence-discovery-find";
  findButton.type = "submit";
  findButton.textContent = "Search";
  findButton.disabled = question.value.trim().length < 3;
  if (!scopedProjectID) controls.append(projectSelect);
  controls.append(findButton);
  projectSelect.addEventListener("change", () => {
    if (activeEvidenceDiscovery) {
      activeEvidenceDiscovery.projectID = projectSelect.value;
    }
  });
  const formStatus = document.createElement("p");
  formStatus.className = "evidence-discovery-status";
  question.addEventListener("input", () => {
    findButton.disabled = question.value.trim().length < 3;
  });
  if (!usesActiveDecisionQuestion) form.append(questionLabel);
  form.append(controls, formStatus);

  const results = document.createElement("section");
  results.className = "evidence-discovery-results";

  const renderResults = () => {
    clear(results);
    const discovery = activeEvidenceDiscovery;
    if (!discovery?.response) return;
    const response = discovery.response;
    const candidates = response.candidates || [];
    const approved = candidates.filter((candidate) =>
      candidate.reviewState === "approved" &&
      evidenceCandidatePreparationReady(candidate)
    );
    const rejectedCount = candidates.filter((candidate) => candidate.reviewState === "rejected").length;
    const notReviewedCount = candidates.length - approved.length - rejectedCount;
    if (discovery.showRejected === true && rejectedCount === 0) discovery.showRejected = false;
    const availableCandidates = candidates.filter((candidate) => candidate.reviewState !== "rejected");
    const visibleCandidateCount = Math.min(
      Math.max(Number(discovery.visibleCandidateCount) || 3, 1),
      availableCandidates.length
    );
    discovery.visibleCandidateCount = visibleCandidateCount;
    const visibleCandidates = discovery.showRejected === true
      ? candidates.filter((candidate) => candidate.reviewState === "rejected")
      : availableCandidates.slice(0, visibleCandidateCount);
    const requestedCandidateIndex = visibleCandidates.findIndex((candidate) => candidate.id === discovery.activeCandidateID);
    const candidateIndex = requestedCandidateIndex === -1 ? 0 : requestedCandidateIndex;
    discovery.activeCandidateID = visibleCandidates[candidateIndex]?.id || "";
    const showCandidate = (nextIndex, options = {}) => {
      if (!visibleCandidates.length) return;
      const boundedIndex = Math.min(Math.max(0, nextIndex), visibleCandidates.length - 1);
      discovery.activeCandidateID = visibleCandidates[boundedIndex].id;
      renderResults();
      if (options.focus !== false) {
        requestAnimationFrame(() => results.querySelector(".evidence-candidate-card")?.focus({ preventScroll: true }));
      }
    };
    const advanceAfterDisposition = () => {
      const nextUnreviewedIndex = visibleCandidates.findIndex((candidate, index) =>
        index > candidateIndex && !["approved", "rejected"].includes(candidate.reviewState)
      );
      showCandidate(nextUnreviewedIndex === -1 ? Math.min(candidateIndex + 1, visibleCandidates.length - 1) : nextUnreviewedIndex);
    };
    const summary = document.createElement("div");
    summary.className = "evidence-discovery-summary";
    const summaryText = document.createElement("strong");
    summaryText.textContent = visibleCandidates.length
      ? `Candidate ${candidateIndex + 1} of ${visibleCandidates.length}`
      : "No review candidates";
    const progress = document.createElement("span");
    progress.setAttribute("role", "status");
    progress.setAttribute("aria-live", "polite");
    progress.textContent = discovery.showRejected === true
      ? `Reviewing ${visibleCandidates.length} dismissed suggestions · ${approved.length} selected · ${notReviewedCount} not reviewed`
      : `Showing ${visibleCandidateCount} of ${availableCandidates.length} available candidates from ${candidates.length} ranked results · ${approved.length} selected · ${rejectedCount} dismissed · ${notReviewedCount} not reviewed`;
    const summaryActions = document.createElement("div");
    summaryActions.className = "evidence-discovery-summary-actions";
    const findMore = document.createElement("button");
    findMore.type = "button";
    findMore.className = "evidence-candidate-find-more";
    const remainingCandidateCount = Math.max(0, availableCandidates.length - visibleCandidateCount);
    const nextCandidateBatchSize = Math.min(3, remainingCandidateCount);
    findMore.textContent = nextCandidateBatchSize ? `Find ${nextCandidateBatchSize} more` : "All candidates shown";
    findMore.disabled = remainingCandidateCount === 0;
    findMore.hidden = discovery.showRejected === true;
    findMore.addEventListener("click", () => {
      discovery.visibleCandidateCount = Math.min(availableCandidates.length, visibleCandidateCount + 3);
      renderResults();
      requestAnimationFrame(() => {
        results.querySelector(".evidence-candidate-card")?.focus({ preventScroll: true });
      });
    });
    const reviewRejected = document.createElement("button");
    reviewRejected.type = "button";
    reviewRejected.className = "evidence-candidate-review-rejected";
    reviewRejected.textContent = discovery.showRejected === true ? "Hide dismissed" : `Review dismissed (${rejectedCount})`;
    reviewRejected.hidden = rejectedCount === 0;
    reviewRejected.setAttribute("aria-pressed", String(discovery.showRejected === true));
    reviewRejected.addEventListener("click", () => {
      discovery.showRejected = discovery.showRejected !== true;
      if (discovery.showRejected) {
        discovery.activeCandidateID = candidates.find((candidate) => candidate.reviewState === "rejected")?.id || discovery.activeCandidateID;
      } else if (candidates.find((candidate) => candidate.id === discovery.activeCandidateID)?.reviewState === "rejected") {
        discovery.activeCandidateID = candidates.find((candidate) => candidate.reviewState !== "rejected")?.id || "";
      }
      renderResults();
      requestAnimationFrame(() => {
        results.querySelector(".evidence-candidate-card")?.focus({ preventScroll: true });
      });
    });
    const viewAll = document.createElement("button");
    viewAll.type = "button";
    viewAll.className = "evidence-candidate-view-all";
    viewAll.textContent = discovery.candidateNavigatorOpen ? "Hide list" : "View all";
    viewAll.setAttribute("aria-expanded", String(discovery.candidateNavigatorOpen === true));
    viewAll.disabled = candidates.length === 0;
    viewAll.addEventListener("click", () => {
      discovery.candidateNavigatorOpen = discovery.candidateNavigatorOpen !== true;
      renderResults();
    });
    summaryActions.append(viewAll, findMore, reviewRejected);
    summary.append(summaryText, progress, summaryActions);
    results.append(summary);

    if (response.outsideCurrentLibrary?.length) {
      const outside = document.createElement("aside");
      outside.className = "evidence-discovery-outside";
      const outsideHeading = document.createElement("strong");
      outsideHeading.textContent = "Outside Construction Code Research";
      const outsideList = document.createElement("ul");
      response.outsideCurrentLibrary.forEach((outsideItem) => {
        const item = document.createElement("li");
        const copy = document.createElement("span");
        copy.textContent = outsideItem.text;
        item.append(copy);
        if (outsideItem.sourceURL) {
          const link = document.createElement("a");
          link.href = outsideItem.sourceURL;
          link.target = "_blank";
          link.rel = "noopener noreferrer";
          link.textContent = `Open ${outsideItem.sourceName || outsideItem.label || "official source"}`;
          item.append(link);
        }
        outsideList.append(item);
      });
      outside.append(outsideHeading, outsideList);
      results.append(outside);
    }

    if (discovery.candidateNavigatorOpen && candidates.length) {
      const navigator = document.createElement("nav");
      navigator.className = "evidence-candidate-navigator";
      navigator.setAttribute("aria-label", "Review candidates");
      visibleCandidates.forEach((candidate, index) => {
        const option = document.createElement("button");
        option.type = "button";
        option.className = "evidence-candidate-navigator-item";
        option.classList.toggle("is-active", index === candidateIndex);
        option.classList.toggle("is-selected", candidate.reviewState === "approved");
        option.classList.toggle("is-rejected", candidate.reviewState === "rejected");
        option.setAttribute("aria-current", index === candidateIndex ? "true" : "false");
        option.innerHTML = `
          <span>${index + 1}</span>
          <strong>${escapeHTML(evidenceCandidateCitation(candidate))}</strong>
          <small>${escapeHTML(candidate.reviewState === "approved" ? "Selected" : candidate.reviewState === "rejected" ? "Dismissed" : "Not reviewed")}</small>`;
        option.addEventListener("click", () => {
          discovery.candidateNavigatorOpen = false;
          showCandidate(index);
        });
        navigator.append(option);
      });
      results.append(navigator);
    }

    const tray = document.createElement("section");
    tray.className = "evidence-candidate-tray";
    const candidate = visibleCandidates[candidateIndex];
    if (candidate) {
      const reviewState = candidate.reviewState || "candidate";
      const card = document.createElement("article");
      card.className = `evidence-candidate-card is-active-review is-${reviewState}`;
      card.tabIndex = -1;
      card.addEventListener("keydown", (event) => {
        if (event.target !== card || !["ArrowLeft", "ArrowRight"].includes(event.key)) return;
        event.preventDefault();
        showCandidate(candidateIndex + (event.key === "ArrowRight" ? 1 : -1));
      });
      const cardHeader = document.createElement("div");
      cardHeader.className = "evidence-candidate-heading";
      const citationWrap = document.createElement("div");
      const rank = document.createElement("span");
      rank.className = "evidence-candidate-rank";
      rank.textContent = `#${candidate.rank}`;
      const citation = document.createElement("strong");
      citation.id = `evidence-candidate-${candidate.id}`;
      citation.textContent = evidenceCandidateCitation(candidate);
      card.setAttribute("aria-labelledby", citation.id);
      const title = document.createElement("p");
      title.textContent = candidate.title || "Enacted section";
      citationWrap.append(citation, title);
      const stateBadge = document.createElement("span");
      stateBadge.className = "evidence-candidate-state";
      const visualRequirement = evidenceCandidateVisualRequirement(candidate);
      const preparationReady = evidenceCandidatePreparationReady(candidate);
      stateBadge.textContent = visualRequirement && preparationReady
        ? reviewState === "approved"
          ? "Visual evidence reviewed · selected"
          : "Visual evidence reviewed · ready to select"
        : visualRequirement
          ? "Select and confirm applicable visual evidence"
          : candidate.preparationEligible === false
            ? "Additional source review required"
            : reviewState === "approved"
              ? "Selected for Research"
              : reviewState === "rejected"
                ? "Dismissed"
                : "";
      cardHeader.append(rank, citationWrap);
      if (stateBadge.textContent) cardHeader.append(stateBadge);
      const quote = renderEvidenceCandidateExcerpt(candidate);
      const sourceRequirements = document.createElement("div");
      sourceRequirements.className = "evidence-candidate-source-requirements";
      if (candidate.sourceReviewRequirements?.length) {
        const sourceRequirementsHeading = document.createElement("strong");
        sourceRequirementsHeading.textContent = "Cannot prepare from text alone";
        const sourceRequirementsList = document.createElement("ul");
        candidate.sourceReviewRequirements.forEach((requirement) => {
          const item = document.createElement("li");
          item.textContent = requirement.text;
          sourceRequirementsList.append(item);
        });
        sourceRequirements.append(sourceRequirementsHeading, sourceRequirementsList);
      }
      const structuredSources = document.createElement("div");
      structuredSources.className = "evidence-candidate-structured-sources";
      if (candidate.richSources?.length) {
        const structuredSourcesHeading = document.createElement("strong");
        structuredSourcesHeading.textContent = "Complete structured source included";
        const structuredSourcesList = document.createElement("ul");
        candidate.richSources.forEach((source) => {
          const item = document.createElement("li");
          item.textContent = `${source.reference} · ${Number(source.rowCount || 0).toLocaleString()} structured rows · integrity ${String(source.contentHash || "").slice(0, 12)}`;
          structuredSourcesList.append(item);
        });
        structuredSources.append(structuredSourcesHeading, structuredSourcesList);
      }
      const visualSources = document.createElement("div");
      visualSources.className = "evidence-candidate-visual-sources";
      if (candidate.visualSources?.length) {
        const visualSourcesHeading = document.createElement("strong");
        visualSourcesHeading.textContent = "Review official visual evidence";
        const visualRequirementCount = visualRequirement?.count;
        const maximumSelections = Number(visualRequirement?.maximumSelections || 4);
        const selectedVisualSourceIDs = new Set(candidate.selectedVisualSourceIDs || []);
        const visualSourcesSummary = document.createElement("p");
        visualSourcesSummary.textContent = `${candidate.visualSources.length}${visualRequirementCount ? ` of ${visualRequirementCount}` : ""} official assets verified by content hash. Select only the applicable image${maximumSelections === 1 ? "" : "s"} (up to ${maximumSelections}); Permitext will preserve the selected bytes with the Research record.`;
        const visualSourcesDetails = document.createElement("details");
        visualSourcesDetails.open = candidate.visualReviewOpen === true;
        visualSourcesDetails.addEventListener("toggle", () => {
          candidate.visualReviewOpen = visualSourcesDetails.open;
        });
        const visualSourcesToggle = document.createElement("summary");
        visualSourcesToggle.textContent = `Review and select official images · ${selectedVisualSourceIDs.size} selected`;
        const visualSourcesGallery = document.createElement("div");
        visualSourcesGallery.className = "evidence-visual-source-gallery";
        candidate.visualSources.forEach((source, sourceIndex) => {
          const item = document.createElement("label");
          item.className = "evidence-visual-source-option";
          item.classList.toggle("is-selected", selectedVisualSourceIDs.has(source.id));
          const checkbox = document.createElement("input");
          checkbox.type = "checkbox";
          checkbox.checked = selectedVisualSourceIDs.has(source.id);
          checkbox.disabled = !checkbox.checked && selectedVisualSourceIDs.size >= maximumSelections;
          checkbox.setAttribute(
            "aria-label",
            `Select official visual source ${source.assetName}`
          );
          checkbox.addEventListener("change", () => {
            const nextSelection = new Set(candidate.selectedVisualSourceIDs || []);
            if (checkbox.checked) {
              if (nextSelection.size >= maximumSelections) return;
              nextSelection.add(source.id);
            } else {
              nextSelection.delete(source.id);
            }
            candidate.selectedVisualSourceIDs = Array.from(nextSelection);
            candidate.visualReviewConfirmed = false;
            candidate.visualReviewOpen = true;
            if (candidate.reviewState === "approved") candidate.reviewState = "candidate";
            renderResults();
          });
          const image = document.createElement("img");
          image.src = source.assetURL;
          image.alt = `Official visual source ${sourceIndex + 1}: ${source.assetName}`;
          image.loading = "lazy";
          image.decoding = "async";
          const itemCopy = document.createElement("span");
          itemCopy.className = "evidence-visual-source-copy";
          const itemName = document.createElement("strong");
          itemName.textContent = `Official image ${sourceIndex + 1}`;
          const metadata = document.createElement("span");
          metadata.textContent = `${source.assetName} · ${formattedByteLength(source.byteLength)} · integrity ${String(source.contentHash || "").slice(0, 12)}`;
          const link = document.createElement("a");
          link.href = source.assetURL;
          link.target = "_blank";
          link.rel = "noopener noreferrer";
          link.textContent = "Open full-size official image";
          link.addEventListener("click", (event) => event.stopPropagation());
          itemCopy.append(itemName, metadata, link);
          item.append(checkbox, image, itemCopy);
          visualSourcesGallery.append(item);
        });
        const visualReviewConfirmation = document.createElement("label");
        visualReviewConfirmation.className = "evidence-visual-review-confirmation";
        const visualReviewCheckbox = document.createElement("input");
        visualReviewCheckbox.type = "checkbox";
        visualReviewCheckbox.checked = candidate.visualReviewConfirmed === true;
        visualReviewCheckbox.disabled = selectedVisualSourceIDs.size === 0;
        const visualReviewCopy = document.createElement("span");
        visualReviewCopy.textContent = selectedVisualSourceIDs.size
          ? `I reviewed the ${selectedVisualSourceIDs.size} selected official ${selectedVisualSourceIDs.size === 1 ? "image" : "images"} and want ${selectedVisualSourceIDs.size === 1 ? "it" : "them"} attached as evidence.`
          : "Select at least one applicable official image before confirming review.";
        visualReviewCheckbox.addEventListener("change", () => {
          candidate.visualReviewConfirmed = visualReviewCheckbox.checked;
          candidate.visualReviewOpen = true;
          if (candidate.reviewState === "approved") candidate.reviewState = "candidate";
          renderResults();
        });
        visualReviewConfirmation.append(visualReviewCheckbox, visualReviewCopy);
        const visualProviderDisclosure = document.createElement("p");
        visualProviderDisclosure.className = "evidence-visual-provider-disclosure";
        visualProviderDisclosure.textContent = "Selected official images are sent to OpenAI for analysis. Private notes are not included.";
        visualSourcesDetails.append(
          visualSourcesToggle,
          visualSourcesGallery,
          visualReviewConfirmation,
          visualProviderDisclosure
        );
        visualSources.append(
          visualSourcesHeading,
          visualSourcesSummary,
          visualSourcesDetails
        );
      }
      const actions = document.createElement("div");
      actions.className = "evidence-candidate-actions";
      const approveButton = document.createElement("button");
      approveButton.type = "button";
      approveButton.className = "evidence-candidate-approve";
      approveButton.textContent = reviewState === "approved" ? "Selected for Research" : "Use in Research";
      approveButton.setAttribute("aria-pressed", String(reviewState === "approved"));
      approveButton.disabled = !preparationReady;
      if (!preparationReady) {
        approveButton.title = visualRequirement
          ? "Select the applicable official visual evidence and confirm your review first."
          : "Open the source and review its complete supporting material before using it as evidence.";
      }
      approveButton.addEventListener("click", async () => {
        if (!evidenceCandidatePreparationReady(candidate)) return;
        if (reviewState === "approved") {
          candidate.reviewState = "candidate";
          renderResults();
          return;
        }
        approveButton.disabled = true;
        rejectButton.disabled = true;
        try {
          if (reviewState === "rejected") {
            await persistResearchCandidateDisposition(candidate, "restored", discovery.question);
          }
          candidate.reviewState = "approved";
          advanceAfterDisposition();
        } catch (error) {
          formStatus.textContent = error.message;
          approveButton.disabled = false;
          rejectButton.disabled = false;
        }
      });
      const rejectButton = document.createElement("button");
      rejectButton.type = "button";
      rejectButton.className = "evidence-candidate-reject";
      rejectButton.textContent = reviewState === "rejected" ? "Restore" : "Dismiss";
      rejectButton.title = reviewState === "rejected"
        ? "Restore this private Research suggestion"
        : "Dismiss this suggestion from this private Research conversation";
      rejectButton.setAttribute("aria-pressed", String(reviewState === "rejected"));
      const candidateDispositionEnabled = Boolean(
        activeProjectIDForCodeQuestions() &&
        String(codeQuestionWorkspaceState().activeQuestionID || "").trim()
      );
      rejectButton.disabled = !candidateDispositionEnabled;
      if (!candidateDispositionEnabled) {
        rejectButton.title = "Open Research from a Project question to save rejections.";
      }
      rejectButton.addEventListener("click", async () => {
        approveButton.disabled = true;
        rejectButton.disabled = true;
        try {
          const nextDisposition = reviewState === "rejected" ? "restored" : "rejected";
          await persistResearchCandidateDisposition(candidate, nextDisposition, discovery.question);
          candidate.reviewState = nextDisposition === "rejected" ? "rejected" : "candidate";
          if (nextDisposition === "rejected") advanceAfterDisposition();
          else {
            renderResults();
            requestAnimationFrame(() => {
              results.querySelector(".evidence-candidate-card")?.focus({ preventScroll: true });
            });
          }
        } catch (error) {
          formStatus.textContent = error.message;
          approveButton.disabled = false;
          rejectButton.disabled = false;
        }
      });
      const openButton = document.createElement("button");
      openButton.type = "button";
      openButton.className = "evidence-candidate-open";
      openButton.textContent = "Open source";
      openButton.addEventListener("click", () => openSourceInReader(candidate, "utility:analysis"));
      actions.append(approveButton, rejectButton, openButton);
      const navigation = document.createElement("div");
      navigation.className = "evidence-candidate-navigation";
      const previous = document.createElement("button");
      previous.type = "button";
      previous.textContent = "Previous";
      previous.disabled = candidateIndex === 0;
      previous.addEventListener("click", () => showCandidate(candidateIndex - 1));
      const next = document.createElement("button");
      next.type = "button";
      next.textContent = "Next";
      next.disabled = candidateIndex >= visibleCandidates.length - 1;
      next.addEventListener("click", () => showCandidate(candidateIndex + 1));
      const hint = document.createElement("span");
      hint.textContent = "Next skips this candidate without dismissing it.";
      navigation.append(previous, hint, next);
      const reviewControls = document.createElement("div");
      reviewControls.className = "evidence-candidate-controls";
      reviewControls.append(actions, navigation);
      card.append(cardHeader, reviewControls, quote);
      if (candidate.sourceReviewRequirements?.length) {
        card.append(sourceRequirements);
      }
      if (candidate.richSources?.length) {
        card.append(structuredSources);
      }
      if (candidate.visualSources?.length) {
        card.append(visualSources);
      }
      tray.append(card);
    }
    results.append(tray);

    const prepare = document.createElement("section");
    prepare.className = "evidence-discovery-prepare";
    const activeDecisionID = String(codeQuestionWorkspaceState().activeQuestionID || "").trim();
    const linkedConversationID = discovery.projectID === activeProjectIDForCodeQuestions()
      ? linkedResearchConversationIDForQuestion(activeDecisionID)
      : "";
    const prepareButton = document.createElement("button");
    prepareButton.type = "button";
    prepareButton.className = "evidence-discovery-prepare-button";
    prepareButton.textContent = `Add Selected Evidence${approved.length ? ` (${approved.length})` : ""}`;
    prepareButton.disabled = approved.length === 0;
    const prepareStatus = document.createElement("p");
    prepareStatus.className = "evidence-discovery-status";
    prepareButton.addEventListener("click", async () => {
      if (!approved.length) return;
      const prepareAccount = activeAccount();
      const prepareContext = {
        generation: researchOpenGeneration,
        accountUserID: prepareAccount?.userID || "",
        sessionToken: prepareAccount?.sessionToken || "",
        projectID: activeProjectIDForCodeQuestions(),
        conversationID: ""
      };
      prepareButton.disabled = true;
      prepareStatus.textContent = "Adding only the passages you selected…";
      let payload = null;
      try {
        const decisionRequiresLinkedResearch = Boolean(
          activeDecisionID && discovery.projectID === activeProjectIDForCodeQuestions()
        );
        let targetConversationID = linkedConversationID;
        if (decisionRequiresLinkedResearch && !targetConversationID) {
          const linkedConversation = await startLinkedResearchForCodeDecision(activeDecisionID, { open: false });
          if (!researchOpenContextIsCurrent(prepareContext)) return;
          targetConversationID = String(linkedConversation?.id || "").trim();
          if (!targetConversationID) {
            throw new Error("Permitext could not start the question’s linked Research conversation.");
          }
        }
        const selectedPassages = approved.map((candidate) => ({
          sectionID: candidate.sectionID,
          selectedText: candidate.selectedText,
          richSourceIDs: candidate.richSourceIDs || [],
          visualSourceIDs: candidate.selectedVisualSourceIDs || [],
          visualReviewConfirmed: candidate.visualReviewConfirmed === true
        }));
        payload = await postResearch(
          targetConversationID ? "/research/conversations/evidence" : "/research/conversations/create",
          targetConversationID
            ? { conversationID: targetConversationID, selections: selectedPassages }
            : {
                projectID: discovery.projectID || "",
                selections: selectedPassages,
                originSurface: "evidenceDiscovery"
              }
        );
        if (!researchOpenContextIsCurrent(prepareContext)) return;
        if (!payload.conversation) throw new Error("Research did not return the updated conversation.");
        activeResearchConversation = payload.conversation;
        researchQuestionDraft = discovery.question;
        activeEvidenceDiscovery = null;
        await refreshResearchConversationList();
        if (!researchOpenContextIsCurrent(prepareContext)) return;
        await openResearchConversation(payload.conversation.id, { refreshList: true });
      } catch (error) {
        prepareStatus.textContent = error.message;
        prepareButton.disabled = false;
      }
    });
    prepare.append(prepareButton, prepareStatus);
    results.append(prepare);
  };

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const normalizedQuestion = question.value.replace(/\s+/g, " ").trim();
    if (normalizedQuestion.length < 3) return;
    const discoveryAccount = activeAccount();
    const discoveryContext = {
      generation: researchOpenGeneration,
      accountUserID: discoveryAccount?.userID || "",
      sessionToken: discoveryAccount?.sessionToken || "",
      projectID: activeProjectIDForCodeQuestions(),
      conversationID: ""
    };
    question.disabled = true;
    projectSelect.disabled = true;
    findButton.disabled = true;
    formStatus.textContent = "Searching the enacted library for review candidates…";
    try {
      const response = await postResearch("/research/evidence/discover", {
        question: normalizedQuestion,
        projectID: projectSelect.value,
        limit: 12
      });
      if (!researchOpenContextIsCurrent(discoveryContext)) return;
      const rejectedCandidateIDs = rejectedResearchCandidateIDs();
      const rankedCandidates = (response.candidates || []).map((candidate) => ({
        ...candidate,
        reviewState: rejectedCandidateIDs.has(candidate.id) ? "rejected" : "candidate"
      }));
      activeEvidenceDiscovery = {
        accountUserID: activeAccount()?.userID || "",
        question: normalizedQuestion,
        projectID: projectSelect.value,
        activeCandidateID: rankedCandidates.find((candidate) => candidate.reviewState !== "rejected")?.id || "",
        visibleCandidateCount: Math.min(3, rankedCandidates.length),
        candidateNavigatorOpen: false,
        showRejected: false,
        response: {
          ...response,
          candidates: rankedCandidates
        }
      };
      formStatus.textContent = response.candidates?.length
        ? ""
        : "No candidates were found. Refine the question or identify a code section.";
      renderResults();
    } catch (error) {
      if (researchOpenContextIsCurrent(discoveryContext)) formStatus.textContent = error.message;
    } finally {
      if (!researchOpenContextIsCurrent(discoveryContext)) return;
      question.disabled = false;
      projectSelect.disabled = false;
      findButton.disabled = question.value.trim().length < 3;
    }
  });

  section.append(form, results);
  container.append(section);
  renderResults();
}

function bindResearchSendShortcut(input, form) {
  input.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" || event.shiftKey || event.isComposing) return;
    event.preventDefault();
    form.requestSubmit();
  });
}

async function showNewResearchChat() {
  researchOpenGeneration += 1;
  state.researchConversationID = "";
  activeResearchConversation = null;
  researchQuestionDraft = "";
  Object.keys(state.paneWeights)
    .filter((id) => id.startsWith("research:conversation:"))
    .forEach((id) => delete state.paneWeights[id]);
  state.paneOrder = (state.paneOrder || []).filter((id) => !id.startsWith("research:conversation:"));
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: ["utility:analysis"] });
  requestAnimationFrame(() => {
    track.querySelector('.workspace-panel[data-pane-id="utility:analysis"] .research-question-input:not(:disabled)')
      ?.focus({ preventScroll: true });
  });
}

function createResearchProgressSession(conversationID, question) {
  const session = {
    id: crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`,
    conversationID,
    question,
    startedAt: Date.now(),
    endedAt: null,
    status: "active",
    stages: new Map(researchProgressStages.map((stage) => [stage.id, "pending"])),
    controller: new AbortController(),
    retry: null,
    timer: null,
    error: ""
  };
  session.stages.set("preparing_question", "active");
  if (conversationID) activeResearchProgress.set(conversationID, session);
  return session;
}

function researchRequestRecoveryScope(conversationID, requestID = "") {
  return {
    accountUserID: activeAccount()?.userID || "",
    workspaceID: activeWorkspaceID,
    conversationID: String(conversationID || "").trim(),
    requestID: String(requestID || "").trim()
  };
}

function persistResearchProgressSession(progress) {
  const scope = researchRequestRecoveryScope(progress?.conversationID, progress?.id);
  if (!scope.accountUserID || !scope.workspaceID || !scope.conversationID || !scope.requestID) return false;
  return writeResearchRequestRecovery(localStorage, {
    ...scope,
    question: progress.question,
    status: progress.status,
    startedAt: progress.startedAt,
    endedAt: progress.endedAt,
    error: progress.error,
    errorCode: progress.errorCode,
    errorStatus: progress.errorStatus,
    recoveryReason: progress.recoveryReason,
    stages: researchProgressStages.map((stage) => ({
      id: stage.id,
      state: progress.stages.get(stage.id) || "pending"
    }))
  });
}

function researchConversationContainsCompletedRequest(conversation, requestID, question) {
  const matching = (conversation?.messages || []).filter((message) => message.requestID === requestID);
  return matching.some((message) => message.role === "user" && message.question === question) &&
    matching.some((message) => message.role === "assistant" && message.answer);
}

function restoreResearchProgressSession(conversation) {
  const conversationID = String(conversation?.id || "").trim();
  if (!conversationID) return null;
  const scope = researchRequestRecoveryScope(conversationID);
  if (!scope.accountUserID || !scope.workspaceID) return null;
  const saved = readResearchRequestRecovery(localStorage, scope) ||
    [...(conversation.messages || [])].reverse().map((message) =>
      researchRecoveryFromFailedMessage(message, conversationID)).find(Boolean);
  if (!saved) return null;
  if (researchConversationContainsCompletedRequest(conversation, saved.requestID, saved.question)) {
    removeResearchRequestRecovery(localStorage, { ...scope, requestID: saved.requestID });
    return null;
  }

  const interrupted = ["active", "retrying"].includes(saved.status);
  const stages = new Map(saved.stages.map((stage) => [stage.id, stage.state]));
  if (interrupted) {
    const activeStage = researchProgressStages.find((stage) =>
      ["active", "retrying"].includes(stages.get(stage.id))
    ) || researchProgressStages.find((stage) => stages.get(stage.id) === "pending");
    if (activeStage) stages.set(activeStage.id, "failed");
  }
  const progress = {
    id: saved.requestID,
    conversationID,
    question: saved.question,
    startedAt: saved.startedAt,
    endedAt: saved.endedAt || Date.now(),
    status: interrupted ? "failed" : saved.status,
    stages,
    controller: new AbortController(),
    retry: null,
    timer: null,
    error: interrupted ? researchFailureMessage({ code: "RESEARCH_INTERRUPTED" }) : saved.error,
    errorCode: interrupted ? "RESEARCH_INTERRUPTED" : saved.errorCode,
    errorStatus: saved.errorStatus,
    recoveryReason: saved.recoveryReason
  };
  activeResearchProgress.set(conversationID, progress);
  persistResearchProgressSession(progress);
  return progress;
}

function reconciledResearchProgressSession(conversation) {
  const cached = activeResearchProgress.get(conversation.id);
  if (cached && ["failed", "cancelled"].includes(cached.status) &&
      researchConversationContainsCompletedRequest(conversation, cached.id, cached.question)) {
    clearInterval(cached.timer);
    activeResearchProgress.delete(conversation.id);
    removeResearchRequestRecovery(localStorage, researchRequestRecoveryScope(conversation.id, cached.id));
  }
  return activeResearchProgress.get(conversation.id) || restoreResearchProgressSession(conversation);
}

function researchProgressElapsed(startedAt, endedAt = Date.now()) {
  const elapsedSeconds = Math.max(0, Math.floor(((endedAt || Date.now()) - startedAt) / 1_000));
  const minutes = Math.floor(elapsedSeconds / 60);
  const seconds = elapsedSeconds % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

function researchProgressStatusLabel(progress) {
  if (progress.status === "completed") return progress.answerIncomplete ? "Research incomplete" : "Research complete";
  if (progress.errorCode === "RESEARCH_ZONING_SOURCE_UNAVAILABLE") return "Zoning Research unavailable";
  const active = researchProgressStages.find((stage) =>
    ["active", "retrying"].includes(progress.stages.get(stage.id))
  );
  if (active) return active.label;
  if (progress.status === "cancelled") return "Research cancelled";
  if (progress.status === "failed") return "Research interrupted";
  return "Preparing the question";
}

function renderResearchPixelGrid() {
  const grid = document.createElement("span");
  grid.className = "research-progress-grid";
  grid.setAttribute("aria-hidden", "true");
  for (let index = 0; index < 9; index += 1) {
    const pixel = document.createElement("span");
    pixel.style.setProperty("--research-progress-pixel", index);
    grid.append(pixel);
  }
  return grid;
}

function researchProgressFailureRecovery(progress) {
  return researchFailureRecovery({ code: progress.errorCode || (progress.status === "cancelled" ? "RESEARCH_CANCELLED" : ""),
    status: progress.errorStatus, recoveryReason: progress.recoveryReason }, progress.question);
}

async function openResearchProgressIssueReport(progress) {
  const identity = progress.requestIdentity || captureAccountRequest();
  if (!isCurrentAccountRequest(identity)) return;
  try {
    const conversation = supplementalResearchConversations.has(progress.conversationID)
      ? await openSupplementalResearchConversation(progress.conversationID)
      : await openResearchConversation(progress.conversationID, { refreshList: true });
    requireCurrentAccountRequest(identity);
    const message = conversation?.messages?.findLast(item => item.role === "assistant" && item.requestID === progress.id);
    // The feedback API requires a real saved assistant identity. Opening its
    // existing button only opens a local form; Send feedback remains explicit.
    const detailsID = message ? `research-feedback-details-${String(message.id).replace(/[^a-zA-Z0-9_-]/g, "-")}` : "";
    const report = detailsID ? document.querySelector(`button[aria-controls="${CSS.escape(detailsID)}"]`) : null;
    if (report) { report.click(); return; }
    progress.reportUnavailable = true;
    progress.error = "I couldn’t open an issue-report form for this attempt. Open Account feedback to contact support.";
  } catch {
    if (!isCurrentAccountRequest(identity)) return;
    progress.reportUnavailable = true;
    progress.error = "I couldn’t open this attempt. Open Account feedback to contact support.";
  }
  refreshResearchProgressCard(progress);
}

function renderResearchProgressCard(progress, { completed = false, retryDisabled = false } = {}) {
  const card = document.createElement("section");
  card.className = "research-progress-card";
  card.dataset.researchProgressId = progress.id || "saved";
  card.dataset.progressState = progress.status || (completed ? "completed" : "active");
  card.setAttribute("aria-label", "Research progress");

  const loading = document.createElement("div");
  loading.className = "research-progress-loading";
  const label = document.createElement("span");
  label.className = "research-progress-loading-label";
  label.textContent = researchProgressStatusLabel(progress);
  const elapsed = document.createElement("time");
  elapsed.className = "research-progress-elapsed";
  elapsed.dataset.researchProgressElapsed = "true";
  elapsed.textContent = researchProgressElapsed(progress.startedAt, progress.endedAt);
  loading.append(renderResearchPixelGrid(), label, elapsed);
  card.append(loading);

  if (progress.error) {
    const error = document.createElement("p");
    error.className = "research-progress-error";
    error.setAttribute("role", "alert");
    error.textContent = progress.reportUnavailable || progress.recoveryReviewed ? progress.error
      : researchProgressFailureRecovery(progress).text;
    card.append(error);
  }
  if (!completed && progress.errorCode !== "RESEARCH_ZONING_SOURCE_UNAVAILABLE" && ["active", "retrying", "failed", "cancelled"].includes(progress.status)) {
    const actions = document.createElement("div");
    actions.className = "research-progress-actions";
    if (["active", "retrying"].includes(progress.status)) {
      const cancel = document.createElement("button");
      cancel.className = "ghost-button research-progress-cancel";
      cancel.type = "button";
      cancel.textContent = "Cancel";
      cancel.addEventListener("click", () => progress.controller.abort());
      actions.append(cancel);
    } else if (
      progress.errorCode === "RESEARCH_TURNS_REQUIRED" &&
      hasAvailableWebResearchTurnPack()
    ) {
      const purchase = document.createElement("button");
      purchase.className = "ghost-button research-progress-retry";
      purchase.type = "button";
      purchase.textContent = "Buy more turns";
      purchase.addEventListener("click", () => toggleUtilityPane("settings"));
      actions.append(purchase);
    } else if (!progress.recoveryReviewed && ["review_context", "review_sources"].includes(researchProgressFailureRecovery(progress).action)) {
      const review = document.createElement("button");
      review.className = "ghost-button research-progress-review";
      review.type = "button";
      review.textContent = researchProgressFailureRecovery(progress).action === "review_sources" ? "Review sources" : "Review current Research";
      review.addEventListener("click", async () => {
        const requestIdentity = progress.requestIdentity || captureAccountRequest();
        if (!isCurrentAccountRequest(requestIdentity)) return;
        review.disabled = true;
        try {
          let conversation;
          if (supplementalResearchConversations.has(progress.conversationID)) {
            conversation = await openSupplementalResearchConversation(progress.conversationID);
          } else {
            conversation = await openResearchConversation(progress.conversationID, { refreshList: true });
          }
          requireCurrentAccountRequest(requestIdentity);
          if (!conversation) throw new Error("The current conversation is not available");
          progress.recoveryReviewed = true;
          progress.error = "Research reloaded. Review its Project context and sources before continuing.";
          refreshResearchProgressCard(progress);
        } catch (error) {
          if (!isCurrentAccountRequest(requestIdentity)) return;
          progress.error = `Could not reload current Research: ${error.message}. Your question is preserved.`;
          refreshResearchProgressCard(progress);
        }
      });
      actions.append(review);
    } else if (researchProgressFailureRecovery(progress).action === "report" && !progress.reportUnavailable) {
      const report = document.createElement("button");
      report.type = "button";
      report.className = "ghost-button research-progress-report";
      report.textContent = "Report this issue";
      report.addEventListener("click", async () => {
        if (report.disabled) return;
        report.disabled = true;
        await openResearchProgressIssueReport(progress);
        report.disabled = false;
      });
      actions.append(report);
    } else if (researchProgressFailureRecovery(progress).action === "review_account") {
      const account = document.createElement("button");
      account.type = "button";
      account.className = "ghost-button research-progress-account";
      account.textContent = "Open Account";
      account.addEventListener("click", () => toggleUtilityPane("settings"));
      actions.append(account);
    } else if ((researchProgressFailureRecovery(progress).retryable || progress.recoveryReviewed) && typeof progress.retry === "function") {
      const retry = document.createElement("button");
      retry.className = "ghost-button research-progress-retry";
      retry.type = "button";
      retry.textContent = "Retry";
      retry.disabled = retryDisabled;
      retry.addEventListener("click", progress.retry);
      actions.append(retry);
    } else {
      const support = document.createElement("button");
      support.type = "button";
      support.className = "ghost-button research-progress-support";
      support.textContent = "Contact support";
      support.addEventListener("click", () => toggleUtilityPane("settings"));
      actions.append(support);
    }
    card.append(actions);
  }
  return card;
}

function researchProgressFromSavedMessage(message) {
  const value = message?.researchProgress;
  if (!value || value.status !== "completed" || !Array.isArray(value.stages)) return null;
  return {
    id: message.requestID || `saved-${message.id}`,
    status: "completed",
    answerIncomplete: researchAnswerHasVerificationRecovery(message.answer),
    startedAt: Date.parse(value.startedAt) || Date.parse(message.createdAt) || Date.now(),
    endedAt: Date.parse(value.completedAt) || Date.parse(message.createdAt) || Date.now(),
    stages: new Map(value.stages.map((stage) => [stage.id, stage.state]))
  };
}

function refreshResearchProgressCard(progress) {
  const selector = `[data-research-progress-id="${CSS.escape(progress.id)}"]`;
  document.querySelectorAll(selector).forEach((card) => {
    card.replaceWith(renderResearchProgressCard(progress));
  });
}

function startResearchProgressTimer(progress) {
  clearInterval(progress.timer);
  progress.timer = window.setInterval(() => {
    const selector = `[data-research-progress-id="${CSS.escape(progress.id)}"] [data-research-progress-elapsed]`;
    document.querySelectorAll(selector).forEach((elapsed) => {
      elapsed.textContent = researchProgressElapsed(progress.startedAt, progress.endedAt);
    });
  }, 1_000);
}

function updateResearchProgressSession(progress, event) {
  const stage = researchProgressStage(event?.stage);
  if (!stage || stage.label !== event.label) return;
  progress.stages.set(stage.id, event.state);
  if (["active", "retrying"].includes(event.state)) progress.status = event.state;
  persistResearchProgressSession(progress);
  refreshResearchProgressCard(progress);
}

function currentResearchProgressConversation(conversationID) {
  const candidates = [activeResearchConversation, supplementalResearchConversations.get(conversationID),
    ...researchConversationList].filter((conversation) => conversation?.id === conversationID);
  return candidates.reduce((current, candidate) => {
    if (!current) return candidate;
    const contextDifference = Number(candidate.contextRevision || 0) - Number(current.contextRevision || 0);
    return contextDifference > 0 || (contextDifference === 0 && Number(candidate.revision || 0) > Number(current.revision || 0))
      ? candidate : current;
  }, null);
}

function captureResearchProgressView(conversationID) {
  const conversation = currentResearchProgressConversation(conversationID);
  return {
    requestIdentity: captureAccountRequest(),
    workspaceID: activeWorkspaceID,
    projectID: activeProjectIDForCodeQuestions(),
    conversationID,
    supplemental: supplementalResearchConversationIDs.includes(conversationID),
    conversation: conversation ? { ...conversation } : null
  };
}

function researchProgressViewIsCurrent(view) {
  // Saved Project selection is independent of an already-open Research pane.
  // Conversation revisions below guard an actual move to another Project.
  if (!view || !isCurrentAccountRequest(view.requestIdentity) ||
      view.workspaceID !== activeWorkspaceID) return false;
  return view.supplemental
    ? supplementalResearchConversationIDs.includes(view.conversationID) && supplementalResearchConversations.has(view.conversationID)
    : researchConversationPaneIsOpen() && state.researchConversationID === view.conversationID;
}

function researchProgressConversationConflict(view, incoming) {
  if (!incoming) return null;
  const current = currentResearchProgressConversation(view.conversationID) || view.conversation;
  const currentContext = Number(current?.contextRevision || 0);
  const incomingContext = Number(incoming.contextRevision || 0);
  const contextChanged = current && (currentContext > incomingContext || (
    currentContext === incomingContext && incoming.primaryProjectID !== undefined &&
    String(current.primaryProjectID || "") !== String(incoming.primaryProjectID || "")
  ));
  const revisionChanged = current && incoming.revision !== undefined && incomingContext <= currentContext &&
    Number(current.revision || 0) > Number(incoming.revision || 0);
  if (incoming.id === view.conversationID && !contextChanged && !revisionChanged) return null;
  const error = new Error("This Research conversation changed while the response was arriving. Review current Research before continuing. Your question is preserved.");
  error.code = contextChanged ? "RESEARCH_CONTEXT_CHANGED" : "RESEARCH_CONVERSATION_CHANGED";
  error.payload = { code: error.code, status: 409, ...(current ? { conversation: current } : {}) };
  return error;
}

async function runResearchProgressSession(
  progress,
  { onSuccess, onFailure, onRetry } = {},
  { retrying = false } = {}
) {
  const requestIdentity = progress.requestIdentity || captureAccountRequest();
  progress.requestIdentity = requestIdentity;
  const execute = async (retrying = false) => {
    if (!isCurrentAccountRequest(requestIdentity)) return;
    if (retrying) {
      const recovery = researchProgressFailureRecovery(progress);
      if (!recovery.retryable && !(progress.recoveryReviewed &&
          ["review_context", "review_sources"].includes(recovery.action))) return;
    }
    const competing = activeResearchProgress.get(progress.conversationID);
    if (competing && ["active", "retrying"].includes(competing.status) &&
        (competing.id !== progress.id || retrying)) return;
    activeResearchProgress.set(progress.conversationID, progress);
    const view = captureResearchProgressView(progress.conversationID);
    if (retrying) {
      onRetry?.({ view });
      progress.stages = new Map(researchProgressStages.map((stage) => [stage.id, "pending"]));
      progress.stages.set("preparing_question", "retrying");
      progress.status = "retrying";
      progress.error = "";
      progress.errorCode = "";
      progress.errorStatus = 0;
      progress.recoveryReason = "";
      progress.recoveryReviewed = false;
      progress.startedAt = Date.now();
      progress.endedAt = null;
      progress.controller = new AbortController();
      persistResearchProgressSession(progress);
      refreshResearchProgressCard(progress);
      startResearchProgressTimer(progress);
    }
    persistResearchProgressSession(progress);
    try {
      const result = await postResearchWithProgress({
        conversationID: progress.conversationID,
        question: progress.question,
        requestID: progress.id
      }, {
        signal: progress.controller.signal,
        onProgress: (event) => {
          if (isCurrentAccountRequest(requestIdentity)) updateResearchProgressSession(progress, event);
        }
      });
      requireCurrentAccountRequest(requestIdentity);
      const conflict = researchProgressConversationConflict(view, result.conversation);
      if (conflict) throw conflict;
      progress.status = "completed";
      const completedMessage = result.conversation?.messages?.findLast(message =>
        message.role === "assistant" && message.requestID === progress.id
      );
      progress.answerIncomplete = completedMessage ? researchAnswerHasVerificationRecovery(completedMessage.answer) : false;
      progress.endedAt = Date.now();
      clearInterval(progress.timer);
      activeResearchProgress.delete(progress.conversationID);
      removeResearchRequestRecovery(
        localStorage,
        researchRequestRecoveryScope(progress.conversationID, progress.id)
      );
      refreshResearchProgressCard(progress);
      if (researchProgressViewIsCurrent(view)) await onSuccess?.(result, { view });
    } catch (error) {
      if (!isCurrentAccountRequest(requestIdentity)) {
        clearInterval(progress.timer);
        return;
      }
      const cancelled = error.name === "AbortError" || error.code === "RESEARCH_CANCELLED";
      const activeStage = researchProgressStages.find((stage) =>
        ["active", "retrying"].includes(progress.stages.get(stage.id))
      ) || researchProgressStages.find((stage) => progress.stages.get(stage.id) === "pending");
      if (activeStage) progress.stages.set(activeStage.id, cancelled ? "cancelled" : "failed");
      progress.status = cancelled ? "cancelled" : "failed";
      progress.error = cancelled
        ? researchFailureMessage({ code: "RESEARCH_CANCELLED" }, progress.question)
        : researchFailureMessage(error, progress.question);
      progress.errorCode = cancelled ? "RESEARCH_CANCELLED" : error.code || error.payload?.code || "";
      progress.errorStatus = Number(error.status || error.payload?.status || 0);
      progress.recoveryReason = error.payload?.recoveryReason || "";
      if (error.payload?.usage) researchUsage = error.payload.usage;
      progress.endedAt = Date.now();
      clearInterval(progress.timer);
      persistResearchProgressSession(progress);
      refreshResearchProgressCard(progress);
      if (researchProgressViewIsCurrent(view)) await onFailure?.(error, { cancelled, view });
    }
  };
  const callbacks = { onSuccess, onFailure, onRetry };
  progress.retry = () => void runResearchProgressSession(progress, callbacks, { retrying: true });
  await execute(retrying);
}

function recoveredResearchProgressCallbacks(conversationID, { supplemental = false } = {}) {
  const composerControls = () => {
    const dialogue = document.getElementById(`research-dialogue-${conversationID}`)?.parentElement;
    return {
      input: dialogue?.querySelector(".research-question-input") || null,
      sendButton: dialogue?.querySelector(".research-send-button") || null,
      status: dialogue?.querySelector(".research-composer-status") || null
    };
  };
  return {
    onRetry: ({ view } = {}) => {
      if (view && !researchProgressViewIsCurrent(view)) return;
      const controls = composerControls();
      if (controls.input) controls.input.disabled = true;
      if (controls.sendButton) controls.sendButton.disabled = true;
      if (controls.status) controls.status.textContent = "";
    },
    onSuccess: async (result, { view = captureResearchProgressView(conversationID) } = {}) => {
      if (!researchProgressViewIsCurrent(view) || researchProgressConversationConflict(view, result.conversation)) return;
      if (supplemental) supplementalResearchConversations.set(conversationID, result.conversation);
      else activeResearchConversation = result.conversation;
      await refreshProjectSourceConsumers([result.conversation.primaryProjectID], {
        refreshNotebookFoundation: true
      });
      if (!researchProgressViewIsCurrent(view) || researchProgressConversationConflict(view, result.conversation)) return;
      await refreshResearchConversationList();
      if (!researchProgressViewIsCurrent(view) || researchProgressConversationConflict(view, result.conversation)) return;
      await transitionWorkspace("utility", { refreshPaneIDs: [paneIDForResearchConversation(conversationID)] });
    },
    onFailure: async (error, { view = captureResearchProgressView(conversationID) } = {}) => {
      if (!researchProgressViewIsCurrent(view)) return;
      if (error.payload?.conversation && !researchProgressConversationConflict(view, error.payload.conversation)) {
        if (supplemental) supplementalResearchConversations.set(conversationID, error.payload.conversation);
        else activeResearchConversation = error.payload.conversation;
      }
      // Rebuild the composer too: a pane restored during an active request has
      // input handlers which captured that request's disabled state.
      await transitionWorkspace("utility", { refreshPaneIDs: [paneIDForResearchConversation(conversationID)] });
    }
  };
}

function researchComposerDisclosure() {
  const disclosure = document.createElement("p");
  disclosure.className = "research-composer-disclosure";
  disclosure.append(document.createTextNode(
    "AI-assisted—not an official interpretation. Research sends your question, recent chat, selected or retrieved evidence, and current Project facts when assigned to OpenAI. Private notes are not included. Do not include confidential, regulated, or sensitive personal information. Ordinary property information may be included when needed. "
  ));
  const privacyLink = document.createElement("a");
  privacyLink.href = "/privacy";
  privacyLink.target = "_blank";
  privacyLink.rel = "noopener noreferrer";
  privacyLink.textContent = "Privacy";
  disclosure.append(privacyLink);
  return disclosure;
}

function researchProjectContextPreview(projectID, projectInformation = null) {
  const preview = document.createElement("p");
  preview.className = "research-project-context-preview";
  const update = (nextProjectID = projectID, nextInformation = projectInformation) => {
    const normalizedProjectID = String(nextProjectID || "").trim();
    if (!normalizedProjectID) {
      preview.textContent = "Unassigned: no saved Project facts will be sent. Private notes are not included.";
      return;
    }
    const localProject = visibleProjectRecords(currentContentSummary().projects || [])
      .find((project) => researchProjectID(project) === normalizedProjectID) || null;
    const information = nextInformation || localProject || {};
    const usableFacts = projectStructuredFacts(information).filter((fact) =>
      fact.key !== "floor-affected" && ["stated", "confirmed", "sourced"].includes(fact.status)
    );
    const address = String(information.address || localProject?.address || "").trim();
    const labels = [
      ...(address ? [`Address: ${address}`] : []),
      ...usableFacts
        .filter((fact) => fact.key !== "address" || !address)
        .map((fact) => `${fact.label}: ${fact.value}`)
    ];
    const visible = labels.slice(0, 3);
    const remainder = Math.max(0, labels.length - visible.length);
    const hasDescription = Boolean(String(information.description || localProject?.description || "").trim());
    preview.textContent = [
      visible.length ? `Project context sent: ${visible.join(" · ")}` : "Assigned Project has no saved structured facts",
      remainder ? `+${remainder} more saved ${remainder === 1 ? "fact" : "facts"}` : "",
      hasDescription ? "Saved Project description is also included" : "",
      "Private notes are not included"
    ].filter(Boolean).join(". ");
  };
  preview.updateResearchProject = update;
  update(projectID, projectInformation);
  return preview;
}

function researchFailureMessage(error, question = "") {
  return researchFailureRecovery(error, question).text;
}

function renderNewResearchComposer(container, researchEnabled, instance = null) {
  const draftKey = instance ? paneIDForUtilityInstance(instance) : "utility:analysis";
  const form = document.createElement("form");
  form.className = "research-composer research-start-composer";
  form.classList.add("research-compact-composer");
  const currentProject = workspaceProject();
  const initialProjectID = currentProject ? projectDetailKey(currentProject) : "";
  const projectPreview = researchProjectContextPreview(initialProjectID);
  const composerBox = document.createElement("div");
  composerBox.className = "research-composer-box";
  const input = document.createElement("textarea");
  input.className = "research-question-input";
  input.rows = 1;
  input.maxLength = 2000;
  input.placeholder = researchChatPlaceholder;
  input.dataset.researchDraftKey = draftKey;
  input.value = researchNewChatDrafts.get(draftKey) || "";
  const sendButton = document.createElement("button");
  sendButton.className = "ghost-button research-send-button";
  sendButton.type = "submit";
  sendButton.textContent = "Send";
  const status = document.createElement("p");
  status.className = "research-composer-status";
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  const updateSendState = () => {
    sendButton.disabled = !researchEnabled || input.disabled || input.value.trim().length < 3;
  };
  input.addEventListener("input", () => {
    researchNewChatDrafts.set(draftKey, input.value);
    scheduleResearchDraftPersistence();
    resizeComposer();
    updateSendState();
  });
  input.addEventListener("blur", flushResearchDraftPersistence);
  const resizeComposer = () => {
    input.style.height = "auto";
    input.style.height = `${Math.min(180, Math.max(48, input.scrollHeight))}px`;
    input.style.overflowY = input.scrollHeight > 180 ? "auto" : "hidden";
  };
  bindResearchSendShortcut(input, form);
  if (!researchEnabled) {
    input.disabled = true;
    input.placeholder = "Pro required to start a new Research chat…";
  }
  updateSendState();
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const question = input.value.replace(/\s+/g, " ").trim();
    if (question.length < 3 || sendButton.disabled) return;
    input.disabled = true;
    sendButton.disabled = true;
    status.textContent = "";
    let conversationID = "";
    const progress = createResearchProgressSession("", question);
    container.querySelector(".analysis-content")?.append(renderResearchProgressCard(progress));
    startResearchProgressTimer(progress);
    try {
      const created = await postResearch("/research/conversations/create", {
        projectID: initialProjectID
      });
      const conversation = created.conversation;
      conversationID = String(conversation?.id || "").trim();
      if (!conversationID) throw new Error("Research did not return a new conversation.");
      if (!instance) {
        researchConversationPaneOpened = true;
        activeResearchConversation = conversation;
        state.researchConversationID = conversationID;
      }
      researchNewChatDrafts.delete(draftKey);
      progress.conversationID = conversationID;
      activeResearchProgress.set(conversationID, progress);
      researchQuestionDraft = "";
      await refreshResearchConversationList();
      await openResearchConversation(conversationID, { refreshList: false, instance });
      await runResearchProgressSession(progress, recoveredResearchProgressCallbacks(conversationID, { supplemental: Boolean(instance) }));
    } catch (error) {
      clearInterval(progress.timer);
      progress.status = "failed";
      progress.error = error.message || "Permitext could not start this Research chat.";
      progress.endedAt = Date.now();
      progress.stages.set("preparing_question", "failed");
      refreshResearchProgressCard(progress);
      researchQuestionDraft = question;
      if (conversationID) {
        await refreshResearchConversationList().catch(() => {});
        await openResearchConversation(conversationID, { refreshList: false, instance });
        await showWebNotice("Question not sent", error.message || "Permitext could not answer this question.");
        return;
      }
      status.textContent = error.message || "Permitext could not start this Research chat.";
      input.disabled = false;
      updateSendState();
    }
  });
  composerBox.append(input, sendButton);
  const information = document.createElement("details");
  information.className = "research-composer-information";
  const informationToggle = document.createElement("summary");
  informationToggle.textContent = "AI-assisted · Verify cited text";
  informationToggle.setAttribute("aria-label", "Research context and privacy information");
  const informationBody = document.createElement("div");
  informationBody.className = "research-information-popover";
  informationBody.append(projectPreview, researchComposerDisclosure());
  information.append(informationToggle, informationBody);
  let informationHoverTimer;
  information.addEventListener("pointerenter", (event) => {
    if (event.pointerType === "touch") return;
    clearTimeout(informationHoverTimer);
    informationHoverTimer = setTimeout(() => {
      if (information.isConnected) information.open = true;
    }, 1000);
  });
  information.addEventListener("pointerleave", () => {
    clearTimeout(informationHoverTimer);
    if (!information.contains(document.activeElement)) information.open = false;
  });
  information.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      clearTimeout(informationHoverTimer);
      information.open = false;
      informationToggle.focus();
    }
  });
  container.querySelector(".research-chat-welcome")?.append(information);
  if (researchEnabled) {
    input.placeholder = currentProject?.name
      ? `Start a new question about ${currentProject.name}…`
      : "Start a new research question…";
  }
  form.append(composerBox, status);
  container.append(form);
  requestAnimationFrame(resizeComposer);
}

async function renderResearch(paneID = "utility:analysis") {
  if (!hasCapability("research")) return renderProLockedPane(paneID, "Assistant");
  const instance = (state.utilityInstances || []).find((item) => paneIDForUtilityInstance(item) === paneID) || null;
  const conversationOpen = instance ? Boolean(instance.conversationID) : researchConversationPaneIsOpen();
  const draftShowing = researchDraftPaneIDs.has(paneID);
  const chatVisible = conversationOpen || draftShowing;
  // History is always available beside this Assistant, including while composing.
  const historyShowing = true;
  const panel = renderUtility(analysisTemplate, paneID);
  panel.classList.add("analysis-panel", "research-list-panel");
  const projectScopedResearch = Boolean(activeProjectIDForCodeQuestions());
  panel.classList.toggle("is-project-scoped", projectScopedResearch);
  if (!instance) panel.querySelector(".utility-close")?.addEventListener("click", closeResearchWorkspace);
  const panelActions = panel.querySelector(".panel-actions");
  const selectedConversationIDs = new Set();
  const conversationRows = new Map();
  let historyConversations = [];
  const visibleHistoryConversations = () => historyConversations;
  const historyState = instance || (state.researchHistoryFilters ||= {});
  let historyGeneration = 0;
  let historyCursor = null;
  let historyTimer = null;
  let selectingConversations = false;
  let clearingSelectedConversations = false;
  const cancelSelectionButton = document.createElement("button");
  cancelSelectionButton.className = "ghost-button research-history-selection-link";
  cancelSelectionButton.type = "button";
  cancelSelectionButton.textContent = "Cancel";
  cancelSelectionButton.hidden = true;
  const selectAllButton = document.createElement("button");
  selectAllButton.className = "ghost-button research-history-selection-link";
  selectAllButton.type = "button";
  selectAllButton.textContent = "Select all";
  selectAllButton.hidden = true;
  const selectHistoryButton = document.createElement("button");
  selectHistoryButton.className = "icon-button research-history-select-button";
  selectHistoryButton.type = "button";
  selectHistoryButton.title = "Select Research conversations";
  selectHistoryButton.setAttribute("aria-label", selectHistoryButton.title);
  selectHistoryButton.setAttribute("aria-pressed", "false");
  selectHistoryButton.innerHTML = selectionModeIconSVG();
  selectHistoryButton.hidden = true;
  const deleteSelectedButton = document.createElement("button");
  deleteSelectedButton.className = "icon-button research-history-delete-button";
  deleteSelectedButton.type = "button";
  deleteSelectedButton.title = "Remove selected conversations from history";
  deleteSelectedButton.setAttribute("aria-label", deleteSelectedButton.title);
  deleteSelectedButton.innerHTML = trashIconSVG();
  deleteSelectedButton.hidden = true;
  panelActions?.prepend(cancelSelectionButton, selectAllButton, deleteSelectedButton, selectHistoryButton);
  const content = panel.querySelector(".analysis-content");

  panel.classList.add("assistant-workspace", "research-clean-start", "is-history-open");
  panel.classList.toggle("is-history-only", !chatVisible);
  const historyRail = document.createElement("aside");
  historyRail.className = "assistant-history-rail";
  historyRail.setAttribute("aria-label", "Assistant conversations");
  historyRail.append(content);
  const assistantBody = document.createElement("section");
  assistantBody.className = "assistant-body";
  assistantBody.setAttribute("aria-label", "Assistant conversation");
  assistantBody.hidden = !chatVisible;
  panel.append(historyRail, assistantBody);
  content.addEventListener("scroll", () => {
    historyState.historyScrollTop = content.scrollTop;
    scheduleResearchDraftPersistence();
  }, { passive: true });
  if (conversationOpen && !draftShowing) {
    panel.classList.add("has-inline-conversation");
    assistantBody.append(await renderResearchConversation(instance?.conversationID || state.researchConversationID, {
      embedded: true, supplemental: Boolean(instance), ownerInstance: instance, paneID
    }));
  } else if (draftShowing) {
    panel.classList.add("has-research-composer", "is-new-research-chat");
    const welcome = document.createElement("div");
    welcome.className = "research-chat-welcome";
    const heading = document.createElement("h3");
    heading.textContent = "New conversation";
    welcome.append(heading);
    const progress = document.createElement("div");
    progress.className = "analysis-content assistant-start-progress";
    assistantBody.append(welcome, progress);
    renderNewResearchComposer(assistantBody, true, instance);
    if (draftShowing) requestAnimationFrame(() => assistantBody.querySelector(".research-question-input")?.focus({ preventScroll: true }));
  }

  const updateConversationSelection = () => {
    panel.classList.toggle("is-research-history-selecting", selectingConversations);
    selectHistoryButton.setAttribute("aria-pressed", String(selectingConversations));
    cancelSelectionButton.hidden = !selectingConversations;
    selectAllButton.hidden = !selectingConversations;
    deleteSelectedButton.hidden = !selectingConversations;
    selectHistoryButton.hidden = !releaseSurfaceVisibility.researchHistoryManagement || selectingConversations || visibleHistoryConversations().length === 0;
    const allSelected = visibleHistoryConversations().length > 0 &&
      selectedConversationIDs.size === visibleHistoryConversations().length;
    selectAllButton.textContent = allSelected ? "Clear all" : "Select all";
    selectHistoryButton.title = "Select Research conversations";
    selectHistoryButton.setAttribute("aria-label", selectHistoryButton.title);
    selectHistoryButton.disabled = clearingSelectedConversations;
    deleteSelectedButton.title = selectedConversationIDs.size
      ? `Remove ${selectedConversationIDs.size} selected ${selectedConversationIDs.size === 1 ? "conversation" : "conversations"} from history`
      : "Remove selected conversations from history";
    deleteSelectedButton.setAttribute("aria-label", deleteSelectedButton.title);
    deleteSelectedButton.disabled = clearingSelectedConversations || selectedConversationIDs.size === 0;
    cancelSelectionButton.disabled = clearingSelectedConversations;
    selectAllButton.disabled = clearingSelectedConversations;
    conversationRows.forEach((row, conversationID) => {
      const selected = selectedConversationIDs.has(conversationID);
      row.classList.toggle("is-selected", selected);
      const openButton = row.querySelector(".research-conversation-open");
      const selectionMark = row.querySelector(".research-conversation-selection-mark");
      if (selectionMark) {
        selectionMark.hidden = !selectingConversations;
        selectionMark.textContent = selected ? "✓" : "○";
      }
      if (selectingConversations) openButton?.setAttribute("aria-pressed", String(selected));
      else openButton?.removeAttribute("aria-pressed");
    });
  };
  const setConversationSelectionActive = (active) => {
    selectingConversations = Boolean(active);
    selectedConversationIDs.clear();
    updateConversationSelection();
  };
  const toggleConversationSelection = (conversationID) => {
    if (!selectingConversations || clearingSelectedConversations) return;
    if (selectedConversationIDs.has(conversationID)) selectedConversationIDs.delete(conversationID);
    else selectedConversationIDs.add(conversationID);
    updateConversationSelection();
  };
  selectHistoryButton.addEventListener("click", () => setConversationSelectionActive(true));
  deleteSelectedButton.addEventListener("click", async () => {
    const selectedConversations = visibleHistoryConversations().filter((conversation) =>
      selectedConversationIDs.has(conversation.id)
    );
    if (!selectedConversations.length) return;
    clearingSelectedConversations = true;
    updateConversationSelection();
    const cleared = await clearResearchConversationHistory(deleteSelectedButton, selectedConversations, {
      rows: selectedConversations.map((conversation) => conversationRows.get(conversation.id)).filter(Boolean),
      onCleared: () => {
        selectedConversationIDs.clear();
        selectingConversations = false;
        clearingSelectedConversations = false;
        updateConversationSelection();
        // Start a fresh page generation so a pending older-page response cannot
        // restore removed conversations from this column's accumulated history.
        if (isCurrent()) void loadHistory(false);
      }
    });
    if (!cleared && panel.isConnected) {
      clearingSelectedConversations = false;
      updateConversationSelection();
    }
  });
  cancelSelectionButton.addEventListener("click", () => setConversationSelectionActive(false));
  selectAllButton.addEventListener("click", () => {
    if (selectedConversationIDs.size === visibleHistoryConversations().length) selectedConversationIDs.clear();
    else visibleHistoryConversations().forEach((conversation) => selectedConversationIDs.add(conversation.id));
    updateConversationSelection();
  });
  panel.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !selectingConversations || clearingSelectedConversations) return;
    event.preventDefault();
    setConversationSelectionActive(false);
    selectHistoryButton.focus({ preventScroll: true });
  });

  if (!activeAccount()) {
    const empty = document.createElement("article");
    empty.className = "analysis-card research-empty-state";
    const heading = document.createElement("h3");
    heading.textContent = "Sign in to keep private research history";
    const copy = document.createElement("p");
    copy.textContent = "Research conversations are stored with your Permitext account and stay separate from official code content.";
    const button = document.createElement("button");
    button.className = "ghost-button";
    button.type = "button";
    button.textContent = "Open Account";
    button.addEventListener("click", () => focusUtility("settings"));
    empty.append(heading, copy, button);
    content.append(empty);
    return panel;
  }

  const researchEnabled = hasCapability("research");
  if (researchEnabled) {
    const newChatButton = document.createElement("button");
    newChatButton.type = "button";
    newChatButton.className = "ghost-button research-new-chat";
    newChatButton.textContent = "+ New chat";
    newChatButton.addEventListener("click", () => {
      researchDraftPaneIDs.add(paneID);
      saveWorkspaceState();
      void transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
    });
    panel.classList.add("has-research-history-footer");
    historyRail.append(newChatButton);
  }

  const renderingIdentity = captureAccountRequest();
  const renderingWorkspaceID = activeWorkspaceID;
  const isCurrent = () => panel.isConnected && isCurrentAccountRequest(renderingIdentity) &&
    activeWorkspaceID === renderingWorkspaceID;
  const usageHost = document.createElement("div");
  const historyHost = document.createElement("div");
  const filters = document.createElement("div");
  filters.className = "research-history-filters";
  // Removing the search control also clears its old, now invisible filter.
  historyState.historyQuery = "";
  const projectFilter = document.createElement("select");
  projectFilter.className = "research-history-project-select";
  projectFilter.setAttribute("aria-label", "Filter Research history by Project");
  const projectChoices = [{ value: "*", label: "All Projects" },
    { value: "", label: "Unassigned" }, ...researchProjectChoices({ includeUnassigned: false })];
  projectChoices.forEach(({ value, label }) => {
    const option = document.createElement("option"); option.value = value; option.textContent = label; projectFilter.append(option);
  });
  const desiredProjectFilter = historyState.historyProjectID ?? (activeProjectIDForCodeQuestions() || "*");
  projectFilter.value = projectChoices.some((choice) => choice.value === desiredProjectFilter) ? desiredProjectFilter : "*";
  const refreshFilters = () => {
    clearTimeout(historyTimer);
    historyGeneration += 1;
    historyState.historyProjectID = projectFilter.value;
    scheduleResearchDraftPersistence();
    selectedConversationIDs.clear();
    historyTimer = setTimeout(() => { if (isCurrent()) void loadHistory(false); }, 200);
  };
  projectFilter.addEventListener("change", refreshFilters);
  filters.append(projectFilter);
  content.append(usageHost, filters, historyHost);
  enhanceSelect(projectFilter);
  const loading = document.createElement("p");
  loading.className = "research-list-status";
  loading.setAttribute("role", "status");
  loading.textContent = "Loading history…";
  historyHost.append(loading);

  const loadUsage = async (reuseRecent = true) => {
    try {
      await refreshResearchUsage({ reuseRecent });
      if (!isCurrent()) return;
      clear(usageHost);

  if (researchEnabled && researchUsage) {
    const usage = document.createElement("section");
    usage.className = "research-usage";
    usage.setAttribute("role", "status");
    const heading = document.createElement("strong");
    heading.textContent = "Research turns";
    const copy = document.createElement("p");
    copy.textContent = researchUsageCopy(researchUsage);
    usage.append(heading, copy);
    if (hasAvailableWebResearchTurnPack(researchUsage)) {
      const buyMore = document.createElement("button");
      buyMore.type = "button";
      buyMore.className = "ghost-button";
      buyMore.textContent = "Buy more turns";
      buyMore.addEventListener("click", () => focusUtility("settings"));
      usage.append(buyMore);
    }
    usageHost.append(usage);
  }
    } catch {
      if (!isCurrent()) return;
      clear(usageHost);
      const retry = document.createElement("button");
      retry.type = "button";
      retry.className = "ghost-button";
      retry.textContent = "Retry allowance";
      retry.addEventListener("click", () => { retry.disabled = true; void loadUsage(false); });
      usageHost.append(retry);
    }
  };
  const loadHistory = async (reuseRecent = true, append = false) => {
    const content = historyHost;
    const generation = ++historyGeneration;
    const current = () => isCurrent() && generation === historyGeneration;
    if (!append) {
      historyCursor = null;
      historyConversations = [];
      clear(content);
      const status = document.createElement("p");
      status.className = "research-list-status";
      status.setAttribute("role", "status");
      status.textContent = "Loading history…";
      content.append(status);
    }
    try {
      const payload = await readResearchHistoryPage({ projectID: projectFilter.value,
        cursor: append ? historyCursor : null }, { reuseRecent });
      if (!current()) return;
      const byID = new Map((append ? historyConversations : []).map((item) => [item.id, item]));
      (payload.conversations || []).forEach((item) => byID.set(item.id, item));
      historyConversations = [...byID.values()];
      historyCursor = payload.hasMore ? payload.nextCursor : null;
      clear(content);
      conversationRows.clear();
      selectHistoryButton.hidden = !releaseSurfaceVisibility.researchHistoryManagement || visibleHistoryConversations().length === 0;
    } catch (error) {
      if (!current()) return;
      if (!append) clear(content);
      const status = document.createElement("p");
      status.className = "research-list-status is-error";
      status.textContent = error.message || "History could not be loaded.";
      const retry = document.createElement("button");
      retry.type = "button";
      retry.className = "ghost-button";
      retry.textContent = "Retry history";
      retry.addEventListener("click", () => { retry.disabled = true; void loadHistory(false, append); });
      content.append(status, retry);
      return;
    }

  if (!researchEnabled) {
    const upgrade = document.createElement("article");
    upgrade.className = "analysis-card research-empty-state";
    const upgradeHeading = document.createElement("h3");
    upgradeHeading.textContent = "Pro required for Research";
    const upgradeCopy = document.createElement("p");
    upgradeCopy.textContent = "Your saved Research history remains readable. Upgrade to Pro to start conversations, attach evidence, or generate new answers.";
    const upgradeButton = document.createElement("button");
    upgradeButton.className = "ghost-button";
    upgradeButton.type = "button";
    upgradeButton.textContent = "View Plans";
    upgradeButton.addEventListener("click", () => focusUtility("settings"));
    upgrade.append(upgradeHeading, upgradeCopy, upgradeButton);
    content.append(upgrade);
  }

  const activeDecisionID = codeQuestionWorkspaceEnabled()
    ? String(codeQuestionWorkspaceState().activeQuestionID || "").trim()
    : "";
  if (activeDecisionID && !projectScopedResearch) {
    const linkedConversationID = linkedResearchConversationIDForQuestion(activeDecisionID);
    const linkedConversation = visibleHistoryConversations().find((item) => item.id === linkedConversationID) || null;
    const decisionResearch = document.createElement("article");
    decisionResearch.className = "analysis-card code-decision-research-entry";
    const decisionAction = document.createElement("button");
    decisionAction.type = "button";
    decisionAction.className = "ghost-button";
    decisionAction.textContent = linkedConversationID ? "Resume linked Research" : "Start Research for this decision";
    const canEditDecision = ["owner", "editor"].includes(codeQuestionDefineRole());
    decisionAction.disabled = !researchEnabled || (!linkedConversationID && (!canEditDecision || !codeQuestionIsOnline()));
    if (!researchEnabled) decisionAction.title = "Pro required for Research";
    else if (!linkedConversationID && !canEditDecision) decisionAction.title = "An Owner or Editor must start linked Research";
    else if (!linkedConversationID && !codeQuestionIsOnline()) decisionAction.title = "Reconnect to start linked Research";
    const decisionStatus = document.createElement("p");
    decisionStatus.className = "research-list-status";
    decisionStatus.setAttribute("role", "status");
    decisionStatus.setAttribute("aria-live", "polite");
    const decisionProjectID = activeProjectIDForCodeQuestions();
    const pendingNotice = codeDecisionResearchNotice(decisionProjectID, activeDecisionID);
    if (pendingNotice) {
      const notice = document.createElement("aside");
      notice.className = "analysis-card code-decision-research-status";
      notice.setAttribute("role", "status");
      notice.setAttribute("aria-live", "polite");
      const noticeHeading = document.createElement("strong");
      noticeHeading.textContent = pendingNotice.title;
      const noticeCopy = document.createElement("p");
      noticeCopy.className = "research-list-status";
      noticeCopy.textContent = pendingNotice.message;
      const noticeActions = document.createElement("div");
      noticeActions.className = "research-summary-actions";
      const dismissButton = document.createElement("button");
      dismissButton.type = "button";
      dismissButton.className = "ghost-button";
      dismissButton.textContent = "Dismiss";
      dismissButton.addEventListener("click", () => {
        clearCodeDecisionResearchNotice(decisionProjectID, activeDecisionID);
        notice.remove();
        decisionAction.focus({ preventScroll: true });
      });
      noticeActions.append(dismissButton);
      notice.append(noticeHeading, noticeCopy, noticeActions);
      decisionResearch.append(notice);
    }
    decisionAction.addEventListener("click", async () => {
      decisionAction.disabled = true;
      decisionStatus.textContent = linkedConversationID ? "Opening linked Research…" : "Starting linked Research…";
      try {
        if (linkedConversationID) {
          clearCodeDecisionResearchNotice(decisionProjectID, activeDecisionID);
          await openResearchConversation(linkedConversationID, {
            conversation: linkedConversation,
            linkedQuestionID: activeDecisionID,
            refreshList: true
          });
        } else {
          await startLinkedResearchForCodeDecision(activeDecisionID);
        }
      } catch (error) {
        decisionStatus.textContent = error.message || "Research could not be opened.";
        decisionAction.disabled = false;
      }
    });
    decisionResearch.append(decisionAction, decisionStatus);
    content.append(decisionResearch);
  }


  if (!visibleHistoryConversations().length) {
    if (projectFilter.value === "*") {
      const empty = document.createElement("div");
      empty.className = "research-conversation-empty";
      empty.textContent = "Your previous chats will appear here.";
      content.append(empty);
    }
    return panel;
  }

  const list = document.createElement("section");
  list.className = "research-conversation-list";
  researchConversationHistoryGroups(visibleHistoryConversations()).forEach((historyGroup) => {
    const group = document.createElement("section");
    group.className = "research-history-group";
    group.dataset.historyGroup = historyGroup.id;
    const groupHeading = document.createElement("div");
    groupHeading.className = "research-history-group-heading";
    const groupLabel = document.createElement(historyGroup.collapsible === false ? "span" : "button");
    groupLabel.className = "research-history-group-label";
    groupLabel.type = "button";
    groupLabel.textContent = historyGroup.label;
    const groupToggle = document.createElement("button");
    groupToggle.className = "project-section-toggle-chevron research-history-group-chevron";
    groupToggle.type = "button";
    groupToggle.innerHTML = researchChevronIconsSVG();
    const groupBody = document.createElement("div");
    groupBody.className = "research-history-group-body";
    groupBody.id = `research-history-${paneID}-${historyGroup.id}`;
    groupLabel.setAttribute("aria-controls", groupBody.id);
    groupToggle.setAttribute("aria-controls", groupBody.id);
    if (historyGroup.collapsible === false) {
      groupLabel.setAttribute("role", "heading");
      groupLabel.setAttribute("aria-level", "3");
      groupHeading.append(groupLabel);
    } else {
      groupHeading.append(groupLabel, groupToggle);
    }
    group.append(groupHeading, groupBody);

    historyGroup.conversations.forEach((initialConversation) => {
    let conversation = initialConversation;
    const row = document.createElement("article");
    row.className = "research-conversation-row";
    row.dataset.conversationId = conversation.id;
    conversationRows.set(conversation.id, row);
    const renderRow = () => {
      clear(row);
      const selected = !researchDraftPaneIDs.has(paneID) && conversation.id === (instance?.conversationID || state.researchConversationID);
      row.classList.toggle("is-active", selected);
      const openButton = document.createElement("button");
      openButton.className = "research-conversation-open";
      if (selected) openButton.setAttribute("aria-current", "true");
      openButton.type = "button";
      const title = document.createElement("strong");
      title.textContent = researchConversationTitle(conversation);
      const metaRow = document.createElement("span");
      metaRow.className = "research-conversation-meta";
      const meta = document.createElement("span");
      meta.className = "research-conversation-date";
      meta.textContent = researchConversationDate(conversation.createdAt);
      const startedAt = Date.parse(conversation.createdAt);
      if (Number.isFinite(startedAt)) {
        const startTime = document.createElement("span");
        startTime.className = "research-conversation-start-time";
        startTime.textContent = new Intl.DateTimeFormat(undefined, {
          hour: "numeric", minute: "2-digit"
        }).format(new Date(startedAt));
        meta.append(startTime);
        meta.title = `Started ${new Intl.DateTimeFormat(undefined, {
          dateStyle: "medium", timeStyle: "short"
        }).format(new Date(startedAt))}`;
      } else {
        meta.textContent = "Start time not recorded";
      }
      const projectPill = document.createElement("span");
      projectPill.className = "research-conversation-project-pill";
      projectPill.textContent = conversation.primaryProjectID
        ? researchProjectName(conversation.primaryProjectID)
        : "Unassigned";
      const conversationProject = researchProjects().find((project) =>
        researchProjectID(project) === String(conversation.primaryProjectID || "")
      );
      if (conversationProject) {
        projectPill.style.setProperty("--project-color", projectColor(conversationProject));
      }
      const preview = document.createElement("span");
      preview.className = "research-conversation-preview";
      preview.textContent = String(conversation.starterQuestion || "").replace(/\s+/g, " ").trim();
      preview.hidden = !preview.textContent || preview.textContent === title.textContent;
      const selectionMark = document.createElement("span");
      selectionMark.className = "research-conversation-selection-mark";
      selectionMark.setAttribute("aria-hidden", "true");
      selectionMark.hidden = !selectingConversations;
      selectionMark.textContent = selectedConversationIDs.has(conversation.id) ? "✓" : "○";
      openButton.append(title, meta, projectPill, preview, selectionMark);
      openButton.addEventListener("click", () => {
        if (selectingConversations) {
          toggleConversationSelection(conversation.id);
          return;
        }
        if (!instance) researchConversationPaneOpened = true;
        void openResearchHistoryConversation(conversation, instance)
          .catch((error) => { if (isCurrent()) void showWebNotice("Research not opened", error.message); });
      });
      if (!releaseSurfaceVisibility.researchHistoryManagement) {
        row.append(openButton);
        return;
      }

      const linkedQuestion = questionsForActiveProject().find((item) =>
        item.id === conversation.linkedCodeDecisionID
      );

      const actions = document.createElement("div");
      actions.className = "research-conversation-row-actions";
      const projectChoices = researchProjectChoices({
        value: conversation.primaryProjectID || "",
        unassignedLabel: "Unassigned"
      });
      const projectSelectWrap = document.createElement("div");
      projectSelectWrap.className = "code-filter-menu research-conversation-project-picker";
      const projectToggle = document.createElement("button");
      projectToggle.className = "code-filter-menu-toggle research-conversation-project-toggle";
      projectToggle.type = "button";
      const projectLabel = document.createElement("span");
      projectLabel.className = "code-filter-menu-label";
      projectLabel.textContent = researchProjectName(conversation.primaryProjectID || "");
      const projectMenuIcon = document.createElement("span");
      projectMenuIcon.className = "code-filter-menu-icon";
      projectMenuIcon.setAttribute("aria-hidden", "true");
      projectMenuIcon.innerHTML = `
        <svg class="code-filter-chevron-down" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m8 10 4 4 4-4"></path></svg>
        <svg class="code-filter-chevron-up" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m8 14 4-4 4 4"></path></svg>
      `;
      projectToggle.append(projectLabel, projectMenuIcon);
      projectToggle.title = conversation.primaryProjectID
        ? `Assigned to ${researchProjectName(conversation.primaryProjectID)}`
        : "Assign conversation to a Project";
      projectToggle.disabled = !researchEnabled;
      const projectOptions = document.createElement("div");
      projectOptions.className = "research-conversation-project-options";
      projectOptions.setAttribute("aria-label", `Project for ${conversation.title}`);
      projectOptions.hidden = true;
      const projectMenuState = { projectMenuOpen: false };
      const setProjectMenuEnabled = (enabled) => {
        projectToggle.disabled = !enabled;
        projectOptions.querySelectorAll("button").forEach((button) => {
          button.disabled = !enabled;
        });
      };
      let previousProjectChoiceCategory = "";
      projectChoices.forEach((choice) => {
        if (choice.category !== "unassigned" && choice.category !== previousProjectChoiceCategory) {
          const categoryLabel = document.createElement("p");
          categoryLabel.className = "research-conversation-project-category";
          categoryLabel.textContent = "Projects";
          projectOptions.append(categoryLabel);
        }
        previousProjectChoiceCategory = choice.category;
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = "research-conversation-project-option";
        optionButton.textContent = choice.label;
        optionButton.dataset.projectId = choice.value;
        optionButton.setAttribute("aria-pressed", String(choice.value === (conversation.primaryProjectID || "")));
        optionButton.addEventListener("click", async () => {
          const previousProjectID = conversation.primaryProjectID || "";
          const previousLinkedQuestionID = conversation.linkedCodeDecisionID || "";
          const targetProjectID = choice.value;
          if (targetProjectID === previousProjectID) {
            projectMenuState.projectMenuOpen = false;
            updateCodeFilterMenu(projectOptions, projectMenuState, {
              stateKey: "projectMenuOpen",
              menuName: `Projects for ${conversation.title}`,
              label: () => researchProjectName(previousProjectID)
            });
            return;
          }
          projectMenuState.projectMenuOpen = false;
          updateCodeFilterMenu(projectOptions, projectMenuState, {
            stateKey: "projectMenuOpen",
            menuName: `Projects for ${conversation.title}`,
            label: () => researchProjectName(previousProjectID)
          });
          setProjectMenuEnabled(false);
          projectSelectWrap.setAttribute("aria-busy", "true");
          try {
            const payload = await assignResearchConversationProject(conversation, targetProjectID, {
              warningContainer: projectSelectWrap.closest(".workspace-panel")
            });
            if (!payload) {
              return;
            }
            conversation = { ...conversation, ...payload.conversation };
            researchConversationList = researchConversationList.map((item) =>
              item.id === conversation.id ? { ...item, ...conversation } : item
            );
            if (state.researchConversationID === conversation.id) {
              activeResearchConversation = {
                ...(activeResearchConversation || {}),
                ...payload.conversation
              };
            }
            if (
              previousLinkedQuestionID &&
              codeQuestionWorkspaceState().activeQuestionID === previousLinkedQuestionID
            ) {
              setCodeQuestionWorkspaceState(
                switchCodeQuestionProject(
                  codeQuestionWorkspaceState(),
                  activeProjectIDForCodeQuestions()
                ),
                { activeProjectID: activeProjectIDForCodeQuestions(), syncDeepLink: true }
              );
            }
            if (previousProjectID) {
              await hydrateCodeQuestionList(previousProjectID, { force: true, render: false });
            }
            await refreshResearchProjectAssignmentConsumers([previousProjectID, targetProjectID]);
            const projectPaneIDs = openProjectDetails().map((detail) => paneIDForProjectDetail(detail));
            await transitionWorkspace("utility", {
              refreshPaneIDs: [
                "utility:analysis",
                ...projectPaneIDs
              ]
            });
          } catch (error) {
            await showWebNotice("Project not changed", error.message);
          } finally {
            setProjectMenuEnabled(researchEnabled);
            projectSelectWrap.removeAttribute("aria-busy");
          }
        });
        projectOptions.append(optionButton);
      });
      projectSelectWrap.append(projectToggle, projectOptions);
      wireCodeFilterMenu(projectOptions, projectMenuState, {
        stateKey: "projectMenuOpen",
        menuName: `Projects for ${conversation.title}`,
        label: () => researchProjectName(conversation.primaryProjectID || "")
      });
      if (
        activeDecisionID &&
        conversation.primaryProjectID === activeProjectIDForCodeQuestions() &&
        conversation.linkedCodeDecisionID !== activeDecisionID
      ) {
        const linkDecisionButton = document.createElement("button");
        linkDecisionButton.className = "research-conversation-link-decision";
        linkDecisionButton.type = "button";
        linkDecisionButton.textContent = "Use for active decision";
        linkDecisionButton.disabled = !researchEnabled ||
          !codeQuestionIsOnline() ||
          !["owner", "editor"].includes(codeQuestionDefineRole());
        linkDecisionButton.title = "Link this private Research history without copying exploratory content into the professional record";
        linkDecisionButton.addEventListener("click", async () => {
          linkDecisionButton.disabled = true;
          try {
            await linkResearchConversationToActiveCodeDecision(conversation);
          } catch (error) {
            await showWebNotice("Research link unchanged", error.message || "The conversation could not be linked.");
            linkDecisionButton.disabled = false;
          }
        });
        actions.append(linkDecisionButton);
      }
      if (researchEnabled) {
        const renameButton = document.createElement("button");
        renameButton.className = "research-conversation-rename";
        renameButton.type = "button";
        renameButton.title = "Rename conversation";
        renameButton.setAttribute("aria-label", `Rename ${conversation.title}`);
        renameButton.innerHTML = pencilIconSVG();
        renameButton.addEventListener("click", () => {
          clear(row);
          row.classList.add("is-renaming");
          const form = document.createElement("form");
          form.className = "research-conversation-rename-form";
          const input = document.createElement("input");
          input.className = "research-conversation-rename-input";
          input.type = "text";
          input.maxLength = 120;
          input.value = conversation.title;
          input.setAttribute("aria-label", "Research conversation name");
          const saveButton = document.createElement("button");
          saveButton.type = "submit";
          saveButton.textContent = "Save";
          const cancelButton = document.createElement("button");
          cancelButton.type = "button";
          cancelButton.textContent = "Cancel";
          const status = document.createElement("span");
          status.className = "research-conversation-rename-status";
          const cancel = () => {
            row.classList.remove("is-renaming");
            renderRow();
          };
          cancelButton.addEventListener("click", cancel);
          input.addEventListener("keydown", (event) => {
            if (event.key === "Escape") {
              event.preventDefault();
              cancel();
            }
          });
          form.addEventListener("submit", async (event) => {
            event.preventDefault();
            const nextTitle = input.value.replace(/\s+/g, " ").trim();
            if (!nextTitle) {
              status.textContent = "Enter a conversation name.";
              input.focus();
              return;
            }
            input.disabled = true;
            saveButton.disabled = true;
            cancelButton.disabled = true;
            status.textContent = "Saving…";
            try {
              const payload = await postResearch("/research/conversations/rename", {
                conversationID: conversation.id,
                title: nextTitle
              });
              conversation = { ...conversation, ...payload.conversation };
              researchConversationList = researchConversationList.map((item) =>
                item.id === conversation.id ? { ...item, ...conversation } : item
              );
              if (state.researchConversationID === conversation.id) {
                activeResearchConversation = {
                  ...(activeResearchConversation || {}),
                  ...payload.conversation
                };
              }
              row.classList.remove("is-renaming");
              renderRow();
            } catch (error) {
              status.textContent = error.message;
              input.disabled = false;
              saveButton.disabled = false;
              cancelButton.disabled = false;
              input.focus();
            }
          });
          form.append(input, saveButton, cancelButton, status);
          row.append(form);
          requestAnimationFrame(() => {
            input.focus();
            input.select();
          });
        });
        actions.append(renameButton);
      }
      const deleteButton = document.createElement("button");
      deleteButton.className = "research-conversation-delete";
      deleteButton.type = "button";
      deleteButton.title = "Delete conversation";
      deleteButton.setAttribute("aria-label", `Delete ${conversation.title}`);
      deleteButton.textContent = "Delete";
      deleteButton.addEventListener("click", () => deleteResearchConversationFromList(conversation, deleteButton));
      actions.append(deleteButton);
      row.append(openButton, actions);
      if (!projectScopedResearch) row.append(projectSelectWrap);
    };
    renderRow();
    groupBody.append(row);
    });

    // Draft rows always stay visible, including evidence and interrupted requests.
    if (historyGroup.collapsible !== false) {
    const storedExpanded = state.researchHistoryGroupExpansion?.[historyGroup.id];
    const containsActiveConversation = historyGroup.conversations.some((conversation) =>
      conversation.id === state.researchConversationID
    );
    const initialExpanded = typeof storedExpanded === "boolean"
      ? storedExpanded
      : historyGroup.defaultExpanded || containsActiveConversation;
    wireProjectSectionMotion(
      group,
      groupBody,
      [groupLabel, groupToggle],
      historyGroup.label,
      initialExpanded,
      {
        onChange: (expanded) => {
          state.researchHistoryGroupExpansion ||= {};
          state.researchHistoryGroupExpansion[historyGroup.id] = expanded;
          saveWorkspaceState();
        }
      }
    );
    }
    list.append(group);
  });
  content.append(list);
  requestAnimationFrame(() => { if (isCurrent()) panel.querySelector(".assistant-history-rail > .analysis-content").scrollTop = Math.max(0, Number(historyState.historyScrollTop) || 0); });
  if (historyCursor) {
    const more = document.createElement("button");
    more.type = "button";
    more.className = "ghost-button research-history-more";
    more.textContent = "Load older conversations";
    more.addEventListener("click", () => { more.disabled = true; more.textContent = "Loading…"; void loadHistory(true, true); });
    content.append(more);
  }
  updateConversationSelection();
  };
  // Publish the column, including New chat, before either metadata request.
  requestAnimationFrame(() => {
    if (!isCurrent()) return;
    void loadHistory();
    void loadUsage();
  });
  return panel;
}

function visualEvidenceDataURL(source) {
  return source?.dataBase64 && source?.mediaType
    ? `data:${source.mediaType};base64,${source.dataBase64}`
    : source?.assetURL || "";
}

function renderResearchVisualEvidence(sources, options = {}) {
  const visualSources = Array.isArray(sources) ? sources : [];
  if (!visualSources.length) return null;
  const wrap = document.createElement("section");
  wrap.className = "research-visual-evidence";
  const heading = document.createElement("strong");
  heading.textContent = options.immutable
    ? "Preserved official visual evidence"
    : "Reviewed official visual evidence";
  const gallery = document.createElement("div");
  gallery.className = "research-visual-evidence-gallery";
  visualSources.forEach((source, index) => {
    const card = document.createElement("article");
    const image = document.createElement("img");
    image.src = visualEvidenceDataURL(source);
    image.alt = `Official visual evidence ${index + 1}: ${source.assetName || "image"}`;
    image.loading = "lazy";
    image.decoding = "async";
    const name = document.createElement("strong");
    name.textContent = source.assetName || `Official image ${index + 1}`;
    const metadata = document.createElement("span");
    metadata.textContent = `${formattedByteLength(source.byteLength)} · SHA-256 ${source.contentHash}`;
    const link = document.createElement("a");
    link.href = visualEvidenceDataURL(source);
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = "Open preserved image";
    card.append(image, name, metadata, link);
    gallery.append(card);
  });
  wrap.append(heading, gallery);
  return wrap;
}

function researchChevronIconsSVG() {
  return `
    <svg class="research-chevron-down" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m8 10 4 4 4-4"></path></svg>
    <svg class="research-chevron-up" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m8 14 4-4 4 4"></path></svg>
  `;
}

function setResearchSourceCardExpanded(card, expanded, options = {}) {
  const toggle = card.querySelector(".research-source-toggle");
  const body = card.querySelector(".research-source-body");
  if (!toggle || !body) return;
  toggle.setAttribute("aria-expanded", String(expanded));
  if (expanded) {
    body.hidden = false;
    const applyExpandedHeight = () => {
      card.style.setProperty("--research-source-body-height", `${body.scrollHeight}px`);
    };
    if (options.instant && !card.classList.contains("is-open")) {
      card.classList.add("is-restoring", "is-open");
      card.style.setProperty("--research-source-body-height", "10000px");
      const restoreWhenMounted = (remainingFrames = 60) => {
        if (toggle.getAttribute("aria-expanded") !== "true") {
          card.classList.remove("is-restoring");
          return;
        }
        if ((!body.isConnected || body.offsetWidth === 0) && remainingFrames > 0) {
          requestAnimationFrame(() => restoreWhenMounted(remainingFrames - 1));
          return;
        }
        if (body.isConnected && body.offsetWidth > 0) applyExpandedHeight();
        void body.offsetHeight;
        requestAnimationFrame(() => card.classList.remove("is-restoring"));
      };
      requestAnimationFrame(() => restoreWhenMounted());
      return;
    }
    if (!card.classList.contains("is-open")) {
      requestAnimationFrame(() => {
        if (toggle.getAttribute("aria-expanded") === "true") {
          applyExpandedHeight();
          card.classList.add("is-open");
        }
      });
    } else {
      applyExpandedHeight();
    }
    return;
  }
  if (!card.classList.contains("is-open")) {
    body.hidden = true;
    return;
  }
  card.style.setProperty("--research-source-body-height", `${body.scrollHeight}px`);
  card.classList.remove("is-open");
  const hideBody = (event) => {
    if (event && event.target !== body) return;
    if (event && event.propertyName !== "max-height") return;
    if (toggle.getAttribute("aria-expanded") !== "true") body.hidden = true;
    body.removeEventListener("transitionend", hideBody);
  };
  body.addEventListener("transitionend", hideBody);
  window.setTimeout(hideBody, 500);
}

function renderResearchSource(source, options = {}) {
  const sourceKind = String(
    source.kind || source.sourceClassification || source.authorityClass || "related"
  ).trim();
  const card = document.createElement("article");
  card.className = `research-source-card is-${sourceKind} code-theme-${codeTheme(source.codePrefix || "BC")}`;
  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "research-source-toggle";
  toggle.setAttribute("aria-expanded", "true");
  const citation = document.createElement("strong");
  const supportingSource = ["official_guidance", "technical_source", "secondary_source", "web"].includes(sourceKind);
  citation.textContent = supportingSource
    ? String(source.title || source.publisher || source.sourceURL || source.url || "Supporting source")
    : options.openInReader
      ? researchAnswerSourceCitation(source)
      : researchSourceCitation(source);
  const disclosure = document.createElement("span");
  disclosure.className = "research-source-disclosure";
  disclosure.setAttribute("aria-hidden", "true");
  if (!options.openInReader) {
    disclosure.innerHTML = researchChevronIconsSVG();
  }
  const body = document.createElement("div");
  body.className = "research-source-body";
  toggle.append(citation);
  if (!options.openInReader) toggle.append(disclosure);
  if (options.openInReader) {
    toggle.removeAttribute("aria-expanded");
    toggle.setAttribute("aria-label", `Open ${citation.textContent} in Reader`);
    toggle.addEventListener("click", () => {
      const sourceURL = String(source.sourceURL || source.url || "").trim();
      if (source.sectionID || (!sourceURL && source.id)) {
        void openSourceInReader(source, options.anchorPaneID, { projectID: options.projectID });
      } else if (sourceURL) {
        window.open(sourceURL, "_blank", "noopener,noreferrer");
      }
    });
  } else {
    toggle.addEventListener("click", () => {
      const expanded = toggle.getAttribute("aria-expanded") === "true";
      setResearchSourceCardExpanded(card, !expanded);
    });
  }
  if (options.openInReader) {
    card.append(toggle);
    const previewText = String(source.selectedText || source.passageText || source.excerpt || source.snippet || source.text || source.userSelectedText || "").replace(/\s+/g, " ").trim();
    if (previewText) {
      const preview = document.createElement("p");
      preview.className = "research-source-preview";
      preview.textContent = previewText;
      card.append(preview);
    }
    return card;
  }
  if (sourceKind === "related") {
    const label = document.createElement("p");
    label.className = "section-label";
    label.textContent = "Suggested related section — not included in analysis";
    const relationship = document.createElement("p");
    relationship.textContent = "Suggested because it is explicitly referenced by this enacted section. Open it and select the relevant passage to include it in analysis.";
    body.append(label, relationship);
  } else if (["enacted_permitext_discovered", "permitext_discovered", "permitext_cross_reference"].includes(sourceKind)) {
    if (
      source.evidencePriority?.evidenceRole === "contextual" ||
      source.provenance?.evidenceRole === "contextual"
    ) {
      const label = document.createElement("p");
      label.className = "section-label";
      label.textContent = "Contextual enacted source — does not govern this answer";
      body.append(label);
    }
  } else if (["enacted_user_pinned", "user_pinned"].includes(sourceKind)) {
    const label = document.createElement("p");
    label.className = "section-label";
    label.textContent = "Pinned enacted source";
    body.append(label);
  } else if (supportingSource) {
    const sourceRoleLabels = {
      official_guidance: "Official guidance — supporting context",
      technical_source: "Technical source — supporting context",
      secondary_source: "Secondary source — noncontrolling context",
      web: "Web source — supporting context"
    };
    const label = document.createElement("p");
    label.className = "section-label";
    label.textContent = sourceRoleLabels[sourceKind] || sourceRoleLabels.web;
    body.append(label);
  }
  const userSelectedText = String(source.userSelectedText || "").trim();
  if (userSelectedText) {
    const pinnedLabel = document.createElement("p");
    pinnedLabel.className = "section-label";
    pinnedLabel.textContent = "Exact text pinned by you";
    const pinnedQuote = document.createElement("blockquote");
    pinnedQuote.textContent = userSelectedText;
    body.append(pinnedLabel, pinnedQuote);
  }
  const sourceText = source.selectedText || source.passageText || source.excerpt || source.snippet || "";
  if (sourceText) {
    const normalizedPinnedText = userSelectedText.replace(/\s+/g, " ").trim();
    const normalizedSourceText = String(sourceText).replace(/\s+/g, " ").trim();
    if (normalizedPinnedText && normalizedPinnedText !== normalizedSourceText) {
      const contextLabel = document.createElement("p");
      contextLabel.className = "section-label";
      contextLabel.textContent = "Complete enacted context used";
      body.append(contextLabel);
    }
    const structuredSource = renderResearchStructuredSource(source.structuredSource);
    if (structuredSource) {
      body.append(structuredSource);
    } else {
      const quote = document.createElement("blockquote");
      quote.textContent = sourceText;
      body.append(quote);
    }
  }
  const visualEvidence = renderResearchVisualEvidence(source.visualSources);
  if (visualEvidence) body.append(visualEvidence);
  card.append(toggle, body);
  return card;
}

function renderResearchStructuredSource(structuredSource) {
  const grids = Array.isArray(structuredSource?.grids) ? structuredSource.grids : [];
  if (!grids.some((grid) => Array.isArray(grid?.rows) && grid.rows.length)) return null;
  const container = document.createElement("section");
  container.className = "research-source-structured-tables";
  grids.forEach((grid, gridIndex) => {
    if (!Array.isArray(grid?.rows) || !grid.rows.length) return;
    const wrapper = document.createElement("div");
    wrapper.className = "code-table research-source-structured-table";
    const table = document.createElement("table");
    if (gridIndex === 0 && structuredSource.reference) {
      const caption = document.createElement("caption");
      caption.textContent = structuredSource.reference;
      table.append(caption);
    }
    const tableBody = document.createElement("tbody");
    grid.rows.forEach((row, rowIndex) => {
      const tableRow = document.createElement("tr");
      (Array.isArray(row?.cells) ? row.cells : []).forEach((cell) => {
        const tableCell = document.createElement(rowIndex === 0 ? "th" : "td");
        if (rowIndex === 0) tableCell.scope = "col";
        tableCell.textContent = String(cell?.text || "");
        const rowSpan = Number(cell?.rowSpan || 1);
        const columnSpan = Number(cell?.columnSpan || 1);
        if (rowSpan > 1) tableCell.rowSpan = rowSpan;
        if (columnSpan > 1) tableCell.colSpan = columnSpan;
        tableRow.append(tableCell);
      });
      tableBody.append(tableRow);
    });
    table.append(tableBody);
    wrapper.append(table);
    container.append(wrapper);
  });
  return container.childElementCount ? container : null;
}

function researchDisplaySources(sources = []) {
  const displayed = [];
  const comparableText = (value) => String(value || "")
    .normalize("NFKD")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  sources.forEach((source) => {
    const sourceText = comparableText(source.selectedText || source.passageText || source.excerpt || source.snippet);
    const redundantIndex = displayed.findIndex((current) => {
      if (String(current.sectionID || "") !== String(source.sectionID || "")) return false;
      const currentText = comparableText(current.selectedText || current.passageText || current.excerpt || current.snippet);
      return Boolean(sourceText && currentText) &&
        (sourceText.includes(currentText) || currentText.includes(sourceText));
    });
    if (redundantIndex < 0) {
      displayed.push(source);
      return;
    }
    const current = displayed[redundantIndex];
    const currentText = comparableText(current.selectedText || current.passageText || current.excerpt || current.snippet);
    if (
      sourceText.length > currentText.length ||
      (source.richSourceID && !current.richSourceID)
    ) displayed[redundantIndex] = source;
  });
  return displayed;
}

function researchConversationHasSelectionOrigin(conversation) {
  const originKind = String(conversation?.origin?.kind || "");
  const originSurface = String(conversation?.origin?.surface || "");
  if (originSurface === "reader") return true;
  if (originSurface) return false;
  // Older selection-origin records did not preserve which surface created them.
  return originKind === "selectedPassage" || originKind === "selectedPassages";
}

function researchOriginExcerpt(source, limit = 280) {
  const text = String(
    source?.selectedText || source?.passageText || source?.excerpt || source?.snippet || ""
  ).replace(/\s+/g, " ").trim();
  return text.length > limit ? `${text.slice(0, limit - 1).trimEnd()}…` : text;
}

function renderReaderResearchOrigin(conversation, sources, anchorPaneID) {
  if (!sources.length) return null;
  const origin = document.createElement("section");
  origin.className = "research-reader-origin";
  origin.setAttribute("aria-label", "Starting Research evidence");
  const list = document.createElement("section");
  list.className = "research-reader-origin-list";
  sources.forEach((source) => {
    const passage = document.createElement("article");
    passage.classList.add(`code-theme-${codeTheme(source.codePrefix || "BC")}`);
    const passageHeader = document.createElement("div");
    const reference = document.createElement("button");
    reference.type = "button";
    reference.className = "research-reader-origin-open";
    const prefix = String(source.codePrefix || "").trim();
    const sectionNumber = String(source.sectionNumber || "").trim();
    reference.textContent = [prefix, sectionDisplayTitle(sectionNumber, source.title, "Selected code passage")]
      .filter(Boolean)
      .join(" ") || source.title || "Selected code passage";
    reference.setAttribute("aria-label", `Open ${reference.textContent}`);
    reference.addEventListener("click", () => {
      void openSourceInReader(
        source,
        anchorPaneID,
        { projectID: conversation.primaryProjectID || "" }
      );
    });
    const edition = document.createElement("span");
    edition.className = "research-origin-edition";
    edition.textContent = researchCodeEdition(source);
    passageHeader.append(reference);
    passageHeader.append(edition);
    const excerpt = document.createElement("blockquote");
    excerpt.textContent = researchOriginExcerpt(source);
    passage.append(passageHeader, excerpt);
    list.append(passage);
  });
  origin.append(list);
  return origin;
}

function researchSourcesForAnswer(conversation, message) {
  const answer = message?.answer || {};
  const answerSources = [
    ...(Array.isArray(message?.sources) ? message.sources : []),
    ...(Array.isArray(answer.sources) ? answer.sources : []),
    ...(Array.isArray(answer.supportingSources) ? answer.supportingSources : [])
  ];
  const conversationSources = Array.isArray(conversation?.sources) ? conversation.sources : [];
  const available = researchDisplaySources(conversationSources);
  const sourceIDs = new Set([
    ...(answer.evidenceSourceIDs || []),
    ...(answer.sourceIDs || [])
  ].map(String));
  const citedSections = new Set((answer.citations || []).flatMap((citation) => [
    citation.sectionID,
    citation.sectionNumber
  ]).filter(Boolean).map(String));
  const matchedConversationSources = available.filter((source) =>
    sourceIDs.has(String(source.id || "")) ||
    sourceIDs.has(String(source.sourceID || "")) ||
    citedSections.has(String(source.sectionID || "")) ||
    citedSections.has(String(source.sectionNumber || ""))
  );
  const fallbackConversationSources = sourceIDs.size || citedSections.size ? [] : available;
  return researchDisplaySources([
    ...answerSources,
    ...(matchedConversationSources.length ? matchedConversationSources : fallbackConversationSources)
  ]);
}

function renderResearchAnswerSources(conversation, message, anchorPaneID) {
  const answerSources = researchSourcesForAnswer(conversation, message);
  if (!answerSources.length && !message?.id) return null;
  const details = document.createElement("details");
  details.className = "research-answer-source-text";
  const summary = document.createElement("summary");
  const sourceCount = Math.max(
    answerSources.length,
    message?.answer?.evidenceSourceIDs?.length || 0,
    message?.answer?.citations?.length || 0
  );
  const evidenceEconomy = message?.answer?.answerQuality?.evidenceEconomy || {};
  const citedSourceCount = Number(evidenceEconomy.citedSourceCount || 0);
  const reviewedOnlySourceCount = Number(evidenceEconomy.reviewedOnlySourceCount || 0);
  const sourceSummaryText = () => citedSourceCount
    ? [
        `${citedSourceCount} ${citedSourceCount === 1 ? "source" : "sources"} cited`,
        reviewedOnlySourceCount
          ? `${reviewedOnlySourceCount} additional ${reviewedOnlySourceCount === 1 ? "source" : "sources"} reviewed`
          : ""
      ].filter(Boolean).join(" · ")
    : sourceCount
      ? `${sourceCount} ${sourceCount === 1 ? "source" : "sources"} used`
      : "Sources used";
  summary.textContent = sourceSummaryText();
  const list = document.createElement("section");
  list.className = "research-answer-source-list";
  const renderSourceGroup = (label, sources, className) => {
    if (!sources.length) return;
    const group = document.createElement("section");
    group.className = `research-answer-source-group ${className}`;
    const heading = document.createElement("header");
    heading.className = "research-answer-source-group-heading";
    const title = document.createElement("strong");
    title.textContent = label;
    heading.append(title);
    const items = document.createElement("section");
    items.className = "research-answer-source-group-items";
    sources.forEach((source, index) => {
      const card = renderResearchSource(source, {
        openInReader: true,
        anchorPaneID,
        projectID: conversation.primaryProjectID || ""
      });
      const number = document.createElement("span");
      number.className = "research-answer-source-number";
      number.setAttribute("aria-hidden", "true");
      number.textContent = `${index + 1}.`;
      card.prepend(number);
      items.append(card);
    });
    group.append(heading, items);
    list.append(group);
  };
  const renderSourceGroups = ({ cited = [], reviewed = [] }) => {
    clear(list);
    renderSourceGroup("Cited in this answer", cited, "is-cited");
    renderSourceGroup("Reviewed for context — not cited", reviewed, "is-reviewed");
  };
  const splitSourcesByCitation = (sources, answer = {}) => {
    const answerQuality = answer.answerQuality || answer.quality || {};
    const citedSourceIDs = new Set([
      ...(answerQuality.citedSourceIDs || []),
      ...(answer.citations || []).flatMap((citation) => citation.sourceIDs || [])
    ].filter(Boolean).map(String));
    const reviewedSourceIDs = new Set((answerQuality.reviewedOnlySourceIDs || [])
      .filter(Boolean)
      .map(String));
    const citedSections = new Set((answer.citations || [])
      .map((citation) => citation.sectionID)
      .filter(Boolean)
      .map(String));
    if (!citedSourceIDs.size && !citedSections.size) return { cited: sources, reviewed: [] };
    const sourceIsCited = (source) => citedSourceIDs.size
      ? citedSourceIDs.has(String(source.id || "")) ||
        citedSourceIDs.has(String(source.sourceID || ""))
      : citedSections.has(String(source.sectionID || ""));
    const sourceIsReviewedOnly = (source) =>
      reviewedSourceIDs.has(String(source.id || "")) ||
      reviewedSourceIDs.has(String(source.sourceID || ""));
    return {
      cited: sources.filter((source) => !sourceIsReviewedOnly(source) && sourceIsCited(source)),
      reviewed: sources.filter((source) => sourceIsReviewedOnly(source) || !sourceIsCited(source))
    };
  };
  renderSourceGroups(splitSourcesByCitation(answerSources, message?.answer));
  let loaded = false;
  if (openTrashAfterSettingsDeletion) { details.open = true; openTrashAfterSettingsDeletion = false; }
  details.addEventListener("toggle", async () => {
    if (!details.open || loaded || !message?.id) return;
    loaded = true;
    const loading = document.createElement("p");
    loading.className = "research-list-status";
    loading.textContent = "Loading the exact saved sources…";
    list.append(loading);
    try {
      const payload = await postResearch("/research/answers/get", { answerID: message.id });
      const answerRecord = payload.answer || {};
      const enactedSources = (answerRecord.evidence || []).map((source) => ({
        ...source,
        id: source.sourceID || source.id,
        kind: source.provenance?.origin || source.origin || "enacted_permitext_discovered",
        relationship: source.provenance?.relationship || source.relationship,
        userSelectedText: source.provenance?.userSelectedText || "",
        codePrefix: source.codeBook || source.codePrefix,
        codeVersion: source.sourceLibraryVersion || source.codeVersion,
        evidencePriority: source.provenance?.evidenceRole
          ? {
              evidenceRole: source.provenance.evidenceRole,
              primaryFunction: source.provenance.evidenceFunction || null
            }
          : null,
        selectedText: source.passageText || source.selectedText
      }));
      const supportingSources = answerRecord.answer?.supportingSources || answerRecord.supportingSources || [];
      const exactSources = researchDisplaySources([...enactedSources, ...supportingSources]);
      if (exactSources.length) {
        const exactAnswer = answerRecord.answer || {};
        renderSourceGroups(splitSourcesByCitation(exactSources, exactAnswer));
        summary.textContent = sourceSummaryText();
      } else {
        renderSourceGroups({ cited: answerSources });
        if (!answerSources.length) list.textContent = "The exact source record is unavailable.";
      }
    } catch (error) {
      loaded = false;
      renderSourceGroups({ cited: answerSources });
      const failure = document.createElement("p");
      failure.className = "research-list-status is-error";
      failure.textContent = error.message || "The exact source record could not be loaded.";
      list.append(failure);
    }
  });
  details.append(summary, list);
  wireResearchDetailsMotion(details, list);
  return details;
}

function appendHistoricalResearchList(container, title, items = []) {
  if (!items.length) return;
  const heading = document.createElement("strong");
  heading.textContent = title;
  const list = document.createElement("ul");
  items.forEach((item) => {
    const row = document.createElement("li");
    row.textContent = item;
    list.append(row);
  });
  container.append(heading, list);
}

function renderHistoricalResearchRecord(container, answerRecord) {
  clear(container);
  const record = document.createElement("article");
  record.className = "research-historical-record";
  const heading = document.createElement("div");
  heading.className = "research-historical-heading";
  const title = document.createElement("strong");
  title.textContent = "Saved Research record";
  const meta = document.createElement("span");
  meta.textContent = [
    researchRelativeDate(answerRecord.createdAt),
    answerRecord.projectID ? researchProjectName(answerRecord.projectID) : "No Project at answer time",
    answerRecord.model
  ].filter(Boolean).join(" · ");
  heading.append(title, meta);

  const questionLabel = document.createElement("strong");
  questionLabel.textContent = "Exact stored question";
  const question = document.createElement("p");
  question.className = "research-historical-question";
  question.textContent = answerRecord.question;

  const exactAnswer = document.createElement("section");
  exactAnswer.className = "research-historical-answer";
  renderResearchInterpretation(exactAnswer, answerRecord.answer, { detailsOpen: true, recordQuestion: answerRecord.question,
    recordMessage: researchAnswerHasVerificationRecovery(answerRecord.answer) ? { id: answerRecord.id, answer: answerRecord.answer } : null, conversationID: answerRecord.conversationID });

  const evidenceHeading = document.createElement("strong");
  evidenceHeading.textContent = "Cited evidence snapshots";
  const evidenceList = document.createElement("section");
  evidenceList.className = "research-historical-evidence";
  (answerRecord.evidence || []).forEach((evidence) => {
    const evidenceCard = document.createElement("article");
    const citation = document.createElement("strong");
    citation.textContent = `${evidence.codeBook} § ${evidence.sectionNumber}`;
    const evidenceMeta = document.createElement("span");
    evidenceMeta.textContent = `${evidence.codeEdition} · Library ${evidence.sourceLibraryVersion}`;
    const quote = document.createElement("blockquote");
    quote.textContent = evidence.passageText;
    const hash = document.createElement("code");
    hash.textContent = `SHA-256 ${evidence.passageTextHash}`;
    evidenceCard.append(citation, evidenceMeta, quote, hash);
    const visualEvidence = renderResearchVisualEvidence(
      evidence.visualSources,
      { immutable: true }
    );
    if (visualEvidence) evidenceCard.append(visualEvidence);
    evidenceList.append(evidenceCard);
  });

  const evidenceBySnapshotID = new Map(
    (answerRecord.evidence || []).map((evidence) => [evidence.id, evidence])
  );
  const mapping = (answerRecord.passageToCitationMapping || []).map((item) => {
    const snapshotCount = item.evidenceSnapshotIDs?.length || 0;
    const sourceLabels = Array.from(new Set(
      (item.evidenceSnapshotIDs || []).map((snapshotID) => {
        const evidence = evidenceBySnapshotID.get(snapshotID);
        return evidence
          ? `${evidence.codeBook} § ${evidence.sectionNumber}`
          : `Source ${snapshotID}`;
      })
    ));
    return `${sourceLabels.join(", ")}: ${snapshotCount} cited ${snapshotCount === 1 ? "snapshot" : "snapshots"} — ${item.relevance || "Cited support"}`;
  });
  const mappingWrap = document.createElement("section");
  mappingWrap.className = "research-historical-mapping";
  appendHistoricalResearchList(mappingWrap, "Passage-to-citation mapping", mapping);

  const reuse = document.createElement("section");
  reuse.className = "research-historical-reuse";
  const reuseHeading = document.createElement("strong");
  reuseHeading.textContent = "Start fresh from this cited evidence";
  const reuseCopy = document.createElement("p");
  reuseCopy.textContent = "This creates a new, empty Research conversation. It rechecks the passage against the current enacted library and does not copy the old question, answer, assumptions, or additional Research facts.";
  const reuseControls = document.createElement("div");
  reuseControls.className = "research-historical-reuse-controls";
  const projectSelect = createResearchProjectSelect({
    value: preferredResearchProjectID(),
    includeUnassigned: false,
    ariaLabel: "Project for reused evidence"
  });
  const reuseButton = document.createElement("button");
  reuseButton.className = "ghost-button";
  reuseButton.type = "button";
  reuseButton.textContent = "Start new Research";
  reuseButton.disabled = !hasCapability("research");
  if (reuseButton.disabled) reuseButton.title = "Pro required for Research";
  reuseButton.disabled = !projectSelect.value;
  const reuseStatus = document.createElement("p");
  reuseStatus.className = "research-historical-status";
  projectSelect.addEventListener("change", () => {
    reuseButton.disabled = !projectSelect.value;
  });
  reuseButton.addEventListener("click", async () => {
    if (!projectSelect.value) return;
    reuseButton.disabled = true;
    projectSelect.disabled = true;
    reuseStatus.textContent = "Rechecking the cited evidence…";
    try {
      const payload = await postResearch("/research/conversations/reuse-evidence", {
        answerID: answerRecord.id,
        projectID: projectSelect.value
      });
      await refreshResearchConversationList();
      await openResearchConversation(payload.conversation.id, { refreshList: true });
    } catch (error) {
      reuseStatus.textContent = error.message;
      projectSelect.disabled = false;
      reuseButton.disabled = !projectSelect.value;
    }
  });
  reuseControls.append(projectSelect, reuseButton);
  reuse.append(reuseHeading, reuseCopy, reuseControls, reuseStatus);

  record.append(
    heading,
    questionLabel,
    question,
    exactAnswer,
    evidenceHeading,
    evidenceList,
    mappingWrap,
    reuse
  );
  container.append(record);
}

function renderHistoricalResearchControl(container, message) {
  if (!message?.id) return;
  const details = document.createElement("details");
  details.className = "research-historical-details";
  const summary = document.createElement("summary");
  summary.textContent = "Open exact historical record";
  const body = document.createElement("section");
  body.className = "research-historical-body";
  let loaded = false;
  details.addEventListener("toggle", async () => {
    if (!details.open || loaded) return;
    loaded = true;
    body.textContent = "Loading the saved record…";
    try {
      const payload = await postResearch("/research/answers/get", { answerID: message.id });
      renderHistoricalResearchRecord(body, payload.answer);
    } catch (error) {
      loaded = false;
      body.textContent = error.message;
    }
  });
  details.append(summary, body);
  container.append(details);
}

function renderResearchProjectContext(container, conversation) {
  const section = document.createElement("section");
  section.className = "research-project-context";
  container.append(section);
  return section;
}

function researchEvidenceSplitRatio(conversationID) {
  return normalizeResearchEvidenceSplitRatio(state.researchEvidenceSplitRatios?.[conversationID]);
}

function researchMessageCaptureBasis(conversationID, messageID) {
  return `Captured from Research ${conversationID} message ${messageID}`;
}

function researchAnswerQuestion(conversation, message) {
  const messages = Array.isArray(conversation.messages) ? conversation.messages : [];
  const index = messages.findIndex((item) => item === message || item.id === message.id);
  const preceding = index >= 0 ? messages.slice(0, index) : [];
  const requestID = message.requestID || message.researchRequestID;
  const matching = requestID ? preceding.findLast((item) => item.role === "user" &&
    (item.requestID || item.researchRequestID) === requestID) : null;
  const question = matching || preceding.findLast((item) => item.role === "user");
  return String(question?.question || message.question || conversation.starterQuestion || researchConversationTitle(conversation)).trim();
}

function renderResearchNotebookHandoff(conversation, message) {
  if (!message.id || !message.answer || !hasCapability("notebook")) return null;
  const region = document.createElement("div");
  region.className = "research-notebook-handoff";
  const projects = researchProjects();
  const select = document.createElement("select");
  select.setAttribute("aria-label", "Project for this Assistant answer");
  const projectID = String(conversation.primaryProjectID || "");
  const choices = projectID ? projects.filter((project) => researchProjectID(project) === projectID) : projects;
  choices.forEach((project) => {
    const option = document.createElement("option"); option.value = researchProjectID(project);
    option.textContent = readableProjectName(project); select.append(option);
  });
  select.hidden = Boolean(projectID);
  const button = document.createElement("button");
  button.type = "button";
  button.className = "ghost-button";
  button.textContent = "Add to note";
  button.disabled = !choices.length;
  if (!choices.length) button.title = "Create or restore a Project to keep this Research reference in Notebook.";
  const mutationID = `research-reference:${crypto.randomUUID()}`;
  let savedCard = null;
  button.addEventListener("click", async () => {
    const requestIdentity = captureAccountRequest();
    const originPaneID = region.closest(".workspace-panel")?.dataset.paneId;
    const originWorkspaceID = activeWorkspaceID;
    const originWorkflowGeneration = state.workflowNavigationGeneration || 0;
    const originIsCurrent = () => isCurrentAccountRequest(requestIdentity) && region.isConnected &&
      activeWorkspaceID === originWorkspaceID &&
      originWorkflowGeneration === (state.workflowNavigationGeneration || 0);
    const project = choices.find((item) => researchProjectID(item) === select.value);
    if (!project) return;
    const title = researchAnswerQuestion(conversation, message).slice(0, 300);
    const currentMount = notebookMounts.get(researchProjectID(project));
    const currentNote = currentMount?.insertionTarget?.();
    if (!savedCard && currentNote) {
      const destination = await openWebWarning({ title: "Add to note", message: "Choose where to keep this Assistant answer.",
        confirmLabel: "Add to note", choiceLabel: "Destination Note", container: region,
        choices: [{ value: "current", label: currentNote.title || "Untitled Note" }, { value: "new", label: "New Note" }] });
      if (!destination || !originIsCurrent()) return;
      if (destination === "current") {
        button.disabled = true;
        try {
          await currentMount.insertLinkedReference(currentNote.id, {
            referenceKind: "researchAnswer", referenceID: message.id, label: `Research: ${title}`
          });
          if (originIsCurrent()) button.textContent = "Added to note";
        } catch (error) {
          if (originIsCurrent()) await showWebNotice("Note not updated", error.message);
        } finally {
          if (originIsCurrent()) button.disabled = false;
        }
        return;
      }
    }
    if (!savedCard && !currentNote && !await confirmWebWarning("Keep this Research reference in Notebook?",
      `Project: ${readableProjectName(project)}\n\n${title}\n\nThe new Note links to the exact saved answer and its cited sources. Review the answer before writing your own conclusion.`,
      { confirmLabel: "Create reference Note", container: region })) return;
    if (!originIsCurrent()) return;
    button.disabled = true;
    select.disabled = true;
    try {
      if (!savedCard) {
        if (navigator.onLine === false) throw new Error("Reconnect to create this Note. The saved Research answer remains available.");
        const document = emptyNotebookDocument();
        document.document = [{ type: "paragraph", content: [{ type: "permitextReference", props: {
          referenceKind: "researchAnswer", referenceID: message.id, label: `Research: ${title}`
        } }] }];
        const payload = await postResearch("/notebook/cards/save", { projectID: researchProjectID(project),
          clientMutationID: mutationID, expectedVersion: 0, cardType: "finding", title, document, evidenceLinks: [] });
        requireCurrentAccountRequest(requestIdentity);
        savedCard = payload.card;
        await saveNotebookCardSnapshot(requestIdentity.userID, researchProjectID(project), savedCard);
      }
      requireCurrentAccountRequest(requestIdentity);
      if (!originIsCurrent()) return;
      pendingNotebookCardByProject.set(researchProjectID(project), savedCard.id);
      if (researchWorkspaceProjectID() !== researchProjectID(project)) {
        reconcileProjectWorkspaces();
        const target = workspaceRegistry.workspaces.find((item) => item.projectID === projectRecordID(project));
        if (!target || !await switchWorkspace(target.id, { focus: false })) return;
        requireCurrentAccountRequest(requestIdentity);
      }
      const destinationWorkspaceID = activeWorkspaceID;
      const destinationWorkflowGeneration = state.workflowNavigationGeneration || 0;
      const destinationIsCurrent = () => isCurrentAccountRequest(requestIdentity) &&
        activeWorkspaceID === destinationWorkspaceID &&
        destinationWorkflowGeneration === (state.workflowNavigationGeneration || 0);
      if (originWorkspaceID === activeWorkspaceID) requestLinkedPanePlacement(originPaneID, paneIDForProjectNotebook(project));
      if (!await openProjectNotebook(project)) return;
      if (!destinationIsCurrent() || !await whenWorkspacePaneReady(paneIDForProjectNotebook(project)) || !destinationIsCurrent()) return;
      const mount = notebookMounts.get(researchProjectID(project));
      await mount?.refreshCards?.();
      if (!destinationIsCurrent()) return;
      if (mount?.activeCardID?.() !== savedCard.id) await mount?.focusCard?.(savedCard.id);
      if (mount?.activeCardID?.() === savedCard.id) pendingNotebookCardByProject.delete(researchProjectID(project));
      button.textContent = "Open reference Note";
    } catch (error) {
      if (originIsCurrent()) await showWebNotice("Notebook handoff not completed", error.message);
    } finally {
      if (savedCard && !originIsCurrent() && pendingNotebookCardByProject.get(researchProjectID(project)) === savedCard.id) {
        pendingNotebookCardByProject.delete(researchProjectID(project));
      }
      if (isCurrentAccountRequest(requestIdentity)) { button.disabled = false; select.disabled = Boolean(savedCard); }
    }
  });
  region.append(select, button);
  if (hasCapability("professional-exports")) {
    const reportButton = document.createElement("button");
    reportButton.type = "button";
    reportButton.className = "workflow-action workflow-action-secondary";
    reportButton.textContent = "Add to Report";
    reportButton.disabled = !choices.length;
    const refreshMembership = () => {
      reportButton.setAttribute("data-report-membership-mode", "action");
      reportButton.setAttribute("data-report-membership-project", select.value);
      reportButton.setAttribute("data-report-source-kind", "researchAnswer");
      reportButton.setAttribute("data-report-source-id", message.id);
      window.requestAnimationFrame(() => { if (reportButton.isConnected) void refreshProjectReportMembership(select.value); });
    };
    select.addEventListener("change", refreshMembership);
    refreshMembership();
    reportButton.addEventListener("click", async () => {
      const project = choices.find(item => researchProjectID(item) === select.value);
      if (!project) return;
      const requestIdentity = captureAccountRequest();
      const workspaceID = activeWorkspaceID;
      reportButton.disabled = true;
      try {
        const draft = await addProjectSourcesToReport(project, sources => {
          const source = sources.find(item => item.kind === "researchAnswer" && item.id === message.id);
          if (!source) throw new Error("Link this Assistant conversation to the selected Project before adding its answer to a Report.");
          return [source];
        });
        if (!draft) return;
        if (isCurrentAccountRequest(requestIdentity) && workspaceID === activeWorkspaceID && reportButton.isConnected) {
          reportButton.textContent = "In Report";
          reportButton.title = `Included in ${draft.title || "Report"}`;
        }
      } catch (error) {
        if (isCurrentAccountRequest(requestIdentity) && workspaceID === activeWorkspaceID && region.isConnected) {
          await showWebNotice("Report handoff not completed", error.message);
        }
      } finally {
        if (isCurrentAccountRequest(requestIdentity) && reportButton.isConnected) reportButton.disabled = !choices.length;
      }
    });
    region.append(reportButton);
  }
  return region;
}

function renderResearchMessageCapture(conversation, message) {
  const questionID = String(conversation.linkedCodeDecisionID || "").trim();
  const activeQuestionID = String(codeQuestionWorkspaceState().activeQuestionID || "").trim();
  if (
    !questionID || questionID !== activeQuestionID ||
    conversation.primaryProjectID !== activeProjectIDForCodeQuestions()
  ) return null;
  const basis = researchMessageCaptureBasis(conversation.id, message.id);
  const existing = (getDefinitionForQuestion(questionID)?.inputs || [])
    .find((input) => input.basis === basis);
  if (existing) return null;
  const region = document.createElement("div");
  region.className = "research-message-capture";
  const status = document.createElement("p");
  status.className = "research-message-capture-status";
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  const canCapture = ["owner", "editor"].includes(codeQuestionDefineRole());
  const label = document.createElement("span");
  label.textContent = "Capture for analysis";
  const actions = document.createElement("div");
  actions.className = "research-message-capture-actions";
  const choices = [
    { label: "Confirm fact", kind: "confirmedFact", state: "confirmed", disposition: "project-fact" },
    { label: "Keep as assumption", kind: "assumption", state: "proposed", disposition: "assumption" },
    { label: "Track missing", kind: "unknown", state: "proposed", disposition: "missing-information" }
  ];
  const buttons = choices.map((choice) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = choice.label;
    button.disabled = !canCapture;
    if (!canCapture) button.title = "An Owner or Editor can capture professional analysis inputs";
    button.addEventListener("click", async () => {
      buttons.forEach((item) => { item.disabled = true; });
      status.textContent = "Capturing in the analysis record…";
      const inputID = `research-message:${conversation.id}:${message.id}`;
      const actor = codeQuestionActor();
      try {
        const result = await executeCodeQuestionMutation("/projects/code-questions/inputs/save", {
          projectID: conversation.primaryProjectID,
          questionID,
          id: inputID,
          kind: choice.kind,
          state: choice.state,
          statement: message.question,
          basis,
          researchSource: {
            conversationID: conversation.id,
            messageID: message.id,
            disposition: choice.disposition
          }
        }, {
          commandKind: "codeQuestion.input.save",
          projectID: conversation.primaryProjectID,
          questionID,
          clientMutationID: `capture:${inputID}`,
          applyOptimistic: () => saveDefinitionForQuestion(questionID, createQuestionInput(
            getDefinitionForQuestion(questionID),
            {
              id: inputID,
              inputKind: choice.kind,
              state: choice.state,
              statement: message.question,
              basis,
              actorUserID: actor.userID,
              responsibleDisplayName: actor.displayName
            }
          ))
        });
        refreshCodeDecisionPrimaryPanes(questionID);
        if (result.queued) {
          status.textContent = "Capture queued. It will be validated against the linked Research message after reconnecting.";
        } else {
          region.remove();
        }
      } catch (error) {
        status.textContent = error.message || "This message could not be captured.";
        buttons.forEach((item) => { item.disabled = !canCapture; });
      }
    });
    return button;
  });
  actions.append(...buttons);
  region.append(label, actions, status);
  return region;
}

function bindResearchEvidenceDivider(layout, divider, conversationID) {
  const applyRatio = (value) => {
    const desiredRatio = normalizeResearchEvidenceSplitRatio(value);
    state.researchEvidenceSplitRatios ||= {};
    state.researchEvidenceSplitRatios[conversationID] = desiredRatio;
    const bounds = layout.getBoundingClientRect();
    const dividerHeight = divider.offsetHeight || 17;
    const availableHeight = Math.max(0, bounds.height - dividerHeight);
    const composerHeight = layout.querySelector(".research-composer")?.offsetHeight || 0;
    const minimumEvidenceHeight = Math.min(96, Math.max(56, availableHeight * 0.2));
    const minimumDialogueHeight = Math.min(
      Math.max(140, composerHeight + 40),
      Math.max(100, availableHeight - minimumEvidenceHeight)
    );
    const minimumRatio = bounds.height
      ? Math.min(0.45, Math.max(0.12, minimumEvidenceHeight / bounds.height))
      : 0.2;
    const maximumRatio = bounds.height
      ? Math.min(0.7, Math.max(minimumRatio + 0.02, (availableHeight - minimumDialogueHeight) / bounds.height))
      : 0.7;
    const displayedRatio = clampNumber(desiredRatio, minimumRatio, maximumRatio, 0.36);
    layout.style.setProperty("--research-evidence-size", `${displayedRatio * 100}%`);
    divider.setAttribute("aria-valuemin", String(Math.round(minimumRatio * 100)));
    divider.setAttribute("aria-valuemax", String(Math.round(maximumRatio * 100)));
    divider.setAttribute("aria-valuenow", String(Math.round(displayedRatio * 100)));
  };
  applyRatio(researchEvidenceSplitRatio(conversationID));
  requestAnimationFrame(() => applyRatio(researchEvidenceSplitRatio(conversationID)));

  const resize = (event) => {
    const bounds = layout.getBoundingClientRect();
    if (!bounds.height) return;
    applyRatio((event.clientY - bounds.top) / bounds.height);
  };
  const endResize = (event) => {
    divider.classList.remove("is-dragging");
    document.body.classList.remove("is-resizing-research-evidence");
    if (divider.hasPointerCapture?.(event.pointerId)) {
      divider.releasePointerCapture(event.pointerId);
    }
    saveWorkspaceState();
    window.removeEventListener("pointermove", resize);
    window.removeEventListener("pointerup", endResize);
    window.removeEventListener("pointercancel", endResize);
  };

  divider.addEventListener("pointerdown", (event) => {
    if (event.isPrimary === false || event.button !== 0) return;
    event.preventDefault();
    divider.setPointerCapture?.(event.pointerId);
    divider.classList.add("is-dragging");
    document.body.classList.add("is-resizing-research-evidence");
    resize(event);
    window.addEventListener("pointermove", resize);
    window.addEventListener("pointerup", endResize);
    window.addEventListener("pointercancel", endResize);
  });
  divider.addEventListener("dblclick", () => {
    applyRatio(0.36);
    saveWorkspaceState();
  });
  divider.addEventListener("keydown", (event) => {
    const direction = event.key === "ArrowUp" ? -1 : event.key === "ArrowDown" ? 1 : 0;
    if (!direction && event.key !== "Home" && event.key !== "End") return;
    event.preventDefault();
    const ratio = event.key === "Home"
      ? 0.2
      : event.key === "End"
        ? 0.7
        : researchEvidenceSplitRatio(conversationID) + direction * 0.04;
    applyRatio(ratio);
    saveWorkspaceState();
  });
}

async function renderResearchConversation(conversationID, options = {}) {
  if (!hasCapability("research")) return renderProLockedPane(`research:conversation:${conversationID}`, "Assistant");
  const ownerInstance = Object.hasOwn(options, "ownerInstance")
    ? options.ownerInstance
    : (state.utilityInstances || []).find((item) => item.key === "analysis" && item.conversationID === conversationID);
  const embedded = options.embedded === true;
  const supplemental = options.supplemental === true;
  const paneID = options.paneID || (ownerInstance ? paneIDForUtilityInstance(ownerInstance) : paneIDForResearchConversation(conversationID));
  const renderingAccount = activeAccount();
  const renderingContext = {
    generation: researchOpenGeneration,
    accountUserID: renderingAccount?.userID || "",
    sessionToken: renderingAccount?.sessionToken || "",
    projectID: activeProjectIDForCodeQuestions(),
    conversationID
  };
  const panel = document.createElement(embedded ? "section" : "article");
  panel.className = embedded
    ? "research-conversation-embedded"
    : "workspace-panel utility-panel research-conversation-panel";
  if (!embedded) applyPaneWeight(panel, paneID);
  const header = document.createElement("header");
  header.className = "panel-header";
  const headingWrap = document.createElement("div");
  const eyebrow = document.createElement("p");
  eyebrow.className = "eyebrow panel-kind";
  eyebrow.textContent = "Assistant";
  const panelTitle = document.createElement("h2");
  panelTitle.className = "panel-title";
  panelTitle.tabIndex = -1;
  panelTitle.textContent = "Loading…";
  headingWrap.append(eyebrow, panelTitle);
  const closeButton = document.createElement("button");
  closeButton.className = "icon-button utility-close";
  closeButton.type = "button";
  closeButton.title = "Close conversation";
  closeButton.setAttribute("aria-label", "Close conversation");
  closeButton.innerHTML = circleXIconSVG();
  closeButton.addEventListener("click", () => closeResearchConversation(conversationID));
  const actions = document.createElement("div");
  actions.className = "panel-actions";
  actions.append(closeButton);
  header.append(headingWrap, actions);
  const content = document.createElement("section");
  content.className = "research-conversation-content";
  content.classList.toggle(
    "is-evidence-pane-deferred",
    !releaseSurfaceVisibility.researchConversationEvidencePane
  );
  panel.append(...(embedded ? [content] : [header, content]));

  let conversation = null;
  try {
    const supplementalConversation = supplementalResearchConversations.get(conversationID);
    const alreadyLoaded = activeResearchConversation?.id === conversationID &&
      Array.isArray(activeResearchConversation.messages) &&
      Array.isArray(activeResearchConversation.sources);
    conversation = supplemental && supplementalConversation
      ? supplementalConversation
      : alreadyLoaded
        ? activeResearchConversation
        : await fetchAuthoritativeResearchConversation(conversationID);
  } catch (error) {
    const status = document.createElement("p");
    status.className = "research-list-status is-error";
    status.textContent = error.message;
    content.append(status);
    return panel;
  }
  if (!supplemental && !researchOpenContextIsCurrent(renderingContext, { requireConversationID: true })) return panel;
  if (!researchConversationInWorkspace(conversation)) {
    panelTitle.textContent = "Research belongs to another workspace";
    const notice = document.createElement("p");
    notice.className = "research-list-status";
    notice.textContent = "Open this conversation in its project workspace. Its project assignment has not changed.";
    content.append(notice);
    return panel;
  }
  if (supplemental && !supplementalResearchConversationIDs.includes(conversationID)) {
    if (!(state.utilityInstances || []).some((item) => item.conversationID === conversationID)) return panel;
    supplementalResearchConversationIDs.push(conversationID);
  }
  if (supplemental) supplementalResearchConversations.set(conversationID, conversation);
  else activeResearchConversation = conversation;

  const activeCodeQuestionProjectID = activeProjectIDForCodeQuestions();
  const linkedQuestion = questionsForActiveProject().find((item) =>
    item.id === conversation.linkedCodeDecisionID
  );
  const exactLinkedDecision = Boolean(
    conversation.linkedCodeDecisionID &&
    conversation.primaryProjectID === activeCodeQuestionProjectID &&
    linkedQuestion?.researchConversationID === conversation.id
  );
  if (!supplemental && codeQuestionWorkspaceEnabled() && activeCodeQuestionProjectID) {
    if (exactLinkedDecision) {
      const cq = codeQuestionWorkspaceState();
      if (cq.activeQuestionID !== conversation.linkedCodeDecisionID) {
        setCodeQuestionWorkspaceState(
          openCodeDecisionSurface(cq, {
            projectID: conversation.primaryProjectID,
            questionID: conversation.linkedCodeDecisionID,
            questionText: conversation.starterQuestion || "",
            researchConversationID: conversation.id
          }),
          { activeProjectID: conversation.primaryProjectID, syncDeepLink: true }
        );
        requestAnimationFrame(() => {
          if (state.researchConversationID === conversation.id) void renderWorkspace({ persist: false });
        });
      } else {
        alignResearchConversationWithCodeDecision(conversation.linkedCodeDecisionID, conversation.id);
      }
    } else if (codeQuestionWorkspaceState().activeQuestionID) {
      setCodeQuestionWorkspaceState(
        switchCodeQuestionProject(codeQuestionWorkspaceState(), activeCodeQuestionProjectID),
        { activeProjectID: activeCodeQuestionProjectID, syncDeepLink: true }
      );
      requestAnimationFrame(() => {
        if (state.researchConversationID === conversation.id) void renderWorkspace({ persist: false });
      });
    }
  }
  applyProjectDerivedPaneTheme(panel, conversation.primaryProjectID);
  const summaryConversation = researchConversationList.find((item) => item.id === conversation.id);
  panelTitle.textContent = researchConversationTitle(conversation, researchConversationTitle(summaryConversation));
  if (!embedded && !researchWorkspaceProjectID()) {
    const projectSelect = createResearchProjectSelect({
      value: conversation.primaryProjectID || "",
      unassignedLabel: "Unassigned",
      ariaLabel: "Project for this Research conversation"
    });
    projectSelect.classList.add("research-conversation-header-project");
    projectSelect.disabled = !hasCapability("research");
    projectSelect.title = conversation.primaryProjectID
      ? `This conversation is in ${researchProjectName(conversation.primaryProjectID)}`
      : "Not assigned to a Project";
    projectSelect.addEventListener("change", async () => {
      const previousProjectID = conversation.primaryProjectID || "";
      const targetProjectID = projectSelect.value;
      if (targetProjectID === previousProjectID) return;
      projectSelect.disabled = true;
      try {
        const payload = await assignResearchConversationProject(conversation, targetProjectID, {
          warningContainer: panel
        });
        if (!payload) {
          projectSelect.value = previousProjectID;
          projectSelect._syncCustomSelect?.();
          return;
        }
        conversation = { ...conversation, ...payload.conversation };
        if (supplemental) supplementalResearchConversations.set(conversationID, conversation);
        else activeResearchConversation = conversation;
        researchConversationList = researchConversationList.map((item) =>
          item.id === conversation.id ? { ...item, ...conversation } : item
        );
        await refreshResearchProjectAssignmentConsumers([previousProjectID, targetProjectID]);
        const projectPaneIDs = openProjectDetails().map((detail) => paneIDForProjectDetail(detail));
        await transitionWorkspace("utility", {
          refreshPaneIDs: ["utility:analysis", paneID, ...projectPaneIDs]
        });
      } catch (error) {
        projectSelect.value = previousProjectID;
        projectSelect._syncCustomSelect?.();
        projectSelect.disabled = false;
        await showWebNotice("Project not changed", error.message);
      }
    });
    actions.prepend(projectSelect);
    enhanceSelect(projectSelect);
  }
  const selectedSources = conversation.sources.filter((source) => source.kind === "selection");
  const displayedSources = researchDisplaySources(selectedSources);
  const evidencePane = document.createElement("section");
  evidencePane.className = "research-evidence-pane";
  evidencePane.hidden = !releaseSurfaceVisibility.researchConversationEvidencePane;
  const evidenceScroll = document.createElement("section");
  evidenceScroll.className = "research-evidence-scroll";
  evidenceScroll.id = `research-evidence-${conversation.id}`;
  evidencePane.append(evidenceScroll);

  const divider = document.createElement("div");
  divider.className = "research-evidence-divider";
  divider.hidden = !releaseSurfaceVisibility.researchConversationEvidencePane;
  divider.setAttribute("role", "separator");
  divider.setAttribute("aria-label", "Resize context and evidence above the conversation");
  divider.setAttribute("aria-orientation", "horizontal");
  divider.tabIndex = 0;

  const dialoguePane = document.createElement("section");
  dialoguePane.className = "research-dialogue-pane";
  let embeddedEvidenceNoticeRegion = null;
  if (embedded) {
    const selectedEvidenceNotices = document.createElement("section");
    selectedEvidenceNotices.className = "research-selected-evidence-notices";
    embeddedEvidenceNoticeRegion = selectedEvidenceNotices;
    content.append(selectedEvidenceNotices, dialoguePane);
  } else {
    content.append(evidencePane, divider, dialoguePane);
  }

  const projectContextSection = renderResearchProjectContext(evidenceScroll, conversation);
  const sources = document.createElement("section");
  sources.className = "research-sources";
  const sourceToggle = document.createElement("button");
  sourceToggle.type = "button";
  sourceToggle.className = "research-sources-toggle";
  sourceToggle.setAttribute("aria-expanded", "true");
  const sourceDisclosure = document.createElement("span");
  sourceDisclosure.className = "research-source-disclosure";
  sourceDisclosure.setAttribute("aria-hidden", "true");
  sourceDisclosure.innerHTML = researchChevronIconsSVG();
  const sourceLabel = document.createElement("span");
  sourceLabel.textContent = conversation.linkedCodeDecisionID
    ? "Research evidence · not yet approved for analysis"
    : "Research evidence";
  sourceToggle.append(sourceDisclosure, sourceLabel);
  const sourceList = document.createElement("section");
  sourceList.className = "research-source-list";
  displayedSources.forEach((source) => sourceList.append(renderResearchSource(source)));
  sources.append(sourceToggle, sourceList);
  projectContextSection.prepend(sources);
  sourceList.querySelectorAll(".research-source-card").forEach((card) =>
    setResearchSourceCardExpanded(card, true, { instant: true })
  );
  const updateSourceToggle = () => {
    const passageToggles = Array.from(sourceList.querySelectorAll(".research-source-toggle"));
    const anyExpanded = passageToggles.some((toggle) => toggle.getAttribute("aria-expanded") === "true");
    sourceToggle.setAttribute("aria-expanded", String(anyExpanded));
    sourceToggle.setAttribute("aria-label", anyExpanded ? "Collapse all passages" : "Expand all passages");
    sourceToggle.title = anyExpanded ? "Collapse all passages" : "Expand all passages";
  };
  sourceToggle.addEventListener("click", () => {
    const expandAll = sourceToggle.getAttribute("aria-expanded") !== "true";
    sourceList.querySelectorAll(".research-source-card").forEach((card) =>
      setResearchSourceCardExpanded(card, expandAll)
    );
    updateSourceToggle();
  });
  sourceList.addEventListener("click", (event) => {
    if (event.target.closest(".research-source-toggle")) requestAnimationFrame(updateSourceToggle);
  });
  updateSourceToggle();

  if (conversation.sourceStatus === "changed") {
    const warning = document.createElement("aside");
    warning.className = "research-source-warning";
    const warningText = document.createElement("p");
    warningText.textContent = "The enacted source changed after this conversation began. Rechecking updates the source metadata only when the exact selected words still exist. If the selected words changed or disappeared, start a new selection from the current Reader.";
    const refreshButton = document.createElement("button");
    refreshButton.className = "ghost-button";
    refreshButton.type = "button";
    refreshButton.textContent = "Refresh sources";
    refreshButton.disabled = !hasCapability("research");
    if (refreshButton.disabled) refreshButton.title = "Pro required for Research";
    refreshButton.addEventListener("click", async () => {
      refreshButton.disabled = true;
      try {
        const result = await postResearch("/research/conversations/refresh", { conversationID });
        activeResearchConversation = result.conversation;
        await openResearchConversation(conversationID, { refreshList: true });
      } catch (error) {
        warningText.textContent = error.message;
        refreshButton.disabled = false;
      }
    });
    warning.append(warningText, refreshButton);
    (embeddedEvidenceNoticeRegion || evidenceScroll).append(warning);
  }

  const thread = document.createElement("section");
  thread.className = "research-message-thread";
  thread.id = `research-dialogue-${conversation.id}`;
  const scrollPositionKey = `${renderingAccount?.userID || ""}:${paneID}:${conversation.id}`;
  thread.addEventListener("scroll", () => {
    if (thread.isConnected) researchThreadScrollPositions.set(scrollPositionKey, thread.scrollTop);
  }, { passive: true });
  divider.setAttribute("aria-controls", `${evidenceScroll.id} ${thread.id}`);
  const readerOrigin = renderReaderResearchOrigin(conversation, displayedSources, paneID);
  if (readerOrigin) thread.append(readerOrigin);
  const pendingProgress = reconciledResearchProgressSession(conversation);
  conversation.messages.forEach((message) => {
    if (message.role === "user") {
      const bubble = document.createElement("article");
      bubble.className = "research-message is-user";
      bubble.dataset.createdAt = message.createdAt || "";
      const messageText = document.createElement("p");
      messageText.textContent = message.question;
      bubble.append(messageText);
      if (message.failure && message.requestID !== pendingProgress?.id) {
        const failed = researchRecoveryFromFailedMessage(message, conversationID);
        if (failed) {
          const progress = { ...failed, id: failed.requestID, stages: new Map(failed.stages.map((stage) => [stage.id, stage.state])), controller: new AbortController(), timer: null };
          progress.retry = () => {
            void runResearchProgressSession(progress, recoveredResearchProgressCallbacks(conversationID, { supplemental }), { retrying: true });
          };
          bubble.append(renderResearchProgressCard(progress, {
            retryDisabled: ["active", "retrying"].includes(pendingProgress?.status)
          }));
        }
      }
      const capture = renderResearchMessageCapture(conversation, message);
      if (capture) bubble.append(capture);
      thread.append(bubble);
      return;
    }
    const bubble = document.createElement("article");
    bubble.className = "research-message is-assistant";
    bubble.dataset.createdAt = message.createdAt || "";
    const savedProgress = researchProgressFromSavedMessage(message);
    renderResearchInterpretation(bubble, message.answer, {
      message,
      conversationID,
      conversation,
      anchorPaneID: paneID
    });
    if (savedProgress) bubble.prepend(renderResearchProgressCard(savedProgress, { completed: true }));
    const answerSources = renderResearchAnswerSources(conversation, message, paneID);
    if (answerSources) {
      const evidenceReviewedBody = bubble.querySelector(".research-evidence-reviewed-body");
      (evidenceReviewedBody || bubble).append(answerSources);
    }
    const notebookHandoff = renderResearchNotebookHandoff(conversation, message);
    if (notebookHandoff) bubble.append(notebookHandoff);
    thread.append(bubble);
  });
  if (pendingProgress) {
    if (typeof pendingProgress.retry !== "function") {
      const callbacks = recoveredResearchProgressCallbacks(conversationID, { supplemental });
      pendingProgress.retry = () => void runResearchProgressSession(
        pendingProgress,
        callbacks,
        { retrying: true }
      );
    }
    const pendingQuestion = document.createElement("article");
    pendingQuestion.className = "research-message is-user is-pending";
    const pendingQuestionText = document.createElement("p");
    pendingQuestionText.textContent = pendingProgress.question;
    pendingQuestion.append(pendingQuestionText);
    const pendingAnswer = document.createElement("article");
    pendingAnswer.className = "research-message is-assistant is-pending";
    pendingAnswer.append(renderResearchProgressCard(pendingProgress));
    // Recovered failures retain their place among later completed exchanges.
    const nextMessage = [...thread.children].find((node) =>
      Date.parse(node.dataset.createdAt || "") > pendingProgress.startedAt
    );
    const pendingNodes = conversation.messages.some((message) => message.role === "user" && message.requestID === pendingProgress.id)
      ? [pendingAnswer] : [pendingQuestion, pendingAnswer];
    if (nextMessage) nextMessage.before(...pendingNodes);
    else thread.append(...pendingNodes);
    startResearchProgressTimer(pendingProgress);
  }
  dialoguePane.append(thread);

  const composer = document.createElement("form");
  composer.className = "research-composer research-compact-composer";
  const projectPreview = researchProjectContextPreview(
    conversation.primaryProjectID,
    conversation.projectInformation
  );
  const input = document.createElement("textarea");
  input.className = "research-question-input";
  input.rows = 3;
  input.maxLength = 2000;
  const starterAnalysisQuestion = conversation.messages.length === 0
    ? conversation.starterQuestion || ""
    : "";
  input.placeholder = conversation.messages.length ? "Ask a follow-up…" : displayedSources.length ? "Ask about this evidence…" : "Ask a question…";
  const followUpDraftKey = `followup:${conversationID}`;
  input.dataset.researchDraftKey = followUpDraftKey;
  input.value = researchNewChatDrafts.get(followUpDraftKey) ?? (ownerInstance?.draft || "");
  const sendButton = document.createElement("button");
  sendButton.className = "ghost-button research-send-button";
  sendButton.type = "submit";
  sendButton.textContent = "Send";
  const composerBox = document.createElement("div");
  composerBox.className = "research-composer-box";
  const projectContextBlocked = Boolean(conversation.projectContextReviewRequired);
  const researchEnabled = hasCapability("research");
  const researchRequestActive = Boolean(
    pendingProgress && ["active", "retrying"].includes(pendingProgress.status)
  );
  sendButton.disabled = !researchEnabled ||
    researchRequestActive ||
    conversation.sourceStatus === "changed" ||
    projectContextBlocked ||
    (input.value.trim() || starterAnalysisQuestion).length < 3;
  if (!researchEnabled || researchRequestActive) {
    input.disabled = true;
    if (!researchEnabled) input.placeholder = "Pro required to continue this Research conversation…";
  }
  const status = document.createElement("p");
  status.className = "research-composer-status";
  if (conversation.sourceStatus === "changed") {
    status.textContent = "A pinned enacted source changed. Refresh it above before continuing this chat.";
  } else if (projectContextBlocked) {
    status.textContent = "Review the Project context in the Project column before analyzing.";
  }
  const resizeComposerInput = () => {
    input.style.height = "auto";
    input.style.height = `${Math.min(180, Math.max(48, input.scrollHeight))}px`;
    input.style.overflowY = input.scrollHeight > 180 ? "auto" : "hidden";
  };
  input.addEventListener("input", () => {
    resizeComposerInput();
    if (ownerInstance) {
      const currentInstance = state.utilityInstances.find((item) => item.id === ownerInstance.id);
      if (currentInstance) currentInstance.draft = input.value;
      ownerInstance.draft = input.value;
    }
    else researchQuestionDraft = input.value;
    researchNewChatDrafts.set(followUpDraftKey, input.value);
    scheduleResearchDraftPersistence();
    sendButton.disabled = !researchEnabled ||
      researchRequestActive ||
      conversation.sourceStatus === "changed" ||
      projectContextBlocked ||
      (input.value.trim() || starterAnalysisQuestion).length < 3;
  });
  input.addEventListener("blur", flushResearchDraftPersistence);
  if (!conversation.messages.length && !pendingProgress && displayedSources.length) {
    const welcome = document.createElement("section");
    welcome.className = "research-entry-context";
    const projectLabel = document.createElement("p");
    projectLabel.className = "research-entry-project";
    projectLabel.textContent = conversation.primaryProjectID
      ? `Project · ${researchProjectName(conversation.primaryProjectID)}` : "Unassigned Research";
    const heading = document.createElement("h3");
    heading.textContent = "What would you like to understand?";
    welcome.append(projectLabel, heading, projectPreview);
    thread.append(welcome);
  }
  bindResearchSendShortcut(input, composer);
  composer.addEventListener("submit", async (event) => {
    event.preventDefault();
    const question = input.value.trim() || starterAnalysisQuestion;
    if (question.length < 3 || sendButton.disabled) return;
    input.disabled = true;
    sendButton.disabled = true;
    status.textContent = "";
    if (ownerInstance) ownerInstance.draft = "";
    else researchQuestionDraft = "";
    researchNewChatDrafts.delete(followUpDraftKey);
    saveWorkspaceState();
    input.value = "";
    resizeComposerInput();
    const progress = createResearchProgressSession(conversationID, question);
    const pendingQuestion = document.createElement("article");
    pendingQuestion.className = "research-message is-user is-pending";
    const pendingQuestionText = document.createElement("p");
    pendingQuestionText.textContent = question;
    pendingQuestion.append(pendingQuestionText);
    const pendingAnswer = document.createElement("article");
    pendingAnswer.className = "research-message is-assistant is-pending";
    pendingAnswer.append(renderResearchProgressCard(progress));
    thread.append(pendingQuestion, pendingAnswer);
    thread.scrollTop = thread.scrollHeight;
    researchThreadScrollPositions.set(scrollPositionKey, thread.scrollTop);
    startResearchProgressTimer(progress);
    await runResearchProgressSession(progress, recoveredResearchProgressCallbacks(conversationID, { supplemental }));
  });
  composerBox.append(input, sendButton);
  input.rows = 1;
  composer.append(composerBox, status);
  dialoguePane.append(composer);
  if (!embedded && releaseSurfaceVisibility.researchConversationEvidencePane) {
    bindResearchEvidenceDivider(content, divider, conversation.id);
  }
  requestAnimationFrame(() => {
    resizeComposerInput();
    thread.scrollTop = researchThreadScrollPositions.get(scrollPositionKey) ?? thread.scrollHeight;
    researchThreadScrollPositions.set(scrollPositionKey, thread.scrollTop);
  });
  return panel;
}

function selectedReaderResearchPassages() {
  const selection = window.getSelection();
  if (!selection || selection.isCollapsed || !selection.rangeCount) return null;
  const range = selection.getRangeAt(0);
  const startElement = range.startContainer.nodeType === Node.ELEMENT_NODE
    ? range.startContainer : range.startContainer.parentElement;
  const panel = startElement?.closest(".reader-panel");
  if (!panel || !panel.contains(range.endContainer) || !readerPrivateContentAllowed(panel)) return null;
  const passages = [];
  panel.querySelectorAll("[data-research-section-id]").forEach((element) => {
    if (!range.intersectsNode(element)) return;
    // Nested selectable wrappers represent the same source; keep the outer one.
    if (element.parentElement.closest("[data-research-section-id]")) return;
    const clipped = document.createRange();
    clipped.selectNodeContents(element);
    if (range.compareBoundaryPoints(Range.START_TO_START, clipped) > 0) {
      clipped.setStart(range.startContainer, range.startOffset);
    }
    if (range.compareBoundaryPoints(Range.END_TO_END, clipped) < 0) {
      clipped.setEnd(range.endContainer, range.endOffset);
    }
    const selectedText = researchSelectionTextFromRange("", clipped);
    if (selectedText) passages.push({
      sectionID: element.dataset.researchSectionId,
      selectedText,
      savedItemID: element.dataset.researchSavedItemId || ""
    });
  });
  if (!passages.length) return null;
  return { passages, originSurface: "reader", originPaneID: panel.dataset.paneId || "",
    projectID: researchCreationProjectID(selectedOpenProjectID() || panel.dataset.projectId) };
}

const readerSelectionResearchAction = document.createElement("button");
readerSelectionResearchAction.type = "button";
readerSelectionResearchAction.className = "reader-selection-research-action";
readerSelectionResearchAction.textContent = "Research selected text";
readerSelectionResearchAction.hidden = true;
document.body.append(readerSelectionResearchAction);
let selectedReaderResearchIntent = null;
let readerSelectionResearchPositionFrame = 0;
function positionReaderSelectionResearchAction() {
  readerSelectionResearchPositionFrame = 0;
  if (readerSelectionResearchAction.hidden) return;
  const range = window.getSelection()?.rangeCount ? window.getSelection().getRangeAt(0) : null;
  const node = range?.startContainer;
  const element = node?.nodeType === Node.ELEMENT_NODE ? node : node?.parentElement;
  const panel = element?.closest(".reader-panel");
  if (!panel?.isConnected) {
    readerSelectionResearchAction.hidden = true;
    return;
  }
  readerSelectionResearchAction.style.setProperty(
    "--selection-code-accent", getComputedStyle(panel).getPropertyValue("--code-accent").trim()
  );
  const bounds = panel.getBoundingClientRect();
  const left = Math.max(0, bounds.left);
  const right = Math.min(window.innerWidth, bounds.right);
  if (right <= left || bounds.bottom <= 0 || bounds.top >= window.innerHeight) {
    readerSelectionResearchAction.hidden = true;
    return;
  }
  readerSelectionResearchAction.style.left = `${bounds.left + bounds.width / 2}px`;
  readerSelectionResearchAction.style.bottom = `${Math.max(24, window.innerHeight - bounds.bottom + 24)}px`;
  readerSelectionResearchPositionFrame = requestAnimationFrame(positionReaderSelectionResearchAction);
}
readerSelectionResearchAction.addEventListener("pointerdown", (event) => event.preventDefault());
readerSelectionResearchAction.addEventListener("click", () => {
  const intent = selectedReaderResearchIntent;
  if (!intent || readerSelectionResearchAction.disabled) return;
  openResearchDestinationMenu(readerSelectionResearchAction, intent);
});
document.addEventListener("selectionchange", () => {
  if (document.activeElement === readerSelectionResearchAction) return;
  selectedReaderResearchIntent = selectedReaderResearchPassages();
  readerSelectionResearchAction.hidden = !selectedReaderResearchIntent;
  if (readerSelectionResearchPositionFrame) cancelAnimationFrame(readerSelectionResearchPositionFrame);
  positionReaderSelectionResearchAction();
});
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") {
    readerSelectionResearchAction.hidden = true;
    selectedReaderResearchIntent = null;
  }
});

function researchSelectionTextFromRange(selection, range) {
  const fragment = range.cloneContents();
  const container = document.createElement("div");
  container.append(fragment);
  container.querySelectorAll('[data-research-selection-exclude="true"]').forEach((element) => element.remove());
  container.querySelectorAll([
    "address", "article", "aside", "blockquote", "br", "dd", "div", "dl", "dt",
    "figcaption", "figure", "footer", "h1", "h2", "h3", "h4", "h5", "h6",
    "header", "hr", "li", "main", "nav", "ol", "p", "pre", "section", "table",
    "tbody", "td", "tfoot", "th", "thead", "tr", "ul"
  ].join(",")).forEach((element) => element.append(document.createTextNode("\n")));
  return String(container.textContent || selection)
    .replace(/[ \t\f\v]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function normalizedPassageAnchorText(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function pendingResearchPassages(selection) {
  return (selection?.passages || [selection]).map(({ sectionID, selectedText, savedItemID }) => ({
    sectionID,
    selectedText,
    savedItemID
  }));
}

function preservePendingResearchSelection(selection, kind, conversationID = "") {
  return writePendingResearchIntent(sessionStorage, {
    kind,
    workspaceID: activeWorkspaceID,
    projectID: researchCreationProjectID(selection?.projectID),
    conversationID,
    originPaneID: selection?.originPaneID || "",
    originSurface: selection?.originSurface || "reader",
    passages: pendingResearchPassages(selection)
  });
}

function pendingResearchWorkspaceIDs() {
  return new Set((workspaceRegistry?.workspaces || []).map((workspace) => workspace.id));
}

async function resumePendingResearchIntent() {
  const intent = readPendingResearchIntent(sessionStorage, {
    allowedWorkspaceIDs: pendingResearchWorkspaceIDs()
  });
  if (!intent || !activeAccount() || !hasCapability("research")) return false;
  if (pendingResearchIntentResumePromise) return pendingResearchIntentResumePromise;
  if (pendingResearchIntentInFlightID === intent.intentID) return false;
  pendingResearchIntentInFlightID = intent.intentID;
  pendingResearchIntentResumePromise = (async () => {
    if (intent.workspaceID !== activeWorkspaceID) {
      await switchWorkspace(intent.workspaceID, { focus: false });
    }
    const values = {
      selections: intent.passages,
      projectID: intent.projectID,
      originSurface: intent.originSurface
    };
    let conversation;
    if (intent.kind === "append-selection") {
      const payload = await postResearch("/research/conversations/evidence", {
        conversationID: intent.conversationID,
        selections: intent.passages
      });
      conversation = payload.conversation;
    } else {
      const payload = await postResearch("/research/conversations/create", {
        ...values,
        requestID: intent.intentID
      });
      conversation = payload.conversation;
    }
    const conversationID = String(conversation?.id || intent.conversationID || "").trim();
    if (!conversationID) throw new Error("The preserved Research action did not return a conversation.");
    activeResearchConversation = conversation;
    researchConversationPaneOpened = true;
    state.researchConversationID = conversationID;
    window.getSelection?.().removeAllRanges();
    await refreshResearchConversationList();
    await openResearchConversation(conversationID, {
      conversation,
      refreshList: true,
      anchorPaneID: intent.originPaneID
    });
    clearPendingResearchIntent(sessionStorage, intent.intentID);
    presentWorkspaceIssue("Your Research action resumed after access was confirmed.");
    return true;
  })().catch((error) => {
    presentWorkspaceIssue(
      error?.message || "The preserved Research action is still waiting. Open Research to try again.",
      {
        actionLabel: "Try again",
        onAction: () => void resumePendingResearchIntent()
      }
    );
    return false;
  }).finally(() => {
    pendingResearchIntentInFlightID = "";
    pendingResearchIntentResumePromise = null;
  });
  return pendingResearchIntentResumePromise;
}

async function startNewResearchFromSelection(selection) {
  if (!activeAccount()) {
    preservePendingResearchSelection(selection, "create-selection");
    await focusUtility("settings");
    return null;
  }
  if (!hasCapability("research")) {
    preservePendingResearchSelection(selection, "create-selection");
    await presentPlanLimitNotice(
      "Pro required for Research",
      "Upgrade to Pro for cited enacted-code conversations. Code reading and search remain free."
    );
    return null;
  }
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const workflowGeneration = state.workflowNavigationGeneration || 0;
  const navigationIsCurrent = () => isCurrentAccountRequest(identity) && activeWorkspaceID === workspaceID &&
    workflowGeneration === (state.workflowNavigationGeneration || 0);
  const passages = selection.passages || [selection];
  const payload = await postResearch("/research/conversations/create", {
    selections: passages.map(({ sectionID, selectedText, savedItemID }) => ({
      sectionID,
      selectedText,
      savedItemID
    })),
    projectID: selection.projectID || "",
    savedItemID: selection.savedItemID || "",
    originSurface: selection.originSurface || "reader"
  });
  if (!navigationIsCurrent()) return payload.conversation;
  activeResearchConversation = payload.conversation;
  window.getSelection?.().removeAllRanges();
  await refreshResearchConversationList();
  if (!navigationIsCurrent()) return payload.conversation;
  await openResearchConversation(payload.conversation.id, {
    refreshList: true,
    anchorPaneID: selection.originPaneID || ""
  });
  return payload.conversation;
}

async function addResearchSelectionToCurrent(selection, destinationConversationID = state.researchConversationID) {
  const conversationID = String(destinationConversationID || "").trim();
  if (!conversationID) return startNewResearchFromSelection(selection);
  if (!activeAccount()) {
    preservePendingResearchSelection(selection, "append-selection", conversationID);
    await focusUtility("settings");
    return null;
  }
  if (!hasCapability("research")) {
    preservePendingResearchSelection(selection, "append-selection", conversationID);
    await presentPlanLimitNotice(
      "Pro required for Research",
      "Upgrade to Pro to continue this cited conversation. Code reading and search remain free."
    );
    return null;
  }
  const workspaceID = activeWorkspaceID;
  const identity = captureAccountRequest();
  const passages = selection.passages || [selection];
  const payload = await postResearch("/research/conversations/evidence", {
    conversationID,
    selections: passages.map(({ sectionID, selectedText, savedItemID }) => ({
      sectionID,
      selectedText,
      savedItemID
    }))
  });
  if (workspaceID !== activeWorkspaceID || !isCurrentAccountRequest(identity)) return null;
  if (conversationID === state.researchConversationID) activeResearchConversation = payload.conversation;
  else supplementalResearchConversations.set(conversationID, payload.conversation);
  researchConversationList = researchConversationList.map((item) => item.id === conversationID ? payload.conversation : item);
  window.getSelection?.().removeAllRanges();
  // Refresh only the existing destination. Its composer restores its own durable
  // follow-up draft; adding evidence never submits a question or replaces another chat.
  const paneID = paneIDForResearchConversation(conversationID);
  await transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
  return payload.conversation;
}

function createProjectBulkSelectionController(panel, projects, mode) {
  const records = projects.slice(0, 24).filter((project) => projectRecordID(project));
  const recordByID = new Map(records.map((project) => [projectRecordID(project), project]));
  const orderedIDs = [...recordByID.keys()];
  const selectedIDs = new Set();
  const cards = new Map();
  let active = false;
  let busy = false;
  let lastSelectedIndex = -1;

  const selectButton = document.createElement("button");
  selectButton.className = "icon-button projects-select-button";
  selectButton.type = "button";
  selectButton.title = "Select projects";
  selectButton.setAttribute("aria-label", "Select projects");
  selectButton.setAttribute("aria-pressed", "false");
  selectButton.innerHTML = selectionModeIconSVG();
  panel.querySelector(".panel-actions")?.prepend(selectButton);

  const bulkBar = document.createElement("section");
  bulkBar.className = "project-bulk-bar";
  bulkBar.classList.toggle("is-archive", mode === "archive");
  bulkBar.hidden = true;
  bulkBar.setAttribute("aria-label", mode === "archive" ? "Archived project selection" : "Project selection");
  const countLabel = document.createElement("span");
  countLabel.className = "project-bulk-count";
  const selectAllButton = document.createElement("button");
  selectAllButton.className = "project-bulk-link";
  selectAllButton.type = "button";
  const actionButton = document.createElement("button");
  actionButton.className = `project-bulk-action ${mode === "archive" ? "is-delete" : "is-archive"}`;
  actionButton.type = "button";
  const deleteButton = mode === "projects" ? document.createElement("button") : null;
  if (deleteButton) {
    deleteButton.className = "project-bulk-action is-delete";
    deleteButton.type = "button";
  }
  const cancelButton = document.createElement("button");
  cancelButton.className = "project-bulk-link";
  cancelButton.type = "button";
  cancelButton.textContent = "Cancel";
  if (mode === "archive") {
    bulkBar.append(actionButton, cancelButton);
  } else {
    bulkBar.append(countLabel, selectAllButton, actionButton);
    if (deleteButton) bulkBar.append(deleteButton);
    bulkBar.append(cancelButton);
  }
  panel.append(bulkBar);

  function update() {
    panel.classList.toggle("is-project-selecting", active);
    selectButton.setAttribute("aria-pressed", String(active));
    selectButton.title = active ? "Cancel project selection" : "Select projects";
    selectButton.setAttribute("aria-label", selectButton.title);
    bulkBar.hidden = !active;
    const selectedCount = selectedIDs.size;
    countLabel.textContent = `${selectedCount} selected`;
    const allSelected = orderedIDs.length > 0 && selectedCount === orderedIDs.length;
    selectAllButton.textContent = allSelected ? "Clear all" : "Select all";
    actionButton.textContent = mode === "archive" ? "Delete" : `Archive ${selectedCount}`;
    actionButton.disabled = selectedCount === 0 || busy;
    if (deleteButton) {
      deleteButton.textContent = `Delete ${selectedCount}`;
      deleteButton.disabled = selectedCount === 0 || busy;
    }
    selectAllButton.disabled = busy;
    cancelButton.disabled = busy;
    selectButton.disabled = busy;
    cards.forEach((card, id) => {
      const selected = selectedIDs.has(id);
      card.classList.toggle("is-selected", selected);
      if (active) card.setAttribute("aria-pressed", String(selected));
      else card.removeAttribute("aria-pressed");
      card.setAttribute(
        "aria-label",
        active ? `${selected ? "Deselect" : "Select"} ${card.dataset.projectName || "project"}` : card.dataset.defaultAriaLabel
      );
    });
  }

  function setActive(nextActive) {
    active = nextActive;
    selectedIDs.clear();
    lastSelectedIndex = -1;
    update();
  }

  const controller = {
    isActive: () => active,
    register(card, project) {
      const id = projectRecordID(project);
      if (!id || !recordByID.has(id)) return;
      cards.set(id, card);
      card.dataset.projectRecordId = id;
      card.dataset.projectName = project.name || project.title || "project";
      card.dataset.defaultAriaLabel = card.getAttribute("aria-label") || "Open project";
      const indicator = document.createElement("span");
      indicator.className = "project-selection-check";
      indicator.setAttribute("aria-hidden", "true");
      indicator.innerHTML = selectionIndicatorIconSVG();
      card.prepend(indicator);
      update();
    },
    toggle(project, event = null) {
      const id = projectRecordID(project);
      const index = orderedIDs.indexOf(id);
      if (!active || index < 0 || busy) return;
      const shouldSelect = !selectedIDs.has(id);
      if (event?.shiftKey && lastSelectedIndex >= 0) {
        const start = Math.min(lastSelectedIndex, index);
        const end = Math.max(lastSelectedIndex, index);
        orderedIDs.slice(start, end + 1).forEach((rangeID) => {
          if (shouldSelect) selectedIDs.add(rangeID);
          else selectedIDs.delete(rangeID);
        });
      } else if (shouldSelect) {
        selectedIDs.add(id);
      } else {
        selectedIDs.delete(id);
      }
      lastSelectedIndex = index;
      update();
    }
  };

  selectButton.addEventListener("click", () => setActive(!active));
  selectAllButton.addEventListener("click", () => {
    if (selectedIDs.size === orderedIDs.length) selectedIDs.clear();
    else orderedIDs.forEach((id) => selectedIDs.add(id));
    lastSelectedIndex = -1;
    update();
  });
  cancelButton.addEventListener("click", () => setActive(false));
  actionButton.addEventListener("click", async () => {
    const selectedProjects = orderedIDs.filter((id) => selectedIDs.has(id)).map((id) => recordByID.get(id));
    if (!selectedProjects.length) return;
    busy = true;
    update();
    const completed = mode === "projects"
      ? await archiveProjects(selectedProjects)
      : await deleteArchivedProjects(selectedProjects);
    if (!completed) {
      busy = false;
      update();
    }
  });
  deleteButton?.addEventListener("click", async () => {
    const selectedProjects = orderedIDs.filter((id) => selectedIDs.has(id)).map((id) => recordByID.get(id));
    if (!selectedProjects.length) return;
    busy = true;
    update();
    const completed = await deleteArchivedProjects(selectedProjects);
    if (!completed) {
      busy = false;
      update();
    }
  });
  update();
  return controller;
}

function appendWorkspaceColumnIntro(content, text) {
  const intro = document.createElement("p");
  intro.className = "workspace-column-intro";
  intro.textContent = text;
  content.append(intro);
}

async function renderProjects() {
  const panel = renderTemplate(projectsTemplate);
  applyPaneWeight(panel, "utility:projects");
  const content = panel.querySelector(".projects-content");
  const addButton = panel.querySelector(".projects-add-button");
  const archiveButton = panel.querySelector(".projects-archive-button");
  clear(content);
  appendWorkspaceColumnIntro(content, "Projects organize saved sections and notes around a specific job or research topic.");
  addButton?.addEventListener("click", () => showProjectCreateSheet(panel));
  archiveButton?.setAttribute("aria-pressed", String(state.utilities.archive));
  archiveButton?.addEventListener("click", toggleArchiveAfterProjectsStack);
  const data = await loadSyncedContent();

  if (data.status === "disconnected") {
    const projects = activeProjectRecords([]);
    if (projects.length === 0) {
      appendProjectEmptyCard(content, "No Projects", "Use the add button to create a Project.");
    } else {
      const selectionController = createProjectBulkSelectionController(panel, projects, "projects");
      renderProjectRows(content, projects, currentContentSummary().projectSections, { mode: "projects", selectionController });
    }
    return panel;
  }
  if (data.status === "error") {
    appendProjectEmptyCard(content, "Sync error", data.error || "Could not load projects.");
    return panel;
  }

  const { projects, projectSections } = currentContentSummary();
  const visibleProjects = activeProjectRecords(projects);
  if (visibleProjects.length === 0) {
    appendProjectEmptyCard(content, "No Projects", "Use the add button to create a Project.");
  } else {
    const selectionController = createProjectBulkSelectionController(panel, visibleProjects, "projects");
    renderProjectRows(content, visibleProjects, projectSections, { mode: "projects", selectionController });
  }

  return panel;
}

async function renderArchive() {
  const panel = renderTemplate(projectsTemplate);
  panel.classList.remove("projects-panel");
  panel.classList.add("archive-panel");
  panel.dataset.paneId = "utility:archive";
  applyPaneWeight(panel, "utility:archive");
  const kind = panel.querySelector(".panel-kind");
  const title = panel.querySelector(".panel-title");
  const addButton = panel.querySelector(".projects-add-button");
  const archiveButton = panel.querySelector(".projects-archive-button");
  const actions = panel.querySelector(".panel-actions");
  const content = panel.querySelector(".projects-content");
  if (kind) kind.textContent = "Archive";
  if (title) title.textContent = "Archive";
  addButton?.remove();
  archiveButton?.remove();
  const closeButton = document.createElement("button");
  closeButton.className = "icon-button archive-close-button";
  closeButton.type = "button";
  closeButton.title = "Close archive";
  closeButton.setAttribute("aria-label", "Close archive");
  closeButton.innerHTML = circleXIconSVG();
  closeButton.addEventListener("click", closeArchiveColumn);
  actions?.prepend(closeButton);
  clear(content);
  const data = await loadSyncedContent();
  const sourceProjects = ["connected", "offline"].includes(data.status) ? data.summary.projects : [];
  const projects = archivedProjectRecords(sourceProjects);
  if (data.status === "error") {
    appendProjectEmptyCard(content, "Sync error", data.error || "Could not load archived Projects and saved collections.");
    return panel;
  }
  if (projects.length === 0) {
    appendProjectEmptyCard(content, "Archive is empty", "Archived Projects and saved collections will appear here.");
  } else {
    const selectionController = createProjectBulkSelectionController(panel, projects, "archive");
    renderProjectRows(content, projects, currentContentSummary().projectSections || [], { mode: "archive", selectionController });
  }
  return panel;
}

function projectIdentity(project) {
  return {
    id: project.id || "",
    clientID: project.clientID || "",
    localFolderID: project.localFolderID || "",
    name: project.name || project.title || "Project",
    title: project.title || project.name || "Project",
    address: project.address || "",
    description: project.description || "",
    structuredFacts: projectStructuredFacts(project),
    recordsChecklist: project.recordsChecklist || [],
    folderType: folderType(project),
    color: projectColor(project),
    ...(project.sharedOrganizationID ? {
      sharedOrganizationID: project.sharedOrganizationID,
      sharedOrganizationName: project.sharedOrganizationName || "",
      sharedRole: project.sharedRole || "viewer",
      sharedPermissions: Array.isArray(project.sharedPermissions)
        ? project.sharedPermissions
        : [],
      sharedOnly: project.sharedOnly === true
    } : {})
  };
}

function projectSectionBelongsToProject(item, project) {
  const itemIDs = [item?.folderClientID, item?.localFolderID, item?.folderID]
    .filter((value) => value !== undefined && value !== null && value !== "")
    .map(String);
  const projectIDs = [project?.clientID, project?.id, project?.localFolderID]
    .filter((value) => value !== undefined && value !== null && value !== "")
    .map(String);
  return itemIDs.some((id) => projectIDs.includes(id));
}

function mountProjectOpeningPane(project, options = {}) {
  const identity = projectIdentity(project);
  const paneID = paneIDForProjectDetail(identity);
  const panel = document.createElement("article");
  panel.className = "workspace-panel project-detail-panel project-detail-loading";
  panel.dataset.paneId = paneID;
  panel.style.setProperty("--project-color", identity.color);
  panel.setAttribute("aria-busy", "true");
  applyPaneWeight(panel, paneID);

  const chrome = document.createElement("header");
  chrome.className = "project-detail-chrome";
  const heading = document.createElement("div");
  heading.className = "project-detail-heading";
  const title = document.createElement("h2");
  title.textContent = identity.name;
  const status = document.createElement("p");
  status.textContent = "Opening Project…";
  heading.append(title, status);
  chrome.append(heading);

  const content = document.createElement("section");
  content.className = "project-detail-content";
  const loading = document.createElement("p");
  loading.className = "project-detail-loading-status";
  loading.textContent = "Loading saved evidence, notes, and research history…";
  content.append(loading);
  panel.append(chrome, content);

  const replacingPane = options.replacingPaneID
    ? track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(options.replacingPaneID)}"]`)
    : null;
  const sourcePane = options.sourcePaneID
    ? track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(options.sourcePaneID)}"]`)
    : null;
  if (replacingPane) replacingPane.replaceWith(panel);
  else if (sourcePane) sourcePane.after(panel);
  else track.prepend(panel);
  requestAnimationFrame(() => scrollPaneIntoView(paneID));
}

function selectProjectInSaved(project, preferredPaneID = "") {
  let savedInstance = (state.utilityInstances || []).find((instance) =>
    instance.key === "saved" && paneIDForUtilityInstance(instance) === preferredPaneID
  ) || (state.utilityInstances || []).find((instance) => instance.key === "saved");
  if (!savedInstance) {
    savedInstance = newUtilityInstance("saved");
    state.utilityInstances = [...(state.utilityInstances || []), savedInstance];
    state.utilities.saved = false;
    state.paneWeights[paneIDForUtilityInstance(savedInstance)] = defaultSavedPaneWidth;
    movePaneToFront(paneIDForUtilityInstance(savedInstance));
  }
  savedInstance.selectedFolderID = projectRecordID(project);
  savedInstance.projectsArchiveMode = false;
  savedInstance.organizeUnassigned = false;
  savedInstance.showAllSaved = false;
  savedInstance.folderQuery = "";
  const paneID = paneIDForUtilityInstance(savedInstance);
  state.projectHostPaneID = paneID;
  return paneID;
}

async function openProjectDetail(project, options = {}) {
  if (!detachedProjectWindow && folderIsProject(project)) {
    reconcileProjectWorkspaces();
    const linked = workspaceRegistry.workspaces.find((item) => item.projectID === projectRecordID(project));
    if (linked && linked.id !== activeWorkspaceID && !(await switchWorkspace(linked.id, { focus: false }))) return;
  }
  if (!detachedProjectWindow && projectHasDetachedWorkboard(project)) {
    openDetachedWindow(project);
    return;
  }
  const identity = projectIdentity(project);
  const sourceSavedInstance = (state.utilityInstances || []).find((instance) =>
    instance.key === "saved" && paneIDForUtilityInstance(instance) === options.sourcePaneID
  ) || (state.utilityInstances || []).find((instance) => instance.key === "saved");
  const sourcePaneID = sourceSavedInstance ? paneIDForUtilityInstance(sourceSavedInstance) : "";
  const activated = await activateProjectStudio(identity, {
    ...options,
    sourcePaneID,
    focusSaved: false,
    showOverview: true,
    transition: false
  });
  if (!activated) return;
  const savedPaneID = selectProjectInSaved(identity, sourcePaneID);
  saveWorkspaceState();
  await transitionProjectSelection(savedPaneID);
  scrollPaneIntoView(savedPaneID);
}

function projectDetailMatches(project, detail) {
  if (!project || !detail) return false;
  const ids = [project.id, project.clientID, project.localFolderID].filter(Boolean).map(String);
  const detailIDs = [detail.id, detail.clientID, detail.localFolderID].filter(Boolean).map(String);
  if (detailIDs.some((id) => ids.includes(id))) return true;
  return Boolean(!ids.length && !detailIDs.length && projectDetailKey(project) === projectDetailKey(detail));
}

function emptyNotebookDocument() {
  return {
    schema: "permitext-notebook-card",
    schemaVersion: 2,
    format: "blocknote-json",
    document: [{ type: "paragraph", content: [] }]
  };
}

function notebookDocumentFromPlainText(value) {
  const blocks = String(value || "")
    .split(/\n{2,}/)
    .map((paragraph) => paragraph.replace(/\s*\n\s*/g, " ").trim())
    .filter(Boolean)
    .map((paragraph) => ({
      type: "paragraph",
      content: [{ type: "text", text: paragraph, styles: {} }]
    }));
  return {
    ...emptyNotebookDocument(),
    document: blocks.length ? blocks : emptyNotebookDocument().document
  };
}

function notebookReferenceCodeTitle(codePrefix = "BC") {
  return codeDisplayLabel(codePrefix)
    .replace(/\s*\([^)]*\)\s*$/g, "")
    .replace(/\s+[—–-].*$/, "")
    .trim();
}

function notebookCanonicalReferenceLabel(savedItem, chapter, resolvedSection = null) {
  const codePrefix = savedItem?.codePrefix || chapter?.codePrefix || "BC";
  const chapterNumber = String(savedItem?.chapterNumber || chapter?.chapterNumber || "").trim();
  const sectionNumber = String(savedItem?.sectionNumber || "").trim();
  const section = resolvedSection || (chapter?.sections || []).find((candidate) =>
    String(candidate.id) === String(savedItem?.sectionID) ||
    (sectionNumber && String(candidate.sectionNumber || "") === sectionNumber)
  );
  const provisionTitle = sectionTitleWithoutNumber({
    sectionNumber,
    title: section?.title || savedItem?.title || ""
  }).replace(/[.\s]+$/, "");
  const citation = sectionNumber ? `§ ${sectionNumber}` : "Code section";
  return {
    label: [notebookReferenceCodeTitle(codePrefix), savedEvidenceEdition(savedItem), citation, provisionTitle].filter(Boolean).join(" · "),
    title: [citation, provisionTitle].filter(Boolean).join(" · "),
    meta: [savedEvidenceEdition(savedItem), chapterNumber ? `Chapter ${chapterNumber}` : ""].filter(Boolean).join(" · ")
  };
}

function compareNotebookReferences(left, right) {
  const kindOrder = {
    canonicalSection: 0,
    researchAnswer: 1,
    notebookCard: 2,
    workboard: 3
  };
  const kindDifference = (kindOrder[left.referenceKind] ?? 99) -
    (kindOrder[right.referenceKind] ?? 99);
  if (kindDifference) return kindDifference;
  if (left.referenceKind === "canonicalSection") {
    const codeDifference = codeOptions.findIndex((option) => option.prefix === left.codePrefix) -
      codeOptions.findIndex((option) => option.prefix === right.codePrefix);
    if (codeDifference) return codeDifference;
    const hierarchyDifference = [left.chapterNumber, left.sectionNumber]
      .map((part) => String(part || ""))
      .join(".")
      .localeCompare(
        [right.chapterNumber, right.sectionNumber]
          .map((part) => String(part || ""))
          .join("."),
        undefined,
        { numeric: true, sensitivity: "base" }
      );
    if (hierarchyDifference) return hierarchyDifference;
  }
  return String(left.label || "").localeCompare(String(right.label || ""), undefined, {
    numeric: true,
    sensitivity: "base"
  });
}

function notebookResearchAnswers(foundation) {
  const value = foundation?.researchAnswers;
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== "object") return [];
  return Object.values(value).filter((answer) =>
    answer && typeof answer === "object" && String(answer.id || "").trim()
  );
}

async function notebookReferenceCandidates(project, foundation, cards) {
  const identity = projectIdentity(project);
  const projectID = projectDetailKey(identity);
  const activeLinks = (foundation.links || []).filter((link) =>
    !link.deletedAt && link.projectID === projectID
  );
  const summary = currentContentSummary();
  const savedItems = summary.savedItems || [];
  const savedBySectionID = new Map(savedItems.map((item) => [String(item.sectionID || item.id || ""), item]));
  const currentProjectSections = (summary.projectSections || [])
    .filter((item) => projectSectionBelongsToProject(item, identity));
  const canonicalTargets = currentProjectSections.length
    ? currentProjectSections.map((item) => ({
        targetID: String(item.sectionID || item.savedSectionID || item.itemID || ""),
        projectSection: item
      }))
    : activeLinks
        .filter((link) => link.targetKind === "canonicalSection")
        .map((link) => ({ targetID: String(link.targetID || ""), projectSection: null }));
  const references = [];
  const canonicalReferences = await Promise.all(
    canonicalTargets.filter((target) => target.targetID).map(async (target) => {
      const savedItem = savedBySectionID.get(target.targetID) || {};
      const detail = {
        codePrefix: savedItem.codePrefix || target.projectSection?.codePrefix || "BC",
        codeVersion: savedItem.codeVersion || target.projectSection?.codeVersion || "",
        chapterID: savedItem.chapterID || target.projectSection?.chapterID || "",
        chapterNumber: savedItem.chapterNumber || target.projectSection?.chapterNumber || "",
        sectionID: target.targetID,
        sectionNumber: savedItem.sectionNumber || target.projectSection?.sectionNumber || "",
        title: savedItem.title || target.projectSection?.title || "Section"
      };
      const resolved = await resolveSectionDetail(detail).catch(() => ({ chapter: null, section: null }));
      const citation = notebookCanonicalReferenceLabel(detail, resolved.chapter, resolved.section);
      return {
        referenceKind: "canonicalSection",
        referenceID: target.targetID,
        label: citation.label,
        displayTitle: citation.title,
        displayMeta: citation.meta,
        codePrefix: detail.codePrefix || resolved.chapter?.codePrefix || "BC",
        chapterNumber: detail.chapterNumber || resolved.chapter?.chapterNumber || "",
        sectionNumber: detail.sectionNumber || resolved.section?.sectionNumber || ""
      };
    })
  );
  references.push(...canonicalReferences);
  notebookResearchAnswers(foundation).forEach((answer) => {
    references.push({
      referenceKind: "researchAnswer",
      referenceID: answer.id,
      label: `Research: ${answer.question || answer.conclusion || "Historical answer"}`
    });
  });
  cards.forEach((card) => {
    const referenceID = String(card.id || "").trim();
    references.push({
      referenceKind: "notebookCard",
      referenceID,
      label: `Notebook: ${card.title}`,
      disabledReason: referenceID ? "" : "Finish syncing this Note before linking it."
    });
  });
  return references
    .filter((reference, index, all) =>
      all.findIndex((candidate) =>
        candidate.referenceKind === reference.referenceKind &&
        candidate.referenceID === reference.referenceID
      ) === index
    )
    .sort(compareNotebookReferences);
}

function notebookDocumentWithCurrentCardLabels(document, cards) {
  const labelsByCardID = new Map(
    (cards || [])
      .map((card) => [String(card.id || "").trim(), String(card.title || "").trim()])
      .filter(([cardID, title]) => cardID && title)
      .map(([cardID, title]) => [cardID, `Notebook: ${title}`])
  );
  const evidenceLabels = new Map((currentContentSummary().savedItems || [])
    .filter(item => item.codeVersion && item.sectionID)
    .map(item => [String(item.sectionID), notebookCanonicalReferenceLabel(item, null).label]));
  if (!labelsByCardID.size && !evidenceLabels.size) return { document, changed: false };
  const nextDocument = structuredClone(document);
  let changed = false;
  const visit = (value) => {
    if (!value || typeof value !== "object") return;
    if (
      value.type === "permitextReference" &&
      value.props?.referenceKind === "notebookCard"
    ) {
      const nextLabel = labelsByCardID.get(String(value.props.referenceID || "").trim());
      if (nextLabel && value.props.label !== nextLabel) {
        value.props.label = nextLabel;
        changed = true;
      }
    }
    if (value.type === "permitextReference" && value.props?.referenceKind === "canonicalSection") {
      const nextLabel = evidenceLabels.get(String(value.props.referenceID || "").trim());
      if (nextLabel && value.props.label !== nextLabel) {
        value.props.label = nextLabel;
        changed = true;
      }
    }
    Object.values(value).forEach(visit);
  };
  visit(nextDocument);
  return changed ? { document: nextDocument, changed } : { document, changed };
}

async function openNotebookReference(project, foundation, reference, selectCard, anchorPaneID, projectID) {
  if (reference.referenceKind === "selectedPassage") {
    const evidenceLink = reference.evidenceLink;
    if (!evidenceLink?.source?.sectionID) {
      throw new Error("This passage link is missing its enacted-source locator.");
    }
    await openSourceInReader({
      ...evidenceLink.source,
      title: evidenceLink.source.sectionTitle
    }, anchorPaneID, { projectID, evidenceAnchor: evidenceLink });
    return;
  }
  if (reference.referenceKind === "canonicalSection") {
    const savedItem = (currentContentSummary().savedItems || [])
      .find((item) => String(item.sectionID) === String(reference.referenceID));
    await openSourceInReader({
      sectionID: reference.referenceID,
      codePrefix: savedItem?.codePrefix || "",
      codeVersion: savedItem?.codeVersion || "",
      chapterID: savedItem?.chapterID || "",
      chapterNumber: savedItem?.chapterNumber || "",
      sectionNumber: savedItem?.sectionNumber || "",
      title: savedItem?.title || reference.label
    }, anchorPaneID, { projectID });
    return;
  }
  if (reference.referenceKind === "researchAnswer") {
    const answer = notebookResearchAnswers(foundation)
      .find((candidate) => candidate.id === reference.referenceID);
    if (!answer?.conversationID) {
      throw new Error("This saved Research reference is unavailable. Reload the Project and try again.");
    }
    await openResearchConversation(answer.conversationID, { anchorPaneID });
    return;
  }
  if (reference.referenceKind === "notebookCard") {
    await selectCard(reference.referenceID);
    return;
  }
  if (reference.referenceKind === "workboard") {
    await showWebNotice(
      "Legacy Workboard reference",
      "This reference is preserved for the historical Notebook record, but Workboard has been retired and can no longer be opened."
    );
    return;
  }
  await showWebNotice(
    "Linked Project item",
    "This item is preserved in the Notebook card and will open in its dedicated Project Studio view when that view is available."
  );
}

function privateCacheFallbackAllowed(error) {
  if (["ACCOUNT_CONTEXT_CHANGED", "OFFLINE_ACCOUNT_DELETED"].includes(error?.code)) return false;
  const status = Number(error?.status || 0);
  return status === 0 || status >= 500;
}

async function notebookDeviceRecoveryBundle(projectID, identity) {
  requireCurrentAccountRequest(identity);
  const snapshot = await offlineAccountRecoverySnapshot(identity.userID);
  requireCurrentAccountRequest(identity);
  const belongsHere = (record) => record.accountUserID === identity.userID && record.projectID === projectID;
  const drafts = snapshot.drafts.filter(belongsHere);
  const images = await Promise.all(snapshot.images.filter(belongsHere).map(async ({ blob, ...record }) => ({
    ...record, ...(blob ? { dataURL: await blobDataURL(blob) } : {})
  })));
  requireCurrentAccountRequest(identity);
  return { format: "permitext-device-draft-recovery", version: 1, projectID,
    accountUserID: identity.userID, exportedAt: new Date().toISOString(), drafts, images,
    instructions: "These are your local authored drafts and images. Review them before copying into a saved Note. This file does not import or synchronize changes." };
}

function notebookRecoveryPlainText(node) {
  if (!node) return "";
  if (typeof node === "string") return node;
  if (Array.isArray(node)) return node.map(notebookRecoveryPlainText).join("");
  if (Array.isArray(node.document)) return node.document.map(notebookRecoveryPlainText).join("\n\n");
  if (node.type === "text") return String(node.text || "");
  if (node.type === "permitextReference") return String(node.props?.label || "");
  if (node.type === "image") return String(node.props?.caption || node.props?.name || "Image");
  const body = (Array.isArray(node.content) ? node.content : []).map(notebookRecoveryPlainText).join(node.type === "doc" ? "\n\n" : "");
  const children = (Array.isArray(node.children) ? node.children : []).map(notebookRecoveryPlainText);
  return [body, ...children].filter(Boolean).join("\n");
}

function appendNotebookDraftCopyReview(container, draft, identity, onResolve) {
  if (!draft.recoveryCopies?.length) return;
  const versions = document.createElement("details");
  const heading = document.createElement("summary");
  heading.textContent = `Compare ${draft.recoveryCopies.length + 1} device versions`;
  versions.append(heading);
  for (const [index, copy] of [draft, ...draft.recoveryCopies].entries()) {
    const title = document.createElement("strong");
    title.textContent = `${index === 0 ? "Current editor version" : `Other device version ${index}`} · ${copy.title || "Untitled"}`;
    const text = document.createElement("pre");
    text.style.whiteSpace = "pre-wrap";
    text.textContent = [notebookRecoveryPlainText(copy.document), notebookQuestionsText(copy.openQuestions || [])].filter(Boolean).join("\n\n") || "This version contains structured content. Download the recovery file to inspect it.";
    versions.append(title, text);
  }
  const keep = document.createElement("button");
  keep.type = "button";
  keep.textContent = "Keep current editor version";
  const status = document.createElement("span");
  status.setAttribute("role", "status");
  keep.addEventListener("click", async () => {
    if (!isCurrentAccountRequest(identity)) return;
    const confirmed = await confirmWebWarning("Keep this device version?",
      "Compare the device versions above first. Keeping the current editor version removes the other retained device versions. Download a recovery file first if you want to keep them. The saved server version will still be checked before syncing.",
      { confirmLabel: "Keep current editor version" });
    if (!confirmed || !isCurrentAccountRequest(identity)) return;
    keep.disabled = true;
    try { await onResolve(draft.revision); }
    catch (error) {
      if (isCurrentAccountRequest(identity)) status.textContent = `${error.message} All device versions remain available for review.`;
    } finally { keep.disabled = false; }
  });
  container.append(versions, keep, status);
}

async function appendNotebookDeviceRecovery(container, projectID, identity) {
  try {
    const drafts = (await pendingNotebookDrafts(identity.userID))
      .filter((draft) => draft.accountUserID === identity.userID && draft.projectID === projectID);
    requireCurrentAccountRequest(identity);
    if (!drafts.length) return;
    const region = document.createElement("section");
    region.className = "notebook-device-recovery";
    const heading = document.createElement("h3");
    heading.textContent = "Your drafts on this device";
    const description = document.createElement("p");
    description.textContent = "Your local edits are preserved. You can read them here and download a recovery file with their images while Notebook access is unavailable.";
    region.append(heading, description);
    for (const draft of drafts) {
      const details = document.createElement("details");
      const summary = document.createElement("summary");
      summary.textContent = draft.title || (draft.scope === "collaboration-note" ? "Project information draft" : "Untitled Note");
      const text = document.createElement("pre");
      text.textContent = [notebookRecoveryPlainText(draft.document), notebookQuestionsText(draft.openQuestions || [])].filter(Boolean).join("\n\n") || "This draft contains images or structured content. Download the recovery file to preserve all of it.";
      details.append(summary, text);
      region.append(details);
    }
    const download = document.createElement("button");
    download.type = "button";
    download.className = "notebook-recovery-download";
    download.textContent = "Download drafts and images";
    const status = document.createElement("p");
    status.setAttribute("role", "status");
    download.addEventListener("click", async () => {
      if (!isCurrentAccountRequest(identity)) return;
      download.disabled = true;
      try {
        const bundle = await notebookDeviceRecoveryBundle(projectID, identity);
        requireCurrentAccountRequest(identity);
        downloadCodeMemoBlob(new Blob([JSON.stringify(bundle, null, 2)], { type: "application/json" }), "permitext-device-drafts.json");
        status.textContent = "Recovery file downloaded. Your drafts remain on this device.";
      } catch (error) {
        if (isCurrentAccountRequest(identity)) status.textContent = `Download could not finish: ${error.message}`;
      } finally {
        if (isCurrentAccountRequest(identity)) download.disabled = false;
      }
    });
    region.append(download, status);
    container.append(region);
  } catch (error) {
    if (!isCurrentAccountRequest(identity)) return;
    const status = document.createElement("p");
    status.setAttribute("role", "status");
    status.textContent = "Device drafts could not be read. Keep this browser's site data and try again.";
    container.append(status);
  }
}

async function renderProjectNotebook(project, options = {}) {
  if (!hasCapability("notebook")) return renderProLockedPane(paneIDForProjectNotebook(project), "Notes");
  const requestIdentity = captureAccountRequest();
  const accountUserID = requestIdentity.userID;
  const notebookRequest = (path, values) => {
    requireCurrentAccountRequest(requestIdentity);
    return postResearch(path, values);
  };
  const identity = projectIdentity(project);
  const projectID = projectDetailKey(identity);
  const paneID = paneIDForProjectNotebook(identity);
  notebookMounts.get(projectID)?.dispose?.();

  const panel = document.createElement("article");
  panel.className = "workspace-panel notebook-panel";
  panel.dataset.paneId = paneID;
  panel.dataset.projectId = projectID;
  panel.style.setProperty("--project-color", identity.color || "#c96410");
  applyPaneWeight(panel, paneID);

  const header = document.createElement("header");
  header.className = "notebook-header";
  const heading = document.createElement("div");
  heading.className = "notebook-heading";
  const headingTitle = document.createElement("h2");
  headingTitle.textContent = "Notes";
  headingTitle.className = "eyebrow panel-kind";
  heading.append(headingTitle);
  const dragHandle = createProjectToolDragHandle(identity);
  const closeButton = document.createElement("button");
  closeButton.className = "icon-button utility-close notebook-close";
  closeButton.type = "button";
  closeButton.title = "Close notes";
  closeButton.setAttribute("aria-label", "Close notes");
  closeButton.innerHTML = circleXIconSVG();
  closeButton.addEventListener("click", () => {
    void closeProjectNotebook(identity);
  });
  header.append(heading, closeButton, dragHandle);

  const shell = document.createElement("div");
  shell.className = "notebook-shell";
  const status = document.createElement("p");
  status.className = "notebook-status";
  status.setAttribute("role", "status");
  status.textContent = "Loading Project Notebook…";
  shell.append(status);
  panel.append(header, shell);

  let editorMount = null;
  const notebookEditingPositions = new Map();
  const returnScrollContext = { generation: accountRuntimeGeneration, userID: accountUserID, workspaceID: activeWorkspaceID, projectID };
  let captureNotebookReturnScroll = () => {};
  let releaseNotebookReturnScroll = () => {};
  let editorRenderSequence = 0;
  let notebookCardLoadGeneration = 0;
  const notebookCardIdentities = new WeakMap();
  function notebookCardIdentity(card) {
    if (!card) return null;
    if (!notebookCardIdentities.has(card)) notebookCardIdentities.set(card, {});
    return notebookCardIdentities.get(card);
  }
  function retainNotebookCardIdentity(previous, next) {
    notebookCardIdentities.set(next, notebookCardIdentity(previous));
    return next;
  }
  let cards = [];
  let foundation = { links: [], researchAnswers: [] };
  let activeCard = null;
  let draftDocument = emptyNotebookDocument();
  let dirty = false;
  let notebookRevision = 0;
  let persistedRevision = -1;
  let persistedCardID = null;
  let persistedDraft = null;
  let draftWriteQueue = Promise.resolve();
  let saveConflict = false;
  const draftStatus = document.createElement("p");
  draftStatus.className = "notebook-status notebook-draft-status";
  draftStatus.setAttribute("role", "status");
  panel.append(draftStatus);
  const showDraftStatus = (message) => {
    if (!isCurrentAccountRequest(requestIdentity)) return;
    const statusMessage = message === "Synced" ? "Saved" : String(message || "").trim();
    draftStatus.replaceChildren();
    draftStatus.title = statusMessage;
    if (!statusMessage) return;
    const statusText = document.createElement("span");
    statusText.className = "notebook-draft-status-message";
    statusText.textContent = statusMessage;
    draftStatus.append(statusText);
  };
  function showNotebookRecoveryConflict(draft) {
    if (!draft?.recoveryConflict) return false;
    saveConflict = true;
    if (!isCurrentAccountRequest(requestIdentity)) return true;
    showDraftStatus("Device draft conflict · different versions are preserved. Compare them before continuing. Automatic saving is paused.");
    const download = document.createElement("button");
    download.type = "button";
    download.className = "notebook-recovery-download";
    download.textContent = "Download recovery draft";
    download.addEventListener("click", async () => {
      if (!isCurrentAccountRequest(requestIdentity)) return;
      try {
        const deviceRecovery = await notebookDeviceRecoveryBundle(projectID, requestIdentity);
        requireCurrentAccountRequest(requestIdentity);
        const recovery = { format: "permitext-notebook-recovery", version: 1, projectID,
          originalCardID: draft.cardID || "", acceptedCardID: draft.acceptedCardID || "",
          title: activeCard?.title || draft.title || "", document: structuredClone(draftDocument),
          evidenceLinks: structuredClone(activeCard?.evidenceLinks || draft.evidenceLinks || []),
          openQuestions: structuredClone(activeCard?.openQuestions ?? draft.openQuestions ?? []),
          recoveryCopies: structuredClone(draft.recoveryCopies || []), deviceRecovery };
        downloadCodeMemoBlob(new Blob([JSON.stringify(recovery, null, 2)], { type: "application/json" }), "permitext-notebook-recovery.json");
      } catch (error) {
        if (isCurrentAccountRequest(requestIdentity)) void showWebNotice("Recovery download failed", `${error.message}. Your device versions are still preserved.`);
      }
    });
    draftStatus.append(" ", download);
    appendNotebookDraftCopyReview(draftStatus, draft, requestIdentity, async (expectedRevision) => {
      const resolution = draftWriteQueue.then(async () => {
        requireCurrentAccountRequest(requestIdentity);
        const resolved = await resolveNotebookDraftCopiesAfterReview(accountUserID, projectID, draft.cardID, expectedRevision);
        persistedDraft = resolved;
        return resolved;
      });
      draftWriteQueue = resolution.catch(() => {});
      const resolved = await resolution;
      requireCurrentAccountRequest(requestIdentity);
      saveConflict = Boolean(resolved.recoveryConflict);
      if (!showNotebookRecoveryConflict(resolved)) {
        showDraftStatus("Reviewed device version · waiting to sync");
        void flushNotebookAutosave();
      }
    });
    return true;
  }
  const persistFocusedDraft = () => {
    if (!dirty || !activeCard) return draftWriteQueue.then(() => persistedDraft);
    const revision = notebookRevision;
    const cardID = activeCard.id || "";
    const snapshot = {
      accountUserID, projectID, cardID, scope: "notebook-card",
      baseVersion: activeCard.version, cardType: activeCard.cardType || "finding",
      title: activeCard.title || "", document: structuredClone(draftDocument),
      evidenceLinks: structuredClone(activeCard.evidenceLinks || []),
      openQuestions: structuredClone(activeCard.openQuestions || [])
    };
    const write = draftWriteQueue.catch(() => {}).then(async () => {
      // A write captured while acknowledgement was rekeying a new Note may
      // have the accepted ID. A detected collision belongs to the retained old
      // draft; never apply those editor bytes to the other canonical-ID draft.
      if (persistedDraft?.recoveryConflict && saveConflict && snapshot.cardID !== persistedDraft.cardID) {
        snapshot.cardID = persistedDraft.cardID || "";
        snapshot.baseVersion = persistedDraft.baseVersion;
      }
      if (persistedRevision === revision && persistedCardID === cardID && persistedDraft) return persistedDraft;
      const saved = await saveNotebookDraft({ ...snapshot,
        expectedRevision: persistedDraft && persistedCardID === snapshot.cardID ? persistedDraft.revision : null });
      persistedRevision = revision;
      persistedCardID = snapshot.cardID;
      persistedDraft = saved;
      if (!showNotebookRecoveryConflict(saved)) showDraftStatus("Saved on this device · waiting to sync");
      if (isCurrentAccountRequest(requestIdentity)) void refreshNotebookPendingStatus(requestIdentity).catch(() => {});
      return saved;
    });
    draftWriteQueue = write;
    return write;
  };
  let notebookReadOnly = false;
  let disposed = false;
  const notebookObjectURLs = new Set();
  let notebookAutosaveTimer = null;
  let notebookIdlePrefetchTimer = null;
  let notebookIdlePrefetchHandle = null;
  let flushNotebookAutosave = async () => !dirty;
  let refreshNotebookCards = async () => false;
  let refreshNotebookReferenceSources = async () => false;
  let refreshNotebookReportStatus = async () => false;
  const notebookImageUploaded = (event) => {
    if (disposed || !isCurrentAccountRequest(requestIdentity) || event.detail?.accountUserID !== accountUserID || event.detail?.generation !== requestIdentity.generation || event.detail?.projectID !== projectID) return;
    editorMount?.replaceAssetURL?.(event.detail.localURL, event.detail.permanentURL);
  };
  window.addEventListener("permitext:notebook-image-uploaded", notebookImageUploaded);

  const mountState = {
    panel,
    persistDraft: persistFocusedDraft,
    async syncDraft() { return flushNotebookAutosave(); },
    activeCardID() {
      return activeCard?.id || "";
    },
    async confirmDiscardIfNeeded() {
      if (!dirty || !activeCard) return true;
      if (await flushNotebookAutosave()) return true;
      return confirmWebWarning(
        "Discard unsaved Notebook changes?",
        `Your edits to “${activeCard.title || "Untitled card"}” have not been saved.`,
        { confirmLabel: "Discard changes" }
      );
    },
    async refreshReferenceSources(options = {}) {
      return refreshNotebookReferenceSources(options);
    },
    async refreshCards() {
      return refreshNotebookCards();
    },
    async refreshReportStatus() {
      return refreshNotebookReportStatus();
    },
    dispose() {
      captureNotebookReturnScroll();
      releaseNotebookReturnScroll();
      void persistFocusedDraft().catch(() => {});
      disposed = true;
      window.clearTimeout(notebookAutosaveTimer);
      window.clearTimeout(notebookIdlePrefetchTimer);
      if (notebookIdlePrefetchHandle !== null && typeof window.cancelIdleCallback === "function") {
        window.cancelIdleCallback(notebookIdlePrefetchHandle);
      }
      editorRenderSequence += 1;
      editorMount?.destroy?.();
      editorMount = null;
      notebookObjectURLs.forEach((url) => URL.revokeObjectURL(url));
      notebookObjectURLs.clear();
      window.removeEventListener("permitext:notebook-image-uploaded", notebookImageUploaded);
    }
  };
  notebookMounts.set(projectID, mountState);

  if (!activeAccount()) {
    status.textContent = "Sign in from Account to use the private Project Notebook.";
    return panel;
  }

  try {
    let foundationPayload;
    let cardPayload;
    try {
      const hubPayload = await projectTransitionHubPayload(projectID);
      if (hubPayload?.foundation && hubPayload?.notebook && hubPayload.access?.canReadNotebook === true) {
        foundationPayload = hubPayload.foundation;
        cardPayload = {
          ...hubPayload.notebook,
          access: {
            ...(hubPayload.notebook.access || {}),
            readOnly: hubPayload.access?.readOnly === true
          }
        };
      } else {
        [foundationPayload, cardPayload] = await Promise.all([
          options.foundationScope ? options.foundationScope.read(identity) : loadInitialProjectFoundation(identity),
          notebookRequest("/notebook/cards/list", { projectID })
        ]);
      }
      await saveNotebookProjectSnapshot({
        accountUserID: accountUserID,
        projectID,
        foundation: foundationPayload,
        cardPayload
      }).catch(() => {});
    } catch (networkError) {
      requireCurrentAccountRequest(requestIdentity);
      if (!privateCacheFallbackAllowed(networkError)) throw networkError;
      const cached = await loadNotebookProjectSnapshot(
        accountUserID,
        projectID
      ).catch(() => null);
      if (!cached?.foundation || !cached?.cardPayload) throw networkError;
      foundationPayload = cached.foundation;
      cardPayload = cached.cardPayload;
      status.textContent = "Offline Notebook · changes will synchronize when connectivity returns.";
    }
    if (disposed || !isCurrentAccountRequest(requestIdentity)) return panel;
    foundation = foundationPayload;
    cards = cardPayload.cards || [];
    notebookReadOnly = cardPayload.access?.readOnly === true;
    shell.replaceChildren();
    panel.append(draftStatus);
    if (identity.sharedOrganizationID) {
      const accessNote = document.createElement("p");
      accessNote.className = "notebook-access-note";
      accessNote.textContent = notebookReadOnly
        ? `${identity.sharedOrganizationName || "Firm"} · ${identity.sharedRole || "viewer"} access · view only`
        : `${identity.sharedOrganizationName || "Firm"} · ${identity.sharedRole || "editor"} access · edits are attributed to your account`;
      shell.append(accessNote);
    }

    const noteMenu = createNotebookNoteMenu({
      onSelect(card) {
        if (selectingCards) {
          if (selectedCardIDs.has(card.id)) selectedCardIDs.delete(card.id);
          else selectedCardIDs.add(card.id);
          updateNotebookCardManagement();
          return;
        }
        void loadCard(card.id).catch((error) => showWebNotice("Note not opened", error.message));
      },
      onTitleChange(value) {
        if (disposed || notebookReadOnly || !isCurrentAccountRequest(requestIdentity) || !activeCard) return;
        activeCard.title = value;
        const summary = cards.find((card) => card.id && card.id === activeCard.id);
        if (summary) summary.title = value;
        markNotebookDirty();
      }
    });
    const rail = noteMenu.menu;
    const railHeader = noteMenu.footer;
    const railLabel = noteMenu.label;
    const newButton = noteMenu.createButton;
    const cardList = noteMenu.list;
    const archiveButton = document.createElement("button");
    archiveButton.className = "notebook-card-archive-action";
    archiveButton.type = "button";
    archiveButton.title = "Show archived notes";
    archiveButton.setAttribute("aria-label", archiveButton.title);
    archiveButton.setAttribute("aria-pressed", "false");
    archiveButton.innerHTML = archiveIconSVG();
    archiveButton.disabled = notebookReadOnly;
    const selectButton = document.createElement("button");
    selectButton.className = "notebook-card-select-action";
    selectButton.type = "button";
    selectButton.title = "Select notes";
    selectButton.setAttribute("aria-label", selectButton.title);
    selectButton.setAttribute("aria-pressed", "false");
    selectButton.innerHTML = selectionModeIconSVG();
    selectButton.disabled = notebookReadOnly;
    const cancelSelectionButton = document.createElement("button");
    cancelSelectionButton.className = "notebook-card-selection-cancel";
    cancelSelectionButton.type = "button";
    cancelSelectionButton.textContent = "Cancel";
    cancelSelectionButton.hidden = true;
    const archiveSelectedButton = document.createElement("button");
    archiveSelectedButton.className = "notebook-card-selection-action notebook-card-selection-archive";
    archiveSelectedButton.type = "button";
    archiveSelectedButton.hidden = true;
    const deleteSelectedButton = document.createElement("button");
    deleteSelectedButton.className = "notebook-card-selection-action notebook-card-selection-delete";
    deleteSelectedButton.type = "button";
    deleteSelectedButton.title = "Delete selected notes";
    deleteSelectedButton.setAttribute("aria-label", deleteSelectedButton.title);
    deleteSelectedButton.innerHTML = trashIconSVG();
    deleteSelectedButton.hidden = true;
    const railActions = noteMenu.management;
    railActions.append(
      cancelSelectionButton,
      archiveButton,
      archiveSelectedButton,
      deleteSelectedButton,
      selectButton
    );
    const focus = document.createElement("section");
    focus.className = "notebook-focus";
    shell.append(noteMenu.element, focus);
    panel.append(draftStatus);

    let notebookAutosaveTask = null;
    let showingArchivedCards = false;
    let selectingCards = false;
    let cardSelectionBusy = false;
    const selectedCardIDs = new Set();

    const notebookSummaryForCard = (card, savedCard = card) => ({
      id: card.id,
      version: card.version,
      cardType: card.cardType,
      title: card.title,
      plainText: savedCard.plainText,
      referenceCount: savedCard.references?.length || 0,
      openQuestions: card.openQuestions || [],
      createdAt: savedCard.createdAt,
      updatedAt: savedCard.updatedAt,
      archivedAt: savedCard.archivedAt || null
    });

    function scheduleNotebookAutosave(delay = 700) {
      window.clearTimeout(notebookAutosaveTimer);
      if (notebookReadOnly || disposed || !isCurrentAccountRequest(requestIdentity) || saveConflict || !dirty || !activeCard) return;
      if (!String(activeCard.title || "").trim()) return;
      notebookAutosaveTimer = window.setTimeout(() => {
        notebookAutosaveTimer = null;
        void saveActiveNotebookCard();
      }, delay);
    }

    function markNotebookDirty() {
      dirty = true;
      notebookRevision += 1;
      void persistFocusedDraft().catch((error) => showDraftStatus(`Device save failed: ${error.message}. Keep this Note open and copy your work.`));
      scheduleNotebookAutosave();
    }

    async function saveActiveNotebookCard() {
      if (notebookAutosaveTask) return notebookAutosaveTask;
      if (notebookReadOnly || disposed || !isCurrentAccountRequest(requestIdentity) || !dirty || !activeCard) return !dirty;
      const revisionAtStart = notebookRevision;
      const cardAtStart = activeCard;
      const saveTask = (async () => {
        try {
          const submittedDraft = await persistFocusedDraft();
          requireCurrentAccountRequest(requestIdentity);
          if (saveConflict || !submittedDraft || navigator.onLine === false) return false;
          const payload = await synchronizeNotebookDraft(submittedDraft, requestIdentity, { deferAcknowledgement: true });
          if (!payload) return false;
          const acknowledgedDraft = payload.submittedDraft;
          const ownsFocusedCard = activeCard === cardAtStart;
          const hasNewerDeviceDraft = submittedDraft.revision !== acknowledgedDraft.revision;
          // Change the local identity before scheduling the acknowledgement. Later edits capture
          // the accepted card ID; already queued writes finish before its atomic rekey.
          if (ownsFocusedCard) {
            activeCard = retainNotebookCardIdentity(activeCard, { ...payload.card, title: activeCard.title, document: draftDocument,
              evidenceLinks: activeCard.evidenceLinks || [], openQuestions: activeCard.openQuestions || [] });
          }
          const acceptedFocusedCard = ownsFocusedCard ? activeCard : null;
          const acknowledgement = draftWriteQueue.then(async () => {
            const result = await acknowledgeNotebookDraft(
              accountUserID, projectID, acknowledgedDraft.cardID || "", acknowledgedDraft.revision, payload.card
            );
            // Publish our own acknowledged checkpoint before the queue admits
            // another edit, rather than after an unrelated cache/network await.
            if (!result.conflict && ownsFocusedCard && activeCard === acceptedFocusedCard) {
              persistedDraft = result.draft;
              persistedCardID = result.draft?.cardID ?? null;
              if (!result.draft) persistedRevision = -1;
            }
            return result;
          });
          draftWriteQueue = acknowledgement;
          const acknowledged = await acknowledgement;
          if (acknowledged?.conflict && acknowledged.draft) {
            persistedDraft = acknowledged.draft;
            persistedCardID = acknowledged.draft.cardID || "";
            persistedRevision = -1;
            saveConflict = true;
            dirty = true;
            if (ownsFocusedCard && activeCard === acceptedFocusedCard) {
              activeCard = retainNotebookCardIdentity(activeCard, { ...activeCard, id: acknowledged.draft.cardID || "", version: acknowledged.draft.baseVersion });
              // The other tab may own the database's current text. Retain it
              // as a separate version before checkpointing this editor again.
              persistedCardID = null;
              await persistFocusedDraft();
            }
          }
          await saveNotebookCardSnapshot(accountUserID, projectID, payload.card);
          await refreshNotebookPendingStatus(requestIdentity);
          if (acknowledged?.conflict) {
            if (!disposed && ownsFocusedCard) showNotebookRecoveryConflict(persistedDraft);
            return false;
          }
          if (disposed || !isCurrentAccountRequest(requestIdentity) || !ownsFocusedCard || activeCard !== acceptedFocusedCard) return false;
          const changedDuringSave = hasNewerDeviceDraft || notebookRevision !== revisionAtStart;
          if (!changedDuringSave) {
            activeCard = retainNotebookCardIdentity(activeCard, payload.card);
            draftDocument = payload.card.document;
            persistedDraft = null;
            persistedRevision = -1;
            persistedCardID = null;
            dirty = false;
          } else {
            dirty = true;
          }
          const summary = notebookSummaryForCard(activeCard, payload.card);
          const provisionalCardID = String(cardAtStart.id || "").trim();
          cards = [summary, ...cards.filter((card) =>
            card.id !== summary.id &&
            (provisionalCardID
              ? card.id !== provisionalCardID
              : Boolean(String(card.id || "").trim()))
          )];
          foundation.artifacts = [
            ...(foundation.artifacts || []).filter((artifact) => artifact.envelope?.id !== payload.card.id),
            { envelope: { id: payload.card.id, type: "notebookCard" }, payload: payload.card }
          ];
          await saveNotebookProjectSnapshot({ accountUserID, projectID, foundation,
            cardPayload: { cards, access: { readOnly: notebookReadOnly } } });
          requireCurrentAccountRequest(requestIdentity);
          if (disposed) return true;
          showDraftStatus(dirty ? "Saved on this device · newer edits waiting to sync" : "Synced");
          renderCardList();
          void refreshNotebookReportStatus().catch(() => false);
          if (dirty) scheduleNotebookAutosave(180);
          void reportDraftMounts.get(projectID)?.refreshSources?.().catch(() => false);
          return !dirty;
        } catch (error) {
          if (disposed || !isCurrentAccountRequest(requestIdentity)) return false;
          if (error.code === "OFFLINE_DRAFT_RECOVERY_REQUIRED") {
            persistedRevision = -1;
            try { await persistFocusedDraft(); }
            catch (checkpointError) { showDraftStatus(`Device save failed: ${checkpointError.message}. Keep this Note open and copy your work.`); }
          } else if (error.payload?.code === "NOTEBOOK_VERSION_CONFLICT") {
            saveConflict = true;
            showDraftStatus("Save conflict · your device draft is preserved. Compare it with the latest Note before saving another version.");
            const latest = error.payload.card;
            if (latest) {
              const review = document.createElement("button");
              review.type = "button";
              review.textContent = "Review save conflict";
              review.addEventListener("click", async () => {
                const confirmed = await confirmWebWarning("Review the current Note",
                  `Current saved Note: ${latest.title}\n\n${[latest.plainText, notebookQuestionsText(latest.openQuestions || [])].filter(Boolean).join("\n\n") || "(No plain text)"}\n\nYour local draft remains in the editor. Save your draft as the next version only after comparing these changes.`,
                  { confirmLabel: "Save my draft as next version" });
                if (!confirmed || disposed || !isCurrentAccountRequest(requestIdentity)) return;
                try {
                  const reviewed = await persistFocusedDraft();
                  requireCurrentAccountRequest(requestIdentity);
                  const rebased = await rebaseNotebookDraftAfterReview(accountUserID, projectID,
                    activeCard.id || "", reviewed.revision, latest);
                  requireCurrentAccountRequest(requestIdentity);
                  activeCard = retainNotebookCardIdentity(activeCard, { ...activeCard, id: rebased.cardID, version: rebased.baseVersion });
                  persistedDraft = rebased;
                  persistedCardID = rebased.cardID;
                  persistedRevision = notebookRevision;
                  saveConflict = false;
                  showDraftStatus("Reviewed device draft · waiting to sync");
                  scheduleNotebookAutosave(0);
                } catch (error) {
                  showDraftStatus(`Conflict review could not be applied: ${error.message}. Your device draft is preserved.`);
                }
              });
              draftStatus.append(" ", review);
            }
          } else {
            showDraftStatus(persistedDraft
              ? `Saved on this device · sync pending: ${error.message}`
              : `Device save failed: ${error.message}. Keep this Note open and copy your work.`);
          }
          return false;
        }
      })();
      notebookAutosaveTask = saveTask.finally(() => { notebookAutosaveTask = null; });
      return notebookAutosaveTask;
    }

    flushNotebookAutosave = async () => {
      window.clearTimeout(notebookAutosaveTimer);
      notebookAutosaveTimer = null;
      if (!dirty) return true;
      await saveActiveNotebookCard();
      try { await persistFocusedDraft(); return true; }
      catch { return false; }
    };

    async function loadCard(cardID) {
      const loadGeneration = ++notebookCardLoadGeneration;
      const workspaceID = activeWorkspaceID;
      const isCurrent = () => loadGeneration === notebookCardLoadGeneration && !disposed &&
        isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === workspaceID;
      if (!isCurrent()) return;
      captureNotebookReturnScroll();
      if (activeCard?.id && editorMount) {
        notebookEditingPositions.set(activeCard.id, {
          selection: editorMount.getEditingPosition?.(),
          scrollTop: focus.querySelector(".notebook-editor-surface")?.scrollTop || 0,
          shellScrollTop: shell.scrollTop
        });
      }
      const preserveFocusedChanges = async () => {
        if (!dirty || !activeCard) return isCurrent();
        const saved = await flushNotebookAutosave();
        if (!isCurrent()) return false;
        if (saved) return true;
        const confirmed = await confirmWebWarning(
          "Discard unsaved Notebook changes?",
          "Your edits to the focused card have not been saved.",
          { confirmLabel: "Discard changes" }
        );
        return isCurrent() && confirmed;
      };
      if (!(await preserveFocusedChanges()) || !isCurrent()) return;
      let outgoingCard = activeCard;
      const outgoingIdentity = notebookCardIdentity(outgoingCard);
      const outgoingIsCurrent = () => activeCard === outgoingCard ||
        (outgoingIdentity && notebookCardIdentity(activeCard) === outgoingIdentity);
      let outgoingRevision = notebookRevision;
      let outgoingChangedDuringLoad = false;
      let payload;
      try {
        payload = await notebookRequest("/notebook/cards/get", { projectID, cardID });
        if (!isCurrent()) return;
        await saveNotebookCardSnapshot(
          accountUserID,
          projectID,
          payload.card
        ).catch(() => {});
        if (!isCurrent()) return;
      } catch (networkError) {
        if (!isCurrent()) return;
        requireCurrentAccountRequest(requestIdentity);
        if (!privateCacheFallbackAllowed(networkError)) throw networkError;
        const cached = await loadNotebookProjectSnapshot(
          accountUserID,
          projectID
        ).catch(() => null);
        if (!isCurrent()) return;
        const cachedCard = cached?.cardDocuments?.[cardID];
        if (!cachedCard) throw networkError;
        payload = { card: cachedCard };
      }
      if (!isCurrent()) return;
      const candidateCard = { ...payload.card };
      const localDraft = await loadNotebookDraft(accountUserID, projectID, cardID).catch(() => null);
      if (!isCurrent()) return;
      const useLocalDraft = Boolean(localDraft);
      const reconciledDocument = await reconcileNotebookDocumentAssets(
        useLocalDraft ? localDraft.document : candidateCard.document,
        projectID,
        requestIdentity
      );
      if (!isCurrent()) return;
      // The old editor remains usable while the next Note loads. Persist any
      // intervening edits before replacing it, including edits during a save.
      while (outgoingIsCurrent() && notebookRevision !== outgoingRevision) {
        outgoingChangedDuringLoad = true;
        outgoingRevision = notebookRevision;
        if (!(await preserveFocusedChanges()) || !isCurrent() || !outgoingIsCurrent()) return;
        outgoingCard = activeCard;
      }
      if (!outgoingIsCurrent() || !isCurrent()) return;
      // Refreshing the selected Note may have fetched its old version before
      // the visible editor saved newer work. Keep that newer focused state.
      if (activeCard?.id === candidateCard.id && (outgoingChangedDuringLoad ||
          Number(activeCard.version || 0) > Number(candidateCard.version || 0))) return;
      const currentCardLabels = notebookDocumentWithCurrentCardLabels(reconciledDocument, cards);
      if (useLocalDraft) {
        candidateCard.version = localDraft.baseVersion;
        candidateCard.title = localDraft.title || "";
        candidateCard.evidenceLinks = localDraft.evidenceLinks || candidateCard.evidenceLinks || [];
        candidateCard.openQuestions = localDraft.openQuestions ?? candidateCard.openQuestions ?? [];
      }
      activeCard = candidateCard;
      draftDocument = currentCardLabels.document;
      saveConflict = false;
      dirty = useLocalDraft || currentCardLabels.changed;
      persistedDraft = localDraft || null;
      persistedCardID = candidateCard.id || "";
      persistedRevision = localDraft ? notebookRevision : -1;
      if (currentCardLabels.changed) notebookRevision += 1;
      if (!showNotebookRecoveryConflict(localDraft)) {
        showDraftStatus(currentCardLabels.changed
          ? "Updated linked reference · waiting to sync"
          : useLocalDraft ? "Recovered device draft · waiting to sync" : "Synced");
      }
      renderCardList();
      await renderFocusedCard();
      if (isCurrent() && activeCard === candidateCard && dirty) scheduleNotebookAutosave();
    }
    mountState.focusCard = loadCard;
    mountState.insertionTarget = () => !disposed && !notebookReadOnly && !saveConflict && activeCard && editorMount
      ? { id: activeCard.id, title: activeCard.title } : null;
    mountState.insertLinkedReference = async (cardID, reference, evidenceLink = null) => {
      requireCurrentAccountRequest(requestIdentity);
      if (disposed || notebookReadOnly || saveConflict || activeCard?.id !== cardID || !editorMount) {
        throw new Error("The destination Note changed or is unavailable. Choose it again.");
      }
      const previousLinks = activeCard.evidenceLinks || [];
      if (evidenceLink) activeCard.evidenceLinks = [...previousLinks, evidenceLink];
      try {
        if (editorMount.insertReference(reference) === false) throw new Error("The Note editor is still loading. Try again.");
      } catch (error) {
        activeCard.evidenceLinks = previousLinks;
        throw error;
      }
      draftDocument = editorMount.getDocument();
      markNotebookDirty();
      await persistFocusedDraft();
    };


    function scheduleIdleNotebookPrefetch() {
      if (disposed || !isCurrentAccountRequest(requestIdentity) || navigator.onLine === false || cards.length < 2) return;
      const prefetch = async () => {
        notebookIdlePrefetchHandle = null;
        notebookIdlePrefetchTimer = null;
        if (disposed || !isCurrentAccountRequest(requestIdentity) || navigator.onLine === false) return;
        const currentAccountUserID = accountUserID;
        if (!currentAccountUserID) return;
        const cached = await loadNotebookProjectSnapshot(
          accountUserID,
          projectID
        ).catch(() => null);
        const cachedCardIDs = new Set(Object.keys(cached?.cardDocuments || {}));
        const pendingCards = cards
          .filter((card) => card.id !== activeCard?.id && !cachedCardIDs.has(card.id))
          .slice(0, notebookIdlePrefetchLimit);
        for (const card of pendingCards) {
          if (disposed || !isCurrentAccountRequest(requestIdentity) || navigator.onLine === false) return;
          try {
            const payload = await notebookRequest("/notebook/cards/get", {
              projectID,
              cardID: card.id
            });
            await saveNotebookCardSnapshot(
              accountUserID,
              projectID,
              payload.card
            );
          } catch {
            return;
          }
        }
      };
      if (typeof window.requestIdleCallback === "function") {
        notebookIdlePrefetchHandle = window.requestIdleCallback(
          () => void prefetch(),
          { timeout: 3000 }
        );
      } else {
        notebookIdlePrefetchTimer = window.setTimeout(() => void prefetch(), 2000);
      }
    }

    async function deleteNotebookCard(card, trigger, options = {}) {
      let target = card;
      if (activeCard?.id === card.id) {
        if (dirty && !(await flushNotebookAutosave())) return;
        target = activeCard;
      }
      if (!options.skipConfirmation) {
        const confirmed = await confirmWebWarning(
          "Delete Notebook Note?",
          `“${target.title}” will be removed from its linked Projects. Its tombstone remains in sync history.`,
          { confirmLabel: "Delete card" }
        );
        if (!confirmed) return false;
      }
      if (trigger) trigger.disabled = true;
      try {
        await notebookRequest("/notebook/cards/delete", {
          projectID,
          cardID: target.id,
          expectedVersion: target.version
        });
        cards = cards.filter((candidate) => candidate.id !== target.id);
        foundation.artifacts = (foundation.artifacts || []).filter(
          (artifact) => artifact.envelope?.id !== target.id
        );
        await Promise.all([
          deleteNotebookDraft(accountUserID, projectID, target.id).catch(() => {}),
          deleteNotebookCardSnapshot(accountUserID, projectID, target.id).catch(() => {}),
          ...((target.imageAssets || []).map((assetID) =>
            deleteLocalNotebookImage(`permitext-notebook-local:${assetID}`).catch(() => {})
          ))
        ]);
        if (activeCard?.id === target.id) {
          activeCard = null;
          draftDocument = emptyNotebookDocument();
          dirty = false;
          renderCardList();
          await renderFocusedCard();
        } else {
          renderCardList();
        }
        await reportDraftMounts.get(projectID)?.refreshSources?.().catch(() => false);
        return true;
      } catch (error) {
        if (trigger) trigger.disabled = false;
        await showWebNotice("Note not deleted", error.message);
        return false;
      }
    }

    async function setNotebookCardArchived(card, archived) {
      if (activeCard?.id === card.id && dirty && !(await flushNotebookAutosave())) return false;
      try {
        const payload = await notebookRequest("/notebook/cards/archive", {
          projectID,
          cardID: card.id,
          expectedVersion: activeCard?.id === card.id ? activeCard.version : card.version,
          archived
        });
        const summary = notebookSummaryForCard(payload.card, payload.card);
        cards = cards.map((candidate) => candidate.id === summary.id ? summary : candidate);
        if (activeCard?.id === summary.id) {
          activeCard = null;
          draftDocument = emptyNotebookDocument();
          dirty = false;
          await renderFocusedCard();
        }
        await saveNotebookProjectSnapshot({
          accountUserID: accountUserID,
          projectID,
          foundation,
          cardPayload: { cards, access: { readOnly: notebookReadOnly } }
        }).catch(() => {});
        await reportDraftMounts.get(projectID)?.refreshSources?.().catch(() => false);
        return true;
      } catch (error) {
        await showWebNotice(archived ? "Note not archived" : "Note not restored", error.message);
        return false;
      }
    }

    const updateNotebookCardManagement = () => {
      const visibleCards = cards.filter((card) => Boolean(card.archivedAt) === showingArchivedCards);
      railHeader.hidden = false;
      rail.classList.toggle("is-selecting-cards", selectingCards);
      rail.classList.toggle("is-showing-archived-cards", showingArchivedCards);
      railLabel.textContent = showingArchivedCards ? "Archive" : "Notes";
      selectButton.setAttribute("aria-pressed", String(selectingCards));
      archiveButton.setAttribute("aria-pressed", String(showingArchivedCards));
      archiveButton.title = showingArchivedCards ? "Show active notes" : "Show archived notes";
      archiveButton.setAttribute("aria-label", archiveButton.title);
      archiveButton.innerHTML = showingArchivedCards ? activeProjectsIconSVG() : archiveIconSVG();
      cancelSelectionButton.hidden = !selectingCards;
      newButton.hidden = selectingCards || showingArchivedCards;
      archiveButton.hidden = selectingCards || !cards.length;
      archiveSelectedButton.hidden = !selectingCards;
      deleteSelectedButton.hidden = !selectingCards;
      selectButton.hidden = visibleCards.length === 0;
      archiveSelectedButton.title = showingArchivedCards ? "Restore selected notes" : "Archive selected notes";
      archiveSelectedButton.setAttribute("aria-label", archiveSelectedButton.title);
      archiveSelectedButton.innerHTML = showingArchivedCards ? archiveRestoreIconSVG() : archiveIconSVG();
      archiveSelectedButton.disabled = cardSelectionBusy || selectedCardIDs.size === 0;
      deleteSelectedButton.disabled = cardSelectionBusy || selectedCardIDs.size === 0;
      cancelSelectionButton.disabled = cardSelectionBusy;
      selectButton.disabled = notebookReadOnly || cardSelectionBusy;
      archiveButton.disabled = cardSelectionBusy;
      cardList.querySelectorAll(".notebook-card-row").forEach((row) => {
        const selected = selectedCardIDs.has(row.dataset.cardId);
        row.classList.toggle("is-selected", selected);
        const button = row.querySelector(".notebook-card-tile");
        if (selectingCards) button?.setAttribute("aria-pressed", String(selected));
      });
    };

    function renderCardList() {
      noteMenu.render({ cards, activeCard, showingArchivedCards, selectingCards, selectedCardIDs,
        readOnly: notebookReadOnly });
      updateNotebookCardManagement();
    }

    refreshNotebookCards = async () => {
      if (disposed) return false;
      const payload = await notebookRequest("/notebook/cards/list", { projectID });
      if (disposed) return false;
      let nextCards = payload.cards || [];
      notebookReadOnly = payload.access?.readOnly === true;
      const focusedCardID = activeCard?.id || "";
      const focusedSummary = focusedCardID
        ? nextCards.find((card) => card.id === focusedCardID)
        : null;
      if (dirty && activeCard) {
        const localSummary = notebookSummaryForCard(activeCard, activeCard);
        nextCards = focusedSummary
          ? nextCards.map((card) => card.id === focusedCardID ? localSummary : card)
          : [localSummary, ...nextCards];
      }
      cards = nextCards;
      if (activeCard) {
        const currentCardLabels = notebookDocumentWithCurrentCardLabels(draftDocument, cards);
        if (currentCardLabels.changed) {
          draftDocument = currentCardLabels.document;
          dirty = true;
          notebookRevision += 1;
          showDraftStatus("Updated linked reference · waiting to sync");
          editorMount?.setDocument(draftDocument);
          scheduleNotebookAutosave();
        }
      }
      renderCardList();
      await saveNotebookProjectSnapshot({
        accountUserID: accountUserID,
        projectID,
        foundation,
        cardPayload: { cards, access: { readOnly: notebookReadOnly } }
      }).catch(() => {});
      if (dirty || !focusedCardID) return true;
      if (!focusedSummary) {
        activeCard = null;
        draftDocument = emptyNotebookDocument();
        await renderFocusedCard();
        return true;
      }
      if (
        Number(focusedSummary.version || 0) !== Number(activeCard?.version || 0) ||
        String(focusedSummary.updatedAt || "") !== String(activeCard?.updatedAt || "")
      ) {
        await loadCard(focusedCardID);
      }
      return true;
    };

    async function renderFocusedCard() {
      if (!disposed && isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === returnScrollContext.workspaceID &&
          notebookMounts.get(projectID) === mountState) {
        rememberNotebookReturnCard(returnScrollContext, activeCard?.id || "");
      }
      editorRenderSequence += 1;
      const renderSequence = editorRenderSequence;
      refreshNotebookReferenceSources = async () => false;
      refreshNotebookReportStatus = async () => false;
      const replaceFocusedContent = (...children) => {
        editorMount?.destroy?.();
        editorMount = null;
        notebookObjectURLs.forEach((url) => URL.revokeObjectURL(url));
        notebookObjectURLs.clear();
        focus.replaceChildren(...children);
      };

      if (!activeCard) {
        const welcome = document.createElement("div");
        welcome.className = "notebook-welcome";
        const welcomeAction = document.createElement("button");
        welcomeAction.className = "notebook-primary-action";
        welcomeAction.type = "button";
        welcomeAction.textContent = "Create first Note";
        welcomeAction.addEventListener("click", () => newButton.click());
        welcome.append(welcomeAction);
        replaceFocusedContent(welcome);
        return;
      }
      const focusedCardID = activeCard.id;
      const focusedCardIdentity = notebookCardIdentity(activeCard);

      const toolbar = document.createElement("div");
      toolbar.className = "notebook-toolbar code-filter-menu notebook-reference-menu";
      toolbar.setAttribute("aria-label", "Insert into note");
      const referenceToggle = document.createElement("button");
      referenceToggle.className = "code-filter-menu-toggle notebook-reference-menu-toggle";
      referenceToggle.type = "button";
      const referenceLabel = document.createElement("span");
      referenceLabel.className = "code-filter-menu-label";
      referenceLabel.textContent = "Insert";
      referenceToggle.append(referenceLabel);
      const referenceList = document.createElement("div");
      referenceList.className = "notebook-reference-list";
      let candidates = (await notebookReferenceCandidates(identity, foundation, cards))
        .filter((reference) =>
          reference.referenceKind !== "notebookCard" ||
          reference.referenceID !== activeCard.id
        );
      if (disposed || !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence || activeCard?.id !== focusedCardID) return;
      const appendReferenceOption = (reference, index, parent) => {
        const option = document.createElement("button");
        option.className = "notebook-reference-option";
        option.type = "button";
        option.disabled = Boolean(reference.disabledReason);
        option.title = reference.disabledReason || reference.label;
        option.dataset.referenceIndex = String(index);
        if (reference.displayTitle) {
          const optionTitle = document.createElement("strong");
          optionTitle.textContent = reference.displayTitle;
          option.append(optionTitle);
          if (reference.displayMeta) {
            const optionMeta = document.createElement("small");
            optionMeta.textContent = reference.displayMeta;
            option.append(optionMeta);
          }
        } else if (reference.disabledReason) {
          const optionTitle = document.createElement("strong");
          optionTitle.textContent = reference.label;
          const optionMeta = document.createElement("small");
          optionMeta.textContent = reference.disabledReason;
          option.append(optionTitle, optionMeta);
        } else {
          option.textContent = reference.label;
        }
        parent.append(option);
      };
      const renderReferenceOptions = () => {
        referenceList.replaceChildren();
        const addInsertAction = (label, action) => {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "notebook-insert-action";
          button.textContent = label;
          button.disabled = notebookReadOnly;
          button.addEventListener("click", () => {
            if (notebookReadOnly || !editorMount) return;
            action();
            referenceMenuState.referenceMenuOpen = false;
            updateCodeFilterMenu(referenceList, referenceMenuState, referenceMenuOptions);
          });
          referenceList.append(button);
        };
        addInsertAction("Image", () => editorMount.insertImage());
        addInsertAction("Finding template", () => {
          activeCard.cardType = "finding";
          draftDocument = appendFindingTemplate(editorMount.getDocument(), () => crypto.randomUUID());
          editorMount.setDocument(draftDocument);
          markNotebookDirty();
        });
        const evidenceGroup = document.createElement("details");
        evidenceGroup.className = "notebook-insert-group";
        const evidenceSummary = document.createElement("summary");
        evidenceSummary.textContent = "Evidence";
        evidenceGroup.append(evidenceSummary);
        referenceList.append(evidenceGroup);
        const canonicalGroups = new Map();
        candidates.forEach((reference, index) => {
          if (reference.referenceKind !== "canonicalSection") return;
          const codePrefix = reference.codePrefix || "BC";
          const chapterNumber = String(reference.chapterNumber || "Other").trim() || "Other";
          if (!canonicalGroups.has(codePrefix)) canonicalGroups.set(codePrefix, new Map());
          const chapters = canonicalGroups.get(codePrefix);
          if (!chapters.has(chapterNumber)) chapters.set(chapterNumber, []);
          chapters.get(chapterNumber).push({ reference, index });
        });
        canonicalGroups.forEach((chapters, codePrefix) => {
          const codeGroup = document.createElement("details");
          codeGroup.className = `notebook-reference-code-group code-theme-${codeTheme(codePrefix)}`;
          codeGroup.open = true;
          const codeSummary = document.createElement("summary");
          codeSummary.className = "notebook-reference-group-title";
          codeSummary.textContent = notebookReferenceCodeTitle(codePrefix);
          const codeBody = document.createElement("div");
          codeBody.className = "notebook-reference-code-body";
          chapters.forEach((entries, chapterNumber) => {
            const chapterGroup = document.createElement("details");
            chapterGroup.className = "notebook-reference-chapter-group";
            chapterGroup.open = true;
            const chapterSummary = document.createElement("summary");
            chapterSummary.className = "notebook-reference-chapter-title";
            chapterSummary.textContent = chapterNumber === "Other" ? "Other provisions" : `Chapter ${chapterNumber}`;
            const chapterBody = document.createElement("div");
            chapterBody.className = "notebook-reference-chapter-body";
            entries.forEach(({ reference, index }) => appendReferenceOption(reference, index, chapterBody));
            chapterGroup.append(chapterSummary, chapterBody);
            codeBody.append(chapterGroup);
          });
          codeGroup.append(codeSummary, codeBody);
          evidenceGroup.append(codeGroup);
        });
        let activeReferenceKind = "";
        let referenceGroup = null;
        candidates.forEach((reference, index) => {
          if (reference.referenceKind === "canonicalSection") return;
          if (reference.referenceKind !== activeReferenceKind) {
            activeReferenceKind = reference.referenceKind;
            referenceGroup = document.createElement("details");
            referenceGroup.className = "notebook-insert-group";
            const groupTitle = document.createElement("summary");
            groupTitle.className = "notebook-reference-group-title";
            groupTitle.textContent = reference.referenceKind === "researchAnswer"
              ? "Assistant answer"
              : reference.referenceKind === "notebookCard"
                ? "Other Notes"
                : "Project references";
            referenceGroup.append(groupTitle);
            referenceList.append(referenceGroup);
          }
          appendReferenceOption(reference, index, referenceGroup);
        });
        if (!canonicalGroups.size) {
          const empty = document.createElement("p");
          empty.className = "notebook-reference-empty";
          empty.textContent = "Save a passage in Evidence to insert it here.";
          evidenceGroup.append(empty);
        }
        if (!candidates.some(reference => reference.referenceKind === "researchAnswer")) {
          const assistantGroup = document.createElement("details");
          assistantGroup.className = "notebook-insert-group";
          const summary = document.createElement("summary");
          summary.textContent = "Assistant answer";
          const empty = document.createElement("p");
          empty.className = "notebook-reference-empty";
          empty.textContent = "Assistant answers linked to this Project will appear here.";
          assistantGroup.append(summary, empty);
          referenceList.append(assistantGroup);
        }
        referenceList.querySelectorAll(".notebook-reference-option").forEach((option) => {
          option.addEventListener("click", () => {
            const reference = candidates[Number(option.dataset.referenceIndex)];
            if (!reference || reference.disabledReason) return;
            try {
              if (editorMount?.insertReference(reference) === false) {
                throw new Error("The Notebook editor is still loading. Try again.");
              }
            } catch (error) {
              void showWebNotice("Reference not inserted", error.message);
              return;
            }
            referenceMenuState.referenceMenuOpen = false;
            updateCodeFilterMenu(referenceList, referenceMenuState, referenceMenuOptions);
          });
        });
        if (notebookReadOnly) {
          referenceList.querySelectorAll("button").forEach((control) => {
            control.disabled = true;
          });
        }
      };
      toolbar.append(referenceToggle, referenceList);
      const referenceMenuState = { referenceMenuOpen: false };
      const referenceMenuOptions = {
        stateKey: "referenceMenuOpen",
        menuName: "Insert into note",
        label: "Insert"
      };
      renderReferenceOptions();
      wireCodeFilterMenu(referenceList, referenceMenuState, referenceMenuOptions);
      referenceToggle.disabled = notebookReadOnly;
      if (notebookReadOnly) {
        toolbar.querySelectorAll("button").forEach((control) => {
          control.disabled = true;
        });
      }
      refreshNotebookReferenceSources = async ({ refreshFoundation = false } = {}) => {
        if (disposed || !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence || activeCard?.id !== focusedCardID) return false;
        if (refreshFoundation) {
          foundation = identity.sharedOrganizationID
            ? await notebookRequest("/organizations/projects/snapshot", { projectID })
                .then((payload) => payload.project)
            : await notebookRequest("/projects/foundation/state", { projectID });
        }
        const nextCandidates = (await notebookReferenceCandidates(identity, foundation, cards))
          .filter((reference) =>
            reference.referenceKind !== "notebookCard" ||
            reference.referenceID !== focusedCardID
          );
        if (disposed || !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence || activeCard?.id !== focusedCardID) return false;
        candidates = nextCandidates;
        renderReferenceOptions();
        referenceToggle.disabled = notebookReadOnly;
        updateCodeFilterMenu(referenceList, referenceMenuState, referenceMenuOptions);
        return true;
      };

      const editorElement = document.createElement("div");
      editorElement.className = "notebook-editor-surface";
      const activateFocusedReference = (referenceElement) => {
        const referenceID = referenceElement.dataset.referenceId;
        void openNotebookReference(identity, foundation, {
          referenceKind: referenceElement.dataset.referenceKind,
          referenceID,
          label: referenceElement.dataset.referenceLabel || referenceElement.textContent || "Linked item",
          evidenceLink: (activeCard.evidenceLinks || []).find((link) => link.id === referenceID) || null
        }, loadCard, paneID, projectID).catch((error) => showWebNotice("Linked item not opened", error.message));
      };
      editorElement.addEventListener("click", (event) => {
        const referenceElement = event.target.closest?.("[data-permitext-reference]");
        if (!referenceElement) return;
        event.preventDefault();
        event.stopPropagation();
        activateFocusedReference(referenceElement);
      }, true);
      editorElement.addEventListener("keydown", (event) => {
        if (event.key !== "Enter" && event.key !== " ") return;
        const referenceElement = event.target.closest?.("[data-permitext-reference]");
        if (!referenceElement) return;
        event.preventDefault();
        event.stopPropagation();
        activateFocusedReference(referenceElement);
      }, true);
      const footer = document.createElement("div");
      footer.className = "notebook-card-footer";
      const footerActions = document.createElement("div");
      const researchButton = document.createElement("button");
      researchButton.className = "notebook-secondary-action";
      researchButton.type = "button";
      researchButton.textContent = "Start Research";
      researchButton.title = "Use this card as the starting point for a new evidence-selected Research question";
      researchButton.hidden = true;
      const coordinateButton = document.createElement("button");
      coordinateButton.className = "notebook-secondary-action";
      coordinateButton.type = "button";
      coordinateButton.textContent = "Coordinate";
      coordinateButton.title = activeCard.id
        ? "Open a coordination item linked to this Notebook card"
        : "Save this card before opening a coordination item";
      coordinateButton.disabled = !activeCard.id;
      coordinateButton.hidden = !releaseSurfaceVisibility.coordination ||
        !projectCollaborationAccess(identity, "project.review.request");
      coordinateButton.addEventListener("click", () => {
        void openCoordinationComposer({
          projectID,
          type: "revision-request",
          targetKind: "notebookCard",
          targetID: activeCard.id,
          snapshot: { label: `Notebook: ${activeCard.title || "Untitled card"}` }
        });
      });
      const reportButton = document.createElement("button");
      reportButton.type = "button";
      reportButton.className = "notebook-secondary-action workflow-action workflow-action-secondary";
      reportButton.textContent = "Add to Report";
      reportButton.disabled = notebookReadOnly;
      reportButton.addEventListener("click", async () => {
        const handoffRenderSequence = editorRenderSequence;
        reportButton.disabled = true;
        try {
          const synchronized = await saveActiveNotebookCard();
          if (disposed || !isCurrentAccountRequest(requestIdentity) || handoffRenderSequence !== editorRenderSequence) return;
          if (!synchronized || dirty || saveConflict) throw new Error("Finish syncing this Note and resolve any save conflict before adding it to a Report. Your device draft is preserved.");
          if (!activeCard?.id) throw new Error("Save this Note before adding it to a Report.");
          const addedReport = await promoteNotebookCardToReport(identity, activeCard);
          reportAdditionFeedback(reportButton, addedReport);
        } catch (error) {
          if (!disposed && isCurrentAccountRequest(requestIdentity)) await showWebNotice("Report handoff not completed", error.message);
        }
        finally { if (!disposed) reportButton.disabled = notebookReadOnly; }
      });
      footerActions.append(reportButton, researchButton, coordinateButton);
      const module = await loadNotebookModule();
      if (disposed || !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence || activeCard?.id !== focusedCardID) return;
      // The indicator paints connected hosts on the next frame. Schedule it
      // only after loading the editor, immediately before attaching the footer.
      const reportMembership = reportMembershipIndicator(projectID, "notebookCard", activeCard);
      refreshNotebookReportStatus = async () => {
        if (disposed || !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence ||
            notebookCardIdentity(activeCard) !== focusedCardIdentity) return false;
        reportMembership.dataset.reportSourceId = activeCard.id || "";
        await refreshProjectReportMembership(projectID);
        return true;
      };
      footer.append(reportMembership, footerActions);
      const focusedContent = [editorElement];
      if (notebookReadOnly) panel.append(draftStatus);
      focusedContent.push(footer);
      replaceFocusedContent(...focusedContent);

      let scrollCaptureReady = false;
      const captureReturnScroll = () => {
        if (!scrollCaptureReady || disposed || !panel.isConnected || !editorElement.isConnected ||
            !isCurrentAccountRequest(requestIdentity) || notebookMounts.get(projectID) !== mountState ||
            renderSequence !== editorRenderSequence || activeCard?.id !== focusedCardID) return;
        rememberNotebookReturnScroll(returnScrollContext, focusedCardID, {
          scrollTop: editorElement.scrollTop, shellScrollTop: shell.scrollTop
        });
      };
      releaseNotebookReturnScroll();
      captureNotebookReturnScroll = captureReturnScroll;
      editorElement.addEventListener("scroll", captureReturnScroll, { passive: true });
      shell.addEventListener("scroll", captureReturnScroll, { passive: true });
      releaseNotebookReturnScroll = () => {
        editorElement.removeEventListener("scroll", captureReturnScroll);
        shell.removeEventListener("scroll", captureReturnScroll);
      };
      editorMount = module.mountPermitextNotebookEditor(editorElement, {
        document: draftDocument,
        autofocus: false,
        editable: !notebookReadOnly,
        toolbarInsertElement: toolbar,
        toolbarStatusElement: draftStatus,
        uploadFile: (file) => uploadNotebookAsset(projectID, file, activeCard.id, requestIdentity).catch((error) => {
          void showWebNotice("Image not added", error.message);
          throw error;
        }),
        async resolveFileUrl(url) {
          const resolved = await resolveNotebookAsset(projectID, url, requestIdentity);
          if (resolved.startsWith("blob:")) notebookObjectURLs.add(resolved);
          return resolved;
        },
        onChange(document) {
          if (notebookReadOnly || disposed || !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence) return;
          draftDocument = document;
          markNotebookDirty();
        },
        onReady() {
          const localPosition = notebookEditingPositions.get(focusedCardID);
          const position = localPosition || readNotebookReturnScroll(returnScrollContext, focusedCardID);
          window.requestAnimationFrame(() => {
            if (disposed || !panel.isConnected || !editorElement.isConnected || notebookMounts.get(projectID) !== mountState ||
                !isCurrentAccountRequest(requestIdentity) || renderSequence !== editorRenderSequence || activeCard?.id !== focusedCardID) return;
            if (localPosition?.selection) editorMount?.restoreEditingPosition?.(localPosition.selection);
            if (position) {
              editorElement.scrollTop = position.scrollTop;
              shell.scrollTop = position.shellScrollTop;
            }
            scrollCaptureReady = true;
          });
        },
        onOpenReference: null
      });
      if (!notebookReadOnly && !activeCard.id) {
        noteMenu.editTitle();
      }
      researchButton.addEventListener("click", async () => {
        const bodyText = notebookRecoveryPlainText(editorMount?.getDocument() || draftDocument).trim();
        researchQuestionDraft = bodyText || activeCard.title;
        const researchWasOpen = Boolean(state.utilities.analysis);
        await focusUtility("analysis");
        if (researchWasOpen) {
          await transitionWorkspace("utility", { refreshPaneIDs: ["utility:analysis"] });
          scrollPaneIntoView("utility:analysis");
        }
      });
    }

    archiveButton.addEventListener("click", () => {
      showingArchivedCards = !showingArchivedCards;
      selectingCards = false;
      selectedCardIDs.clear();
      renderCardList();
    });
    selectButton.addEventListener("click", () => {
      selectingCards = !selectingCards;
      selectedCardIDs.clear();
      renderCardList();
    });
    cancelSelectionButton.addEventListener("click", () => {
      selectingCards = false;
      selectedCardIDs.clear();
      renderCardList();
      selectButton.focus({ preventScroll: true });
    });
    archiveSelectedButton.addEventListener("click", async () => {
      const selectedCards = cards.filter((card) => selectedCardIDs.has(card.id));
      if (!selectedCards.length) return;
      cardSelectionBusy = true;
      updateNotebookCardManagement();
      for (const card of selectedCards) {
        if (!(await setNotebookCardArchived(card, !showingArchivedCards))) break;
      }
      cardSelectionBusy = false;
      selectingCards = false;
      selectedCardIDs.clear();
      renderCardList();
    });
    deleteSelectedButton.addEventListener("click", async () => {
      const selectedCards = cards.filter((card) => selectedCardIDs.has(card.id));
      if (!selectedCards.length) return;
      const confirmed = await confirmWebWarning(
        "Delete selected Notebook Notes?",
        `${selectedCards.length} selected ${selectedCards.length === 1 ? "Note" : "Notes"} will be removed from linked Projects. Tombstones remain in sync history.`,
        { confirmLabel: selectedCards.length === 1 ? "Delete Note" : `Delete ${selectedCards.length}` }
      );
      if (!confirmed) return;
      cardSelectionBusy = true;
      updateNotebookCardManagement();
      for (const card of selectedCards) {
        if (!(await deleteNotebookCard(card, null, { skipConfirmation: true }))) break;
      }
      cardSelectionBusy = false;
      selectingCards = false;
      selectedCardIDs.clear();
      renderCardList();
    });
    rail.addEventListener("keydown", (event) => {
      if (event.key !== "Escape" || !selectingCards || cardSelectionBusy) return;
      event.preventDefault();
      selectingCards = false;
      selectedCardIDs.clear();
      renderCardList();
      selectButton.focus({ preventScroll: true });
    });

    newButton.addEventListener("click", async () => {
      const loadGeneration = ++notebookCardLoadGeneration;
      const workspaceID = activeWorkspaceID;
      const isCurrent = () => loadGeneration === notebookCardLoadGeneration && !disposed &&
        isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === workspaceID;
      const preserveFocusedChanges = async () => {
        if (!dirty || !activeCard) return isCurrent();
        const saved = await flushNotebookAutosave();
        if (!isCurrent()) return false;
        if (saved) return true;
        const confirmed = await confirmWebWarning(
          "Discard unsaved Notebook changes?",
          "Your edits to the focused card have not been saved.",
          { confirmLabel: "Discard changes" }
        );
        return isCurrent() && confirmed;
      };
      if (!(await preserveFocusedChanges()) || !isCurrent()) return;
      let outgoingCard = activeCard;
      const outgoingIdentity = notebookCardIdentity(outgoingCard);
      const outgoingIsCurrent = () => activeCard === outgoingCard ||
        (outgoingIdentity && notebookCardIdentity(activeCard) === outgoingIdentity);
      let outgoingRevision = notebookRevision;
      let pendingNewDraft;
      try {
        pendingNewDraft = await loadNotebookDraft(accountUserID, projectID, "");
      } catch (error) {
        if (isCurrent()) showDraftStatus(`Could not check the saved new Note draft: ${error.message}. Try New Note again.`);
        return;
      }
      if (!isCurrent()) return;
      const candidateDocument = pendingNewDraft
        ? await reconcileNotebookDocumentAssets(pendingNewDraft.document, projectID, requestIdentity)
        : emptyNotebookDocument();
      if (!isCurrent()) return;
      while (outgoingIsCurrent() && notebookRevision !== outgoingRevision) {
        outgoingRevision = notebookRevision;
        if (!(await preserveFocusedChanges()) || !isCurrent() || !outgoingIsCurrent()) return;
        outgoingCard = activeCard;
      }
      if (!outgoingIsCurrent() || !isCurrent()) return;
      if (pendingNewDraft) {
        activeCard = { id: "", version: pendingNewDraft.baseVersion ?? 0,
          cardType: pendingNewDraft.cardType || "finding", title: pendingNewDraft.title || "",
          references: [], evidenceLinks: pendingNewDraft.evidenceLinks || [], openQuestions: pendingNewDraft.openQuestions || [] };
        draftDocument = candidateDocument;
        dirty = true;
        persistedDraft = pendingNewDraft;
        persistedCardID = "";
        persistedRevision = notebookRevision;
        saveConflict = Boolean(pendingNewDraft.recoveryConflict);
        if (!showNotebookRecoveryConflict(pendingNewDraft)) showDraftStatus("Recovered device draft · finish syncing this Note before creating another");
        renderCardList();
        await renderFocusedCard();
        if (isCurrent()) scheduleNotebookAutosave();
        return;
      }
      persistedDraft = null;
      persistedCardID = null;
      persistedRevision = -1;
      saveConflict = false;
      activeCard = {
        id: "",
        version: 0,
        cardType: "finding",
        title: "",
        plainText: "",
        references: [],
        evidenceLinks: []
      };
      draftDocument = candidateDocument;
      dirty = false;
      renderCardList();
      await renderFocusedCard();
    });

    renderCardList();
    const unsavedDraft = await loadNotebookDraft(accountUserID, projectID, "").catch(() => null);
    requireCurrentAccountRequest(requestIdentity);
    if (unsavedDraft?.document) {
      activeCard = {
        id: "",
        version: unsavedDraft.baseVersion || 0,
        cardType: "finding",
        title: unsavedDraft.title || "",
        plainText: "",
        references: [],
        evidenceLinks: unsavedDraft.evidenceLinks || [],
        openQuestions: unsavedDraft.openQuestions || []
      };
      draftDocument = await reconcileNotebookDocumentAssets(unsavedDraft.document, projectID, requestIdentity);
      dirty = true;
      persistedDraft = unsavedDraft;
      persistedRevision = notebookRevision;
      persistedCardID = "";
      if (!showNotebookRecoveryConflict(unsavedDraft)) showDraftStatus(notebookReadOnly ? "Recovered device draft · view only" : "Recovered device draft · waiting to sync");
      renderCardList();
      await renderFocusedCard();
      scheduleNotebookAutosave();
    } else if (cards.some(card => !card.deletedAt && !card.archivedAt)) {
      const pendingCardID = pendingNotebookCardByProject.get(projectID);
      const returnCardID = readNotebookReturnCard(returnScrollContext, cards);
      const explicitCard = cards.find((card) => card.id === pendingCardID);
      const initialCard = explicitCard || cards.find((card) => card.id === returnCardID) ||
        cards.find(card => !card.deletedAt && !card.archivedAt);
      pendingNotebookCardByProject.delete(projectID);
      try {
        await loadCard(initialCard.id);
      } catch (error) {
        // A remembered card may have been removed after the list request.
        const unavailable = [404, 410].includes(Number(error.status));
        const fallback = cards.find((card) => card.id !== initialCard.id && !card.deletedAt && !card.archivedAt);
        if (explicitCard || initialCard.id !== returnCardID || !unavailable || disposed ||
            !isCurrentAccountRequest(requestIdentity) || activeWorkspaceID !== returnScrollContext.workspaceID ||
            notebookMounts.get(projectID) !== mountState) throw error;
        rememberNotebookReturnCard(returnScrollContext, "");
        cards = cards.filter((card) => card.id !== initialCard.id);
        if (fallback) await loadCard(fallback.id);
        else { activeCard = null; await renderFocusedCard(); }
      }
      scheduleIdleNotebookPrefetch();
    } else {
      await renderFocusedCard();
    }
  } catch (error) {
    if (disposed || !isCurrentAccountRequest(requestIdentity)) return panel;
    status.textContent = error.payload?.code === "PRO_REQUIRED_NOTEBOOK"
      ? "The Project Notebook is included with Permitext Pro."
      : `Notebook unavailable: ${error.message}`;
    await appendNotebookDeviceRecovery(shell, projectID, requestIdentity);
  }
  return panel;
}

function emptyProjectReportDraft(project) {
  return {
    id: "",
    version: 0,
    title: `${project.name || "Project"} Code Research Report`,
    reportDate: new Date().toISOString(),
    introduction: "",
    blocks: []
  };
}

async function notebookCardReportBlock(project, cardID) {
  const projectID = projectDetailKey(projectIdentity(project));
  const payload = await postResearch("/reports/drafts/list", { projectID });
  const draft = payload.drafts?.[0] || null;
  if (!draft) return null;
  return (draft.blocks || []).find((block) =>
    block.derivedFrom?.kind === "notebookCard" && block.derivedFrom.id === cardID
  ) || null;
}

function appendUniqueReportSources(draft, sources) {
  draft.blocks ||= [];
  for (const source of sources) {
    if (draft.blocks.some(block => block.kind === source.kind && block.sourceID === source.id)) continue;
    const legacyIndex = source.kind === "notebookCard" ? draft.blocks.findIndex(block =>
      block.derivedFrom?.kind === "notebookCard" && block.derivedFrom.id === source.id) : -1;
    if (legacyIndex >= 0) {
      // An existing edited snapshot is already included. Updating it is explicit.
      continue;
    }
    draft.blocks.push({ id: crypto.randomUUID(), kind: source.kind, sourceID: source.id,
      label: source.label, sourceClassification: source.sourceClassification });
  }
}

async function addProjectSourcesToReport(project, selectSources) {
  const identity = projectIdentity(project);
  const projectID = projectDetailKey(identity);
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const check = () => {
    requireCurrentAccountRequest(requestIdentity);
    if (workspaceID !== activeWorkspaceID) throw accountContextChangedError();
  };
  if (!hasCapability("professional-exports")) throw new Error("Pro is required to add to a Report.");
  if (identity.sharedOnly) throw new Error("Shared Report editing is not available yet.");
  const [draftPayload, sourcePayload] = await Promise.all([
    postResearch("/reports/drafts/list", { projectID }),
    postResearch("/reports/sources/list", { projectID })
  ]);
  check();
  const selectedSources = selectSources(sourcePayload.sources || []);
  if (!selectedSources.length) throw new Error("This material is not available for this Project's Report yet. Sync it and try again.");
  const drafts = [...(draftPayload.drafts || [])];
  const mountedDraft = reportDraftMounts.get(projectID)?.getDraftSnapshot?.();
  if (mountedDraft && !mountedDraft.id && reportDraftMounts.get(projectID)?.hasUnsavedChanges?.()) drafts.unshift(mountedDraft);
  if (!drafts.length) drafts.push(emptyProjectReportDraft(identity));
  let target = drafts[0];
  if (drafts.length > 1) {
    const selected = await openWebWarning({ title: "Add to Report", message: "Choose the destination Report.",
      confirmLabel: "Add to Report", choices: drafts.map((draft, index) => ({ value: String(index), label: `${draft.title || "Untitled Report"}${selectedSources.every(source => reportsContainingSource([draft], source.kind, source.id).length) ? " · Already included" : ""}` })) });
    check();
    if (selected === false) return null;
    target = drafts[Number(selected)];
  }
  check();
  const currentTarget = reportDraftMounts.get(projectID)?.getDraftSnapshot?.();
  const existingTarget = currentTarget?.id === target.id ? currentTarget : target;
  if (selectedSources.every(source => (existingTarget.blocks || []).some(block => block.kind === source.kind && block.sourceID === source.id))) {
    await refreshProjectReportMembership(projectID, true);
    check();
    return target;
  }
  const mount = reportDraftMounts.get(projectID);
  let saved;
  if (mount?.getDraftSnapshot?.().id === target.id) {
    saved = await mount.addSources(target.id, selectedSources);
  } else {
    const draft = structuredClone(target);
    appendUniqueReportSources(draft, selectedSources);
    check();
    const payload = await postResearch("/reports/drafts/save", { projectID, draftID: draft.id,
      expectedVersion: draft.version || 0, title: draft.title, reportDate: draft.reportDate,
      introduction: draft.introduction, blocks: draft.blocks });
    check();
    saved = payload.draft;
    await reportDraftMounts.get(projectID)?.refreshArtifacts?.();
  }
  check();
  await notebookMounts.get(projectID)?.refreshReportStatus?.().catch(() => false);
  await refreshProjectReportMembership(projectID, true);
  check();
  return saved;
}

const reportMembershipRequests = new Map();
const reportMembershipCache = new Map();

async function refreshProjectReportMembership(projectID, force = false) {
  if (!projectID || !hasCapability("professional-exports")) return;
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const key = JSON.stringify([identity, workspaceID, projectID]);
  const paint = data => {
    if (!isCurrentAccountRequest(identity) || workspaceID !== activeWorkspaceID) return;
    const drafts = [...data.drafts];
    const mounted = reportDraftMounts.get(projectID)?.getDraftSnapshot?.();
    if (mounted) {
      const index = drafts.findIndex(draft => draft.id === mounted.id);
      if (index >= 0) drafts[index] = mounted;
      else drafts.unshift(mounted);
    }
    track.querySelectorAll("[data-report-membership-project]").forEach(host => {
      if (host.dataset.reportMembershipProject !== projectID) return;
      let sourceID = host.dataset.reportSourceId;
      if (host.dataset.reportSourceKind === "evidence") {
        sourceID = data.sources.find(source => source.kind === "evidence" &&
          String(source.sectionID) === host.dataset.reportSectionId &&
          source.sourceLibraryVersion === host.dataset.reportEdition &&
          String(source.selectionBlockID || "") === host.dataset.reportBlockId)?.id;
      }
      const included = sourceID ? reportsContainingSource(drafts,host.dataset.reportSourceKind,sourceID) : [];
      host.classList.toggle("is-in-report", included.length > 0);
      host.textContent = included.length
        ? included.length === 1 ? `In Report · ${included[0].title || "Untitled Report"}` : `In ${included.length} Reports`
        : drafts.length === 1 ? `Destination · ${drafts[0].title || "Untitled Report"}`
        : drafts.length > 1 ? "Choose a Report when adding" : "Adding creates the first Report";
      host.title = included.length ? included.map(draft => draft.title || "Untitled Report").join(", ") : host.textContent;
      host.setAttribute("aria-label", included.length ? `Included in ${host.title}` : host.textContent);
      if (host.dataset.reportMembershipMode === "action") {
        host.textContent = included.length ? "In Report" : "Add to Report";
        const sourceLabel = host.dataset.reportSourceKind === "researchAnswer" ? "Assistant answer" : "evidence";
        host.setAttribute("aria-label", included.length ? `In Report: ${host.title}. Choose a Report to add this ${sourceLabel}.` : `Add ${sourceLabel} to Report`);
      }
    });
  };
  if (!force && reportMembershipCache.has(key)) { paint(reportMembershipCache.get(key)); return; }
  if (reportMembershipRequests.has(key)) return reportMembershipRequests.get(key);
  const request = Promise.all([
    postResearch("/reports/drafts/list", { projectID }),
    postResearch("/reports/sources/list", { projectID })
  ]).then(([drafts,sources]) => {
    if (!isCurrentAccountRequest(identity) || workspaceID !== activeWorkspaceID) return;
    const data = {drafts:drafts.drafts || [],sources:sources.sources || []};
    reportMembershipCache.clear();
    reportMembershipCache.set(key,data); paint(data);
  }).catch(() => {
    if (!isCurrentAccountRequest(identity) || workspaceID !== activeWorkspaceID) return;
    track.querySelectorAll("[data-report-membership-project]").forEach(host => {
      if (host.dataset.reportMembershipProject === projectID) host.textContent = "Report status unavailable";
    });
  }).finally(() => reportMembershipRequests.delete(key));
  reportMembershipRequests.set(key,request);
  return request;
}

const scheduledReportMembershipProjects = new Set();

function reportMembershipIndicator(projectID, kind, source, mode = "status") {
  const status = document.createElement(mode === "action" ? "button" : "p");
  if (mode === "action") status.type = "button";
  status.dataset.reportMembershipMode = mode;
  status.className = "report-membership-status";
  if (mode !== "action") status.setAttribute("role", "status");
  status.dataset.reportMembershipProject = projectID;
  status.dataset.reportSourceKind = kind;
  status.dataset.reportSourceId = source.id || "";
  if (kind === "evidence") {
    status.dataset.reportSectionId = String(source.sectionID);
    status.dataset.reportEdition = syncCodeVersion(source.codeVersion);
    status.dataset.reportBlockId = source.scope === "section" ? "" : String(source.blockID || "").trim();
  }
  status.textContent = "Checking Report…";
  if (!scheduledReportMembershipProjects.has(projectID)) {
    scheduledReportMembershipProjects.add(projectID);
    window.requestAnimationFrame(() => {
      scheduledReportMembershipProjects.delete(projectID);
      void refreshProjectReportMembership(projectID);
    });
  }
  return status;
}

function reportAdditionFeedback(button, draft) {
  if (!draft || !button.isConnected) return;
  button.dataset.reportActionLabel ||= button.textContent;
  window.clearTimeout(button.reportFeedbackTimer);
  button.setAttribute("aria-live", "polite");
  button.textContent = button.dataset.reportActionLabel;
  button.title = `Included in ${draft.title || "Report"}. Adding again will not duplicate it.`;

}

async function addSavedEvidenceToReport(project, items) {
  return addProjectSourcesToReport(project, sources => items.map(item => {
    const blockID = item.scope === "section" ? "" : String(item.blockID || "").trim();
    const source = sources.find(source => source.kind === "evidence" &&
      String(source.sectionID) === String(item.sectionID) &&
      source.sourceLibraryVersion === syncCodeVersion(item.codeVersion) &&
      String(source.selectionBlockID || "") === blockID);
    if (!source) throw new Error("A selected passage is not available for this Project's Report. Sync the evidence and try again.");
    return source;
  }));
}

async function promoteNotebookCardToReport(project, card) {
  if (!String(card.plainText || "").trim() && !(card.references || []).length) {
    throw new Error("Write the Note or link a source before adding it to a Report.");
  }
  return addProjectSourcesToReport(project, sources => sources.filter(source => source.kind === "notebookCard" && source.id === card.id));
}

function reportSourceClassificationLabel(value) {
  return {
    "published-code": "Published code",
    "user-authored": "User-authored",
    "ai-assisted": "AI-assisted Research",
    "project-material": "Project material"
  }[value] || "Project content";
}

function reportBlockTitle(block) {
  if (block.kind === "heading") return block.text || "Heading";
  if (block.kind === "paragraph") return (block.text || "Paragraph").slice(0, 80);
  if (block.kind === "list") return `${block.items?.length || 0} list items`;
  return block.label || block.title || block.kind;
}

function createReportPaneHeader(closeReport) {
  const header = document.createElement("header");
  header.className = "report-draft-header";
  const heading = document.createElement("div");
  heading.className = "report-heading";
  const title = document.createElement("h2");
  title.textContent = "Report";
  title.className = "eyebrow panel-kind";
  heading.append(title);
  const close = document.createElement("button");
  close.className = "icon-button utility-close report-draft-close";
  close.type = "button";
  close.title = "Close Report";
  close.setAttribute("aria-label", "Close Report");
  close.innerHTML = circleXIconSVG();
  close.addEventListener("click", () => { void closeReport(); });
  const actions = document.createElement("div");
  actions.className = "panel-actions report-draft-header-actions";
  actions.append(close);
  header.append(heading, actions);
  return header;
}

async function renderProjectReportDraft(project, resume = null) {
  if (!hasCapability("professional-exports")) return renderProLockedPane(paneIDForProjectReportDraft(project), "Reports");
  const requestIdentity = captureAccountRequest();
  const requestWorkspaceID = activeWorkspaceID;
  const accountUserID = requestIdentity.userID;
  const reportRequest = (path, values) => { requireCurrentAccountRequest(requestIdentity); return postResearch(path, values); };
  const identity = projectIdentity(project);
  const projectID = projectDetailKey(identity);
  const paneID = paneIDForProjectReportDraft(identity);
  reportDraftMounts.get(projectID)?.dispose?.();

  const panel = document.createElement("article");
  panel.className = "workspace-panel report-draft-panel";
  panel.dataset.paneId = paneID;
  panel.dataset.projectId = projectID;
  panel.style.setProperty("--project-color", identity.color || "#c96410");
  applyPaneWeight(panel, paneID);

  const header = createReportPaneHeader(() => closeProjectReportDraft(identity));
  header.hidden = true;

  const shell = document.createElement("div");
  shell.className = "report-draft-shell";
  const status = document.createElement("p");
  status.className = "report-draft-status";
  status.setAttribute("role", "status");
  status.hidden = true;
  shell.append(status);
  panel.append(header, shell);

  let drafts = [];
  let sources = [];
  const sourcePreviewRequests = new Map();
  let sourceWarnings = [];
  let history = [];
  let reportOptions = {
    templates: [],
    defaultReportTemplateID: "permitext-standard",
    branding: { displayName: "Permitext", accentColorHex: "#a65318" }
  };
  let selectedReportTemplateID = "permitext-standard";
  let activeDraft = emptyProjectReportDraft(identity);
  let dirty = false;
  let disposed = false;
  let refreshReportSources = async () => false;
  let refreshReportArtifacts = async () => false;
  let draggedReportBlock = null;
  let outlineController = null;
  let comparisonController = null;
  const outlineSectionExpansion = new Map();
  let renderedDraftKey = null;
  let outlineNavigationGeneration = 0;
  let reportPresentationInteraction = 0;
  for (const event of ["pointerdown", "wheel", "keydown"]) {
    panel.addEventListener(event, () => { reportPresentationInteraction += 1; }, {passive: true});
  }
  let autosave = null;
  let recoveryEditorID = crypto.randomUUID();
  let recoveredDrafts = [];
  let restoredRecovery = null;
  let savePresentation = { state: "saved", error: null, recoverable: false };
  const beforeReportUnload = event => {
    if (!dirty) return;
    event.preventDefault(); event.returnValue = "";
  };
  window.addEventListener("beforeunload", beforeReportUnload);
  const reportSourceGroupExpanded = new Map();
  const reportLibraryScroll = { sources: 0 };
  const reportSectionExpanded = (sectionName, fallback = true) => {
    const currentSessionValue = reportSourceGroupExpanded.get(sectionName);
    return typeof currentSessionValue === "boolean"
      ? currentSessionValue
      : projectSectionExpanded(identity, `Report:${sectionName}`, fallback);
  };
  const persistReportSectionExpanded = (sectionName, expanded) => {
    reportSourceGroupExpanded.set(sectionName, Boolean(expanded));
    persistProjectSectionExpansion(identity, `Report:${sectionName}`, expanded);
  };
  const mountState = {
    panel,
    getPresentationState: () => !disposed && isCurrentAccountRequest(requestIdentity) && requestWorkspaceID === activeWorkspaceID && renderedDraftKey ? captureReportResume(panel, {
      draftID: activeDraft.id || "", versionID: comparisonController?.selectedID || "",
      comparisonScroll: comparisonController?.capturePosition(), outlineSections: [...outlineSectionExpansion]
    }) : null,
    async restorePresentation(snapshot) {
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
      for (const [key, expanded] of snapshot.outlineSections) outlineSectionExpansion.set(key, expanded);
      applyReportResumeLayout(panel, snapshot);
      renderWorkspaceContent();
      if (snapshot.versionID && history.some(report => report.id === snapshot.versionID)) await openHistoricalReport(snapshot.versionID);
      applyReportResumeLayout(panel, snapshot);
      syncReferenceReaderLayout();
      comparisonController?.restorePosition(snapshot.comparisonScroll);
      restoreReportResumeScroll(panel, snapshot);
      const interaction = reportPresentationInteraction;
      await navigateReportOutline({requests: sourcePreviewRequests.values(),
        isCurrent: () => !disposed && isCurrentAccountRequest(requestIdentity) && requestWorkspaceID === activeWorkspaceID &&
          reportScreen?.isOpen() && reportPresentationInteraction === interaction,
        navigate: () => restoreReportResumeScroll(panel, snapshot)});
    },
    hasUnsavedChanges: () => dirty,
    getDraftSnapshot: () => structuredClone(activeDraft),
    async addSources(draftID, selectedSources) {
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) throw accountContextChangedError();
      if (activeDraft.id !== draftID || generatingReport || deletingReport || autosave?.isSaving()) throw new Error("The Report is busy or has changed. Try adding again.");
      appendUniqueReportSources(activeDraft, selectedSources);
      setDirty();
      renderWorkspaceContent();
      if (!await saveDraft()) throw new Error("The Report could not finish saving. Your added material and edits remain in the Report; use Retry to save them.");
      return structuredClone(activeDraft);
    },
    async confirmDiscardIfNeeded() {
      if (!dirty || await saveDraft()) return true;
      const retained = autosave?.isRecoverable();
      return confirmWebWarning(
        retained ? "Leave with unsynced Report edits?" : "Discard unsaved Report changes?",
        retained ? `A recovery copy of “${activeDraft.title || "Untitled report"}” is saved on this device. You can recover it when you return to this Project.`
          : `Your edits to “${activeDraft.title || "Untitled report"}” could not be saved to the server or this device.`,
        { confirmLabel: retained ? "Leave Report" : "Discard changes" }
      );
    },
    async refreshSources() {
      return refreshReportSources();
    },
    async refreshArtifacts(options = {}) {
      return refreshReportArtifacts(options);
    },
    dispose() {
      disposed = true;
      outlineController?.dispose();
      comparisonController?.dispose();
      autosave?.dispose();
      window.removeEventListener("beforeunload", beforeReportUnload);
      panel.closest(".report-screen")?.remove();
    }
  };
  reportDraftMounts.set(projectID, mountState);

  const clearStatus = () => {
    status.textContent = "";
    status.hidden = true;
  };

  const showStatusError = (message) => {
    status.textContent = message;
    status.hidden = false;
  };

  if (!activeAccount()) {
    showStatusError("Sign in from Account to use private Project Reports.");
    return panel;
  }

  const paintReportSaveState = () => {
    const label = shell.querySelector(".report-autosave-status");
    if (label) label.textContent = savePresentation.state === "saving" ? "Saving…"
      : savePresentation.state === "pending" ? "Unsaved changes"
      : savePresentation.state === "error" ? "Not saved" : activeDraft.id ? "SAVED" : "";
    const retry = shell.querySelector(".report-autosave-retry");
    if (retry) retry.hidden = savePresentation.state !== "error";
    const copy = shell.querySelector(".report-autosave-copy");
    if (copy) copy.hidden = savePresentation.error?.payload?.code !== "REPORT_DRAFT_VERSION_CONFLICT";
  };
  autosave = createReportAutosave({
    read: () => activeDraft,
    isCurrent: () => !disposed && !deletingReport && isCurrentAccountRequest(requestIdentity) && requestWorkspaceID === activeWorkspaceID,
    retain: draft => saveReportDraftRecovery({ accountUserID, projectID, editorID: recoveryEditorID, draft }),
    acknowledge: async recovery => {
      await deleteReportDraftRecovery(accountUserID, recovery.key, recovery.draft);
      if (restoredRecovery) {
        const restored = restoredRecovery;
        await deleteReportDraftRecovery(accountUserID, restored.key, restored.draft);
        recoveredDrafts = recoveredDrafts.filter(item => item.key !== restored.key);
        if (restoredRecovery === restored) restoredRecovery = null;
      }
    },
    write: async snapshot => {
      const payload = await reportRequest("/reports/drafts/save", {
        projectID, draftID: snapshot.id, clientDraftID: snapshot.clientDraftID, expectedVersion: snapshot.version || 0,
        title: snapshot.title, reportDate: snapshot.reportDate,
        introduction: snapshot.introduction, blocks: snapshot.blocks
      });
      return payload.draft;
    },
    onSaved: saved => {
      const index = drafts.findIndex(draft => draft.id === saved.id);
      if (index < 0) drafts.unshift(structuredClone(saved)); else drafts[index] = structuredClone(saved);
      // Retain the block objects referenced by text-field event handlers.
      for (const key of ["id", "version", "createdAt", "updatedAt"]) if (saved[key] !== undefined) activeDraft[key] = saved[key];
      const remove = shell.querySelector(".report-title-delete");
      if (remove) { remove.disabled = false; remove.title = "Delete Report"; }
      const createNew = shell.querySelector(".report-draft-version-option.is-create");
      if (createNew) { createNew.hidden = false; createNew.closest("details").hidden = false; }
      void notebookMounts.get(projectID)?.refreshReportStatus?.().catch(() => false);
      void refreshProjectReportMembership(projectID, true);
    },
    onState: next => {
      savePresentation = next;
      dirty = autosave.isDirty();
      if (next.state === "error") showStatusError(`${next.error?.message || "Report could not be saved."} ${next.recoverable ? "A recovery copy is saved on this device." : "Keep this tab open to retain your edits."} Use Retry to save.`);
      else clearStatus();
      paintReportSaveState();
    }
  });
  const setDirty = () => {
    dirty = true;
    activeDraft.clientDraftID ||= crypto.randomUUID();
    autosave.change();
    void refreshProjectReportMembership(projectID);
  };
  const saveDraft = () => { activeDraft.clientDraftID ||= crypto.randomUUID(); return autosave.flush({ force: !activeDraft.id }); };

  const ensureComparison = () => comparisonController ||= createReportComparison({
    panel, columns: () => shell.querySelector(".report-document-columns"),
    availableWidth: () => shell.querySelector(".report-workspace-columns")?.clientWidth || 0,
    isCurrent: () => !disposed && panel.isConnected && isCurrentAccountRequest(requestIdentity) && requestWorkspaceID === activeWorkspaceID,
    onResize: () => { panel._updateReportColumns?.(); if (panel.isConnected) syncReferenceReaderLayout(); }
  });
  const reviewReport = (manifest, file) => ensureComparison().select(manifest,
    async () => ({ manifest, ...(await readProjectReportFile(projectID, file, manifest.title)) }));

  const openHistoricalReport = async (manifestID) => {
    clearStatus();
    const report = history.find(report => report.id === manifestID);
    if (!report) return;
    ensureComparison().select(report, async () => {
      const payload = await reportRequest("/reports/manifests/get", { manifestID });
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) throw accountContextChangedError();
      const file = report.files?.find(file => file.format === "web-pdf");
      if (!file) throw new Error("The stored Report PDF is unavailable. Its saved version remains in history.");
      return {manifest: payload.manifest, ...(await readProjectReportFile(projectID, file, report.title))};
    }, {toggle: true});
  };

  let generatingReport = false;
  let deletingReport = false;
  let deletingVersionID = null;
  let historyMutationGeneration = 0;
  const paintExportState = () => {
    panel.querySelectorAll(".report-history-delete").forEach((button) => { button.disabled = generatingReport; });
    const button = panel.querySelector('[data-report-export]');
    if (!button) return;
    button.disabled = generatingReport;
    button.textContent = generatingReport ? "Exporting PDF…" : "Export PDF version";
  };
  const generateReport = async () => {
    if (generatingReport || deletingReport) return;
    generatingReport = true;
    paintExportState();
    try {
      if ((dirty || !activeDraft.id) && !(await saveDraft())) return;
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
      if (dirty) {
        showStatusError("Your latest changes are still saving. Wait for Saved before exporting.");
        return;
      }
      if (!activeDraft.blocks.length && !activeDraft.introduction) {
        showStatusError("Add at least one Report item before generating a PDF.");
        return;
      }
      clearStatus();
      try {
        const payload = await reportRequest("/reports/generate", {
          projectID,
          draftID: activeDraft.id,
          expectedVersion: activeDraft.version,
          reportTemplateID: selectedReportTemplateID
        });
        if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
        const historyPayload = await reportRequest("/reports/history/list", { projectID });
        if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
        history = historyPayload.reports || [];
        clearStatus();
        renderWorkspaceContent();
        reviewReport(payload.manifest, payload.generatedReport.file);
        await transitionWorkspace("utility", {
          refreshPaneIDs: [paneIDForProjectDetail(identity)]
        });
      } catch (error) {
        if (disposed || !isCurrentAccountRequest(requestIdentity)) return;
        if (error.payload?.code === "REPORT_DRAFT_VERSION_CONFLICT" && !dirty) {
          await refreshReportArtifacts();
          if (disposed || !isCurrentAccountRequest(requestIdentity)) return;
        }
        showStatusError(error.message === "Report text is too long."
          ? "A Report item exceeds the supported text length. Shorten that item and try again."
          : error.message || "The Report could not be generated.");
      }
    } finally { generatingReport = false; paintExportState(); }
  };

  const deleteReport = async (trigger) => {
    if (deletingReport || !activeDraft.id || disposed ||
        !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return false;
    if (autosave?.isSaving() || generatingReport) {
      showStatusError("Wait for the Report to finish saving or exporting before deleting it.");
      return false;
    }
    autosave.suspend();
    const deletingDraft = activeDraft;
    const draftID = deletingDraft.id;
    const expectedVersion = deletingDraft.version;
    deletingReport = true;
    trigger.disabled = true;
    shell.inert = true;
    try {
      const confirmed = await confirmWebWarning(
        "Delete Report?",
        `“${deletingDraft.title || "Untitled Report"}” will be deleted.${dirty ? " Unsaved edits will also be discarded." : ""} Exported versions stay available.`,
        { confirmLabel: "Delete Report", container: panel, scope: trigger.closest(".report-document") }
      );
      if (!confirmed || disposed || !isCurrentAccountRequest(requestIdentity) ||
          requestWorkspaceID !== activeWorkspaceID || activeDraft !== deletingDraft) return false;
      clearStatus();
      await reportRequest("/reports/drafts/delete", { projectID, draftID, expectedVersion });
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return false;
      await autosave.settleRecovery();
      const copies = await reportDraftRecoveries(accountUserID, projectID).catch(() => []);
      const ownCopy = copies.find(copy => copy.editorID === recoveryEditorID);
      if (ownCopy) await deleteReportDraftRecovery(accountUserID, ownCopy.key, ownCopy.draft).catch(() => {});
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return false;
      drafts = drafts.filter((draft) => draft.id !== draftID);
      void refreshProjectReportMembership(projectID, true);
      activeDraft = drafts[0] ? structuredClone(drafts[0]) : emptyProjectReportDraft(identity);
      dirty = false;
      recoveryEditorID = crypto.randomUUID();
      deletingReport = false;
      autosave.reset();
      clearStatus();
      renderWorkspaceContent();
      await notebookMounts.get(projectID)?.refreshReportStatus?.().catch(() => false);
      return true;
    } catch (error) {
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return false;
      if (error.payload?.code === "REPORT_DRAFT_VERSION_CONFLICT" && !dirty) {
        deletingReport = false;
        await refreshReportArtifacts().catch(() => false);
        if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return false;
      }
      showStatusError(error.message || "The Report could not be deleted. Try again.");
      return false;
    } finally {
      deletingReport = false;
      autosave.resume();
      shell.inert = false;
      trigger.disabled = false;
    }
  };

  function renderIncludedReportComments(container) {
    const comments = reportCommentPresentation(activeDraft.blocks, sources);
    container.querySelectorAll("[data-report-comments-for]").forEach(host => {
      host.replaceChildren();
      const included = comments.get(host.dataset.reportCommentsFor) || [];
      host.hidden = included.length === 0;
      for (const item of included) {
        const comment = document.createElement("p");
        const scope = document.createElement("span");
        scope.className = "report-comment-scope";
        scope.textContent = item.reportCommentKey === "section" ? "Section comment" : "Passage comment";
        comment.append(scope, document.createTextNode(item.text || ""));
        host.append(comment);
      }
    });
  }

  function renderReportCommentOptions(row, block, source) {
    const previous = row.querySelector(".report-comment-options");
    const wasOpen = previous?.open || false;
    previous?.remove();
    if (block.kind === "evidence" && source?.notes?.length) {
      const comments = document.createElement("details");
      comments.className = "report-comment-options";
      const summary = document.createElement("summary");
      const updateLabel = () => {
        const excluded = new Set(block.excludedCommentKeys || []);
        const count = source.notes.filter(note => !excluded.has(reportCommentKey(note))).length;
        summary.textContent = `Comments in this Report · ${count} of ${source.notes.length}`;
      };
      updateLabel(); comments.append(summary);
      source.notes.forEach(note => {
        const label = document.createElement("label");
        const checkbox = document.createElement("input"); checkbox.type = "checkbox";
        const key = reportCommentKey(note);
        checkbox.checked = !(block.excludedCommentKeys || []).includes(key);
        const text = document.createElement("span");
        text.textContent = `${note.blockID ? "Passage comment" : "Section comment"}: ${note.body}`;
        checkbox.addEventListener("change", () => {
          const excluded = new Set(block.excludedCommentKeys || []);
          if (checkbox.checked) excluded.delete(key); else excluded.add(key);
          block.excludedCommentKeys = [...excluded]; updateLabel(); setDirty(); renderIncludedReportComments(panel);
        });
        label.append(checkbox,text); comments.append(label);
      });
      comments.open = wasOpen;
      row.append(comments);
    }
  }

  function refreshIncludedReportComments() {
    for (const block of activeDraft.blocks) {
      const row = [...panel.querySelectorAll(".report-draft-block")].find(row => row.dataset.blockId === block.id);
      if (row) {
        renderReportCommentOptions(row, block,
          sources.find(source => source.kind === block.kind && source.id === block.sourceID));
        row.refreshLinkedNoteState?.();
      }
    }
    renderIncludedReportComments(panel);
  }

  function renderBlockEditor(container) {
    if (!activeDraft.blocks.length) {
      return;
    }
    activeDraft.blocks.forEach((block, index) => {
      const row = document.createElement("article");
      row.className = `report-draft-block report-draft-block-${block.kind}`;
      row._reportBlock = block;
      row.dataset.blockId = block.id || `${block.kind}-${index}`;
      const top = document.createElement("div");
      top.className = "report-draft-block-top";
      const label = document.createElement("span");
      label.className = "report-draft-classification";
      label.textContent = reportSourceClassificationLabel(
        block.sourceClassification ||
        (["heading", "paragraph", "list"].includes(block.kind) ? "user-authored" : sources.find((source) =>
          source.id === block.sourceID && source.kind === block.kind
        )?.sourceClassification)
      );
      const kindLabel = ({ heading: "Heading", paragraph: block.derivedFrom?.kind === "notebookCard" ? "Notebook note" : "Paragraph", list: "List", evidence: "Code excerpt", notebookCard: "Notebook note", researchAnswer: "Research answer", projectFacts: "Project facts" })[block.kind] || "Source";
      label.textContent = `${kindLabel} · ${label.textContent}`;
      const actions = document.createElement("div");
      actions.className = "report-draft-block-actions";
      const reorderBlock = (targetIndex, focusHandle = false) =>
        reorderDraftBlock(block, targetIndex, focusHandle ? "document" : null);
      const dragHandle = document.createElement("button");
      dragHandle.type = "button";
      dragHandle.className = "report-draft-block-drag-handle";
      dragHandle.draggable = true;
      dragHandle.title = "Drag to reorder Report item";
      dragHandle.setAttribute("aria-label", "Drag to reorder Report item");
      dragHandle.setAttribute("aria-keyshortcuts", "ArrowUp ArrowDown");
      dragHandle.innerHTML = paneDragHandleSVG();
      dragHandle.addEventListener("keydown", (event) => {
        if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
        event.preventDefault();
        reorderBlock(activeDraft.blocks.indexOf(block) + (event.key === "ArrowUp" ? -1 : 1), true);
      });
      dragHandle.addEventListener("dragstart", (event) => {
        draggedReportBlock = block;
        row.classList.add("is-dragging");
        event.dataTransfer?.setData("text/plain", block.id || `${block.kind}-${index}`);
        if (event.dataTransfer) event.dataTransfer.effectAllowed = "move";
      });
      dragHandle.addEventListener("dragend", () => {
        draggedReportBlock = null;
        container.querySelectorAll(".report-draft-block").forEach((item) => {
          item.classList.remove("is-dragging", "is-drop-before", "is-drop-after");
        });
      });
      row.addEventListener("dragover", (event) => {
        if (!draggedReportBlock || draggedReportBlock === block) return;
        event.preventDefault();
        if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
        const after = event.clientY > row.getBoundingClientRect().top + row.offsetHeight / 2;
        container.querySelectorAll(".report-draft-block").forEach((item) => {
          item.classList.remove("is-drop-before", "is-drop-after");
        });
        row.classList.add(after ? "is-drop-after" : "is-drop-before");
      });
      row.addEventListener("dragleave", (event) => {
        if (!row.contains(event.relatedTarget)) {
          row.classList.remove("is-drop-before", "is-drop-after");
        }
      });
      row.addEventListener("drop", (event) => {
        const sourceIndex = activeDraft.blocks.indexOf(draggedReportBlock);
        const targetIndex = activeDraft.blocks.indexOf(block);
        if (sourceIndex < 0 || sourceIndex === targetIndex) return;
        event.preventDefault();
        const after = event.clientY > row.getBoundingClientRect().top + row.offsetHeight / 2;
        const moved = draggedReportBlock;
        draggedReportBlock = null;
        reorderDraftBlock(moved, reportDropIndex(sourceIndex, targetIndex, after));
      });
      actions.append(dragHandle);
      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "report-draft-block-remove";
      remove.title = "Remove Report item";
      remove.setAttribute("aria-label", "Remove Report item");
      remove.innerHTML = trashIconSVG();
      remove.addEventListener("click", () => {
        activeDraft.blocks.splice(activeDraft.blocks.indexOf(block), 1);
        setDirty();
        renderWorkspaceContent();
      });
      actions.append(remove);
      top.append(label, actions);
      row.append(top);

      if (block.kind === "heading") {
        const input = document.createElement("input");
        input.type = "text";
        input.value = block.text || "";
        input.placeholder = "Report heading";
        input.setAttribute("aria-label", "Report heading");
        input.addEventListener("input", () => {
          block.text = input.value;
          setDirty();
        });
        row.append(input);
      } else if (block.kind === "paragraph") {
        const textarea = document.createElement("textarea");
        textarea.value = block.text || "";
        textarea.placeholder = "Professional narrative paragraph";
        textarea.setAttribute("aria-label", "Report paragraph");
        textarea.addEventListener("input", () => {
          block.text = textarea.value;
          setDirty();
        });
        row.append(textarea);
        if (block.derivedFrom?.kind === "notebookCard") {
          const provenance = document.createElement("section");
          provenance.className = "report-note-provenance";
          const provenanceLabel = document.createElement("p");
          provenanceLabel.textContent = `Snapshot of Note: ${block.derivedFrom.title}`;
          provenance.append(provenanceLabel);
          let latestSource;
          const updateNote = document.createElement("button");
          updateNote.type = "button";
          row.refreshLinkedNoteState = () => {
            latestSource = sources.find(source => source.kind === "notebookCard" && source.id === block.derivedFrom.id);
            updateNote.textContent = latestSource?.version > block.derivedFrom.version ? "Review updated Note" : "Review linked Note";
            updateNote.disabled = !latestSource;
          };
          row.refreshLinkedNoteState();
          updateNote.addEventListener("click", async () => {
            updateNote.disabled = true;
            const draftID = activeDraft.id;
            try {
              const { card } = await postResearch("/notebook/cards/get", { projectID, cardID: block.derivedFrom.id });
              requireCurrentAccountRequest(requestIdentity);
              if (disposed || activeWorkspaceID !== requestWorkspaceID || activeDraft.id !== draftID || !activeDraft.blocks.includes(block)) return;
              const text = card.plainText || "";
              if (text.length > 20000) throw new Error("This Note is too long for one Report paragraph. Keep the linked source or split the Note before updating this paragraph.");
              const accepted = await confirmWebWarning("Update this Report paragraph?",
                `Latest Note: ${card.title} · version ${card.version}\n\n${text}\n\nThis replaces this paragraph’s report-specific text. Saved PDF versions stay unchanged.`,
                { confirmLabel: "Replace with reviewed Note" });
              if (!accepted || disposed || !isCurrentAccountRequest(requestIdentity) || activeWorkspaceID !== requestWorkspaceID || activeDraft.id !== draftID || !activeDraft.blocks.includes(block)) return;
              block.text = text;
              block.derivedFrom = {kind: "notebookCard", id: card.id, title: card.title, version: card.version};
              block.sourceSnapshotAt = new Date().toISOString();
              block.evidenceLinks = structuredClone(card.evidenceLinks || []);
              setDirty(); renderWorkspaceContent();
            } catch (error) { if (isCurrentAccountRequest(requestIdentity)) showStatusError(error.message); }
            finally { updateNote.disabled = !latestSource; }
          });
          provenance.append(updateNote);
          (block.evidenceLinks || []).forEach((evidenceLink) => {
            const sourceButton = document.createElement("button");
            sourceButton.type = "button";
            sourceButton.className = `report-note-evidence code-theme-${codeTheme(evidenceLink.source?.codePrefix)}`;
            sourceButton.textContent = evidenceLink.label || [
              evidenceLink.source?.codePrefix,
              evidenceLink.source?.sectionNumber
            ].filter(Boolean).join(" § ");
            sourceButton.addEventListener("click", () => {
              void openSourceInReader({
                ...evidenceLink.source,
                title: evidenceLink.source?.sectionTitle
              }, paneID, { projectID, evidenceAnchor: evidenceLink });
            });
            provenance.append(sourceButton);
          });
          row.append(provenance);
        }
      } else if (block.kind === "list") {
        const textarea = document.createElement("textarea");
        textarea.value = (block.items || []).join("\n");
        textarea.placeholder = "One list item per line";
        textarea.setAttribute("aria-label", "Report list items");
        textarea.addEventListener("input", () => {
          block.items = textarea.value.split("\n").map((value) => value.trim()).filter(Boolean);
          setDirty();
        });
        row.append(textarea);
      } else {
        let source = sources.find((item) => item.kind === block.kind && item.id === block.sourceID);
        if (block.kind === "evidence" && source) {
          row.classList.add(`code-theme-${codeTheme(source.codePrefix)}`);
        }
        const sourceTitle = document.createElement("strong");
        sourceTitle.textContent = block.kind === "projectFacts"
          ? "PROJECT FACTS"
          : block.kind === "evidence" && source
            ? [source.sectionNumber, stripLeadingSectionNumber(source.title || "", source.sectionNumber)].filter(Boolean).join(" ")
            : reportBlockTitle(block);
        if (block.kind === "evidence" && source) {
          const citation = document.createElement("p");
          citation.className = "report-block-citation";
          citation.textContent = [source.codePrefix || "Code", savedEvidenceEdition(source)].filter(Boolean).join(" · ");
          row.append(sourceTitle, citation);
        }
        renderReportCommentOptions(row, block, source);
        if (!sourceTitle.parentElement) row.append(sourceTitle);
        if (source) {
          if (block.kind === "notebookCard") {
            const explanation = document.createElement("p");
            explanation.className = "report-workflow-help";
            explanation.textContent = "Linked Note uses its latest saved content. Create an editable snapshot to keep report-specific wording.";
            const snapshot = document.createElement("button"); snapshot.type = "button";
            snapshot.textContent = "Create editable snapshot";
            snapshot.addEventListener("click", async () => {
              const draftID = activeDraft.id;
              snapshot.disabled = true;
              try {
                const { card } = await postResearch("/notebook/cards/get", {projectID, cardID: block.sourceID});
                requireCurrentAccountRequest(requestIdentity);
                if (disposed || activeWorkspaceID !== requestWorkspaceID || activeDraft.id !== draftID || !activeDraft.blocks.includes(block)) return;
                const text = card.plainText || "";
                if (text.length > 20000) throw new Error("This Note is too long for one Report paragraph. Keep the linked source or split the Note first.");
                Object.assign(block, {kind: "paragraph", text, derivedFrom: {kind: "notebookCard", id: card.id, title: card.title, version: card.version},
                  sourceSnapshotAt: new Date().toISOString(), evidenceLinks: structuredClone(card.evidenceLinks || [])});
                delete block.sourceID;
                setDirty(); renderWorkspaceContent();
              } catch (error) { if (isCurrentAccountRequest(requestIdentity)) showStatusError(error.message); }
              finally { snapshot.disabled = false; }
            });
            row.append(explanation, snapshot);
          }
          if (reportEvidenceCoverage(activeDraft.blocks, sources).has(block.id)) {
            const notice = document.createElement("p");
            notice.textContent = "Passage text is included in the whole section. Selected comments appear once in the export.";
            row.append(notice);
          }
          const preview = document.createElement("details");
          preview.className = "report-full-preview";
          const toggle = document.createElement("summary"); toggle.textContent = "Source text";
          const body = document.createElement("div"); body.className = "report-full-preview-body"; preview.append(toggle, body);
          preview.open = !reportEvidenceCoverage(activeDraft.blocks, sources).has(block.id);
          let loaded = false, loading = false;
          let previewRevision = 0;
          const loadPreview = async () => {
            if (!preview.open || loaded || loading) return;
            const revision = previewRevision;
            loading = true; body.textContent = "Loading complete source…";
            const identity = captureAccountRequest();
            try {
              const key = JSON.stringify([block.kind, block.sourceID, source]);
              let request = sourcePreviewRequests.get(key);
              if (!request) {
                request = postResearch("/reports/sources/preview", {projectID, kind:block.kind, sourceID:block.sourceID});
                sourcePreviewRequests.set(key, request);
                request.catch(() => { if (sourcePreviewRequests.get(key) === request) sourcePreviewRequests.delete(key); });
              }
              const result = await request;
              requireCurrentAccountRequest(identity);
              if (disposed || requestWorkspaceID !== activeWorkspaceID || revision !== previewRevision) return;
              body.replaceChildren();
              for (const part of result.preview || []) {
                if (part.kind === "table") {
                  const scroll = document.createElement("div"); scroll.className = "report-preview-table";
                  const table = document.createElement("table");
                  for (const cells of part.rows || []) {
                    const row = document.createElement("tr");
                    for (const value of cells) {
                      const cell = document.createElement("td"); cell.textContent = value; row.append(cell);
                    }
                    table.append(row);
                  }
                  scroll.append(table); body.append(scroll);
                } else {
                  if (part.label) {
                    const heading = document.createElement("strong"); heading.textContent = part.label; body.append(heading);
                  }
                  const text = document.createElement("p"); text.textContent = part.text; body.append(text);
                }
              }
              loaded = true;
            } catch (error) {
              if (isCurrentAccountRequest(identity) && revision === previewRevision) body.textContent = `${error.message} Close and reopen to retry.`;
            } finally {
              loading = false;
              if (revision !== previewRevision && !disposed) void loadPreview();
            }
          };
          if (block.kind === "notebookCard") {
            const refreshNoteState = row.refreshLinkedNoteState;
            row.refreshLinkedNoteState = () => {
              refreshNoteState?.();
              const latest = sources.find(item => item.kind === block.kind && item.id === block.sourceID);
              if (!latest || JSON.stringify(latest) === JSON.stringify(source)) return;
              source = latest;
              sourceTitle.textContent = latest.title || latest.label || reportBlockTitle(block);
              previewRevision += 1;
              loaded = false;
              void loadPreview();
            };
          }
          preview.addEventListener("toggle", loadPreview);
          row.append(preview);
          void loadPreview();
        }
        if (block.kind === "evidence") {
          const includedComments = document.createElement("div");
          includedComments.className = "report-included-comments";
          includedComments.dataset.reportCommentsFor = block.id;
          row.append(includedComments);
        }
        const commentOptions = row.querySelector(".report-comment-options");
        if (commentOptions) row.append(commentOptions);
      }
      container.append(row);
    });
    renderIncludedReportComments(container);
  }

  function reportSourcePickerLabel() {
    return sourceWarnings.length
      ? `Add sources — ${sourceWarnings.length} unavailable`
      : "Add sources";
  }

  function renderSourcePalette(container) {
    const pickerSummary = panel.querySelector(".report-source-picker > .section-label");
    if (pickerSummary) { pickerSummary.textContent = reportSourcePickerLabel(); pickerSummary.hidden = !sourceWarnings.length; }
    const appendSourceGroup = (label, description, renderBody) => {
      const section = document.createElement("section");
      section.className = "report-source-group";
      const heading = document.createElement("div");
      heading.className = "report-source-group-heading project-collapsible-heading";
      const title = document.createElement("button");
      title.type = "button";
      title.className = "project-section-toggle-label section-label report-source-group-toggle";
      title.textContent = label;
      heading.append(title);
      const body = document.createElement("div");
      body.className = "report-source-group-body";
      if (description) {
        const copy = document.createElement("p");
        copy.className = "report-source-group-description";
        copy.textContent = description;
        body.append(copy);
      }
      renderBody(body);
      section.append(heading, body);
      container.append(section);
      const initiallyExpanded = reportSectionExpanded(label);
      wireProjectSectionMotion(section, body, [title], label, initiallyExpanded, {
        onChange(expanded) {
          persistReportSectionExpanded(label, expanded);
        }
      });
    };
    const appendSourceCard = (container, source) => {
      const row = document.createElement("article");
      row.className = "report-source-card";
      const copy = document.createElement("div");
      const heading = document.createElement("strong");
      heading.textContent = source.label;
      const summary = document.createElement("p");
      summary.textContent = source.summary || "Project source";
      copy.append(heading, summary);
      const add = document.createElement("button");
      add.type = "button";
      add.textContent = "Add";
      add.disabled = reportsContainingSource([activeDraft], source.kind, source.id).length > 0;
      add.textContent = add.disabled ? "Added" : "Add";
      add.setAttribute("aria-label", `${add.disabled ? "Already included" : "Add to Report"}: ${source.label || heading.textContent}`);
      add.addEventListener("click", () => {
        activeDraft.blocks.push({
          id: crypto.randomUUID(),
          kind: source.kind,
          sourceID: source.id,
          label: source.label,
          sourceClassification: source.sourceClassification
        });
        setDirty();
        renderWorkspaceContent();
      });
      row.append(copy, add);
      container.append(row);
    };

    const projectFactsSources = sources.filter((source) => source.kind === "projectFacts");
    appendSourceGroup("Project facts", "", (groupBody) => {
      projectFactsSources.forEach((source) => appendSourceCard(groupBody, source));
    });

    for (const [kind, label] of [["evidence", "Evidence"], ["notebookCard", "Notes"]]) {
      appendSourceGroup(label, "", body => {
        const items = sources.filter(source => source.kind === kind);
        items.forEach(source => appendSourceCard(body, source));
        if (!items.length && kind === "evidence") {
          const empty = document.createElement("p");
          empty.className = "report-workflow-help";
          empty.textContent = "Save passages in your workspace to use them here.";
          body.append(empty);
        }
      });
    }
    const researchSources = sources.filter((source) => source.kind === "researchAnswer");
    appendSourceGroup("Research", "", (groupBody) => {

      researchSources.forEach((source) => appendSourceCard(groupBody, source));
    });

  }

  async function deleteVersion(report, trigger) {
    if (disposed || generatingReport || deletingReport || deletingVersionID || !isCurrentAccountRequest(requestIdentity) ||
        requestWorkspaceID !== activeWorkspaceID) return false;
    deletingVersionID = report.id;
    historyMutationGeneration += 1;
    const wasInert = shell.inert;
    shell.inert = true;
    trigger.disabled = true;
    try {
      const confirmed = await confirmWebWarning("Delete version?",
        `“${report.title} · Version ${report.reportVersion}” will be removed from Versions. The editable Report stays available.`,
        { confirmLabel: "Delete", container: panel, scope: trigger.closest(".report-versions-panel") });
      if (!confirmed || disposed || !isCurrentAccountRequest(requestIdentity) ||
          requestWorkspaceID !== activeWorkspaceID) return false;
      clearStatus();
      await reportRequest("/reports/history/delete", { projectID, manifestID: report.id });
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return false;
      history = history.filter((version) => version.id !== report.id);
      comparisonController?.removeVersion(report.id);
      panel._updateReportColumns?.();
      const historyBody = panel.querySelector(".report-history");
      if (historyBody) {
        const scroll = historyBody.scrollTop;
        historyBody.replaceChildren();
        renderHistory(historyBody);
        historyBody.scrollTop = scroll;
      }
      clearStatus();
      return true;
    } catch (error) {
      if (!disposed && isCurrentAccountRequest(requestIdentity) && requestWorkspaceID === activeWorkspaceID) {
        showStatusError(error.message || "The Report version could not be deleted. Try again.");
      }
      return false;
    } finally {
      deletingVersionID = null;
      shell.inert = wasInert;
      trigger.disabled = false;
      if (!disposed && isCurrentAccountRequest(requestIdentity) && requestWorkspaceID === activeWorkspaceID) {
        if (trigger.isConnected) trigger.focus({ preventScroll: true });
        else panel.querySelector(".report-history-card, .report-versions-collapse")?.focus({ preventScroll: true });
      }
    }
  }

  function renderHistory(container) {
    const selectedID = comparisonController?.selectedID;
    if (selectedID && !history.some((version) => version.id === selectedID)) comparisonController.removeVersion(selectedID);
    if (!history.length) {
      const empty = document.createElement("p");
      empty.className = "report-workflow-help";
      empty.textContent = "Export a PDF version when your draft is ready. Saved versions will appear here.";
      container.append(empty);
      return;
    }
    history.forEach((report) => {
      const entry = document.createElement("article");
      entry.className = "report-history-entry";
      const button = document.createElement("button");
      button.type = "button";
      button.className = "report-history-card";
      button.dataset.reportPreview = report.id;
      button.setAttribute("aria-label", `Preview ${report.title}, version ${report.reportVersion}`);
      button.setAttribute("aria-pressed", String(comparisonController?.selectedID === report.id));
      button.addEventListener("click", () => void openHistoricalReport(report.id));
      const heading = document.createElement("strong");
      heading.textContent = `${report.title} · Version ${report.reportVersion}`;
      const meta = document.createElement("span");
      const generatedAt = new Date(report.createdAt);
      const generatedDate = generatedAt.toLocaleDateString(undefined, {
        month: "short",
        day: "numeric",
        year: "numeric"
      });
      const generatedTime = generatedAt.toLocaleTimeString(undefined, {
        hour: "numeric",
        minute: "2-digit"
      });
      meta.textContent = [
        `${generatedDate} at ${generatedTime}`,
        `${report.itemCount} included ${report.itemCount === 1 ? "item" : "items"}`
      ].filter(Boolean).join(" · ");
      button.append(heading, meta);
      entry.append(button);
      const fileActions = document.createElement("div");
      fileActions.className = "report-history-files";
      entry.append(fileActions);
      const files = Array.isArray(report.files) ? report.files : [];
      if (files.length) {
        files.forEach((file) => {
          const download = document.createElement("button");
          download.type = "button";
          download.textContent = file.format === "ios-pdf"
            ? "Download iOS PDF"
            : "Download PDF";
          download.addEventListener("click", async () => {
            download.disabled = true;
            clearStatus();
            try {
              await downloadProjectReportFile(projectID, file, report.title);
              clearStatus();
            } catch (error) {
              showStatusError(error.message || "The Report PDF could not be downloaded.");
            } finally {
              download.disabled = false;
            }
          });
          fileActions.append(download);
        });
      }
      if (report.deletable !== false && (!identity.sharedOrganizationID || identity.sharedPermissions?.includes("project.edit"))) {
        const remove = document.createElement("button");
        remove.type = "button";
        remove.className = "report-history-delete workflow-action-icon";
        remove.title = `Delete version ${report.reportVersion}`;
        remove.setAttribute("aria-label", `Delete ${report.title}, version ${report.reportVersion}`);
        remove.innerHTML = trashIconSVG();
        remove.disabled = generatingReport;
        remove.addEventListener("click", () => void deleteVersion(report, remove));
        fileActions.append(remove);
      }
      container.append(entry);
    });
  }

  function reorderDraftBlock(block, targetIndex, focusArea = null) {
    if (!moveReportBlock(activeDraft.blocks, activeDraft.blocks.indexOf(block), targetIndex)) return;
    outlineNavigationGeneration += 1;
    const documentBody = shell.querySelector(".report-document");
    const scroll = documentBody.scrollTop;
    const rows = [...documentBody.querySelectorAll(".report-draft-block")];
    const rowByBlock = new Map(rows.map(row => [row._reportBlock, row]));
    rows[0].parentElement.append(...activeDraft.blocks.map(item => rowByBlock.get(item)));
    outlineController.reorder();
    renderIncludedReportComments(panel);
    documentBody.scrollTop = scroll;
    setDirty();
    outlineController.announce(`${reportBlockTitle(block)} moved to position ${targetIndex + 1}.`);
    if (focusArea) requestAnimationFrame(() => {
      if (focusArea === "outline") outlineController.reveal(block);
      const blockID = block.id || `${block.kind}-${targetIndex}`;
      const escapedID = CSS.escape(blockID);
      const handle = shell.querySelector(focusArea === "outline"
        ? `.report-outline-item[data-block-id="${escapedID}"] .report-outline-drag`
        : `.report-draft-block[data-block-id="${escapedID}"] .report-draft-block-drag-handle`);
      handle?.focus({ preventScroll: true });
      if (focusArea === "outline" && handle) revealOutlineHandle(outlineController.element, handle);
    });
  }

  function renderWorkspaceContent() {
    if (disposed || !isCurrentAccountRequest(requestIdentity)) return;
    outlineNavigationGeneration += 1;
    const draftKey = activeDraft.id || activeDraft.clientDraftID;
    const keepPosition = renderedDraftKey === draftKey;
    const oldDocument = shell.querySelector(".report-document");
    const oldOutline = shell.querySelector(".report-outline");
    const columnsScroll = shell.querySelector(".report-document-columns")?.scrollLeft || 0;
    const comparisonScroll = comparisonController?.capturePosition();
    const documentScroll = keepPosition ? oldDocument?.scrollTop || 0 : 0;
    const outlineScroll = keepPosition ? oldOutline?.scrollTop || 0 : 0;
    const disclosures = new Map(keepPosition ? [...shell.querySelectorAll(".report-draft-block")].map(row =>
      [row.dataset.blockId, [...row.querySelectorAll("details")].map(detail => detail.open)]) : []);
    for (const [key, selector] of [["sources", ".report-source-picker"]]) {
      const body = shell.querySelector(selector);
      if (keepPosition && body && !body.hidden) reportLibraryScroll[key] = body.scrollTop;
    }
    renderedDraftKey = draftKey;
    outlineController?.dispose();
    resetEnhancedSelects(shell);
    shell.querySelectorAll(":scope > :not(.report-draft-status)").forEach((element) => element.remove());

    const draftPicker = document.createElement("div");
    draftPicker.className = "report-draft-picker";
    const titleControl = document.createElement("div");
    titleControl.className = "report-title-control";
    const titleButton = document.createElement("button");
    titleButton.type = "button";
    titleButton.className = "report-title-text";
    titleButton.textContent = activeDraft.title || "Untitled Report";
    titleButton.setAttribute("aria-label", "Edit Report title");
    const titleEditor = document.createElement("input");
    titleEditor.type = "text";
    titleEditor.className = "report-title-editor";
    titleEditor.value = activeDraft.title || "";
    titleEditor.setAttribute("aria-label", "Edit Report title");
    titleEditor.hidden = true;
    const revisionLabel = document.createElement("span");
    revisionLabel.className = "report-title-revision";
    revisionLabel.textContent = `Draft revision ${activeDraft.version || 1}`;
    const deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "report-title-delete workflow-action-icon";
    deleteButton.title = activeDraft.id ? "Delete Report" : "Save this Report before deleting it";
    deleteButton.setAttribute("aria-label", "Delete Report");
    deleteButton.innerHTML = trashIconSVG();
    deleteButton.disabled = !activeDraft.id;
    deleteButton.addEventListener("click", () => void deleteReport(deleteButton));
    const beginTitleEditing = () => {
      titleEditor.value = activeDraft.title || "";
      titleButton.hidden = true;
      titleEditor.hidden = false;
      titleEditor.focus();
      titleEditor.select();
    };
    const finishTitleEditing = ({ cancel = false, restoreFocus = true } = {}) => {
      if (titleEditor.hidden) return;
      const previousTitle = activeDraft.title || "Untitled Report";
      const nextTitle = cancel ? previousTitle : titleEditor.value.trim() || previousTitle;
      if (!cancel && nextTitle !== activeDraft.title) {
        activeDraft.title = nextTitle;
        setDirty();
      }
      titleButton.textContent = activeDraft.title || "Untitled Report";
      titleEditor.hidden = true;
      titleButton.hidden = false;
      if (restoreFocus) titleButton.focus();
    };
    titleButton.addEventListener("click", beginTitleEditing);
    titleEditor.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        finishTitleEditing();
      } else if (event.key === "Escape") {
        event.preventDefault();
        finishTitleEditing({ cancel: true });
      }
    });
    titleEditor.addEventListener("blur", () => finishTitleEditing({ restoreFocus: false }));
    const versionList = document.createElement("details");
    versionList.className = "report-draft-version-list";
    const reportMenu = document.createElement("summary");
    reportMenu.textContent = "Reports";
    reportMenu.setAttribute("aria-label", "Choose report");
    const reportOptions = document.createElement("div");
    reportOptions.className = "workspace-menu report-draft-menu-items";
    reportOptions.setAttribute("role", "group");
    reportOptions.setAttribute("aria-label", "Available reports");
    versionList.append(reportMenu, reportOptions);
    versionList.addEventListener("keydown", event => {
      if (event.key === "Escape" && versionList.open) {
        event.preventDefault();
        event.stopPropagation();
        versionList.open = false;
        reportMenu.focus({ preventScroll: true });
        return;
      }
      if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
      if (event.target === reportMenu && !["ArrowDown", "ArrowUp"].includes(event.key)) return;
      event.preventDefault();
      versionList.open = true;
      const options = webFocusableElements(reportOptions);
      const current = options.indexOf(document.activeElement);
      const next = event.key === "Home" ? 0 : event.key === "End" ? options.length - 1 :
        current < 0 ? event.key === "ArrowUp" ? options.length - 1 : 0 :
        (current + (event.key === "ArrowUp" ? -1 : 1) + options.length) % options.length;
      options[next]?.focus({ preventScroll: true });
    });
    versionList.addEventListener("focusout", event => {
      if (event.relatedTarget && !versionList.contains(event.relatedTarget)) versionList.open = false;
    });
    const switchDraft = async (draftID) => {
      if (deletingReport) return;
      if (dirty && !(await mountState.confirmDiscardIfNeeded())) return;
      activeDraft = draftID === "__new__"
        ? emptyProjectReportDraft(identity)
        : structuredClone(
            drafts.find((draft) => draft.id === draftID) || emptyProjectReportDraft(identity)
          );
      dirty = false;
      recoveryEditorID = crypto.randomUUID();
      deletingReport = false;
      autosave.reset();
      clearStatus();
      renderWorkspaceContent();
      shell.querySelector(".report-draft-version-list > summary")?.focus({ preventScroll: true });
    };
    drafts.forEach((draft) => {
      const current = draft.id === activeDraft.id;
      const choice = document.createElement("button");
      choice.type = "button";
      choice.className = "report-draft-version-option";
      if (current) choice.setAttribute("aria-current", "true");
      const choiceTitle = document.createElement("span");
      choiceTitle.textContent = (current ? activeDraft.title : draft.title) || "Untitled Report";
      const choiceRevision = document.createElement("small");
      choiceRevision.textContent = current ? "Current" : `Revision ${draft.version || 1}`;
      choice.append(choiceTitle, choiceRevision);
      choice.addEventListener("click", () => {
        versionList.open = false;
        if (current) reportMenu.focus({ preventScroll: true });
        else void switchDraft(draft.id);
      });
      reportOptions.append(choice);
    });
    {
      const createNew = document.createElement("button");
      createNew.hidden = !activeDraft.id;
      createNew.type = "button";
      createNew.className = "report-draft-version-option is-create";
      createNew.textContent = "+ New report";
      createNew.setAttribute("aria-label", "New report");
      createNew.addEventListener("click", () => {
        versionList.open = false;
        void switchDraft("__new__");
      });
      reportOptions.append(createNew);
    }
    for (const recovery of recoveredDrafts) {
      const recover = document.createElement("button");
      recover.type = "button";
      recover.className = "report-draft-version-option is-recovery";
      recover.textContent = `Recover edits: ${recovery.draft.title || "Untitled Report"} · ${new Date(recovery.updatedAt).toLocaleString()}`;
      recover.addEventListener("click", async () => {
        if (dirty && !await mountState.confirmDiscardIfNeeded()) return;
        if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
        const remote = drafts.find(draft => draft.id === (recovery.draft.id || recovery.draft.clientDraftID));
        const changedElsewhere = !remote || remote.version !== recovery.draft.version;
        if (changedElsewhere && !await confirmWebWarning("Recover as a new Report?", "The server Report has changed or is no longer available. Recovering these edits creates a separate Report and keeps the server version intact.", {confirmLabel:"Recover as new Report"})) return;
        if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
        activeDraft = structuredClone(recovery.draft);
        if (changedElsewhere) {
          activeDraft.id = null; activeDraft.version = 0; activeDraft.clientDraftID = crypto.randomUUID();
          activeDraft.title = `${activeDraft.title || "Untitled Report"} (recovered)`;
        }
        restoredRecovery = recovery;
        recoveryEditorID = crypto.randomUUID();
        autosave.reset(); setDirty(); renderWorkspaceContent();
      });
      reportOptions.append(recover);
    }
    versionList.hidden = !activeDraft.id && !drafts.length && !recoveredDrafts.length;
    if (recoveredDrafts.length) { reportMenu.title = "Recovered edits are available"; versionList.open = true; }
    titleControl.append(titleButton, titleEditor, revisionLabel, versionList, deleteButton);
    draftPicker.append(titleControl);

    const metadata = document.createElement("div");
    metadata.className = "report-draft-metadata";
    const introductionSection = document.createElement("section");
    introductionSection.className = "report-introduction-section";
    const introductionHeading = document.createElement("div");
    introductionHeading.className = "report-introduction-heading project-collapsible-heading";
    const introductionLabel = document.createElement("button");
    introductionLabel.type = "button";
    introductionLabel.className = "project-section-toggle-label section-label report-introduction-label";
    introductionLabel.textContent = "Introduction";
    const introduction = document.createElement("textarea");
    introduction.id = `report-introduction-${activeDraft.id || projectID}`;
    introduction.value = activeDraft.introduction || "";
    introduction.placeholder = "Describe the purpose and scope of this report (optional).";
    introduction.setAttribute("aria-label", "Report introduction");
    introduction.addEventListener("input", () => {
      activeDraft.introduction = introduction.value;
      setDirty();
    });
    const introductionBody = document.createElement("div");
    introductionBody.append(introduction);
    introductionHeading.append(introductionLabel);
    introductionSection.append(introductionHeading, introductionBody);
    wireProjectSectionMotion(introductionSection, introductionBody,
      [introductionLabel], "Report introduction",
      reportSectionExpanded("Report introduction"),
      { onChange(expanded) { persistReportSectionExpanded("Report introduction", expanded); } });
    metadata.append(introductionSection);

    const addControls = document.createElement("div");
    addControls.className = "report-draft-add-controls";
    addControls.setAttribute("role", "group");
    addControls.setAttribute("aria-label", "Add report content");
    [
      { kind: "heading", label: "Add heading", value: { text: "Report section" } },
      { kind: "paragraph", label: "Add paragraph", value: { text: "" } },
      { kind: "list", label: "Add list", value: { items: [""] } }
    ].forEach((control) => {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = control.label;
      button.addEventListener("click", () => {
        activeDraft.blocks.push({
          id: crypto.randomUUID(),
          kind: control.kind,
          sourceClassification: "user-authored",
          ...structuredClone(control.value)
        });
        setDirty();
        renderWorkspaceContent();
      });
      addControls.append(button);
    });
    const addSource = document.createElement("button");
    addSource.type = "button";
    addSource.textContent = "Add source";
    addSource.addEventListener("click", () => {
      panel.dataset.libraryOpen = "true";
      renderWorkspaceContent();
      panel.querySelector('.report-source-group-toggle')?.focus({preventScroll: true});
    });
    addControls.append(addSource);

    const blocks = document.createElement("section");
    blocks.className = "report-draft-blocks";
    blocks.setAttribute("aria-label", "Report content");
    const blocksBody = document.createElement("div");
    blocksBody.className = "report-draft-blocks-body";
    blocksBody.append(addControls);
    if (!activeDraft.blocks.length) {
      const empty = document.createElement("p");
      empty.className = "report-workflow-help";
      empty.textContent = "Add a heading, paragraph, list, or saved source to start your report.";
      blocksBody.append(empty);
    }
    renderBlockEditor(blocksBody);
    blocks.append(blocksBody);
    const sourcePalette = document.createElement("section");
    sourcePalette.className = "report-source-palette";
    renderSourcePalette(sourcePalette);
    const sourcePicker = document.createElement("section");
    sourcePicker.className = "report-source-picker";
    const sourcePickerToggle = document.createElement("p");
    sourcePickerToggle.textContent = reportSourcePickerLabel();
    sourcePickerToggle.className = "section-label";
    sourcePickerToggle.hidden = !sourceWarnings.length;
    sourcePicker.append(sourcePickerToggle, sourcePalette);

    const primaryActions = document.createElement("div");
    primaryActions.className = "report-draft-primary-actions";
    const save = document.createElement("button");
    save.type = "button";
    save.className = "workflow-action workflow-action-secondary";
    save.classList.add("report-autosave-retry");
    save.textContent = "Retry";
    save.title = "Retry saving Report edits";
    save.hidden = savePresentation.state !== "error";
    const saveStatus = document.createElement("span");
    saveStatus.className = "report-autosave-status";
    saveStatus.setAttribute("role", "status");
    save.addEventListener("click", () => {
      void saveDraft();
    });
    const saveCopy = document.createElement("button");
    saveCopy.type = "button"; saveCopy.className = "report-autosave-copy";
    saveCopy.textContent = "Save as new Report";
    saveCopy.hidden = savePresentation.error?.payload?.code !== "REPORT_DRAFT_VERSION_CONFLICT";
    saveCopy.addEventListener("click", async () => {
      const records = await reportDraftRecoveries(accountUserID, projectID).catch(() => []);
      if (disposed || !isCurrentAccountRequest(requestIdentity) || requestWorkspaceID !== activeWorkspaceID) return;
      restoredRecovery = records.find(record => record.editorID === recoveryEditorID) || null;
      activeDraft = {...structuredClone(activeDraft), id:null, version:0, clientDraftID:crypto.randomUUID(), title:`${activeDraft.title || "Untitled Report"} (copy)`};
      recoveryEditorID = crypto.randomUUID(); autosave.reset(); setDirty(); renderWorkspaceContent();
    });
    const generate = document.createElement("button");
    generate.type = "button";
    generate.className = "workflow-action workflow-action-primary";
    generate.dataset.reportExport = "true";
    generate.disabled = generatingReport;
    generate.textContent = generatingReport ? "Exporting PDF…" : "Export PDF version";
    generate.title = "Save current edits and create a fixed Report version for export";
    generate.addEventListener("click", () => {
      void generateReport();
    });
    const coordinate = document.createElement("button");
    coordinate.type = "button";
    coordinate.textContent = "Coordinate";
    coordinate.disabled = !activeDraft.id;
    coordinate.title = activeDraft.id
      ? "Open a coordination item linked to this Report"
      : "Save this Report before opening a coordination item";
    coordinate.hidden = !releaseSurfaceVisibility.coordination || !projectCollaborationAccess(identity, "project.review.request");
    coordinate.addEventListener("click", () => {
      void openCoordinationComposer({
        projectID,
        type: "revision-request",
        targetKind: "reportDraft",
        targetID: activeDraft.id,
        snapshot: { label: `Report: ${activeDraft.title || "Untitled Report"}` }
      });
    });
    primaryActions.append(saveStatus, save, saveCopy, generate, coordinate);

    const comparison = ensureComparison();
    const historyBody = comparison.versionBody;
    historyBody.replaceChildren();
    renderHistory(historyBody);
    const documentBody = document.createElement("div");
    documentBody.className = "report-document";
    documentBody.append(draftPicker, metadata, blocks);
    outlineController = createReportOutline({
      blocks: activeDraft.blocks, introduction: metadata,
      targets: [...blocksBody.querySelectorAll(".report-draft-block")], documentBody,
      dragIcon: paneDragHandleSVG(), sectionExpansion: outlineSectionExpansion,
      describe: block => {
        const source = sources.find(item => item.kind === block.kind && item.id === block.sourceID);
        if (block.kind === "evidence" && source) return {
          title: [source.sectionNumber, stripLeadingSectionNumber(source.title || "", source.sectionNumber)].filter(Boolean).join(" "),
          detail: [source.codePrefix || "Code", savedEvidenceEdition(source), source.selectionBlockID ? "Passage" : "Section"].filter(Boolean).join(" · ")
        };
        return { title: reportBlockTitle(block), detail: ({ heading: "Heading", paragraph: block.derivedFrom?.kind === "notebookCard" ? "Notebook note" : "Paragraph", list: "List", notebookCard: "Notebook note", researchAnswer: "Research answer", projectFacts: "Project facts" })[block.kind] || "Source" };
      },
      onNavigate: target => {
        if (target === metadata && introductionLabel.getAttribute("aria-expanded") === "false") introductionLabel.click();
        const navigation = ++outlineNavigationGeneration;
        const isCurrent = () => !disposed && isCurrentAccountRequest(requestIdentity) &&
          navigation === outlineNavigationGeneration && target.isConnected && panel.closest(".report-screen")?.open;
        void navigateReportOutline({
          requests: sourcePreviewRequests.values(),
          isCurrent,
          navigate: () => requestAnimationFrame(() => {
            if (isCurrent()) scrollReportTarget(documentBody, target);
          })
        });
      },
      onMove: reorderDraftBlock
    });
    const outline = outlineController.element;
    const library = document.createElement("aside");
    library.className = "report-library";
    library.setAttribute("aria-label", "Report sources");
    const availableSidebarWidth = () => panel.dataset.comparisonOpen === "true" ? 0 :
      Math.max(shell.clientWidth, document.querySelector(".workspace-shell")?.clientWidth || 0);
    const libraryControls = createReportLibraryControls({
      panel, shell, library,
      availableWidth: () => Math.max(shell.clientWidth, document.querySelector(".workspace-shell")?.clientWidth || 0),
      reservedWidth: () => panel.dataset.comparisonOpen === "true" ? (panel.dataset.versionsCollapsed === "true" ? 48 : Number(panel.dataset.versionsWidth) || 300) + 1 :
        panel.dataset.outlineHidden === "true" || availableSidebarWidth() <= 1100 ||
        document.querySelector(".workspace-shell")?.classList.contains("has-compact-reference-document")
        ? 0 : (Number(panel.dataset.outlineWidth) || 300) + 1,
      onResize: syncReferenceReaderLayout
    });
    const outlineControls = createReportOutlineControls({
      panel, shell, outline, availableWidth: availableSidebarWidth,
      reservedWidth: () => panel.dataset.libraryOpen === "true" ? (Number(panel.dataset.libraryWidth) || 330) + 1 : 0,
      onResize: syncReferenceReaderLayout
    });
    outline.querySelector("h2").replaceWith(outlineControls.header);
    sourcePicker.setAttribute("aria-label", "Report sources");
    sourcePicker.addEventListener("scroll", () => { reportLibraryScroll.sources = sourcePicker.scrollTop; }, {passive: true});
    sourcePicker.scrollTop = reportLibraryScroll.sources;
    library.append(libraryControls.header, sourcePicker);
    const versionsControls = createReportVersionsControls({
      panel, shell, versions: comparison.versions, availableWidth: () => shell.clientWidth,
      reservedWidth: () => panel.dataset.libraryOpen === "true" ? (Number(panel.dataset.libraryWidth) || 330) + 1 : 0,
      onResize: gesture => comparison.resizeVersions(gesture)
    });
    const versionsTitle = document.createElement("button");
    versionsTitle.type = "button";
    versionsTitle.className = "report-versions-collapse";
    versionsTitle.textContent = "Versions";
    versionsTitle.addEventListener("click", () => {
      panel.dataset.versionsCollapsed = String(panel.dataset.versionsCollapsed !== "true");
      syncReferenceReaderLayout();
      if (panel.dataset.versionsCollapsed !== "true") {
        const row = shell.querySelector(".report-document-columns");
        row.scrollLeft = Math.max(0, row.scrollWidth - row.clientWidth);
      }
    });
    versionsControls.header.querySelector("h2").replaceChildren(versionsTitle);
    comparison.versions.querySelector(".report-versions-header")?.remove();
    comparison.versions.prepend(versionsControls.header);
    panel._reportSidebarControls = [libraryControls, outlineControls, versionsControls, comparison];
    const tools = document.createElement("button");
    tools.type = "button";
    tools.textContent = "Sources";
    tools.title = "Show Report sources and versions";
    tools.setAttribute("aria-expanded", String(panel.dataset.libraryOpen === "true"));
    tools.addEventListener("click", () => {
      const expanded = panel.dataset.libraryOpen !== "true";
      panel.dataset.libraryOpen = String(expanded);
      tools.setAttribute("aria-expanded", String(expanded));
      syncReferenceReaderLayout();
    });
    primaryActions.insertBefore(tools, saveStatus);
    if (panel.dataset.outlineHidden === undefined) {
      panel.dataset.outlineHidden = String(!reportSectionExpanded("Outline column", !initialReportOutlineHidden(activeDraft.blocks)));
    }
    const outlineToggle = document.createElement("button");
    outlineToggle.type = "button";
    outlineToggle.className = "workflow-action workflow-action-secondary";
    outlineToggle.textContent = "Outline";
    const paintOutlineToggle = () => {
      const shown = panel.dataset.outlineHidden !== "true";
      outlineToggle.setAttribute("aria-pressed", String(shown));
      outlineToggle.title = shown ? "Hide Report outline" : "Show Report outline when space allows";
    };
    outlineToggle.addEventListener("click", () => {
      panel.dataset.outlineHidden = String(panel.dataset.outlineHidden !== "true");
      persistReportSectionExpanded("Outline column", panel.dataset.outlineHidden !== "true");
      paintOutlineToggle();
      syncReferenceReaderLayout();
    });
    paintOutlineToggle();
    primaryActions.insertBefore(outlineToggle, saveStatus);
    const versionsToggle = document.createElement("button");
    versionsToggle.type = "button";
    versionsToggle.textContent = "Versions";
    versionsToggle.hidden = history.length === 0;
    versionsToggle.title = "Compare saved PDF versions beside the current Report";
    versionsToggle.addEventListener("click", () => comparison.toggle());
    primaryActions.insertBefore(versionsToggle, saveStatus);
    const columns = document.createElement("div");
    columns.className = "report-workspace-columns";
    columns.setAttribute("role", "region");
    columns.setAttribute("aria-label", "Report columns");
    const documents = document.createElement("div");
    documents.className = "report-document-columns";
    documents.setAttribute("role", "region");
    documents.setAttribute("aria-label", "Report documents");
    documents.tabIndex = 0;
    documents.append(outline, outlineControls.divider, documentBody, comparison.divider, comparison.preview);
    columns.append(library, libraryControls.divider, documents, versionsControls.divider, comparison.versions);
    panel._updateReportColumns = () => {
      versionsToggle.hidden = history.length === 0;
      const comparing = panel.dataset.comparisonOpen === "true";
      const previewing = comparing && Boolean(comparison.selectedID);
      const sourceWidth = panel.dataset.libraryOpen === "true" ? Number(panel.dataset.libraryWidth) || 330 : 0;
      const outlineShown = panel.dataset.outlineHidden !== "true" && (comparing ||
        !document.querySelector(".workspace-shell")?.classList.contains("has-compact-reference-document"));
      const outlineWidth = outlineShown ? Number(panel.dataset.outlineWidth) || 300 : 0;
      const collapsedVersions = panel.dataset.versionsCollapsed === "true";
      const layout = reportComparisonLayout(columns.clientWidth || shell.clientWidth, {
        sources: sourceWidth, outline: outlineWidth, comparing, previewing,
        versions: collapsedVersions ? 48 : Number(panel.dataset.versionsWidth) || 300,
        reportWidth: Number(panel.dataset.reportComparisonWidth) || 0,
        pdfWidth: Number(panel.dataset.pdfComparisonWidth) || 0
      });
      if (sourceWidth && layout.sourcesWidth !== sourceWidth) {
        panel.dataset.libraryWidth = String(layout.sourcesWidth);
        panel.style.setProperty("--report-library-width", `${layout.sourcesWidth}px`);
      }
      if (comparing && !collapsedVersions && layout.versionsWidth !== (Number(panel.dataset.versionsWidth) || 300)) {
        panel.dataset.versionsWidth = String(layout.versionsWidth);
        panel.style.setProperty("--report-versions-width", `${layout.versionsWidth}px`);
      }
      if (columns.style.gridTemplateColumns !== layout.template || documents.style.gridTemplateColumns !== layout.documentTemplate) {
        preserveReportReadingPosition(documentBody, () => {
          columns.style.gridTemplateColumns = layout.template;
          documents.style.gridTemplateColumns = layout.documentTemplate;
        });
      }
      library.hidden = libraryControls.divider.hidden = !sourceWidth;
      outline.hidden = outlineControls.divider.hidden = !outlineShown;
      comparison.preview.hidden = comparison.divider.hidden = !previewing;
      comparison.versions.hidden = versionsControls.divider.hidden = !comparing;
      versionsControls.divider.tabIndex = collapsedVersions ? -1 : 0;
      versionsControls.divider.setAttribute("aria-disabled", String(collapsedVersions));
      versionsTitle.setAttribute("aria-expanded", String(!collapsedVersions));
      versionsTitle.setAttribute("aria-label", `${collapsedVersions ? "Expand" : "Collapse"} Versions list`);
      versionsToggle.setAttribute("aria-pressed", String(comparing));
      tools.setAttribute("aria-expanded", String(Boolean(sourceWidth)));
      paintOutlineToggle();
      libraryControls.update(); versionsControls.update();
    };
    shell.append(primaryActions, columns);
    panel._updateReportColumns();
    documents.scrollLeft = keepPosition ? columnsScroll : 0;
    sourcePicker.scrollTop = reportLibraryScroll.sources;
    comparison.restorePosition(comparisonScroll);
    blocksBody.querySelectorAll(".report-draft-block").forEach(row => {
      const previous = disclosures.get(row.dataset.blockId);
      if (previous) row.querySelectorAll("details").forEach((detail, index) => { detail.open = previous[index] || false; });
    });
    documentBody.scrollTop = documentScroll;
    outline.scrollTop = outlineScroll;
    if (keepPosition && documentScroll) {
      const interaction = reportPresentationInteraction;
      void navigateReportOutline({requests: sourcePreviewRequests.values(),
        isCurrent: () => !disposed && documentBody.isConnected && isCurrentAccountRequest(requestIdentity) &&
          requestWorkspaceID === activeWorkspaceID && reportPresentationInteraction === interaction,
        navigate: () => { documentBody.scrollTop = documentScroll; }});
    }
    documentBody.addEventListener("input", () => outlineController.refreshLabels());
    documentBody.addEventListener("wheel", () => { outlineNavigationGeneration += 1; }, { passive: true });
    documentBody.addEventListener("pointerdown", () => { outlineNavigationGeneration += 1; });
    paintReportSaveState();
    if (panel.isConnected) syncReferenceReaderLayout();
  }

  refreshReportSources = async () => {
    if (disposed || !isCurrentAccountRequest(requestIdentity)) return false;
    const payload = await reportRequest("/reports/sources/list", { projectID });
    if (disposed || !isCurrentAccountRequest(requestIdentity)) return false;
    sources = payload.sources || [];
    sourceWarnings = payload.warnings || [];
    refreshIncludedReportComments();
    const sourcePalette = panel.querySelector(".report-source-palette");
    if (!sourcePalette) return false;
    sourcePalette.replaceChildren();
    renderSourcePalette(sourcePalette);
    return true;
  };

  refreshReportArtifacts = async (options = {}) => {
    if (disposed || deletingReport || deletingVersionID || !isCurrentAccountRequest(requestIdentity)) return false;
    const historyGeneration = historyMutationGeneration;
    const [draftPayload, sourcePayload, historyPayload] = await Promise.all([
      reportRequest("/reports/drafts/list", { projectID }),
      reportRequest("/reports/sources/list", { projectID }),
      reportRequest("/reports/history/list", { projectID })
    ]);
    if (disposed || deletingVersionID || historyGeneration !== historyMutationGeneration || !isCurrentAccountRequest(requestIdentity)) return false;
    drafts = draftPayload.drafts || [];
    sources = sourcePayload.sources || [];
    sourceWarnings = sourcePayload.warnings || [];
    history = historyPayload.reports || [];
    if (dirty) {
      refreshIncludedReportComments();
      const sourcePalette = panel.querySelector(".report-source-palette");
      if (sourcePalette) {
        sourcePalette.replaceChildren();
        renderSourcePalette(sourcePalette);
      }
      const historyBody = panel.querySelector(".report-history");
      if (historyBody) {
        const scroll = historyBody.scrollTop;
        historyBody.replaceChildren();
        renderHistory(historyBody);
        historyBody.scrollTop = scroll;
      }
      panel._updateReportColumns?.();
      return true;
    }
    const nextActiveDraft = drafts.find((draft) => draft.id === (options.draftID || activeDraft.id)) || drafts[0];
    activeDraft = nextActiveDraft
      ? structuredClone(nextActiveDraft)
      : emptyProjectReportDraft(identity);
    clearStatus();
    renderWorkspaceContent();
    return true;
  };

  try {
    const historyPayloadPromise = projectTransitionHubPayload(projectID)
      .then((hubPayload) => hubPayload?.reports || reportRequest("/reports/history/list", { projectID }));
    const [draftPayload, sourcePayload, historyPayload, optionsPayload, recoveries] = await Promise.all([
      reportRequest("/reports/drafts/list", { projectID }),
      reportRequest("/reports/sources/list", { projectID }),
      historyPayloadPromise,
      reportRequest("/reports/options", { projectID }),
      reportDraftRecoveries(accountUserID, projectID).catch(() => [])
    ]);
    if (disposed || !isCurrentAccountRequest(requestIdentity)) return panel;
    drafts = draftPayload.drafts || [];
    const contentIdentity = draft => JSON.stringify([draft.title, draft.reportDate, draft.introduction, draft.blocks]);
    recoveredDrafts = [];
    for (const recovery of recoveries) {
      const serverDraft = drafts.find(draft => draft.id === (recovery.draft.id || recovery.draft.clientDraftID));
      if (serverDraft && contentIdentity(serverDraft) === contentIdentity(recovery.draft)) {
        void deleteReportDraftRecovery(accountUserID, recovery.key, recovery.draft).catch(() => {});
      } else recoveredDrafts.push(recovery);
    }
    sources = sourcePayload.sources || [];
    sourceWarnings = sourcePayload.warnings || [];
    history = historyPayload.reports || [];
    reportOptions = optionsPayload;
    selectedReportTemplateID = optionsPayload.defaultReportTemplateID ||
      optionsPayload.templates?.[0]?.id ||
      "permitext-standard";
    const pendingDraftID = pendingReportDraftByProject.get(projectID);
    const exactDraft = pendingDraftID ? drafts.find((draft) => draft.id === pendingDraftID) : null;
    const requestedDraft = exactDraft || drafts.find(draft => draft.id === resume?.draftID) || drafts[0];
    if (pendingDraftID) {
      reportDraftFocusResultByProject.set(projectID, {
        threadTargetID: pendingDraftID,
        focused: Boolean(exactDraft)
      });
    }
    pendingReportDraftByProject.delete(projectID);
    activeDraft = requestedDraft ? structuredClone(requestedDraft) : emptyProjectReportDraft(identity);
    status.textContent = "";
    renderWorkspaceContent();
  } catch (error) {
    if (disposed || !isCurrentAccountRequest(requestIdentity) || activeWorkspaceID !== requestWorkspaceID) return panel;
    showStatusError(error.payload?.code === "PRO_REQUIRED_EXPORTS"
      ? "Professional Project Reports are included with Permitext Pro."
      : `Report unavailable: ${error.message}`);
    const retry = document.createElement("button");
    retry.type = "button";
    retry.className = "ghost-button report-draft-retry";
    retry.textContent = "Retry Report";
    const canRetry = () => !disposed && panel.isConnected &&
      isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === requestWorkspaceID &&
      projectHasOpenReportDraft(identity);
    retry.addEventListener("click", async () => {
      if (retry.disabled || !canRetry()) return;
      retry.disabled = true;
      try {
        await renderUtilityWorkspace({ refreshPaneIDs: [paneID], skipDeletedProjectCleanup: true, persist: false });
      } catch (retryError) {
        if (canRetry()) showStatusError(`Report unavailable: ${retryError.message}`);
      } finally {
        if (canRetry()) retry.disabled = false;
      }
    });
    shell.append(retry);
  }
  return panel;
}

function closeProjectDetailForProject(project) {
  const matchingDetails = openProjectDetails().filter((detail) => projectDetailMatches(project, detail));
  if (!matchingDetails.length) return;
  state.projectContextOpen = false;
  state.projectFactsOpen = false;
  setOpenProjectDetails(openProjectDetails().filter((detail) => !projectDetailMatches(project, detail)));
  matchingDetails.forEach((detail) => {
    const detailID = paneIDForProjectDetail(detail);
    const contextID = paneIDForProjectInformation(detail, "context");
    const factsID = paneIDForProjectInformation(detail, "facts");
    projectInformationMounts.delete(contextID);
    projectInformationMounts.delete(factsID);
    delete state.paneWeights[contextID];
    delete state.paneWeights[factsID];
    const workboardID = paneIDForProjectWorkboard(detail);
    const notebookID = paneIDForProjectNotebook(detail);
    const reportDraftID = paneIDForProjectReportDraft(detail);
    const coordinationID = paneIDForProjectCoordination(detail);
    const coordinationThread = openCoordinationThreadForProject(detail);
    const coordinationThreadID = coordinationThread
      ? paneIDForProjectCoordinationThread(detail, coordinationThread.threadID)
      : "";
    delete state.paneWeights[detailID];
    delete state.paneWeights[workboardID];
    delete state.paneWeights[notebookID];
    delete state.paneWeights[reportDraftID];
    delete state.paneWeights[coordinationID];
    if (coordinationThreadID) delete state.paneWeights[coordinationThreadID];
    state.paneOrder = (state.paneOrder || [])
      .filter((id) =>
        id !== detailID &&
        id !== contextID &&
        id !== factsID &&
        id !== workboardID &&
        id !== notebookID &&
        id !== reportDraftID &&
        id !== coordinationID &&
        id !== coordinationThreadID
      );
  });
  state.workboards = openWorkboards().filter((item) => !projectDetailMatches(project, item));
  state.notebooks = openNotebooks().filter((item) => !projectDetailMatches(project, item));
  state.reportDrafts = openReportDrafts().filter((item) => !projectDetailMatches(project, item));
  state.coordinations = openCoordinations().filter((item) => !projectDetailMatches(project, item));
  state.coordinationThreads = openCoordinationThreads().filter((item) => !projectDetailMatches(project, item));
}

function closeDeletedProjectDetails() {
  if (syncedContent?.status !== "connected") return false;
  const visibleProjects = visibleProjectRecords(syncedContent.summary?.projects || []);
  const deletedDetails = openProjectDetails().filter((detail) =>
    !visibleProjects.some((project) => projectDetailMatches(project, detail))
  );
  deletedDetails.forEach((detail) => closeProjectDetailForProject(detail));
  return deletedDetails.length > 0;
}

async function archiveProject(project) {
  return archiveProjects([project]);
}

async function refreshProjectOverviewPreservingSavedPanes(...additionalPaneIDs) {
  const requestIdentity = captureAccountRequest();
  const savedIDs = savedPaneIDs();
  const results = await Promise.all(savedIDs.map(async (paneID) => ({
    paneID,
    refreshed: await refreshSavedPanelInPlace(paneID)
  })));
  requireCurrentAccountRequest(requestIdentity);
  const failedSavedIDs = new Set(
    results.filter((result) => !result.refreshed).map((result) => result.paneID)
  );
  const refreshPaneIDs = projectOverviewRefreshPaneIDs(...additionalPaneIDs).filter((paneID) =>
    !savedIDs.includes(paneID) || failedSavedIDs.has(paneID)
  );
  await transitionWorkspace("utility", { refreshPaneIDs });
  requireCurrentAccountRequest(requestIdentity);
}

async function archiveProjects(projects, options = {}) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const archived = archivedProjectIDSet();
  const eligibleProjects = projects.filter((project) => projectRecordID(project));
  if (!eligibleProjects.length) return false;
  const archivedAt = new Date().toISOString();
  eligibleProjects.forEach((project) => archived.add(projectRecordID(project)));
  state.archivedProjectIDs = Array.from(archived);
  const archivedProjects = eligibleProjects.map((project) => ({
    ...project,
    archivedAt,
    updatedAt: archivedAt
  }));
  const archivedIDs = new Set(archivedProjects.map(projectRecordID));
  state.localProjects = [
    ...(state.localProjects || []).filter((project) => !archivedIDs.has(projectRecordID(project))),
    ...archivedProjects
  ];
  eligibleProjects.forEach((project) => closeProjectDetailForProject(project));
  state.detachedWorkboards = detachedWorkboards().filter((item) =>
    !eligibleProjects.some((project) => projectDetailMatches(project, item))
  );
  const currentLeft = track.scrollLeft;
  saveWorkspaceState();
  const account = activeAccount();
  if (account) {
    for (const project of archivedProjects) {
      try {
        await pushMutation(projectMutationForRecord(project, account));
        requireCurrentAccountRequest(requestIdentity);
        state.localProjects = (state.localProjects || [])
          .filter((item) => projectRecordID(item) !== projectRecordID(project));
      } catch (error) {
        requireCurrentAccountRequest(requestIdentity);
        if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
        // Keep the local archived overlay while the durable sync queue recovers.
      }
    }
    saveWorkspaceState();
  }
  requireCurrentAccountRequest(requestIdentity);
  if (options.preserveSavedPanes) {
    await refreshProjectOverviewPreservingSavedPanes(...(state.utilities.archive ? ["utility:archive"] : []));
  } else {
    await transitionWorkspace("utility", {
      refreshPaneIDs: projectOverviewRefreshPaneIDs(...(state.utilities.archive ? ["utility:archive"] : []))
    });
  }
  requireCurrentAccountRequest(requestIdentity);
  track.scrollLeft = currentLeft;
  return true;
}

async function restoreArchivedProject(project) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const id = projectRecordID(project);
  if (!id) return;
  const restoredAt = new Date().toISOString();
  const restoredProject = {
    ...project,
    archivedAt: null,
    updatedAt: restoredAt
  };
  state.archivedProjectIDs = Array.from(archivedProjectIDSet()).filter((projectID) => projectID !== id);
  state.localProjects = [
    ...(state.localProjects || []).filter((item) => projectRecordID(item) !== id),
    restoredProject
  ];
  const currentLeft = track.scrollLeft;
  saveWorkspaceState();
  const account = activeAccount();
  if (account) {
    try {
      await pushMutation(projectMutationForRecord(restoredProject, account));
      requireCurrentAccountRequest(requestIdentity);
      state.localProjects = (state.localProjects || []).filter((item) => projectRecordID(item) !== id);
      saveWorkspaceState();
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
      // Keep the local restored overlay while the durable sync queue recovers.
    }
  }
  requireCurrentAccountRequest(requestIdentity);
  await transitionWorkspace("utility", { refreshPaneIDs: projectOverviewRefreshPaneIDs("utility:archive") });
  requireCurrentAccountRequest(requestIdentity);
  track.scrollLeft = currentLeft;
}

async function deleteArchivedProject(project) {
  const requestIdentity = captureAccountRequest();
  const id = projectRecordID(project);
  if (!id) return;
  const recordLabel = folderTypeLabel(project);
  const name = project.name || project.title || `this ${recordLabel.toLowerCase()}`;
  const confirmed = await confirmWebWarning(
    `Delete ${recordLabel}`,
    `Move ${name} to Trash? You can restore it from Account → Trash for 30 days. Saved bookmarks will remain.`,
    { confirmLabel: "Move to Trash", container: document.body }
  );
  requireCurrentAccountRequest(requestIdentity);
  if (!confirmed) return;
  const currentLeft = track.scrollLeft;
  try {
    await prepareRecoverableDeletion();
    requireCurrentAccountRequest(requestIdentity);
    await deleteArchivedProjectData(project);
    requireCurrentAccountRequest(requestIdentity);
  } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    await showWebNotice(`Could not delete ${recordLabel.toLowerCase()}`, error.message || `The ${recordLabel.toLowerCase()} could not be deleted.`, { container: document.body });
    return;
  }
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: projectOverviewRefreshPaneIDs("utility:archive") });
  requireCurrentAccountRequest(requestIdentity);
  track.scrollLeft = currentLeft;
}

async function deleteArchivedProjects(projects, options = {}) {
  const requestIdentity = captureAccountRequest();
  const eligibleProjects = projects.filter((project) => projectRecordID(project));
  if (!eligibleProjects.length) return false;
  const count = eligibleProjects.length;
  const recordLabel = folderRecordCountLabel(eligibleProjects);
  const names = options.includeNames
    ? `\n\n${eligibleProjects.map((project) => project.name || project.title || "Project").join("\n")}`
    : "";
  const confirmed = await confirmWebWarning(
    `Delete ${recordLabel}`,
    `Move ${recordLabel} to Trash? You can restore ${count === 1 ? "it" : "them"} from Account → Trash for 30 days. Saved bookmarks will remain.${names}`,
    { confirmLabel: "Move to Trash", container: document.body }
  );
  requireCurrentAccountRequest(requestIdentity);
  if (!confirmed) return false;
  const currentLeft = track.scrollLeft;
  try {
    await prepareRecoverableDeletion();
    requireCurrentAccountRequest(requestIdentity);
  } catch (error) {
    requireCurrentAccountRequest(requestIdentity);
    await showWebNotice("Could not move to Trash", error.message, { container: document.body });
    return false;
  }
  let deletedCount = 0;
  const deletedIDs = new Set();
  for (const project of eligibleProjects) {
    try {
      await deleteArchivedProjectData(project);
      requireCurrentAccountRequest(requestIdentity);
      deletedCount += 1;
      deletedIDs.add(projectRecordID(project));
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      const progress = deletedCount > 0 ? ` Deleted ${deletedCount} of ${count}.` : "";
      await showWebNotice(
        "Could not delete selected records",
        `${error.message || `The selected ${recordLabel} could not be deleted.`}${progress}`,
        { container: document.body }
      );
      requireCurrentAccountRequest(requestIdentity);
      break;
    }
  }
  state.localProjects = (state.localProjects || []).filter((item) => !deletedIDs.has(projectRecordID(item)));
  state.archivedProjectIDs = Array.from(archivedProjectIDSet()).filter((id) => !deletedIDs.has(id));
  saveWorkspaceState();
  if (options.preserveSavedPanes) {
    await refreshProjectOverviewPreservingSavedPanes("utility:archive");
  } else {
    await transitionWorkspace("utility", { refreshPaneIDs: projectOverviewRefreshPaneIDs("utility:archive") });
  }
  requireCurrentAccountRequest(requestIdentity);
  track.scrollLeft = currentLeft;
  return deletedCount > 0;
}

async function deleteArchivedProjectData(project) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const account = activeAccount();
  const id = projectRecordID(project);
  if (!id) return;
  const workboardID = workboardProjectID(projectIdentity(project));
  const deletedAt = new Date().toISOString();
  const linkedSections = (currentContentSummary().projectSections || [])
    .filter((item) => projectSectionBelongsToProject(item, project));
  const membershipTombstones = linkedSections.map((item) =>
    deletedProjectSectionMutationForItem(project, item).projectSection
  );
  state.localProjects = [
    ...(state.localProjects || []).filter((item) => projectRecordID(item) !== id),
    { ...project, updatedAt: deletedAt, deletedAt }
  ];
  state.archivedProjectIDs = Array.from(archivedProjectIDSet()).filter((projectID) => projectID !== id);
  state.localProjectSections = [
    ...(state.localProjectSections || []).filter((item) => !projectSectionBelongsToProject(item, project)),
    ...membershipTombstones
  ];
  saveWorkspaceState();
  if (account) {
    try {
      membershipTombstones.forEach((record) => enqueueSyncMutation({ projectSection: record }, account));
      enqueueSyncMutation(deletedProjectMutationForRecord(project), account);
      await flushSyncOutbox({ refresh: true });
      requireCurrentAccountRequest(requestIdentity);
    } catch (error) {
      requireCurrentAccountRequest(requestIdentity);
      if (isSessionAuthenticationError(error)) clearExpiredAccountSession();
      // Keep the local deletion tombstone while sync recovers.
    }
  }
  requireCurrentAccountRequest(requestIdentity);
  if (account) {
    try {
      await deleteSyncedWorkboard(workboardID);
      requireCurrentAccountRequest(requestIdentity);
    } catch {
      requireCurrentAccountRequest(requestIdentity);
      // The project deletion must survive a missing or stale Workboard record.
    }
  }
  await deleteLocalWorkboard(workboardID);
  requireCurrentAccountRequest(requestIdentity);
  closeProjectDetailForProject(project);
  state.detachedWorkboards = detachedWorkboards().filter((item) => !projectDetailMatches(project, item));
}

