function populateSavedEvidenceSection(section, savedInstance, folder, ...children) {
  const folderID = projectRecordID(folder);
  const { heading, title, search, select } = createSavedEvidenceHeading();
  const body = document.createElement("div");
  body.className = "saved-project-evidence-body";
  body.id = `saved-evidence-${safeAnnotationIDPart(folderID)}-${safeAnnotationIDPart(savedInstance.id)}`;
  title.setAttribute("aria-controls", body.id);
  if (folderIsProject(folder)) {
    title.remove();
    if (!folder.sharedOnly && hasCapability("professional-exports")) {
      const destination = reportMembershipIndicator(projectDetailKey(projectIdentity(folder)), "destination", {});
      destination.classList.add("evidence-report-destination");
      heading.prepend(destination);
    }
    body.append(...children);
    section.append(heading, body);
    return;
  }
  body.append(...children);
  section.append(heading, body);
  const collapsedFolderIDs = new Set(savedInstance.collapsedEvidenceFolderIDs);
  const recordExpandedState = (expanded) => {
    if (expanded) collapsedFolderIDs.delete(folderID);
    else collapsedFolderIDs.add(folderID);
    savedInstance.collapsedEvidenceFolderIDs = Array.from(collapsedFolderIDs);
    persistProjectSectionExpansion(folder, "savedEvidence", expanded);
  };
  const setExpanded = wireProjectSectionMotion(
    section,
    body,
    [title],
    "Saved evidence",
    projectSectionExpanded(folder, "savedEvidence", !collapsedFolderIDs.has(folderID)),
    {
      onChange: recordExpandedState
    }
  );
  [search, select].forEach((control) => control.addEventListener("click", () => {
    if (!collapsedFolderIDs.has(folderID)) return;
    setExpanded(true);
    recordExpandedState(true);
  }, { capture: true }));
}

function appendProjectRecordsChecklist(container, project, identity) {
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  let items = normalizeRecordsChecklist(project.recordsChecklist || []);
  let saved = JSON.stringify(items);
  let pending = null;
  const current = () => isCurrentAccountRequest(requestIdentity) && workspaceID === activeWorkspaceID;
  const section = document.createElement("section");
  section.className = "project-records-checklist workflow-section";
  const heading = document.createElement("h3");
  heading.textContent = "Records checklist";
  const copy = document.createElement("p");
  copy.className = "workflow-help";
  copy.textContent = "Track records to obtain and review. A reviewed record does not automatically confirm a Project fact.";
  const list = document.createElement("div");
  const status = document.createElement("p");
  status.className = "workflow-help";
  status.setAttribute("role", "status");
  const retry = document.createElement("button");
  retry.type = "button";
  retry.className = "workflow-action workflow-action-secondary";
  retry.textContent = "Retry saving checklist";
  retry.hidden = true;
  const save = () => {
    if (pending) return pending;
    if (!current() || identity.sharedOnly || saved === JSON.stringify(items)) return Promise.resolve();
    pending = (async () => {
      while (current() && saved !== JSON.stringify(items)) {
        const snapshot = normalizeRecordsChecklist(items);
        const result = await updateProjectFolder(project, { recordsChecklist: snapshot });
        if (result === false) throw new Error("Checklist could not be saved.");
        saved = JSON.stringify(snapshot);
      }
      if (current()) { status.textContent = ""; retry.hidden = true; }
    })().catch(error => {
      if (current()) { status.textContent = "Checklist not saved. Your changes are still here."; retry.hidden = false; }
      throw error;
    }).finally(() => { pending = null; });
    return pending;
  };
  const autosave = () => { void save().catch(() => {}); };
  retry.addEventListener("click", autosave);
  const render = () => {
    list.replaceChildren();
    for (const item of items) {
      const row = document.createElement("article");
      row.className = "project-records-row";
      const label = document.createElement("input");
      label.value = item.label; label.maxLength = 300;
      label.setAttribute("aria-label", "Record name");
      label.addEventListener("change", () => {
        if (!label.value.trim()) { label.value = item.label; return; }
        item.label = label.value.trim(); autosave();
      });
      const select = document.createElement("select");
      select.setAttribute("aria-label", `Status for ${item.label}`);
      for (const value of recordStatuses) {
        const option = document.createElement("option"); option.value = value;
        option.textContent = {needed:"Needed",requested:"Requested",received:"Received",reviewed:"Reviewed","not-applicable":"Not applicable"}[value];
        select.append(option);
      }
      select.value = item.status;
      select.addEventListener("change", () => { item.status = select.value; autosave(); });
      const note = document.createElement("textarea");
      note.rows = 2; note.maxLength = 2000; note.value = item.note;
      note.placeholder = "Source, date, or follow-up";
      note.setAttribute("aria-label", `Record notes for ${item.label}`);
      note.addEventListener("input", () => { item.note = note.value; });
      note.addEventListener("blur", autosave);
      const remove = document.createElement("button");
      remove.type = "button"; remove.className = "workflow-action workflow-action-secondary";
      remove.textContent = "Remove"; remove.setAttribute("aria-label", `Remove record ${item.label}`);
      remove.addEventListener("click", () => { items = items.filter(candidate => candidate.id !== item.id); render(); autosave(); });
      for (const input of [label,select,note,remove]) input.disabled = Boolean(identity.sharedOnly);
      row.append(label, select, note, remove); list.append(row);
    }
  };
  const add = document.createElement("button");
  add.type = "button"; add.className = "workflow-action workflow-action-secondary";
  add.textContent = "Add record"; add.disabled = Boolean(identity.sharedOnly);
  add.addEventListener("click", () => {
    if (items.length >= 50) { status.textContent = "A checklist can contain up to 50 records."; return; }
    items.push({id:crypto.randomUUID(),label:"New record",status:"needed",note:""});
    render(); autosave(); list.lastElementChild?.querySelector("input")?.focus();
  });
  const suggested = document.createElement("button");
  suggested.type = "button"; suggested.className = "workflow-action workflow-action-secondary";
  suggested.textContent = "Add suggested records"; suggested.disabled = Boolean(identity.sharedOnly);
  suggested.addEventListener("click", () => {
    for (const label of suggestedRecords) if (items.length < 50 && !items.some(item => item.label === label)) {
      items.push({id:crypto.randomUUID(),label,status:"needed",note:""});
    }
    render(); autosave();
  });
  section.append(heading,copy,list,add,suggested,status,retry); container.append(section); render();
  return { flush: save };
}

async function renderProjectInformation(project, kind) {
  const identity = projectIdentity(project);
  const paneID = paneIDForProjectInformation(identity, kind);
  const label = kind === "context" ? "Context" : "Facts";
  if (!hasCapability("projects")) return renderProLockedPane(paneID, label);
  const current = workspaceProject();
  if (!current || !projectDetailMatches(current, identity)) throw accountContextChangedError();
  const panel = document.createElement("article");
  panel.className = `workspace-panel project-information-panel project-${kind}-panel`;
  panel.dataset.paneId = paneID;
  panel.dataset.projectId = projectDetailKey(identity);
  const header = document.createElement("header");
  header.className = "panel-header";
  const title = document.createElement("h2");
  title.className = "eyebrow panel-kind";
  title.textContent = label;
  const actions = document.createElement("div");
  actions.className = "panel-actions";
  const close = document.createElement("button");
  close.className = "icon-button utility-close";
  close.type = "button";
  close.setAttribute("aria-label", `Close ${label}`);
  close.innerHTML = circleXIconSVG();
  close.addEventListener("click", () => void closeProjectInformation(identity, kind));
  actions.append(close);
  actions.append(createProjectToolDragHandle(identity));
  header.append(title, actions);
  const content = document.createElement("section");
  content.className = "saved-project-summary project-information-content";
  const editor = appendSavedProjectFactEditor(content, current, projectIdentity(current), { section: kind });
  const checklist = kind === "context" ? appendProjectRecordsChecklist(content, current, identity) : null;
  projectInformationMounts.set(paneID, { panel, flush: async () => { await editor.flush(); await checklist?.flush(); } });
  panel.append(header, content);
  applyPaneWeight(panel, paneID);
  return panel;
}

function appendSavedProjectFactEditor(container, folder, identity, options = {}) {
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const contextOnly = options.section === "context";
  const factsOnly = options.section === "facts";
  const factsSection = document.createElement("section");
  factsSection.className = "saved-project-facts-section";
  const heading = document.createElement("div");
  heading.className = "saved-project-facts-heading";
  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "saved-project-facts-toggle section-label";
  toggle.textContent = "Project context";
  const chevron = document.createElement("button");
  chevron.type = "button";
  chevron.className = "project-section-toggle-chevron saved-project-facts-chevron";
  chevron.innerHTML = researchChevronIconsSVG();
  heading.append(toggle, chevron);

  const body = document.createElement("section");
  body.className = "saved-project-facts-body";

  const address = document.createElement("input");
  address.type = "text";
  address.className = "saved-project-fact-input saved-project-fact-address";
  address.value = String(folder.address || identity.address || "");
  address.placeholder = "Add project address";
  address.autocomplete = "street-address";
  address.setAttribute("aria-label", "Project address");

  const description = document.createElement("textarea");
  description.className = "saved-project-fact-input saved-project-fact-description";
  description.value = String(folder.description || identity.description || "");
  description.placeholder = "Add existing conditions, proposed work, relevant dates, constraints, assumptions, and other Project context";
  description.rows = 2;
  description.setAttribute("aria-label", "Project context");
  const storedStructuredFacts = projectStructuredFacts(folder);
  const legacyAddressFact = storedStructuredFacts.find((fact) => fact.key === "address");
  if (!address.value.trim() && legacyAddressFact?.value) address.value = legacyAddressFact.value;
  let structuredFacts = migratedProjectStructuredFacts({ structuredFacts: storedStructuredFacts });
  let saved = {
    address: address.value,
    description: description.value,
    structuredFacts: storedStructuredFacts
  };
  let saveSequence = Promise.resolve();
  let submitted = null;
  const save = ({ reportFailure = false } = {}) => {
    if (!isCurrentAccountRequest(requestIdentity) || workspaceID !== activeWorkspaceID) return Promise.resolve();
    const next = {
      address: address.value.trim(),
      description: description.value.trim(),
      structuredFacts: projectStructuredFacts({ structuredFacts })
    };
    if (!submitted &&
      (contextOnly || next.address === saved.address) &&
      (factsOnly || next.description === saved.description) &&
      (contextOnly || JSON.stringify(next.structuredFacts) === JSON.stringify(saved.structuredFacts))
    ) return saveSequence;
    if (JSON.stringify(next) === JSON.stringify(submitted)) return saveSequence;
    submitted = next;
    const changes = contextOnly ? { description: next.description }
      : factsOnly ? { address: next.address, structuredFacts: next.structuredFacts }
      : { address: next.address, description: next.description, structuredFacts: next.structuredFacts };
    saveSequence = updateProjectFolder(folder, changes).then((updated) => {
        if (updated === false) throw new Error("Project edits were not saved. Try again.");
        if (isCurrentAccountRequest(requestIdentity) && submitted === next) { saved = next; submitted = null; }
      }).catch((error) => {
      if (submitted === next) submitted = null;
      if (reportFailure) throw error;
      void showWebNotice(factsOnly ? "Project facts not saved" : "Project context not saved", error.message || "Could not save Project edits");
      throw error;
    });
    // Blur autosave reports its own failure; explicit close/switch still awaits it.
    void saveSequence.catch(() => {});
    return saveSequence;
  };
  if (contextOnly) {
    description.addEventListener("blur", () => void save());
    description.addEventListener("keydown", event => {
      if ((event.metaKey || event.ctrlKey) && event.key === "Enter") description.blur();
      if (event.key === "Escape") { event.preventDefault(); description.value = saved.description; description.blur(); }
    });
    description.disabled = Boolean(identity.sharedOnly);
    if (identity.sharedOnly) description.title = "Project context is read-only in this shared Project";
    container.append(description);
    return { flush: () => save({ reportFailure: true }) };
  }
  let structuredSaveTimer = 0;
  const scheduleStructuredSave = () => {
    window.clearTimeout(structuredSaveTimer);
    void save();
  };

  const structuredSection = document.createElement("section");
  structuredSection.className = "saved-project-structured-section";
  const structuredHeading = document.createElement("div");
  structuredHeading.className = "saved-project-facts-heading";
  const structuredToggle = document.createElement("button");
  structuredToggle.type = "button";
  structuredToggle.className = "saved-project-facts-toggle section-label";
  structuredToggle.textContent = "Structured facts";
  structuredHeading.append(structuredToggle);
  const structuredBody = document.createElement("section");
  structuredBody.className = "saved-project-structured-facts";
  const structuredGroups = document.createElement("div");
  structuredGroups.className = "saved-project-structured-groups";
  structuredBody.append(structuredGroups);
  structuredSection.append(structuredHeading, structuredBody);

  const replaceFact = (key, label, value, id = `project-fact:${key}`) => {
    structuredFacts = structuredFacts.filter((fact) => fact.key !== key);
    const normalized = normalizeProjectStructuredFact({
      id,
      key,
      label,
      value,
      status: "stated",
      source: "user",
      sourceText: "",
      updatedAt: new Date().toISOString()
    });
    if (normalized) structuredFacts.push(normalized);
  };

  const appendDefaultFactField = (list, field, factsByKey) => {
    const { key, label: fieldLabel, projectAddress = false } = field;
    const row = document.createElement("article");
    row.className = "saved-project-structured-fact";
    row.dataset.factKey = key;
    const label = document.createElement("label");
    label.className = "saved-project-structured-fact-label";
    label.textContent = fieldLabel;
    const value = document.createElement("input");
    value.type = "text";
    value.className = "saved-project-structured-fact-value";
    value.value = projectAddress ? address.value : factsByKey.get(key)?.value || "";
    value.setAttribute("aria-label", fieldLabel);
    const fact = factsByKey.get(key);
    if (fact?.sourceText) value.title = fact.sourceText;
    label.htmlFor = value.id = `project-structured-${safeAnnotationIDPart(projectRecordID(folder))}-${key}`;
    row.append(label, value);
    if (fact) {
      const review = document.createElement("small");
      review.className = "project-fact-review-status";
      review.textContent = ({unknown: "Needs review", assumed: "Assumption", confirmed: "Confirmed", stated: "Stated", sourced: "Sourced", rejected: "Rejected"})[fact.status] || fact.status;
      if (fact.source && fact.source !== "user") review.textContent += ` · ${fact.source}`;
      if (fact.sourceText) review.title = fact.sourceText;
      row.append(review);
    }
    value.addEventListener("input", () => {
      if (projectAddress) address.value = value.value;
      else replaceFact(key, fieldLabel, value.value);
      scheduleStructuredSave();
    });
    value.addEventListener("blur", save);
    if (identity.sharedOnly) value.disabled = true;
    list.append(row);
  };

  const groupLists = new Map();
  const presentationGroups = factsOnly ? projectFactPresentationGroups() : projectStructuredFactGroups;
  let showAllFacts = false;
  const factFilter = document.createElement("button");
  factFilter.type = "button";
  factFilter.className = "ghost-button project-facts-filter";
  factFilter.textContent = "All facts";
  factFilter.setAttribute("aria-pressed", "false");
  const applyFactVisibility = () => {
    if (!factsOnly) return;
    const factsByKey = new Map(structuredFacts.map(fact => [fact.key, fact]));
    for (const group of presentationGroups) {
      const list = groupLists.get(group.key);
      for (const row of list.children) {
        const field = group.fields.find(field => field.key === row.dataset.factKey);
        row.hidden = !showProjectFact(field, factsByKey.get(field.key), {all: showAllFacts, address: address.value});
      }
      list.closest(".saved-project-structured-group").hidden = ![...list.children].some(row => !row.hidden);
    }
  };
  factFilter.addEventListener("click", () => {
    showAllFacts = !showAllFacts;
    factFilter.textContent = showAllFacts ? "Recorded & core facts" : "All facts";
    factFilter.setAttribute("aria-pressed", String(showAllFacts));
    applyFactVisibility();
  });
  if (factsOnly) structuredBody.prepend(factFilter);
  presentationGroups.forEach((group, groupIndex) => {
    const groupSection = document.createElement("section");
    groupSection.className = `saved-project-structured-group is-${group.key}`;
    const groupHeading = document.createElement("div");
    groupHeading.className = "saved-project-structured-group-heading";
    const groupToggle = document.createElement(factsOnly ? "h3" : "button");
    if (!factsOnly) groupToggle.type = "button";
    groupToggle.className = factsOnly ? "saved-project-structured-group-label" : "saved-project-structured-group-toggle section-label";
    groupToggle.textContent = group.label;
    groupHeading.append(groupToggle);
    const groupBody = document.createElement("section");
    groupBody.className = "saved-project-structured-group-body";
    const groupList = document.createElement("div");
    groupList.className = "saved-project-structured-facts-list";
    groupBody.append(groupList);
    groupSection.append(groupHeading, groupBody);
    structuredGroups.append(groupSection);
    groupLists.set(group.key, groupList);
    if (factsOnly) {
      groupSection.classList.add("is-open");
    } else {
      const groupChevron = document.createElement("button");
      groupChevron.type = "button";
      groupChevron.className = "project-section-toggle-chevron saved-project-structured-group-chevron";
      groupChevron.innerHTML = researchChevronIconsSVG();
      groupHeading.append(groupChevron);
      wireProjectSectionMotion(
        groupSection,
        groupBody,
        [groupToggle, groupChevron],
        group.label,
        projectSectionExpanded(identity, `structuredFacts:${group.key}`, groupIndex === 0),
        {
          onChange(expanded) {
            persistProjectSectionExpansion(identity, `structuredFacts:${group.key}`, expanded);
          }
        }
      );
    }
  });
  const renderStructuredFacts = () => {
    groupLists.forEach((list) => clear(list));
    const factsByKey = new Map(structuredFacts.map((fact) => [fact.key, fact]));
    presentationGroups.forEach((group) => {
      group.fields.filter(field => field.key !== "transit-zone" || factsByKey.has(field.key))
        .forEach((field) => appendDefaultFactField(groupLists.get(group.key), field, factsByKey));
    });
    applyFactVisibility();
  };
  renderStructuredFacts();
  let refreshFacts = null;
  if (!identity.sharedOnly) {
    refreshFacts = document.createElement("button");
    refreshFacts.type = "button";
    refreshFacts.className = "saved-project-refresh-facts";
    refreshFacts.innerHTML = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg>';
    refreshFacts.setAttribute("aria-label", "Refresh ZoLa data");
    refreshFacts.title = "Refresh ZoLa data";
    structuredHeading.append(refreshFacts);
    const refreshedStatus = document.createElement("p");
    refreshedStatus.className = "project-refresh-status";
    refreshedStatus.setAttribute("role", "status");
    const updateRefreshDate = () => {
      const dates = structuredFacts.filter(f => f.source === "nyc-planning").map(f => f.updatedAt).filter(Boolean).sort();
      refreshedStatus.textContent = dates.length ? `Last fetched ${new Date(dates.at(-1)).toLocaleString()}` : "";
    };
    structuredBody.prepend(refreshedStatus);
    updateRefreshDate();
    refreshFacts.addEventListener("click", async () => {
      const lookupAddress = address.value.trim();
      const oldBBL = structuredFacts.find(fact => fact.key === "bbl")?.value;
      if (!lookupAddress && !oldBBL) {
        void showWebNotice("Address required", "Enter a Project address to refresh ZoLa data.");
        return;
      }
      const snapshot = JSON.stringify(structuredFacts);
      refreshFacts.disabled = true;
      refreshFacts.setAttribute("aria-busy", "true");
      refreshFacts.setAttribute("aria-label", "Fetching ZoLa data");
      try {
        const property = (await postResearch("/projects/property/lookup", { address: lookupAddress, bbl: oldBBL }))?.property;
        requireCurrentAccountRequest(requestIdentity);
        if (!structuredSection.isConnected || address.value.trim() !== lookupAddress || JSON.stringify(structuredFacts) !== snapshot) return;
        if (!property?.structuredFacts?.length) throw new Error("No property facts returned. Your current facts are unchanged.");
        if (oldBBL && oldBBL !== property.bbl) throw new Error("The returned tax lot does not match the saved BBL.");
        const preview = previewNYCPropertyRefresh(structuredFacts, property.structuredFacts, property.retrievedAt);
        const overlay = document.createElement("section");
        overlay.className = "project-sheet-overlay project-refresh-overlay";
        const dialog = document.createElement("section");
        dialog.className = "project-refresh-dialog";
        dialog.setAttribute("role", "dialog");
        dialog.setAttribute("aria-modal", "true");
        dialog.setAttribute("aria-label", "Review ZoLa updates");
        const title = document.createElement("h2");
        title.textContent = "Review ZoLa updates";
        const intro = document.createElement("p");
        intro.textContent = `BBL ${property.bbl} · Fetched ${new Date(property.retrievedAt).toLocaleString()}. Your edited or confirmed facts are unchecked. Select a conflict only to replace your value.`;
        dialog.append(title, intro);
        const choices = new Map();
        const labels = { new: "New", changed: "Changed", conflict: "Your value differs", unavailable: "Needs review", unchanged: "Unchanged" };
        for (const kind of ["new", "changed", "conflict", "unavailable", "unchanged"]) {
          const rows = preview.filter(row => row.kind === kind);
          if (!rows.length) continue;
          const group = document.createElement("details");
          group.open = kind !== "unchanged";
          const summary = document.createElement("summary");
          summary.textContent = `${labels[kind]} (${rows.length})`;
          group.append(summary);
          for (const row of rows) {
            const label = document.createElement("label");
            label.className = "project-refresh-choice";
            const choice = document.createElement("input");
            choice.type = "checkbox";
            choice.checked = row.selected;
            choice.setAttribute("aria-label", `Update ${row.label}`);
            choices.set(row.key, choice);
            const text = document.createElement("span");
            const name = document.createElement("strong");
            name.textContent = row.label;
            const values = document.createElement("span");
            values.textContent = kind === "new" ? row.next.value : kind === "unavailable" || row.next?.status === "unknown" ? `Current: ${row.current.value}. Current source unavailable; keep this value and flag it for review.` : kind === "unchanged" ? row.current.value : `Current: ${row.current.value} → Latest: ${row.next.value}`;
            const source = document.createElement("small");
            source.textContent = row.next?.sourceText || row.replacement.sourceText;
            text.append(name, values, source);
            label.append(choice, text);
            group.append(label);
          }
          dialog.append(group);
        }
        const warnings = document.createElement("p");
        warnings.textContent = (property.warnings || []).join(" ");
        dialog.append(warnings);
        const actions = document.createElement("div");
        actions.className = "project-refresh-actions";
        const cancel = document.createElement("button");
        cancel.type = "button";
        cancel.textContent = "Cancel";
        const apply = document.createElement("button");
        apply.type = "button";
        apply.textContent = "Apply updates";
        const close = () => {
          overlay.remove();
          const returnTarget = factsOnly ? container.closest(".workspace-panel")?.querySelector(".column-group-menu-button") : refreshFacts;
          returnTarget?.focus();
        };
        cancel.addEventListener("click", close);
        overlay.addEventListener("keydown", event => {
          if (event.key === "Escape" && !apply.disabled) { event.preventDefault(); close(); }
          if (event.key === "Tab") {
            const controls = [...dialog.querySelectorAll('button:not(:disabled), input, summary')].filter(e => e.getClientRects().length);
            const first = controls[0], last = controls.at(-1);
            if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
            else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
          }
        });
        apply.addEventListener("click", async () => {
          if (!isCurrentAccountRequest(requestIdentity) || !structuredSection.isConnected || address.value.trim() !== lookupAddress || JSON.stringify(structuredFacts) !== snapshot) {
            close();
            void showWebNotice("Project changed", "Fetch the property data again before applying updates.");
            return;
          }
          const previous = structuredFacts;
          structuredFacts = applyNYCPropertyRefresh(structuredFacts, preview, new Set([...choices].filter(([, control]) => control.checked).map(([key]) => key)));
          apply.disabled = cancel.disabled = true;
          apply.textContent = "Saving…";
          try {
            await save({ reportFailure: true });
            if (isCurrentAccountRequest(requestIdentity) && structuredSection.isConnected) {
              renderStructuredFacts();
              updateRefreshDate();
              refreshedStatus.textContent += " · Selected updates applied";
            }
            close();
          } catch (error) {
            structuredFacts = previous;
            apply.disabled = cancel.disabled = false;
            apply.textContent = "Apply updates";
            warnings.textContent = error.message || "Could not save updates. Try again.";
          }
        });
        actions.append(cancel, apply);
        dialog.append(actions);
        overlay.append(dialog);
        document.body.append(overlay);
        cancel.focus();
      } catch (error) {
        if (isCurrentAccountRequest(requestIdentity)) void showWebNotice("ZoLa data could not be fetched", error.message || "Try again.");
      } finally {
        refreshFacts.disabled = false;
        refreshFacts.removeAttribute("aria-busy");
        refreshFacts.setAttribute("aria-label", "Refresh ZoLa data");
      }
    });
  }

  if (
    !identity.sharedOnly &&
    JSON.stringify(structuredFacts) !== JSON.stringify(storedStructuredFacts)
  ) {
    queueMicrotask(() => void save());
  }
  const restore = (control, value) => {
    control.value = value;
    control.blur();
  };

  address.addEventListener("input", () => {
    const zoningAddress = structuredBody.querySelector('input[aria-label="Address"]');
    if (zoningAddress && zoningAddress !== document.activeElement) zoningAddress.value = address.value;
  });
  address.addEventListener("blur", save);
  description.addEventListener("blur", save);
  address.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      address.blur();
    } else if (event.key === "Escape") {
      event.preventDefault();
      restore(address, saved.address);
    }
  });
  description.addEventListener("keydown", (event) => {
    if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
      event.preventDefault();
      description.blur();
    } else if (event.key === "Escape") {
      event.preventDefault();
      restore(description, saved.description);
    }
  });

  if (identity.sharedOnly) {
    address.disabled = true;
    description.disabled = true;
    address.title = description.title = "Project context is read-only in this shared Project";
  }
  body.append(description);
  factsSection.append(heading, body);
  if (factsOnly) {
    structuredSection.classList.add("is-open");
    structuredHeading.remove();
    container.append(structuredSection);
    return {
      flush: () => save({ reportFailure: true }),
      refreshZoLa: refreshFacts ? () => refreshFacts.click() : null,
      isRefreshing: () => Boolean(refreshFacts?.disabled)
    };
  }
  container.append(factsSection, structuredSection);
  wireProjectSectionMotion(
    factsSection,
    body,
    [toggle, chevron],
    "Project context",
    projectSectionExpanded(identity, "projectFacts", false),
    {
      onChange(expanded) {
        persistProjectSectionExpansion(identity, "projectFacts", expanded);
      }
    }
  );
  wireProjectSectionMotion(
    structuredSection,
    structuredBody,
    [structuredToggle],
    "Structured facts",
    projectSectionExpanded(identity, "structuredFacts", false),
    {
      onChange(expanded) {
        persistProjectSectionExpansion(identity, "structuredFacts", expanded);
      }
    }
  );
  return { flush: () => save({ reportFailure: true }) };
}

const initialProjectFoundationScopes = new Set();
const initialProjectFoundationRevisions = new Map();

function createInitialProjectFoundationScope() {
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const consumers = new Set();
  const entries = new Map();
  let disposed = false;
  const guardResult = (promise) => promise.then((payload) => {
    if (!isCurrentAccountRequest(identity) || workspaceID !== activeWorkspaceID) throw accountContextChangedError();
    return payload;
  });
  const scope = {
    register(id) { if (!disposed) consumers.add(id); },
    release(id) {
      consumers.delete(id);
      if (!consumers.size) { disposed = true; entries.clear(); initialProjectFoundationScopes.delete(scope); }
    },
    invalidate(projectID) { entries.delete(String(projectID)); },
    read(project) {
      if (!isCurrentAccountRequest(identity) || workspaceID !== activeWorkspaceID) {
        return Promise.reject(accountContextChangedError());
      }
      if (disposed) return guardResult(loadInitialProjectFoundation(project));
      const key = String(projectDetailKey(project));
      const scopeKey = String(project.sharedOrganizationID || "");
      const existing = entries.get(key);
      if (existing?.scopeKey === scopeKey) return guardResult(existing.promise);
      const promise = loadInitialProjectFoundation(project);
      const entry = { scopeKey, promise };
      entries.set(key, entry);
      void promise.catch(() => { if (entries.get(key) === entry) entries.delete(key); });
      return guardResult(promise);
    }
  };
  initialProjectFoundationScopes.add(scope);
  return scope;
}

function invalidateInitialProjectFoundation(projectID) {
  const id = String(projectID);
  initialProjectFoundationRevisions.set(id, (initialProjectFoundationRevisions.get(id) || 0) + 1);
  initialProjectFoundationScopes.forEach((scope) => scope.invalidate(projectID));
}

const initialProjectFoundationReads = new Map();

function loadInitialProjectFoundation(project) {
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const projectID = projectDetailKey(project);
  const sharedScope = String(project.sharedOrganizationID || "");
  const key = JSON.stringify([requestIdentity.userID, requestIdentity.sessionToken,
    requestIdentity.generation, workspaceID, projectID, sharedScope, initialProjectFoundationRevisions.get(String(projectID)) || 0]);
  const existing = initialProjectFoundationReads.get(key);
  if (existing) return existing;
  const request = Promise.resolve().then(() => {
    requireCurrentAccountRequest(requestIdentity);
    if (workspaceID !== activeWorkspaceID) throw accountContextChangedError();
    return postResearch(sharedScope ? "/organizations/projects/snapshot" : "/projects/foundation/state", { projectID });
  }).then((payload) => {
    requireCurrentAccountRequest(requestIdentity);
    if (workspaceID !== activeWorkspaceID) throw accountContextChangedError();
    return sharedScope ? payload.project : payload;
  }).finally(() => {
    if (initialProjectFoundationReads.get(key) === request) initialProjectFoundationReads.delete(key);
  });
  initialProjectFoundationReads.set(key, request);
  return request;
}

async function renderSavedFolderContext(panel, savedInstance, paneID, folders) {
  const previousContext = panel.querySelector(".saved-folder-context");
  const inlineFilters = panel.querySelector(".saved-inline-filters");
  const planUsage = panel.querySelector(".saved-plan-usage");
  const savedContent = panel.querySelector(".saved-content");
  const folder = activeFolderRecords(folders).find((item) =>
    projectRecordID(item) === String(savedInstance.selectedFolderID || "")
  ) || null;
  const projectsSection = panel.querySelector(".saved-projects-section");
  projectsSection.hidden = true;
  if (!folder) {
    inlineFilters.hidden = !savedInstance.organizeUnassigned;
    savedContent.hidden = !savedInstance.organizeUnassigned;
    previousContext?.remove();
    panel.querySelector(".saved-unassigned-notice")?.remove();
    if (savedInstance.organizeUnassigned) {
      const context = document.createElement("section");
      context.className = "saved-folder-context is-unassigned-context";
      const savedSection = document.createElement("section");
      savedSection.className = "saved-inbox";
      const { heading, title } = createSavedEvidenceHeading();
      title.remove();
      heading.setAttribute("aria-label", "Unassigned save actions");
      savedSection.append(heading, inlineFilters, planUsage, savedContent);
      const count = document.createElement("span");
      count.className = "saved-inbox-count";
      const order = document.createElement("span");
      order.className = "saved-inbox-order";
      order.textContent = "Newest first";
      heading.prepend(count, order);
      context.append(savedSection);
      projectsSection.after(context);
    } else {
      projectsSection.after(inlineFilters, planUsage, savedContent);
    }
    if (savedInstance.selectedFolderID) savedInstance.selectedFolderID = "";
    panel.classList.remove("has-selected-project-folder");
    panel.style.removeProperty("--project-color");
    return null;
  }

  const context = document.createElement("section");
  context.className = `saved-folder-context is-${folderType(folder)}`;
  inlineFilters.hidden = false;
  savedContent.hidden = false;
  if (folderIsProject(folder)) {
    context.style.setProperty("--project-color", projectColor(folder));
  }

  if (folderIsProject(folder)) {
    const identity = projectIdentity(folder);
    context.dataset.projectId = projectDetailKey(identity);
    const controls = document.createElement("nav");
    controls.className = "saved-folder-controls saved-project-tool-controls";
    controls.setAttribute("aria-label", `${identity.name} tools`);
    [
      ...(releaseSurfaceVisibility.coordination
        ? [["Coordination", "project-coordination-button", projectHasOpenCoordination, openProjectCoordination, closeProjectCoordination]]
        : [])
    ].forEach(([label, className, isOpen, openTool, closeTool]) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = className;
      button.textContent = label;
      button.setAttribute("aria-pressed", String(isOpen(identity)));
      button.addEventListener("click", async () => {
        const previousHostPaneID = state.projectHostPaneID;
        state.projectHostPaneID = paneID;
        const changed = isOpen(identity)
          ? await closeTool(identity)
          : await openTool(identity);
        if (changed === false) {
          if (state.projectHostPaneID === paneID) state.projectHostPaneID = previousHostPaneID;
          return;
        }
        button.setAttribute("aria-pressed", String(isOpen(identity)));
      });
      controls.append(button);
    });
    if (controls.childElementCount) context.append(controls);

    const savedSection = document.createElement("section");
    savedSection.className = "project-studio-section saved-project-evidence-section";
    populateSavedEvidenceSection(
      savedSection,
      savedInstance,
      folder,
      inlineFilters,
      planUsage,
      savedContent
    );
    context.append(savedSection);
  } else {
    const controls = document.createElement("div");
    controls.className = "saved-folder-controls";
    const notes = document.createElement("span");
    notes.textContent = folder.description || "Add notes explaining how this reference collection should be used.";
    notes.className = "saved-reference-capabilities";
    const edit = document.createElement("button");
    edit.type = "button";
    edit.textContent = "Edit notes";
    edit.addEventListener("click", () => showProjectCreateSheet(panel, folder));
    const convert = document.createElement("button");
    convert.type = "button";
    convert.textContent = "Convert to Project";
    convert.disabled = !hasCapability("projects");
    if (convert.disabled) convert.title = "Projects require Pro";
    convert.addEventListener("click", async () => {
      const confirmed = await openWebWarning({
        title: "Convert to Project?",
        message: "This keeps every saved section, note, and collection association, then adds Notebook, Report, and Project history.",
        confirmLabel: "Convert",
        container: panel
      });
      if (!confirmed) return;
      const converted = await updateProjectFolder(folder, {
        name: folder.name || folder.title,
        address: folder.address || "",
        description: folder.description || "",
        color: projectColor(folder),
        folderType: "project"
      });
      if (converted === false) return;
      await transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
    });
    controls.append(notes, edit, convert);
    context.append(controls);

    const savedSection = document.createElement("section");
    savedSection.className = "project-studio-section saved-project-evidence-section";
    populateSavedEvidenceSection(
      savedSection,
      savedInstance,
      projectRecordID(folder),
      inlineFilters,
      planUsage,
      savedContent
    );
    context.append(savedSection);
  }

  if (folderIsProject(folder)) {
    panel.style.setProperty("--project-color", projectColor(folder));
    panel.classList.add("has-selected-project-folder");
  } else {
    panel.classList.remove("has-selected-project-folder");
    panel.style.removeProperty("--project-color");
  }
  if (previousContext?.isConnected) previousContext.replaceWith(context);
  else projectsSection.after(context);
  if (folderIsProject(folder)) syncProjectToolButtonStates(projectIdentity(folder));
  return folder;
}

async function reconcileProjectStudioWithSavedFolders(folders) {
  if (projectStudioFolderReconcilePromise) return projectStudioFolderReconcilePromise;
  projectStudioFolderReconcilePromise = (async () => {
    const activeFolders = activeFolderRecords(folders);
    const previousHostPaneID = state.projectHostPaneID;
    const host = projectHostSavedInstance(activeFolders);
    const selectedFolder = host
      ? activeFolders.find((folder) =>
          projectRecordID(folder) === String(host.selectedFolderID || "")
        ) || null
      : null;
    const expectedWorkspaceID = activeWorkspaceID;
    const expectedHostPaneID = state.projectHostPaneID;
    const expectedSelectedFolderID = String(host?.selectedFolderID || "");
    const current = openProjectDetails()[0] || null;
    let changed = state.projectHostPaneID !== previousHostPaneID;

    if (selectedFolder && folderIsProject(selectedFolder) && (!current || !projectDetailMatches(selectedFolder, current))) {
      const outcome = { value: "" };
      const activated = await activateProjectStudio(selectedFolder, {
        focusSaved: false,
        transition: false,
        outcome
      });
      if (activated) {
        changed = true;
      } else if (
        outcome.value === "cancelled" &&
        activeWorkspaceID === expectedWorkspaceID &&
        state.projectHostPaneID === expectedHostPaneID &&
        String(host?.selectedFolderID || "") === expectedSelectedFolderID
      ) {
        const live = openProjectDetails()[0] || null;
        const liveFolder = live
          ? activeFolders.find((folder) => folderIsProject(folder) && projectDetailMatches(folder, live))
          : null;
        const restoredFolderID = liveFolder ? projectRecordID(liveFolder) : "";
        if (host && host.selectedFolderID !== restoredFolderID) {
          host.selectedFolderID = restoredFolderID;
          changed = true;
        }
      }
    } else if (selectedFolder && !folderIsProject(selectedFolder) && current) {
      const outcome = { value: "" };
      const deactivated = await deactivateProjectStudio(current, { transition: false, outcome });
      if (deactivated) {
        changed = true;
      } else if (
        outcome.value === "cancelled" &&
        activeWorkspaceID === expectedWorkspaceID &&
        state.projectHostPaneID === expectedHostPaneID &&
        String(host?.selectedFolderID || "") === expectedSelectedFolderID
      ) {
        const live = openProjectDetails()[0] || null;
        const liveFolder = live
          ? activeFolders.find((folder) => folderIsProject(folder) && projectDetailMatches(folder, live))
          : null;
        const restoredFolderID = liveFolder ? projectRecordID(liveFolder) : projectRecordID(selectedFolder);
        if (host && host.selectedFolderID !== restoredFolderID) {
          host.selectedFolderID = restoredFolderID;
          changed = true;
        }
      }
    } else if (!selectedFolder && current) {
      const currentFolder = activeFolders.find((folder) => projectDetailMatches(folder, current));
      if (currentFolder && host) {
        host.selectedFolderID = projectRecordID(currentFolder);
        changed = true;
      }
    } else if (!current) {
      const hadOrphanTools = [
        ...openNotebooks(),
        ...openReportDrafts(),
        ...openCoordinations(),
        ...openCoordinationThreads()
      ].length > 0 || state.projectContextOpen || state.projectFactsOpen;
      if (hadOrphanTools) {
        state.projectContextOpen = false;
        state.projectFactsOpen = false;
        projectInformationMounts.clear();
        state.workboards = genericWorkboardIsOpen() ? [genericWorkboardIdentity] : [];
        state.notebooks = [];
        state.reportDrafts = [];
        state.coordinations = [];
        state.coordinationThreads = [];
        changed = true;
      }
    }

    if (changed) {
      saveWorkspaceState();
      requestAnimationFrame(() => {
        void transitionWorkspace("utility");
      });
    }
    return changed;
  })();
  try {
    return await projectStudioFolderReconcilePromise;
  } finally {
    projectStudioFolderReconcilePromise = null;
  }
}

function renderUnassignedEvidenceNotice(panel, savedInstance, paneID, savedItems, projectSections, projects, selectedFolder, annotations = []) {
  panel.querySelector(".saved-unassigned-notice")?.remove();
  const unassignedIDs = unassignedSavedEvidenceKeys(savedItems, projectSections, projects, annotations);
  return selectedFolder ? new Set() : unassignedIDs;
}

function unassignedSavedEvidenceKeys(savedItems, projectSections, projects = [], annotations = []) {
  const projectRecords = activeProjectRecords(projects || []);
  const linkedSectionIDs = new Set((projectSections || [])
    .filter((item) => projectRecords.some((project) => projectSectionBelongsToProject(item, project)))
    .map((item) => savedEvidenceKey(item)));
  return new Set([...(savedItems || []), ...(annotations || [])]
    .filter((item) => item && !item.deletedAt)
    .filter((item) => String(item.sectionID || item.savedSectionID || item.itemID || "").trim())
    .map((item) => savedEvidenceKey(item))
    .filter((sectionID) => !linkedSectionIDs.has(sectionID)));
}

function savedEvidenceMatchesQuery(item, query) {
  const normalizedQuery = String(query || "").trim().toLocaleLowerCase();
  if (!normalizedQuery) return true;
  const prefix = item.codePrefix || item.code || "BC";
  return [
    prefix,
    codeDisplayLabel(prefix),
    item.chapterNumber,
    item.chapterID,
    item.chapterTitle,
    item.sectionNumber,
    item.sectionID,
    item.title,
    item.body,
    item.bodyText,
    item.savedContentComparisonText,
    item.previewText,
    item.text,
    item.excerpt,
    item.noteBody
  ].some((value) => String(value || "").toLocaleLowerCase().includes(normalizedQuery));
}

async function resolveSavedSearchPage(options = {}) {
  const candidates = Array.isArray(options.candidates) ? options.candidates : [];
  const limit = Math.max(0, Math.trunc(Number(options.limit) || 0));
  const batchSize = Math.max(1, Math.trunc(Number(options.batchSize) || 1));
  const hydrateItems = options.hydrateItems || (async (items) => items);
  const matchesItem = options.matchesItem || (() => true);
  const normalizeMatches = options.normalizeMatches || ((items) => items);
  const shouldContinue = options.shouldContinue || (() => true);
  const targetCount = limit + 1;
  const matchingItems = [];
  let normalizedMatches = [];
  let scannedCount = 0;

  while (scannedCount < candidates.length && normalizedMatches.length < targetCount) {
    if (!shouldContinue()) {
      return { items: [], hasMore: false, scannedCount, exhausted: false, cancelled: true };
    }
    const batch = candidates.slice(scannedCount, scannedCount + Math.min(batchSize, targetCount - normalizedMatches.length));
    scannedCount += batch.length;
    const hydratedBatch = await hydrateItems(batch);
    if (!shouldContinue()) {
      return { items: [], hasMore: false, scannedCount, exhausted: false, cancelled: true };
    }
    matchingItems.push(...hydratedBatch.filter(matchesItem));
    normalizedMatches = normalizeMatches(matchingItems);
  }

  return {
    items: normalizedMatches.slice(0, limit),
    hasMore: normalizedMatches.length > limit,
    scannedCount,
    exhausted: scannedCount >= candidates.length,
    cancelled: false
  };
}

function animateSavedMembershipUpdate(content, previousHeight) {
  if (
    !content ||
    !Number.isFinite(previousHeight) ||
    previousHeight <= 0 ||
    window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
  ) return;
  const nextHeight = content.getBoundingClientRect().height;
  if (!Number.isFinite(nextHeight) || Math.abs(nextHeight - previousHeight) < 1) return;
  content.getAnimations?.().forEach((animation) => animation.cancel());
  content.animate([
    { height: `${previousHeight}px`, overflow: "clip" },
    { height: `${nextHeight}px`, overflow: "clip" }
  ], {
    duration: 420,
    easing: "cubic-bezier(0.22, 1, 0.36, 1)"
  });
}

async function performSavedPanelHydration(panel, savedInstance, paneID, options = {}) {
  const content = panel.querySelector(".saved-content");
  // Initial mounting follows the workspace access gate's completed sync.
  // Explicit refreshes retain their fresh pull instead of reusing this snapshot.
  const data = await (options.reuseVerifiedSync
    ? ensureSyncedContentForRender()
    : loadSyncedContent());
  if (!panel.isConnected) return;
  const summary = currentContentSummary();
  const workspaceProjects = await projectsWithOrganizationAccess(summary.projects || []);
  if (!panel.isConnected) return;
  if (options.reconcileProjectStudio !== false) {
    await reconcileProjectStudioWithSavedFolders(workspaceProjects);
  }
  if (!panel.isConnected) return;
  const preserveProjectChrome = options.preserveProjectChrome === true;
  const selectedFolder = preserveProjectChrome
    ? workspaceProjects.find((project) =>
        projectRecordID(project) === String(savedInstance.selectedFolderID || "")
      ) || null
    : await renderSavedFolderContext(panel, savedInstance, paneID, workspaceProjects);
  if (!panel.isConnected) return;
  const annotatedItems = consolidatedSavedAnnotations(summary.annotations || []);
  if (preserveProjectChrome) {
    panel.querySelectorAll(".saved-project-tile[data-project-id]").forEach((tile) => {
      const project = workspaceProjects.find((item) => projectRecordID(item) === tile.dataset.projectId);
      if (!project) return;
      const count = projectEvidenceCount(summary.projectSections || [], project);
      const countLabel = tile.querySelector(".saved-project-count");
      if (!countLabel) return;
      countLabel.textContent = String(count);
      countLabel.title = count === 1 ? "1 saved section" : `${count} saved sections`;
      countLabel.setAttribute("aria-label", countLabel.title);
    });
    const unassignedCountLabel = panel.querySelector(".is-unassigned-saved .saved-project-count");
    if (unassignedCountLabel) {
      const unassignedCount = unassignedSavedEvidenceKeys(
        summary.savedItems || [],
        summary.projectSections || [],
        workspaceProjects,
        annotatedItems
      ).size;
      unassignedCountLabel.textContent = String(unassignedCount);
      unassignedCountLabel.title = unassignedCount === 1
        ? "1 unassigned save"
        : `${unassignedCount} unassigned saves`;
      unassignedCountLabel.setAttribute("aria-label", unassignedCountLabel.title);
    }
  } else {
    renderSavedProjects(
      panel,
      savedInstance,
      paneID,
      workspaceProjects,
      summary.projectSections || [],
      summary.savedItems || [],
      annotatedItems
    );
  }
  const showingUnassigned = !selectedFolder && savedInstance.organizeUnassigned;
  if (!selectedFolder && !showingUnassigned) return;

  if (data.status === "disconnected" && summary.savedItems.length === 0 && summary.annotations.length === 0) {
    clear(content);
    appendEmptySaved(content, "Sign in to sync", "Open Account and sign in to show synced bookmarks and notes.");
    return;
  }
  if (data.status === "error" && summary.savedItems.length === 0 && summary.annotations.length === 0) {
    clear(content);
    appendEmptySaved(content, "Sync error", data.error || "Could not load saved content.");
    return;
  }

  const { savedItems } = summary;
  const combinedItems = mergeSavedColumnItems(savedItems, annotatedItems);
  const unassignedSectionIDs = renderUnassignedEvidenceNotice(
    panel,
    savedInstance,
    paneID,
    savedItems,
    summary.projectSections || [],
    workspaceProjects,
    selectedFolder,
    annotatedItems
  );
  const hydratedItemPromises = new WeakMap();
  const hydrateItems = async (items) => {
    const missingItems = items.filter((item) => !hydratedItemPromises.has(item));
    if (missingItems.length) {
      const hydration = hydrateSavedColumnItems(missingItems);
      missingItems.forEach((item, index) => {
        hydratedItemPromises.set(item, hydration.then((resolved) => resolved[index]));
      });
    }
    return Promise.all(items.map((item) => hydratedItemPromises.get(item)));
  };
  const selectedFolderEvidenceKeys = selectedFolder
    ? new Set((summary.projectSections || [])
        .filter((link) => projectSectionBelongsToProject(link, selectedFolder))
        .map((link) => savedEvidenceKey(link)))
    : null;
  const selectedFolderSectionEvidenceKeys = selectedFolder
    ? new Set((summary.projectSections || [])
        .filter((link) =>
          projectSectionBelongsToProject(link, selectedFolder) &&
          !normalizeAnnotationBlockID(link.blockID || link.anchorID || link.contentBlockID)
        )
        .map((link) => savedEvidenceKey(link)))
    : null;
  const projectNamesForItem = (item) => {
    const evidenceKey = savedEvidenceKey(item);
    return workspaceProjects
      .filter((project) => (summary.projectSections || []).some((link) =>
        savedEvidenceKey(link) === evidenceKey && projectSectionBelongsToProject(link, project)
      ))
      .map((project) => projectIdentity(project).name)
      .filter(Boolean);
  };
  const folderHydrationItems = selectedFolder && !savedInstance.showAllSaved
    ? combinedItems
        .filter((item) => selectedFolderEvidenceKeys.has(savedEvidenceKey(item)))
        .map((item) =>
          item.savedColumnKind === "bookmark" &&
          !normalizeAnnotationBlockID(item.blockID) &&
          selectedFolderSectionEvidenceKeys.has(savedEvidenceKey(item))
          ? { ...item, projectSavedScope: "section" }
          : item
        )
    : combinedItems;
  // Keep the complete collection for filtering and selection, but load source
  // bodies only for the visible page. A Project may contain thousands of saves.
  // Older saves may lack the canonical numbers needed to order all pages. Fill
  // those exceptions before choosing a page so a late row cannot sort first.
  const missingSortMetadata = selectedFolder && !showingUnassigned
    ? folderHydrationItems.filter((item) => !item.chapterNumber || !item.sectionNumber)
    : [];
  const resolvedSortMetadata = await hydrateItems(missingSortMetadata);
  if (!panel.isConnected) return;
  const resolvedSortItems = new Map(missingSortMetadata.map((item, index) => [item, resolvedSortMetadata[index]]));
  resolvedSortMetadata.forEach((item) => hydratedItemPromises.set(item, Promise.resolve(item)));
  const savedCandidates = sortSavedItems(folderHydrationItems.map((item) => resolvedSortItems.get(item) || item),
    showingUnassigned ? "recentlySaved" : "codeOrder");
  const removableSavedItems = selectedFolder && !savedInstance.showAllSaved
    ? folderHydrationItems.filter((item) => selectedFolderEvidenceKeys.has(savedEvidenceKey(item)))
    : showingUnassigned ? combinedItems.filter((item) => unassignedSectionIDs.has(savedEvidenceKey(item)))
    : !workspaceProject() ? combinedItems : [];
  const selectionController = removableSavedItems.length
    ? createSavedBulkSelectionController(panel, removableSavedItems, {
        reportProject: selectedFolder && folderIsProject(selectedFolder) ? selectedFolder : null,
        allowProjectAssignment: showingUnassigned || !workspaceProject(),
        inbox: showingUnassigned,
        removeConfirmationDetail: selectedFolder
          ? "Evidence linked to another Project will remain there. Items with no remaining destination will also have their saved record deleted. Notes and source history are not reassigned."
          : "This deletes the selected saved records.",
        removeBatchAction: (items, onProgress) => deleteSavedEvidenceBatch(items, selectedFolder, onProgress),
        removeAction: (item, removalOptions) => selectedFolder ? unlinkEvidenceFromFolder(
          selectedFolder,
          (summary.projectSections || []).find((link) =>
            savedEvidenceKey(link) === savedEvidenceKey(item) &&
            projectSectionBelongsToProject(link, selectedFolder)
          ) || item,
          panel,
          { refreshPanes: false, confirmedFinalDestinationRemoval: removalOptions?.confirmedFinalDestinationRemoval === true }
        ) : persistSectionBookmark(item, false, { refreshSavedPanes: false })
      })
    : null;
  const savedEvidenceSelectToggle = panel.querySelector(".saved-evidence-select-toggle");
  if (savedEvidenceSelectToggle) savedEvidenceSelectToggle.hidden = !selectionController;
  let allSavedLimit = savedItemsPageSize;
  let savedSearchContentMinHeight = 0;
  let previousViewSignature = "";
  let viewGeneration = 0;
  const applySavedView = async (viewOptions = {}) => {
    const generation = ++viewGeneration;
    const query = savedInstance.folderQuery.trim();
    const searchActive = Boolean(query);
    const scrollContainer = panel.querySelector(".saved-column-scroll");
    const preservedScrollTop = scrollContainer?.scrollTop || 0;
    if (searchActive) {
      if (!savedSearchContentMinHeight) {
        savedSearchContentMinHeight = Math.ceil(content.getBoundingClientRect().height);
      }
      if (savedSearchContentMinHeight > 0) {
        content.style.minHeight = `${savedSearchContentMinHeight}px`;
      }
    } else {
      savedSearchContentMinHeight = 0;
      content.style.removeProperty("min-height");
    }
    const viewSignature = [
      query.toLocaleLowerCase(),
      String(savedInstance.organizeUnassigned),
      String(savedInstance.showAllSaved),
      selectedFolder ? projectRecordID(selectedFolder) : "all"
    ].join(":");
    if (viewSignature !== previousViewSignature) {
      allSavedLimit = savedItemsPageSize;
      previousViewSignature = viewSignature;
    }
    const matchesView = (item, options = {}) => {
      const itemSectionID = savedEvidenceKey(item);
      const folderMatches = !selectedFolder || savedInstance.showAllSaved || selectedFolderEvidenceKeys.has(itemSectionID);
      const queryMatches = options.ignoreQuery || savedEvidenceMatchesQuery(item, query);
      const organizationMatches = !savedInstance.organizeUnassigned || unassignedSectionIDs.has(itemSectionID);
      return folderMatches && queryMatches && organizationMatches;
    };
    const page = await resolveSavedSearchPage({
      candidates: savedCandidates.filter((item) => matchesView(item, { ignoreQuery: true })),
      limit: allSavedLimit,
      batchSize: savedItemsPageSize,
      hydrateItems,
      matchesItem: (item) => matchesView(item),
      normalizeMatches: mergeEquivalentSavedColumnRows,
      shouldContinue: () => generation === viewGeneration && panel.isConnected
    });
    if (page.cancelled) return;
    const resolvedItems = page.items;
    const hasMore = page.hasMore;
    if (generation !== viewGeneration || !panel.isConnected) return;
    const filteredItems = resolvedItems.filter((item) => matchesView(item));
    const orderedItems = sortSavedItems(filteredItems, showingUnassigned ? "recentlySaved" : "codeOrder");
    const inboxCount = panel.querySelector(".saved-inbox-count");
    if (inboxCount) inboxCount.textContent = `${unassignedSectionIDs.size} ${unassignedSectionIDs.size === 1 ? "save" : "saves"}`;
    const previousContentHeight = options.animateContentUpdate
      ? content.getBoundingClientRect().height
      : 0;
    const restoreExpansionFocus = viewOptions.focusOrigin && document.activeElement === viewOptions.focusOrigin;
    clear(content);
    content.setAttribute("aria-busy", "false");
    if (orderedItems.length > 0) {
      selectionController?.beginRender();
      const commonRenderOptions = {
        inbox: showingUnassigned,
        showChapterHeaders: !showingUnassigned,
        preserveOrder: true,
        collapsedCodePrefixes: searchActive ? [] : savedInstance.collapsedCodePrefixes,
        onCodeGroupToggle: (prefix, collapsed) => {
          if (searchActive) return;
          const collapsedPrefixes = new Set(savedInstance.collapsedCodePrefixes);
          if (collapsed) collapsedPrefixes.add(prefix);
          else collapsedPrefixes.delete(prefix);
          savedInstance.collapsedCodePrefixes = Array.from(collapsedPrefixes);
          saveWorkspaceState();
        },
        removableSavedItems: Boolean(selectionController),
        selectionController,
        projectNamesForItem,
        showProjectContext: !selectedFolder && !savedInstance.organizeUnassigned,
        reportProject: selectedFolder && folderIsProject(selectedFolder) ? selectedFolder : null,
        researchProjectID: selectedFolder && folderIsProject(selectedFolder) ? projectDetailKey(selectedFolder) : "",
        animateSavedItemRemoval: animateSavedRowRemoval,
        onSavedItemRemoved: async () => {
          await performSavedPanelHydration(panel, savedInstance, paneID, {
            preserveProjectChrome: true,
            reconcileProjectStudio: false
          });
        }
      };
      if (!selectedFolder && !searchActive && !savedInstance.organizeUnassigned) {
        const unassignedItems = orderedItems.filter((item) => unassignedSectionIDs.has(savedEvidenceKey(item)));
        const assignedItems = orderedItems.filter((item) => !unassignedSectionIDs.has(savedEvidenceKey(item)));
        if (unassignedItems.length) {
          appendSectionLabel(content, "Unassigned saves");
          renderSavedItemsByCode(content, unassignedItems, paneID, commonRenderOptions);
        }
        if (assignedItems.length) {
          appendSectionLabel(content, unassignedItems.length ? "Assigned" : "Saved");
          renderSavedItemsByCode(content, assignedItems, paneID, commonRenderOptions);
        }
      } else {
        renderSavedItemsByCode(content, orderedItems, paneID, commonRenderOptions);
      }
    } else if (selectedFolder && resolvedItems.length === 0 && !searchActive) {
      // Keep an empty destination blank beneath its Saved Evidence heading.
    } else if (savedInstance.organizeUnassigned && !selectedFolder && !searchActive) {
      appendEmptySaved(
        content,
        "No unassigned saves",
        "Saved passages and notes that are not assigned to a Project appear here."
      );
    } else if (combinedItems.length > 0) {
      const viewingUnassigned = savedInstance.organizeUnassigned && !selectedFolder;
      appendEmptySaved(
        content,
        viewingUnassigned ? "No unassigned saves match" : "No saved items match",
        viewingUnassigned
          ? "Clear the search to see every unassigned save."
          : selectedFolder
            ? "Try another search or code book, or add evidence to this destination."
            : "Try another code book."
      );
    } else {
      appendMutedRow(content, "No saved sections", "");
    }
    if (hasMore) {
      const footer = document.createElement("section");
      footer.className = "saved-load-more";
      const status = document.createElement("p");
      status.textContent = `${orderedItems.length.toLocaleString()} shown`;
      const button = document.createElement("button");
      button.type = "button";
      button.className = "saved-load-more-button";
      button.textContent = "Show more";
      button.addEventListener("click", () => {
        allSavedLimit += savedItemsPageSize;
        content.setAttribute("aria-busy", "true");
        void applySavedView({ focusOrigin: button, previousEvidenceKeys: new Set(orderedItems.map((item) => savedEvidenceKey(item))) });
      });
      footer.append(status, button);
      content.append(footer);
    }
    if (options.animateContentUpdate) {
      animateSavedMembershipUpdate(content, previousContentHeight);
    }
    if (scrollContainer) scrollContainer.scrollTop = preservedScrollTop;
    if (restoreExpansionFocus) {
      const nextRow = Array.from(content.querySelectorAll(".saved-section-row")).find((row) =>
        !viewOptions.previousEvidenceKeys.has(row.dataset.savedEvidenceKey) && !row.closest(".is-collapsed"));
      const focusTarget = nextRow?.querySelector(".saved-section-open") || content.querySelector(".saved-load-more-button") ||
        content.querySelector(".saved-code-toggle");
      focusTarget?.focus({ preventScroll: true });
    }
  };
  panel.__applySavedView = applySavedView;
  renderSavedFilters(panel, savedInstance, folderHydrationItems, () => {
    content.setAttribute("aria-busy", "true");
    void applySavedView();
  });
  await applySavedView();
  panel.__refreshProjectMembership = () => refreshSavedPanelInPlace(paneID, {
    reconcileProjectStudio: false,
    preserveProjectChrome: true,
    animateContentUpdate: true
  });
}

function hydrateSavedPanel(panel, savedInstance, paneID, options = {}) {
  const previousHydration = panel.__savedHydrationPromise || Promise.resolve();
  const hydration = previousHydration
    .catch(() => {})
    .then(() => performSavedPanelHydration(panel, savedInstance, paneID, options));
  panel.__savedHydrationPromise = hydration;
  return hydration.then((value) => {
    panel.dataset.savedHydrated = "true";
    return value;
  }).finally(() => {
    if (panel.__savedHydrationPromise === hydration) {
      delete panel.__savedHydrationPromise;
    }
  });
}

async function refreshSavedPanelInPlace(paneID, options = {}) {
  const panel = track.querySelector(
    `.saved-panel[data-pane-id="${CSS.escape(paneID)}"]`
  );
  const savedInstance = (state.utilityInstances || []).find((instance) =>
    instance.key === "saved" && paneIDForUtilityInstance(instance) === paneID
  );
  if (!panel || !savedInstance) return false;
  const scrollContainer = panel.querySelector(".saved-column-scroll");
  const scrollTop = scrollContainer?.scrollTop || 0;
  await hydrateSavedPanel(panel, savedInstance, paneID, options);
  if (!panel.isConnected) return false;
  if (scrollContainer) scrollContainer.scrollTop = scrollTop;
  return true;
}

function projectTransitionHubMatches(entry, projectID) {
  const account = activeAccount();
  return Boolean(
    entry &&
    account &&
    entry.projectID === String(projectID || "") &&
    entry.accountUserID === account.userID &&
    entry.sessionToken === account.sessionToken &&
    entry.workspaceID === activeWorkspaceID
  );
}

async function projectTransitionHubPayload(projectID) {
  const entry = projectTransitionHubEntry;
  if (!projectTransitionHubMatches(entry, projectID)) return null;
  const payload = await entry.promise;
  if (!projectTransitionHubMatches(entry, projectID)) return null;
  return String(payload?.projectID || "") === String(projectID || "") ? payload : null;
}

function beginProjectTransitionHub(project) {
  const account = activeAccount();
  const projectID = project ? projectDetailKey(projectIdentity(project)) : "";
  if (!account || !projectID || (!projectHasOpenNotebook(project) && !projectHasOpenReportDraft(project))) {
    return null;
  }
  const entry = {
    accountUserID: account.userID,
    sessionToken: account.sessionToken,
    workspaceID: activeWorkspaceID,
    projectID,
    promise: postResearch("/projects/hub/bootstrap", { projectID }).catch(() => null)
  };
  projectTransitionHubEntry = entry;
  return entry;
}

async function settleSavedPanelAfterProjectTransition(paneID, previousPanel) {
  if (!await whenWorkspacePaneReady(paneID)) return false;
  const panel = track.querySelector(
    `.saved-panel[data-pane-id="${CSS.escape(paneID)}"]`
  );
  if (!panel) return false;
  if (panel === previousPanel) return refreshSavedPanelInPlace(paneID);
  await new Promise((resolve) => requestAnimationFrame(resolve));
  const hydration = panel.__savedHydrationPromise;
  if (hydration) await hydration;
  else if (panel.dataset.savedHydrated !== "true") {
    const savedInstance = (state.utilityInstances || []).find((instance) =>
      instance.key === "saved" && paneIDForUtilityInstance(instance) === paneID
    );
    if (!savedInstance) return false;
    await hydrateSavedPanel(panel, savedInstance, paneID);
  }
  return panel.isConnected;
}

async function transitionProjectSelection(paneID) {
  const previousPanel = track.querySelector(
    `.saved-panel[data-pane-id="${CSS.escape(paneID)}"]`
  );
  const entry = beginProjectTransitionHub(openProjectDetails()[0] || null);
  try {
    await transitionWorkspace("utility");
    if (await settleSavedPanelAfterProjectTransition(paneID, previousPanel)) return;
    await transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
  } finally {
    if (projectTransitionHubEntry === entry) projectTransitionHubEntry = null;
    startProjectArtifactCheckpointLoop({ immediate: true });
  }
}

function projectSelectionControllerKey(workspaceID, paneID) {
  return `${String(workspaceID || "")}::${String(paneID || "")}`;
}

function projectSelectionInstance(controller) {
  if (activeWorkspaceID !== controller.workspaceID) return null;
  return (state.utilityInstances || []).find((instance) =>
    instance.id === controller.instanceID &&
    instance.key === "saved" &&
    paneIDForUtilityInstance(instance) === controller.paneID
  ) || null;
}

function projectSelectionIntentTargetsProject(intent, project) {
  return Boolean(
    intent?.kind === "project" &&
    intent.project &&
    project &&
    projectDetailMatches(intent.project, project)
  );
}

function takeLatestProjectSelectionIntent(controller, fallbackIntent) {
  const intent = controller.pending || fallbackIntent;
  controller.pending = null;
  controller.activeIntent = intent;
  syncProjectSelectionControllerUI(controller);
  return intent;
}

function syncProjectSelectionControllerUI(controller) {
  if (activeWorkspaceID !== controller.workspaceID) return;
  const panel = track.querySelector(
    `.saved-panel[data-pane-id="${CSS.escape(controller.paneID)}"]`
  );
  if (!panel) return;
  const intent = controller.pending || controller.activeIntent;
  const busy = Boolean(controller.running || intent);
  panel.classList.toggle("is-project-selection-busy", busy);
  panel.querySelectorAll(".saved-project-tile").forEach((tile) => {
    tile.classList.remove("is-opening");
    tile.removeAttribute("aria-busy");
    delete tile.dataset.opening;
  });
  if (!busy || !intent) return;
  let tile = null;
  if (intent.kind === "project" && intent.folderID) {
    tile = panel.querySelector(
      `.saved-project-tile[data-project-id="${CSS.escape(String(intent.folderID))}"]`
    );
  } else if (intent.kind === "unassigned") {
    tile = panel.querySelector(".saved-project-tile.is-unassigned-saved");
  } else {
    tile = panel.querySelector(".saved-project-tile.is-selected");
  }
  if (!tile) return;
  tile.dataset.opening = "true";
  tile.classList.add("is-opening");
  tile.setAttribute("aria-busy", "true");
}

function renderProjectSelectionImmediately(controller, savedInstance, intent) {
  if (activeWorkspaceID !== controller.workspaceID) return false;
  const panel = track.querySelector(
    `.saved-panel[data-pane-id="${CSS.escape(controller.paneID)}"]`
  );
  if (!panel?.isConnected) return false;

  const selectedProjectID = intent.kind === "project" ? String(intent.folderID || "") : "";
  panel.querySelectorAll(".saved-project-tile").forEach((tile) => {
    const selected = intent.kind === "unassigned"
      ? tile.classList.contains("is-unassigned-saved")
      : Boolean(selectedProjectID && tile.dataset.projectId === selectedProjectID);
    tile.classList.toggle("is-selected", selected);
    if (selected) tile.setAttribute("aria-current", "true");
    else tile.removeAttribute("aria-current");
  });

  const folders = intent.kind === "project" && intent.project ? [intent.project] : [];
  void renderSavedFolderContext(panel, savedInstance, controller.paneID, folders);
  return true;
}

async function confirmLatestProjectSelectionIntent(controller, requestedIntent) {
  let intent = takeLatestProjectSelectionIntent(controller, requestedIntent);
  while (projectSelectionInstance(controller)) {
    const current = openProjectDetails()[0] || null;
    if (!current || projectSelectionIntentTargetsProject(intent, current)) {
      return { confirmed: true, intent };
    }
    if (!(await confirmNotebookDiscard(current))) {
      return { confirmed: false, intent };
    }
    if (!projectSelectionInstance(controller)) return { confirmed: false, stale: true, intent };
    if (!openProjectDetails().some((project) => projectDetailMatches(project, current))) {
      intent = takeLatestProjectSelectionIntent(controller, intent);
      continue;
    }
    intent = takeLatestProjectSelectionIntent(controller, intent);
    if (projectSelectionIntentTargetsProject(intent, current)) {
      return { confirmed: true, intent };
    }
    if (!(await confirmReportDraftDiscard(current))) {
      return { confirmed: false, intent };
    }
    if (!projectSelectionInstance(controller)) return { confirmed: false, stale: true, intent };
    if (!openProjectDetails().some((project) => projectDetailMatches(project, current))) {
      intent = takeLatestProjectSelectionIntent(controller, intent);
      continue;
    }
    return {
      confirmed: true,
      intent: takeLatestProjectSelectionIntent(controller, intent)
    };
  }
  return { confirmed: false, stale: true, intent };
}

async function applyProjectSelectionIntent(controller, requestedIntent) {
  const instance = projectSelectionInstance(controller);
  if (!instance) return false;
  const intent = takeLatestProjectSelectionIntent(controller, requestedIntent);
  if (intent.kind === "project") {
    if (!intent.project || !folderIsProject(intent.project)) return false;
    const activated = await activateProjectStudio(intent.project, {
      sourcePaneID: controller.paneID,
      focusSaved: false,
      transition: false,
      skipDiscardConfirmation: true
    });
    if (!activated) return false;
  } else {
    const deactivated = await deactivateProjectStudio(openProjectDetails()[0], {
      transition: false,
      skipDiscardConfirmation: true
    });
    if (!deactivated) return false;
  }
  const liveInstance = projectSelectionInstance(controller);
  if (!liveInstance) return false;
  state.projectHostPaneID = controller.paneID;
  liveInstance.selectedFolderID = intent.kind === "project" ? intent.folderID : "";
  liveInstance.organizeUnassigned = intent.kind === "unassigned";
  liveInstance.showAllSaved = false;
  liveInstance.folderQuery = "";
  liveInstance.evidenceSearchOpen = false;
  renderProjectSelectionImmediately(controller, liveInstance, intent);
  saveWorkspaceState();
  await transitionProjectSelection(controller.paneID);
  return true;
}

async function drainProjectSelectionController(controller) {
  controller.running = true;
  try {
    while (controller.pending) {
      let intent = takeLatestProjectSelectionIntent(controller, controller.pending);
      const result = await confirmLatestProjectSelectionIntent(controller, intent);
      if (!result.confirmed) {
        controller.pending = null;
        break;
      }
      intent = takeLatestProjectSelectionIntent(controller, result.intent);
      if (!(await applyProjectSelectionIntent(controller, intent)) && !controller.pending) break;
    }
  } finally {
    controller.running = false;
    controller.activeIntent = null;
    syncProjectSelectionControllerUI(controller);
    if (projectSelectionControllers.get(controller.key) === controller) {
      projectSelectionControllers.delete(controller.key);
    }
  }
}

function requestProjectSelection(paneID, instanceID, intent) {
  const workspaceID = activeWorkspaceID;
  const key = projectSelectionControllerKey(workspaceID, paneID);
  let controller = projectSelectionControllers.get(key);
  if (!controller) {
    controller = {
      key,
      workspaceID,
      paneID,
      instanceID,
      pending: null,
      activeIntent: null,
      running: false,
      promise: null
    };
    projectSelectionControllers.set(key, controller);
  }
  controller.pending = { ...intent, workspaceID, paneID, instanceID };
  syncProjectSelectionControllerUI(controller);
  if (!controller.running) controller.promise = drainProjectSelectionController(controller);
  return controller.promise;
}

function hydrateSavedPanelWhenConnected(panel, savedInstance, paneID, attempt = 0, options = {}) {
  if (options.signal?.aborted) { options.foundationScope?.release(paneID); return; }
  if (!panel.isConnected) {
    if (attempt < 120) {
      requestAnimationFrame(() => hydrateSavedPanelWhenConnected(panel, savedInstance, paneID, attempt + 1, options));
    } else options.foundationScope?.release(paneID);
    return;
  }
  void hydrateSavedPanel(panel, savedInstance, paneID, { ...options })
    .catch(() => {
      if (panel.isConnected && !options.signal?.aborted) console.warn("Saved content could not finish loading.");
    })
    .finally(() => options.foundationScope?.release(paneID));
}

function renderProLockedPane(paneID, title) {
  const panel = renderUtility(analysisTemplate, paneID);
  panel.classList.add("pro-locked-panel");
  const header = panel.querySelector(".panel-header");
  header.querySelector(".panel-kind").textContent = title;
  header.querySelector(".panel-title").textContent = title;
  const instance = (state.utilityInstances || []).find(item => paneIDForUtilityInstance(item) === paneID);
  const close = header.querySelector(".utility-close");
  if (!instance && paneID === "utility:analysis") close.addEventListener("click", closeResearchWorkspace);
  else if (!instance) close.remove();
  const content = document.createElement("div");
  content.className = "pro-locked-content";
  const message = document.createElement("p");
  message.textContent = `${title} requires Pro`;
  const upgrade = document.createElement("button");
  upgrade.type = "button";
  upgrade.textContent = "View Pro";
  upgrade.addEventListener("click", () => void focusUtility("settings"));
  content.append(message, upgrade);
  panel.querySelector(".analysis-content").replaceWith(content);
  if (instance) wireUtilityInstanceActions(panel, instance);
  return panel;
}

async function renderSaved(instance, options = {}) {
  if (!hasCapability("saved-work")) {
    const paneID = paneIDForUtilityInstance(instance);
    options.foundationScope?.release(paneID);
    return renderProLockedPane(paneID, "Evidence");
  }
  // Share only within this synchronous setup; hydration obtains its own fresh summary.
  const summary = currentContentSummary();
  const savedInstance = scopeSavedInstanceToWorkspace(normalizeSavedInstance(instance), { projects: summary.projects || [] });
  const paneID = paneIDForUtilityInstance(savedInstance);
  const panel = renderTemplate(savedTemplate);
  panel.classList.add("saved-panel");
  applyPaneWeight(panel, paneID);
  const content = panel.querySelector(".saved-content");
  content.hidden = !savedInstance.selectedFolderID;
  panel.querySelector(".saved-inline-filters").hidden = !savedInstance.selectedFolderID;
  clear(content);
  renderSavedPlanUsage(panel.querySelector(".saved-plan-usage"));
  if (!workspaceProject(summary.projects || [])) {
    content.hidden = false;
    panel.querySelector(".saved-projects-section").hidden = true;
    panel.querySelector(".saved-plan-usage").hidden = true;
    const prompt = document.createElement("div");
    prompt.className = "pro-locked-content saved-project-required";
    const message = document.createElement("p");
    message.textContent = "Choose a Project to view saved passages";
    const choose = document.createElement("button");
    choose.type = "button";
    choose.textContent = "Choose Project";
    choose.addEventListener("click", () => void chooseProjectForSaving());
    prompt.append(message, choose);
    content.append(prompt);
    wireUtilityInstanceActions(panel, savedInstance);
    options.foundationScope?.release(paneID);
    return panel;
  }
  renderSavedProjects(
    panel,
    savedInstance,
    paneID,
    mergeProjectsWithOrganizationAccess(summary.projects || []),
    summary.projectSections || [],
    summary.savedItems || [],
    consolidatedSavedAnnotations(summary.annotations || []),
    summary.projects || []
  );
  requestAnimationFrame(() => hydrateSavedPanelWhenConnected(panel, savedInstance, paneID, 0, { ...options, reuseVerifiedSync: true }));

  return panel;
}

function renderSavedProjects(panel, instance, paneID, projects, projectSections, savedItems = [], annotations = [], workspaceProjects = null) {
  if (workspaceProject(workspaceProjects)) {
    panel.querySelector(".saved-projects-section").hidden = true;
    return;
  }
  projects = projects.filter((project) => !folderIsProject(project));
  const list = panel.querySelector(".saved-project-list");
  const section = panel.querySelector(".saved-projects-section");
  const selectButton = panel.querySelector(".saved-projects-select-button");
  const addButton = panel.querySelector(".saved-projects-add-button");
  const archiveButton = panel.querySelector(".saved-projects-archive-button");
  const headingActions = panel.querySelector(".saved-projects-actions");
  headingActions.querySelector(".saved-projects-selection-actions")?.remove();
  let showingArchived = Boolean(instance.projectsArchiveMode);
  let selecting = false;
  let selectionBusy = false;
  const selectedProjectIDs = new Set();
  const selectionActions = document.createElement("div");
  selectionActions.className = "saved-projects-selection-actions";
  selectionActions.hidden = true;
  selectionActions.setAttribute("aria-label", "Project and saved collection selection");
  const cancelSelectionButton = document.createElement("button");
  cancelSelectionButton.type = "button";
  cancelSelectionButton.className = "saved-projects-selection-action saved-projects-selection-cancel";
  cancelSelectionButton.textContent = "Cancel";
  const archiveSelectedButton = document.createElement("button");
  archiveSelectedButton.type = "button";
  archiveSelectedButton.className = "saved-projects-selection-action saved-projects-selection-archive";
  const deleteSelectedButton = document.createElement("button");
  deleteSelectedButton.type = "button";
  deleteSelectedButton.className = "saved-projects-selection-action saved-projects-selection-delete";
  deleteSelectedButton.title = "Delete selected Projects and saved collections";
  deleteSelectedButton.setAttribute("aria-label", deleteSelectedButton.title);
  deleteSelectedButton.innerHTML = trashIconSVG();
  selectionActions.append(cancelSelectionButton, archiveSelectedButton, deleteSelectedButton);
  headingActions.append(selectionActions);
  const projectsMenuLabel = (savedInstance) => {
    if (savedInstance.projectsMenuOpen) return "";
    if (savedInstance.projectsArchiveMode) return "Archived Projects";
    const selectedProject = projects.find((project) =>
      projectRecordID(project) === String(savedInstance.selectedFolderID || "")
    );
    return selectedProject?.name || selectedProject?.title || "Projects";
  };
  addButton.onclick = () => showProjectCreateSheet(panel);
  wireCodeFilterMenu(list, instance, {
    stateKey: "projectsMenuOpen",
    menuName: "projects",
    label: projectsMenuLabel
  });
  const projectsMenuToggle = panel.querySelector(".saved-projects-menu-toggle");
  projectsMenuToggle.onclick = () => {
    if (instance.projectsMenuOpen || !showingArchived) return;
    showingArchived = false;
    instance.projectsArchiveMode = false;
    syncProjectModeControls();
    renderProjectCards();
    saveWorkspaceState();
  };

  const syncProjectModeControls = () => {
    archiveButton.setAttribute("aria-pressed", String(showingArchived));
    archiveButton.title = showingArchived ? "Show active projects" : "Show archived projects";
    archiveButton.setAttribute("aria-label", archiveButton.title);
    archiveButton.innerHTML = showingArchived ? activeProjectsIconSVG() : archiveIconSVG();
    addButton.hidden = showingArchived;
    addButton.disabled = showingArchived;
    selectButton.hidden = false;
    selectButton.disabled = selectionBusy;
  };

  const selectableProjects = () => (showingArchived
    ? archivedProjectRecords(projects)
    : activeFolderRecords(projects)
  ).filter((project) => !project.sharedOnly);
  const updateSelectionControls = () => {
    const selectableIDs = selectableProjects().map(projectRecordID).filter(Boolean);
    selectedProjectIDs.forEach((id) => {
      if (!selectableIDs.includes(id)) selectedProjectIDs.delete(id);
    });
    section.classList.toggle("is-selecting", selecting);
    selectButton.setAttribute("aria-pressed", String(selecting));
    selectButton.title = selecting ? "Cancel selection" : "Select Projects and saved collections";
    selectButton.setAttribute("aria-label", selectButton.title);
    selectButton.hidden = selecting;
    selectionActions.hidden = !selecting;
    const selectedCount = selectedProjectIDs.size;
    archiveSelectedButton.title = showingArchived
      ? "Restore selected Projects and saved collections"
      : "Archive selected Projects and saved collections";
    archiveSelectedButton.setAttribute("aria-label", archiveSelectedButton.title);
    archiveSelectedButton.innerHTML = showingArchived ? archiveRestoreIconSVG() : archiveIconSVG();
    archiveSelectedButton.disabled = selectedCount === 0 || selectionBusy;
    deleteSelectedButton.disabled = selectedCount === 0 || selectionBusy;
    cancelSelectionButton.disabled = selectionBusy;
    addButton.hidden = showingArchived || selecting;
    archiveButton.hidden = selecting;
    addButton.disabled = showingArchived || selecting || selectionBusy;
    archiveButton.disabled = selecting || selectionBusy;
    list.querySelectorAll(".saved-project-tile").forEach((tile) => {
      const id = tile.dataset.projectId || "";
      const eligible = tile.dataset.bulkSelectable === "true";
      const selected = selectedProjectIDs.has(id);
      tile.classList.toggle("is-bulk-selected", selected);
      if (selecting && eligible) {
        tile.setAttribute("aria-pressed", String(selected));
        tile.setAttribute("aria-label", `${selected ? "Deselect" : "Select"} ${tile.dataset.projectName || "item"}`);
      } else {
        tile.removeAttribute("aria-pressed");
        tile.setAttribute("aria-label", tile.dataset.defaultAriaLabel || "Open item");
      }
      const editProjectButton = tile.querySelector(".saved-project-tile-edit");
      if (editProjectButton) {
        editProjectButton.hidden = !selecting;
        editProjectButton.disabled = selectionBusy;
      }
    });
  };

  const setSelecting = (nextSelecting) => {
    selecting = Boolean(nextSelecting);
    selectedProjectIDs.clear();
    updateSelectionControls();
  };

  const renderProjectCards = () => {
    const visibleRecords = showingArchived
      ? archivedProjectRecords(projects)
      : activeFolderRecords(projects);
    const visibleFolders = visibleRecords;
    clear(list);
    list.classList.toggle("is-showing-archive", showingArchived);

    let draggedProjectID = "";
    const clearDropIndicators = () => {
      list.querySelectorAll(".saved-project-tile").forEach((tile) => {
        tile.classList.remove("is-drop-before", "is-drop-after");
      });
    };
    const reorderProject = async (sourceID, targetID, placeAfter) => {
      if (showingArchived) return;
      const sourceIndex = visibleFolders.findIndex((project) => projectRecordID(project) === sourceID);
      const targetIndex = visibleFolders.findIndex((project) => projectRecordID(project) === targetID);
      if (sourceIndex === -1 || targetIndex === -1 || sourceIndex === targetIndex) return;
      if (folderType(visibleFolders[sourceIndex]) !== folderType(visibleFolders[targetIndex])) return;
      const reordered = [...visibleFolders];
      const [movedProject] = reordered.splice(sourceIndex, 1);
      let insertionIndex = targetIndex - (sourceIndex < targetIndex ? 1 : 0);
      if (placeAfter) insertionIndex += 1;
      reordered.splice(insertionIndex, 0, movedProject);
      await persistProjectOrder(reordered, paneID);
    };

    visibleFolders.forEach((project) => {
      const tile = document.createElement("article");
      tile.className = "saved-project-tile";
      tile.classList.add(`is-${folderType(project)}`);
      if (showingArchived) tile.classList.add("is-archived");
      if (project.sharedOrganizationID) tile.classList.add("is-shared");
      const tileColor = projectColor(project);
      tile.style.setProperty("--project-color", tileColor);
      tile.style.setProperty("--project-on-color", projectForegroundColor(tileColor));
      tile.tabIndex = 0;
      tile.setAttribute("role", "button");
      tile.setAttribute("aria-label", `Open ${project.name || project.title || (folderIsProject(project) ? "Project" : "saved collection")}`);
      tile.dataset.projectId = projectRecordID(project);
      tile.dataset.projectName = project.name || project.title || (folderIsProject(project) ? "Project" : "saved collection");
      tile.dataset.folderType = folderType(project);
      tile.dataset.defaultAriaLabel = tile.getAttribute("aria-label");
      tile.dataset.bulkSelectable = String(!project.sharedOnly);
      const selected = !showingArchived && projectRecordID(project) === String(instance.selectedFolderID || "");
      tile.classList.toggle("is-selected", selected);
      if (selected) tile.setAttribute("aria-current", "true");
      if (!showingArchived && !project.sharedOnly) {
        tile.dataset.draggable = "true";
        tile.draggable = true;
        tile.title = `Drag to reorder · Alt+Arrow keys also move this ${folderIsProject(project) ? "Project" : "saved collection"}`;
        tile.setAttribute("aria-keyshortcuts", "Alt+ArrowUp Alt+ArrowDown");
      }
      const heading = document.createElement("strong");
      heading.textContent = project.name || project.title || "Project";
      const count = projectEvidenceCount(projectSections, project);
      const countLabel = document.createElement("span");
      countLabel.className = "saved-project-count";
      countLabel.textContent = String(count);
      countLabel.title = count === 1 ? "1 saved section" : `${count} saved sections`;
      countLabel.setAttribute("aria-label", countLabel.title);
      tile.append(heading, countLabel);
      if (!project.sharedOnly) {
        const editProjectButton = document.createElement("button");
        editProjectButton.type = "button";
        editProjectButton.className = "saved-project-tile-edit";
        editProjectButton.title = `Edit ${project.name || project.title || (folderIsProject(project) ? "Project" : "saved collection")}`;
        editProjectButton.setAttribute("aria-label", editProjectButton.title);
        editProjectButton.innerHTML = pencilIconSVG();
        editProjectButton.hidden = !selecting;
        editProjectButton.addEventListener("click", (event) => {
          event.stopPropagation();
          if (!selecting || selectionBusy) return;
          showProjectCreateSheet(panel, project);
        });
        editProjectButton.addEventListener("keydown", (event) => event.stopPropagation());
        tile.append(editProjectButton);
      }
      const open = () => {
        if (selecting) {
          const id = projectRecordID(project);
          if (!id || project.sharedOnly || selectionBusy) return;
          if (selectedProjectIDs.has(id)) selectedProjectIDs.delete(id);
          else selectedProjectIDs.add(id);
          updateSelectionControls();
          return;
        }
        const nextFolderID = projectRecordID(project) === String(instance.selectedFolderID || "")
          ? ""
          : projectRecordID(project);
        void requestProjectSelection(paneID, instance.id, {
          kind: nextFolderID ? "project" : "none",
          folderID: nextFolderID,
          project: nextFolderID ? project : null
        });
      };
      tile.addEventListener("pointerdown", (event) => {
        if (event.pointerType !== "mouse" && event.pointerType !== "pen") return;
        tile.dataset.pointerFocus = "true";
      });
      tile.addEventListener("pointercancel", () => {
        delete tile.dataset.pointerFocus;
      });
      tile.addEventListener("click", (event) => {
        if (tile.dataset.justDragged === "true") return;
        if (event.detail > 0) {
          tile.blur();
          delete tile.dataset.pointerFocus;
        }
        void open();
      });
      tile.addEventListener("keydown", (event) => {
        if (
          !showingArchived &&
          !project.sharedOnly &&
          event.altKey &&
          (event.key === "ArrowUp" || event.key === "ArrowDown")
        ) {
          event.preventDefault();
          const currentIndex = visibleFolders.findIndex(
            (candidate) => projectRecordID(candidate) === projectRecordID(project)
          );
          const nextIndex = currentIndex + (event.key === "ArrowUp" ? -1 : 1);
          const target = visibleFolders[nextIndex];
          if (target && folderType(target) === folderType(project)) {
            void reorderProject(
              projectRecordID(project),
              projectRecordID(target),
              event.key === "ArrowDown"
            );
          }
          return;
        }
        if (event.key !== "Enter" && event.key !== " ") return;
        event.preventDefault();
        open();
      });
      tile.addEventListener("dragstart", (event) => {
        if (selecting || showingArchived || project.sharedOnly) {
          event.preventDefault();
          return;
        }
        draggedProjectID = projectRecordID(project);
        tile.dataset.justDragged = "true";
        clearDropIndicators();
        list.querySelectorAll(".saved-project-tile.is-dragging").forEach((candidate) => {
          candidate.classList.remove("is-dragging");
        });
        tile.classList.add("is-dragging");
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", draggedProjectID);
      });
      tile.addEventListener("dragover", (event) => {
        const sourceID = draggedProjectID || event.dataTransfer.getData("text/plain");
        if (!sourceID || sourceID === tile.dataset.projectId || tile.dataset.draggable !== "true") return;
        const sourceProject = visibleFolders.find((candidate) => projectRecordID(candidate) === sourceID);
        if (!sourceProject || folderType(sourceProject) !== folderType(project)) return;
        event.preventDefault();
        event.dataTransfer.dropEffect = "move";
        const bounds = tile.getBoundingClientRect();
        const horizontalDistance = Math.abs(event.clientX - (bounds.left + (bounds.width / 2)));
        const verticalDistance = Math.abs(event.clientY - (bounds.top + (bounds.height / 2)));
        const placeAfter = horizontalDistance >= verticalDistance
          ? event.clientX >= bounds.left + (bounds.width / 2)
          : event.clientY >= bounds.top + (bounds.height / 2);
        clearDropIndicators();
        tile.classList.add(placeAfter ? "is-drop-after" : "is-drop-before");
      });
      tile.addEventListener("drop", (event) => {
        const sourceID = draggedProjectID || event.dataTransfer.getData("text/plain");
        if (!sourceID || sourceID === tile.dataset.projectId) return;
        event.preventDefault();
        const placeAfter = tile.classList.contains("is-drop-after");
        const targetID = tile.dataset.projectId || "";
        clearDropIndicators();
        if (targetID) void reorderProject(sourceID, targetID, placeAfter);
      });
      tile.addEventListener("dragend", () => {
        draggedProjectID = "";
        delete tile.dataset.pointerFocus;
        tile.classList.remove("is-dragging");
        clearDropIndicators();
        requestAnimationFrame(() => {
          tile.dataset.justDragged = "false";
        });
      });
      list.append(tile);
    });
    updateSelectionControls();
    updateCodeFilterMenu(list, instance, {
      stateKey: "projectsMenuOpen",
      menuName: "projects",
      label: projectsMenuLabel
    });
  };

  archiveButton.onclick = () => {
    showingArchived = !showingArchived;
    instance.projectsArchiveMode = showingArchived;
    syncProjectModeControls();
    renderProjectCards();
    saveWorkspaceState();
  };

  selectButton.onclick = () => setSelecting(!selecting);
  cancelSelectionButton.onclick = () => setSelecting(false);
  archiveSelectedButton.onclick = async () => {
    const selectedProjects = selectableProjects().filter((project) => selectedProjectIDs.has(projectRecordID(project)));
    if (!selectedProjects.length) return;
    selectionBusy = true;
    updateSelectionControls();
    if (showingArchived) {
      for (const project of selectedProjects) await restoreArchivedProject(project);
      setSelecting(false);
      return;
    }
    const operation = archiveProjects(selectedProjects, { preserveSavedPanes: true });
    if (!showingArchived) {
      selecting = false;
      selectedProjectIDs.clear();
      renderProjectCards();
    }
    const completed = await operation;
    if (!completed) {
      selectionBusy = false;
      updateSelectionControls();
    }
  };
  deleteSelectedButton.onclick = async () => {
    const selectedProjects = selectableProjects().filter((project) => selectedProjectIDs.has(projectRecordID(project)));
    if (!selectedProjects.length || selectionBusy) return;
    selectionBusy = true;
    updateSelectionControls();
    const completed = await deleteArchivedProjects(selectedProjects, { preserveSavedPanes: true });
    if (completed) setSelecting(false);
    else {
      selectionBusy = false;
      updateSelectionControls();
    }
  };

  syncProjectModeControls();
  renderProjectCards();
}

function annotationEvidenceIsVisible(annotation) {
  const note = String(annotation?.noteBody || "").trim();
  const tags = Array.isArray(annotation?.tags) ? annotation.tags : [];
  return Boolean(note) || tags.some((tag) => String(tag || "").trim());
}

function consolidatedSavedAnnotations(annotations = []) {
  if (!annotations.length) return [];
  // This is one synchronous render pass. Read authoritative overlays once, then
  // index by edition, section and passage; never retain this snapshot across edits.
  const annotationSnapshot = {
    localIDs: new Set((state.localAnnotations || []).map((annotation) => String(annotation?.id || ""))),
    clearRecords: currentBulkClearRecords()
  };
  const recordsByTarget = new Map();
  const targetKey = (annotation) => [
    syncCodeVersion(annotation?.codeVersion),
    String(annotation?.sectionID || ""),
    normalizeAnnotationBlockID(annotation?.blockID || annotation?.anchorID || annotation?.contentBlockID)
  ].join(":");
  (currentContentSummary().annotations || []).forEach((annotation) => {
    const key = targetKey(annotation);
    if (!recordsByTarget.has(key)) recordsByTarget.set(key, []);
    recordsByTarget.get(key).push(annotation);
  });
  const latestByTarget = new Map();
  annotations.forEach((annotation) => {
    if (!annotation || annotation.deletedAt || !annotation.sectionID) return;
    const blockID = normalizeAnnotationBlockID(annotation.blockID || annotation.anchorID || annotation.contentBlockID);
    const key = [syncCodeVersion(annotation.codeVersion), annotation.sectionID, blockID].map(String).join(":");
    const existing = latestByTarget.get(key);
    if (!existing || Date.parse(annotation.updatedAt || 0) >= Date.parse(existing.updatedAt || 0)) {
      latestByTarget.set(key, { ...annotation, blockID, codeVersion: syncCodeVersion(annotation.codeVersion) });
    }
  });
  return Array.from(latestByTarget.entries()).flatMap(([key, annotation]) => {
    const merged = annotationForTarget(annotation, "", "", {
      ...annotationSnapshot,
      annotations: recordsByTarget.get(key) || []
    });
    if (!annotationEvidenceIsVisible(merged)) return [];
    return [{
      ...annotation,
      ...merged,
      blockID: annotation.blockID,
      codeVersion: annotation.codeVersion,
      savedColumnKind: "annotation"
    }];
  });
}

function mergeSavedColumnItems(savedItems = [], annotatedItems = []) {
  const sectionAnnotations = new Map(
    annotatedItems
      .filter((item) => !normalizeAnnotationBlockID(item.blockID))
      .map((item) => [savedEvidenceKey(item), item])
  );
  const bookmarkedSectionKeys = new Set(
    savedItems
      .filter((item) => !normalizeAnnotationBlockID(item.blockID))
      .map((item) => savedEvidenceKey(item))
  );
  const bookmarks = savedItems.map((item) => {
    const annotation = normalizeAnnotationBlockID(item.blockID)
      ? null
      : sectionAnnotations.get(savedEvidenceKey(item));
    return {
      ...item,
      ...(annotation ? { noteBody: annotation.noteBody, tags: annotation.tags } : {}),
      savedColumnKind: "bookmark"
    };
  });
  const annotations = annotatedItems.filter((item) =>
    normalizeAnnotationBlockID(item.blockID) || !bookmarkedSectionKeys.has(savedEvidenceKey(item))
  );
  return [...bookmarks, ...annotations];
}

function savedSectionIsNestedListParagraph(chapter, section) {
  const sectionID = String(section?.id || "");
  const sectionNumber = String(section?.sectionNumber || "").trim().replace(/\.$/, "");
  if (!sectionID || !/^\d+(?:\.\d+)*$/.test(sectionNumber)) return false;

  const parentGroup = (chapter?.groups || []).find((group) =>
    (group?.sections || []).some((candidate) =>
      String(candidate?.id ?? candidate) === sectionID
    )
  );
  const parentNumber = String(parentGroup?.headerLine || parentGroup?.headingLine || "")
    .match(/\b(\d+(?:\.\d+)*)\b/)?.[1];
  if (!parentNumber) return false;

  return sectionNumber !== parentNumber && !sectionNumber.startsWith(`${parentNumber}.`);
}

async function resolveSavedSectionDetail(detail) {
  // Reuse revision-validated chapter windows instead of one HTTP request per
  // saved row. Stable windows also survive closing/reopening the Evidence pane.
  if (detail.chapterID && detail.sectionID) {
    try {
      const chapter = await fetchChapter(detail.chapterID);
      if (chapter.bodyContract === 2 && sectionRecordMatchesRequestedEdition(detail, chapter)) {
        const index = (chapter.sections || []).findIndex(section =>
          String(section.id) === String(detail.sectionID));
        if (index >= 0) {
          const start = Math.floor(index / 50) * 50;
          const windowChapter = await fetchChapterBodyWindow(detail.chapterID, start, 50, chapter);
          const section = readerSectionWithWindowBody(chapter.sections[index], windowChapter);
          if (Array.isArray(section.blocks) && sectionRecordMatchesRequestedEdition(detail, section)) {
            return { chapter, section };
          }
        }
      }
    } catch {
      // Missing legacy metadata or a changed corpus retains exact-section recovery.
    }
  }
  return resolveSectionDetail(detail);
}

async function hydrateSavedColumnItems(items = []) {
  const sectionPromises = new Map();
  const resolveItemSection = (item) => {
    const sectionID = String(item.sectionID || item.savedSectionID || item.itemID || "");
    const key = [syncCodeVersion(item.codeVersion), sectionID].join(":");
    if (!sectionPromises.has(key)) {
      const detail = {
        codePrefix: item.codePrefix || "BC",
        codeVersion: syncCodeVersion(item.codeVersion || syncCodeVersionForPrefix(item.codePrefix || "BC")),
        chapterID: item.chapterID || "",
        chapterNumber: item.chapterNumber || "",
        sectionID,
        sectionNumber: item.sectionNumber || "",
        title: item.title || "Section"
      };
      sectionPromises.set(key, resolveSavedSectionDetail(detail).then(({ chapter, section }) => ({ chapter, section, detail })));
    }
    return sectionPromises.get(key);
  };

  return Promise.all(items.map(async (item) => {
    try {
      const { chapter, section, detail } = await resolveItemSection(item);
      const blockID = item.projectSavedScope === "section"
        ? ""
        : normalizeAnnotationBlockID(item.blockID || item.anchorID || item.contentBlockID);
      const annotatedBlocks = section ? annotatedBlocksForSection(section) : [];
      const block = blockID
        ? annotatedBlocks.find((candidate) =>
            normalizeAnnotationBlockID(candidate?.id || candidate?.tableID || candidate?.imageID) === blockID
          )
        : null;
      const rawPreview = block?.plainText || block?.text || sectionPlainText(section) || item.previewText || "";
      const codePrefix = detail.codePrefix || chapter?.codePrefix || item.codePrefix || "BC";
      const chapterID = detail.chapterID || chapter?.id || item.chapterID || "";
      const chapterNumber = detail.chapterNumber || chapter?.chapterNumber || item.chapterNumber || "";
      const savedContentComparisonText = String(rawPreview).replace(/\s+/g, " ").trim();
      return {
        ...item,
        blockID,
        codePrefix,
        chapterID,
        chapterNumber,
        chapterTitle: chapter?.fullTitle || chapter?.displayTitle || chapter?.title || item.chapterTitle || "",
        sectionNumber: section?.sectionNumber || detail.sectionNumber || item.sectionNumber || "",
        title: section?.title || detail.title || item.title || "Section",
        isNestedListParagraph: savedSectionIsNestedListParagraph(chapter, section),
        savedContentComparisonText,
        previewText: savedContentComparisonText.slice(0, 240)
      };
    } catch {
      return { ...item, previewText: String(item.previewText || "").replace(/\s+/g, " ").trim().slice(0, 240) };
    }
  }));
}

function mergeEquivalentSavedColumnRows(items = []) {
  const normalizedPreview = (item) => String(item?.savedContentComparisonText || item?.previewText || "")
    .replace(/\s+/g, " ")
    .replace(/(["“‘])\s+/g, "$1")
    .replace(/\s+([,.;:!?])/g, "$1")
    .trim();
  const targetKey = (item) => [
    syncCodeVersion(item?.codeVersion),
    String(item?.sectionID || ""),
    normalizeAnnotationBlockID(item?.blockID || item?.anchorID || item?.contentBlockID)
  ].join(":");
  const bookmarksByTarget = new Map(
    items
      .filter((item) => item?.savedColumnKind === "bookmark")
      .map((item) => [targetKey(item), item])
  );
  const mergedAnnotations = new Set();

  items.forEach((item) => {
    const blockID = normalizeAnnotationBlockID(item?.blockID);
    if (!blockID || item?.savedColumnKind !== "annotation") return;
    const bookmark = bookmarksByTarget.get(targetKey(item));
    const bookmarkPreview = normalizedPreview(bookmark);
    if (!bookmark || !bookmarkPreview || bookmarkPreview !== normalizedPreview(item)) return;
    bookmark.annotationBlockID = blockID;
    bookmark.noteBody = String(item.noteBody || bookmark.noteBody || "").trim();
    mergedAnnotations.add(item);
  });

  return items.filter((item) => !mergedAnnotations.has(item));
}

async function refreshOpenSavedPanes() {
  const paneIDs = (state.utilityInstances || [])
    .filter((instance) => instance.key === "saved")
    .map((instance) => paneIDForUtilityInstance(instance));
  if (!paneIDs.length) return;
  await transitionWorkspace("utility", { refreshPaneIDs: paneIDs });
}

function removeIconSVG() {
  return `
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <path d="M3 6h18"></path>
      <path d="M8 6V4h8v2"></path>
      <path d="M19 6l-1 14H6L5 6"></path>
      <path d="M10 11v5"></path>
      <path d="M14 11v5"></path>
    </svg>
  `;
}

function savedItemSelectionID(item) {
  return String(item?.id || `${item?.sectionID || "section"}:${item?.blockID || ""}`);
}

function createSavedBulkSelectionController(panel, savedItems, options = {}) {
  const records = savedItems.filter((item) => item?.sectionID);
  const recordByID = new Map(records.map((item) => [savedItemSelectionID(item), item]));
  const orderedIDs = [...recordByID.keys()];
  const selectedIDs = new Set();
  const rows = new Map();
  let active = false;
  let busy = false;

  const selectButton = panel.querySelector(".saved-evidence-select-toggle");
  const removeButton = panel.querySelector(".saved-evidence-delete-selection");
  const cancelButton = panel.querySelector(".saved-evidence-cancel-selection");
  if (!selectButton || !removeButton || !cancelButton) return null;
  const reportButton = document.createElement("button");
  reportButton.type = "button";
  reportButton.className = "saved-evidence-add-report-selection";
  reportButton.textContent = "Add to Report";
  reportButton.hidden = true;
  if (options.reportProject && !options.reportProject.sharedOnly && hasCapability("professional-exports")) cancelButton.before(reportButton);
  reportButton.addEventListener("click", async () => {
    if (busy || !selectedIDs.size) return;
    busy = true;
    update();
    try {
      const draft = await addSavedEvidenceToReport(options.reportProject, [...selectedIDs].map(id => recordByID.get(id)));
      reportAdditionFeedback(reportButton, draft);
    } catch (error) { await showWebNotice("Could not add to Report", error.message); }
    finally { busy = false; update(); }
  });
  const researchButton = document.createElement("button");
  researchButton.type = "button";
  researchButton.className = "saved-evidence-research-selection";
  researchButton.textContent = "Ask Assistant";
  researchButton.hidden = true;
  cancelButton.before(researchButton);
  researchButton.addEventListener("click", async () => {
    if (busy || !selectedIDs.size) return;
    busy = true;
    update();
    try {
      const passages = [...selectedIDs].map(id => recordByID.get(id)).map(item => ({
        sectionID: String(item.sectionID),
        selectedText: String(item.previewText || item.selectedText || item.title || "").trim(),
        savedItemID: item.savedColumnKind === "bookmark" ? String(item.id || "") : ""
      }));
      if (passages.some(passage => !passage.selectedText)) throw new Error("A selected item has no source text. Open it before starting an Assistant conversation.");
      await startNewResearchFromSelection({passages,
        projectID: options.reportProject ? projectDetailKey(projectIdentity(options.reportProject)) : "",
        originPaneID: panel.dataset.paneId || primarySavedPaneID(), originSurface: "saved"});
    } catch (error) { await showWebNotice("Could not open Assistant", error.message); }
    finally { busy = false; update(); }
  });
  const projectPicker = document.createElement("select");
  projectPicker.setAttribute("aria-label", "Add selected evidence to project");
  projectPicker.hidden = true;
  const placeholder = new Option("Add to project", "");
  projectPicker.append(placeholder);
  const assignmentProjects = activeFolderRecords(currentContentSummary().projects || [])
    .filter((project) => folderIsProject(project) && !project.sharedOnly);
  assignmentProjects.forEach((project) => projectPicker.append(new Option(project.name || project.title, projectRecordID(project))));
  const assignButton = document.createElement("button");
  assignButton.type = "button";
  assignButton.className = "saved-inbox-assign-selection";
  assignButton.setAttribute("aria-label", "Add selected saves to Project");
  assignButton.setAttribute("aria-haspopup", "menu");
  assignButton.setAttribute("aria-expanded", "false");
  assignButton.innerHTML = folderAddIconSVG();
  if (options.inbox) cancelButton.before(assignButton);
  else if (options.allowProjectAssignment) cancelButton.before(projectPicker);
  assignButton.addEventListener("click", () => {
    if (busy || !selectedIDs.size) return;
    const selected = [...selectedIDs].map(id => recordByID.get(id));
    const identity = captureAccountRequest();
    const workspaceID = activeWorkspaceID;
    showSectionDetailProjectMenu(panel, selected[0], assignButton, {
      onAssign: async (project) => {
        busy = true;
        update();
        try {
          for (const item of selected) {
            requireCurrentAccountRequest(identity);
            if (workspaceID !== activeWorkspaceID) throw accountContextChangedError();
            if (!await persistSectionInProject(project, item)) throw new Error("The passage could not be added. Please try again.");
          }
          requireCurrentAccountRequest(identity);
          if (workspaceID !== activeWorkspaceID) throw accountContextChangedError();
          setActive(false);
          await refreshOpenSavedPanes();
          return { saved: true };
        } finally { busy = false; update(); }
      }
    });
  });
  projectPicker.addEventListener("change", async () => {
    const project = assignmentProjects.find((item) => projectRecordID(item) === projectPicker.value);
    if (!project || busy || !selectedIDs.size || !options.allowProjectAssignment) return;
    busy = true;
    update();
    try {
      for (const id of selectedIDs) await persistSectionInProject(project, recordByID.get(id));
      setActive(false);
      await refreshOpenSavedPanes();
    } catch (error) {
      await showWebNotice("Could not add evidence to project", error.message || "Please try again.");
    } finally {
      busy = false;
      projectPicker.value = "";
      update();
    }
  });

  const update = () => {
    panel.classList.toggle("is-saved-selecting", active);
    selectButton.setAttribute("aria-pressed", String(active));
    const selectedCount = selectedIDs.size;
    researchButton.hidden = selectedCount === 0;
    researchButton.disabled = busy || selectedCount === 0;
    reportButton.hidden = selectedCount === 0;
    reportButton.disabled = busy || selectedCount === 0;
    projectPicker.hidden = options.inbox || !options.allowProjectAssignment || selectedCount === 0;
    assignButton.hidden = !options.inbox || selectedCount === 0;
    assignButton.disabled = busy;
    projectPicker.disabled = busy || !assignmentProjects.length;
    removeButton.hidden = options.inbox || selectedCount === 0;
    removeButton.title = selectedCount === 1 ? "Delete selected evidence" : `Delete ${selectedCount} selected items`;
    removeButton.setAttribute("aria-label", removeButton.title);
    removeButton.disabled = selectedCount === 0 || busy;
    cancelButton.hidden = !active;
    cancelButton.disabled = busy;
    selectButton.disabled = busy;
    rows.forEach((row, id) => {
      const selected = selectedIDs.has(id);
      row.classList.toggle("is-selected", selected);
      const rowButton = row.querySelector(".saved-section-open");
      if (active) rowButton?.setAttribute("aria-pressed", String(selected));
      else rowButton?.removeAttribute("aria-pressed");
    });
  };

  const setActive = (nextActive) => {
    active = nextActive;
    selectedIDs.clear();
    update();
  };
  const controller = {
    isActive: () => active,
    beginRender() {
      rows.clear();
    },
    register(row, item) {
      const id = savedItemSelectionID(item);
      if (recordByID.has(id)) recordByID.set(id, item);
      rows.set(id, row);
      const indicator = document.createElement("span");
      indicator.className = "saved-selection-check";
      indicator.setAttribute("aria-hidden", "true");
      indicator.innerHTML = selectionIndicatorIconSVG();
      row.prepend(indicator);
      const selected = selectedIDs.has(id);
      row.classList.toggle("is-selected", selected);
      const rowButton = row.querySelector(".saved-section-open");
      if (active) rowButton?.setAttribute("aria-pressed", String(selected));
      else rowButton?.removeAttribute("aria-pressed");
    },
    toggle(item) {
      if (!active || busy) return;
      const id = savedItemSelectionID(item);
      if (selectedIDs.has(id)) selectedIDs.delete(id);
      else selectedIDs.add(id);
      update();
    }
  };

  selectButton.addEventListener("click", () => setActive(!active));
  cancelButton.addEventListener("click", () => setActive(false));
  removeButton.addEventListener("click", async () => {
    const selectedItems = orderedIDs.filter((id) => selectedIDs.has(id)).map((id) => recordByID.get(id));
    const count = selectedItems.length;
    if (!count) return;
    const requestIdentity = captureAccountRequest();
    const confirmed = await confirmWebWarning(
      "Delete saved evidence",
      `Delete ${count} selected ${count === 1 ? "item" : "items"}?${options.removeConfirmationDetail ? `\n\n${options.removeConfirmationDetail}` : ""}`,
      { confirmLabel: "Delete" }
    );
    if (!confirmed) return;
    requireCurrentAccountRequest(requestIdentity);
    busy = true;
    update();
    let removedCount = 0;
    try {
      if (typeof options.removeBatchAction === "function") {
        removedCount = await options.removeBatchAction(selectedItems, count => { removedCount = count; });
        requireCurrentAccountRequest(requestIdentity);
      } else for (const item of selectedItems) {
        requireCurrentAccountRequest(requestIdentity);
        const removed = typeof options.removeAction === "function"
          ? await options.removeAction(item, { confirmedFinalDestinationRemoval: true })
          : await persistSectionBookmark(item, false, { refreshSavedPanes: false });
        if (removed === false) continue;
        removedCount += 1;
      }
      await refreshOpenSavedPanes();
      requireCurrentAccountRequest(requestIdentity);
      await showWebNotice(
        "Saved evidence deleted",
        `${removedCount} saved ${removedCount === 1 ? "item was" : "items were"} deleted.`
      );
      await refreshOpenSavedPanes();
      refreshVisibleSyncedDerivedState();
      await refreshProjectSourceConsumers();
    } catch (error) {
      await showWebNotice(
        "Could not remove saved items",
        `${error.message || "The selected saved items could not be removed."} Removed ${removedCount} of ${count}.`
      );
      busy = false;
      update();
    }
  });
  update();
  return controller;
}

function folderAddIconSVG() {
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7V4h6l2 3h10v13H3Z"/><path d="M12 10v7m-3.5-3.5h7"/></svg>';
}

function appendSavedEvidenceRow(codeBody, item, paneID, options, annotationSnapshot) {
  const row = document.createElement("article");
  row.className = `saved-row saved-section-row code-theme-${codeTheme(item.codePrefix || item.code || "BC")}`;
  row.dataset.savedEvidenceKey = savedEvidenceKey(item);
  if (item.isNestedListParagraph) {
    row.classList.add("is-list-paragraph");
  }
  const removableSavedItem = typeof options.removableSavedItems === "function"
      ? options.removableSavedItems(item)
      : Boolean(options.removableSavedItems);
  const selectableSavedItem = removableSavedItem && Boolean(options.selectionController);
  const openButton = document.createElement("button");
  openButton.className = "saved-row-button saved-section-open";
  openButton.type = "button";
  const sectionNumber = String(item.sectionNumber || item.sectionID || "").trim();
  const titleText = sectionTitleWithoutNumber({ sectionNumber, title: item.title || "Section" }) || "Section";
  const heading = document.createElement("span");
  heading.className = "saved-section-heading";
  const meta = document.createElement("span");
  meta.className = "saved-section-meta";
  meta.textContent = normalizeAnnotationBlockID(item.blockID) || item.isNestedListParagraph
    ? ["Paragraph", sectionNumber].filter(Boolean).join(" · ")
    : item.kind === "textBlock"
      ? ["Text Block", sectionNumber].filter(Boolean).join(" · ")
    : ["Section", sectionNumber].filter(Boolean).join(" · ");
  meta.textContent += ` · ${savedEvidenceEdition(item)}`;
  if (options.inbox) meta.textContent = `${item.codePrefix || item.code || "BC"} · ${savedEvidenceEdition(item)} · § ${sectionNumber}`;
  const annotation = annotationForTarget(item, "", "", annotationSnapshot);
  const notePreview = String(item.noteBody || annotation.noteBody || "").trim();
  const title = document.createElement(item.isNestedListParagraph ? "span" : "strong");
  title.className = "saved-section-title";
  title.textContent = titleText;
  const metaLine = document.createElement("span");
  metaLine.className = "saved-section-meta-line";
  metaLine.append(meta);
  heading.append(metaLine, title);
  openButton.append(heading);
  if (item.previewText) {
    const preview = document.createElement("span");
    preview.className = "saved-paragraph-preview";
    preview.textContent = item.previewText;
    markResearchSelectable(preview, {
      ...item,
      researchSavedItemID: item.savedColumnKind === "bookmark" ? item.id : ""
    });
    openButton.append(preview);
  }
  if (notePreview) {
    const note = document.createElement("span");
    note.className = "saved-note-preview";
    const noteText = document.createElement("span");
    noteText.className = "saved-note-text";
    noteText.textContent = notePreview;
    note.append(noteText);
    openButton.append(note);
  }
  if (options.showProjectContext !== false) {
    const projectNames = typeof options.projectNamesForItem === "function"
      ? options.projectNamesForItem(item)
      : [];
    if (projectNames.length) {
      const projectContext = document.createElement("span");
      projectContext.className = "saved-row-projects";
      projectContext.textContent = projectNames.join(" · ");
      openButton.append(projectContext);
    } else {
      const unassigned = document.createElement("span");
      unassigned.className = "saved-row-projects is-unassigned";
      unassigned.textContent = "Unassigned saves";
      openButton.append(unassigned);
    }
  }
  openButton.addEventListener("click", () => {
    if (window.getSelection && String(window.getSelection()).trim()) return;
    if (options.selectionController?.isActive()) {
      if (selectableSavedItem) options.selectionController.toggle(item);
    } else {
      const openItem = item.annotationBlockID
        ? { ...item, blockID: item.annotationBlockID }
        : item;
      void openSavedItemInReader(openItem, paneID);
    }
  });
  row.append(openButton);
  if (options.inbox) {
    const assign = document.createElement("button");
    assign.type = "button";
    assign.className = "saved-inbox-assign";
    assign.setAttribute("aria-label", `Add ${sectionNumber} ${savedEvidenceEdition(item)} to Project`);
    assign.setAttribute("aria-haspopup", "menu");
    assign.setAttribute("aria-expanded", "false");
    assign.innerHTML = folderAddIconSVG();
    assign.addEventListener("click", () => showSectionDetailProjectMenu(codeBody.closest(".saved-panel"), item, assign));
    row.append(assign);
  } else if (!options.selectionController?.isActive()) {
    const actions = document.createElement("div");
    actions.className = "saved-row-actions";
    const researchButton = document.createElement("button");
    researchButton.type = "button";
    researchButton.textContent = "Research";
    researchButton.addEventListener("click", async () => {
      researchButton.disabled = true;
      try {
        await startFocusedResearchFromSavedItem(item, options.researchProjectID || "");
      } catch (error) {
        researchButton.disabled = false;
        await showWebNotice(
          "Could not start Research",
          error.message || "The saved passage could not be added to a new Research conversation."
        );
      }
    });
    actions.append(researchButton);
    if (options.reportProject && !options.reportProject.sharedOnly && hasCapability("professional-exports")) {
      const reportButton = reportMembershipIndicator(projectDetailKey(projectIdentity(options.reportProject)), "evidence", item, "action");
      reportButton.className = "saved-add-to-report workflow-action workflow-action-secondary";
      reportButton.textContent = "Add to Report";
      reportButton.addEventListener("click", async () => {
        reportButton.disabled = true;
        try { reportAdditionFeedback(reportButton, await addSavedEvidenceToReport(options.reportProject, [item])); }
        catch (error) { await showWebNotice("Could not add to Report", error.message); }
        finally { if (reportButton.isConnected) reportButton.disabled = false; }
      });
      actions.append(reportButton);
    }
    if (item.savedColumnKind === "bookmark") {
      const removeItemButton = document.createElement("button");
      removeItemButton.type = "button";
      removeItemButton.textContent = "Remove";
      removeItemButton.addEventListener("click", async () => {
        removeItemButton.disabled = true;
        row.classList.add("is-removing");
        const removalAnimation = typeof options.animateSavedItemRemoval === "function"
          ? options.animateSavedItemRemoval(row)
          : animateSavedRowRemoval(row);
        const removed = await persistSectionBookmark(item, false, {
          undoPaneID: paneID,
          refreshSavedPanes: false,
          refreshProjectPanes: false
        });
        await removalAnimation;
        if (removed === false) {
          await refreshOpenSavedPanes();
          return;
        }
        if (typeof options.onSavedItemRemoved === "function") {
          await options.onSavedItemRemoved(item);
        }
      });
      const more = document.createElement("details");
      more.className = "saved-row-more";
      const summary = document.createElement("summary");
      summary.textContent = "⋯";
      summary.setAttribute("aria-label", "Evidence actions");
      more.append(summary, removeItemButton);
      more.addEventListener("keydown", event => {
        if (event.key === "Escape") { more.open = false; summary.focus(); }
      });
      more.addEventListener("focusout", () => requestAnimationFrame(() => {
        if (!more.contains(document.activeElement)) more.open = false;
      }));
      actions.append(more);
    }
    row.append(actions);
  }
  if (selectableSavedItem) options.selectionController.register(row, item);
  codeBody.append(row);
}

function renderSavedItemsByCode(content, savedItems, paneID = "utility:saved", options = {}) {
  // Keep this snapshot local to this synchronous render; later renders must see new edits and clears.
  const annotationSnapshot = {
    annotations: currentContentSummary().annotations,
    localIDs: new Set((state.localAnnotations || []).map((annotation) => String(annotation?.id || ""))),
    clearRecords: currentBulkClearRecords()
  };
  if (options.inbox) {
    savedItems.forEach(item => appendSavedEvidenceRow(content, item, paneID, options, annotationSnapshot));
    return;
  }
  const codeGroups = new Map();
  savedItems.forEach((item) => {
    const prefix = item.codePrefix || item.code || "BC";
    const groupKey = savedCodeGroupKey(item);
    if (!codeGroups.has(groupKey)) codeGroups.set(groupKey, { prefix, items: [] });
    codeGroups.get(groupKey).items.push(item);
  });

  Array.from(codeGroups.entries()).forEach(([groupKey, group]) => {
    const { prefix, items } = group;
    const codeGroup = document.createElement("section");
    codeGroup.className = "saved-code-group";
    codeGroup.classList.add(`code-theme-${codeTheme(prefix)}`);
    const collapsedPrefixes = new Set(
      (Array.isArray(options.collapsedCodePrefixes) ? options.collapsedCodePrefixes : [])
        .map((value) => String(value || ""))
        .filter(Boolean)
    );
    const codeBody = document.createElement("div");
    codeBody.className = "saved-code-group-body";
    codeBody.id = `saved-code-group-${crypto.randomUUID()}`;
    const codeLabel = document.createElement("button");
    codeLabel.type = "button";
    codeLabel.className = "section-label saved-code-label saved-code-toggle";
    codeLabel.setAttribute("aria-controls", codeBody.id);
    const codeLabelText = document.createElement("span");
    codeLabelText.textContent = codeDisplayLabel(prefix, items[0]?.codeVersion || "");
    const chevron = document.createElement("span");
    chevron.className = "saved-code-toggle-chevron";
    chevron.setAttribute("aria-hidden", "true");
    chevron.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 18 6-6-6-6"></path></svg>';
    codeLabel.append(codeLabelText, chevron);
    const initiallyCollapsed = collapsedPrefixes.has(groupKey);
    codeGroup.classList.toggle("is-collapsed", initiallyCollapsed);
    wireProjectSectionMotion(
      codeGroup,
      codeBody,
      [codeLabel],
      codeDisplayLabel(prefix, items[0]?.codeVersion || ""),
      !initiallyCollapsed,
      {
        onChange: (expanded) => {
          const collapsed = !expanded;
          codeGroup.classList.toggle("is-collapsed", collapsed);
          if (typeof options.onCodeGroupToggle === "function") {
            options.onCodeGroupToggle(groupKey, collapsed);
          }
        }
      }
    );
    codeGroup.append(codeLabel, codeBody);

    const orderedItems = options.preserveOrder ? [...items] : [...items].sort((left, right) => {
      const chapterOrder = String(left.chapterNumber || left.chapterID || "").localeCompare(
        String(right.chapterNumber || right.chapterID || ""),
        undefined,
        { numeric: true, sensitivity: "base" }
      );
      if (chapterOrder) return chapterOrder;
      const sectionOrder = String(left.sectionNumber || left.sectionID || "").localeCompare(
        String(right.sectionNumber || right.sectionID || ""),
        undefined,
        { numeric: true, sensitivity: "base" }
      );
      if (sectionOrder) return sectionOrder;
      const leftIsParagraph = Boolean(normalizeAnnotationBlockID(left.blockID));
      const rightIsParagraph = Boolean(normalizeAnnotationBlockID(right.blockID));
      if (leftIsParagraph !== rightIsParagraph) return leftIsParagraph ? 1 : -1;
      return String(left.blockID || left.id || "").localeCompare(String(right.blockID || right.id || ""));
    });
    const renderEntries = [];
    if (options.showChapterHeaders) {
      const chapterGroups = new Map();
      orderedItems.forEach((item) => {
        const chapterKey = String(item.chapterNumber || item.chapterID || "");
        if (!chapterGroups.has(chapterKey)) chapterGroups.set(chapterKey, []);
        chapterGroups.get(chapterKey).push(item);
      });
      chapterGroups.forEach((chapterItems, chapterKey) => {
        renderEntries.push({ kind: "chapter", chapterKey, item: chapterItems[0] });
        chapterItems.forEach((item) => renderEntries.push({ kind: "item", item }));
      });
    } else {
      orderedItems.forEach((item) => renderEntries.push({ kind: "item", item }));
    }
    renderEntries.forEach((entry) => {
      if (entry.kind === "chapter") {
        const chapterHeader = document.createElement("div");
        chapterHeader.className = "saved-chapter-header";
        const chapterNumber = document.createElement("strong");
        chapterNumber.textContent = entry.item.chapterNumber ? `Chapter ${entry.item.chapterNumber}` : "Chapter";
        const chapterTitle = document.createElement("span");
        const normalizedChapterTitle = String(entry.item.chapterTitle || "")
          .replace(/^\s*chapter\s+\S+\s*[:—-]?\s*/i, "")
          .trim();
        chapterTitle.textContent = normalizedChapterTitle;
        chapterHeader.append(chapterNumber);
        if (normalizedChapterTitle) chapterHeader.append(chapterTitle);
        codeBody.append(chapterHeader);
        return;
      }
      appendSavedEvidenceRow(codeBody, entry.item, paneID, options, annotationSnapshot);
    });

    content.append(codeGroup);
  });
}

async function animateSavedRowRemoval(row) {
  if (!row?.isConnected) return;
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches || typeof row.animate !== "function") {
    row.remove();
    return;
  }
  const height = row.getBoundingClientRect().height;
  row.style.overflow = "hidden";
  const animation = row.animate([
    { height: `${height}px`, opacity: 1, transform: "translateY(0)" },
    { height: "0px", opacity: 0, transform: "translateY(-6px)" }
  ], {
    duration: 220,
    easing: "cubic-bezier(0.22, 1, 0.36, 1)",
    fill: "forwards"
  });
  try {
    await animation.finished;
  } catch {
    // A panel refresh may replace the row before its local animation finishes.
  }
  row.remove();
}

function appendSectionLabel(container, label) {
  const element = document.createElement("p");
  element.className = "section-label";
  element.textContent = label;
  container.append(element);
}

function appendMutedRow(container, title, message) {
  const row = document.createElement("article");
  row.className = "saved-row";
  const heading = document.createElement("strong");
  heading.textContent = title;
  const body = document.createElement("span");
  body.textContent = message;
  row.append(heading);
  if (message) row.append(body);
  container.append(row);
}

function appendEmptySaved(container, title, message) {
  const wrapper = document.createElement("section");
  wrapper.className = "reader-empty";
  const heading = document.createElement("h3");
  heading.textContent = title;
  const paragraph = document.createElement("p");
  paragraph.textContent = message;
  wrapper.append(heading, paragraph);
  container.append(wrapper);
}

async function openDeepLinkedSectionInReader(item) {
  if (workspaceColumnsRequireProject()) return;
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  let navigationItem;
  const isCurrent = () => isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === workspaceID &&
    !workspaceColumnsRequireProject() &&
    (!navigationItem?.__activeCodeSourceContext || activeCodeSourcesController.isCurrent(navigationItem.__activeCodeSourceContext));
  navigationItem = await resolveReaderSource(item, {isCurrent});
  if (!navigationItem || !isCurrent()) return;
  const detail = searchResultDetail(navigationItem);
  let reader = (state.readers || []).find((candidate) => candidate.codePrefix === detail.codePrefix);
  if (!reader) {
    reader = newReaderState(readerFieldsForSectionDetail(detail, {
      shouldSmoothScrollToSection: false
    }));
    state.readers.push(reader);
  } else {
    Object.assign(reader, readerFieldsForSectionDetail(detail, {
      shouldSmoothScrollToSection: false
    }));
  }
  const paneID = paneIDForReader(reader);
  state.paneWeights[paneID] ||= defaultPaneWidthForID(paneID);
  appendPaneIfMissing(paneID);
  scheduleContinuitySync(reader);
  saveWorkspaceState();
  await transitionWorkspace("utility", { refreshPaneIDs: [paneID] });
  if (!isCurrent() || !await whenWorkspacePaneReady(paneID) || !isCurrent()) return;
  alignReaderSectionAfterLayout(reader);
  scrollPaneIntoView(paneID);
}

function readerMatchesSource(reader, detail) {
  if (!reader || !detail) return false;
  const sameCode = String(reader.codePrefix || "BC").toUpperCase() ===
    String(detail.codePrefix || "BC").toUpperCase();
  const readerSectionID = String(reader.sectionID || "");
  const detailSectionID = String(detail.sectionID || detail.id || "");
  const sameSection = detailSectionID
    ? readerSectionID === detailSectionID
    : String(reader.sectionNumber || "") === String(detail.sectionNumber || "");
  return sameCode && sameSection;
}

function readerIsClearlyAvailable(reader) {
  return Boolean(reader) &&
    !String(reader.chapterID || "").trim() &&
    !String(reader.sectionID || "").trim() &&
    !String(reader.sectionNumber || "").trim() &&
    (!String(reader.title || "").trim() || reader.title === "Reader");
}

function readerPositionLabel(reader) {
  const index = (state.readers || []).findIndex((candidate) => candidate.id === reader?.id);
  return index >= 0 ? `Reader ${index + 1}` : "Reader";
}

function readerSourceLabel(reader) {
  return sectionDisplayTitle(reader?.sectionNumber, reader?.title, "current section");
}

function searchReaderReplacementCandidate(anchorPaneID = "") {
  return (state.readers || []).find((reader) => reader.sourceAnchorPaneID === anchorPaneID) ||
    state.readers[1] ||
    state.readers[0] ||
    null;
}

async function confirmSearchReaderReplacement(reader, detail, anchorPaneID = "") {
  if (!reader) return false;
  const readerLabel = readerPositionLabel(reader);
  const currentSource = readerSourceLabel(reader);
  const nextSource = sectionDisplayTitle(detail?.sectionNumber, detail?.title, "this Search result");
  const container = anchorPaneID
    ? track.querySelector(`[data-pane-id="${CSS.escape(anchorPaneID)}"]`)
    : null;
  return confirmWebWarning(
    `Replace ${readerLabel}?`,
    `Free includes two Readers and both are in use. Opening ${nextSource} will replace ${currentSource} in ${readerLabel}. The other Reader will stay unchanged.`,
    {
      confirmLabel: `Replace ${readerLabel}`,
      container
    }
  );
}

function revealReaderSourceTarget(reader, item, evidenceAnchor = null, options = {}) {
  const paneID = paneIDForReader(reader);
  const revealToken = crypto.randomUUID();
  reader.sourceRevealToken = revealToken;
  [0, 90, 240].forEach((delay) => {
    window.setTimeout(() => {
      if (reader.sourceRevealToken !== revealToken) return;
      const panel = track.querySelector(`.reader-panel[data-pane-id="${CSS.escape(paneID)}"]`);
      const content = panel?.querySelector(".reader-content");
      const target = savedReaderTarget(content, item, options);
      if (!content || !target) return;
      content.querySelectorAll(".is-source-target").forEach((candidate) => {
        candidate.classList.remove("is-source-target");
      });
      target.classList.add("is-source-target");
      reader.sourceRevealToken = null;
      if (evidenceAnchor?.passages?.length) {
        revealNotebookEvidencePassages(target, evidenceAnchor);
      }
      if (options.preferPassage) stabilizeReaderSectionAtHeader(content, target, "auto");
      else scrollReaderContentToNode(content, target, "auto");
    }, delay);
  });
}

async function resolveReaderSourceMetadata({sectionID, codePrefix, sectionNumber, codeVersion, hasExplicitVersion}) {
  const params = new URLSearchParams({include: "metadata"});
  if (sectionID) {
    if (hasExplicitVersion) params.set("version", codeVersion);
    return (await api(`/code/sections/${encodeURIComponent(sectionID)}?${params}`)).section;
  }
  // Resolve citation numbers against catalog metadata only. Search snippets and
  // passage bodies must not load before a disabled source is explicitly enabled.
  if (!normalizedInlineSectionNumber(sectionNumber)) {
    throw new Error("This reference has no exact section identity or section number.");
  }
  params.set("code", codePrefix);
  params.set("sectionNumber", sectionNumber);
  params.set("version", codeVersion);
  return (await api(`/code/sections/resolve?${params}`)).section;
}

async function resolveReaderSource(item, options = {}) {
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const isCurrent = () => isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === workspaceID &&
    (options.isCurrent?.() ?? true);
  const sourcePrefix = String(item.codePrefix || item.codeBook || "").trim().toUpperCase();
  const codePrefix = sourcePrefix || "BC";
  const sectionNumber = String(item.sectionNumber || "").trim();
  const sourceVersion = String(item.codeVersion || item.sourceLibraryVersion || "").trim();
  const codeVersion = syncCodeVersion(sourceVersion || syncCodeVersionForPrefix(codePrefix));
  // A saved source's id identifies the evidence record, not necessarily the
  // enacted section. Never replace a canonical section with a number lookup.
  const sectionID = String(item.sectionID || (/^\d+$/.test(String(item.id || "")) ? item.id : "")).trim();
  function validateMetadata(resolved) {
    const resolvedID = String(resolved?.sectionID || resolved?.id || "").trim();
    const resolvedPrefix = String(resolved?.codePrefix || "").trim().toUpperCase();
    const resolvedVersion = resolved?.codeVersion ? syncCodeVersion(resolved.codeVersion) : "";
    if (
      !resolvedID ||
      !resolvedPrefix ||
      !resolvedVersion ||
      !(resolved?.navigationChapterID || resolved?.chapterID) ||
      ((sourcePrefix || !sectionID) && resolvedPrefix !== codePrefix) ||
      ((sourceVersion || !sectionID) && resolvedVersion !== codeVersion) ||
      (sectionID && resolvedID !== sectionID && String(resolved.webSectionID || "") !== sectionID) ||
      (!sectionID && normalizedInlineSectionNumber(resolved.sectionNumber) !== normalizedInlineSectionNumber(sectionNumber))
    ) {
      throw new Error("This source could not be matched to its exact code section and edition. Reopen the saved evidence or refresh its sources before continuing.");
    }
    return {resolvedID, resolvedPrefix, resolvedVersion};
  }
  const trustedSource = item.codeSource && sectionID && (item.navigationChapterID || item.chapterID) &&
    syncCodeVersion(item.codeSource.canonicalEdition) === codeVersion ? item.codeSource : null;
  const metadataTarget = {...item};
  if (trustedSource) validateMetadata(metadataTarget);
  const guardNavigation = createActiveCodeSourceNavigationGuard({
    controller: activeCodeSourcesController,
    async resolveTarget() {
      const section = await resolveReaderSourceMetadata({
        sectionID, codePrefix, sectionNumber, codeVersion, hasExplicitVersion: Boolean(sourceVersion)
      });
      validateMetadata(section);
      return {target: section, source: section?.codeSource};
    },
    confirmEnable: ({catalogEntry}) => confirmWebWarning(
      "Enable source and open?",
      `${catalogEntry.categoryLabel || catalogEntry.codePrefix || "This code source"} is turned off. Enable it to open this exact passage.`,
      {confirmLabel: "Enable and open", cancelLabel: "Cancel"}
    )
  });
  const navigation = await guardNavigation({target: metadataTarget, source: trustedSource || undefined, isCurrent});
  if (!navigation) return null;
  const resolved = navigation.target;
  const {resolvedID, resolvedPrefix, resolvedVersion} = validateMetadata(resolved);
  return {
    ...item,
    ...resolved,
    id: resolvedID,
    sectionID: resolvedID,
    codePrefix: resolvedPrefix,
    codeVersion: resolvedVersion,
    codeSource: navigation.source,
    __activeCodeSourceContext: navigation.context
  };
}

function reusableSearchReader(readers, anchorPaneID, forceNewReader = false) {
  if (forceNewReader || !anchorPaneID) return null;
  return readers.find((reader) => reader.searchPreviewPaneID === anchorPaneID) || null;
}

const searchReaderOpeningAttempts = new Map();

function retainReaderForSource(reader, detail) {
  if (!reader || String(reader.chapterID) !== String(detail.chapterID) ||
      reader.codePrefix !== detail.codePrefix || reader.codeVersion !== detail.codeVersion) return null;
  const panel = track.querySelector(`.reader-panel[data-pane-id="${CSS.escape(paneIDForReader(reader))}"]`);
  const content = panel?.querySelector(".reader-content");
  if (!content || panel.dataset.workspacePaneLoading || content.classList.contains("is-searching-reader") ||
      panel.dataset.readerPublicCorpusGeneration !== String(publicCodeRevision.generation)) return null;
  const section = [...content.querySelectorAll(".chapter-section")].find(node =>
    node.dataset.sectionId === String(detail.sectionID) ||
    node.dataset.sectionAliases?.split(/\s+/).includes(String(detail.sectionID)));
  return section && savedReaderTarget(content, detail, {preferPassage: true}) ? panel : null;
}

async function openSourceInReader(item, anchorPaneID = "", options = {}) {
  if (workspaceColumnsRequireProject()) return null;
  if (currentColumnWorkflowView() === "report") {
    if (!await switchWorkflowView("research")) return null;
    anchorPaneID = "";
  }
  const requestIdentity = captureAccountRequest();
  const sourceWorkspaceID = activeWorkspaceID;
  const workflowGeneration = state.workflowNavigationGeneration || 0;
  const searchOpening = options.sourceSurface === "search" && !options.forceNewReader;
  const openingAttempt = searchOpening ? Symbol() : null;
  if (searchOpening) searchReaderOpeningAttempts.set(anchorPaneID, openingAttempt);
  let navigationItem;
  const navigationIsCurrent = () => isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === sourceWorkspaceID &&
    !workspaceColumnsRequireProject() && workflowGeneration === (state.workflowNavigationGeneration || 0) &&
    (!navigationItem?.__activeCodeSourceContext || activeCodeSourcesController.isCurrent(navigationItem.__activeCodeSourceContext)) &&
    (!searchOpening || searchReaderOpeningAttempts.get(anchorPaneID) === openingAttempt);
  try {
    navigationItem = await resolveReaderSource(item, {isCurrent: navigationIsCurrent});
  } catch (error) {
    if (!navigationIsCurrent()) return null;
    await showWebNotice("Source could not be opened", error.message || "The exact source is unavailable.");
    return null;
  }
  if (!navigationItem || !navigationIsCurrent()) return null;
  const detail = searchResultDetail(navigationItem);
  const sourceFields = readerFieldsForSectionDetail(detail, {
    shouldSmoothScrollToSection: false,
    sourceAnchorPaneID: anchorPaneID,
    sourceProjectID: String(options.projectID || ""),
    sourceBlockID: normalizeAnnotationBlockID(detail.blockID)
  });
  const fromSearch = options.sourceSurface === "search";
  const visibleReaders = (state.readers || []).filter(candidate => workflowPaneIsVisible(paneIDForReader(candidate)));
  let reader = fromSearch
    ? reusableSearchReader(visibleReaders, anchorPaneID, options.forceNewReader)
    : visibleReaders.find((candidate) =>
      (!anchorPaneID || candidate.sourceAnchorPaneID === anchorPaneID) && readerMatchesSource(candidate, detail));
  if (!reader && !fromSearch) {
    reader = visibleReaders.find(readerIsClearlyAvailable) || null;
  }
  if (!reader && anchorPaneID && options.sourceSurface !== "search") {
    reader = visibleReaders.find((candidate) => candidate.sourceAnchorPaneID === anchorPaneID);
  }
  if (!reader) {
    if (isProAccount() || state.readers.length < 2) {
      reader = newReaderState(sourceFields);
      state.readers.push(reader);
    } else if (options.sourceSurface === "search") {
      const replacement = searchReaderReplacementCandidate(anchorPaneID);
      const confirmed = await confirmSearchReaderReplacement(replacement, detail, anchorPaneID);
      if (!confirmed || !navigationIsCurrent()) return null;
      reader = replacement;
    } else {
      const replacement = visibleReaders.find(candidate => paneIDForReader(candidate) !== anchorPaneID) || state.readers[0];
      if (!await confirmSearchReaderReplacement(replacement, detail, anchorPaneID) || !navigationIsCurrent()) return null;
      reader = replacement;
    }
  }
  const retainedPanel = fromSearch && !options.forceNewReader ? retainReaderForSource(reader, detail) : null;
  Object.assign(reader, sourceFields);
  resolvedReaderSourceNavigations.set(reader, {chapterID: reader.chapterID, sectionID: reader.sectionID,
    sectionNumber: reader.sectionNumber, codePrefix: reader.codePrefix, codeVersion: reader.codeVersion});
  if (fromSearch) reader.searchPreviewPaneID = options.forceNewReader ? "" : anchorPaneID;
  const paneID = paneIDForReader(reader);
  state.paneWeights[paneID] ||= defaultPaneWidthForID(paneID);
  if (anchorPaneID && anchorPaneID !== paneID) placePaneAfter(anchorPaneID, paneID);
  else appendPaneIfMissing(paneID);
  if (reader.sectionID) updateBrowserSectionURL(reader.sectionID);
  scheduleContinuitySync(reader);
  saveWorkspaceState();
  if (retainedPanel) {
    retainedPanel.dataset.workspacePaneIdentity = workspaceReaderContentIdentity(reader);
    retainedPanel.dataset.readerContentKey = readerContentScrollKey(reader);
    retainedPanel.querySelector(".section-select").value = reader.sectionID || "";
    setTitle(retainedPanel, reader);
  }
  await transitionWorkspace("utility", { refreshPaneIDs: retainedPanel ? [] : [paneID] });
  if (!navigationIsCurrent() || !await whenWorkspacePaneReady(paneID) || !navigationIsCurrent()) return null;
  revealReaderSourceTarget(reader, navigationItem, options.evidenceAnchor, {preferPassage: fromSearch});
  scrollPaneIntoView(paneID);
  return reader;
}

function removeSectionDetail(searchID) {
  closeLinkedReaderForSearch(searchID);
  delete sectionDetailsBySearch()[searchID];
  delete sectionDetailAnchorsBySearch()[searchID];
  const detailPaneID = paneIDForSectionDetail(searchID);
  delete state.paneWeights[detailPaneID];
  state.paneOrder = (state.paneOrder || []).filter((paneID) => paneID !== detailPaneID);
  state.utilityInstances = (state.utilityInstances || []).filter((instance) =>
    instance.id !== searchID || instance.key !== "sdc"
  );
}

function closeSavedItemDetailsForPane(savedPaneID) {
  savedItemDetailIDsForPane(savedPaneID).forEach(removeSectionDetail);
}

function savedItemDetailIDsForPane(savedPaneID) {
  const details = sectionDetailsBySearch();
  const anchors = sectionDetailAnchorsBySearch();
  const savedDetailIDs = new Set((state.utilityInstances || [])
    .filter((instance) => instance.key === "sdc").map((instance) => instance.id));
  // Match the same fallback anchor used to place older saved-detail columns.
  return Object.keys(details).filter((searchID) =>
    (anchors[searchID] || (savedDetailIDs.has(searchID) ? primarySavedPaneID() : "")) === savedPaneID);
}

const savedItemOpeningAttempts = new Map();

async function openSavedItemInReader(item, savedPaneID) {
  const attempt = {};
  savedItemOpeningAttempts.set(savedPaneID, attempt);
  try {
  const sectionID = String(item?.sectionID || item?.id || "").trim();
  if (!sectionID) return;
  const requestIdentity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const workflowGeneration = state.workflowNavigationGeneration || 0;
  const isCurrent = () => savedItemOpeningAttempts.get(savedPaneID) === attempt &&
    isCurrentAccountRequest(requestIdentity) && activeWorkspaceID === workspaceID &&
    workflowGeneration === (state.workflowNavigationGeneration || 0);
  let navigationItem = {
    ...item,
    id: sectionID,
    sectionID
  };
  try {
    navigationItem = await resolveReaderSource(navigationItem, { isCurrent });
  } catch (error) {
    if (isCurrent()) await showWebNotice("Saved section unavailable", error.message || "This exact source could not be opened.");
    return;
  }
  if (!navigationItem || !isCurrent() || !isCurrentActiveCodeSourceContext(navigationItem.__activeCodeSourceContext)) return;
  const existingDetailID = Object.entries(sectionDetailAnchorsBySearch()).find(
    ([id, anchor]) => anchor === savedPaneID && sectionDetailsBySearch()[id]
  )?.[0];
  const detailInstance = (state.utilityInstances || []).find(
    (instance) => instance.id === existingDetailID && instance.key === "sdc"
  ) || newUtilityInstance("sdc");
  if (!(state.utilityInstances || []).includes(detailInstance)) {
    state.utilityInstances = [...(state.utilityInstances || []), detailInstance];
  }
  let publishedDetail;
  try {
    const opening = openSectionDetail(detailInstance.id, navigationItem, {
      isCurrent,
      anchorPaneID: savedPaneID,
      updateURL: false,
      updateLinkedReader: false,
      evidenceAnchor: item?.evidenceAnchor || null
    });
    publishedDetail = sectionDetailsBySearch()[detailInstance.id];
    await opening;
  } catch {
    if (!isCurrent() || !isCurrentActiveCodeSourceContext(navigationItem.__activeCodeSourceContext) ||
        !publishedDetail || sectionDetailsBySearch()[detailInstance.id] !== publishedDetail) return;
    removeSectionDetail(detailInstance.id);
    saveWorkspaceState();
    await showWebNotice(
      "Saved section unavailable",
      navigator.onLine === false
        ? "Connect to the internet, then open this saved section again. For offline reading, download the code library in Account while Pro is active."
        : "This saved section could not be loaded. Check your connection, then open it again. Your saved item has not been removed."
    );
    return;
  }
  if (!isCurrent() || sectionDetailsBySearch()[detailInstance.id] !== publishedDetail || !isCurrentActiveCodeSourceContext(navigationItem.__activeCodeSourceContext)) return;

  scrollPaneIntoView(paneIDForSectionDetail(detailInstance.id));
  } finally {
    if (savedItemOpeningAttempts.get(savedPaneID) === attempt) savedItemOpeningAttempts.delete(savedPaneID);
  }
}

async function startFocusedResearchFromSavedItem(item, projectID = "") {
  const sectionID = String(item?.sectionID || item?.id || "").trim();
  const selectedText = String(item?.previewText || item?.selectedText || item?.title || "").trim();
  if (!sectionID || !selectedText) throw new Error("This saved passage does not have enough source text for Research.");
  const savedItemID = item?.savedColumnKind === "bookmark" ? String(item.id || "") : "";
  return startNewResearchFromSelection({
    sectionID,
    selectedText,
    savedItemID,
    projectID: String(projectID || "").trim(),
    originPaneID: primarySavedPaneID(),
    originSurface: "saved"
  });
}

function normalizedPublicUsername(value) {
  const trimmed = String(value || "").trim().replace(/^@/, "").toLowerCase();
  return trimmed || null;
}

function publicUsernameValidationMessage(value) {
  const username = normalizedPublicUsername(value);
  if (!username) return "";
  if (username.length < 3) return "Use at least 3 characters.";
  if (username.length > 30) return "Use 30 characters or fewer.";
  if (!/^[a-z0-9_-]+$/.test(username)) return "Use letters, numbers, hyphens, or underscores.";
  return "";
}

function bookmarkRecordsForSettings() {
  return (currentContentSummary().savedItems || [])
    .filter((item) => item?.sectionID && !item.deletedAt);
}

function enqueueSettingsBulkClear(scope, options = {}) {
  const account = activeAccount();
  if (!account) return null;
  const mutation = {
    codeVersionClear: {
      userID: account.userID,
      codeVersion: options.codeVersion || defaultSyncCodeVersion,
      values: { scope },
      updatedAt: new Date().toISOString()
    }
  };
  const record = mutation.codeVersionClear;
  const key = bulkClearKey(record);
  state.localBulkClears = [
    ...(state.localBulkClears || []).filter((item) => bulkClearKey(item) !== key),
    record
  ];
  enqueueSyncMutation(mutation, account, options);
  return mutation;
}

function enqueueSettingsClearForAllCodes(scope, records, options = {}) {
  const versions = new Set([defaultSyncCodeVersion, historicalConstructionSyncCodeVersion,
    zoningSyncCodeVersion, existingBuildingSyncCodeVersion, enactedAdministrativeSyncCodeVersion,
    specialtyCodesSyncCodeVersion, ...records.map(item => syncCodeVersion(item.codeVersion))]);
  for (const codeVersion of versions) enqueueSettingsBulkClear(scope, {...options, codeVersion});
}

let openTrashAfterSettingsDeletion = false;

async function prepareRecoverableDeletion() {
  requirePrivateWorkspaceWritable();
  const identity = captureAccountRequest();
  const account = activeAccount();
  if (!account) throw new Error("Sign in and connect before deleting saved content.");
  await flushSyncOutbox({ refresh: true });
  requireCurrentAccountRequest(identity);
  if ([...(state.syncOutbox || []), ...(state.syncConflicts || [])].some(item => item.accountUserID === account.userID)) {
    throw new Error("Finish syncing or resolve sync conflicts before deleting saved content.");
  }
  await loadSyncedContent({ force: true, skipOutbox: true });
  requireCurrentAccountRequest(identity);
  // A missing or unavailable recovery service must never fall back to permanent removal.
  await postResearch("/content/trash", { action: "list" });
  requireCurrentAccountRequest(identity);
}

function attachSettingsTrash(panel) {
  const details = panel.querySelector(".settings-trash");
  const list = panel.querySelector(".settings-trash-list");
  const status = panel.querySelector(".settings-trash-status");
  const refresh = panel.querySelector(".settings-trash-refresh");
  const identity = captureAccountRequest();
  let busy = false;
  const update = async (action = "list", id, confirmation) => {
    if (busy || !isCurrentAccountRequest(identity)) return;
    busy = true;
    refresh.disabled = true;
    list.querySelectorAll("button, input").forEach(control => { control.disabled = true; });
    status.textContent = "Loading Trash…";
    try {
      if (action !== "list") await prepareRecoverableDeletion();
      const result = await postResearch("/content/trash", {action, id, confirmation});
      if (!isCurrentAccountRequest(identity)) return;
      if (action === "restore") {
        await loadSyncedContent({force: true, skipOutbox: true});
        requireCurrentAccountRequest(identity);
        openTrashAfterSettingsDeletion = true;
        await refreshWorkspaceAfterSettingsClear(settingsPanelScrollTop(panel), track.scrollLeft);
        return;
      }
      status.textContent = result.entries.length ? "Choose a deletion to restore or permanently remove." : "Trash is empty.";
      list.replaceChildren();
      const button = (label, click) => {
        const element = document.createElement("button");
        element.type = "button";
        element.className = "settings-secondary-button";
        element.textContent = label;
        element.addEventListener("click", click);
        return element;
      };
      const permanent = (container, action, id) => {
        if (container.querySelector(".settings-trash-confirm")) return;
        const form = document.createElement("div");
        form.className = "settings-trash-confirm";
        const copy = document.createElement("p");
        copy.textContent = action === "empty"
          ? "Permanently remove every recovery copy from this account’s Trash? This cannot be undone."
          : "Permanently remove this recovery copy from the account? This cannot be undone.";
        const label = document.createElement("label");
        label.textContent = "Type DELETE to confirm";
        const input = document.createElement("input");
        input.autocomplete = "off";
        input.spellcheck = false;
        label.append(input);
        const confirm = button("Delete Permanently", () => update(action, id, input.value));
        confirm.disabled = true;
        input.addEventListener("input", () => { confirm.disabled = input.value !== "DELETE"; });
        form.append(copy, label, confirm, button("Cancel", () => form.remove()));
        container.append(form);
        input.focus();
      };
      for (const entry of result.entries) {
        const row = document.createElement("div");
        row.className = "settings-trash-entry";
        const title = document.createElement("strong"); title.textContent = entry.title;
        const date = document.createElement("p"); date.textContent = `Available until ${new Date(entry.expiresAt).toLocaleDateString()}`;
        row.append(title, date, button("Restore / Undo", () => update("restore", entry.id)), button("Delete Permanently…", () => permanent(row, "purge", entry.id)));
        list.append(row);
      }
      if (result.entries.length) list.append(button("Empty Trash…", () => permanent(list, "empty")));
    } catch (error) {
      if (isCurrentAccountRequest(identity)) status.textContent = error.message || "Trash is unavailable. Please reconnect and retry.";
    } finally {
      busy = false;
      refresh.disabled = false;
      // Render again after failed mutations so disabled controls cannot get stranded.
      list.querySelectorAll("button, input").forEach(control => { if (control.textContent !== "Delete Permanently") control.disabled = false; });
    }
  };
  details.addEventListener("toggle", () => { if (details.open) update(); });
  refresh.addEventListener("click", () => update());
}

async function clearSettingsBookmarks() {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const summary = currentContentSummary();
  const records = bookmarkRecordsForSettings();
  const projectSections = (summary.projectSections || [])
    .filter((item) => item?.sectionID && !item.deletedAt);
  const folders = visibleProjectRecords(summary.projects || []);
  const savedTombstones = records.map((record) =>
    deletedSavedMutationForSection(record, record).savedItem
  );
  const membershipTombstones = projectSections.map((item) => {
    const folder = folders.find((candidate) => projectSectionBelongsToProject(item, candidate)) || {
      id: item.localFolderID || item.folderClientID,
      clientID: item.folderClientID || item.localFolderID,
      folderType: item.folderType || "project"
    };
    return deletedProjectSectionMutationForItem(folder, item).projectSection;
  });
  const account = activeAccount();
  // Keep explicit tombstones locally and in the durable outbox. The bulk-clear
  // marker prevents older offline records from returning, while the tombstones
  // remove every known folder membership even if its timestamp is newer than
  // the marker because it was echoed or edited by another device.
  state.localSavedItems = savedTombstones;
  state.localSavedSectionIDs = [];
  state.localProjectSections = membershipTombstones;
  const operationGroupID = crypto.randomUUID();
  if (account) {
    savedTombstones.forEach((record) => enqueueSyncMutation(
      { savedItem: record },
      account,
      { operationGroupID }
    ));
    membershipTombstones.forEach((record) => enqueueSyncMutation(
      { projectSection: record },
      account,
      { operationGroupID }
    ));
  }
  enqueueSettingsClearForAllCodes("bookmarks", [...records, ...projectSections], { operationGroupID });
  saveWorkspaceState();
  if (account) await flushSyncOutbox({ refresh: true }).catch(() => {});
  requireCurrentAccountRequest(requestIdentity);
  return records.length;
}

async function clearSettingsNotes() {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  const records = (currentContentSummary().annotations || []).filter(item => String(item.noteBody || "").trim());
  const uniqueTargets = new Map();
  records.forEach((record) => {
    const key = `${syncCodeVersion(record.codeVersion)}:${record.sectionID || ""}:${normalizeAnnotationBlockID(record.blockID)}`;
    if (!uniqueTargets.has(key)) uniqueTargets.set(key, record);
  });
  uniqueTargets.forEach((record) => {
    const localRecord = (state.localAnnotations || []).find((item) => String(item.id || "") === String(record.id || ""));
    if (!localRecord) return;
    localRecord.noteBody = "";
  });
  state.sectionNotes = {};
  enqueueSettingsClearForAllCodes("notes", records, {operationGroupID: crypto.randomUUID()});
  saveWorkspaceState();
  if (activeAccount()) await flushSyncOutbox({ refresh: true }).catch(() => {});
  requireCurrentAccountRequest(requestIdentity);
  return uniqueTargets.size;
}

async function performSettingsClearAction(action) {
  requirePrivateWorkspaceWritable();
  const requestIdentity = captureAccountRequest();
  if (action === "searches") {
    state.recentSearches = [];
    state.recentSearchHistory = [];
    state.recentlyViewedSections = [];
    state.recentActivityUpdatedAt = new Date().toISOString();
    const account = activeAccount();
    if (account) {
      const pendingRecord = [...(state.syncOutbox || [])].reverse()
        .filter((entry) => entry.accountUserID === account.userID)
        .map((entry) => mutationKindAndRecord(entry.mutation))
        .find(({ kind }) => kind === "continuity")?.record;
      const existing = pendingRecord?.values || syncedContent?.summary?.latestContinuity?.values || {};
      const updatedAt = new Date().toISOString();
      enqueueSyncMutation({
        continuity: {
          userID: account.userID,
          codeVersion: defaultSyncCodeVersion,
          values: {
            ...existing,
            recentlyViewedSectionsJSON: "[]",
            recentSearchesJSON: "[]",
            recentSearchHistoryJSON: "[]"
          },
          updatedAt
        }
      }, account);
      state.continuityAppliedAt = updatedAt;
      if (syncedContent?.summary?.latestContinuity) {
        syncedContent.summary.latestContinuity = {
          ...syncedContent.summary.latestContinuity,
          values: {
            ...existing,
            recentlyViewedSectionsJSON: "[]",
            recentSearchesJSON: "[]",
            recentSearchHistoryJSON: "[]"
          },
          updatedAt
        };
      }
    }
    saveWorkspaceState();
    if (account) await flushSyncOutbox({ refresh: true }).catch(() => {});
    requireCurrentAccountRequest(requestIdentity);
    return 0;
  }
  if (action === "bookmarks") return clearSettingsBookmarks();
  if (action === "notes") return clearSettingsNotes();
  return 0;
}

function organizationInvitationTokenFromURL() {
  if (!releaseSurfaceVisibility.firmCollaboration) return "";
  return new URLSearchParams(window.location.search).get("organizationInvite") || "";
}

function clearOrganizationInvitationURL() {
  const url = new URL(window.location.href);
  url.searchParams.delete("organizationInvite");
  window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}` || "/");
}

function firmControlLabel(text, control) {
  const label = document.createElement("label");
  label.className = "settings-firm-field";
  const caption = document.createElement("span");
  caption.textContent = text;
  label.append(caption, control);
  return label;
}

async function refreshOrganizationWorkspaceUI() {
  await loadOrganizationWorkspace({ force: true });
  const refreshPaneIDs = activePaneIDs().filter((paneID) =>
    paneID === "utility:settings" ||
    paneID.startsWith("utility:saved:") ||
    isProjectDetailPaneID(paneID) ||
    isProjectNotebookPaneID(paneID)
  );
  await transitionWorkspace("utility", { refreshPaneIDs });
}

async function renderFirmMemberManager(container, organization, setFirmStatus) {
  container.replaceChildren();
  const loading = document.createElement("p");
  loading.className = "settings-firm-muted";
  loading.textContent = "Loading members…";
  container.append(loading);
  try {
    const payload = await postResearch("/organizations/members/list", {
      organizationID: organization.id
    });
    container.replaceChildren();
    const members = [
      ...(payload.members || []).map((membership) => ({ ...membership, scope: "Firm" })),
      ...(payload.projectMembers || []).map((membership) => ({
        ...membership,
        scope: (organization.projects || []).find((project) => project.id === membership.projectID)?.name ||
          "Project"
      }))
    ];
    const unique = new Map();
    members.forEach((membership) => {
      const key = `${membership.projectID || "firm"}:${membership.userID}`;
      unique.set(key, membership);
    });
    if (!unique.size) {
      const empty = document.createElement("p");
      empty.className = "settings-firm-muted";
      empty.textContent = "No members yet.";
      container.append(empty);
    }
    unique.forEach((membership) => {
      const row = document.createElement("article");
      row.className = "settings-firm-member";
      const copy = document.createElement("div");
      const name = document.createElement("strong");
      name.textContent = membership.account?.displayName ||
        membership.account?.email ||
        membership.userID;
      const meta = document.createElement("span");
      meta.textContent = `${membership.scope} · ${membership.status}`;
      copy.append(name, meta);
      row.append(copy);
      if (membership.role === "owner") {
        const role = document.createElement("span");
        role.className = "settings-firm-role";
        role.textContent = "Owner";
        row.append(role);
      } else {
        const roleSelect = document.createElement("select");
        roleSelect.setAttribute("aria-label", `Role for ${name.textContent}`);
        ["editor", "reviewer", "viewer"].forEach((role) => {
          const option = document.createElement("option");
          option.value = role;
          option.textContent = role[0].toUpperCase() + role.slice(1);
          roleSelect.append(option);
        });
        roleSelect.value = membership.role;
        const statusButton = document.createElement("button");
        statusButton.className = "settings-mini-button";
        statusButton.type = "button";
        statusButton.textContent = membership.status === "active" ? "Remove" : "Restore";
        const updateMembership = async (values) => {
          roleSelect.disabled = true;
          statusButton.disabled = true;
          try {
            await postResearch("/organizations/members/update", {
              organizationID: organization.id,
              projectID: membership.projectID || undefined,
              userID: membership.userID,
              ...values
            });
            setFirmStatus("Member access updated.");
            await refreshOrganizationWorkspaceUI();
          } catch (error) {
            setFirmStatus(error.message || "Member access could not be updated.", true);
            roleSelect.disabled = false;
            statusButton.disabled = false;
          }
        };
        roleSelect.addEventListener("change", () => {
          void updateMembership({ role: roleSelect.value });
        });
        statusButton.addEventListener("click", () => {
          void updateMembership({
            status: membership.status === "active" ? "deactivated" : "active"
          });
        });
        const actions = document.createElement("div");
        actions.className = "settings-firm-member-actions";
        actions.append(roleSelect, statusButton);
        row.append(actions);
      }
      container.append(row);
    });
    (payload.invitations || []).filter((invitation) => invitation.state === "pending")
      .forEach((invitation) => {
        const row = document.createElement("article");
        row.className = "settings-firm-member is-pending";
        const copy = document.createElement("div");
        const name = document.createElement("strong");
        name.textContent = invitation.invitedEmail || invitation.invitedUserID || "Pending invitation";
        const meta = document.createElement("span");
        const scope = invitation.projectID
          ? (organization.projects || []).find((project) => project.id === invitation.projectID)?.name || "Project"
          : "Firm";
        meta.textContent = `${scope} · ${invitation.role} · pending`;
        copy.append(name, meta);
        const revoke = document.createElement("button");
        revoke.className = "settings-mini-button";
        revoke.type = "button";
        revoke.textContent = "Revoke";
        revoke.addEventListener("click", async () => {
          revoke.disabled = true;
          try {
            await postResearch("/organizations/invitations/revoke", {
              organizationID: organization.id,
              invitationID: invitation.id
            });
            setFirmStatus("Invitation revoked.");
            await refreshOrganizationWorkspaceUI();
          } catch (error) {
            setFirmStatus(error.message || "Invitation could not be revoked.", true);
            revoke.disabled = false;
          }
        });
        row.append(copy, revoke);
        container.append(row);
      });
  } catch (error) {
    loading.textContent = error.message || "Members could not be loaded.";
  }
}

function renderFirmStandardsEditor(organization, setFirmStatus) {
  const details = document.createElement("details");
  details.className = "settings-firm-standards";
  const summary = document.createElement("summary");
  summary.textContent = "Firm standards & Report templates";
  const editor = document.createElement("div");
  details.append(summary, editor);
  let controls = structuredClone(organization.firmControls || {});
  const lines = (value) => String(value || "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const render = () => {
    editor.replaceChildren();
    const intro = document.createElement("p");
    intro.className = "settings-firm-muted";
    intro.textContent = `Revision ${controls.version || 1}. New Reports snapshot these settings; older Reports never change.`;
    editor.append(intro);

    const branding = document.createElement("section");
    branding.className = "settings-firm-standard-section";
    const brandingTitle = document.createElement("strong");
    brandingTitle.textContent = "Report branding";
    const displayName = document.createElement("input");
    displayName.value = controls.branding?.displayName || organization.name;
    displayName.maxLength = 160;
    displayName.addEventListener("input", () => {
      controls.branding.displayName = displayName.value;
    });
    const accent = document.createElement("input");
    accent.type = "color";
    accent.value = controls.branding?.accentColorHex || "#a65318";
    accent.addEventListener("input", () => {
      controls.branding.accentColorHex = accent.value;
    });
    const website = document.createElement("input");
    website.type = "url";
    website.value = controls.branding?.website || "";
    website.placeholder = "https://firm.example";
    website.addEventListener("input", () => {
      controls.branding.website = website.value;
    });
    const footer = document.createElement("input");
    footer.value = controls.branding?.footerText || "";
    footer.maxLength = 500;
    footer.placeholder = "Optional PDF footer";
    footer.addEventListener("input", () => {
      controls.branding.footerText = footer.value;
    });
    const requiredDisclaimers = document.createElement("textarea");
    requiredDisclaimers.value = (controls.requiredDisclaimers || []).join("\n");
    requiredDisclaimers.placeholder = "One required firm disclaimer per line";
    requiredDisclaimers.addEventListener("input", () => {
      controls.requiredDisclaimers = lines(requiredDisclaimers.value);
    });
    branding.append(
      brandingTitle,
      firmControlLabel("Firm display name", displayName),
      firmControlLabel("Accent color", accent),
      firmControlLabel("Website", website),
      firmControlLabel("PDF footer", footer),
      firmControlLabel("Required disclaimers", requiredDisclaimers)
    );
    editor.append(branding);

    const templatesSection = document.createElement("section");
    templatesSection.className = "settings-firm-standard-section";
    const templatesHeading = document.createElement("div");
    templatesHeading.className = "settings-firm-standard-heading";
    const templatesTitle = document.createElement("strong");
    templatesTitle.textContent = "Report templates";
    const addTemplate = document.createElement("button");
    addTemplate.className = "settings-secondary-button";
    addTemplate.type = "button";
    addTemplate.textContent = "Add template";
    addTemplate.addEventListener("click", () => {
      const now = new Date().toISOString();
      const templateID = crypto.randomUUID();
      controls.reportTemplates ||= [];
      controls.reportTemplates.push({
        id: templateID,
        name: "New template",
        description: "",
        coverLabel: "Project Code Report",
        disclaimers: [],
        status: "active",
        createdAt: now,
        updatedAt: now,
        order: controls.reportTemplates.length
      });
      const currentDefaultIsActive = controls.reportTemplates.some((template) =>
        template.id === controls.defaultReportTemplateID && template.status === "active"
      );
      if (!currentDefaultIsActive) controls.defaultReportTemplateID = templateID;
      render();
    });
    templatesHeading.append(templatesTitle, addTemplate);
    templatesSection.append(templatesHeading);
    (controls.reportTemplates || []).forEach((template) => {
      const card = document.createElement("article");
      card.className = "settings-firm-template";
      const name = document.createElement("input");
      name.value = template.name || "";
      name.maxLength = 120;
      name.addEventListener("input", () => {
        template.name = name.value;
      });
      const coverLabel = document.createElement("input");
      coverLabel.value = template.coverLabel || "";
      coverLabel.maxLength = 160;
      coverLabel.addEventListener("input", () => {
        template.coverLabel = coverLabel.value;
      });
      const description = document.createElement("textarea");
      description.value = template.description || "";
      description.placeholder = "Internal description";
      description.addEventListener("input", () => {
        template.description = description.value;
      });
      const disclaimers = document.createElement("textarea");
      disclaimers.value = (template.disclaimers || []).join("\n");
      disclaimers.placeholder = "One template disclaimer per line";
      disclaimers.addEventListener("input", () => {
        template.disclaimers = lines(disclaimers.value);
      });
      const status = document.createElement("select");
      [["active", "Active"], ["archived", "Archived"]].forEach(([value, label]) => {
        const option = document.createElement("option");
        option.value = value;
        option.textContent = label;
        status.append(option);
      });
      status.value = template.status || "active";
      status.addEventListener("change", () => {
        template.status = status.value;
        if (
          template.status === "archived" &&
          controls.defaultReportTemplateID === template.id
        ) {
          controls.defaultReportTemplateID = controls.reportTemplates.find((candidate) =>
            candidate.id !== template.id && candidate.status === "active"
          )?.id || "";
        }
        render();
      });
      const defaultTemplate = document.createElement("input");
      defaultTemplate.type = "radio";
      defaultTemplate.name = `default-report-template-${organization.id}`;
      defaultTemplate.checked = controls.defaultReportTemplateID === template.id;
      defaultTemplate.disabled = template.status !== "active";
      defaultTemplate.addEventListener("change", () => {
        if (defaultTemplate.checked) controls.defaultReportTemplateID = template.id;
      });
      const defaultLabel = document.createElement("label");
      defaultLabel.className = "settings-firm-default-template";
      defaultLabel.append(defaultTemplate, document.createTextNode("Default for new Reports"));
      card.append(
        firmControlLabel("Template name", name),
        firmControlLabel("Cover label", coverLabel),
        firmControlLabel("Description", description),
        firmControlLabel("Template disclaimers", disclaimers),
        firmControlLabel("Status", status),
        defaultLabel
      );
      templatesSection.append(card);
    });
    editor.append(templatesSection);

    const policy = document.createElement("section");
    policy.className = "settings-firm-standard-section";
    const policyTitle = document.createElement("strong");
    policyTitle.textContent = "Operating policies";
    const allowanceMode = document.createElement("select");
    [["pooled", "Pooled firm allowance"], ["per-seat", "Per-seat allowance"]]
      .forEach(([value, label]) => {
        const option = document.createElement("option");
        option.value = value;
        option.textContent = label;
        allowanceMode.append(option);
      });
    allowanceMode.value = controls.researchAllowance?.mode || "pooled";
    allowanceMode.addEventListener("change", () => {
      controls.researchAllowance.mode = allowanceMode.value;
    });
    const monthlyUnits = document.createElement("input");
    monthlyUnits.type = "number";
    monthlyUnits.min = "1";
    monthlyUnits.max = "100000";
    monthlyUnits.value = String(controls.researchAllowance?.monthlyUnits || 100);
    monthlyUnits.addEventListener("input", () => {
      controls.researchAllowance.monthlyUnits = Number(monthlyUnits.value);
    });
    const retentionDays = document.createElement("input");
    retentionDays.type = "number";
    retentionDays.min = "1";
    retentionDays.max = "36500";
    retentionDays.value = String(controls.retentionPolicy?.retentionDays || 2555);
    retentionDays.addEventListener("input", () => {
      controls.retentionPolicy.retentionDays = Number(retentionDays.value);
    });
    const usage = document.createElement("p");
    usage.className = "settings-firm-muted";
    usage.textContent = organization.researchUsage
      ? `${organization.researchUsage.requestsUsed}/${organization.researchUsage.requestLimit} Research requests recorded this period · resets ${new Date(organization.researchUsage.resetDate).toLocaleDateString()}.`
      : "Research usage will appear after this workspace refreshes.";
    const retentionNotice = document.createElement("p");
    retentionNotice.className = "settings-firm-muted";
    retentionNotice.textContent = "Retention is policy metadata only. Permitext will not automatically delete Project data.";
    const billingNotice = document.createElement("p");
    billingNotice.className = "settings-firm-muted";
    billingNotice.textContent = `${organization.billingIdentity.status} billing state · ${organization.billingIdentity.seatLimit} seats. Billing identifiers and subscription operations remain server-only.`;
    policy.append(
      policyTitle,
      firmControlLabel("Research allowance", allowanceMode),
      firmControlLabel("Monthly request units", monthlyUnits),
      usage,
      firmControlLabel("Retention period (days)", retentionDays),
      retentionNotice,
      billingNotice
    );
    editor.append(policy);

    const save = document.createElement("button");
    save.className = "settings-primary-button";
    save.type = "button";
    save.textContent = "Save Firm Standards";
    save.addEventListener("click", async () => {
      save.disabled = true;
      try {
        const payload = await postResearch("/organizations/controls/save", {
          organizationID: organization.id,
          expectedVersion: controls.version,
          controls
        });
        controls = structuredClone(payload.organization.firmControls);
        setFirmStatus(`Firm standards saved as revision ${controls.version}.`);
        await refreshOrganizationWorkspaceUI();
      } catch (error) {
        if (error.payload?.controls) controls = structuredClone(error.payload.controls);
        setFirmStatus(error.message || "Firm standards could not be saved.", true);
        save.disabled = false;
      }
    });
    editor.append(save);
  };
  details.addEventListener("toggle", () => {
    if (details.open && !editor.childElementCount) render();
  });
  return details;
}

async function renderFirmWorkspaceSettings(panel, settingsProjects, setStatus) {
  const container = panel.querySelector(".settings-firm-content");
  if (!container) return;
  container.replaceChildren();
  const setFirmStatus = (message, isError = false) => {
    setStatus(message, isError);
    const inline = container.querySelector(".settings-firm-status");
    if (inline) {
      inline.textContent = message || "";
      inline.classList.toggle("has-error", isError);
    }
  };
  const account = activeAccount();
  if (!account) {
    const message = document.createElement("p");
    message.className = "settings-firm-muted";
    message.textContent = organizationInvitationTokenFromURL()
      ? "Sign in to review and accept this firm invitation."
      : "Sign in to create a firm workspace or open Projects shared with you.";
    container.append(message);
    return;
  }

  const pendingInvitationToken = organizationInvitationTokenFromURL();
  if (pendingInvitationToken) {
    const invitation = document.createElement("section");
    invitation.className = "settings-firm-invitation";
    const copy = document.createElement("div");
    const title = document.createElement("strong");
    title.textContent = "Firm invitation";
    const detail = document.createElement("span");
    detail.textContent = "Accept only if you recognize the firm or Project that shared this link.";
    copy.append(title, detail);
    const accept = document.createElement("button");
    accept.className = "settings-primary-button";
    accept.type = "button";
    accept.textContent = "Accept Invitation";
    accept.addEventListener("click", async () => {
      accept.disabled = true;
      try {
        const payload = await postResearch("/organizations/invitations/accept", {
          invitationToken: pendingInvitationToken
        });
        clearOrganizationInvitationURL();
        setFirmStatus(`Access added to ${payload.organization.name}.`);
        await refreshOrganizationWorkspaceUI();
      } catch (error) {
        setFirmStatus(error.message || "The invitation could not be accepted.", true);
        accept.disabled = false;
      }
    });
    invitation.append(copy, accept);
    container.append(invitation);
  }

  const workspace = await loadOrganizationWorkspace();
  const organizations = workspace.organizations || [];
  if (workspace.error) {
    const error = document.createElement("p");
    error.className = "settings-firm-muted has-error";
    error.textContent = workspace.error;
    container.append(error);
  }

  const creationForm = document.createElement("form");
  creationForm.className = "settings-firm-create";
  const nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.maxLength = 160;
  nameInput.placeholder = "Firm or team name";
  nameInput.setAttribute("aria-label", "Firm or team name");
  const createButton = document.createElement("button");
  createButton.className = "settings-primary-button";
  createButton.type = "submit";
  createButton.textContent = "Create Firm Workspace";
  createButton.disabled = !isProAccount();
  creationForm.append(nameInput, createButton);
  if (!isProAccount()) {
    const note = document.createElement("p");
    note.className = "settings-firm-muted";
    note.textContent = "Pro is required to create a firm workspace. Invited members can participate without buying a separate personal plan.";
    creationForm.append(note);
  }
  creationForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (!nameInput.value.trim() || createButton.disabled) return;
    createButton.disabled = true;
    try {
      const payload = await postResearch("/organizations/create", {
        name: nameInput.value.trim()
      });
      setFirmStatus(`${payload.organization.name} created with five private-beta seats.`);
      await refreshOrganizationWorkspaceUI();
    } catch (error) {
      setFirmStatus(error.message || "The firm workspace could not be created.", true);
      createButton.disabled = false;
    }
  });
  container.append(creationForm);

  if (!organizations.length) {
    const empty = document.createElement("p");
    empty.className = "settings-firm-muted";
    empty.textContent = "No firm workspaces yet.";
    container.append(empty);
  }

  for (const organization of organizations) {
    const card = document.createElement("article");
    card.className = "settings-firm-workspace";
    const heading = document.createElement("div");
    heading.className = "settings-firm-workspace-heading";
    const copy = document.createElement("div");
    const name = document.createElement("strong");
    name.textContent = organization.name;
    const meta = document.createElement("span");
    meta.textContent = [
      organization.role,
      organization.accessScope === "project" ? "Project access" : "Firm access",
      organization.seats ? `${organization.seats.used}/${organization.billingIdentity.seatLimit} seats` : ""
    ].filter(Boolean).join(" · ");
    copy.append(name, meta);
    const role = document.createElement("span");
    role.className = "settings-firm-role";
    role.textContent = organization.role || "member";
    heading.append(copy, role);
    card.append(heading);

    const projectList = document.createElement("div");
    projectList.className = "settings-firm-projects";
    (organization.projects || []).forEach((project) => {
      const button = document.createElement("button");
      button.className = "settings-firm-project";
      button.type = "button";
      const projectName = document.createElement("strong");
      projectName.textContent = project.name || "Untitled Project";
      const projectMeta = document.createElement("span");
      projectMeta.textContent = `${project.role || organization.role} · Open Project Studio`;
      button.append(projectName, projectMeta);
      button.addEventListener("click", () => {
        void openProjectDetail({
          ...project,
          clientID: project.id,
          sharedOrganizationID: organization.id,
          sharedOrganizationName: organization.name,
          sharedRole: project.role || organization.role,
          sharedPermissions: project.permissions || organization.permissions || [],
          sharedOnly: !settingsProjects.some((candidate) =>
            projectDetailKey(candidate) === String(project.id)
          )
        }, { sourcePaneID: "utility:settings" });
      });
      projectList.append(button);
    });
    if (!organization.projects?.length) {
      const empty = document.createElement("p");
      empty.className = "settings-firm-muted";
      empty.textContent = "No Projects are shared in this workspace yet.";
      projectList.append(empty);
    }
    card.append(projectList);

    if (organization.permissions?.includes("project.transfer")) {
      const ownerTools = document.createElement("section");
      ownerTools.className = "settings-firm-owner-tools";
      const transferSelect = document.createElement("select");
      transferSelect.setAttribute("aria-label", "Personal Project to transfer");
      const transferPlaceholder = document.createElement("option");
      transferPlaceholder.value = "";
      transferPlaceholder.textContent = "Choose a personal Project…";
      transferSelect.append(transferPlaceholder);
      const organizationProjectIDs = new Set(
        organizations.flatMap((entry) => entry.projects || []).map((project) => String(project.id))
      );
      settingsProjects.filter((project) =>
        !organizationProjectIDs.has(projectDetailKey(project))
      ).forEach((project) => {
        const option = document.createElement("option");
        option.value = projectDetailKey(project);
        option.textContent = readableProjectName(project);
        transferSelect.append(option);
      });
      const transferButton = document.createElement("button");
      transferButton.className = "settings-secondary-button";
      transferButton.type = "button";
      transferButton.textContent = "Transfer to Firm";
      transferButton.disabled = true;
      transferSelect.addEventListener("change", () => {
        transferButton.disabled = !transferSelect.value;
      });
      transferButton.addEventListener("click", async () => {
        if (!transferSelect.value) return;
        const confirmed = await confirmWebWarning(
          "Transfer Project to firm?",
          "The Project keeps its stable identity and original-owner attribution. Firm roles will control future shared access.",
          { confirmLabel: "Transfer Project" }
        );
        if (!confirmed) return;
        transferButton.disabled = true;
        try {
          await postResearch("/organizations/projects/transfer", {
            organizationID: organization.id,
            projectID: transferSelect.value
          });
          setFirmStatus("Project transferred. Existing files and history were preserved.");
          await refreshOrganizationWorkspaceUI();
        } catch (error) {
          setFirmStatus(error.message || "The Project could not be transferred.", true);
          transferButton.disabled = false;
        }
      });

      const inviteForm = document.createElement("form");
      inviteForm.className = "settings-firm-invite";
      const email = document.createElement("input");
      email.type = "email";
      email.autocomplete = "email";
      email.placeholder = "teammate@example.com";
      email.required = true;
      const inviteRole = document.createElement("select");
      inviteRole.setAttribute("aria-label", "Invitation role");
      [
        ["viewer", "Viewer"],
        ["editor", "Editor"],
        ["reviewer", "Reviewer"]
      ].forEach(([value, label]) => {
        const option = document.createElement("option");
        option.value = value;
        option.textContent = label;
        inviteRole.append(option);
      });
      const inviteScope = document.createElement("select");
      inviteScope.setAttribute("aria-label", "Invitation scope");
      const allProjects = document.createElement("option");
      allProjects.value = "";
      allProjects.textContent = "Entire firm workspace";
      inviteScope.append(allProjects);
      (organization.projects || []).forEach((project) => {
        const option = document.createElement("option");
        option.value = project.id;
        option.textContent = `Only ${project.name}`;
        inviteScope.append(option);
      });
      const inviteButton = document.createElement("button");
      inviteButton.className = "settings-primary-button";
      inviteButton.type = "submit";
      inviteButton.textContent = "Create Invitation Link";
      const invitationResult = document.createElement("div");
      invitationResult.className = "settings-firm-invite-result";
      inviteForm.append(
        firmControlLabel("Email", email),
        firmControlLabel("Role", inviteRole),
        firmControlLabel("Scope", inviteScope),
        inviteButton,
        invitationResult
      );
      inviteForm.addEventListener("submit", async (event) => {
        event.preventDefault();
        inviteButton.disabled = true;
        invitationResult.replaceChildren();
        try {
          const payload = await postResearch("/organizations/members/invite", {
            organizationID: organization.id,
            projectID: inviteScope.value || undefined,
            email: email.value,
            role: inviteRole.value
          });
          const invitationURL = `${window.location.origin}${payload.acceptPath}`;
          const link = document.createElement("input");
          link.readOnly = true;
          link.value = invitationURL;
          link.setAttribute("aria-label", "Invitation link");
          const copyButton = document.createElement("button");
          copyButton.className = "settings-secondary-button";
          copyButton.type = "button";
          copyButton.textContent = "Copy Link";
          copyButton.addEventListener("click", async () => {
            try {
              await navigator.clipboard.writeText(invitationURL);
              copyButton.textContent = "Copied";
            } catch {
              link.focus();
              link.select();
              setFirmStatus("Invitation link selected. Copy it with your browser or keyboard.");
            }
          });
          invitationResult.append(link, copyButton);
          setFirmStatus("Invitation created. Permitext does not email it yet; send the private link directly.");
        } catch (error) {
          setFirmStatus(error.message || "The invitation could not be created.", true);
          inviteButton.disabled = false;
        }
      });

      const members = document.createElement("details");
      members.className = "settings-firm-members";
      const summary = document.createElement("summary");
      summary.textContent = "Members & pending invitations";
      const memberList = document.createElement("div");
      members.append(summary, memberList);
      members.addEventListener("toggle", () => {
        if (members.open && !memberList.childElementCount) {
          void renderFirmMemberManager(memberList, organization, setFirmStatus);
        }
      });
      const deleteFirmButton = document.createElement("button");
      deleteFirmButton.className =
        "settings-secondary-button settings-destructive-secondary settings-firm-delete";
      deleteFirmButton.type = "button";
      deleteFirmButton.textContent = "Delete Firm Workspace";
      deleteFirmButton.addEventListener("click", async () => {
        const projectCount = organization.projects?.length || 0;
        const projectMessage = projectCount
          ? `${projectCount} firm ${projectCount === 1 ? "Project" : "Projects"} will return to their original owners. `
          : "";
        const confirmed = await confirmWebWarning(
          `Delete ${organization.name}?`,
          `${projectMessage}Members and pending invitations will lose access, and the firm's standards will be deleted. Personal accounts and Project content will remain. This cannot be undone.`,
          { confirmLabel: "Delete Firm" }
        );
        if (!confirmed) return;
        deleteFirmButton.disabled = true;
        try {
          const payload = await postResearch("/organizations/delete", {
            organizationID: organization.id,
            confirmation: "delete"
          });
          const restoredCount = payload.restoredProjectIDs?.length || 0;
          setFirmStatus(
            restoredCount
              ? `${organization.name} deleted. ${restoredCount} ${restoredCount === 1 ? "Project was" : "Projects were"} returned to personal ownership.`
              : `${organization.name} deleted.`
          );
          await refreshOrganizationWorkspaceUI();
        } catch (error) {
          setFirmStatus(error.message || "The firm workspace could not be deleted.", true);
          deleteFirmButton.disabled = false;
        }
      });
      ownerTools.append(
        renderFirmStandardsEditor(organization, setFirmStatus),
        firmControlLabel("Project ownership", transferSelect),
        transferButton,
        inviteForm,
        members,
        deleteFirmButton
      );
      card.append(ownerTools);
    }
    container.append(card);
  }
  const firmStatus = document.createElement("p");
  firmStatus.className = "settings-firm-status";
  firmStatus.setAttribute("role", "status");
  container.append(firmStatus);
}

function settingsPanelScrollTop(panel) {
  return (panel.querySelector(".settings-scroll") || panel).scrollTop;
}

async function refreshWorkspaceAfterSettingsClear(settingsScrollTop, workspaceScrollLeft) {
  const accountScreen = document.querySelector(".account-screen[open]");
  const categoryScrollTops = new Map(Array.from(accountScreen?.querySelectorAll(".settings-card") || [], card => [
    card.getAttribute("aria-labelledby"), card.scrollTop
  ]));
  const refreshPaneIDs = activePaneIDs().filter((paneID) => paneID !== "utility:settings");
  await transitionWorkspace("utility", { refreshPaneIDs });
  const settingsPanel = track.querySelector('.workspace-panel[data-pane-id="utility:settings"]');
  const settingsScroller = settingsPanel?.querySelector(".settings-scroll") || settingsPanel;
  if (settingsScroller) settingsScroller.scrollTop = Math.min(
    settingsScrollTop,
    Math.max(0, settingsScroller.scrollHeight - settingsScroller.clientHeight)
  );
  track.scrollLeft = Math.min(
    workspaceScrollLeft,
    Math.max(0, track.scrollWidth - track.clientWidth)
  );
  const dialog = document.querySelector(".account-screen[open]");
  if (dialog && activeAccount()) {
    const refreshed = renderSettings();
    mountAccountScreenContent(dialog, refreshed);
    refreshed.querySelector(".settings-scroll").scrollTop = settingsScrollTop;
    // Source rows load asynchronously; restore their position after they exist.
    await refreshed.__refreshActiveCodeSources?.();
    if (document.querySelector(".account-screen[open]") !== dialog) return;
    refreshed.querySelectorAll(".settings-card").forEach(card => {
      card.scrollTop = categoryScrollTops.get(card.getAttribute("aria-labelledby")) || 0;
    });
    if (refreshed.querySelector(".settings-trash[open]")) {
      refreshed.querySelector(".settings-trash > summary")?.focus();
    }
  }
}

function wireSettingsCardCollapsing(panel) {
  panel.querySelectorAll(":scope > .settings-card").forEach((card, index) => {
    const title = card.querySelector(
      ":scope > .settings-section-title, :scope > .settings-card-heading > .settings-section-title"
    );
    if (!title) return;
    const heading = title.closest(".settings-card-heading") || title;
    const cardID = title.id || `settings-card-${index + 1}`;
    const titleText = title.textContent.trim();
    const toggle = document.createElement("button");
    const content = document.createElement("div");
    toggle.className = "settings-card-toggle";
    content.className = "settings-card-content";
    toggle.type = "button";
    const label = document.createElement("span");
    label.textContent = titleText;
    toggle.append(label);
    title.replaceChildren(toggle);
    Array.from(card.children).forEach((child) => {
      if (child !== heading) content.append(child);
    });
    card.append(content);
    card.dataset.settingsCardId = cardID;

    const measureContent = () => {
      if (!card.isConnected) {
        card.style.removeProperty("--settings-card-content-height");
        return;
      }
      card.style.removeProperty("--settings-card-content-height");
      card.style.setProperty("--settings-card-content-height", `${content.scrollHeight}px`);
    };
    const update = ({ animate = true } = {}) => {
      const collapsed = collapsedSettingsCardIDs.has(cardID);
      toggle.setAttribute("aria-expanded", String(!collapsed));
      toggle.setAttribute("aria-label", `${collapsed ? "Expand" : "Collapse"} ${titleText}`);
      content.toggleAttribute("inert", collapsed);
      content.setAttribute("aria-hidden", String(collapsed));
      measureContent();
      if (!animate) {
        card.classList.toggle("is-collapsed", collapsed);
        return;
      }
      requestAnimationFrame(() => {
        measureContent();
        card.classList.toggle("is-collapsed", collapsed);
      });
    };
    toggle.addEventListener("click", () => {
      if (collapsedSettingsCardIDs.has(cardID)) collapsedSettingsCardIDs.delete(cardID);
      else collapsedSettingsCardIDs.add(cardID);
      update();
    });
    if ("ResizeObserver" in window) {
      const resizeObserver = new ResizeObserver(() => {
        if (!collapsedSettingsCardIDs.has(cardID)) measureContent();
      });
      Array.from(content.children).forEach((child) => resizeObserver.observe(child));
    }
    update({ animate: false });
  });
}


function profileNeedsName(account) {
  return !String(account?.displayName || "").trim() || ["Permitext account", "Apple account", "Web browser"].includes(account.displayName);
}

function profileNeedsSetup(account) {
  return profileNeedsName(account) || !account?.onboardingCompleted;
}

function profileSetupSupported(account = activeAccount()) {
  if (!account) return false;
  if (account.authProvider !== "web") return true;
  return ["localhost", "127.0.0.1"].includes(location.hostname);
}

function professionalRoleLabel(value, other = "") {
  return ({
    architect_designer: "Architect or designer",
    engineer: "Engineer",
    code_zoning_consultant: "Code or zoning consultant",
    expeditor_filing_representative: "Expeditor or filing representative",
    contractor: "Contractor",
    owner_operator: "Owner or operator",
    student: "Student",
    other: String(other || "").trim() || "Other"
  })[value] || "";
}

async function refreshAccountProfile() {
  const account = activeAccount();
  if (!account) return null;
  const identity = captureAccountRequest();
  const payload = await postJSON("/account/profile/read", { auth: { accountUserID: account.userID } }, { token: account.sessionToken });
  requireCurrentAccountRequest(identity);
  Object.assign(state.account, payload.account);
  persistAccountSession();
  return state.account;
}

let accountProfileSetupPromise = null;
function setupAccountProfile(options = {}) {
  if (accountProfileSetupPromise) return accountProfileSetupPromise;
  accountProfileSetupPromise = presentAccountProfile(options).finally(() => { accountProfileSetupPromise = null; });
  return accountProfileSetupPromise;
}

async function presentAccountProfile({ edit = false } = {}) {
  if (!profileSetupSupported()) return;
  const account = await refreshAccountProfile();
  if (!edit && !profileNeedsSetup(account)) return;
  const policyConfiguration = await loadCurrentPolicyConfiguration();
  if (!edit && (!policyConfiguration.configured || !policyConfiguration.versions)) {
    throw new Error("Account setup is temporarily unavailable while the current policies are being prepared.");
  }
  const identity = captureAccountRequest();
  return new Promise((resolve) => {
    const dialog = document.createElement("dialog");
    dialog.className = "account-dialog profile-dialog";
    dialog.setAttribute("aria-label", edit ? "Edit profile" : "Set up your account");
    dialog.innerHTML = `<form class="profile-form">
      <h1>${edit ? "Edit profile" : "Set up your account"}</h1>
      <p>How should your name appear in Permitext?</p>
      <label>Name<input name="displayName" autocomplete="name" required maxlength="100"></label>
      <label>Email<input name="email" type="text" readonly></label>
      <label>Username (optional)<input name="publicUsername" autocomplete="username" maxlength="30"></label>
      <label>Professional role (optional)<select name="professionalRole">
        <option value="">Select a role</option>
        <option value="architect_designer">Architect or designer</option>
        <option value="engineer">Engineer</option>
        <option value="code_zoning_consultant">Code or zoning consultant</option>
        <option value="expeditor_filing_representative">Expeditor or filing representative</option>
        <option value="contractor">Contractor</option>
        <option value="owner_operator">Owner or operator</option>
        <option value="student">Student</option>
        <option value="other">Other</option>
      </select></label>
      <label class="profile-other-role" hidden>Describe your role<input name="professionalRoleOther" maxlength="80"></label>
      <label class="profile-choice profile-policy-choice">
        <input name="acceptPolicies" type="checkbox" ${account.policiesAccepted ? "checked disabled" : ""}>
        <span>${account.policiesAccepted ? "Terms and Privacy Policy accepted." : `I agree to the <a href="${policyConfiguration.documents?.terms?.url || "/terms"}" target="_blank" rel="noopener noreferrer">Terms</a> and <a href="${policyConfiguration.documents?.privacy?.url || "/privacy"}" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.`}</span>
      </label>
      <label class="profile-choice">
        <input name="productEmailOptIn" type="checkbox">
        <span>Send me occasional product updates, tips, and announcements. Optional.</span>
      </label>
      <p class="profile-error" role="status"></p>
      <button type="submit" class="settings-primary-button">${edit ? "Save changes" : "Continue"}</button>
      <button type="button" class="profile-cancel settings-secondary-button">${edit ? "Cancel" : "Continue later"}</button>
    </form>`;
    const form = dialog.querySelector("form");
    form.elements.displayName.value = profileNeedsName(account) ? "" : account.displayName;
    form.elements.email.value = account.email || "Email unavailable";
    form.elements.publicUsername.value = account.publicUsername || "";
    form.elements.professionalRole.value = account.professionalRole || "";
    form.elements.professionalRoleOther.value = account.professionalRoleOther || "";
    form.elements.productEmailOptIn.checked = account.productEmailOptIn === true;
    const otherRole = form.querySelector(".profile-other-role");
    const syncOtherRole = () => {
      const selected = form.elements.professionalRole.value === "other";
      otherRole.hidden = !selected;
      form.elements.professionalRoleOther.required = selected;
      if (!selected) form.elements.professionalRoleOther.value = "";
    };
    form.elements.professionalRole.addEventListener("change", syncOtherRole);
    syncOtherRole();
    dialog.querySelector(".profile-cancel").onclick = () => dialog.close();
    dialog.addEventListener("close", () => { dialog.remove(); resolve(); });
    form.onsubmit = async event => {
      event.preventDefault();
      const button = form.querySelector('[type="submit"]');
      button.disabled = true;
      try {
        requireCurrentAccountRequest(identity);
        const displayName = form.elements.displayName.value.trim();
        if (!displayName) throw new Error("Enter your name.");
        if (!edit && !account.policiesAccepted && !form.elements.acceptPolicies.checked) {
          throw new Error("Agree to the Terms and Privacy Policy to continue.");
        }
        const requestedRole = form.elements.professionalRole.value;
        const requestedOtherRole = form.elements.professionalRoleOther.value.trim();
        if (requestedRole === "other" && !requestedOtherRole) {
          throw new Error("Describe your professional role.");
        }
        const requestedUsername = form.elements.publicUsername.value.trim().replace(/^@/, "").toLowerCase();
        await postJSON("/account/profile", {
          auth: { accountUserID: account.userID },
          displayName,
          publicUsername: requestedUsername,
          professionalRole: requestedRole,
          professionalRoleOther: requestedOtherRole,
          productEmailOptIn: form.elements.productEmailOptIn.checked,
          completeOnboarding: !edit,
          acceptPolicies: !account.policiesAccepted && form.elements.acceptPolicies.checked,
          policyVersions: policyConfiguration.versions
        }, { token: account.sessionToken });
        requireCurrentAccountRequest(identity);
        const savedAccount = await refreshAccountProfile();
        requireCurrentAccountRequest(identity);
        if (
          savedAccount.displayName !== displayName ||
          String(savedAccount.publicUsername || "") !== requestedUsername ||
          savedAccount.professionalRole !== (requestedRole || null) ||
          savedAccount.professionalRoleOther !== (requestedRole === "other" ? requestedOtherRole : null) ||
          savedAccount.productEmailOptIn !== form.elements.productEmailOptIn.checked ||
          (!edit && (!savedAccount.onboardingCompleted || !savedAccount.policiesAccepted))
        ) {
          throw new Error("Your profile was not saved. Try again.");
        }
        dialog.close();
      } catch (error) { dialog.querySelector(".profile-error").textContent = error.message; button.disabled = false; }
    };
    document.body.append(dialog);
    dialog.showModal();
  });
}

function renderAccountWelcome(dialog) {
  const panel = document.createElement("section");
  panel.className = "account-welcome";
  panel.innerHTML = `
    <p class="account-welcome-brand">permitext</p>
    <h1>Your account, your workspace.</h1>
    <p>Read and search for free.<br>Saving, Projects, and Research require Pro.</p>
    <div class="account-welcome-actions">
      <button type="button" class="primary" data-account-mode="signUp">Create account</button>
      <button type="button" data-account-mode="signIn">Sign in</button>
    </div>
    <p class="account-welcome-existing">Already have Pro? Sign in to your existing account.</p>
    <p class="account-welcome-status" role="status" aria-live="polite"></p>
    <button type="button" class="account-welcome-explore">Continue exploring</button>`;
  panel.querySelector(".account-welcome-explore").addEventListener("click", () => dialog.close());
  const buttons = Array.from(panel.querySelectorAll("[data-account-mode]"));
  const status = panel.querySelector(".account-welcome-status");
  buttons.forEach(button => button.addEventListener("click", async () => {
    buttons.forEach(item => { item.disabled = true; });
    status.textContent = "Opening secure sign-in…";
    saveWorkspaceState();
    try {
      await signInCurrentBrowser(button.dataset.accountMode);
      await setupAccountProfile();
      dialog.dataset.continueUpgrade = "true";
      dialog.close();
      organizationWorkspace = null;
      organizationLoadPromise = null;
      await renderWorkspace();
      await resumePendingResearchIntent();
      await resumePendingProSave();
      await resumeProUpgradeIntent();
      startForegroundSyncLoop({ immediate: true });
    } catch (error) {
      status.textContent = error.message || "Could not sign in. Please try again.";
      buttons.forEach(item => { item.disabled = false; });
    }
  }));
  return panel;
}

function mountAccountScreenContent(dialog, panel) {
  // Reader column widths must not constrain the height of this screen's flex layout.
  panel.style.removeProperty("flex");
  panel.querySelector(".panel-header")?.remove();
  const scroll = panel.querySelector(".settings-scroll");
  const profile = scroll?.querySelector(".account-connector");
  if (profile) scroll.prepend(profile);
  const header = document.createElement("header");
  header.className = "account-screen-header";
  const title = document.createElement("h1");
  title.className = "eyebrow panel-kind";
  title.textContent = "Account";
  const close = document.createElement("button");
  close.type = "button";
  close.className = "icon-button utility-close account-screen-close";
  close.innerHTML = circleXIconSVG();
  close.title = "Close Account";
  close.setAttribute("aria-label", "Close Account");
  close.addEventListener("click", () => dialog.close());
  header.append(title, close);
  dialog.replaceChildren(header, panel);
}

function toggleAccountDialog({ upgrade = false } = {}) {
  const existing = document.querySelector(".account-screen[open]");
  if (existing) return;
  closeSharedWorkspaceViews("account");
  const dialog = document.createElement("section");
  dialog.className = "account-dialog account-screen";
  dialog.classList.add("account-workspace-view");
  let closedWithKeyboard = false;
  let closed = false;
  const requestIdentity = captureAccountRequest();
  const coveredState = new Map();
  const contextCheck = setInterval(() => { if (!isCurrentAccountRequest(requestIdentity)) dialog.close(); }, 200);
  dialog.open = true;
  dialog.setAttribute("open", "");
  dialog.close = () => {
    if (closed) return;
    closed = true;
    clearInterval(contextCheck);
    if (upgrade && dialog.dataset.continueUpgrade !== "true") clearProUpgradeIntent();
    dialog.open = false;
    dialog.remove();
    coveredState.forEach((inert, element) => { element.inert = inert; });
    state.workflowNavigationGeneration = (state.workflowNavigationGeneration || 0) + 1;
    syncWorkflowNavigation();
    if (closedWithKeyboard) toggleSettingsButton.focus({ preventScroll: true });
    else toggleSettingsButton.blur();
  };
  dialog.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || event.key !== "Escape") return;
    event.preventDefault();
    closedWithKeyboard = true;
    dialog.close();
  });
  dialog.setAttribute("aria-label", "Account workspace");
  const panel = activeAccount() ? renderSettings({ upgrade }) : renderAccountWelcome(dialog);
  if (upgrade && !activeAccount()) {
    panel.querySelector("h1").textContent = "Continue to Pro.";
    panel.querySelector("h1 + p").textContent = "Sign in or create an account to connect your subscription. Then continue to secure checkout.";
  }
  mountAccountScreenContent(dialog, panel);
  [track, document.querySelector(".workflow-toolbar")].filter(Boolean).forEach(element => {
    coveredState.set(element, element.inert); element.inert = true;
  });
  document.querySelector(".workspace-shell").append(dialog);
  state.workflowNavigationGeneration = (state.workflowNavigationGeneration || 0) + 1;
  syncWorkflowNavigation();
}

function openSearchCodeSourceSettings(panel) {
  const existing = panel.querySelector(".search-code-source-menu");
  if (existing) { existing._close(); return; }
  document.querySelector(".column-group-menu")?._close?.();
  const trigger = panel.querySelector(".column-group-menu-button");
  const menu = document.createElement("section");
  menu.className = "column-group-menu search-code-source-menu";
  menu.id = `search-code-sources-${crypto.randomUUID()}`;
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-label", "Code sources & editions");
  const controller = new AbortController();
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const observer = new MutationObserver(() => {
    if (!panel.isConnected || !isCurrentAccountRequest(identity) || activeWorkspaceID !== workspaceID) dismiss(false);
  });
  const card = settingsTemplate.content.querySelector(".settings-active-sources-card").cloneNode(true);
  card.removeAttribute("aria-labelledby");
  card.setAttribute("aria-label", "Code sources & editions");
  card.querySelector(".settings-section-title").remove();
  card.querySelectorAll(".settings-card-copy:not(.settings-active-sources-status)").forEach(copy => copy.remove());
  card.querySelector(".settings-active-sources-retry").setAttribute("role", "menuitem");
  const dismiss = (restoreFocus = true) => {
    controller.abort();
    observer.disconnect();
    if (panel.__refreshActiveCodeSources === refresh) delete panel.__refreshActiveCodeSources;
    menu.remove();
    trigger.setAttribute("aria-expanded", "false");
    trigger.removeAttribute("aria-controls");
    if (restoreFocus && trigger.isConnected) trigger.focus({ preventScroll: true });
  };
  const items = () => [...menu.querySelectorAll('input:not(:disabled), button:not(:disabled)')]
    .filter(item => !item.hidden && item.getClientRects().length > 0);
  const onKeydown = event => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      dismiss();
    } else if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      const options = items();
      if (!options.length) return;
      event.preventDefault();
      const index = options.indexOf(document.activeElement);
      const next = event.key === "Home" ? 0 : event.key === "End" ? options.length - 1
        : event.key === "ArrowDown" ? (index + 1) % options.length
        : index <= 0 ? options.length - 1 : index - 1;
      options[next].focus();
    }
  };
  const position = () => {
    const rect = trigger.getBoundingClientRect();
    const panelRect = panel.getBoundingClientRect();
    menu.style.top = `${rect.bottom - panelRect.top + 6}px`;
    menu.style.right = `${Math.max(8, panelRect.right - rect.right)}px`;
    menu.style.maxHeight = `${Math.max(0, Math.min(560, window.innerHeight - rect.bottom - 14, panelRect.bottom - rect.bottom - 14))}px`;
  };
  menu._close = dismiss;
  menu.append(card);
  panel.append(menu);
  position();
  trigger.setAttribute("aria-expanded", "true");
  trigger.setAttribute("aria-controls", menu.id);
  menu.addEventListener("keydown", onKeydown, { signal: controller.signal });
  trigger.addEventListener("keydown", onKeydown, { signal: controller.signal });
  menu.addEventListener("focusout", event => {
    if (event.relatedTarget && !menu.contains(event.relatedTarget) && event.relatedTarget !== trigger) dismiss(false);
  }, { signal: controller.signal });
  document.addEventListener("pointerdown", event => {
    if (!menu.contains(event.target) && !trigger.contains(event.target)) dismiss(false);
  }, { signal: controller.signal, capture: true });
  window.addEventListener("resize", position, { signal: controller.signal });
  track.addEventListener("permitext:workspace-layout-change", position, { signal: controller.signal });
  observer.observe(track, { childList: true, subtree: true });
  wireSettingsActiveCodeSources(menu, { enabled: true, readerMenu: true });
  const refresh = () => menu.__refreshActiveCodeSources?.();
  panel.__refreshActiveCodeSources = refresh;
  trigger.focus({ preventScroll: true });
}

function openActiveCodeSourceSettings() {
  const existing = document.querySelector("dialog.active-code-source-dialog");
  if (existing) { existing.querySelector("button")?.focus(); return; }
  const returnFocus = document.activeElement;
  const dialog = document.createElement("dialog");
  dialog.className = "account-dialog active-code-source-dialog";
  dialog.setAttribute("aria-label", "Manage code sources");
  dialog.style.maxHeight = "85vh";
  dialog.style.overflowY = "auto";
  const close = document.createElement("button");
  close.type = "button";
  close.textContent = "Close";
  close.className = "settings-link-button active-code-source-close";
  close.addEventListener("click", () => dialog.close());
  const card = settingsTemplate.content.querySelector(".settings-active-sources-card").cloneNode(true);
  const title = card.querySelector(".settings-section-title");
  title.id = `active-source-dialog-title-${crypto.randomUUID()}`;
  card.setAttribute("aria-labelledby", title.id);
  dialog.append(close, card);
  dialog.addEventListener("close", () => {
    dialog.remove();
    if (returnFocus?.isConnected) returnFocus.focus({ preventScroll: true });
  }, { once: true });
  document.body.append(dialog);
  wireSettingsActiveCodeSources(dialog, { enabled: true });
  dialog.showModal();
  close.focus();
}

function activeCodeSourceMenuRows(catalog) {
  return catalog.map((source, index) => {
    const order = codeOptions.findIndex(code =>
      code.prefix === source.codePrefix && codeOptionVersion(code) === source.canonicalEdition);
    const code = order < 0 ? null : codeOptions[order];
    return { source, order: order < 0 ? codeOptions.length + index : order,
      group: code?.group || "Other installed sources",
      label: code ? readerCodeOptionLabel(code) : `${source.categoryLabel} — ${source.editionLabel}` };
  }).sort((a, b) => a.order - b.order);
}

// Explicit navigation validates source access before changing Reader or detail state.
function wireSettingsActiveCodeSources(panel, { enabled = false, readerMenu = false } = {}) {
  const card = panel.querySelector(".settings-active-sources-card");
  if (!card || !enabled) return;
  card.hidden = false;
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const currentPanel = () => panel.isConnected && isCurrentAccountRequest(identity) && activeWorkspaceID === workspaceID;
  const status = card.querySelector(".settings-active-sources-status");
  const list = card.querySelector(".settings-active-sources-list");
  const retry = card.querySelector(".settings-active-sources-retry");
  const scope = card.querySelector(".settings-active-sources-scope");
  let attempt = 0;
  let rowCatalog = null;
  let rows = [];
  const showFailure = error => {
    status.textContent = `${error?.message || "Code sources could not be loaded."} Your existing choices have not been reset.`;
    retry.hidden = false;
    rows.forEach(({ input }) => { input.disabled = true; });
  };
  const render = () => {
    const snapshot = activeCodeSourcesController.state;
    if (scope) scope.textContent = snapshot.accountID === null
      ? "Guest choices stay in this browser on this device."
      : "These choices apply to this account in this browser on this device.";
    if (snapshot.error || !snapshot.preferences) {
      showFailure(snapshot.error || new Error("Code source preferences are unavailable."));
      return;
    }
    const catalog = snapshot.catalog || [];
    const catalogKey = JSON.stringify(catalog);
    if (rowCatalog !== catalogKey) {
      list.replaceChildren();
      let currentGroup = "";
      const items = readerMenu ? activeCodeSourceMenuRows(catalog) : catalog.map(source => ({ source }));
      rows = items.map(({ source, group, label: shortLabel }) => {
        if (readerMenu && group !== currentGroup) {
          const heading = document.createElement("h3");
          heading.className = "search-source-group-heading";
          heading.textContent = group;
          list.append(heading);
          currentGroup = group;
        }
        const label = document.createElement("label");
        label.className = "settings-active-source-row";
        const input = document.createElement("input");
        input.type = "checkbox";
        if (readerMenu) input.setAttribute("role", "menuitemcheckbox");
        const text = document.createElement("span");
        text.textContent = shortLabel || `${source.categoryLabel} — ${source.editionLabel}`;
        if (readerMenu) label.title = `${source.categoryLabel} — ${source.editionLabel}`;
        label.append(input, text);
        list.append(label);
        const row = { input, source, token: null };
        input.addEventListener("change", () => {
          if (!currentPanel()) return;
          if (!activeCodeSourcesController.isCurrent(row.token)) { render(); return; }
          try {
            activeCodeSourcesController.update(source, input.checked, row.token);
            render();
          } catch (error) {
            if (!currentPanel()) return;
            input.checked = activeCodeSourcesController.state.preferences?.isEnabled(source) ?? false;
            showFailure(error);
          }
        });
        return row;
      });
      rowCatalog = catalogKey;
    }
    for (const row of rows) {
      row.token = activeCodeSourcesController.captureContext();
      row.input.checked = snapshot.preferences.isEnabled(row.source);
      if (readerMenu) row.input.setAttribute("aria-checked", String(row.input.checked));
      row.input.disabled = false;
    }
    retry.hidden = true;
    status.textContent = !catalog.length ? "No configurable sources are installed."
      : rows.every(({ input }) => !input.checked)
        ? "All configurable sources are off. Turn one on to show its chapters and search results. Saved references remain available and ask you to enable their source when opened."
        : "";
  };
  const refresh = async () => {
    const request = ++attempt;
    const token = activeCodeSourcesController.captureContext();
    if (activeCodeSourcesController.state.error) { render(); return; }
    if (!activeCodeSourcesController.state.catalog) status.textContent = "Loading code sources…";
    try {
      await activeCodeSourcesController.ensureCatalog();
      if (!currentPanel() || request !== attempt || !activeCodeSourcesController.isCurrent(token)) return;
      render();
    } catch (error) {
      if (!currentPanel() || request !== attempt || !activeCodeSourcesController.isCurrent(token)) return;
      showFailure(error);
    }
  };
  retry.addEventListener("click", () => {
    if (!currentPanel()) return;
    activeCodeSourcesController.reload();
    void refresh();
  });
  // The controller owner can refresh this card after another tab changes preferences.
  panel.__refreshActiveCodeSources = refresh;
  void refresh();
}

function renderSettings({ upgrade = false } = {}) {
  const settingsIdentity = captureAccountRequest();
  const panel = renderTemplate(settingsTemplate);
  wireSettingsActiveCodeSources(panel, { enabled: true });
  applyPaneWeight(panel, "utility:settings");

  panel.querySelector(".settings-close-button")?.addEventListener("click", () => toggleUtilityPane("settings"));
  const accountCopy = panel.querySelector(".account-status-copy");
  const accountIdentity = panel.querySelector(".account-identity");
  const editableAccountRows = Array.from(accountIdentity.querySelectorAll("[data-profile-edit]"));
  let activeInlineProfileEditor = null;
  const saveInlineProfilePatch = async (row, patch) => {
    const account = activeAccount();
    if (!account) throw new Error("Sign in before editing your profile.");
    row.classList.add("is-saving");
    await postJSON("/account/profile", {
      auth: { accountUserID: account.userID },
      ...patch
    }, { token: account.sessionToken });
    requireCurrentAccountRequest(settingsIdentity);
    await refreshAccountProfile();
    requireCurrentAccountRequest(settingsIdentity);
  };
  const beginInlineProfileEdit = (row) => {
    if (!profileSetupSupported() || activeInlineProfileEditor?.row === row) return;
    activeInlineProfileEditor?.cancel();
    const account = activeAccount();
    const value = row.querySelector("dd");
    if (!account || !value) return;
    const field = row.dataset.profileEdit;
    let settled = false;
    const cancel = () => {
      if (settled) return;
      settled = true;
      activeInlineProfileEditor = null;
      row.classList.remove("is-editing", "is-saving");
      syncAccountState();
    };
    const finish = async (patch) => {
      if (settled) return;
      settled = true;
      try {
        await saveInlineProfilePatch(row, patch);
        accountCopy.textContent = "";
        accountCopy.hidden = true;
      } catch (error) {
        accountCopy.textContent = error.message || "Could not save your profile.";
        accountCopy.hidden = false;
      } finally {
        activeInlineProfileEditor = null;
        row.classList.remove("is-editing", "is-saving");
        if (isCurrentAccountRequest(settingsIdentity)) syncAccountState();
      }
    };
    activeInlineProfileEditor = { row, cancel };
    row.classList.add("is-editing");
    value.replaceChildren();

    if (field === "displayName" || field === "publicUsername") {
      const input = document.createElement("input");
      input.type = "text";
      input.className = "account-identity-inline-input";
      input.maxLength = field === "displayName" ? 100 : 30;
      input.value = field === "displayName" ? String(account.displayName || "") : String(account.publicUsername || "");
      input.setAttribute("aria-label", field === "displayName" ? "Name" : "Username");
      const saveText = () => {
        const requested = input.value.trim();
        if (field === "displayName" && !requested) {
          accountCopy.textContent = "Enter your name.";
          accountCopy.hidden = false;
          input.focus();
          return;
        }
        void finish(field === "displayName"
          ? { displayName: requested }
          : { publicUsername: requested.replace(/^@/, "").toLowerCase() });
      };
      input.addEventListener("keydown", (event) => {
        if (event.key === "Enter") { event.preventDefault(); saveText(); }
        if (event.key === "Escape") { event.preventDefault(); cancel(); }
      });
      input.addEventListener("blur", saveText);
      value.append(input);
      input.focus();
      input.setSelectionRange(input.value.length, input.value.length);
      return;
    }

    if (field === "professionalRole") {
      const select = document.createElement("select");
      select.className = "account-identity-inline-select";
      select.setAttribute("aria-label", "Professional role");
      [
        ["", "Select a role"],
        ["architect_designer", "Architect or designer"],
        ["engineer", "Engineer"],
        ["code_zoning_consultant", "Code or zoning consultant"],
        ["expeditor_filing_representative", "Expeditor or filing representative"],
        ["contractor", "Contractor"],
        ["owner_operator", "Owner or operator"],
        ["student", "Student"],
        ["other", "Other"]
      ].forEach(([optionValue, label]) => select.add(new Option(label, optionValue)));
      select.value = account.professionalRole || "";
      value.append(select);
      const showOtherRole = () => {
        value.querySelector(".account-identity-inline-other")?.remove();
        if (select.value !== "other") {
          void finish({ professionalRole: select.value, professionalRoleOther: "" });
          return;
        }
        const other = document.createElement("input");
        other.type = "text";
        other.className = "account-identity-inline-input account-identity-inline-other";
        other.maxLength = 80;
        other.placeholder = "Describe your role";
        other.value = account.professionalRole === "other" ? String(account.professionalRoleOther || "") : "";
        const saveOther = () => {
          const requested = other.value.trim();
          if (!requested) {
            accountCopy.textContent = "Describe your professional role.";
            accountCopy.hidden = false;
            other.focus();
            return;
          }
          void finish({ professionalRole: "other", professionalRoleOther: requested });
        };
        other.addEventListener("keydown", (event) => {
          if (event.key === "Enter") { event.preventDefault(); saveOther(); }
          if (event.key === "Escape") { event.preventDefault(); cancel(); }
        });
        other.addEventListener("blur", saveOther);
        value.append(other);
        other.focus();
        other.setSelectionRange(other.value.length, other.value.length);
      };
      select.addEventListener("change", showOtherRole);
      select.addEventListener("blur", () => queueMicrotask(() => {
        if (!value.contains(document.activeElement)) cancel();
      }));
      select.addEventListener("keydown", (event) => {
        if (event.key === "Escape") { event.preventDefault(); cancel(); }
      });
      if (select.value === "other") showOtherRole();
      else select.focus();
      return;
    }

    const select = document.createElement("select");
    select.className = "account-identity-inline-select";
    select.setAttribute("aria-label", "Product emails");
    select.add(new Option("Subscribed", "true"));
    select.add(new Option("Off", "false"));
    select.value = account.productEmailOptIn === true ? "true" : "false";
    select.addEventListener("change", () => void finish({ productEmailOptIn: select.value === "true" }));
    select.addEventListener("blur", cancel);
    select.addEventListener("keydown", (event) => {
      if (event.key === "Escape") { event.preventDefault(); cancel(); }
    });
    value.append(select);
    select.focus();
  };
  editableAccountRows.forEach((row) => {
    if (!profileSetupSupported()) return;
    row.setAttribute("role", "button");
    row.tabIndex = 0;
    row.addEventListener("click", (event) => {
      if (event.target.closest("input, select")) return;
      beginInlineProfileEdit(row);
    });
    row.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      if (event.target.closest("input, select")) return;
      event.preventDefault();
      beginInlineProfileEdit(row);
    });
  });
  void refreshAccountProfile().then(() => {
    if (isCurrentAccountRequest(settingsIdentity) && panel.isConnected) syncAccountState();
  }).catch(() => {});

  const accountIdentityName = panel.querySelector(".account-identity-name");
  const accountIdentityUsernameRow = panel.querySelector(".account-identity-username-row");
  const accountIdentityUsername = panel.querySelector(".account-identity-username");
  const accountIdentityEmail = panel.querySelector(".account-identity-email");
  const accountIdentityRoleRow = panel.querySelector(".account-identity-role-row");
  const accountIdentityRole = panel.querySelector(".account-identity-role");
  const accountIdentityProductEmails = panel.querySelector(".account-identity-product-emails");
  appendLinkedAccountRecoveryControls(accountCopy.closest(".settings-card"), settingsIdentity);
  appendLegacyWorkspaceRecoveryControls(panel.querySelector(".settings-data-card"), settingsIdentity);
  const planRows = Array.from(panel.querySelectorAll("[data-plan-option]"));
  const planUsage = panel.querySelector(".settings-plan-usage");
  const researchPacks = panel.querySelector(".settings-research-packs");
  const researchPackActions = panel.querySelector(".settings-research-pack-actions");
  const planDetails = panel.querySelector(".settings-plan-details");
  const stripeTaxDisclosure = panel.querySelector(".settings-stripe-tax-disclosure");
  const signInButton = panel.querySelector(".account-sign-in");
  const signOutButton = panel.querySelector(".account-clear");
  const deleteAccountButton = panel.querySelector(".account-delete");
  const syncConflictsCard = panel.querySelector(".settings-sync-conflicts-card");
  const syncConflictsSummary = panel.querySelector(".settings-sync-conflicts-summary");
  const syncConflictsList = panel.querySelector(".settings-sync-conflicts-list");
  const checkoutButton = panel.querySelector(".account-checkout");
  const purchaseConsent = panel.querySelector(".settings-purchase-consent");
  const policyAcceptance = panel.querySelector(".settings-policy-acceptance");
  if (upgrade) {
    const checkoutNotice = document.createElement("p");
    checkoutNotice.className = "settings-card-copy";
    checkoutNotice.textContent = "Agree below to continue to Stripe Checkout. You will review and complete payment there.";
    purchaseConsent.before(checkoutNotice);
  }
  const policyDocumentLinks = Array.from(panel.querySelectorAll("[data-policy-document]"));
  const planSecondaryButton = panel.querySelector(".account-plan-secondary");
  const offlineCopy = panel.querySelector(".settings-offline-copy");
  const offlineStatus = panel.querySelector(".settings-offline-status");
  const offlineProgress = panel.querySelector(".settings-offline-progress");
  const offlineDownload = panel.querySelector(".settings-offline-download");
  const offlineRemove = panel.querySelector(".settings-offline-remove");
  const projectList = panel.querySelector(".settings-project-list");
  const projectEmpty = panel.querySelector(".settings-projects-empty");
  const projectSelectAll = panel.querySelector(".settings-project-select-all");
  const projectDelete = panel.querySelector(".settings-project-delete");
  const projectClearAll = panel.querySelector(".settings-project-clear-all");
  const status = panel.querySelector(".settings-status-message");
  wireOperationalSupport(panel);
  const setStatus = (message, isError = false) => {
    status.textContent = message || "";
    status.classList.toggle("has-error", isError);
  };
  let currentPolicyConfiguration = null;
  let policyConfigurationLoaded = false;
  let checkoutInFlight = false;

  const applyPolicyConfiguration = (configuration) => {
    currentPolicyConfiguration = configuration;
    policyConfigurationLoaded = true;
    policyDocumentLinks.forEach((link) => {
      const document = configuration?.documents?.[link.dataset.policyDocument];
      if (document?.url) link.href = document.url;
    });
  };
  if (clerkSignInReturnNotice) {
    setStatus(clerkSignInReturnNotice.message, clerkSignInReturnNotice.isError);
  }

  const renderResearchPacks = () => {
    clear(researchPackActions);
    const account = activeAccount();
    const availablePacks = (researchUsage?.packs || []).filter((pack) => pack.webAvailable);
    researchPacks.hidden = !account || !isProAccount() || availablePacks.length === 0;
    if (researchPacks.hidden) return;
    availablePacks.forEach((pack) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "settings-secondary-button";
      button.textContent = `Buy ${Number(pack.turns).toLocaleString()} more turns`;
      button.addEventListener("click", async () => {
        Array.from(researchPackActions.querySelectorAll("button")).forEach((item) => {
          item.disabled = true;
        });
        setStatus("Opening Research turn checkout...");
        try {
          const current = activeAccount();
          if (!current) throw new Error("Sign in before buying Research turns.");
          const payload = await postJSON(
            "/billing/research/checkout",
            { auth: { accountUserID: current.userID }, packID: pack.id },
            { token: current.sessionToken }
          );
          if (!payload.url) throw new Error("Checkout did not return a URL.");
          window.location.href = payload.url;
        } catch (error) {
          setStatus(error.message || "Could not open Research turn checkout.", true);
          Array.from(researchPackActions.querySelectorAll("button")).forEach((item) => {
            item.disabled = false;
          });
        }
      });
      researchPackActions.append(button);
    });
  };

  const renderSyncConflictReview = () => {
    const account = activeAccount();
    const conflicts = account
      ? (state.syncConflicts || []).filter((entry) => entry.accountUserID === account.userID)
      : [];
    syncConflictsCard.hidden = conflicts.length === 0;
    syncConflictsSummary.textContent = conflicts.length
      ? `Permitext resolved every safe match automatically. ${conflicts.length} ${conflicts.length === 1 ? "change may" : "changes may"} contain unique edits and ${conflicts.length === 1 ? "needs" : "need"} your decision.`
      : "";
    syncConflictsList.replaceChildren();

    const kindLabels = {
      annotation: "Note",
      codeVersionClear: "Saved evidence removal",
      continuity: "Recent activity",
      project: "Project",
      projectSection: "Project evidence",
      savedItem: "Saved evidence",
      workboard: "Workboard"
    };
    conflicts.forEach((entry) => {
      const { kind, record } = mutationKindAndRecord(entry.mutation);
      const row = document.createElement("article");
      row.className = "settings-conflict-row";
      row.setAttribute("role", "listitem");
      const heading = document.createElement("strong");
      heading.textContent = record?.title || record?.name || record?.sectionNumber || kindLabels[kind] || "Saved change";
      const type = document.createElement("span");
      type.className = "settings-conflict-kind";
      type.textContent = kindLabels[kind] || "Synced data";
      const message = document.createElement("span");
      message.textContent = entry.lastError || "This change could not be reconciled automatically.";
      const guidance = document.createElement("span");
      guidance.className = "settings-conflict-guidance";
      guidance.textContent = "Use server keeps the latest synced copy. Keep mine uploads this device's copy as the newest version.";
      const actions = document.createElement("div");
      actions.className = "connector-actions settings-conflict-actions";
      [
        ["Use server", false],
        ["Keep mine", true]
      ].forEach(([label, keepLocal]) => {
        const button = document.createElement("button");
        button.className = "settings-mini-button";
        button.type = "button";
        button.textContent = label;
        button.addEventListener("click", async () => {
          actions.querySelectorAll("button").forEach((candidate) => {
            candidate.disabled = true;
          });
          try {
            await resolveSyncConflict(entry, keepLocal);
            if (panel.isConnected && isCurrentAccountRequest(settingsIdentity)) renderSyncConflictReview();
          } catch (error) {
            setStatus(error.message || "Could not resolve this sync conflict.", true);
            actions.querySelectorAll("button").forEach((candidate) => {
              candidate.disabled = false;
            });
          }
        });
        actions.append(button);
      });
      row.append(heading, type, message, guidance, actions);
      syncConflictsList.append(row);
    });
  };

  const settingsProjects = visibleProjectRecords(currentContentSummary().projects || [])
    .map((project, sourceIndex) => ({ project, sourceIndex }))
    .sort((left, right) =>
      Number(projectIsArchived(left.project)) - Number(projectIsArchived(right.project)) ||
      left.sourceIndex - right.sourceIndex
    )
    .map(({ project }) => project);
  const selectedProjectIDs = new Set();
  const projectCheckboxes = new Map();
  const updateProjectSelection = () => {
    const count = selectedProjectIDs.size;
    projectSelectAll.textContent = count === settingsProjects.length && count > 0 ? "Clear All" : "Select All";
    projectSelectAll.disabled = settingsProjects.length === 0;
    projectDelete.disabled = count === 0;
    projectClearAll.disabled = settingsProjects.length === 0;
    projectDelete.textContent = count > 0 ? `Delete ${count} Selected` : "Delete Selected";
    projectCheckboxes.forEach((checkbox, id) => {
      checkbox.checked = selectedProjectIDs.has(id);
    });
  };
  projectEmpty.hidden = settingsProjects.length > 0;
  settingsProjects.forEach((project) => {
    const id = projectRecordID(project);
    const row = document.createElement("label");
    row.className = "settings-project-row";
    row.style.setProperty("--project-color", projectColor(project));
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.setAttribute(
      "aria-label",
      `Select ${folderTypeLabel(project)} ${project.name || project.title || "record"}`
    );
    const copy = document.createElement("span");
    copy.className = "settings-project-copy";
    const name = document.createElement("strong");
    name.textContent = readableProjectName(project);
    const typeLabel = document.createElement("span");
    typeLabel.textContent = folderTypeLabel(project);
    copy.append(name, typeLabel);
    row.append(checkbox, copy);
    if (projectIsArchived(project)) {
      const archivedLabel = document.createElement("span");
      archivedLabel.className = "settings-project-archive-label";
      archivedLabel.textContent = "Archived";
      row.append(archivedLabel);
    }
    checkbox.addEventListener("change", () => {
      if (checkbox.checked) selectedProjectIDs.add(id);
      else selectedProjectIDs.delete(id);
      updateProjectSelection();
    });
    projectCheckboxes.set(id, checkbox);
    projectList.append(row);
  });
  projectSelectAll.addEventListener("click", () => {
    if (selectedProjectIDs.size === settingsProjects.length) selectedProjectIDs.clear();
    else settingsProjects.forEach((project) => selectedProjectIDs.add(projectRecordID(project)));
    updateProjectSelection();
  });
  projectDelete.addEventListener("click", async () => {
    if (!isCurrentAccountRequest(settingsIdentity)) return;
    const selectedProjects = settingsProjects.filter((project) => selectedProjectIDs.has(projectRecordID(project)));
    const count = selectedProjects.length;
    if (!count) return;
    const recordLabel = folderRecordCountLabel(selectedProjects);
    const confirmed = await confirmWebWarning(
      `Delete ${recordLabel}`,
      `Move ${recordLabel} to Trash across synced devices. Restore within 30 days. Saved passages and notes remain.`,
      { confirmLabel: "Delete" }
    );
    if (!isCurrentAccountRequest(settingsIdentity)) return;
    if (!confirmed) return;
    projectDelete.disabled = true;
    try {
      await prepareRecoverableDeletion();
      for (const project of selectedProjects) {
        await deleteArchivedProjectData(project);
        requireCurrentAccountRequest(settingsIdentity);
      }
      await prepareRecoverableDeletion();
      openTrashAfterSettingsDeletion = true;
      setStatus(`${recordLabel} moved to Trash. Open Trash to undo.`);
      await refreshWorkspaceAfterSettingsClear(settingsPanelScrollTop(panel), track.scrollLeft);
    } catch (error) {
      if (!isCurrentAccountRequest(settingsIdentity)) return;
      setStatus(error.message || `Could not delete ${recordLabel}.`, true);
      projectDelete.disabled = false;
    }
  });
  projectClearAll.addEventListener("click", async () => {
    if (!isCurrentAccountRequest(settingsIdentity)) return;
    const count = settingsProjects.length;
    if (!count) return;
    const recordLabel = folderRecordCountLabel(settingsProjects);
    const confirmed = await confirmWebWarning(
      "Clear all Projects and saved collections?",
      `Move ${recordLabel}, including archived records, to Trash across synced devices. Restore within 30 days. Saved passages and notes remain.`,
      { confirmLabel: "Delete All" }
    );
    if (!isCurrentAccountRequest(settingsIdentity)) return;
    if (!confirmed) return;
    projectClearAll.disabled = true;
    try {
      await prepareRecoverableDeletion();
      for (const project of settingsProjects) {
        await deleteArchivedProjectData(project);
        requireCurrentAccountRequest(settingsIdentity);
      }
      await prepareRecoverableDeletion();
      openTrashAfterSettingsDeletion = true;
      setStatus(`${recordLabel} moved to Trash. Open Trash to undo.`);
      await refreshWorkspaceAfterSettingsClear(settingsPanelScrollTop(panel), track.scrollLeft);
    } catch (error) {
      if (!isCurrentAccountRequest(settingsIdentity)) return;
      setStatus(error.message || `Could not delete ${recordLabel}.`, true);
      projectClearAll.disabled = false;
    }
  });
  updateProjectSelection();
  const renderOfflineState = async () => {
    const pro = hasCapability("offline-access");
    const library = await offlineLibraryStatus().catch(() => ({ available: false, supported: false }));
    offlineProgress.hidden = true;
    offlineDownload.hidden = !pro;
    offlineDownload.disabled = false;
    offlineRemove.hidden = !library.available;
    if (!pro) {
      offlineCopy.textContent = "Download the complete searchable code library for use without an internet connection.";
      offlineStatus.textContent = "Available with Pro.";
      return;
    }
    offlineCopy.textContent = `Keep the app and the complete searchable enacted-code library on this device. Estimated download: ${offlineFeatureMetadata.estimatedDownload}.`;
    if (!library.supported) {
      offlineStatus.textContent = "This browser does not provide the storage required for offline codes.";
      offlineDownload.textContent = "Offline Storage Unavailable";
      offlineDownload.disabled = true;
      return;
    }
    if (!library.available) {
      offlineStatus.textContent = navigator.onLine ? "" : "Connect to the internet to download.";
      offlineDownload.textContent = "Download for Offline Use";
      offlineDownload.disabled = navigator.onLine === false;
      return;
    }
    if (
      library.librarySchemaVersion !== offlineFeatureMetadata.librarySchemaVersion ||
      library.assetVersion !== offlineFeatureMetadata.assetVersion
    ) {
      offlineStatus.textContent = navigator.onLine
        ? "An updated offline code package is available."
        : "Your offline package works, but must be updated when you reconnect.";
      offlineDownload.textContent = "Update Offline Codes";
      offlineDownload.disabled = navigator.onLine === false;
      return;
    }
    offlineStatus.textContent = "";
    offlineDownload.textContent = "Downloaded for Offline Use";
    offlineDownload.disabled = true;
  };

  const syncAccountState = () => {
    const account = activeAccount();
    const pro = isProAccount();
    const source = currentEntitlement()?.source;
    const activePlanCopy = settingsPlanCopy({ pro, source });
    planRows.forEach((row) => {
      const active = row.dataset.planOption === "free"
        ? !pro
        : pro;
      row.hidden = !active;
      row.classList.toggle("is-active", active);
      row.setAttribute("aria-current", active ? "true" : "false");
      const indicator = row.querySelector(".settings-feature-icon");
      if (indicator) indicator.textContent = active ? "✓" : "";
      if (active) {
        const title = row.querySelector("strong");
        const summary = row.querySelector("span:not(.settings-feature-icon)");
        if (title) title.textContent = activePlanCopy.title;
        if (summary) {
          summary.textContent = source === "lifetimeGrant" ? "" : activePlanCopy.summary;
          summary.hidden = source === "lifetimeGrant";
        }
      }
    });
    const policyAcceptanceReady = Boolean(
      policyConfigurationLoaded &&
      currentPolicyConfiguration?.configured &&
      policyAcceptance?.checked
    );
    checkoutButton.disabled = checkoutInFlight || !account ||
      (pro && source === "lifetimeGrant") ||
      (!pro && !policyAcceptanceReady);
    checkoutButton.hidden = pro && source === "lifetimeGrant";
    checkoutButton.classList.toggle("is-pro-active", pro);
    checkoutButton.textContent = pro
      ? "Manage Subscription"
      : "Upgrade to Pro - $20.00/month";
    planDetails.hidden = pro;
    stripeTaxDisclosure.hidden = pro;
    stripeTaxDisclosure.textContent = webStripePriceDisclosure;
    purchaseConsent.hidden = pro;
    policyAcceptance.disabled = checkoutInFlight || pro || !account || !currentPolicyConfiguration?.configured;
    planSecondaryButton.hidden = !account || source === "lifetimeGrant";
    planSecondaryButton.textContent = "Restore Purchases";
    accountIdentity.hidden = !account;
    if (account) {
      accountIdentityName.textContent = account.displayName || "Permitext account";
      accountIdentityEmail.textContent = account.email || "Email unavailable";
      const username = String(account.publicUsername || "").trim();
      accountIdentityUsernameRow.hidden = false;
      accountIdentityUsername.textContent = username ? (username.startsWith("@") ? username : `@${username}`) : "Add username";
      const roleLabel = professionalRoleLabel(account.professionalRole, account.professionalRoleOther);
      accountIdentityRoleRow.hidden = false;
      accountIdentityRole.textContent = roleLabel || "Add role";
      accountIdentityProductEmails.textContent = account.productEmailOptIn ? "Subscribed" : "Off";
      editableAccountRows.forEach((row) => {
        const label = row.querySelector("dt")?.textContent?.trim() || "profile";
        const value = row.querySelector("dd")?.textContent?.trim() || "not set";
        row.setAttribute("aria-label", `Edit ${label.toLowerCase()}, current value ${value}`);
      });
    }
    accountCopy.hidden = Boolean(account);
    signOutButton.hidden = !account;
    deleteAccountButton.hidden = !account;
    signInButton.hidden = Boolean(account);
    signInButton.textContent = "Sign in";
    accountCopy.textContent = account ? "" : settingsAccountSummary(null);
    renderSyncConflictReview();
    renderPlanUsageRows(planUsage);
    renderResearchPacks();
    void renderOfflineState();
  };

  syncAccountState();
  policyAcceptance.addEventListener("change", () => {
    syncAccountState();
    if (upgrade && policyAcceptance.checked && !checkoutButton.disabled) checkoutButton.click();
  });
  void loadCurrentPolicyConfiguration()
    .then((configuration) => {
      applyPolicyConfiguration(configuration);
      syncAccountState();
      if (upgrade && panel.isConnected) {
        panel.querySelector(".settings-purchase-consent")?.scrollIntoView({ block: "center" });
        setStatus(isProAccount()
          ? (currentEntitlement()?.source === "lifetimeGrant" ? "Lifetime Pro is already active. No subscription is needed." : "Pro is already active. You can manage your existing subscription here.")
          : "Review the policies below. Agreeing will open Stripe Checkout; payment is completed there.");
      }
      if (activeAccount() && !isProAccount() && !configuration.configured) {
        setStatus("Purchases are temporarily unavailable while approved policy versions are being prepared.", true);
      }
    })
    .catch((error) => {
      policyConfigurationLoaded = true;
      currentPolicyConfiguration = null;
      syncAccountState();
      if (activeAccount() && !isProAccount()) {
        setStatus(error.message || "Could not load the current purchase policies.", true);
      }
    });
  wireSettingsCardCollapsing(panel);
  const researchUsageAccount = activeAccount();
  if (researchUsageAccount && hasCapability("research")) {
    void postJSON(
      "/research/usage",
      { auth: { accountUserID: researchUsageAccount.userID } },
      { token: researchUsageAccount.sessionToken }
    )
      .then((payload) => {
        const currentAccount = activeAccount();
        if (
          currentAccount?.userID !== researchUsageAccount.userID ||
          currentAccount?.sessionToken !== researchUsageAccount.sessionToken
        ) return;
        researchUsage = payload.usage || null;
        if (panel.isConnected) {
          renderPlanUsageRows(planUsage);
          renderResearchPacks();
        }
      })
      .catch(() => {
        const currentAccount = activeAccount();
        if (
          currentAccount?.userID !== researchUsageAccount.userID ||
          currentAccount?.sessionToken !== researchUsageAccount.sessionToken
        ) return;
        if (!panel.isConnected || !planUsage) return;
        const researchRow = Array.from(planUsage.querySelectorAll("p"))
          .find((row) => row.querySelector("span")?.textContent === "Research");
        if (researchRow?.querySelector("strong")) {
          researchRow.querySelector("strong").textContent = "Research status unavailable";
        }
      });
  }
  appleWebSignInConfig().then((config) => {
    if (panel.dataset.clerkReady === "true") return;
    const account = activeAccount();
    if (account) return;
    signInButton.textContent = config.available ? "Sign in with Apple" : "Sign in";
    signInButton.disabled = !config.available && !config.browserFallbackAllowed;
    if (!config.available && !config.browserFallbackAllowed) accountCopy.textContent = "Apple web sign-in is not configured yet.";
  }).catch(() => {
    if (!activeAccount()) accountCopy.textContent = "Could not check sign-in configuration.";
  });
  clerkWebSignInConfig().then((config) => {
    if (!config.available) return;
    panel.dataset.clerkReady = "true";
    const account = activeAccount();
    signInButton.hidden = Boolean(account);
    signInButton.disabled = false;
    signInButton.textContent = "Sign in or create an account";
    if (!account) {
      accountCopy.textContent = "Sign in to access your account. Saving, Projects, and synced work require Pro; reading and search are free.";
    }
  }).catch(() => {});

  signInButton.addEventListener("click", async () => {
    signInButton.disabled = true;
    clerkSignInReturnNotice = null;
    setStatus("Signing in...");
    try {
      await signInCurrentBrowser();
      await setupAccountProfile();
      organizationWorkspace = null;
      organizationLoadPromise = null;
      await renderWorkspace();
      await resumePendingResearchIntent();
      await resumePendingProSave();
      await resumeProUpgradeIntent();
      startForegroundSyncLoop({ immediate: true });
    } catch (error) {
      setStatus(error.message || "Could not sign in.", true);
      signInButton.disabled = false;
      syncAccountState();
    }
  });
  signOutButton.addEventListener("click", async () => {
    const account = activeAccount();
    const requestIdentity = captureAccountRequest();
    signOutButton.disabled = true;
    try {
      await Promise.all(Array.from(notebookMounts.values()).map((mount) => mount.persistDraft?.()));
      requireCurrentAccountRequest(requestIdentity);
      if (account) {
        const drafts = await pendingNotebookDrafts(account.userID);
        requireCurrentAccountRequest(requestIdentity);
        const pending = (state.syncOutbox || []).filter((item) => item.accountUserID === account.userID).length +
          (state.codeQuestionOutbox || []).filter((item) => item.accountUserID === account.userID).length + drafts.length;
        const conflicts = (state.syncConflicts || []).filter((item) => item.accountUserID === account.userID).length +
          (state.codeQuestionConflicts || []).filter((item) => item.accountUserID === account.userID).length;
        if (pending > 0 || conflicts > 0) {
          const details = [
            pending > 0 ? `${pending} ${pending === 1 ? "change is" : "changes are"} waiting to sync` : "",
            conflicts > 0 ? `${conflicts} sync ${conflicts === 1 ? "conflict needs" : "conflicts need"} review` : ""
          ].filter(Boolean).join(", and ");
          const confirmed = await confirmWebWarning(
            "Sign out with unfinished sync?",
            `${details}. This work will remain on this device and can resume when you sign back in to this account.`,
            { confirmLabel: "Sign Out" }
          );
          requireCurrentAccountRequest(requestIdentity);
          if (!confirmed) return;
        }
        await signOutCapturedClerkSession(account, requestIdentity);
        requireCurrentAccountRequest(requestIdentity);
        try {
          await postJSON("/account/sign-out", { auth: { accountUserID: account.userID } }, { token: account.sessionToken });
        } catch (error) {
          requireCurrentAccountRequest(requestIdentity);
          // Offline sign-out keeps this account's durable local work for its next session.
        }
      }
      requireCurrentAccountRequest(requestIdentity);
      if (!isCurrentAccountRequest(requestIdentity)) return;
      if (account) persistCodeQuestionAccountState(account.userID);
      replaceActiveAccount(null);
      panel.closest(".account-dialog")?.close();
      await disableOfflineFeature().catch(() => {});
      await renderWorkspace();
    } catch (error) {
      if (isCurrentAccountRequest(requestIdentity)) {
        setStatus(`Sign-out paused: ${error.message || "the local draft could not be saved"}`, true);
      }
    } finally {
      if (isCurrentAccountRequest(requestIdentity)) signOutButton.disabled = false;
    }
  });
  deleteAccountButton.addEventListener("click", async () => {
    if (!isCurrentAccountRequest(settingsIdentity)) return;
    const account = activeAccount();
    if (!account) return;
    const deletionIdentity = captureAccountRequest();
    let preparedIdentity = null;
    const entitlement = currentEntitlement();
    const appleManaged = [
      entitlement?.source,
      ...Object.values(entitlement?.addOns || {}).map((addOn) => addOn?.source)
    ].some((source) => ["appleSubscription", "subscription"].includes(source));
    const stripeManaged = [
      entitlement?.source,
      ...Object.values(entitlement?.addOns || {}).map((addOn) => addOn?.source)
    ].some((source) => source === "webSubscription");
    const lifetimeGrant = entitlement?.source === "lifetimeGrant";
    const confirmed = await confirmAccountDeletion({ appleManaged, stripeManaged, lifetimeGrant });
    if (!isCurrentAccountRequest(deletionIdentity)) return;
    if (!confirmed) return;

    deleteAccountButton.disabled = true;
    // A native modal dialog occupies the browser top layer and makes Clerk's
    // separately mounted verification UI inaccessible, regardless of z-index.
    // Release that layer before verification; cancellation uses its own notice.
    panel.closest(".account-dialog")?.close();
    setStatus("Verifying your sign-in identity before deleting account data...");
    try {
      preparedIdentity = await prepareAccountDeletionIdentity(account, deletionIdentity);
      requireCurrentAccountRequest(deletionIdentity);
    } catch (error) {
      if (isCurrentAccountRequest(deletionIdentity)) {
        deleteAccountButton.disabled = false;
        setStatus("Account deletion paused. No data was deleted.", true);
        await showWebNotice("Account deletion paused", error.code === "reverification_cancelled"
          ? "Identity verification was canceled. No account data was deleted."
          : `${error.message || "Identity verification did not finish."} No account data was deleted.`);
      }
      return;
    }
    setStatus("Deleting your account and synced data...");
    const progress = openAccountDeletionProgress();
    progress.setStage("billing", "active");
    progress.setStage("data", "active");
    // Retired Workboard caches use unowned Project-only keys. Preserve those
    // legacy bytes until ownership is established instead of erasing another
    // account's copy of a shared Project.
    const clearThisBrowser = () => clearDeletedAccountBrowserData(account, deletionIdentity);

    const removeClerkIdentity = async () => {
      if (account.authProvider !== "clerk") return "notApplicable";
      return progress.withIdentityPrompt(() => removePreparedAccountDeletionIdentity(preparedIdentity));
    };

    const showBackendFailure = (error) => {
      const stages = error.payload?.stages || {};
      const stripeStatus = stages.stripeBilling?.status;
      if (stripeStatus === "canceled") {
        progress.setStage("billing", "complete", "Stripe confirmed cancellation.");
      } else if (stripeStatus === "notApplicable") {
        progress.setStage("billing", "skipped", "No Stripe subscription was linked.");
      } else {
        progress.setStage("billing", "failed", "Stripe cancellation was not confirmed.");
      }
      const assetDeleted = stages.privateAssets?.status === "deleted";
      progress.setStage(
        "data",
        "failed",
        assetDeleted
          ? "Private images were deleted, but deletion of the remaining Permitext data was not confirmed."
          : error.payload?.error || error.message || "Permitext data deletion was not confirmed."
      );
      progress.setStage("device", "skipped", "Not started because server deletion did not finish.");
      progress.setStage("identity", "skipped", "Not started because server deletion did not finish.");
      progress.finish({
        title: error.payload?.partial ? "Deletion incomplete" : "Deletion stopped",
        message: error.payload?.error || error.message || "Permitext could not complete account deletion.",
        retryLabel: isCurrentAccountRequest(deletionIdentity) ? "Retry deletion" : "",
        onRetry: () => {
          if (!isCurrentAccountRequest(deletionIdentity)) return;
          progress.close();
          deleteAccountButton.disabled = false;
          deleteAccountButton.click();
        }
      });
    };

    let payload;
    try {
      requireCurrentAccountRequest(deletionIdentity);
      payload = await deleteCapturedAccount(account, deletionIdentity);
    } catch (error) {
      setStatus(error.message || "Could not delete this account.", true);
      deleteAccountButton.disabled = false;
      showBackendFailure(error);
      return;
    }

    const stripeResult = payload.billingCancellation?.stripe;
      progress.setStage(
        "billing",
        stripeResult?.status === "canceled" ? "complete" : "skipped",
        stripeResult?.status === "canceled"
          ? `Stripe canceled ${stripeResult.subscriptionCount || 1} subscription${stripeResult.subscriptionCount === 1 ? "" : "s"}.`
          : "No Stripe subscription was linked."
      );
      progress.setStage(
        "data",
        "complete",
        `Permitext data and ${payload.deletedPrivateAssetCount || 0} private image${payload.deletedPrivateAssetCount === 1 ? "" : "s"} were deleted.`
      );

      progress.setStage("device", "active");
      let deviceFailures = await clearThisBrowser();
      progress.setStage(
        "device",
        deviceFailures.length ? "failed" : "complete",
        deviceFailures.length ? deviceFailures.join(" ") : "Account-scoped browser data was cleared. Unattributed legacy data remains isolated."
      );

      progress.setStage("identity", "active");
      let identityError = null;
      try {
        const identityResult = await removeClerkIdentity();
        progress.setStage(
          "identity",
          identityResult === "deleted" ? "complete" : "skipped",
          identityResult === "deleted"
            ? "The Permitext Clerk sign-in identity was removed."
            : "No separate Clerk identity needed removal."
        );
      } catch (error) {
        identityError = error;
        reportClientError("error", error, { source: "account-deletion" });
        progress.setStage("identity", "failed", error.message || "The Clerk sign-in identity was not removed.");
      }

      try {
        await renderWorkspace();
      } catch (error) {
        deviceFailures.push(`Interface refresh: ${error.message || "could not be completed"}`);
        progress.setStage("device", "failed", deviceFailures.join(" "));
      }
      const finishCleanup = () => {
        const incomplete = deviceFailures.length > 0 || Boolean(identityError);
        progress.finish({
          title: incomplete ? "Permitext data deleted; cleanup incomplete" : "Permitext account deleted",
          message: incomplete
            ? "The stages marked Needs attention remain. Retry cleanup or contact support; the result above shows exactly what was completed."
            : "Your account and data were handled as shown above. Unattributed legacy browser data remains isolated for ownership review.",
          retryLabel: incomplete ? "Retry cleanup" : "",
          onRetry: incomplete ? async () => {
            if (deviceFailures.length) {
              progress.setStage("device", "active");
              deviceFailures = await clearThisBrowser();
              try {
                await renderWorkspace();
              } catch (error) {
                deviceFailures.push(`Interface refresh: ${error.message || "could not be completed"}`);
              }
              progress.setStage(
                "device",
                deviceFailures.length ? "failed" : "complete",
                deviceFailures.length ? deviceFailures.join(" ") : "Account-scoped browser data was cleared. Unattributed legacy data remains isolated."
              );
            }
            if (identityError) {
              progress.setStage("identity", "active");
              try {
                await removeClerkIdentity();
                identityError = null;
                progress.setStage("identity", "complete", "The Permitext Clerk sign-in identity was removed.");
              } catch (error) {
                identityError = error;
                progress.setStage("identity", "failed", error.message || "The Clerk sign-in identity was not removed.");
              }
            }
            finishCleanup();
          } : null
        });
      };
      finishCleanup();
  });
  checkoutButton.addEventListener("click", async () => {
    if (checkoutInFlight || !isCurrentAccountRequest(settingsIdentity)) return;
    const account = activeAccount();
    if (!account) return;
    if (isProAccount()) {
      if (currentEntitlement()?.source === "lifetimeGrant") return;
      if (currentEntitlement()?.source === "appleSubscription") {
        window.location.href = "https://apps.apple.com/account/subscriptions";
        return;
      }
      checkoutButton.disabled = true;
      setStatus("Opening subscription management...");
      try {
        const payload = await postJSON("/billing/web/portal", { auth: { accountUserID: account.userID } }, { token: account.sessionToken });
        if (!payload.url) throw new Error("Subscription management did not return a URL.");
        window.location.href = payload.url;
      } catch (error) {
        setStatus(error.message || "Could not open subscription management.", true);
        checkoutButton.disabled = false;
      }
      return;
    }
    checkoutButton.disabled = true;
    checkoutInFlight = true;
    policyAcceptance.disabled = true;
    setStatus("Confirming your policy acceptance...");
    try {
      if (!policyAcceptance.checked) {
        throw new Error("Review and accept the current policies before upgrading.");
      }
      const latestPolicyConfiguration = await loadCurrentPolicyConfiguration();
      requireCurrentAccountRequest(settingsIdentity);
      if (!latestPolicyConfiguration.configured || !latestPolicyConfiguration.versions) {
        throw new Error("Purchases are temporarily unavailable while approved policy versions are being prepared.");
      }
      if (latestPolicyConfiguration.policySetID !== currentPolicyConfiguration?.policySetID) {
        applyPolicyConfiguration(latestPolicyConfiguration);
        policyAcceptance.checked = false;
        syncAccountState();
        throw new Error("The policies changed. Review the current documents and select the agreement again.");
      }
      const release = await loadReleaseIdentity();
      requireCurrentAccountRequest(settingsIdentity);
      await postJSON(
        "/account/policy-acceptance",
        {
          auth: { accountUserID: account.userID },
          platform: "web",
          versions: latestPolicyConfiguration.versions,
          clientRelease: release?.releaseID || "web-unknown"
        },
        { token: account.sessionToken }
      );
      setStatus("Opening checkout...");
      requireCurrentAccountRequest(settingsIdentity);
      const payload = await postJSON(
        "/billing/web/checkout",
        {
          auth: { accountUserID: account.userID },
          packageID: "pro",
          ...(upgrade ? { cancelURL: new URL("/#plans", location.origin).href } : {})
        },
        { token: account.sessionToken }
      );
      if (!payload.url) throw new Error("Checkout did not return a URL.");
      requireCurrentAccountRequest(settingsIdentity);
      clearProUpgradeIntent();
      window.location.href = payload.url;
    } catch (error) {
      checkoutInFlight = false;
      setStatus(error.message || "Could not open checkout.", true);
      syncAccountState();
    }
  });
  planSecondaryButton.addEventListener("click", async () => {
    const account = activeAccount();
    if (!account) return;
    planSecondaryButton.disabled = true;
    const restored = await openStripeRestoreDialog(async (restoreID) => {
      const payload = await postJSON(
        "/billing/stripe/restore",
        {
          auth: { accountUserID: account.userID },
          restoreID
        },
        { token: account.sessionToken }
      );
      storeAccountEntitlement(payload.entitlement || null);
    });
    if (restored) {
      await renderWorkspace();
      return;
    }
    planSecondaryButton.disabled = false;
  });
  offlineDownload.addEventListener("click", async () => {
    const account = activeAccount();
    if (!account) {
      signInButton.click();
      return;
    }
    if (!hasCapability("offline-access")) {
      checkoutButton.click();
      return;
    }
    offlineDownload.disabled = true;
    offlineRemove.hidden = true;
    offlineProgress.hidden = false;
    offlineProgress.value = 0;
    offlineStatus.textContent = "Confirming Pro access…";
    try {
      await loadSyncedContent({ force: true });
      if (!hasCapability("offline-access")) {
        await disableOfflineFeature();
        throw new Error("An active Pro plan is required for offline access.");
      }
      await downloadOfflineLibrary({
        codeVersion: defaultSyncCodeVersion,
        onProgress(progress) {
          offlineProgress.value = progress.percent || 0;
          offlineStatus.textContent = progress.total > 1
            ? `${progress.phase} · ${progress.completed} of ${progress.total} ${progress.unit || "items"}${progress.detail ? ` · ${progress.detail}` : ""}`
            : progress.phase;
        }
      });
      if (syncedContent?.status === "connected" && account.userID === syncedContent.userID) {
        await saveOfflineSyncSnapshot(account.userID, syncedContent);
      }
      offlineStatus.textContent = "Offline access is ready.";
      await renderOfflineState();
    } catch (error) {
      const message = error.message || "Could not download offline codes.";
      offlineProgress.hidden = true;
      await renderOfflineState();
      offlineStatus.textContent = message;
    }
  });
  offlineRemove.addEventListener("click", async () => {
    offlineRemove.disabled = true;
    offlineStatus.textContent = "Removing offline download…";
    try {
      await disableOfflineFeature();
      offlineStatus.textContent = "Offline download removed.";
      await renderOfflineState();
    } catch (error) {
      offlineStatus.textContent = error.message || "Could not remove the offline download.";
      offlineRemove.disabled = false;
    }
  });

  attachSettingsTrash(panel);
  const clearActionCopy = {
    searches: ["Clear recent searches", "This will remove recent searches and Recently Viewed sections from this account across synced devices. Pinned searches will remain. Are you sure?"],
    bookmarks: ["Move Saved passages to Trash", `${bookmarkRecordsForSettings().length} saved passages and their Project memberships will move to Trash across synced devices. Restore within 30 days. Projects and notes remain.`],
    notes: ["Move notes to Trash", `${(currentContentSummary().annotations || []).filter(item => String(item.noteBody || "").trim()).length} notes across all code versions will move to Trash across synced devices. Restore within 30 days. Saved passages and tags remain.`]
  };
  panel.querySelectorAll("[data-clear-action]").forEach((button) => {
    button.addEventListener("click", async () => {
      const action = button.dataset.clearAction;
      const [title, message] = clearActionCopy[action];
      const confirmed = await confirmWebWarning(title, message, { confirmLabel: "Confirm" });
      if (!confirmed) return;
      const settingsScrollTop = settingsPanelScrollTop(panel);
      const workspaceScrollLeft = track.scrollLeft;
      button.disabled = true;
      try {
        if (action !== "searches") await prepareRecoverableDeletion();
        requireCurrentAccountRequest(settingsIdentity);
        const count = await performSettingsClearAction(action);
        if (action !== "searches") { await prepareRecoverableDeletion(); openTrashAfterSettingsDeletion = true; }
        setStatus(action === "searches" ? "Recent searches cleared." : `${count} ${action} moved to Trash. Open Trash to undo.`);
        await refreshWorkspaceAfterSettingsClear(settingsScrollTop, workspaceScrollLeft);
      } catch (error) {
        setStatus(error.message || `Could not clear ${action}.`, true);
        button.disabled = false;
      }
    });
  });
  return panel;
}

function singleExpandedDividerEdge(previousPaneID, nextPaneID) {
  const previousOpen = previousPaneID && !paneIsCollapsed(previousPaneID);
  const nextOpen = nextPaneID && !paneIsCollapsed(nextPaneID);
  // The pinned boundary belongs only to the fixed column, not the scrolling
  // neighbor that happens to follow it in the mounted sequence.
  if (previousOpen && previousPaneID === activePinnedPaneID()) return { paneID: previousPaneID, side: "right" };
  if (previousOpen && !nextOpen) return { paneID: previousPaneID, side: "right" };
  if (nextOpen && !previousOpen) return { paneID: nextPaneID, side: "left" };
  return null;
}

function updateAdjacentDividerValue(divider, previousWidth, nextWidth) {
  const total = previousWidth + nextWidth;
  divider.setAttribute("aria-valuemin", "0");
  divider.setAttribute("aria-valuemax", "100");
  divider.setAttribute("aria-valuenow", String(Math.round(previousWidth / total * 100)));
  divider.setAttribute("aria-valuetext", `Left column ${Math.round(previousWidth)} pixels; right column ${Math.round(nextWidth)} pixels`);
}

function resizeAdjacentPanesBy(previousPaneID, nextPaneID, delta, divider) {
  if (paneIsCollapsed(previousPaneID) || paneIsCollapsed(nextPaneID)) return;
  const previousPane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(previousPaneID)}"]`);
  const nextPane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(nextPaneID)}"]`);
  if (!previousPane || !nextPane) return;
  const previousWidth = previousPane.getBoundingClientRect().width;
  const nextWidth = nextPane.getBoundingClientRect().width;
  const scrollLeft = track.scrollLeft;
  const widths = [
    Math.max(minimumPaneWidthForID(previousPaneID), previousWidth + delta),
    Math.max(minimumPaneWidthForID(nextPaneID), nextWidth - delta)
  ];
  state.paneWeights[previousPaneID] = widths[0];
  state.paneWeights[nextPaneID] = widths[1];
  applyPaneWeight(previousPane, previousPaneID);
  applyPaneWeight(nextPane, nextPaneID);
  // Match pointer resizing when one column reaches its minimum width.
  track.scrollLeft = Math.max(0, scrollLeft + widths[0] - previousWidth - delta);
  updateAdjacentDividerValue(divider, ...widths);
  scheduleVisibleReaderScrollIndicatorUpdates();
  notifyWorkspaceLayoutChange();
  saveWorkspaceState();
}

function refreshPaneDividerValue(divider) {
  const previousID = divider.dataset.previousPaneId;
  const nextID = divider.dataset.nextPaneId;
  const edge = singleExpandedDividerEdge(previousID, nextID);
  const paneForID = (id) => id ? track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(id)}"]`) : null;
  const previousPane = paneForID(previousID);
  const nextPane = paneForID(nextID);
  const pairOpen = previousPane && nextPane && !paneIsCollapsed(previousID) && !paneIsCollapsed(nextID);
  divider.tabIndex = edge || pairOpen ? 0 : -1;
  if (edge) {
    const pane = edge.paneID === previousID ? previousPane : nextPane;
    if (!pane) return;
    const width = Math.round(pane.getBoundingClientRect().width);
    divider.setAttribute("aria-valuemin", String(Math.round(minimumPaneWidthForID(edge.paneID))));
    divider.removeAttribute("aria-valuemax");
    divider.setAttribute("aria-valuenow", String(width));
    divider.setAttribute("aria-valuetext", `Column width ${width} pixels`);
  } else if (pairOpen) {
    updateAdjacentDividerValue(divider, previousPane.getBoundingClientRect().width, nextPane.getBoundingClientRect().width);
  } else {
    ["aria-valuemin", "aria-valuemax", "aria-valuenow", "aria-valuetext"].forEach((name) => divider.removeAttribute(name));
  }
}

function createDivider(previousPaneID, nextPaneID) {
  const isLeftEdge = !previousPaneID && Boolean(nextPaneID);
  const isRightEdge = Boolean(previousPaneID) && !nextPaneID;
  const edgePaneID = isLeftEdge ? nextPaneID : previousPaneID;
  const divider = document.createElement("div");
  divider.className = "pane-divider";
  if (isLeftEdge || isRightEdge) {
    divider.classList.add(
      "pane-edge-resizer",
      isLeftEdge ? "pane-left-edge-resizer" : "pane-right-edge-resizer"
    );
  }
  divider.dataset.previousPaneId = previousPaneID || "";
  divider.dataset.nextPaneId = nextPaneID || "";
  divider.role = "separator";
  divider.tabIndex = 0;
  divider.setAttribute("aria-orientation", "vertical");
  divider.setAttribute(
    "aria-label",
    isLeftEdge
      ? "Resize left edge of first column"
      : isRightEdge
        ? "Resize right edge of last column"
        : "Resize adjacent columns"
  );
  if (isLeftEdge || isRightEdge) {
    divider.setAttribute("aria-valuemin", String(Math.round(minimumPaneWidthForID(edgePaneID))));
  }
  divider.addEventListener("focus", () => refreshPaneDividerValue(divider));
  divider.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    const edge = singleExpandedDividerEdge(previousPaneID, nextPaneID);
    if (!edge && (!previousPaneID || !nextPaneID || paneIsCollapsed(previousPaneID) || paneIsCollapsed(nextPaneID))) return;
    event.preventDefault();
    const step = event.shiftKey ? 80 : 24;
    if (edge) {
      const growsPane = edge.side === "left" ? event.key === "ArrowLeft" : event.key === "ArrowRight";
      resizePaneEdgeBy(edge.paneID, growsPane ? step : -step, divider);
    } else {
      resizeAdjacentPanesBy(previousPaneID, nextPaneID, event.key === "ArrowRight" ? step : -step, divider);
    }
  });
  divider.addEventListener("pointerdown", (event) => {
    const edge = singleExpandedDividerEdge(previousPaneID, nextPaneID);
    if (edge) startPaneEdgeResize(event, edge.paneID, edge.side);
    else if (previousPaneID && nextPaneID) startPaneResize(event, previousPaneID, nextPaneID);
  });
  divider.addEventListener("dblclick", () => {
    const edge = singleExpandedDividerEdge(previousPaneID, nextPaneID);
    if (edge) resetDividerPanes(edge.paneID, null);
    else if (isLeftEdge || isRightEdge) resetDividerPanes(edgePaneID, null);
    else resetDividerPanes(previousPaneID, nextPaneID);
  });
  return divider;
}

function resetDividerPanes(previousPaneID, nextPaneID) {
  const currentLeft = track.scrollLeft;
  [previousPaneID, nextPaneID].forEach((paneID) => {
    if (!paneID || paneIsCollapsed(paneID)) return;
    state.paneWeights[paneID] = defaultPaneWidthForID(paneID);
    const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
    if (pane) applyPaneWeight(pane, paneID);
  });
  saveWorkspaceState();
  requestAnimationFrame(() => {
    track.scrollLeft = Math.min(currentLeft, Math.max(0, track.scrollWidth - track.clientWidth));
  });
}

function captureColumnGroupContents() {
  if (!(state.columnGroups || []).length) return;
  const active = new Set(defaultActivePaneIDs());
  const positions = captureReaderScrollPositions();
  const projectTypes = [
    ['notebooks', paneIDForProjectNotebook], ['reportDrafts', paneIDForProjectReportDraft],
    ['coordinations', paneIDForProjectCoordination], ['workboards', paneIDForProjectWorkboard]
  ];
  for (const group of state.columnGroups) {
    group.columns ||= {};
    for (const id of group.paneIDs.filter((id) => active.has(id))) {
      const reader = state.readers.find((item) => paneIDForReader(item) === id);
      const instance = state.utilityInstances.find((item) => paneIDForUtilityInstance(item) === id);
      let column = null;
      if (reader) column = { kind: 'reader', value: reader, position: positions.get(id) || group.columns[id]?.position };
      else if (instance) column = { kind: 'utility', value: instance, draft: researchNewChatDrafts.get(id), draftShowing: researchDraftPaneIDs.has(id) };
      else if (id === 'utility:analysis' || id.startsWith('research:conversation:')) {
        column = { kind: 'research', value: { conversationID: id === 'utility:analysis' ? state.researchConversationID : id.slice('research:conversation:'.length), historyShowing: id === 'utility:analysis' && researchHistoryShowing }, draft: researchNewChatDrafts.get(id), draftShowing: researchDraftPaneIDs.has(id) };
      } else {
        for (const [key, paneID] of projectTypes) {
          const detail = openProjectDetails().find((item) => paneID(item) === id);
          if (detail) column = { kind: 'project', key, value: detail, host: state.projectHostPaneID };
        }
        if (!column && ['utility:settings', 'utility:archive'].includes(id)) column = { kind: 'singleton', key: id.slice(8) };
      }
      if (!column) continue;
      group.columns[id] = JSON.parse(JSON.stringify({ ...column, width: state.paneWeights[id] || defaultPaneWidthForID(id), collapsed: (state.collapsedPaneIDs || []).includes(id) }));
    }
  }
}

async function restoreSavedColumnGroup(groupID) {
  captureColumnGroupContents();
  const group = (state.columnGroups || []).find((item) => item.id === groupID);
  if (!group) return;
  const active = new Set(defaultActivePaneIDs());
  const missing = group.paneIDs.filter((id) => !active.has(id));
  if (!missing.length) {
    const first = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(group.paneIDs[0])}"]`);
    if (first) track.scrollTo({ left: track.scrollLeft + first.getBoundingClientRect().left - track.getBoundingClientRect().left, behavior: 'smooth' });
    return;
  }
  if (missing.some((id) => !group.columns?.[id])) {
    showWebNotice('Group unavailable', 'Some columns were closed before their contents could be saved. Edit the group to remove those columns.');
    return;
  }
  const collapsed = new Set(state.collapsedPaneIDs || []);
  for (const oldID of missing) {
    const column = JSON.parse(JSON.stringify(group.columns[oldID]));
    let id = oldID;
    if (column.kind === 'reader') {
      state.readers.push(column.value);
      if (column.position) pendingGroupReaderPositions.set(column.value.id, column.position);
    } else if (column.kind === 'utility' || column.kind === 'research') {
      // Legacy singleton Research becomes an owned instance, never the current ungrouped Research.
      const instance = column.kind === 'research' ? newUtilityInstance('analysis', column.value) : column.value;
      state.utilityInstances.push(instance);
      id = paneIDForUtilityInstance(instance);
      if (column.draft !== undefined) researchNewChatDrafts.set(id, column.draft);
      if (column.draftShowing) researchDraftPaneIDs.add(id);
      if (id !== oldID) {
        group.paneIDs = group.paneIDs.map((member) => member === oldID ? id : member);
        group.columns[id] = { ...column, kind: 'utility', value: instance };
        delete group.columns[oldID];
      }
    } else if (column.kind === 'project') {
      setOpenProjectDetails([...openProjectDetails(), column.value]);
      const records = state[column.key] || [];
      if (!records.some((item) => projectDetailKey(item) === projectDetailKey(column.value))) records.push(column.value);
      state[column.key] = records;
      if (!state.projectHostPaneID) state.projectHostPaneID = column.host || '';
    } else if (column.kind === 'singleton') state.utilities[column.key] = true;
    state.paneWeights[id] = column.width || defaultPaneWidthForID(id);
    if (column.collapsed) collapsed.add(id); else collapsed.delete(id);
  }
  state.collapsedPaneIDs = [...collapsed];
  state.paneOrder = [...(state.paneOrder || []).filter((id) => !group.paneIDs.includes(id)), ...group.paneIDs];
  saveWorkspaceState();
  await transitionWorkspace('utility');
  const first = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(group.paneIDs[0])}"]`);
  if (first) track.scrollTo({ left: track.scrollLeft + first.getBoundingClientRect().left - track.getBoundingClientRect().left, behavior: 'smooth' });
}

function openSavedColumnGroupsMenu(anchor = workspaceActionsButton) {
  if (!workspacePrivatePresentationAllowed()) return;
  document.querySelector('.column-group-menu')?._close?.();
  const menu = document.createElement('div');
  menu.className = 'column-group-menu saved-column-groups-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'Saved column groups');
  const controller = new AbortController();
  const close = () => { controller.abort(); menu.remove(); anchor.focus({ preventScroll: true }); };
  menu._close = close;
  const active = new Set(defaultActivePaneIDs());
  for (const group of state.columnGroups || []) {
    const button = document.createElement('button');
    button.type = 'button'; button.setAttribute('role', 'menuitem');
    const opened = group.paneIDs.every((id) => active.has(id));
    button.textContent = `${group.name} · ${group.paneIDs.length} columns${opened ? ' · Open' : ''}`;
    button.addEventListener('click', () => { close(); void restoreSavedColumnGroup(group.id); });
    menu.append(button);
  }
  // Existing groups remain recoverable; new work uses automatic view restoration.
  document.body.append(menu);
  const rect = anchor.getBoundingClientRect();
  menu.style.left = `${Math.max(8, Math.min(rect.left + (rect.width - menu.offsetWidth) / 2, window.innerWidth - menu.offsetWidth - 8))}px`;
  menu.style.top = `${rect.bottom + 6}px`;
  menu.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') { event.preventDefault(); close(); }
    if (event.key === 'Tab') close();
    const buttons = [...menu.querySelectorAll('button')];
    if (buttons.length && ['ArrowDown', 'ArrowUp'].includes(event.key)) {
      event.preventDefault();
      buttons[(buttons.indexOf(document.activeElement) + (event.key === 'ArrowDown' ? 1 : buttons.length - 1)) % buttons.length].focus();
    }
  });
  document.addEventListener('pointerdown', (event) => { if (!menu.contains(event.target) && event.target !== anchor) close(); }, { signal: controller.signal });
  menu.querySelector('button')?.focus();
}

function columnGroupForPane(paneID) {
  return (state.columnGroups || []).find((group) => group.paneIDs.includes(paneID)) || null;
}

function reconcileColumnGroups(paneIDs) {
  const active = new Set(paneIDs);
  state.columnGroups = normalizeColumnGroups((state.columnGroups || []).map((group) => {
    // Retire a closed legacy Research singleton's ID before an ungrouped Research can reuse it.
    group.paneIDs = group.paneIDs.map((id) => {
      const column = group.columns?.[id];
      if (active.has(id) || column?.kind !== 'research') return id;
      const instance = newUtilityInstance('analysis', column.value);
      const ownedID = paneIDForUtilityInstance(instance);
      group.columns[ownedID] = { ...column, kind: 'utility', value: instance };
      delete group.columns[id];
      return ownedID;
    });
    const members = new Set(group.paneIDs);
    for (const id of [...members].filter((id) => active.has(id))) basePaneGroupForMove(id, paneIDs).forEach((member) => members.add(member));
    // Evidence details belong to their saved list, outside custom column groups.
    return { ...group, paneIDs: [...members].filter((id) => !savedEvidenceColumnGroup(id, paneIDs).length) };
  }));
}

function paneGroupForMove(paneID, orderedIDs = activePaneIDs()) {
  const group = columnGroupForPane(paneID);
  return group ? group.paneIDs.filter((id) => orderedIDs.includes(id)) : basePaneGroupForMove(paneID, orderedIDs);
}

function basePaneGroupForMove(paneID, orderedIDs = activePaneIDs()) {
  if (!paneID) return [];
  const active = new Set(orderedIDs);
  const evidenceGroup = savedEvidenceColumnGroup(paneID, orderedIDs);
  if (evidenceGroup.length) return evidenceGroup;
  const primaryResearchPaneID = paneIDForResearchConversation();
  if (paneID === "utility:analysis" || (primaryResearchPaneID && paneID === primaryResearchPaneID)) {
    return [...new Set(["utility:analysis", primaryResearchPaneID])].filter((id) => id && active.has(id));
  }
  if (paneID.startsWith("research:conversation:")) return active.has(paneID) ? [paneID] : [];
  if (savedPaneIDs().includes(paneID)) return active.has(paneID) ? [paneID] : [];
  if (isProjectDetailPaneID(paneID)) {
    return [
      primarySavedPaneID(),
      ...openProjectDetails().flatMap(projectWorkspacePaneIDs),
      "utility:archive"
    ].filter((id) => active.has(id));
  }
  if (isProjectToolPaneID(paneID)) {
    const detail = projectForToolPaneID(paneID);
    const coordinationID = paneIDForProjectCoordination(detail);
    const thread = openCoordinationThreadForProject(detail);
    const threadID = thread ? paneIDForProjectCoordinationThread(detail, thread.threadID) : "";
    if (paneID === coordinationID || paneID === threadID) {
      return [coordinationID, threadID].filter((id) => active.has(id));
    }
    return active.has(paneID) ? [paneID] : [];
  }
  if (paneID.startsWith("utility:search:")) {
    const searchID = paneID.replace("utility:search:", "");
    return [paneID, paneIDForSectionDetail(searchID), linkedReaderPaneIDForSearch(searchID)].filter((id) => active.has(id));
  }
  if (paneID.startsWith("section:detail:")) {
    const searchID = paneID.replace("section:detail:", "");
    return [paneIDForUtilityInstance({ key: "search", id: searchID }), paneID, linkedReaderPaneIDForSearch(searchID)].filter((id) => active.has(id));
  }
  const linkedSearchID = searchIDForLinkedReaderPane(paneID);
  if (linkedSearchID) {
    if ((state.utilityInstances || []).some((instance) => instance.id === linkedSearchID && instance.key === "sdc")) {
      return active.has(paneID) ? [paneID] : [];
    }
    return [paneIDForUtilityInstance({ key: "search", id: linkedSearchID }), paneIDForSectionDetail(linkedSearchID), paneID].filter((id) => active.has(id));
  }
  return active.has(paneID) ? [paneID] : [];
}

function orderWithPaneMoved(draggedPaneID, targetPaneID, position) {
  if (!draggedPaneID || !targetPaneID || draggedPaneID === targetPaneID) return null;
  const currentOrder = activePaneIDs();
  const draggedGroup = paneGroupForMove(draggedPaneID, currentOrder);
  const targetGroup = paneGroupForMove(targetPaneID, currentOrder);
  if (!draggedGroup.length || !targetGroup.length) return null;
  if (draggedGroup.some((id) => targetGroup.includes(id))) return null;
  const order = currentOrder.filter((id) => !draggedGroup.includes(id));
  const targetIndexes = targetGroup.map((id) => order.indexOf(id)).filter((index) => index !== -1);
  if (!targetIndexes.length) return null;
  const targetIndex = position === "after" ? Math.max(...targetIndexes) + 1 : Math.min(...targetIndexes);
  if (targetIndex === -1) return null;
  order.splice(targetIndex, 0, ...draggedGroup);
  return pinCriticalWorkflowPanesToLeft(order);
}

function applyDragPreviewOrder(order) {
  if (!Array.isArray(order) || !order.length) return;
  const previousRects = new Map(
    Array.from(track.querySelectorAll(".workspace-panel")).map((pane) => [pane.dataset.paneId, pane.getBoundingClientRect()])
  );
  dragPreviewOrder = order;
  const paneIndex = new Map(order.map((id, index) => [id, index]));
  track.querySelectorAll(".workspace-panel").forEach((pane) => {
    const index = paneIndex.get(pane.dataset.paneId);
    if (index !== undefined) pane.style.order = pane.dataset.paneId === activePinnedPaneID() ? "-2" : String(index * 2);
  });
  track.querySelectorAll(".pane-divider").forEach((divider) => {
    const previousIndex = paneIndex.get(divider.dataset.previousPaneId);
    const nextIndex = paneIndex.get(divider.dataset.nextPaneId);
    const index = Math.min(previousIndex ?? Number.MAX_SAFE_INTEGER, nextIndex ?? Number.MAX_SAFE_INTEGER);
    divider.style.order = divider.classList.contains("is-pinned-divider") ? "-1" : String(index * 2 + 1);
  });
  track.querySelectorAll(".workspace-panel").forEach((pane) => {
    const previousRect = previousRects.get(pane.dataset.paneId);
    if (!previousRect) return;
    const nextRect = pane.getBoundingClientRect();
    if (pane.dataset.paneId === activePinnedPaneID()) return;
    const deltaX = previousRect.left - nextRect.left;
    if (Math.abs(deltaX) < 1) return;
    pane.style.willChange = "transform";
    pane.style.transition = "none";
    pane.style.transform = `translateX(${deltaX}px)`;
    requestAnimationFrame(() => {
      pane.style.transition = "";
      pane.style.transform = "";
      pane.style.willChange = "";
    });
  });
}

function clearDragPreviewOrder() {
  dragPreviewOrder = [];
  track.querySelectorAll(".workspace-panel, .pane-divider").forEach((node) => {
    node.style.order = "";
  });
}

function bindPaneDragging(panes) {
  panes.forEach((pane) => {
    const header = pane.querySelector(":scope > header");
    if (header) {
      header.classList.add("pane-header-drag-area");
      header.title = "Drag to move · Click title to collapse";
    }
    pane.querySelectorAll(".pane-header-drag-area, .pane-collapsed-tab, :scope > .pane-drag-handle").forEach((handle) => {
      if (handle.dataset.dragBound === "true") return;
      handle.dataset.dragBound = "true";
      handle.draggable = true;
      if (handle === header) {
        // Native dragstart targets the draggable ancestor, so remember where
        // the pointer actually started before allowing a header drag.
        handle.addEventListener("pointerdown", (event) => {
          handle._dragFromControl = Boolean(event.target.closest("button, a, input, select, textarea, summary, [contenteditable], [role='button']"));
        }, true);
      }

      handle.addEventListener("dragstart", (event) => {
        if (handle === header && handle._dragFromControl) {
          event.preventDefault();
          return;
        }
        pane.classList.add("is-dragging");
        draggedPaneID = pane.dataset.paneId || "";
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", draggedPaneID);
      });

      handle.addEventListener("dragend", () => {
        handle._suppressExpandUntil = Date.now() + 250;
        const finalOrder = dragPreviewOrder.length ? dragPreviewOrder.slice() : null;
        draggedPaneID = "";
        pane.classList.remove("is-dragging");
        track.querySelectorAll(".workspace-panel.is-drop-before, .workspace-panel.is-drop-after").forEach((panel) => {
          panel.classList.remove("is-drop-before", "is-drop-after");
        });
        if (finalOrder?.length) {
          state.paneOrder = finalOrder;
          saveWorkspaceState();
          clearDragPreviewOrder();
          void transitionWorkspace("utility");
        } else {
          clearDragPreviewOrder();
        }
      });

    });
    if (pane.dataset.dragBound === "true") return;
    pane.dataset.dragBound = "true";

    pane.addEventListener("dragover", (event) => {
      const activeDraggedPaneID = draggedPaneID || event.dataTransfer.getData("text/plain");
      if (!activeDraggedPaneID || activeDraggedPaneID === pane.dataset.paneId) return;
      const rect = pane.getBoundingClientRect();
      const position = event.clientX > rect.left + rect.width / 2 ? "after" : "before";
      const previewOrder = orderWithPaneMoved(activeDraggedPaneID, pane.dataset.paneId, position);
      if (!previewOrder) {
        pane.classList.remove("is-drop-before", "is-drop-after");
        return;
      }
      event.preventDefault();
      if (previewOrder && previewOrder.join("|") !== dragPreviewOrder.join("|")) {
        applyDragPreviewOrder(previewOrder);
      }
      pane.classList.toggle("is-drop-before", position === "before");
      pane.classList.toggle("is-drop-after", position === "after");
    });

    pane.addEventListener("dragleave", () => {
      pane.classList.remove("is-drop-before", "is-drop-after");
    });

    pane.addEventListener("drop", (event) => {
      const activeDraggedPaneID = draggedPaneID || event.dataTransfer.getData("text/plain");
      if (!activeDraggedPaneID || activeDraggedPaneID === pane.dataset.paneId) return;
      event.preventDefault();
      const rect = pane.getBoundingClientRect();
      const position = event.clientX > rect.left + rect.width / 2 ? "after" : "before";
      const validOrder = orderWithPaneMoved(activeDraggedPaneID, pane.dataset.paneId, position);
      const nextOrder = validOrder && dragPreviewOrder.length ? dragPreviewOrder.slice() : validOrder;
      draggedPaneID = "";
      if (nextOrder?.length) {
        state.paneOrder = nextOrder;
        saveWorkspaceState();
        clearDragPreviewOrder();
        void transitionWorkspace("utility");
      } else {
        clearDragPreviewOrder();
      }
    });
  });
}

function startPaneResize(event, previousPaneID, nextPaneID) {
  if (paneIsCollapsed(previousPaneID) || paneIsCollapsed(nextPaneID)) return;
  const panes = Array.from(track.querySelectorAll(".workspace-panel"));
  const previousPane = panes.find((pane) => pane.dataset.paneId === previousPaneID);
  const nextPane = panes.find((pane) => pane.dataset.paneId === nextPaneID);
  if (!previousPane || !nextPane) return;

  event.preventDefault();
  const resizeHandle = event.currentTarget;
  resizeHandle?.setPointerCapture?.(event.pointerId);
  track.classList.add("is-resizing");
  const startX = event.clientX;
  const startScrollLeft = track.scrollLeft;
  const paneData = panes.map((pane) => ({
    id: pane.dataset.paneId,
    pane,
    startWidth: pane.getBoundingClientRect().width,
    minWidth: minimumPaneWidthForID(pane.dataset.paneId)
  }));
  const previousIndex = paneData.findIndex((pane) => pane.id === previousPaneID);
  const nextIndex = paneData.findIndex((pane) => pane.id === nextPaneID);
  if (previousIndex === -1 || nextIndex === -1) {
    track.classList.remove("is-resizing");
    return;
  }
  const lastAppliedWidths = paneData.map((pane) => pane.startWidth);
  let pendingClientX = startX;
  let resizeFrame = null;

  const applyResizeAt = (clientX) => {
    const delta = clientX - startX;
    const widths = paneData.map((pane) => pane.startWidth);
    widths[previousIndex] = Math.max(
      paneData[previousIndex].minWidth,
      paneData[previousIndex].startWidth + delta
    );
    widths[nextIndex] = Math.max(
      paneData[nextIndex].minWidth,
      paneData[nextIndex].startWidth - delta
    );
    [previousIndex, nextIndex].forEach((index) => {
      if (Math.abs(widths[index] - lastAppliedWidths[index]) < 0.25) return;
      const pane = paneData[index];
      state.paneWeights[pane.id] = widths[index];
      applyPaneWeight(pane.pane, pane.id);
      lastAppliedWidths[index] = widths[index];
    });
    syncReferenceReaderLayout();
    updateAdjacentDividerValue(resizeHandle, widths[previousIndex], widths[nextIndex]);
    const appliedPreviousDelta = widths[previousIndex] - paneData[previousIndex].startWidth;
    const pushedScrollDelta = appliedPreviousDelta - delta;
    track.scrollLeft = Math.max(0, startScrollLeft + pushedScrollDelta);
    scheduleVisibleReaderScrollIndicatorUpdates();
  };

  const applyPendingResize = () => {
    resizeFrame = null;
    applyResizeAt(pendingClientX);
  };

  const onMove = (moveEvent) => {
    pendingClientX = moveEvent.clientX;
    if (resizeFrame === null) resizeFrame = window.requestAnimationFrame(applyPendingResize);
  };

  const onUp = (upEvent) => {
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
    if (resizeFrame !== null) window.cancelAnimationFrame(resizeFrame);
    pendingClientX = Number.isFinite(upEvent.clientX) ? upEvent.clientX : pendingClientX;
    applyResizeAt(pendingClientX);
    if (resizeHandle?.hasPointerCapture?.(upEvent.pointerId)) {
      resizeHandle.releasePointerCapture(upEvent.pointerId);
    }
    track.classList.remove("is-resizing");
    notifyWorkspaceLayoutChange();
    saveWorkspaceState();
  };

  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", onUp, { once: true });
  window.addEventListener("pointercancel", onUp, { once: true });
}

function resizePaneEdgeBy(paneID, delta, resizeHandle = null) {
  if (paneIsCollapsed(paneID)) return;
  const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
  if (!pane) return;
  const minWidth = minimumPaneWidthForID(paneID);
  const currentWidth = pane.getBoundingClientRect().width;
  const nextWidth = Math.max(minWidth, currentWidth + delta);
  state.paneWeights[paneID] = nextWidth;
  applyPaneWeight(pane, paneID);
  resizeHandle?.setAttribute("aria-valuenow", String(Math.round(nextWidth)));
  resizeHandle?.setAttribute("aria-valuetext", `Column width ${Math.round(nextWidth)} pixels`);
  notifyWorkspaceLayoutChange();
  saveWorkspaceState();
}

function startPaneEdgeResize(event, paneID, edgeSide = "right") {
  if (paneIsCollapsed(paneID)) return;
  const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
  if (!pane) return;

  event.preventDefault();
  const resizeHandle = event.currentTarget;
  resizeHandle?.setPointerCapture?.(event.pointerId);
  track.classList.add("is-resizing");
  const startX = event.clientX;
  const startWidth = pane.getBoundingClientRect().width;
  const minWidth = minimumPaneWidthForID(paneID);
  const isReferenceResize = ["report", "project-details"].includes(currentColumnWorkflowView());
  const edgeAutoResizeThreshold = 32;
  const edgeAutoResizeMaxSpeed = 640;
  let pointerClientX = startX;
  let virtualClientX = startX;
  let resizeFrame = null;
  let previousFrameTime = null;
  let lastAppliedWidth = startWidth;
  let isDragging = true;

  const applyResizeAt = (clientX) => {
    const direction = edgeSide === "left" ? -1 : 1;
    const nextWidth = Math.max(minWidth, startWidth + direction * (clientX - startX));
    if (Math.abs(nextWidth - lastAppliedWidth) < 0.25) return;
    state.paneWeights[paneID] = nextWidth;
    applyPaneWeight(pane, paneID);
    syncReferenceReaderLayout();
    resizeHandle?.setAttribute("aria-valuenow", String(Math.round(nextWidth)));
    resizeHandle?.setAttribute("aria-valuetext", `Column width ${Math.round(nextWidth)} pixels`);
    lastAppliedWidth = nextWidth;
    if (edgeSide === "right") {
      const handleRect = resizeHandle.getBoundingClientRect();
      const trackRect = track.getBoundingClientRect();
      const overflow = handleRect.right - trackRect.right;
      if (overflow > 0) track.scrollLeft = Math.min(track.scrollLeft + overflow, track.scrollWidth - track.clientWidth);
    }
    scheduleVisibleReaderScrollIndicatorUpdates();
  };

  const edgeResizeVelocity = () => {
    const trackRect = track.getBoundingClientRect();
    if (edgeSide === "left") {
      // A reference dock follows the divider; only the screen edge should
      // trigger continued growth when the pointer stops moving.
      const visibleLeft = (isReferenceResize ? 0 : Math.max(trackRect.left, 0)) + 1;
      const edgeEnd = visibleLeft + edgeAutoResizeThreshold;
      if (pointerClientX >= edgeEnd) return 0;
      const proximity = Math.min(1, Math.max(0, (edgeEnd - pointerClientX) / edgeAutoResizeThreshold));
      return -edgeAutoResizeMaxSpeed * proximity;
    }
    const visibleRight = Math.min(trackRect.right, window.innerWidth) - 1;
    const edgeStart = visibleRight - edgeAutoResizeThreshold;
    if (pointerClientX <= edgeStart) return 0;
    const proximity = Math.min(1, Math.max(0, (pointerClientX - edgeStart) / edgeAutoResizeThreshold));
    return edgeAutoResizeMaxSpeed * proximity;
  };

  const applyPendingResize = (frameTime) => {
    resizeFrame = null;
    if (!isDragging) return;
    const elapsed = previousFrameTime === null
      ? 0
      : Math.min(32, Math.max(0, frameTime - previousFrameTime));
    previousFrameTime = frameTime;
    const velocity = edgeResizeVelocity();
    if (velocity !== 0 && elapsed > 0) {
      virtualClientX += velocity * elapsed / 1000;
    }
    applyResizeAt(virtualClientX);
    if (velocity !== 0) resizeFrame = window.requestAnimationFrame(applyPendingResize);
  };

  const onMove = (moveEvent) => {
    const nextPointerClientX = moveEvent.clientX;
    virtualClientX += nextPointerClientX - pointerClientX;
    pointerClientX = nextPointerClientX;
    if (resizeFrame === null) resizeFrame = window.requestAnimationFrame(applyPendingResize);
  };

  const onUp = (upEvent) => {
    isDragging = false;
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    window.removeEventListener("pointercancel", onUp);
    if (resizeFrame !== null) window.cancelAnimationFrame(resizeFrame);
    if (Number.isFinite(upEvent.clientX)) {
      virtualClientX += upEvent.clientX - pointerClientX;
      pointerClientX = upEvent.clientX;
    }
    applyResizeAt(virtualClientX);
    if (resizeHandle?.hasPointerCapture?.(upEvent.pointerId)) {
      resizeHandle.releasePointerCapture(upEvent.pointerId);
    }
    track.classList.remove("is-resizing");
    notifyWorkspaceLayoutChange();
    saveWorkspaceState();
  };

  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", onUp, { once: true });
  window.addEventListener("pointercancel", onUp, { once: true });
}

function notifyWorkspaceLayoutChange() {
  syncReferenceReaderLayout();
  track.dispatchEvent(new Event("permitext:workspace-layout-change"));
}

function ensureWorkspacePanelAccessibleName(panel) {
  if (!(panel instanceof HTMLElement)) return;
  const heading = panel.querySelector(
    ":scope > .panel-title, :scope > .panel-header .panel-title, :scope > header h2"
  );
  if (heading) {
    heading.id ||= `workspace-panel-heading-${crypto.randomUUID()}`;
    panel.setAttribute("aria-labelledby", heading.id);
    panel.removeAttribute("aria-label");
    return;
  }
  if (panel.hasAttribute("aria-label") || panel.hasAttribute("aria-labelledby")) return;
  const paneLabel = String(panel.dataset.paneId || "Workspace panel")
    .replace(/^utility:/, "")
    .replace(/[\:_-]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
  panel.setAttribute("aria-label", paneLabel || "Workspace panel");
}

function entryHasExternalIntent() {
  if (sectionRouteIDFromLocation() || detachedWorkboardRoute) return true;
  if (String(window.location.hash || "").startsWith("#cq/")) return true;
  const params = new URLSearchParams(window.location.search);
  return [
    "checkout",
    "session_id",
    "package",
    "appleSignIn",
    "organizationInvite",
    "detachedWorkboard",
    "enableCodeQuestionWorkspace"
  ].some((key) => params.has(key));
}

function workspaceHasPriorUse() {
  const summary = currentContentSummary();
  const activeWorkspace = activeWorkspaceRecord();
  return Boolean(
    activeAccount() ||
    (workspaceRegistry?.workspaces || []).length > 1 ||
    (activeWorkspace?.name && activeWorkspace.name !== "General") ||
    (state.localProjects || []).length ||
    (state.localSavedItems || []).length ||
    (state.localAnnotations || []).length ||
    (state.recentSearches || []).length ||
    (state.recentlyViewedSections || []).length ||
    Object.keys(state.recentChaptersByCode || {}).length ||
    (summary.projects || []).length ||
    (summary.savedItems || []).length
  );
}

function shouldShowFirstUseWelcome() {
  if (firstUseWelcomeActive) return true;
  if (detachedProjectWindow || entryHasExternalIntent() || workspaceHasPriorUse()) return false;
  try {
    if (localStorage.getItem(firstUseWelcomeSeenKey)) return false;
  } catch {
    // The welcome remains session-only when browser storage is unavailable.
  }
  firstUseWelcomeActive = true;
  return true;
}

function completeFirstUseWelcome() {
  firstUseWelcomeActive = false;
  try {
    localStorage.setItem(firstUseWelcomeSeenKey, new Date().toISOString());
  } catch {
    // No persisted dismissal is available in this browser session.
  }
}

function renderEmptyResearchWorkspace() {
  const welcome = document.createElement("section");
  welcome.className = "workspace-empty-state workspace-empty-research";
  welcome.setAttribute("aria-label", "Research tools");
  const content = document.createElement("div");
  const actions = document.createElement("div");
  actions.className = "workspace-empty-actions";
  const reader = createReaderToolbarButton();
  const search = document.createElement("button");
  search.type = "button";
  search.textContent = "Search";
  search.addEventListener("click", () => { void focusRecentUtilityColumn("search"); });
  const assistant = document.createElement("button");
  assistant.type = "button";
  assistant.textContent = "Assistant";
  assistant.addEventListener("click", () => { void focusRecentUtilityColumn("analysis"); });
  actions.append(reader, search, assistant);
  content.append(actions);
  welcome.append(content);
  return welcome;
}

function renderProjectRequiredWorkspace() {
  const welcome = document.createElement("section");
  welcome.className = "workspace-empty-state workspace-empty-guidance";
  welcome.setAttribute("aria-label", "Project required");
  const content = document.createElement("div");
  const actions = document.createElement("div");
  actions.className = "workspace-empty-actions";
  const create = document.createElement("button");
  create.type = "button";
  create.textContent = "Create Project";
  create.addEventListener("click", () => { void createNewWorkspace(); });
  actions.append(create);
  const message = document.createElement("p");
  message.className = "workspace-project-required-message";
  message.setAttribute("role", "alert");
  message.textContent = "Create a Project first to open workspace columns.";
  message.hidden = !projectRequiredColumnNoticeVisible;
  content.append(actions, message);
  welcome.append(content);
  return welcome;
}

function renderFirstUseWelcome() {
  const welcome = document.createElement("section");
  welcome.className = "workspace-empty-state workspace-first-use";
  const headingID = `first-use-heading-${crypto.randomUUID()}`;
  welcome.setAttribute("aria-labelledby", headingID);

  const content = document.createElement("div");
  content.className = "first-use-content";
  const heading = document.createElement("h1");
  heading.id = headingID;
  heading.textContent = "Explore NYC construction codes and read the enacted text.";
  const supporting = document.createElement("p");
  supporting.className = "first-use-supporting";
  supporting.textContent = "Browse codes, follow references, and search. No account needed.";

  const explore = document.createElement("button");
  explore.type = "button";
  explore.className = "primary";
  explore.textContent = "Explore Permitext";
  explore.addEventListener("click", async () => {
    completeFirstUseWelcome();
    if (!state.readers.length) state.readers.push(newReaderState());
    await renderWorkspace();
  });
  const signIn = document.createElement("button");
  signIn.type = "button";
  signIn.textContent = "Sign in";
  signIn.addEventListener("click", () => {
    completeFirstUseWelcome();
    void focusUtility("settings");
  });
  const actions = document.createElement("div");
  actions.className = "first-use-actions";
  actions.append(explore, signIn);
  content.append(heading, supporting, actions);
  welcome.append(content);
  return welcome;
}

function columnPaneLabel(panel) {
  const code = panel.querySelector('.code-select')?.selectedOptions?.[0]?.textContent;
  const chapter = panel.querySelector('.chapter-select')?.selectedOptions?.[0]?.textContent;
  return code ? [code, chapter].filter(Boolean).join(' · ')
    : panel.querySelector(':scope > header .panel-kind, :scope > header h2')?.textContent?.trim() || 'Column';
}

function refreshColumnGroupPresentation({ preparePanels = true } = {}) {
  const panels = [...track.querySelectorAll(':scope > .workspace-panel')];
  panels.forEach((panel) => panel.classList.remove('is-group-hidden'));
  if (preparePanels) panels.forEach(preparePaneCollapse);
  const hidden = new Set();
  for (const group of state.columnGroups || []) {
    if (columnGroupIsCollapsed(group)) group.paneIDs.filter((id) => id !== activePinnedPaneID() &&
      workflowPaneIsVisible(id) && panels.some((panel) => panel.dataset.paneId === id)).slice(1).forEach((id) => hidden.add(id));
  }
  panels.forEach((panel) => panel.classList.toggle('is-group-hidden', hidden.has(panel.dataset.paneId)));
  track.querySelectorAll(':scope > .pane-divider').forEach((divider) => {
    divider.classList.toggle('is-group-hidden', hidden.has(divider.dataset.nextPaneId));
  });
  updateCollapsedPaneDividers();
}

function setColumnGroupCollapsed(group, collapsed) {
  if (!columnGroupCanCollapse(group)) return;
  const panels = [...track.querySelectorAll(':scope > .workspace-panel')]
    .filter((panel) => panel.dataset.paneId !== activePinnedPaneID() && group.paneIDs.includes(panel.dataset.paneId));
  panels.forEach((panel) => {
    panel._collapseAnimation?.cancel();
    panel._restoreCollapseChildWidths?.();
  });
  const transition = Symbol();
  group._transition = transition;
  const totalWidth = panels.reduce((sum, panel) => sum + panel.getBoundingClientRect().width, 0);
  const scrolls = panels.flatMap((panel) => panel._collapsedScrollPositions || []);
  const readerPositions = new Map(panels.filter((panel) => panel._collapsedReaderPosition)
    .map((panel) => [panel.dataset.paneId, panel._collapsedReaderPosition]));
  group.collapsed = collapsed;
  refreshColumnGroupPresentation();
  saveWorkspaceState();
  notifyWorkspaceLayoutChange();
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    const animations = panels.filter((panel) => !panel.classList.contains('is-group-hidden')).map((panel, index) => {
      panel._collapseAnimation?.cancel();
      const width = panel.getBoundingClientRect().width;
      const from = collapsed ? totalWidth : index === 0 ? 48 : 0;
      const animation = panel.animate([
        { flex: `0 0 ${from}px`, minWidth: `${from}px`, maxWidth: `${from}px`, paddingInline: '0px' },
        { flex: `0 0 ${width}px`, minWidth: `${width}px`, maxWidth: `${width}px`, paddingInline: getComputedStyle(panel).paddingInline }
      ], { duration: 240, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' });
      panel._collapseAnimation = animation;
      return animation.finished.catch(() => {});
    });
    Promise.all(animations).then(() => {
      if (group.collapsed !== collapsed || group._transition !== transition) return;
      if (!collapsed) {
        scrolls.forEach(({ node, top, left }) => { node.scrollTop = top; node.scrollLeft = left; });
        restoreReaderScrollPositions(readerPositions);
      }
      notifyWorkspaceLayoutChange();
    });
  }
}

function orderWithPaneStepped(paneID, direction) {
  const order = activePaneIDs();
  const unit = paneGroupForMove(paneID, order);
  const indexes = unit.map((id) => order.indexOf(id)).filter((index) => index >= 0);
  if (!indexes.length) return null;
  const targetIndex = direction < 0 ? Math.min(...indexes) - 1 : Math.max(...indexes) + 1;
  const target = order[targetIndex];
  if (!target) return null;
  const codeQuestionIDs = openCodeQuestionPaneIDs();
  if (codeQuestionIDs.length) {
    // These legacy workflow surfaces are re-anchored by activePaneIDs. Do not
    // offer an action that would immediately snap back after normalization.
    const anchored = new Set([
      ...codeQuestionIDs,
      ...(state.utilities.analysis ? ["utility:analysis"] : []),
      ...openResearchConversationPaneIDs()
    ]);
    if ([...unit, ...paneGroupForMove(target, order)].some((id) => anchored.has(id))) return null;
  }
  const moved = orderWithPaneMoved(paneID, target, direction < 0 ? "before" : "after");
  return moved && moved.some((id, index) => id !== order[index]) ? moved : null;
}

function activePinnedPaneID() {
  // Retain the saved Pro preference, but never apply it to a Free layout.
  if (!isProAccount()) return "";
  const paneID = state.pinnedPaneID || "";
  // Pin a saved detail through its Evidence anchor so the pair cannot split.
  return paneID.startsWith("section:detail:")
    ? savedEvidenceColumnGroup(paneID, state.paneOrder || [])[0] || paneID
    : paneID;
}

function togglePinnedPane(panel) {
  if (!isProAccount()) return;
  const selectedPaneID = panel.dataset.paneId;
  const paneID = selectedPaneID.startsWith("section:detail:")
    ? savedEvidenceColumnGroup(selectedPaneID, activePaneIDs())[0] || selectedPaneID
    : selectedPaneID;
  state.pinnedPaneID = activePinnedPaneID() === paneID ? "" : paneID;
  if (state.pinnedPaneID) {
    state.collapsedPaneIDs = (state.collapsedPaneIDs || []).filter((id) => id !== paneID);
  }
  // Keep the logical order and group membership intact. Move mounted nodes only,
  // so readers, editors and unsent Research drafts retain their state.
  appendPaneSequence([...track.querySelectorAll(':scope > .workspace-panel')]);
  saveWorkspaceState();
  const group = columnGroupForPane(paneID);
  if (!state.pinnedPaneID && group?.collapsed) focusColumnGroupControl(group);
  else panel.querySelector('.column-group-menu-button')?.focus({ preventScroll: true });
}

function movePaneOneStep(panel, direction) {
  const order = orderWithPaneStepped(panel.dataset.paneId, direction);
  if (!order) return;
  state.paneOrder = order;
  // Reorder mounted nodes; do not reconstruct editors or unsent Research drafts.
  appendPaneSequence([...track.querySelectorAll(':scope > .workspace-panel')]);
  saveWorkspaceState();
  panel.querySelector(paneIsCollapsed(panel.dataset.paneId)
    ? ':scope > .pane-collapsed-tab' : '.column-group-menu-button')?.focus();
}

function focusColumnGroupControl(group) {
  const first = [...track.querySelectorAll(':scope > .workspace-panel')]
    .find((panel) => group.paneIDs.includes(panel.dataset.paneId) && !panel.classList.contains('is-group-hidden'));
  first?.querySelector(paneIsCollapsed(first.dataset.paneId)
    ? ':scope > .pane-collapsed-tab' : '.column-group-menu-button')?.focus({ preventScroll: true });
}

function prepareColumnGroupControls(panel, header, group) {
  if (!workspacePrivatePresentationAllowed() || !canGroupWorkspaceColumn(panel.dataset.paneId)) group = null;
  let menuButton = header.querySelector('.column-group-menu-button');
  if (!menuButton) {
    header.addEventListener('click', (event) => {
      if (event.target.closest('button[class*="close"]')) captureColumnGroupContents();
    }, { capture: true });
    menuButton = document.createElement('button');
    menuButton.type = 'button';
    menuButton.className = 'column-group-menu-button';
    menuButton.setAttribute('aria-haspopup', 'menu');
    menuButton.setAttribute('aria-expanded', 'false');
    const actions = header.querySelector('.panel-actions') || header;
    actions.insertBefore(menuButton, actions.querySelector('[class*="close"]'));
    menuButton.addEventListener('click', () => openColumnGroupMenu(panel, menuButton));
  }
  menuButton.hidden = false;
  panel.querySelector('.column-group-collapsed-menu')?.remove();
  menuButton.textContent = group ? group.name : '⋯';
  menuButton.classList.toggle('has-group', Boolean(group));
  menuButton.title = group ? `${group.name} · ${group.paneIDs.length} columns` : 'Column options';
  menuButton.setAttribute('aria-label', group ? `Group options: ${group.name}` : 'Column options');
  panel.classList.toggle('has-column-group', Boolean(group));
}

function appendReaderMenuControls(menu, panel) {
  const reader = (state.readers || []).find((item) => item.id === panel.dataset.readerId);
  if (!reader) return;
  const tools = document.createElement("div");
  tools.className = "column-menu-typography";
  tools.innerHTML = `<div class="column-menu-control-row" role="group" aria-label="Reader text size">
    <span>Text</span><button type="button" role="menuitem" class="reader-text-decrease" aria-label="Decrease Reader text size">A−</button><button type="button" role="menuitem" class="reader-text-increase" aria-label="Increase Reader text size">A+</button>
    </div><div class="column-menu-control-row" role="group" aria-label="Reader line spacing">
    <span>Spacing</span><button type="button" role="menuitem" class="reader-spacing-decrease" aria-label="Decrease Reader line spacing">−</button><button type="button" role="menuitem" class="reader-spacing-increase" aria-label="Increase Reader line spacing">+</button></div>`;
  const sync = () => { syncReaderTextSizeControls(tools, reader); syncReaderSpacingControls(tools, reader); };
  for (const [selector, change] of [
    [".reader-text-decrease", () => changeReaderTextSize(panel, reader, -1)],
    [".reader-text-increase", () => changeReaderTextSize(panel, reader, 1)],
    [".reader-spacing-decrease", () => changeReaderSpacing(panel, reader, -0.1)],
    [".reader-spacing-increase", () => changeReaderSpacing(panel, reader, 0.1)]
  ]) tools.querySelector(selector).addEventListener("click", () => { change(); sync(); });
  sync();
  menu.append(tools);
}

function openColumnGroupMenu(panel, anchor) {
  document.querySelector('.column-group-menu')?._close?.();
  const group = workspacePrivatePresentationAllowed() && canGroupWorkspaceColumn(panel.dataset.paneId) ? columnGroupForPane(panel.dataset.paneId) : null;
  const menu = document.createElement('div');
  menu.className = 'column-group-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', group ? `Group options: ${group.name}` : 'Column options');
  const controller = new AbortController();
  const trust = panel._readerTrust || panel.querySelector(".reader-trust");
  const trustHome = trust?.parentElement;
  const searchOptions = panel.classList.contains("search-panel") ? panel.querySelector(".search-options") : null;
  const searchControls = searchOptions ? [...searchOptions.children] : [];
  const matchControl = searchOptions?.querySelector(".search-match-control");
  anchor.setAttribute('aria-expanded', 'true');
  const close = () => {
    controller.abort();
    if (trust && trustHome) {
      trust.open = false;
      delete trust._positionMenu;
      trust.querySelector("summary").setAttribute("aria-expanded", "false");
      trustHome.append(trust);
    }
    if (searchOptions) {
      matchControl.open = false;
      matchControl.querySelector("summary").setAttribute("aria-expanded", "false");
      searchOptions.append(...searchControls);
    }
    menu.remove();
    anchor.setAttribute('aria-expanded', 'false');
    anchor.focus({ preventScroll: true });
  };
  menu._close = close;
  const separate = () => {
    if (!menu.children.length || menu.lastElementChild.getAttribute("role") === "separator") return;
    const divider = document.createElement("div");
    divider.className = "column-menu-divider";
    divider.setAttribute("role", "separator");
    menu.append(divider);
  };
  const add = (label, action, disabled = false) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.setAttribute('role', 'menuitem');
    button.textContent = label;
    button.disabled = disabled;
    button.addEventListener('click', () => { close(); action(); });
    menu.append(button);
  };
  const factEditor = panel.classList.contains("project-facts-panel") ? projectInformationMounts.get(panel.dataset.paneId) : null;
  if (factEditor?.refreshZoLa) add("Refresh ZoLa data", factEditor.refreshZoLa, factEditor.isRefreshing());
  if (panel.classList.contains("search-panel")) add("New search column", () => void openNewSearchColumn());
  if (panel.classList.contains("research-list-panel")) add("New research column", () => void openNewResearchColumn());
  separate();
  if (paneCanCollapse(panel.dataset.paneId) && !columnGroupIsCollapsed(group)) {
    add(paneIsCollapsed(panel.dataset.paneId) ? 'Expand' : 'Collapse', () => {
      setPaneCollapsed(panel, !paneIsCollapsed(panel.dataset.paneId), { focus: true });
    });
  }
  const pinTarget = panel.dataset.paneId.startsWith("section:detail:")
    ? savedEvidenceColumnGroup(panel.dataset.paneId, activePaneIDs())[0] || panel.dataset.paneId
    : panel.dataset.paneId;
  if (isProAccount()) add(activePinnedPaneID() === pinTarget ? 'Unpin' : 'Pin', () => togglePinnedPane(panel));
  separate();
  add('Move Left', () => movePaneOneStep(panel, -1), !orderWithPaneStepped(panel.dataset.paneId, -1));
  add('Move Right', () => movePaneOneStep(panel, 1), !orderWithPaneStepped(panel.dataset.paneId, 1));
  if (searchOptions) {
    separate();
    matchControl.querySelector("summary").setAttribute("role", "menuitem");
    matchControl.querySelector("summary").setAttribute("aria-haspopup", "menu");
    matchControl.querySelector("summary").setAttribute("aria-expanded", String(matchControl.open));
    matchControl.querySelector("button").setAttribute("role", "menuitem");
    searchOptions.querySelector(".search-sources-button").setAttribute("role", "menuitem");
    menu.append(...searchControls);
  }
  if (panel.classList.contains("reader-panel")) {
    separate();
    add("Change Code", () => openReaderCodePicker(anchor, async (code) => {
      const reader = state.readers.find((item) => item.id === panel.dataset.readerId);
      if (reader && panel.isConnected) await changeReaderCode(panel, reader, code);
    }));
    if (trust) {
      panel._readerTrust = trust;
      trust.open = false;
      trust.hidden = false;
      trust.querySelector("summary").setAttribute("role", "menuitem");
      trust.querySelector("summary").setAttribute("aria-expanded", "false");
      trust.style.setProperty("--code-accent", getComputedStyle(panel).getPropertyValue("--code-accent"));
      menu.classList.add("has-reader-trust");
      menu.append(trust);
    }
    if ((state.readers || []).some(reader => reader.id === panel.dataset.readerId)) separate();
    appendReaderMenuControls(menu, panel);
  }
  if (group) {
    separate();
    if (columnGroupCanCollapse(group)) add(group.collapsed ? 'Expand group' : 'Collapse group', () => {
      setColumnGroupCollapsed(group, !group.collapsed);
      focusColumnGroupControl(group);
    });
    add('Edit group…', () => openColumnGroupEditor(panel, group));
    add('Ungroup', () => {
      state.columnGroups = state.columnGroups.filter((item) => item.id !== group.id);
      refreshColumnGroupPresentation();
      saveWorkspaceState();
    });
  }
  document.body.append(menu);
  const position = () => {
    const rect = anchor.getBoundingClientRect();
    const panelRect = panel.getBoundingClientRect();
    const menuWidth = menu.offsetWidth;
    const fitsColumn = panelRect.width >= menuWidth + 16;
    const leftLimit = Math.max(8, fitsColumn ? panelRect.left + 8 : 8);
    const rightLimit = Math.min(window.innerWidth - 8, fitsColumn ? panelRect.right - 8 : window.innerWidth - 8);
    menu.style.left = `${Math.max(8, Math.min(Math.max(leftLimit, rect.right - menuWidth), rightLimit - menuWidth))}px`;
    menu.style.top = `${Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - menu.offsetHeight - 8))}px`;
  };
  position();
  matchControl?.addEventListener("toggle", () => {
    matchControl.querySelector("summary").setAttribute("aria-expanded", String(matchControl.open));
    position();
  }, { signal: controller.signal });
  if (trust) trust._positionMenu = position;
  trust?.addEventListener("toggle", () => {
    trust.querySelector("summary").setAttribute("aria-expanded", String(trust.open));
    position();
  }, { signal: controller.signal });
  menu.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') { event.preventDefault(); close(); }
    const items = [...menu.querySelectorAll('button:not(:disabled), summary[role="menuitem"], a[href]')]
      .filter(item => item.getClientRects().length > 0);
    if (items.length && ['ArrowDown', 'ArrowUp'].includes(event.key)) {
      event.preventDefault();
      items[(items.indexOf(document.activeElement) + (event.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length].focus();
    }
    if (event.key === 'Tab') close();
  });
  document.addEventListener('pointerdown', (event) => { if (!menu.contains(event.target) && event.target !== anchor) close(); }, { signal: controller.signal });
  menu.querySelector('button:not(:disabled)')?.focus();
}

function columnGroupChoiceDetails(pane, position, index) {
  const lines = [];
  if (pane?.classList.contains('reader-panel')) {
    const code = pane.querySelector('.code-select')?.selectedOptions?.[0]?.textContent?.trim();
    const chapter = pane.querySelector('.chapter-select')?.selectedOptions?.[0]?.textContent?.trim();
    if (code) lines.push(code);
    if (chapter) lines.push(chapter);
    const section = position?.sectionID
      ? pane.querySelector(`.chapter-section[data-section-id="${CSS.escape(position.sectionID)}"]`)
      : pane.querySelector(".chapter-section[data-section-id]");
    const title = section?.querySelector('.reader-section-title')?.textContent?.trim();
    lines.push(title ? `At § ${title}` : 'Reading position unavailable');
  } else lines.push(pane ? columnPaneLabel(pane) : 'Column');
  lines.push(`Column ${index + 1} · left to right`);
  return lines;
}

function openColumnGroupEditor(panel, existing = null) {
  if (!workspacePrivatePresentationAllowed()) return;
  const workspaceID = activeWorkspaceID;
  document.querySelector('.column-group-dialog')?.remove();
  const dialog = document.createElement('dialog');
  dialog.className = 'column-group-dialog';
  dialog.setAttribute('aria-label', existing ? 'Edit group' : 'Group columns');
  dialog.innerHTML = `<form>
    <label class="column-group-name-label">Group Name<input name="groupName" maxlength="40" required autocomplete="off" placeholder="e.g. Fire safety"></label>
    <p class="column-group-editor-hint">Choose columns to keep together. Evidence, Context, Facts, Notebook and Report cannot be grouped.</p>
    <div class="column-group-choices"></div><p class="column-group-editor-error" role="status"></p>
    <div class="column-group-editor-actions"><button type="button" data-cancel>Cancel</button><button type="submit">${existing ? 'Save group' : 'Create group'}</button></div></form>`;
  const ids = activePaneIDs();
  const selected = new Set(existing?.paneIDs || (panel ? basePaneGroupForMove(panel.dataset.paneId, ids) : []));
  const seen = new Set();
  const choices = [];
  const positions = captureReaderScrollPositions();
  for (const id of ids) {
    if (seen.has(id)) continue;
    const eligible = canGroupWorkspaceColumn(id);
    const unit = [id];
    unit.forEach((member) => seen.add(member));
    const other = unit.map(columnGroupForPane).find((group) => group && group.id !== existing?.id);
    const label = document.createElement('label');
    label.className = 'column-group-choice';
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = eligible && !other && unit.some((member) => selected.has(member));
    input.disabled = !eligible || Boolean(other);
    const text = document.createElement('span');
    text.className = 'column-group-choice-details';
    const panes = unit.map((member) => track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(member)}"]`));
    unit.forEach((member, index) => {
      columnGroupChoiceDetails(panes[index], positions.get(member), ids.indexOf(member)).forEach((line, lineIndex) => {
        const detail = document.createElement(lineIndex === 0 ? 'strong' : 'small');
        detail.textContent = line;
        text.append(detail);
      });
    });
    if (!eligible) {
      const unavailable = document.createElement('small');
      unavailable.textContent = 'Cannot be grouped';
      text.append(unavailable);
    }
    if (other) {
      const membership = document.createElement('small');
      membership.textContent = `In ${other.name}`;
      text.append(membership);
    }
    label.append(input, text);
    dialog.querySelector('.column-group-choices').append(label);
    choices.push({ input, unit });
  }
  if (!choices.some(({ input }) => !input.disabled)) {
    dialog.querySelector('.column-group-editor-error').textContent = 'Open Reader, Search or Assistant columns to create a group.';
  }
  const name = dialog.querySelector('[name="groupName"]');
  name.value = existing?.name || '';
  const close = () => { dialog.close(); dialog.remove(); };
  dialog.querySelector('[data-cancel]').addEventListener('click', close);
  dialog.addEventListener('cancel', () => { dialog.remove(); });
  dialog.querySelector('form').addEventListener('submit', (event) => {
    event.preventDefault();
    if (workspaceID !== activeWorkspaceID) { close(); return; }
    const members = new Set(choices.filter(({ input }) => input.checked).flatMap(({ unit }) => unit));
    if (members.size < (existing ? 1 : 2) || !name.value.trim()) {
      dialog.querySelector('.column-group-editor-error').textContent = existing ? 'Enter a name and select at least one column.' : 'Enter a name and select at least two columns.';
      return;
    }
    const group = { id: existing?.id || crypto.randomUUID(), name: name.value.trim(), paneIDs: ids.filter((id) => members.has(id)), collapsed: existing?.collapsed || false, columns: existing?.columns || {} };
    const keptReaderPaneIDs = [];
    for (const id of members) {
      const reader = state.readers.find((item) => `reader:${item.id}` === id);
      if (reader && (reader.searchPreviewPaneID || searchIDForLinkedReaderPane(id))) {
        keepDerivedReader(reader);
        keptReaderPaneIDs.push(id);
      }
    }
    state.columnGroups = normalizeColumnGroups([...(state.columnGroups || []).filter((item) => item.id !== group.id), group]);
    close();
    appendPaneSequence([...track.querySelectorAll(':scope > .workspace-panel')]);
    saveWorkspaceState();
    if (keptReaderPaneIDs.length) void transitionWorkspace("utility", { refreshPaneIDs: keptReaderPaneIDs });
  });
  document.body.append(dialog);
  dialog.showModal();
  name.focus();
}

// Collapse keeps the live column DOM (including unsaved editors) in place.
function paneCanCollapse(paneID) {
  return currentColumnWorkflowView() !== "notebook" || paneID.startsWith("reader:");
}

function columnGroupCanCollapse(group) {
  if (currentColumnWorkflowView() !== "notebook") return true;
  const visibleIDs = group.paneIDs.filter(workflowPaneIsVisible);
  return visibleIDs.length > 0 && visibleIDs.every(paneCanCollapse);
}

function columnGroupIsCollapsed(group) {
  return Boolean(group?.collapsed) && columnGroupCanCollapse(group);
}

function paneIsCollapsed(paneID) {
  return paneCanCollapse(paneID) && ((paneID !== activePinnedPaneID() && columnGroupIsCollapsed(columnGroupForPane(paneID))) || (state.collapsedPaneIDs || []).includes(paneID));
}

function applyPaneCollapsedState(panel) {
  const collapsed = paneIsCollapsed(panel.dataset.paneId);
  const wasCollapsed = panel.classList.contains("is-collapsed");
  if (collapsed && !wasCollapsed) {
    panel._collapsedScrollPositions = [panel, ...panel.querySelectorAll("*")]
      .filter((node) => node.scrollTop || node.scrollLeft)
      .map((node) => ({ node, top: node.scrollTop, left: node.scrollLeft }));
    panel._collapsedReaderPosition = captureReaderScrollPositions().get(panel.dataset.paneId);
  }
  panel.classList.toggle("is-collapsed", collapsed);
  applyPaneWeight(panel, panel.dataset.paneId);
  const rail = panel.querySelector(":scope > .pane-collapsed-tab");
  if (rail) rail.hidden = !collapsed;

  if (!collapsed && wasCollapsed) {
    // Restore after the expanded column has its original layout again.
    for (const { node, top, left } of panel._collapsedScrollPositions || []) {
      node.scrollTop = top;
      node.scrollLeft = left;
    }
    if (panel._collapsedReaderPosition) {
      restoreReaderScrollPositions(new Map([[panel.dataset.paneId, panel._collapsedReaderPosition]]));
    }
    delete panel._collapsedScrollPositions;
    delete panel._collapsedReaderPosition;
  }
}

function setPaneCollapsed(panel, collapsed, { focus = false } = {}) {
  const paneID = panel.dataset.paneId;
  if (!paneCanCollapse(paneID)) return;
  const group = columnGroupForPane(paneID);
  if (!collapsed && columnGroupIsCollapsed(group)) setColumnGroupCollapsed(group, false);
  const startWidth = panel.getBoundingClientRect().width;
  const startPadding = getComputedStyle(panel).paddingInline;
  panel._collapseAnimation?.cancel();
  panel._restoreCollapseChildWidths?.();
  const savedScroll = panel._collapsedScrollPositions;
  const savedReaderPosition = panel._collapsedReaderPosition;
  const ids = new Set(state.collapsedPaneIDs || []);
  if (collapsed) ids.add(paneID);
  else ids.delete(paneID);
  state.collapsedPaneIDs = [...ids];
  closeActiveCustomSelect();
  applyPaneCollapsedState(panel);
  updateCollapsedPaneDividers();
  saveWorkspaceState();
  notifyWorkspaceLayoutChange();
  if (focus) panel.querySelector(collapsed ? ".pane-collapsed-tab" : ":scope > header")?.focus({ preventScroll: true });
  if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    const endWidth = panel.getBoundingClientRect().width;
    const endPadding = getComputedStyle(panel).paddingInline;
    // Clip the full-width contents as the column opens, instead of rewrapping
    // text and moving scroll anchors on every animation frame.
    if (!collapsed) {
      const children = Array.from(panel.children).filter((child) => child !== panel.querySelector(".pane-collapsed-tab"));
      const widths = children.map((node) => ({
        node, pixels: node.getBoundingClientRect().width,
        width: node.style.width, minWidth: node.style.minWidth, maxWidth: node.style.maxWidth
      }));
      widths.forEach(({ node, pixels }) => {
        if (!pixels) return;
        node.style.width = node.style.minWidth = node.style.maxWidth = `${pixels}px`;
      });
      panel._restoreCollapseChildWidths = () => {
        widths.forEach(({ node, width, minWidth, maxWidth }) => {
          Object.assign(node.style, { width, minWidth, maxWidth });
        });
        delete panel._restoreCollapseChildWidths;
      };
    }
    const animation = panel.animate([
      { flex: `0 0 ${startWidth}px`, minWidth: `${startWidth}px`, maxWidth: `${startWidth}px`, paddingInline: startPadding },
      { flex: `0 0 ${endWidth}px`, minWidth: `${endWidth}px`, maxWidth: `${endWidth}px`, paddingInline: endPadding }
    ], { duration: 240, easing: "cubic-bezier(0.22, 1, 0.36, 1)" });
    panel._collapseAnimation = animation;
    const title = panel.querySelector(collapsed ? ".pane-collapsed-tab" : ":scope > header");
    title?.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 180, delay: 60, fill: "backwards" });
    animation.finished.then(() => {
      if (panel._collapseAnimation !== animation) return;
      delete panel._collapseAnimation;
      panel._restoreCollapseChildWidths?.();
      if (!collapsed) {
        for (const { node, top, left } of savedScroll || []) {
          node.scrollTop = top;
          node.scrollLeft = left;
        }
        if (savedReaderPosition) restoreReaderScrollPositions(new Map([[paneID, savedReaderPosition]]));
      }
      notifyWorkspaceLayoutChange();
    }).catch(() => {}); // A second click can reverse an in-flight transition.
  }
}

function setAllColumnsCollapsed(collapsed) {
  const panels = [...track.querySelectorAll(":scope > .workspace-panel:not(.is-workflow-hidden)")];
  panels.filter(panel => paneCanCollapse(panel.dataset.paneId)).forEach(panel => {
    if (paneIsCollapsed(panel.dataset.paneId) !== collapsed ||
        (!collapsed && columnGroupIsCollapsed(columnGroupForPane(panel.dataset.paneId)))) {
      setPaneCollapsed(panel, collapsed);
    }
  });
}

function preparePaneCollapse(panel) {
  const header = panel.querySelector(":scope > header");
  if (!header || detachedProjectWindow) return;
  if (!paneCanCollapse(panel.dataset.paneId)) {
    panel._collapseAnimation?.cancel();
    delete panel._collapseAnimation;
    panel._restoreCollapseChildWidths?.();
  }
  const codeSelect = header.querySelector(".code-select");
  const codeLabel = codeSelect?.selectedOptions?.[0]?.textContent?.trim();
  const chapterLabel = panel.querySelector(".chapter-select")?.selectedOptions?.[0]?.textContent?.trim();
  const heading = header.querySelector(".panel-kind, .panel-title, h2");
  const detailLabel = panel.classList.contains("section-detail-panel")
    ? ["Detail", panel.__sectionPayload?.sectionNumber].filter(Boolean).join(" · ")
    : "";
  const title = detailLabel || codeLabel || heading?.textContent?.trim() || "Column";
  const label = codeLabel ? [codeLabel, chapterLabel].filter(Boolean).join(" · ") : title;
  header.tabIndex = -1;
  header.setAttribute("role", "group");
  header.setAttribute("aria-label", `${label} column header`);
  if (header.dataset.collapseBound !== "true") {
    header.dataset.collapseBound = "true";

  }
  header.querySelectorAll(".panel-kind, .panel-title, h2").forEach((titleNode) => {
    if (titleNode.closest("button, a, summary") || titleNode.querySelector("button, a, input, select, textarea, summary, [contenteditable]")) return;
    if (!paneCanCollapse(panel.dataset.paneId)) {
      for (const [name, value] of titleNode._collapseTitleAttributes || []) {
        if (value === null) titleNode.removeAttribute(name);
        else titleNode.setAttribute(name, value);
      }
      return;
    }
    titleNode._collapseTitleAttributes ||= ["tabindex", "role", "aria-label", "aria-expanded", "title"]
      .map(name => [name, titleNode.getAttribute(name)]);
    titleNode.tabIndex = 0;
    titleNode.setAttribute("role", "button");
    titleNode.setAttribute("aria-label", `Collapse ${label}`);
    titleNode.setAttribute("aria-expanded", String(!paneIsCollapsed(panel.dataset.paneId)));
    titleNode.title = `Collapse ${label}`;
    if (titleNode.dataset.collapseTitleBound === "true") return;
    titleNode.dataset.collapseTitleBound = "true";
    const collapse = (event) => {
      if (!paneCanCollapse(panel.dataset.paneId)) return;
      event.preventDefault();
      event.stopPropagation();
      setPaneCollapsed(panel, true, { focus: true });
    };
    titleNode.addEventListener("click", collapse);
    titleNode.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") collapse(event);
    });
  });
  let rail = panel.querySelector(":scope > .pane-collapsed-tab");
  if (!rail) {
    rail = document.createElement("button");
    rail.type = "button";
    rail.className = "pane-collapsed-tab";
    rail.hidden = true;
    rail.innerHTML = '<span></span>';
    rail.setAttribute("aria-expanded", "false");
    rail.addEventListener("click", (event) => {
      if (event.detail !== 0 && Date.now() < (rail._suppressExpandUntil || 0)) return;
      const group = workspacePrivatePresentationAllowed() ? columnGroupForPane(panel.dataset.paneId) : null;
      if (columnGroupIsCollapsed(group)) {
        setColumnGroupCollapsed(group, false);
        focusColumnGroupControl(group);
      } else {
        setPaneCollapsed(panel, false, { focus: true });
        scrollPaneIntoView(panel.dataset.paneId);
      }
    });
    panel.append(rail);
  }
  const headerClose = header.querySelector("button[class*='close']");
  let collapsedClose = panel.querySelector(":scope > .pane-collapsed-close");
  if (headerClose) {
    if (!collapsedClose) {
      collapsedClose = document.createElement("button");
      collapsedClose.type = "button";
      collapsedClose.className = "icon-button pane-collapsed-close";
      collapsedClose.addEventListener("click", (event) => {
        event.stopPropagation();
        header.querySelector("button[class*='close']")?.click();
      });
      panel.append(collapsedClose);
    }
    collapsedClose.innerHTML = headerClose.innerHTML;
    collapsedClose.setAttribute("aria-label", headerClose.getAttribute("aria-label") || `Close ${label}`);
    collapsedClose.title = collapsedClose.getAttribute("aria-label");
    collapsedClose.disabled = headerClose.disabled;
  }
  rail.title = `Expand ${label}`;
  rail.setAttribute("aria-label", rail.title);
  const group = workspacePrivatePresentationAllowed() ? columnGroupForPane(panel.dataset.paneId) : null;
  if (columnGroupIsCollapsed(group)) {
    rail.title = `Expand group ${group.name}`;
    rail.setAttribute("aria-label", rail.title);
  }
  rail.querySelector("span").textContent = columnGroupIsCollapsed(group) ? `${group.name} · ${group.paneIDs.length}` : label;
  prepareColumnGroupControls(panel, header, group);
  applyPaneCollapsedState(panel);
}

function updateCollapsedPaneDividers() {
  track.querySelectorAll(":scope > .pane-divider").forEach((divider) => {
    const disabled = [divider.dataset.previousPaneId, divider.dataset.nextPaneId].filter(Boolean).every(paneIsCollapsed);
    divider.classList.toggle("is-collapse-disabled", disabled);
    divider.setAttribute("aria-disabled", String(disabled));
    divider.tabIndex = disabled ? -1 : 0;
    refreshPaneDividerValue(divider);
  });
}

let pinnedPaneResizeObserver = null;

function refreshPinnedPaneDivider() {
  pinnedPaneResizeObserver?.disconnect();
  const pinned = track.querySelector(':scope > .workspace-panel.is-pinned:not(.is-workflow-hidden)');
  const divider = pinned?.nextElementSibling;
  track.querySelectorAll(':scope > .pane-divider').forEach((node) => {
    node.classList.toggle('is-pinned-divider', node === divider);
  });
  if (!pinned) return;
  const updateWidth = () => track.style.setProperty('--pinned-pane-width', `${pinned.getBoundingClientRect().width}px`);
  updateWidth();
  if ('ResizeObserver' in window) {
    pinnedPaneResizeObserver = new ResizeObserver(updateWidth);
    pinnedPaneResizeObserver.observe(pinned);
  }
}

function appendPaneSequence(panes) {
  closeActiveCustomSelect();
  const orderedPanes = localWelcomePreviewPending ? [] : orderPanes(panes);
  localWelcomePreviewPending = false;
  if (orderedPanes.length && firstUseWelcomeActive) completeFirstUseWelcome();
  const retainedNodes = new Set(orderedPanes);
  track.querySelectorAll(":scope > .search-panel").forEach((panel) => {
    if (!retainedNodes.has(panel)) cancelSearchPanelRequest(panel);
  });
  track.querySelectorAll(":scope > .reader-panel").forEach((panel) => {
    if (!retainedNodes.has(panel)) cancelReaderPanelRequests(panel);
  });
  const activeIDs = new Set(orderedPanes.map((pane) => pane.dataset.paneId));
  state.collapsedPaneIDs = (state.collapsedPaneIDs || []).filter((id) => activeIDs.has(id));
  if (state.pinnedPaneID && !activeIDs.has(state.pinnedPaneID)) state.pinnedPaneID = "";
  const pinnedPaneID = activePinnedPaneID();
  const pinnedIndex = orderedPanes.findIndex((pane) => pane.dataset.paneId === pinnedPaneID);
  if (pinnedIndex > 0) orderedPanes.unshift(...orderedPanes.splice(pinnedIndex, 1));
  const panesByID = new Map(orderedPanes.map((pane) => [pane.dataset.paneId, pane]));
  orderedPanes.splice(0, orderedPanes.length, ...applyLinkedPanePlacements(pairSavedEvidenceDetails([...panesByID.keys()]), true).map((id) => panesByID.get(id)));
  state.paneOrder = orderedPanes.map((pane) => pane.dataset.paneId);
  orderedPanes.forEach((pane) => {
    const pinned = pane.dataset.paneId === pinnedPaneID;
    pane.classList.toggle("is-pinned", pinned);
  });
  orderedPanes.forEach(ensureWorkspacePanelAccessibleName);
  orderedPanes.forEach((pane) => { pane.classList.remove("is-group-hidden"); preparePaneCollapse(pane); });
  const previousScrollLeft = track.scrollLeft;
  const nodes = [];
  const dividerKey = (previousPaneID, nextPaneID) => `${previousPaneID}\u0000${nextPaneID}`;
  const existingDividers = new Map(
    Array.from(track.querySelectorAll(":scope > .pane-divider")).map((divider) => [
      dividerKey(divider.dataset.previousPaneId, divider.dataset.nextPaneId),
      divider
    ])
  );
  cleanupInactiveWorkboardMounts(orderedPanes);
  cleanupInactiveNotebookMounts(orderedPanes);
  cleanupInactiveReportDraftMounts(orderedPanes);
  bindPaneDragging(orderedPanes);
  const visiblePanes = orderedPanes.filter(pane => workflowPaneIsVisible(pane.dataset.paneId));
  orderedPanes.forEach(pane => pane.classList.toggle('is-workflow-hidden', !visiblePanes.includes(pane)));
  presentedColumnWorkflowView = currentColumnWorkflowView();
  syncWorkflowNavigation();
  if (visiblePanes.length) {
    const firstPaneID = visiblePanes[0].dataset.paneId;
    nodes.push(existingDividers.get(dividerKey("", firstPaneID)) || createDivider("", firstPaneID));
  }
  visiblePanes.forEach((pane, index) => {
    if (index > 0) {
      const previousPaneID = visiblePanes[index - 1].dataset.paneId;
      const nextPaneID = pane.dataset.paneId;
      nodes.push(existingDividers.get(dividerKey(previousPaneID, nextPaneID)) || createDivider(previousPaneID, nextPaneID));
    }
    nodes.push(pane);
  });
  if (visiblePanes.length) {
    const lastPaneID = visiblePanes.at(-1).dataset.paneId;
    const edgeResizer = existingDividers.get(dividerKey(lastPaneID, "")) || createDivider(lastPaneID, "");
    nodes.push(edgeResizer);
  }
  if (!orderedPanes.length && workspaceColumnsRequireProject()) {
    nodes.push(renderProjectRequiredWorkspace());
  } else if (!orderedPanes.length && !detachedProjectWindow && shouldShowFirstUseWelcome()) {
    nodes.push(renderFirstUseWelcome());
  } else if (!visiblePanes.length && !detachedProjectWindow && currentColumnWorkflowView() === "research") {
    nodes.push(renderEmptyResearchWorkspace());
  }
  nodes.push(...orderedPanes.filter(pane => !visiblePanes.includes(pane)));
  const desiredNodes = new Set(nodes);
  Array.from(track.children).forEach((node) => {
    if (!desiredNodes.has(node)) node.remove();
  });
  nodes.forEach((node, index) => {
    const currentNode = track.children[index] || null;
    if (currentNode === node) return;
    if (node.parentNode === track && typeof track.moveBefore === "function") {
      track.moveBefore(node, currentNode);
    } else {
      // Older browsers reset nested scroll positions when re-inserting a pane.
      const scrolls = node.parentNode === track
        ? [node, ...node.querySelectorAll("*")].filter((item) => item.scrollTop || item.scrollLeft)
          .map((item) => ({ item, top: item.scrollTop, left: item.scrollLeft })) : [];
      track.insertBefore(node, currentNode);
      scrolls.forEach(({ item, top, left }) => { item.scrollTop = top; item.scrollLeft = left; });
    }
  });
  refreshColumnGroupPresentation();
  refreshPinnedPaneDivider();
  const activeSelectMenus = new Set(
    Array.from(track.querySelectorAll("select.native-select-hidden"))
      .map((select) => select._customSelectMenu)
      .filter(Boolean)
  );
  document.querySelectorAll(".custom-select-menu[data-floating-select='true']").forEach((menu) => {
    if (!activeSelectMenus.has(menu)) menu.remove();
  });
  track.scrollLeft = Math.min(previousScrollLeft, Math.max(0, track.scrollWidth - track.clientWidth));
  notifyWorkspaceLayoutChange();
}

let pendingWorkspacePaneRevealID = "";

function scrollPaneIntoView(paneID, behavior = "smooth") {
  const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
  if (!pane) return;
  if (!workflowPaneIsVisible(paneID)) {
    state.workflowMembership = linkPaneToView(state.workflowMembership, paneID, currentColumnWorkflowView());
    appendPaneSequence([...track.querySelectorAll(':scope > .workspace-panel')]);
    saveWorkspaceState();
  }
  pendingWorkspacePaneRevealID = pane.dataset.workspacePaneLoading ? paneID : "";
  if (paneIsCollapsed(paneID)) setPaneCollapsed(pane, false);
  const paneRect = pane.getBoundingClientRect();
  const trackRect = track.getBoundingClientRect();
  const visibleRight = trackRect.right;
  const paneRight = paneRect.right - visibleRight;
  const pinned = track.querySelector(':scope > .workspace-panel.is-pinned:not(.is-workflow-hidden)');
  if (pinned === pane && window.matchMedia('(min-width: 761px)').matches) return;
  const pinnedWidth = pinned && window.matchMedia('(min-width: 761px)').matches
    ? pinned.getBoundingClientRect().width : 0;
  const paneLeft = paneRect.left - trackRect.left - pinnedWidth;
  if (paneRight > 0) {
    track.scrollTo({
      left: Math.min(track.scrollLeft + paneRight, Math.max(0, track.scrollWidth - track.clientWidth)),
      behavior
    });
  } else if (paneLeft < 0) {
    track.scrollTo({
      left: Math.max(0, track.scrollLeft + paneLeft),
      behavior
    });
  }
}

function keepFocusedWorkspacePaneVisible() {
  requestAnimationFrame(() => {
    const pane = document.activeElement?.closest(".workspace-panel[data-pane-id]");
    if (pane && !paneIsCollapsed(pane.dataset.paneId) && track.contains(pane)) scrollPaneIntoView(pane.dataset.paneId, "auto");
  });
}

function readerContentScrollKey(reader) {
  return JSON.stringify([
    reader?.codePrefix || "BC",
    reader?.codeVersion || "",
    reader?.chapterID || "",
    reader?.sectionID || ""
  ]);
}

function readerScrollPositionFor(reader, position, sections) {
  if (!position?.sectionID || position.contentKey !== readerContentScrollKey(reader)) return null;
  const sectionIndex = sections.findIndex((section) =>
    String(section.id) === position.sectionID || section.readerAliasSectionIDs?.includes(position.sectionID)
  );
  return sectionIndex < 0 ? null : { ...position, sectionIndex };
}

function captureReaderScrollPositions() {
  const positions = new Map();
  track.querySelectorAll('.workspace-panel[data-pane-id^="reader:"]').forEach((panel) => {
    if (panel.classList.contains("is-workflow-hidden")) {
      if (panel._workflowReaderPosition) positions.set(panel.dataset.paneId, panel._workflowReaderPosition);
      return;
    }
    if (panel.classList.contains("is-collapsed")) {
      if (panel._collapsedReaderPosition) positions.set(panel.dataset.paneId, panel._collapsedReaderPosition);
      return;
    }
    const content = panel.querySelector(".reader-content");
    const contentKey = panel.dataset.readerContentKey || "";
    if (!content || !contentKey || content.classList.contains("is-searching-reader")) return;
    const reservedPosition = content._readerChapterExtent?.unloadedScrollPosition(contentKey);
    if (reservedPosition) { positions.set(panel.dataset.paneId, reservedPosition); return; }
    const top = content.getBoundingClientRect().top;
    const section = Array.from(content.querySelectorAll(".chapter-section[data-section-id]"))
      .find((node) => node.getBoundingClientRect().bottom > top);
    if (!section) return;
    const block = Array.from(section.querySelectorAll(".annotated-code-block[data-block-id]"))
      .find((node) => node.getBoundingClientRect().bottom > top);
    const anchor = block || section;
    positions.set(panel.dataset.paneId, {
      contentKey,
      sectionID: section.dataset.sectionId,
      blockID: block?.dataset.blockId || "",
      anchorOffset: anchor.getBoundingClientRect().top - top,
      sectionOffset: section.getBoundingClientRect().top - top
    });
  });
  return positions;
}

function restoreReaderScrollPositions(positions) {
  if (!positions?.size) return;
  positions.forEach((position, paneID) => {
    const panel = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
    const content = panel?.querySelector(".reader-content");
    if (!content || panel.dataset.readerContentKey !== position.contentKey) return;
    if (panel.classList.contains("is-collapsed")) {
      panel._collapsedReaderPosition = position;
      return;
    }
    const renderToken = panel.dataset.readerRenderToken;
    // Select enhancement and the surrounding workspace finish their layout
    // before the frame. Do not apply detached/pre-layout text measurements.
    const controller = new AbortController();
    for (const event of ["wheel", "touchstart", "pointerdown", "keydown"]) {
      content.addEventListener(event, () => controller.abort(), { signal: controller.signal, passive: true });
    }
    requestAnimationFrame(() => {
      if (!controller.signal.aborted && panel.dataset.readerRenderToken === renderToken) {
        applyReaderScrollPosition(panel, position);
      }
      controller.abort();
    });
  });
}

function cancelReaderScrollRestore(content) {
  content?._readerScrollRestoreAbort?.abort();
  if (content) {
    delete content._readerScrollRestoreAbort;
    delete content._readerPendingScrollPosition;
  }
}

function applyReaderScrollPosition(panel, position) {
  if (panel?.classList.contains("is-workflow-hidden")) { panel._workflowReaderPosition = position; return; }
  const content = panel?.querySelector(".reader-content");
  if (!content || !panel.isConnected || panel.dataset.readerContentKey !== position?.contentKey) {
    cancelReaderScrollRestore(content);
    return;
  }
  // Only the small restored body window is loaded here. Measure its real text
  // instead of content-visibility's off-screen intrinsic placeholders.
  content.querySelectorAll(".chapter-section").forEach((node) => {
    node.style.contentVisibility = "visible";
  });
  const section = content.querySelector(`.chapter-section[data-section-id="${CSS.escape(position.sectionID)}"]`);
  if (!section) { cancelReaderScrollRestore(content); return; }
  const block = position.blockID
    ? section.querySelector(`.annotated-code-block[data-block-id="${CSS.escape(position.blockID)}"]`)
    : null;
  const anchor = block || section;
  const offset = block ? position.anchorOffset : Number.isFinite(position.estimatedFraction)
    ? -position.estimatedFraction * section.getBoundingClientRect().height : position.sectionOffset;
  const targetTop = Math.max(0, content.scrollTop + anchor.getBoundingClientRect().top - content.getBoundingClientRect().top - offset);
  const maximumTop = Math.max(0, content.scrollHeight - content.clientHeight);
  content.scrollTop = Math.min(targetTop, maximumTop);
  if (targetTop > maximumTop + 1 && content.dataset.chapterFullyLoaded !== "true") {
    // The first small window may be shorter than the viewport. Retry after
    // nearby sections hydrate, but give control back as soon as the user acts.
    content._readerPendingScrollPosition = position;
    if (!content._readerScrollRestoreAbort) {
      const controller = new AbortController();
      content._readerScrollRestoreAbort = controller;
      for (const event of ["wheel", "touchstart", "pointerdown", "keydown"]) {
        content.addEventListener(event, () => cancelReaderScrollRestore(content), { signal: controller.signal, passive: true });
      }
    }
  } else {
    cancelReaderScrollRestore(content);
  }
  updateReaderScrollIndicator(panel);
}

function restorePendingReaderScrollPosition(panel) {
  const position = panel.querySelector(".reader-content")?._readerPendingScrollPosition;
  if (position) applyReaderScrollPosition(panel, position);
}

function codeQuestionPaneTitle(paneRole) {
  const labels = {
    "question-index": "Questions",
    research: "Research",
    "decision-record": "Analysis Record",
    definition: "Definition",
    candidates: "Candidates",
    reader: "Evidence Reader",
    "evidence-tray": "Evidence Tray",
    "approved-evidence": "Approved Evidence",
    "bounded-analysis": "Bounded Analysis",
    "professional-conclusion": "Professional Conclusion",
    "review-requests": "Review Requests",
    history: "History",
    "code-memo-draft": "Report",
    readiness: "Readiness",
    versions: "Versions",
    "working-notes": "Working Notes",
    workboard: "Workboard",
    "report-draft": "Report",
    legacy: "Legacy / Unassigned"
  };
  return labels[paneRole] || paneRole;
}

function projectColorStyle(project) {
  const color = String(project?.color || project?.colorHex || "").trim();
  return color ? `--project-color: ${color};` : "";
}

function codeDecisionPresentation(questionID, options = {}) {
  const qid = String(questionID || "").trim();
  const question = questionsForActiveProject().find((item) => item.id === qid) || {};
  const cq = codeQuestionWorkspaceState();
  const preferSummary = options.preferSummary === true;
  const hasDefinitionDetail = !preferSummary && Boolean(cq.definitionsByQuestionID?.[qid]);
  const hasReviewDetail = !preferSummary && Boolean(cq.reviewByQuestionID?.[qid]);
  const hasAnalysisDetail = !preferSummary && Boolean(cq.analysisByQuestionID?.[qid]);
  const hasIssueDetail = !preferSummary && Boolean(cq.issueByQuestionID?.[qid]);
  const definition = getDefinitionForQuestion(qid);
  const review = getReviewForQuestion(qid);
  const issue = getIssueForQuestion(qid);
  const blockingReviewCount = hasReviewDetail
    ? unresolvedBlockingRequests(review).length
    : Number(question.blockingReviewCount || 0);
  const missingInformationCount = hasDefinitionDetail
    ? (definition?.inputs || []).filter((input) =>
        !["resolved", "retired"].includes(input.state) && (
          input.inputKind === "unknown" ||
          (input.inputKind === "confirmedFact" && input.state !== "confirmed")
        )
      ).length
    : Number(question.missingInformationCount || 0);
  const conclusionCount = hasAnalysisDetail
    ? getAnalysisForQuestion(qid).conclusionRevisions.length
    : Number(question.conclusionCount || 0);
  const localDependenciesStale = hasDefinitionDetail && Boolean(
    definition?.dependentsStale?.analysis || definition?.dependentsStale?.conclusion
  );
  let state = "In Progress";
  if (question.recordState === "archived") {
    state = "Archived";
  } else if (question.revisionInProgress || localDependenciesStale) {
    state = "Changed";
  } else if (blockingReviewCount) {
    state = "Needs Review";
  } else if (missingInformationCount) {
    state = "Missing Information";
  } else if ((hasIssueDetail && issue.issuedRecords.length) || question.latestIssuedVersion != null) {
    state = "Issued";
  } else if (conclusionCount) {
    state = "Final";
  }
  return { state, blockingReviewCount, missingInformationCount, conclusionCount };
}

function localLegacyInventory(project) {
  const identity = projectIdentity(project || {});
  const projectID = String(projectDetailKey(identity) || activeProjectIDForCodeQuestions() || "").trim();
  const current = getLegacyForProject(projectID);
  const summary = currentContentSummary();
  const existingItems = new Map(current.items
    .filter((item) => releaseSurfaceVisibility.workboard || item.sourceKind !== "workboard")
    .map((item) => [item.id, item]));
  const projectSections = summary.projectSections || [];
  (summary.savedItems || []).forEach((item) => {
    const sourceID = String(item.id || item.sectionID || "").trim();
    if (!sourceID) return;
    const matchingSections = projectSections.filter((section) =>
      String(section.sectionID || section.savedSectionID || section.itemID || "") === String(item.sectionID || "")
    );
    const assignedHere = matchingSections.some((section) => projectSectionBelongsToProject(section, identity));
    if (!assignedHere && matchingSections.length) return;
    existingItems.set(`savedItem:${sourceID}`, {
      id: `savedItem:${sourceID}`,
      sourceKind: "savedItem",
      sourceID,
      typeLabel: legacySourceLabels.savedItem,
      title: [item.codePrefix, item.sectionNumber, item.title].filter(Boolean).join(" ") || "Saved passage",
      summary: item.noteBody || "Saved legal source. Review it explicitly before adding it as Evidence.",
      updatedAt: item.updatedAt || null,
      assignment: assignedHere ? "project" : "unassigned",
      promotions: current.promotions
    });
  });
  (releaseSurfaceVisibility.workboard ? summary.workboards || [] : []).forEach((record) => {
    const workboardID = String(record.id || "").trim();
    const recordProjectID = String(syncProjectIdentity(record.projectID) || record.projectID || "").trim();
    if (!workboardID || recordProjectID !== projectID) return;
    existingItems.set(`workboard:${workboardID}`, {
      id: `workboard:${workboardID}`,
      sourceKind: "workboard",
      sourceID: workboardID,
      typeLabel: legacySourceLabels.workboard,
      title: "Project Workboard",
      summary: "Project-owned diagram. Its ownership and drawing data remain unchanged when linked.",
      updatedAt: record.updatedAt || null,
      assignment: "project",
      promotions: current.promotions
    });
  });
  return {
    projectID,
    items: Array.from(existingItems.values()),
    promotions: current.promotions,
    migration: current.migration
  };
}

function filterDeferredLegacyInventory(inventory) {
  if (releaseSurfaceVisibility.workboard) return inventory;
  return {
    ...inventory,
    items: (inventory?.items || []).filter((item) => item.sourceKind !== "workboard")
  };
}

async function hydrateCodeQuestionLegacy(project, target = null, options = {}) {
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "").trim();
  if (!projectID) return getLegacyForProject(projectID);
  let next = filterDeferredLegacyInventory(
    mergeLegacyInventory(getLegacyForProject(projectID), localLegacyInventory(project), projectID)
  );
  saveLegacyForProject(projectID, next);
  if (!activeAccount()) return next;
  if (!legacyHydrationByProject.has(projectID)) {
    const request = postCodeQuestion("/projects/code-questions/legacy/list", { projectID })
      .then((inventory) => {
        const merged = filterDeferredLegacyInventory(
          mergeLegacyInventory(getLegacyForProject(projectID), inventory, projectID)
        );
        saveLegacyForProject(projectID, merged);
        return merged;
      })
      .catch((error) => {
        const failed = normalizeLegacyWorkspace({
          ...getLegacyForProject(projectID),
          loading: false,
          error: error.message || "Legacy inventory is temporarily unavailable."
        }, projectID);
        saveLegacyForProject(projectID, failed);
        return failed;
      })
      .finally(() => legacyHydrationByProject.delete(projectID));
    legacyHydrationByProject.set(projectID, request);
  }
  next = await legacyHydrationByProject.get(projectID);
  if (target?.isConnected && options.refresh !== false) {
    target.replaceWith(renderCodeQuestionLegacyBody(project, options));
  }
  return next;
}

function refreshCodeQuestionLegacyPanes(projectID = activeProjectIDForCodeQuestions()) {
  const safeProjectID = String(projectID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  track?.querySelectorAll?.(`.code-question-panel[data-project-id="${safeProjectID}"]`).forEach((pane) => {
    const role = pane.dataset.cqRole;
    if (!["legacy", "working-notes", "workboard", "report-draft"].includes(role)) return;
    const body = pane.querySelector(".code-question-panel-body");
    const project = openProjectDetails().find((detail) => projectDetailKey(detail) === projectID) || openProjectDetails()[0];
    const sourceKindFilter = role === "working-notes" ? "notebookCard"
      : role === "workboard" ? "workboard"
        : role === "report-draft" ? "reportDraft"
          : "all";
    if (body) body.replaceChildren(renderCodeQuestionLegacyBody(project, { sourceKindFilter, hydrate: false }));
  });
  saveWorkspaceState();
}

function upsertLocalQuestionFromPromotion(project, questionPayload, questionText, source) {
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "").trim();
  const existing = questionsForActiveProject();
  const id = String(questionPayload.id || "").trim();
  const current = existing.find((question) => question.id === id);
  const nextNumber = existing.reduce((maximum, question) => {
    const value = Number(String(question.displayID || "").replace(/\D/g, "")) || 0;
    return Math.max(maximum, value);
  }, 0) + 1;
  const question = {
    ...(current || {}),
    id,
    displayID: questionPayload.displayID || current?.displayID || `Q-${String(nextNumber).padStart(3, "0")}`,
    title: questionPayload.title || source.title || "Imported question",
    recordState: questionPayload.recordState === "archived" ? "archived" : "active",
    responsibleDisplayName: current?.responsibleDisplayName || codeQuestionActor().displayName,
    reviewState: current?.reviewState || "",
    lastActivityAt: questionPayload.updatedAt || new Date().toISOString(),
    latestIssuedVersion: current?.latestIssuedVersion || null,
    revisionInProgress: false,
    listLabel: current?.listLabel || "Working"
  };
  setQuestionsForActiveProject(current
    ? existing.map((candidate) => candidate.id === id ? question : candidate)
    : [...existing, question]);
  let definition = getDefinitionForQuestion(id) || emptyDefinitionRecord(id, {
    title: question.title,
    createdBy: codeQuestionActor().userID
  });
  if (!String(definition.questionText || "").trim()) {
    definition = updateDefinitionFields(definition, {
      title: question.title,
      questionText
    }, {
      expectedVersion: definition.expectedVersion,
      actorUserID: codeQuestionActor().userID
    });
    saveDefinitionForQuestion(id, definition);
  }
  setCodeQuestionWorkspaceState(
    openCodeDecisionSurface(codeQuestionWorkspaceState(), {
      projectID,
      questionID: id,
      questionText,
      resumeResearch: true
    }),
    { activeProjectID: projectID, syncDeepLink: true }
  );
  return question;
}

async function linkLegacySourceToQuestion(project, source, questionID, options = {}) {
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "").trim();
  const useServer = Boolean(activeAccount()) && !String(questionID || "").startsWith("local-cq-");
  try {
    if (useServer) {
      const payload = await postCodeQuestion("/projects/code-questions/legacy/promote", {
        projectID,
        questionID,
        sourceKind: source.sourceKind,
        sourceID: source.sourceID,
        idempotencyKey: options.idempotencyKey || `link:${projectID}:${source.sourceKind}:${source.sourceID}:${questionID}`
      });
      const current = getLegacyForProject(projectID);
      saveLegacyForProject(projectID, mergeLegacyInventory(current, {
        items: current.items,
        promotions: [...current.promotions.filter((item) => item.id !== payload.promotion.id), payload.promotion]
      }, projectID));
    } else {
      const result = promoteLegacyItem(getLegacyForProject(projectID), source, questionID, {
        projectID,
        actorUserID: codeQuestionActor().userID,
        action: options.action,
        idempotencyKey: options.idempotencyKey
      });
      saveLegacyForProject(projectID, result.workspace);
    }
    refreshCodeQuestionLegacyPanes(projectID);
    await showWebNotice(
      options.recovery ? "Question link restored" : "Linked to question",
      `${source.title} remains unchanged. The link records provenance only; it does not make the source a confirmed fact or approved evidence.`
    );
  } catch (error) {
    await showWebNotice("Could not link legacy work", error.message || "The explicit link was not saved.");
  }
}

async function createQuestionFromLegacySource(project, source) {
  const questionText = await openWebTextPrompt({
    title: "Create question from earlier work",
    message: `${legacyGuidanceForSource(source.sourceKind)} Enter the precise question; Permitext will not infer it from the source.`,
    label: "Precise question",
    required: true,
    multiline: true,
    confirmLabel: "Continue"
  });
  if (!questionText) return;
  const title = await openWebTextPrompt({
    title: "Question title",
    message: "Use a concise professional title. The original source remains separately available.",
    label: "Title",
    required: true,
    defaultValue: source.title || "Imported question",
    confirmLabel: "Create and link"
  });
  if (!title) return;
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "").trim();
  const idempotencyKey = `promote:${projectID}:${source.sourceKind}:${source.sourceID}:${legacyFingerprint(questionText)}`;
  try {
    let questionPayload;
    if (activeAccount()) {
      const payload = await postCodeQuestion("/projects/code-questions/legacy/promote", {
        projectID,
        sourceKind: source.sourceKind,
        sourceID: source.sourceID,
        idempotencyKey,
        createQuestion: { title, questionText }
      });
      questionPayload = payload.question;
      const current = getLegacyForProject(projectID);
      saveLegacyForProject(projectID, mergeLegacyInventory(current, {
        items: current.items,
        promotions: [...current.promotions.filter((item) => item.id !== payload.promotion.id), payload.promotion]
      }, projectID));
    } else {
      const id = `local-cq-promoted-${legacyFingerprint({ projectID, sourceKind: source.sourceKind, sourceID: source.sourceID, questionText })}`;
      questionPayload = { id, title, questionText, recordState: "active", updatedAt: new Date().toISOString() };
      const result = promoteLegacyItem(getLegacyForProject(projectID), source, id, {
        projectID,
        actorUserID: codeQuestionActor().userID,
        action: "create-question",
        idempotencyKey
      });
      saveLegacyForProject(projectID, result.workspace);
    }
    upsertLocalQuestionFromPromotion(project, questionPayload, questionText, source);
    await renderWorkspace();
    await showWebNotice(
      "Question created",
      `${source.title} remains available in Legacy / Unassigned and is linked as provenance. Its content was not silently promoted into facts, evidence, analysis, or the Code Memo.`
    );
  } catch (error) {
    await showWebNotice("Question was not created", error.message || "Legacy promotion failed safely.");
  }
}

async function unlinkLegacySourcePromotion(project, promotion) {
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "").trim();
  try {
    if (activeAccount() && String(promotion.id).startsWith("cq-promotion-")) {
      const payload = await postCodeQuestion("/projects/code-questions/legacy/unlink", {
        projectID,
        promotionID: promotion.id
      });
      const current = getLegacyForProject(projectID);
      saveLegacyForProject(projectID, mergeLegacyInventory(current, {
        items: current.items,
        promotions: [...current.promotions.filter((item) => item.id !== payload.promotion.id), payload.promotion]
      }, projectID));
    } else {
      const result = unlinkLegacyPromotion(getLegacyForProject(projectID), promotion.id, {
        actorUserID: codeQuestionActor().userID
      });
      saveLegacyForProject(projectID, result.workspace);
    }
    refreshCodeQuestionLegacyPanes(projectID);
    await showWebNotice(
      "Question link removed",
      "Only the relationship was removed. The earlier source and question remain unchanged and reachable; Restore link is available."
    );
  } catch (error) {
    await showWebNotice("Could not unlink", error.message || "The relationship remains unchanged.");
  }
}

function openQuestionFromLegacy(questionID) {
  const projectID = activeProjectIDForCodeQuestions();
  if (!questionsForActiveProject().some((question) => question.id === questionID)) {
    void showWebNotice("Question not in this local view", "Reload the signed-in Project to retrieve this linked question.");
    return;
  }
  setCodeQuestionWorkspaceState(
    openCodeDecisionSurface(codeQuestionWorkspaceState(), {
      projectID,
      questionID,
      questionText: getDefinitionForQuestion(questionID)?.questionText,
      resumeResearch: true
    }),
    { activeProjectID: projectID, syncDeepLink: true }
  );
  void renderWorkspace();
}

function renderCodeQuestionLegacyBody(project, options = {}) {
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "").trim();
  const localInventory = localLegacyInventory(project);
  let legacy = mergeLegacyInventory(getLegacyForProject(projectID), localInventory, projectID);
  const forcedSourceKind = options.sourceKindFilter || "all";
  if (forcedSourceKind !== "all") legacy = { ...legacy, sourceKindFilter: forcedSourceKind };
  const wrap = document.createElement("div");
  wrap.className = "code-question-legacy";
  wrap.dataset.projectId = projectID;

  const boundary = document.createElement("section");
  boundary.className = "code-question-legacy-boundary";
  boundary.innerHTML = `
    <p class="code-question-pane-status">Explicit promotion only</p>
    <p>Legacy work stays reachable and unchanged. A link records provenance; it never silently turns notes, diagrams, old answers, or draft prose into governed inputs or approved evidence.</p>
  `;
  wrap.appendChild(boundary);

  const counts = legacyCounts(legacy.items);
  const countBar = document.createElement("div");
  countBar.className = "code-question-legacy-counts";
  [
    ["all", "All", counts.total],
    ["unassigned", "Unassigned", counts.unassigned],
    ["linked", "Linked", counts.linked],
    ["recovery", "Recovery", counts.recovery]
  ].forEach(([filter, label, count]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "code-question-legacy-count";
    if (legacy.filter === filter) button.classList.add("is-active");
    button.setAttribute("aria-pressed", legacy.filter === filter ? "true" : "false");
    button.textContent = `${label} ${count}`;
    button.addEventListener("click", () => {
      saveLegacyForProject(projectID, { ...getLegacyForProject(projectID), filter });
      refreshCodeQuestionLegacyPanes(projectID);
    });
    countBar.appendChild(button);
  });
  wrap.appendChild(countBar);

  const filters = document.createElement("div");
  filters.className = "code-question-legacy-filters";
  const search = document.createElement("input");
  search.type = "search";
  search.placeholder = "Search legacy work";
  search.setAttribute("aria-label", "Search legacy and unassigned work");
  search.value = legacy.query || "";
  search.addEventListener("change", () => {
    saveLegacyForProject(projectID, { ...getLegacyForProject(projectID), query: search.value });
    refreshCodeQuestionLegacyPanes(projectID);
  });
  const kind = document.createElement("select");
  kind.setAttribute("aria-label", "Filter legacy work by type");
  [["all", "All types"], ...legacySourceKinds.map((value) => [value, legacySourceLabels[value]])]
    .forEach(([value, label]) => {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = label;
      kind.appendChild(option);
    });
  kind.value = forcedSourceKind !== "all" ? forcedSourceKind : legacy.sourceKindFilter;
  kind.disabled = forcedSourceKind !== "all";
  kind.addEventListener("change", () => {
    saveLegacyForProject(projectID, { ...getLegacyForProject(projectID), sourceKindFilter: kind.value });
    refreshCodeQuestionLegacyPanes(projectID);
  });
  filters.append(search, kind);
  wrap.appendChild(filters);

  if (legacy.error) {
    const error = document.createElement("p");
    error.className = "code-question-legacy-error";
    error.textContent = `${legacy.error} Local preserved records remain visible below.`;
    wrap.appendChild(error);
  }

  const list = document.createElement("div");
  list.className = "code-question-legacy-list";
  const visible = filterLegacyItems(legacy, {
    filter: legacy.filter,
    sourceKindFilter: forcedSourceKind !== "all" ? forcedSourceKind : legacy.sourceKindFilter,
    query: legacy.query || ""
  });
  visible.forEach((source) => {
    const card = document.createElement("article");
    card.className = `code-question-legacy-item is-${source.promotionState}`;
    card.dataset.sourceKind = source.sourceKind;
    card.dataset.sourceId = source.sourceID;
    const heading = document.createElement("div");
    heading.className = "code-question-legacy-item-heading";
    heading.innerHTML = `
      <span class="code-question-legacy-kind">${escapeHTML(source.typeLabel)}</span>
      <span class="code-question-legacy-state">${escapeHTML(source.promotionState)}</span>
      <h3>${escapeHTML(source.title)}</h3>
      <p>${escapeHTML(source.summary || legacyGuidanceForSource(source.sourceKind))}</p>
      <small>${escapeHTML(source.assignment === "project" ? "Project-owned" : "Account unassigned")} · Source ${escapeHTML(source.sourceID)}</small>
    `;
    card.appendChild(heading);
    const guidance = document.createElement("p");
    guidance.className = "code-question-legacy-guidance";
    guidance.textContent = legacyGuidanceForSource(source.sourceKind);
    card.appendChild(guidance);
    const actions = document.createElement("div");
    actions.className = "code-question-legacy-actions";
    const activeQuestionID = codeQuestionWorkspaceState().activeQuestionID;
    const linkedToActive = source.promotions.find((promotion) =>
      promotion.questionID === activeQuestionID && promotion.status === "linked"
    );
    const recoverActive = source.promotions.find((promotion) =>
      promotion.questionID === activeQuestionID && promotion.status === "unlinked"
    );
    const link = document.createElement("button");
    link.type = "button";
    link.textContent = recoverActive ? "Restore link" : linkedToActive ? "Linked to current question" : "Link to current question";
    link.disabled = !activeQuestionID || Boolean(linkedToActive);
    link.addEventListener("click", () => void linkLegacySourceToQuestion(project, source, activeQuestionID, {
      recovery: Boolean(recoverActive)
    }));
    const create = document.createElement("button");
    create.type = "button";
    create.textContent = "Create question…";
    create.addEventListener("click", () => void createQuestionFromLegacySource(project, source));
    actions.append(link, create);
    source.promotions.filter((promotion) => promotion.status === "linked").forEach((promotion) => {
      const open = document.createElement("button");
      open.type = "button";
      const question = questionsForActiveProject().find((item) => item.id === promotion.questionID);
      open.textContent = `Open ${question?.displayID || "linked question"}`;
      open.addEventListener("click", () => openQuestionFromLegacy(promotion.questionID));
      const unlink = document.createElement("button");
      unlink.type = "button";
      unlink.textContent = "Unlink";
      unlink.addEventListener("click", () => void unlinkLegacySourcePromotion(project, promotion));
      actions.append(open, unlink);
    });
    card.appendChild(actions);
    list.appendChild(card);
  });
  if (!visible.length) {
    const empty = document.createElement("p");
    empty.className = "code-question-legacy-empty";
    empty.textContent = "No records match this filter. Nothing was deleted or automatically promoted.";
    list.appendChild(empty);
  }
  wrap.appendChild(list);

  const migration = document.createElement("details");
  migration.className = "code-question-legacy-migration";
  migration.innerHTML = `
    <summary>Migration summary and recovery</summary>
    <dl>
      <div><dt>Linked</dt><dd>${escapeHTML(String(counts.linked))}</dd></div>
      <div><dt>Awaiting explicit choice</dt><dd>${escapeHTML(String(counts.unassigned))}</dd></div>
      <div><dt>Recoverable links</dt><dd>${escapeHTML(String(counts.recovery))}</dd></div>
      <div><dt>Failed</dt><dd>${escapeHTML(String(legacy.migration?.failedCount || 0))}</dd></div>
    </dl>
    <p>${escapeHTML(legacy.migration?.note || "No legacy record was silently converted.")}</p>
    <p>Recovery action: choose <strong>Recovery</strong>, then restore the exact source-to-question relationship. Original records and Questions are retained.</p>
  `;
  wrap.appendChild(migration);

  if (options.hydrate !== false) void hydrateCodeQuestionLegacy(project, wrap, { ...options, refresh: true });
  return wrap;
}

function renderCodeQuestionPane(paneDescriptor) {
  const parsed = typeof paneDescriptor === "string"
    ? parseQuestionPaneKey(paneDescriptor)
    : paneDescriptor;
  if (!parsed) return null;
  const project = openProjectDetails().find((detail) =>
    String(detail.id || detail.clientID || detail.localFolderID || "") === parsed.projectID
  ) || openProjectDetails()[0] || null;
  if (parsed.questionID && parsed.questionID !== "_") {
    void hydrateCodeQuestionState(parsed.projectID, parsed.questionID);
  }
  const article = document.createElement("article");
  article.className = "workspace-panel code-question-panel";
  article.dataset.paneId = parsed.paneID;
  article.dataset.cqRole = parsed.paneRole;
  article.dataset.projectId = parsed.projectID;
  if (parsed.questionID && parsed.questionID !== "_") {
    article.dataset.questionId = parsed.questionID;
  }
  article.style.cssText = projectColorStyle(project);
  const header = document.createElement("header");
  header.className = "panel-header";
  const titleBlock = document.createElement("div");
  const eyebrow = document.createElement("p");
  eyebrow.className = "eyebrow panel-kind";
  eyebrow.textContent = project?.name || "Project";
  const title = document.createElement("h2");
  title.className = "panel-title";
  title.textContent = codeQuestionPaneTitle(parsed.paneRole);
  titleBlock.append(eyebrow, title);
  header.appendChild(titleBlock);
  const close = document.createElement("button");
  close.type = "button";
  close.className = "icon-button utility-close code-question-pane-close";
  close.title = "Close column";
  close.setAttribute("aria-label", `Close ${codeQuestionPaneTitle(parsed.paneRole)}`);
  close.innerHTML = circleXIconSVG();
  close.addEventListener("click", async () => {
    if (parsed.paneRole === "question-index") {
      codeQuestionIndexArchiveModeProjectIDs.delete(parsed.projectID);
      await closeProjectCodeDecisions(project || { id: parsed.projectID });
      return;
    }
    const current = codeQuestionWorkspaceState();
    const next = parsed.paneRole === "decision-record"
      ? {
          ...current,
          openPanes: (current.openPanes || []).filter((pane) =>
            pane.paneRole === "question-index" || pane.questionID !== parsed.questionID
          ),
          moreMenuOpen: false
        }
      : closeCodeQuestionPane(current, parsed.paneID, activeProjectIDForCodeQuestions());
    setCodeQuestionWorkspaceState(
      next,
      { syncDeepLink: true }
    );
    await renderWorkspace();
  });
  const panelActions = document.createElement("div");
  panelActions.className = "panel-actions";
  if (parsed.paneRole === "question-index") {
    const manage = document.createElement("button");
    const managing = codeQuestionIndexArchiveModeProjectIDs.has(parsed.projectID);
    manage.type = "button";
    manage.className = "icon-button code-question-index-select";
    manage.title = managing ? "Hide archive actions" : "Show archive actions";
    manage.setAttribute("aria-label", manage.title);
    manage.setAttribute("aria-pressed", String(managing));
    manage.innerHTML = selectionModeIconSVG();
    manage.disabled = !["owner", "editor"].includes(codeQuestionDefineRole());
    manage.addEventListener("click", async () => {
      if (managing) codeQuestionIndexArchiveModeProjectIDs.delete(parsed.projectID);
      else codeQuestionIndexArchiveModeProjectIDs.add(parsed.projectID);
      await renderWorkspace();
    });
    panelActions.appendChild(manage);
  }
  panelActions.appendChild(close);
  header.appendChild(panelActions);
  article.appendChild(header);
  const body = document.createElement("div");
  body.className = "panel-body code-question-panel-body";
  if (parsed.paneRole === "question-index") {
    body.appendChild(renderCodeQuestionIndexBody(project));
  } else if (parsed.paneRole === "research") {
    body.appendChild(renderCodeDecisionResearchBody(project, parsed.questionID));
  } else if (parsed.paneRole === "decision-record") {
    body.appendChild(renderCodeDecisionRecordBody(project, parsed.questionID));
  } else if (parsed.paneRole === "definition") {
    body.appendChild(renderCodeQuestionDefinitionBody(project, parsed.questionID));
  } else if (parsed.paneRole === "candidates") {
    body.appendChild(renderCodeQuestionCandidatesBody(project, parsed.questionID));
  } else if (parsed.paneRole === "reader") {
    body.appendChild(renderCodeQuestionEvidenceReaderBody(project, parsed.questionID));
  } else if (parsed.paneRole === "evidence-tray") {
    body.appendChild(renderCodeQuestionEvidenceTrayBody(project, parsed.questionID));
  } else if (parsed.paneRole === "approved-evidence") {
    body.appendChild(renderCodeQuestionApprovedEvidenceBody(project, parsed.questionID));
  } else if (parsed.paneRole === "bounded-analysis") {
    body.appendChild(renderCodeQuestionBoundedAnalysisBody(project, parsed.questionID));
  } else if (parsed.paneRole === "professional-conclusion") {
    body.appendChild(renderCodeQuestionProfessionalConclusionBody(project, parsed.questionID));
  } else if (parsed.paneRole === "review-requests") {
    body.appendChild(renderCodeQuestionReviewRequestsBody(project, parsed.questionID));
  } else if (parsed.paneRole === "history") {
    body.appendChild(renderCodeQuestionReviewHistoryBody(project, parsed.questionID));
  } else if (parsed.paneRole === "code-memo-draft") {
    body.appendChild(renderCodeMemoDraftBody(project, parsed.questionID));
  } else if (parsed.paneRole === "readiness") {
    body.appendChild(renderCodeMemoReadinessBody(project, parsed.questionID));
  } else if (parsed.paneRole === "versions") {
    body.appendChild(renderCodeMemoVersionsBody(project, parsed.questionID));
  } else if (["legacy", "working-notes", "workboard", "report-draft"].includes(parsed.paneRole)) {
    const sourceKindFilter = parsed.paneRole === "working-notes" ? "notebookCard"
      : parsed.paneRole === "workboard" ? "workboard"
        : parsed.paneRole === "report-draft" ? "reportDraft"
          : "all";
    body.appendChild(renderCodeQuestionLegacyBody(project, { sourceKindFilter }));
  } else {
    const placeholder = document.createElement("div");
    placeholder.className = "code-question-pane-placeholder";
    placeholder.innerHTML = `
      <p class="code-question-pane-status">Stage shell ready</p>
      <p>This ${codeQuestionPaneTitle(parsed.paneRole)} column is part of the Project analysis workspace.
      Content for this stage arrives in a later phase.
      Stage selection does not change review or issuance state.</p>
    `;
    body.appendChild(placeholder);
  }
  article.appendChild(body);
  applyPaneWeight(article, parsed.paneID);
  return article;
}

async function openCodeDecisionDetailPanes(questionID, paneRoles = []) {
  const projectID = activeProjectIDForCodeQuestions();
  let next = codeQuestionWorkspaceState();
  paneRoles.forEach((paneRole) => {
    next = openSupportingTool(next, { projectID, questionID, paneRole });
  });
  setCodeQuestionWorkspaceState(next, { activeProjectID: projectID, syncDeepLink: true });
  await renderWorkspace();
}

function renderCodeDecisionResearchBody(_project, questionID) {
  const qid = String(questionID || "").trim();
  const wrap = document.createElement("div");
  wrap.className = "code-decision-research";
  const definition = getDefinitionForQuestion(qid);
  const intro = document.createElement("section");
  intro.className = "code-decision-research-intro";
  intro.innerHTML = `
    <p class="code-question-pane-status">Research workspace updated</p>
    <p>This compatibility column has been replaced by Permitext’s existing persisted Research workspace so conversations, evidence discovery, history, and Project assignment remain one system.</p>`;
  wrap.appendChild(intro);
  const actions = document.createElement("div");
  actions.className = "code-decision-research-actions";
  const open = document.createElement("button");
  open.type = "button";
  open.textContent = "Open Research";
  open.addEventListener("click", async () => {
    researchQuestionDraft = definition?.questionText || "";
    await focusUtility("analysis");
  });
  actions.appendChild(open);
  wrap.appendChild(actions);
  return wrap;
}

function appendCodeDecisionRecordList(section, values, emptyLabel) {
  const list = document.createElement("ul");
  if (!values.length) {
    const item = document.createElement("li");
    item.className = "code-question-define-muted";
    item.textContent = emptyLabel;
    list.appendChild(item);
  } else {
    values.forEach((value) => {
      const item = document.createElement("li");
      item.textContent = value;
      list.appendChild(item);
    });
  }
  section.appendChild(list);
}

function renderCodeDecisionRecordBody(project, questionID) {
  const qid = String(questionID || "").trim();
  const wrap = document.createElement("div");
  wrap.className = "code-decision-record";
  if (!qid) return wrap;
  const question = questionsForActiveProject().find((item) => item.id === qid) || {};
  const definition = getDefinitionForQuestion(qid);
  const grouped = groupInputsByKind(definition?.inputs || []);
  const evidence = getEvidenceForQuestion(qid);
  const approvedSet = currentEvidenceSet(evidence);
  const snapshotByID = new Map(
    Object.values(evidence.snapshots || {}).map((snapshot) => [snapshot.id, snapshot])
  );
  const analysis = getAnalysisForQuestion(qid);
  const run = latestAnalysisRun(analysis);
  const conclusion = analysis.conclusionRevisions.at(-1) || null;
  const review = getReviewForQuestion(qid);
  const issue = getIssueForQuestion(qid);
  const presentation = codeDecisionPresentation(qid);

  const header = document.createElement("section");
  header.className = "code-decision-record-header";
  header.innerHTML = `
    <div><p>${escapeHTML(question.displayID || "Decision")}</p><h3>${escapeHTML(question.title || definition?.title || "Untitled decision")}</h3></div>
    <strong class="code-decision-state is-${escapeHTML(presentation.state.toLowerCase().replaceAll(" ", "-"))}">${escapeHTML(presentation.state)}</strong>`;
  wrap.appendChild(header);

  const unresolvedInputs = [
    ...grouped.unknowns
      .filter((item) => !["resolved", "retired"].includes(item.state))
      .map((item) => item.statement),
    ...grouped.confirmedFacts
      .filter((item) => item.state !== "confirmed")
      .map((item) => `${item.state === "disputed" ? "Disputed" : "Proposed"} fact — ${item.statement}`)
  ];
  const sections = [
    ["Question", [definition?.questionText || "Question not recorded."], "Question not recorded."],
    ["Project Facts", grouped.confirmedFacts.filter((item) => item.state === "confirmed").map((item) => item.statement), "No confirmed Project Facts yet."],
    ["Assumptions", grouped.assumptions.map((item) => item.statement), "No assumptions recorded."],
    ["Missing Information", unresolvedInputs, "No unresolved information recorded."]
  ];
  sections.forEach(([title, values, emptyLabel]) => {
    const section = document.createElement("section");
    section.className = "code-decision-record-section";
    section.innerHTML = `<h4>${escapeHTML(title)}</h4>`;
    appendCodeDecisionRecordList(section, values, emptyLabel);
    wrap.appendChild(section);
  });

  const approved = document.createElement("section");
  approved.className = "code-decision-record-section";
  approved.innerHTML = `<h4>Approved Evidence</h4><p class="code-question-define-muted">${approvedSet ? `Evidence version ${escapeHTML(String(approvedSet.version))} · preserved in history` : "Candidate evidence is not included here."}</p>`;
  appendCodeDecisionRecordList(approved, (approvedSet?.entries || []).map((entry) => {
    const snapshot = snapshotByID.get(entry.snapshotID);
    return `${snapshot?.passageLocator || entry.snapshotID} · ${entry.role}`;
  }), "No professionally approved evidence yet.");
  wrap.appendChild(approved);

  const bounded = document.createElement("section");
  bounded.className = "code-decision-record-section";
  bounded.innerHTML = `<h4>Evidence-bounded Analysis</h4><p>${escapeHTML(run?.answer?.conclusion || "No bounded analysis selected.")}</p>`;
  if (presentation.state === "Changed" && run) {
    const changed = document.createElement("strong");
    changed.className = "code-decision-changed-warning";
    changed.textContent = "Changed — Re-evaluate";
    bounded.appendChild(changed);
  }
  wrap.appendChild(bounded);

  const professional = document.createElement("section");
  professional.className = "code-decision-record-section is-professional";
  professional.innerHTML = `<h4>Professional Conclusion</h4><p>${escapeHTML(conclusion?.conclusionText || "Not finalized.")}</p><p class="code-question-define-muted">${conclusion ? `Revision ${escapeHTML(String(conclusion.revision))} · ${escapeHTML(conclusion.authorUserID)}` : "AI analysis never becomes the Professional Conclusion automatically."}</p>`;
  wrap.appendChild(professional);

  if (review.requests.length || presentation.state === "Needs Review") {
    const reviewSection = document.createElement("section");
    reviewSection.className = "code-decision-record-section";
    reviewSection.innerHTML = `<h4>Review</h4><p>${escapeHTML(String(presentation.blockingReviewCount))} blocking request${presentation.blockingReviewCount === 1 ? "" : "s"} · ${escapeHTML(String(review.approvals.length))} approval record${review.approvals.length === 1 ? "" : "s"}.</p>`;
    wrap.appendChild(reviewSection);
  }

  const actions = document.createElement("div");
  actions.className = "code-decision-record-actions";
  const details = document.createElement("button");
  details.type = "button";
  details.textContent = "Decision details";
  details.addEventListener("click", () => void openCodeDecisionDetailPanes(qid, ["definition", "evidence-tray", "history"]));
  const memo = document.createElement("button");
  memo.type = "button";
  memo.className = "code-decision-create-memo";
  memo.textContent = issue.issuedRecords.length ? "Open Code Memo" : "Create Code Memo";
  memo.disabled = !conclusion;
  memo.title = conclusion ? "Prepare or open the Report" : "Finalize a Professional Conclusion first";
  memo.addEventListener("click", async () => {
    try {
      const context = codeMemoContext(project, qid);
      if (!context.draft) {
        await executeCodeQuestionMutation("/projects/code-questions/memos/prepare", {
          projectID: activeProjectIDForCodeQuestions(),
          questionID: qid,
          title: `${question.displayID || "Question"} · ${question.title || definition?.title || "Analysis"}`,
          narrative: "",
          includeAnalysis: Boolean(run)
        }, { commandKind: "codeQuestion.memo.prepare" });
      }
      await openCodeDecisionDetailPanes(qid, ["code-memo-draft", "readiness", "versions"]);
    } catch (error) {
      void showWebNotice("Report not created", error.message || "The Report was not prepared.");
    }
  });
  actions.append(details, memo);
  wrap.appendChild(actions);
  return wrap;
}

function renderCodeQuestionIndexBody(project) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-index";
  void hydrateCodeQuestionList(String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || ""));
  const toolbar = document.createElement("form");
  toolbar.className = "code-question-index-toolbar";
  const questionEntry = document.createElement("textarea");
  questionEntry.className = "code-question-index-search";
  questionEntry.rows = 3;
  questionEntry.maxLength = 2000;
  questionEntry.placeholder = "Ask a professional code question…";
  questionEntry.setAttribute("aria-label", "Ask a professional code question");
  questionEntry.autocomplete = "off";
  questionEntry.disabled = !["owner", "editor"].includes(codeQuestionDefineRole());
  if (questionEntry.disabled) questionEntry.title = "An Owner or Editor must start Research";
  const startButton = document.createElement("button");
  startButton.type = "submit";
  startButton.className = "ghost-button research-send-button code-question-start-button";
  startButton.textContent = "Start";
  startButton.disabled = true;
  if (questionEntry.disabled) startButton.title = questionEntry.title;
  const composerBox = document.createElement("div");
  composerBox.className = "research-composer-box code-question-entry-box";
  const resizeQuestionEntry = () => {
    questionEntry.style.height = "auto";
    questionEntry.style.height = `${questionEntry.scrollHeight}px`;
  };
  questionEntry.addEventListener("input", () => {
    resizeQuestionEntry();
    startButton.disabled = questionEntry.disabled || questionEntry.value.trim().length < 3;
  });
  questionEntry.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" || event.shiftKey || event.isComposing) return;
    event.preventDefault();
    toolbar.requestSubmit();
  });
  toolbar.addEventListener("submit", async (event) => {
    event.preventDefault();
    const questionText = questionEntry.value.replace(/\s+/g, " ").trim();
    if (questionText.length < 3 || questionEntry.disabled || startButton.disabled) return;
    questionEntry.disabled = true;
    startButton.disabled = true;
    questionEntry.setAttribute("aria-busy", "true");
    const created = await createLocalCodeQuestionDraft(project, { questionText });
    if (!created && questionEntry.isConnected) {
      questionEntry.disabled = false;
      startButton.disabled = questionEntry.value.trim().length < 3;
      questionEntry.removeAttribute("aria-busy");
      questionEntry.focus({ preventScroll: true });
    }
  });
  composerBox.append(questionEntry, startButton);
  toolbar.append(composerBox);
  wrap.appendChild(renderCodeQuestionIndexList(project));
  wrap.appendChild(toolbar);
  return wrap;
}

function renderCodeQuestionIndexList(project) {
  const list = document.createElement("ul");
  list.className = "code-question-index-list";
  list.setAttribute("role", "list");
  const projectID = String(projectDetailKey(project || {}) || activeProjectIDForCodeQuestions() || "");
  const managing = codeQuestionIndexArchiveModeProjectIDs.has(projectID);
  list.classList.toggle("is-managing", managing);
  const cq = codeQuestionWorkspaceState();
  const questions = filterQuestions(questionsForActiveProject(), {
    ...cq.questionFilters,
    query: ""
  });
  if (!questions.length) return list;
  questions.forEach((question, index) => {
    const item = document.createElement("li");
    item.className = "code-question-index-item";
    if (cq.activeQuestionID === question.id) item.classList.add("is-active");
    const button = document.createElement("button");
    button.type = "button";
    button.className = "code-question-index-open";
    const displayNumber = Number(question.questionNumber)
      || Number(String(question.displayID || "").replace(/\D/g, ""))
      || index + 1;
    button.innerHTML = `
      <span class="code-question-index-id">${escapeHTML(String(displayNumber))}</span>
      <span class="code-question-index-title">${escapeHTML(question.title || "Untitled decision")}</span>
    `;
    button.addEventListener("click", async () => {
      await selectCodeDecisionFromIndex(question);
    });
    item.appendChild(button);
    if (managing) {
      const actions = document.createElement("div");
      actions.className = "code-question-index-actions";
      const archiveButton = document.createElement("button");
      const restoring = question.recordState === "archived";
      archiveButton.type = "button";
      archiveButton.className = "icon-button code-question-index-archive";
      archiveButton.title = restoring ? "Restore question" : "Archive question";
      archiveButton.setAttribute("aria-label", `${archiveButton.title}: ${question.displayID || "Question"}`);
      archiveButton.innerHTML = restoring ? archiveRestoreIconSVG() : archiveIconSVG();
      archiveButton.disabled = !["owner", "editor"].includes(codeQuestionDefineRole());
      archiveButton.addEventListener("click", async (event) => {
        event.stopPropagation();
        try {
          await toggleLocalCodeQuestionArchive(question.id);
          await renderWorkspace();
        } catch (error) {
          await showWebNotice("Question status unchanged", error.message);
        }
      });
      actions.appendChild(archiveButton);
      item.appendChild(actions);
    }
    list.appendChild(item);
  });
  return list;
}

function escapeHTML(value) {
  return String(value || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

async function createLocalCodeQuestionDraft(project, options = {}) {
  if (!codeQuestionWorkspaceEnabled()) return null;
  const projectID = project ? String(projectDetailKey(project) || "").trim() : "";
  if (!projectID) return null;
  let questionText = String(options.questionText || "").replace(/\s+/g, " ").trim();
  if (!questionText) {
    questionText = await openWebTextPrompt({
      title: "Start Research",
        message: "Ask the professional question naturally. Permitext will preserve your evidence and analysis alongside the investigation.",
      label: "What do you need to decide?",
      required: true,
      multiline: true,
      confirmLabel: "Start Research"
    });
  }
  if (!questionText) return null;
  const existing = questionsForActiveProject();
  const nextNumber = existing.reduce((max, item) => {
    const n = Number(String(item.displayID || "").replace(/\D/g, "")) || 0;
    return Math.max(max, n);
  }, 0) + 1;
  const displayID = `Q-${String(nextNumber).padStart(3, "0")}`;
  const id = globalThis.crypto?.randomUUID?.() || `local-cq-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
  const actor = codeQuestionActor();
  const generatedTitle = String(questionText)
    .replace(/\s+/g, " ")
    .replace(/[?.!]+$/, "")
    .trim()
    .slice(0, 96) || "Untitled decision";
  const question = {
    id,
    displayID,
    title: generatedTitle,
    recordState: "active",
    responsibleDisplayName: actor.displayName || "",
    reviewState: "",
    lastActivityAt: new Date().toISOString(),
    latestIssuedVersion: null,
    revisionInProgress: false,
    listLabel: "Working"
  };
  const applyOptimistic = () => {
    setQuestionsForActiveProject([...existing, question]);
    saveDefinitionForQuestion(id, emptyDefinitionRecord(id, {
      title: generatedTitle,
      questionText,
      createdBy: actor.userID
    }));
  };
  let createdQuestion = null;
  try {
    const payload = await executeCodeQuestionMutation("/projects/code-questions/create", {
      projectID,
      id,
      title: generatedTitle,
      questionText
    }, {
      commandKind: "codeQuestion.create",
      projectID,
      hydrate: false,
      applyOptimistic
    });
    if (payload.queued) {
      createdQuestion = question;
    } else {
      createdQuestion = payload.question;
      setQuestionsForActiveProject([...existing, {
        ...payload.question,
        listLabel: deriveQuestionListLabel(payload.question)
      }]);
      invalidateCodeQuestionListHydration(projectID);
    }
  } catch (error) {
    await showWebNotice("Could not start Research", error.message || "Creation failed.");
    return null;
  }
  setCodeQuestionWorkspaceState(
    openCodeDecisionSurface(codeQuestionWorkspaceState(), {
      projectID,
      questionID: createdQuestion?.id || id,
      questionText,
      resumeResearch: true
    }),
    { activeProjectID: projectID, syncDeepLink: true }
  );
  if (codeQuestionIsOnline()) {
    await hydrateCodeQuestionState(projectID, createdQuestion?.id || id, { force: true, render: false });
    try {
      await startLinkedResearchForCodeDecision(createdQuestion?.id || id);
      return createdQuestion;
    } catch (error) {
      setCodeDecisionResearchNotice(
        projectID,
        createdQuestion?.id || id,
        "Linked Research did not finish opening. Your analysis record was preserved. Use the Research action below when you are ready."
      );
      await renderWorkspace();
      return createdQuestion;
    }
  }
  await renderWorkspace();
  return createdQuestion;
}

function renderCodeQuestionDefinitionBody(project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-define";
  const qid = String(questionID || codeQuestionWorkspaceState().activeQuestionID || "").trim();
  if (!qid || qid === "_") {
    wrap.innerHTML = `<p class="code-question-define-empty">Open or create a question to edit its definition.</p>`;
    return wrap;
  }
  const definition = getDefinitionForQuestion(qid);
  const readiness = deriveDefineReadiness(definition, { role: codeQuestionDefineRole() });
  const readOnly = readiness.readOnly || !codeQuestionWorkspaceEnabled();
  wrap.dataset.questionId = qid;
  wrap.dataset.readonly = readOnly ? "true" : "false";

  const readinessEl = document.createElement("section");
  readinessEl.className = "code-question-define-readiness";
  readinessEl.setAttribute("aria-label", "Definition readiness");
  readinessEl.innerHTML = `
    <div class="code-question-define-readiness-head">
      <strong>Readiness</strong>
      <span class="code-question-define-revision">Definition r${escapeHTML(String(definition.definitionRevision))} · v${escapeHTML(String(definition.expectedVersion))}</span>
    </div>
    <p class="code-question-define-readiness-summary">
      ${readiness.canApprove ? "No Define blockers for approval/issuance policy." : "Approval/issuance blocked until Define requirements are met."}
      Stage control does not change review or issue state.
    </p>
  `;
  if (readiness.blockers.length) {
    const list = document.createElement("ul");
    list.className = "code-question-define-blockers";
    readiness.blockers.forEach((item) => {
      const li = document.createElement("li");
      li.dataset.classification = "blocker";
      li.textContent = item.message;
      list.appendChild(li);
    });
    readinessEl.appendChild(list);
  }
  if (readiness.disclosedLimitations.length || readiness.acceptedConditions.length) {
    const notes = document.createElement("ul");
    notes.className = "code-question-define-notes";
    [...readiness.disclosedLimitations, ...readiness.acceptedConditions].forEach((item) => {
      const li = document.createElement("li");
      li.dataset.classification = item.classification;
      li.textContent = `${item.classification === "accepted-condition" ? "Condition" : "Note"}: ${item.message}`;
      notes.appendChild(li);
    });
    readinessEl.appendChild(notes);
  }
  if (definition.dependentsStale?.analysis || definition.dependentsStale?.conclusion) {
    const stale = document.createElement("p");
    stale.className = "code-question-define-stale";
    stale.textContent = "Dependent analysis, conclusion, approval, and draft may be stale after this definition change.";
    readinessEl.appendChild(stale);
  }
  wrap.appendChild(readinessEl);

  const form = document.createElement("form");
  form.className = "code-question-define-form";
  form.setAttribute("aria-label", "Question definition");
  if (readOnly) form.setAttribute("aria-readonly", "true");

  const fields = [
    { key: "title", label: "Concise title", type: "text", max: 240 },
    { key: "questionText", label: "Precise question", type: "textarea", max: 8000, required: true },
    { key: "scope", label: "Scope", type: "textarea", max: 4000 },
    { key: "jurisdiction", label: "Jurisdiction", type: "text", max: 240 },
    { key: "asOfDate", label: "As-of date", type: "date" },
    { key: "desiredOutput", label: "Desired decision / output", type: "textarea", max: 2000 }
  ];
  fields.forEach((field) => {
    const group = document.createElement("div");
    group.className = "code-question-define-field";
    const label = document.createElement("label");
    const inputID = `cq-define-${qid}-${field.key}`;
    label.setAttribute("for", inputID);
    label.textContent = field.label;
    let input;
    if (field.type === "textarea") {
      input = document.createElement("textarea");
      input.rows = field.key === "questionText" ? 4 : 2;
    } else {
      input = document.createElement("input");
      input.type = field.type;
    }
    input.id = inputID;
    input.name = field.key;
    input.value = field.key === "asOfDate"
      ? String(definition.asOfDate || "").slice(0, 10)
      : String(definition[field.key] || "");
    if (field.max) input.maxLength = field.max;
    if (field.required) input.required = true;
    input.disabled = readOnly;
    group.append(label, input);
    form.appendChild(group);
  });
  if (!readOnly) {
    const saveDefinition = document.createElement("button");
    saveDefinition.type = "button";
    saveDefinition.className = "code-question-define-add-input";
    saveDefinition.textContent = "Save definition";
    saveDefinition.addEventListener("click", async () => {
      try {
        const values = Object.fromEntries(fields.map((field) => {
          const input = form.elements.namedItem(field.key);
          return [field.key, input?.value || ""];
        }));
        values.asOfDate = values.asOfDate
          ? new Date(`${values.asOfDate}T00:00:00.000Z`).toISOString()
          : null;
        const current = getDefinitionForQuestion(qid);
        await executeCodeQuestionMutation("/projects/code-questions/definition/save", {
          projectID: activeProjectIDForCodeQuestions(),
          questionID: qid,
          expectedVersion: current.expectedVersion,
          ...values
        }, {
          commandKind: "codeQuestion.update",
          expectedVersion: current.expectedVersion,
          applyOptimistic: () => {
            const next = updateDefinitionFields(current, values, {
              expectedVersion: current.expectedVersion,
              actorUserID: codeQuestionActor().userID
            });
            saveDefinitionForQuestion(qid, next);
          }
        });
        refreshCodeQuestionDefinitionPane(qid);
      } catch (error) {
        void showWebNotice("Could not save definition", error.message || "Definition save failed.");
      }
    });
    form.appendChild(saveDefinition);
  }
  wrap.appendChild(form);

  // Structured inputs
  const groups = groupInputsByKind(definition.inputs);
  assertInputPresentationSeparation(definition.inputs);
  wrap.appendChild(renderDefineInputSection({
    questionID: qid,
    title: "Confirmed facts",
    kind: "confirmedFact",
    items: groups.confirmedFacts,
    readOnly,
    emptyText: "No confirmed facts yet."
  }));
  wrap.appendChild(renderDefineInputSection({
    questionID: qid,
    title: "Assumptions",
    kind: "assumption",
    items: groups.assumptions,
    readOnly,
    emptyText: "No assumptions recorded."
  }));
  wrap.appendChild(renderDefineInputSection({
    questionID: qid,
    title: "Unknowns",
    kind: "unknown",
    items: groups.unknowns,
    readOnly,
    emptyText: "No unknowns recorded. Unresolved unknowns block approval/issuance."
  }));

  // Fact requests
  const factSection = document.createElement("section");
  factSection.className = "code-question-define-fact-requests";
  factSection.innerHTML = `<h3>Fact Requests</h3>`;
  const frList = document.createElement("ul");
  frList.className = "code-question-define-fact-request-list";
  const openRequests = definition.factRequests.filter((item) => item.status === "open" || item.status === "waiting");
  if (!openRequests.length && !definition.factRequests.length) {
    const empty = document.createElement("li");
    empty.className = "code-question-define-empty-item";
    empty.textContent = "No Fact Requests. Anchor a request to an unknown or fact when collaboration is needed.";
    frList.appendChild(empty);
  } else {
    definition.factRequests.forEach((request) => {
      const li = document.createElement("li");
      li.className = `code-question-fact-request is-${request.status}`;
      li.innerHTML = `
        <strong>${escapeHTML(request.title)}</strong>
        <span class="code-question-fact-request-meta">${escapeHTML(request.status)}${request.inputID ? ` · anchored to ${escapeHTML(request.inputID)}` : ""}</span>
        <p>${escapeHTML(request.body || "")}</p>
      `;
      if (!readOnly && (request.status === "open" || request.status === "waiting")) {
        const resolveBtn = document.createElement("button");
        resolveBtn.type = "button";
        resolveBtn.textContent = "Resolve";
        resolveBtn.addEventListener("click", async () => {
          try {
            await executeCodeQuestionMutation("/projects/collaboration/threads/save", {
              projectID: activeProjectIDForCodeQuestions(), questionID: qid,
              threadID: request.id, expectedVersion: request.version,
              status: "resolved", resolution: "Fact Request resolved from the Define stage."
            }, { commandKind: "codeQuestion.review.manage", expectedVersion: request.version });
            refreshCodeQuestionDefinitionPane(qid);
          } catch (error) {
            void showWebNotice("Fact Request not resolved", error.message);
          }
        });
        li.appendChild(resolveBtn);
      }
      frList.appendChild(li);
    });
  }
  factSection.appendChild(frList);
  if (!readOnly) {
    const addFr = document.createElement("button");
    addFr.type = "button";
    addFr.className = "code-question-define-secondary";
    addFr.textContent = "Open Fact Request";
    addFr.addEventListener("click", async () => {
      const title = await openWebTextPrompt({
        title: "Fact Request",
        message: "Open a Fact Request anchored to this question.",
        label: "Title",
        required: true,
        confirmLabel: "Continue"
      });
      if (!title) return;
      const body = await openWebTextPrompt({
        title: "Fact Request details",
        message: "Optional details for the assignee.",
        label: "Details",
        required: false,
        multiline: true,
        confirmLabel: "Continue"
      });
      if (body === null) return;
      const anchor = await openWebTextPrompt({
        title: "Anchor input",
        message: "Optional input ID to anchor this request.",
        label: "Input ID",
        required: false,
        confirmLabel: "Create request"
      });
      if (anchor === null) return;
      try {
        const input = getDefinitionForQuestion(qid).inputs.find((item) => item.id === anchor);
        await executeCodeQuestionMutation("/projects/collaboration/threads/save", {
          projectID: activeProjectIDForCodeQuestions(), questionID: qid,
          requestType: "fact-request", kind: "fact-request",
          targetKind: input ? "questionInput" : "codeQuestion",
          targetID: input?.id || qid,
          targetAnchor: input
            ? { anchorKind: "input", anchorID: input.id, label: input.statement }
            : { anchorKind: "question", anchorID: qid, label: "Question definition" },
          blocking: true, title, body: body || "", status: "open"
        }, {
          commandKind: "codeQuestion.review.manage",
          applyOptimistic: () => saveDefinitionForQuestion(qid, openFactRequest(getDefinitionForQuestion(qid), {
            title, body: body || "", inputID: input?.id || null,
            actorUserID: codeQuestionActor().userID,
            actorDisplayName: codeQuestionActor().displayName
          }))
        });
        refreshCodeQuestionDefinitionPane(qid);
      } catch (error) {
        void showWebNotice("Could not open Fact Request", error.message || "Could not open Fact Request.");
      }
    });
    factSection.appendChild(addFr);
  }
  wrap.appendChild(factSection);

  // Offline queue status and explicit replay control.
  const offline = document.createElement("section");
  offline.className = "code-question-define-offline";
  const queuedMutations = (state.codeQuestionOutbox || []).filter((item) => item.questionID === qid);
  const queuedConflicts = (state.codeQuestionConflicts || []).filter((item) => item.questionID === qid);
  offline.innerHTML = `<h3>Offline queue</h3>
    <p class="code-question-define-muted">Queued definition mutations wait for reconnect. Conflicts are reported; edits are not silently dropped.</p>
    <p>Queued: <strong>${queuedMutations.length}</strong> · Conflicts: <strong>${queuedConflicts.length}</strong></p>`;
  if (queuedConflicts.length) {
    const conflictList = document.createElement("ul");
    conflictList.className = "code-question-define-blockers";
    queuedConflicts.forEach((conflict) => {
      const item = document.createElement("li");
      item.textContent = `${conflict.conflictCode || "Conflict"}: ${conflict.lastError || "Review the server version before retrying."}`;
      conflictList.appendChild(item);
    });
    offline.appendChild(conflictList);
  }
  if (!readOnly) {
    const replayBtn = document.createElement("button");
    replayBtn.type = "button";
    replayBtn.className = "code-question-define-secondary";
    replayBtn.textContent = "Replay queue";
    replayBtn.addEventListener("click", async () => {
      if (!codeQuestionIsOnline()) {
        await showWebNotice("Offline queue", "Reconnect before replaying queued question updates.");
        return;
      }
      await flushCodeQuestionOutbox();
      refreshCodeQuestionDefinitionPane(qid);
    });
    replayBtn.hidden = queuedMutations.length === 0;
    offline.appendChild(replayBtn);
  }
  wrap.appendChild(offline);

  if (readOnly) {
    const banner = document.createElement("p");
    banner.className = "code-question-define-readonly-banner";
    banner.textContent = "Read-only for Viewer/Reviewer roles. Editors and Owners can edit definitions.";
    wrap.prepend(banner);
  }
  return wrap;
}

function renderDefineInputSection({ questionID, title, kind, items, readOnly, emptyText }) {
  const section = document.createElement("section");
  section.className = `code-question-define-inputs ${inputKindCssClass(kind)}`;
  section.dataset.inputKind = kind;
  const heading = document.createElement("h3");
  heading.textContent = title;
  section.appendChild(heading);
  const list = document.createElement("ul");
  list.className = "code-question-define-input-list";
  list.setAttribute("aria-label", title);
  if (!items.length) {
    const empty = document.createElement("li");
    empty.className = "code-question-define-empty-item";
    empty.textContent = emptyText;
    list.appendChild(empty);
  } else {
    items.forEach((item) => {
      const li = document.createElement("li");
      li.className = `code-question-define-input ${inputKindCssClass(item.inputKind)}`;
      if (item.changeIndicator) li.classList.add("has-change");
      li.dataset.inputId = item.id;
      li.dataset.inputKind = item.inputKind;
      li.innerHTML = `
        <div class="code-question-define-input-head">
          <span class="code-question-define-kind-badge">${escapeHTML(inputKindLabel(item.inputKind))}</span>
          <span class="code-question-define-input-state">${escapeHTML(item.state)}</span>
          ${item.changeIndicator ? '<span class="code-question-define-change">Changed</span>' : ""}
        </div>
        <p class="code-question-define-statement">${escapeHTML(item.statement)}</p>
        <p class="code-question-define-input-meta">
          ${escapeHTML(item.id)} · r${escapeHTML(String(item.revision))}
          ${item.basis ? ` · Basis: ${escapeHTML(item.basis)}` : ""}
          ${item.responsibleDisplayName ? ` · ${escapeHTML(item.responsibleDisplayName)}` : ""}
          · ${escapeHTML(item.updatedBy || item.createdBy || "")}
        </p>
      `;
      const history = inputRevisionHistory(getDefinitionForQuestion(questionID), item.id);
      if (history.length > 1) {
        const details = document.createElement("details");
        details.className = "code-question-define-history";
        details.innerHTML = `<summary>Revision history (${history.length})</summary>`;
        const histList = document.createElement("ol");
        history.forEach((rev) => {
          const revItem = document.createElement("li");
          revItem.textContent = `r${rev.revision}: ${rev.statement} (${rev.state}) — ${rev.updatedBy || rev.createdBy || "unknown"} @ ${rev.updatedAt || rev.createdAt || ""}`;
          histList.appendChild(revItem);
        });
        details.appendChild(histList);
        li.appendChild(details);
      }
      if (!readOnly) {
        const actions = document.createElement("div");
        actions.className = "code-question-define-input-actions";
        const edit = document.createElement("button");
        edit.type = "button";
        edit.textContent = "Revise";
        edit.addEventListener("click", async () => {
          const statement = await openWebTextPrompt({
            title: "Revise input",
            message: "Update the statement for this structured input.",
            label: "Statement",
            defaultValue: item.statement,
            required: true,
            multiline: true,
            confirmLabel: "Continue"
          });
          if (statement == null) return;
          const stateValue = await openWebTextPrompt({
            title: "Input state",
            message: `Allowed: ${questionInputStatesForKind(item.inputKind).join(", ")}`,
            label: "State",
            defaultValue: item.state,
            required: true,
            confirmLabel: "Save revision"
          });
          if (stateValue == null) return;
          try {
            await executeCodeQuestionMutation("/projects/code-questions/inputs/save", {
              projectID: activeProjectIDForCodeQuestions(), questionID,
              id: item.id, expectedVersion: item.expectedVersion,
              statement, state: stateValue, basis: item.basis || ""
            }, {
              commandKind: "codeQuestion.input.save",
              expectedVersion: item.expectedVersion,
              applyOptimistic: () => saveDefinitionForQuestion(questionID, reviseQuestionInput(
                getDefinitionForQuestion(questionID), item.id, { statement, state: stateValue },
                { actorUserID: codeQuestionActor().userID }
              ))
            });
            refreshCodeQuestionDefinitionPane(questionID);
          } catch (error) {
            void showWebNotice("Could not revise input", error.message || "Could not revise input.");
          }
        });
        actions.appendChild(edit);
        if (item.inputKind === "unknown" && item.state !== "resolved") {
          const resolve = document.createElement("button");
          resolve.type = "button";
          resolve.textContent = "Mark resolved";
          resolve.addEventListener("click", async () => {
            try {
              await executeCodeQuestionMutation("/projects/code-questions/inputs/save", {
                projectID: activeProjectIDForCodeQuestions(), questionID,
                id: item.id, expectedVersion: item.expectedVersion,
                statement: item.statement, state: "resolved", basis: item.basis || ""
              }, {
                commandKind: "codeQuestion.input.save",
                expectedVersion: item.expectedVersion,
                applyOptimistic: () => saveDefinitionForQuestion(questionID, reviseQuestionInput(
                  getDefinitionForQuestion(questionID), item.id, { state: "resolved" },
                  { actorUserID: codeQuestionActor().userID }
                ))
              });
              refreshCodeQuestionDefinitionPane(questionID);
            } catch (error) {
              void showWebNotice("Could not resolve unknown", error.message || "Could not resolve unknown.");
            }
          });
          actions.appendChild(resolve);
        }
        li.appendChild(actions);
      }
      list.appendChild(li);
    });
  }
  section.appendChild(list);
  if (!readOnly) {
    const add = document.createElement("button");
    add.type = "button";
    add.className = "code-question-define-add-input";
    add.textContent = `Add ${inputKindLabel(kind).toLowerCase()}`;
    add.addEventListener("click", async () => {
      const statement = await openWebTextPrompt({
        title: `Add ${inputKindLabel(kind)}`,
        message: "Enter the statement. Assumptions are never labeled as confirmed facts.",
        label: "Statement",
        required: true,
        multiline: true,
        confirmLabel: "Continue"
      });
      if (!statement) return;
      const basis = await openWebTextPrompt({
        title: "Basis / source",
        message: "Optional basis or source for this input.",
        label: "Basis",
        required: false,
        confirmLabel: "Add input"
      });
      if (basis === null) return;
      try {
        const actor = codeQuestionActor();
        const inputID = globalThis.crypto?.randomUUID?.() || `input-${Date.now()}`;
        await executeCodeQuestionMutation("/projects/code-questions/inputs/save", {
          projectID: activeProjectIDForCodeQuestions(), questionID,
          id: inputID, kind, statement, basis: basis || "",
          state: kind === "confirmedFact" ? "confirmed" : "proposed"
        }, {
          commandKind: "codeQuestion.input.save",
          applyOptimistic: () => saveDefinitionForQuestion(questionID, createQuestionInput(
            getDefinitionForQuestion(questionID), {
              id: inputID, inputKind: kind, statement, basis: basis || "",
              actorUserID: actor.userID, responsibleDisplayName: actor.displayName
            }
          ))
        });
        refreshCodeQuestionDefinitionPane(questionID);
      } catch (error) {
        void showWebNotice("Could not add input", error.message || "Could not add input.");
      }
    });
    section.appendChild(add);
  }
  return section;
}

function questionInputStatesForKind(kind) {
  if (kind === "assumption") return ["proposed", "disputed", "retired"];
  if (kind === "unknown") return ["proposed", "resolved", "retired"];
  return ["proposed", "confirmed", "disputed", "retired"];
}

function refreshCodeDecisionPrimaryPanes(questionID) {
  const safeID = String(questionID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const project = openProjectDetails()[0] || null;
  track?.querySelectorAll?.(`.code-question-panel[data-question-id="${safeID}"]`).forEach((pane) => {
    const body = pane.querySelector(".code-question-panel-body");
    if (!body) return;
    if (pane.dataset.cqRole === "research") body.replaceChildren(renderCodeDecisionResearchBody(project, questionID));
    if (pane.dataset.cqRole === "decision-record") body.replaceChildren(renderCodeDecisionRecordBody(project, questionID));
  });
  renderCodeQuestionShellChrome();
}

function refreshCodeQuestionDefinitionPane(questionID) {
  const safeID = String(questionID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const pane = track?.querySelector?.(
    `.code-question-panel[data-cq-role="definition"][data-question-id="${safeID}"] .code-question-panel-body`
  );
  if (!pane) {
    void renderWorkspace();
    return;
  }
  const project = openProjectDetails()[0] || null;
  pane.replaceChildren(renderCodeQuestionDefinitionBody(project, questionID));
  refreshCodeDecisionPrimaryPanes(questionID);
}

function refreshCodeQuestionEvidencePanes(questionID) {
  const project = openProjectDetails()[0] || null;
  const safeID = String(questionID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const roles = ["candidates", "reader", "evidence-tray", "approved-evidence"];
  let refreshed = false;
  for (const role of roles) {
    const pane = track?.querySelector?.(
      `.code-question-panel[data-cq-role="${role}"][data-question-id="${safeID}"] .code-question-panel-body`
    );
    if (!pane) continue;
    refreshed = true;
    if (role === "candidates") pane.replaceChildren(renderCodeQuestionCandidatesBody(project, questionID));
    else if (role === "reader") pane.replaceChildren(renderCodeQuestionEvidenceReaderBody(project, questionID));
    else pane.replaceChildren(renderCodeQuestionEvidenceTrayBody(project, questionID));
  }
  if (!refreshed) void renderWorkspace();
  else refreshCodeDecisionPrimaryPanes(questionID);
}

function renderCodeQuestionCandidatesBody(project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-evidence-candidates";
  const qid = String(questionID || codeQuestionWorkspaceState().activeQuestionID || "").trim();
  if (!qid || qid === "_") {
    wrap.innerHTML = `<p class="code-question-define-empty">Open a question to search for supporting evidence.</p>`;
    return wrap;
  }
  let evidence = ensureCodeQuestionEvidenceWorkspace(qid);
  const role = codeQuestionDefineRole();
  const notice = document.createElement("p");
  notice.className = "code-question-evidence-banner";
  notice.innerHTML = `<strong>Candidates only.</strong> Search results and bookmarks are not evidence until a professional explicitly proposes and approves them.`;
  wrap.appendChild(notice);
  const toolbar = document.createElement("div");
  toolbar.className = "code-question-evidence-toolbar";
  const search = document.createElement("input");
  search.type = "search";
  search.className = "code-question-index-search";
  search.placeholder = "Filter candidates for this question";
  search.setAttribute("aria-label", "Filter evidence candidates");
  const loadSaved = document.createElement("button");
  loadSaved.type = "button";
  loadSaved.className = "code-question-define-secondary";
  loadSaved.textContent = "Load Project Evidence";
  loadSaved.disabled = !canProposeEvidence(role) && role === "viewer";
  loadSaved.addEventListener("click", async () => {
    loadSaved.disabled = true;
    loadSaved.textContent = "Loading…";
    try {
      const projectSections = (currentContentSummary().projectSections || [])
        .filter((item) => projectSectionBelongsToProject(item, project));
      const savedItems = await hydrateSavedColumnItems(projectSections);
      const candidates = savedItems
        .filter((item) => String(item.savedContentComparisonText || item.previewText || "").trim())
        .map((item) => {
          const codeVersion = syncCodeVersion(item.codeVersion);
          const isCurrentPermitextCode = codeVersion === defaultSyncCodeVersion;
          const sectionID = String(item.sectionID || item.savedSectionID || item.itemID || "");
          const blockID = normalizeAnnotationBlockID(item.blockID || item.anchorID || item.contentBlockID);
          return {
            id: `saved:${codeVersion}:${sectionID}:${blockID || "section"}`,
            label: [item.codePrefix || "Code", item.sectionNumber, item.title]
              .filter(Boolean).join(" "),
            sourceIdentity: `permitext-code:${codeVersion}:${item.codePrefix || "code"}:${sectionID}`,
            passageLocator: [item.codePrefix, item.sectionNumber, blockID].filter(Boolean).join(" · "),
            previewText: item.savedContentComparisonText || item.previewText,
            sourceFamily: item.codePrefix || "code",
            edition: codeVersion,
            sourceStatus: isCurrentPermitextCode ? "verified" : "verification-required",
            completeness: blockID ? "saved-passage" : "saved-section",
            researchEligible: isCurrentPermitextCode,
            note: "Imported from this Project's existing Saved evidence."
          };
        });
      evidence = addCandidates(getEvidenceForQuestion(qid), candidates);
      saveEvidenceForQuestion(qid, evidence);
      refreshCodeQuestionEvidencePanes(qid);
      if (!candidates.length) {
        void showWebNotice(
          "No Project Evidence candidates",
          "Save an exact code passage to this Project first, then load it here for professional proposal and approval."
        );
      }
    } catch (error) {
      void showWebNotice("Could not load Project evidence", error.message || "Saved evidence could not be loaded.");
    } finally {
      loadSaved.disabled = false;
      loadSaved.textContent = "Load Project Evidence";
    }
  });
  toolbar.append(search, loadSaved);
  wrap.appendChild(toolbar);
  const list = document.createElement("ul");
  list.className = "code-question-candidate-list";
  list.setAttribute("role", "listbox");
  list.setAttribute("aria-label", "Evidence candidates");
  const renderList = () => {
    list.replaceChildren();
    const query = String(search.value || "").trim().toLowerCase();
    const items = evidence.candidates.filter((item) =>
      !query || `${item.label} ${item.passageLocator} ${item.previewText}`.toLowerCase().includes(query)
    );
    if (!items.length) {
      const empty = document.createElement("li");
      empty.className = "code-question-define-empty-item";
      empty.textContent = "No candidates. Save an exact passage to this Project, then load Project Evidence.";
      list.appendChild(empty);
      return;
    }
    items.forEach((candidate) => {
      const li = document.createElement("li");
      li.className = "code-question-candidate-item";
      if (evidence.selectedCandidateID === candidate.id) li.classList.add("is-selected");
      li.setAttribute("role", "option");
      li.setAttribute("aria-selected", evidence.selectedCandidateID === candidate.id ? "true" : "false");
      const button = document.createElement("button");
      button.type = "button";
      button.className = "code-question-candidate-open";
      button.innerHTML = `
        <span class="code-question-candidate-label">${escapeHTML(candidate.label)}</span>
        <span class="code-question-candidate-meta">${escapeHTML(candidate.passageLocator)} · ${escapeHTML(sourceVerificationLabel(candidate.sourceStatus))}</span>
        <span class="code-question-candidate-badge">Candidate</span>
      `;
      button.addEventListener("click", () => {
        evidence = selectCandidate(getEvidenceForQuestion(qid), candidate.id);
        evidence = setSelectedPassage(evidence, {
          candidateID: candidate.id,
          passageLocator: candidate.passageLocator,
          quotedText: candidate.previewText,
          surroundingContext: candidate.previewText
        });
        saveEvidenceForQuestion(qid, evidence);
        refreshCodeQuestionEvidencePanes(qid);
      });
      li.appendChild(button);
      list.appendChild(li);
    });
  };
  search.addEventListener("input", renderList);
  renderList();
  wrap.appendChild(list);
  return wrap;
}

function renderCodeQuestionEvidenceReaderBody(project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-evidence-reader";
  const qid = String(questionID || codeQuestionWorkspaceState().activeQuestionID || "").trim();
  if (!qid || qid === "_") {
    wrap.innerHTML = `<p class="code-question-define-empty">Open a question to inspect candidate passages.</p>`;
    return wrap;
  }
  const evidence = ensureCodeQuestionEvidenceWorkspace(qid);
  const candidate = evidence.candidates.find((item) => item.id === evidence.selectedCandidateID);
  const passage = evidence.selectedPassage;
  const role = codeQuestionDefineRole();
  if (!candidate) {
    wrap.innerHTML = `<p class="code-question-define-empty">Select a candidate to inspect exact text, provenance, and eligibility.</p>`;
    return wrap;
  }
  const provenance = readerProvenanceModel(candidate);
  const prov = document.createElement("section");
  prov.className = "code-question-evidence-provenance";
  prov.setAttribute("aria-label", "Source provenance");
  prov.innerHTML = `
    <h3>Source verification</h3>
    <dl class="code-question-evidence-provenance-grid">
      <div><dt>Authority</dt><dd>${escapeHTML(provenance.authority)}</dd></div>
      <div><dt>Edition</dt><dd>${escapeHTML(provenance.edition)}</dd></div>
      <div><dt>Effective</dt><dd>${escapeHTML(provenance.effectiveDate || "Not stated")}</dd></div>
      <div><dt>Status</dt><dd>${escapeHTML(provenance.sourceStatusLabel)}</dd></div>
      <div><dt>Completeness</dt><dd>${escapeHTML(provenance.completeness)}</dd></div>
      <div><dt>Research eligibility</dt><dd>${provenance.researchEligible ? "Eligible" : "Not eligible"}</dd></div>
    </dl>
    <p class="code-question-define-muted">Source verification is separate from Project applicability. A verified source may still not govern this Project.</p>
  `;
  wrap.appendChild(prov);
  const passageEl = document.createElement("section");
  passageEl.className = "code-question-evidence-passage";
  passageEl.setAttribute("aria-label", "Exact passage");
  passageEl.innerHTML = `
    <h3>${escapeHTML(candidate.passageLocator || "Passage")}</h3>
    <blockquote class="code-question-evidence-quote">${escapeHTML(passage?.quotedText || candidate.previewText)}</blockquote>
    <h4>Surrounding context</h4>
    <p class="code-question-evidence-context">${escapeHTML(passage?.surroundingContext || "No surrounding context selected.")}</p>
  `;
  if (passage?.structuredMaterial) {
    const table = document.createElement("pre");
    table.className = "code-question-evidence-structured";
    table.textContent = JSON.stringify(passage.structuredMaterial, null, 2);
    passageEl.appendChild(table);
  }
  wrap.appendChild(passageEl);
  const actions = document.createElement("div");
  actions.className = "code-question-evidence-actions";
  const propose = document.createElement("button");
  propose.type = "button";
  propose.className = "code-question-create-button";
  propose.textContent = role === "owner"
    ? "Propose as Evidence"
    : "Add as Evidence (proposal)";
  propose.disabled = !canProposeEvidence(role);
  propose.addEventListener("click", async () => {
    const evidenceRole = await openWebTextPrompt({
      title: "Evidence role",
      message: "governing, supporting, or conflicting",
      label: "Role",
      defaultValue: "governing",
      required: true,
      confirmLabel: "Continue"
    });
    if (!evidenceRole) return;
    const applicability = await openWebTextPrompt({
      title: "Project applicability",
      message: "Separate from source verification: does this provision govern this Project?",
      label: "Applicability note",
      required: false,
      multiline: true,
      confirmLabel: "Propose"
    });
    if (applicability === null) return;
    try {
      const snapshotID = globalThis.crypto?.randomUUID?.() || `esnap-${Date.now()}`;
      const proposalOptions = {
        actorRole: role,
        actorUserID: codeQuestionActor().userID,
        snapshotID,
        role: evidenceRole,
        analysisEligible: candidate.researchEligible === true,
        forceVerificationBlock: candidate.sourceStatus !== "verified",
        projectApplicabilityNote: applicability || "",
        professionalNote: "Proposed from Candidates reader.",
        incompleteContext: !String(passage?.surroundingContext || "").trim()
      };
      await executeCodeQuestionMutation("/projects/code-questions/evidence/snapshot", {
        projectID: activeProjectIDForCodeQuestions(), questionID: qid, id: snapshotID,
        sourceIdentity: candidate.sourceIdentity,
        passageLocator: passage?.passageLocator || candidate.passageLocator,
        quotedText: passage?.quotedText || candidate.previewText,
        sourceVersion: candidate.edition || "",
        structuredMaterial: passage?.structuredMaterial || null
      }, {
        commandKind: "codeQuestion.evidence.propose",
        hydrate: false
      });
      let next = proposeEvidence(getEvidenceForQuestion(qid), proposalOptions);
      // Solo owner explicit combined propose+approve
      if (role === "owner") {
        const combined = await confirmWebWarning(
          "Approve immediately?",
          "As Owner you may propose and approve in one explicit flow. Choose Approve to create a new approved evidence version, or Cancel to leave a proposal only.",
          { confirmLabel: "Approve evidence", cancelLabel: "Leave as proposal" }
        );
        if (combined) {
          const proposal = next.proposals[next.proposals.length - 1];
          next = approveEvidenceProposal(next, proposal.id, {
            actorRole: "owner",
            actorUserID: codeQuestionActor().userID,
            combined: true
          });
          const set = currentEvidenceSet(next);
          const approved = await executeCodeQuestionMutation("/projects/code-questions/evidence/approve-set", {
            projectID: activeProjectIDForCodeQuestions(), questionID: qid,
            id: globalThis.crypto?.randomUUID?.(),
            entries: set.entries
          }, { commandKind: "codeQuestion.evidence.approve" });
          if (!approved.queued) {
            next = { ...getEvidenceForQuestion(qid), proposals: next.proposals };
          }
        }
      }
      saveEvidenceForQuestion(qid, next);
      assertNoCandidatesInAnalysisInput(next);
      refreshCodeQuestionEvidencePanes(qid);
    } catch (error) {
      void showWebNotice("Could not propose evidence", error.message || "Proposal failed.");
    }
  });
  actions.appendChild(propose);
  if (!canProposeEvidence(role)) {
    const ro = document.createElement("p");
    ro.className = "code-question-define-muted";
    ro.textContent = "Viewers cannot propose evidence.";
    actions.appendChild(ro);
  }
  wrap.appendChild(actions);
  return wrap;
}

function renderCodeQuestionEvidenceTrayBody(project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-evidence-tray";
  const qid = String(questionID || codeQuestionWorkspaceState().activeQuestionID || "").trim();
  if (!qid || qid === "_") {
    wrap.innerHTML = `<p class="code-question-define-empty">Open a question to manage its evidence.</p>`;
    return wrap;
  }
  const evidence = ensureCodeQuestionEvidenceWorkspace(qid);
  const model = trayModel(evidence);
  const role = codeQuestionDefineRole();
  const head = document.createElement("div");
  head.className = "code-question-evidence-tray-head";
  head.innerHTML = `
    <h3>Evidence Tray</h3>
    <p class="code-question-define-muted">Approved set v${model.currentVersion || 0}${model.setContentHash ? ` · hash ${escapeHTML(model.setContentHash.slice(0, 12))}…` : ""}. Candidates are never analysis input.</p>
  `;
  wrap.appendChild(head);

  // Proposals awaiting approval
  const propSection = document.createElement("section");
  propSection.className = "code-question-evidence-proposals";
  propSection.innerHTML = `<h4>Proposals</h4>`;
  const propList = document.createElement("ul");
  propList.className = "code-question-evidence-list";
  if (!model.proposals.length) {
    const empty = document.createElement("li");
    empty.className = "code-question-define-empty-item";
    empty.textContent = "No open proposals.";
    propList.appendChild(empty);
  } else {
    model.proposals.forEach((proposal) => {
      const snap = evidence.snapshots[proposal.snapshotID];
      const li = document.createElement("li");
      li.className = `code-question-evidence-item is-${proposal.state}`;
      const warnings = evidenceWarnings(proposal);
      li.innerHTML = `
        <div class="code-question-evidence-item-head">
          <span class="code-question-define-kind-badge">${escapeHTML(proposal.role)}</span>
          <span>${escapeHTML(proposal.state)}</span>
          <span class="code-question-define-muted">${escapeHTML(sourceVerificationLabel(proposal.sourceVerificationState))}</span>
        </div>
        <p>${escapeHTML(snap?.quotedText || "(snapshot)")}</p>
        <p class="code-question-define-muted">
          Verification: ${escapeHTML(proposal.sourceVerificationState)} ·
          Applicability: ${escapeHTML(proposal.projectApplicabilityNote || "Not noted")}
        </p>
      `;
      if (warnings.length) {
        const warn = document.createElement("ul");
        warn.className = "code-question-evidence-warnings";
        warnings.forEach((item) => {
          const w = document.createElement("li");
          w.textContent = item.message;
          warn.appendChild(w);
        });
        li.appendChild(warn);
      }
      if (canApproveEvidence(role)) {
        const actions = document.createElement("div");
        actions.className = "code-question-evidence-item-actions";
        const approve = document.createElement("button");
        approve.type = "button";
        approve.textContent = "Approve";
        approve.addEventListener("click", async () => {
          try {
            let next = approveEvidenceProposal(getEvidenceForQuestion(qid), proposal.id, {
              actorRole: role,
              actorUserID: codeQuestionActor().userID,
              overrideVerification: proposal.state === "verification-blocked"
            });
            const set = currentEvidenceSet(next);
            const approved = await executeCodeQuestionMutation("/projects/code-questions/evidence/approve-set", {
              projectID: activeProjectIDForCodeQuestions(), questionID: qid,
              id: globalThis.crypto?.randomUUID?.(), entries: set.entries
            }, { commandKind: "codeQuestion.evidence.approve" });
            if (!approved.queued) next = { ...getEvidenceForQuestion(qid), proposals: next.proposals };
            saveEvidenceForQuestion(qid, next);
            assertNoCandidatesInAnalysisInput(next);
            refreshCodeQuestionEvidencePanes(qid);
          } catch (error) {
            void showWebNotice("Could not approve evidence", error.message || "Approval failed.");
          }
        });
        const reject = document.createElement("button");
        reject.type = "button";
        reject.textContent = "Reject";
        reject.addEventListener("click", async () => {
          try {
            const next = rejectEvidenceProposal(getEvidenceForQuestion(qid), proposal.id, {
              actorRole: role,
              actorUserID: codeQuestionActor().userID
            });
            saveEvidenceForQuestion(qid, next);
            refreshCodeQuestionEvidencePanes(qid);
          } catch (error) {
            void showWebNotice("Could not reject evidence", error.message || "Reject failed.");
          }
        });
        actions.append(approve, reject);
        li.appendChild(actions);
      }
      propList.appendChild(li);
    });
  }
  propSection.appendChild(propList);
  wrap.appendChild(propSection);

  // Approved set
  const approvedSection = document.createElement("section");
  approvedSection.className = "code-question-evidence-approved";
  approvedSection.innerHTML = `<h4>Approved Evidence</h4>`;
  const approvedList = document.createElement("ul");
  approvedList.className = "code-question-evidence-list";
  if (!model.approved.length) {
    const empty = document.createElement("li");
    empty.className = "code-question-define-empty-item";
    empty.textContent = "No approved evidence yet. Approved entries are the only analysis-eligible material.";
    approvedList.appendChild(empty);
  } else {
    model.approved.forEach(({ entry, snapshot }) => {
      const li = document.createElement("li");
      li.className = "code-question-evidence-item is-approved";
      li.innerHTML = `
        <div class="code-question-evidence-item-head">
          <span class="code-question-define-kind-badge">${escapeHTML(entry.role)}</span>
          <span>${entry.analysisEligible ? "Analysis-eligible" : "Not analysis-eligible"}</span>
        </div>
        <p>${escapeHTML(snapshot?.quotedText || "")}</p>
        <p class="code-question-define-muted">
          Verification: ${escapeHTML(sourceVerificationLabel(entry.sourceVerificationState))} ·
          Applicability: ${escapeHTML(entry.projectApplicabilityNote || "Not noted")} ·
          hash ${escapeHTML((snapshot?.textHash || "").slice(0, 12))}…
        </p>
      `;
      if (canApproveEvidence(role)) {
        const remove = document.createElement("button");
        remove.type = "button";
        remove.textContent = "Remove (new set version)";
        remove.addEventListener("click", async () => {
          const ok = await confirmWebWarning(
            "Remove approved evidence?",
            "Removal creates a new approved evidence version. Prior versions remain available in history.",
            { confirmLabel: "Remove from set" }
          );
          if (!ok) return;
          try {
            let next = removeEvidenceEntry(getEvidenceForQuestion(qid), entry.snapshotID, {
              actorRole: role,
              actorUserID: codeQuestionActor().userID
            });
            const set = currentEvidenceSet(next);
            const removed = await executeCodeQuestionMutation("/projects/code-questions/evidence/approve-set", {
              projectID: activeProjectIDForCodeQuestions(), questionID: qid,
              id: globalThis.crypto?.randomUUID?.(), entries: set.entries
            }, { commandKind: "codeQuestion.evidence.approve" });
            if (!removed.queued) next = { ...getEvidenceForQuestion(qid), proposals: next.proposals };
            saveEvidenceForQuestion(qid, next);
            refreshCodeQuestionEvidencePanes(qid);
          } catch (error) {
            void showWebNotice("Could not remove evidence", error.message || "Removal failed.");
          }
        });
        li.appendChild(remove);
      }
      approvedList.appendChild(li);
    });
  }
  approvedSection.appendChild(approvedList);
  wrap.appendChild(approvedSection);

  // Unassigned saved (outside tray)
  const unassigned = document.createElement("section");
  unassigned.className = "code-question-evidence-unassigned";
  unassigned.innerHTML = `
    <h4>Unassigned saves (outside tray)</h4>
    <p class="code-question-define-muted">Preserved Project/unassigned Saved material is not question evidence until explicitly proposed.</p>
  `;
  const uList = document.createElement("ul");
  uList.className = "code-question-evidence-list";
  if (!model.unassignedSaved.length) {
    const empty = document.createElement("li");
    empty.className = "code-question-define-empty-item";
    empty.textContent = "No unassigned saved items linked here.";
    uList.appendChild(empty);
  } else {
    model.unassignedSaved.forEach((item) => {
      const li = document.createElement("li");
      li.className = "code-question-evidence-item is-unassigned";
      li.innerHTML = `<strong>${escapeHTML(item.label)}</strong><p class="code-question-define-muted">${escapeHTML(item.note || "")}</p>`;
      uList.appendChild(li);
    });
  }
  unassigned.appendChild(uList);
  wrap.appendChild(unassigned);

  // Reconstructability / analysis eligibility summary
  const summary = document.createElement("section");
  summary.className = "code-question-evidence-summary";
  try {
    const reconstructed = reconstructEvidenceSet(evidence);
    const eligible = analysisEligibleEvidence(evidence);
    assertNoCandidatesInAnalysisInput(evidence);
    summary.innerHTML = `
      <h4>Integrity</h4>
      <p>Reconstructable: <strong>${reconstructed ? "yes" : "n/a"}</strong>
      · Analysis-eligible entries: <strong>${eligible.length}</strong>
      · Candidates never included.</p>
    `;
  } catch (error) {
    summary.innerHTML = `<h4>Integrity</h4><p class="code-question-define-blockers">${escapeHTML(error.message)}</p>`;
  }
  wrap.appendChild(summary);
  return wrap;
}

function codeQuestionAnalysisBinding(questionID) {
  const local = buildAnalysisBinding(
    getDefinitionForQuestion(questionID),
    getEvidenceForQuestion(questionID)
  );
  const server = getAnalysisForQuestion(questionID)?.serverBinding;
  return server ? { ...local, ...server } : local;
}

function renderCodeQuestionApprovedEvidenceBody(_project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-analysis-approved";
  const qid = String(questionID || "").trim();
  if (!qid) {
    wrap.innerHTML = '<p class="code-question-define-empty">Open a question to inspect approved evidence.</p>';
    return wrap;
  }
  try {
    const binding = codeQuestionAnalysisBinding(qid);
    wrap.innerHTML = `
      <section class="code-question-analysis-binding">
        <p class="code-question-pane-status">Bound server authority</p>
        <h3>Approved Evidence · Version ${escapeHTML(String(binding.evidenceSetVersion))}</h3>
        <p class="code-question-define-muted">Only these approved, analysis-eligible snapshots may enter Research. Candidates and mutable conversation selections are excluded.</p>
        <dl class="code-question-analysis-hashes">
          <div><dt>Definition</dt><dd title="${escapeHTML(binding.definitionHash)}">r${escapeHTML(String(binding.definitionRevision))} · ${escapeHTML(binding.definitionHash.slice(0, 16))}…</dd></div>
          <div><dt>Inputs</dt><dd title="${escapeHTML(binding.inputSetHash)}">${escapeHTML(String(binding.inputSnapshotIDs.length))} selected · ${escapeHTML(binding.inputSetHash.slice(0, 16))}…</dd></div>
          <div><dt>Evidence</dt><dd title="${escapeHTML(binding.evidenceSetHash)}">${escapeHTML(binding.evidenceSetHash.slice(0, 16))}…</dd></div>
        </dl>
      </section>`;
    const list = document.createElement("ol");
    list.className = "code-question-analysis-evidence-list";
    binding.approvedEvidence.forEach(({ entry, snapshot }) => {
      const item = document.createElement("li");
      item.innerHTML = `
        <div class="code-question-evidence-item-head">
          <span class="code-question-define-kind-badge">${escapeHTML(entry.role)}</span>
          <span>${escapeHTML(snapshot.passageLocator || snapshot.sourceIdentity)}</span>
        </div>
        <blockquote class="code-question-evidence-quote">${escapeHTML(snapshot.quotedText)}</blockquote>
        <p class="code-question-define-muted">Snapshot ${escapeHTML(snapshot.id)} · ${escapeHTML((snapshot.textHash || "").slice(0, 16))}…</p>`;
      list.appendChild(item);
    });
    wrap.appendChild(list);
  } catch (error) {
    wrap.innerHTML = `
      <p class="code-question-pane-status">Not ready for analysis</p>
      <p class="code-question-define-blockers">${escapeHTML(error.message)}</p>
      <p class="code-question-define-muted">Complete Define and approve at least one analysis-eligible passage in Evidence.</p>`;
  }
  return wrap;
}

function renderCodeQuestionBoundedAnalysisBody(_project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-bounded-analysis";
  const qid = String(questionID || "").trim();
  if (!qid) {
    wrap.innerHTML = '<p class="code-question-define-empty">Open a question to run evidence-bounded analysis.</p>';
    return wrap;
  }
  let binding;
  try {
    binding = codeQuestionAnalysisBinding(qid);
  } catch (error) {
    wrap.innerHTML = `<p class="code-question-pane-status">Analysis unavailable</p><p class="code-question-define-blockers">${escapeHTML(error.message)}</p>`;
    return wrap;
  }
  const workspace = getAnalysisForQuestion(qid);
  const run = latestAnalysisRun(workspace);
  const stale = analysisRunIsStale(run, binding);
  const intro = document.createElement("section");
  intro.className = "code-question-analysis-intro";
  intro.innerHTML = `
    <p class="code-question-pane-status">Selected-evidence-only Research</p>
    <p>Each run is bound to Definition r${escapeHTML(String(binding.definitionRevision))}, ${escapeHTML(String(binding.inputSnapshotIDs.length))} selected inputs, and approved evidence version ${escapeHTML(String(binding.evidenceSetVersion))}.</p>
    <p class="code-question-define-muted">AI-generated research assistance, not an official code determination. The professional conclusion is authored separately.</p>`;
  const runButton = document.createElement("button");
  runButton.type = "button";
  runButton.className = "code-question-analysis-run";
  runButton.textContent = run ? (stale ? "Rerun against current versions" : "Run again with new request") : "Run bounded analysis";
  runButton.addEventListener("click", async () => {
    runButton.disabled = true;
    const requestID = globalThis.crypto?.randomUUID?.() || `request-${Date.now()}`;
    const before = getAnalysisForQuestion(qid);
    try {
      const started = beginAnalysisRequest(before, binding, {
        requestID,
        requestedBy: codeQuestionActor().userID
      });
      saveAnalysisForQuestion(qid, started.workspace);
      await executeCodeQuestionMutation("/projects/code-questions/analysis/create", {
        projectID: activeProjectIDForCodeQuestions(), questionID: qid,
        requestID, idempotencyKey: requestID,
        definitionRevision: binding.definitionRevision,
        definitionHash: binding.definitionHash,
        inputSnapshotIDs: binding.inputSnapshotIDs,
        inputSetHash: binding.inputSetHash,
        evidenceSetID: binding.evidenceSetID,
        evidenceSetVersion: binding.evidenceSetVersion,
        evidenceSetHash: binding.evidenceSetHash,
        dependencyHash: binding.dependencyHash
      }, { commandKind: "codeQuestion.analysis.create" });
      refreshCodeQuestionAnalysisPanes(qid);
    } catch (error) {
      saveAnalysisForQuestion(qid, before);
      void showWebNotice("Could not run bounded analysis", error.message || "Analysis failed.");
      runButton.disabled = false;
    }
  });
  intro.appendChild(runButton);
  wrap.appendChild(intro);
  if (!run) {
    const empty = document.createElement("p");
    empty.className = "code-question-define-empty-item";
    empty.textContent = "No analysis run yet. AI is optional; the professional conclusion can be authored without it.";
    wrap.appendChild(empty);
    return wrap;
  }
  const result = document.createElement("article");
  result.className = `code-question-analysis-result${stale ? " is-stale" : ""}`;
  result.innerHTML = `
    <header>
      <p class="code-question-pane-status">${stale ? "Stale analysis — retained for history" : "Current bounded analysis"}</p>
      <p class="code-question-define-muted">${escapeHTML(run.modelID)} · ${escapeHTML(run.createdAt)} · dependency ${escapeHTML(run.dependencyHash)}</p>
    </header>
    <h3>Analysis</h3>`;
  appendResearchAnswerNarrative(result, run.answer);
  const structured = [
    ["Assumptions", run.answer.assumptions],
    ["Missing facts", run.answer.missingFacts],
    ["Limitations", run.answer.limitations],
    ["Conflicts", run.answer.conflicts],
    ["Additional evidence requested", run.answer.additionalEvidenceNeeded]
  ];
  structured.forEach(([label, values]) => {
    const section = document.createElement("section");
    section.className = "code-question-analysis-structured";
    section.innerHTML = `<h4>${escapeHTML(label)}</h4>`;
    const list = document.createElement("ul");
    if (!values.length) {
      const item = document.createElement("li");
      item.textContent = "None stated.";
      list.appendChild(item);
    } else {
      values.forEach((value) => {
        const item = document.createElement("li");
        item.textContent = value;
        list.appendChild(item);
      });
    }
    section.appendChild(list);
    result.appendChild(section);
  });
  const citations = document.createElement("section");
  citations.className = "code-question-analysis-citations";
  citations.innerHTML = "<h4>Validated citations</h4>";
  const citationList = document.createElement("ol");
  run.answer.citations.forEach((citation) => {
    const item = document.createElement("li");
    item.textContent = `${citation.snapshotIDs.join(", ")} — ${citation.relevance}`;
    citationList.appendChild(item);
  });
  citations.appendChild(citationList);
  result.appendChild(citations);
  const actions = document.createElement("div");
  actions.className = "code-question-analysis-actions";
  const start = document.createElement("button");
  start.type = "button";
  start.textContent = "Use as starting point";
  start.disabled = stale;
  start.addEventListener("click", () => {
    saveAnalysisForQuestion(qid, useAnalysisAsStartingPoint(getAnalysisForQuestion(qid), run));
    refreshCodeQuestionAnalysisPanes(qid);
  });
  const transfer = document.createElement("button");
  transfer.type = "button";
  transfer.textContent = "Transfer citations only";
  transfer.disabled = stale;
  transfer.addEventListener("click", () => {
    saveAnalysisForQuestion(qid, transferAnalysisCitations(getAnalysisForQuestion(qid), run));
    refreshCodeQuestionAnalysisPanes(qid);
  });
  actions.append(start, transfer);
  result.appendChild(actions);
  wrap.appendChild(result);
  return wrap;
}

function renderCodeQuestionProfessionalConclusionBody(_project, questionID) {
  const wrap = document.createElement("div");
  wrap.className = "code-question-professional-conclusion";
  const qid = String(questionID || "").trim();
  if (!qid) return wrap;
  let binding;
  try {
    binding = codeQuestionAnalysisBinding(qid);
  } catch (error) {
    wrap.innerHTML = `<p class="code-question-pane-status">Conclusion unavailable</p><p class="code-question-define-blockers">${escapeHTML(error.message)}</p>`;
    return wrap;
  }
  const workspace = getAnalysisForQuestion(qid);
  const draft = workspace.conclusionDraft;
  wrap.innerHTML = `
    <section class="code-question-conclusion-boundary">
      <p class="code-question-pane-status">Human-authored professional work product</p>
      <p>This conclusion is a separate revisioned artifact. Research text never becomes the conclusion without an explicit professional action.</p>
    </section>`;
  const form = document.createElement("form");
  form.className = "code-question-conclusion-form";
  const conclusion = document.createElement("textarea");
  conclusion.rows = 7;
  conclusion.maxLength = 20_000;
  conclusion.value = draft.conclusionText || "";
  conclusion.setAttribute("aria-label", "Professional conclusion");
  const reasoning = document.createElement("textarea");
  reasoning.rows = 5;
  reasoning.maxLength = 20_000;
  reasoning.value = draft.reasoning || "";
  reasoning.setAttribute("aria-label", "Professional reasoning");
  form.innerHTML = "<label>Professional conclusion</label>";
  form.appendChild(conclusion);
  const reasoningLabel = document.createElement("label");
  reasoningLabel.textContent = "Professional reasoning";
  form.append(reasoningLabel, reasoning);
  const citationField = document.createElement("fieldset");
  citationField.innerHTML = "<legend>Approved evidence cited</legend>";
  binding.approvedEvidence.forEach(({ snapshot }) => {
    const label = document.createElement("label");
    label.className = "code-question-conclusion-citation-choice";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.value = snapshot.id;
    checkbox.checked = (draft.citations || []).includes(snapshot.id);
    label.append(checkbox, document.createTextNode(` ${snapshot.passageLocator || snapshot.id}`));
    citationField.appendChild(label);
  });
  form.appendChild(citationField);
  const disclosure = document.createElement("p");
  disclosure.className = "code-question-define-muted";
  disclosure.textContent = draft.aiAssistanceDisclosure || "No AI starting point is currently disclosed. AI may be skipped entirely.";
  form.appendChild(disclosure);
  const saveDraft = () => {
    const citations = Array.from(citationField.querySelectorAll('input[type="checkbox"]:checked')).map((input) => input.value);
    saveAnalysisForQuestion(qid, updateConclusionDraft(getAnalysisForQuestion(qid), {
      conclusionText: conclusion.value,
      reasoning: reasoning.value,
      citations
    }));
  };
  conclusion.addEventListener("input", saveDraft);
  reasoning.addEventListener("input", saveDraft);
  citationField.addEventListener("change", saveDraft);
  const publish = document.createElement("button");
  publish.type = "button";
  publish.className = "code-question-conclusion-publish";
  publish.textContent = "Publish conclusion revision";
  publish.addEventListener("click", async () => {
    try {
      saveDraft();
      const current = getAnalysisForQuestion(qid);
      const conclusionDraft = current.conclusionDraft;
      await executeCodeQuestionMutation("/projects/code-questions/conclusions/publish", {
        projectID: activeProjectIDForCodeQuestions(), questionID: qid,
        definitionRevision: binding.definitionRevision,
        definitionHash: binding.definitionHash,
        inputSetHash: binding.inputSetHash,
        evidenceSetID: binding.evidenceSetID,
        evidenceSetVersion: binding.evidenceSetVersion,
        evidenceSetHash: binding.evidenceSetHash,
        conclusionText: conclusionDraft.conclusionText,
        reasoning: conclusionDraft.reasoning,
        citations: conclusionDraft.citations,
        assumptions: conclusionDraft.assumptions,
        unknowns: conclusionDraft.unknowns,
        analysisRunID: conclusionDraft.analysisRunID || null,
        analysisDependencyHash: conclusionDraft.analysisRunID ? binding.dependencyHash : null,
        aiAssistanceDisclosure: conclusionDraft.aiAssistanceDisclosure,
        predecessorRevisionID: current.conclusionRevisions.at(-1)?.id || null
      }, {
        commandKind: "codeQuestion.conclusion.publish",
        applyOptimistic: () => {
          const result = publishProfessionalConclusion(getAnalysisForQuestion(qid), binding, {
            authorUserID: codeQuestionActor().userID
          });
          saveAnalysisForQuestion(qid, result.workspace);
        }
      });
      refreshCodeQuestionAnalysisPanes(qid);
    } catch (error) {
      void showWebNotice("Could not publish conclusion", error.message || "Conclusion failed.");
    }
  });
  form.appendChild(publish);
  wrap.appendChild(form);
  const history = document.createElement("section");
  history.className = "code-question-conclusion-history";
  history.innerHTML = `<h3>Revision history</h3>`;
  const list = document.createElement("ol");
  if (!workspace.conclusionRevisions.length) {
    const item = document.createElement("li");
    item.textContent = "No published conclusion revisions.";
    list.appendChild(item);
  } else {
    workspace.conclusionRevisions.slice().reverse().forEach((revision) => {
      const item = document.createElement("li");
      item.innerHTML = `<strong>r${escapeHTML(String(revision.revision))}</strong> · ${escapeHTML(revision.authorUserID)} · ${escapeHTML(revision.createdAt)}<p>${escapeHTML(revision.conclusionText)}</p>`;
      list.appendChild(item);
    });
  }
  history.appendChild(list);
  wrap.appendChild(history);
  return wrap;
}

function codeQuestionReviewTargets(questionID) {
  const qid = String(questionID || "").trim();
  const question = questionsForActiveProject().find((item) => item.id === qid);
  const definition = getDefinitionForQuestion(qid);
  const evidence = getEvidenceForQuestion(qid);
  const analysis = getAnalysisForQuestion(qid);
  const targets = [{
    kind: "codeQuestion", id: qid,
    label: `${question?.displayID || "Question"} · ${question?.title || definition?.title || "Question"}`,
    anchor: { anchorKind: "question", anchorID: qid, label: "Question definition", snapshotHash: definition?.definitionHash || "" }
  }];
  (definition?.inputs || []).filter((item) => item.state !== "retired").forEach((item) => targets.push({
    kind: "questionInput", id: item.id,
    label: `${inputKindLabel(item.inputKind)} · ${item.statement}`,
    anchor: { anchorKind: "input", anchorID: item.id, label: item.statement, snapshotHash: item.contentHash || "" }
  }));
  const set = currentEvidenceSet(evidence);
  if (set) targets.push({
    kind: "questionEvidenceSet", id: set.id,
    label: `Approved Evidence · Version ${set.version}`,
    anchor: { anchorKind: "evidence-set", anchorID: set.id, label: `Approved Evidence · Version ${set.version}`, snapshotHash: set.setHash }
  });
  const run = latestAnalysisRun(analysis);
  if (run) targets.push({
    kind: "questionAnalysis", id: run.id,
    label: `Bounded Analysis · ${run.createdAt}`,
    anchor: { anchorKind: "analysis-run", anchorID: run.id, label: "Bounded Analysis", snapshotHash: run.dependencyHash }
  });
  const conclusion = analysis?.conclusionRevisions?.[analysis.conclusionRevisions.length - 1];
  if (conclusion) targets.push({
    kind: "professionalConclusion", id: conclusion.id,
    label: `Professional Conclusion r${conclusion.revision}`,
    anchor: { anchorKind: "conclusion-revision", anchorID: conclusion.id, label: `Conclusion r${conclusion.revision}`, snapshotHash: conclusion.analysisDependencyHash || conclusion.evidenceSetHash }
  });
  return targets;
}

function codeQuestionReviewTypeLabel(type) {
  return {
    "fact-request": "Fact Request",
    "evidence-review": "Evidence Review",
    "interpretation-review": "Interpretation Review",
    "revision-request": "Revision Request"
  }[type] || "Review Request";
}

function refreshCodeQuestionReviewPanes(questionID) {
  const safeID = String(questionID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const project = openProjectDetails()[0] || null;
  track?.querySelectorAll?.(`.code-question-panel[data-question-id="${safeID}"]`).forEach((pane) => {
    const body = pane.querySelector(".code-question-panel-body");
    if (!body) return;
    if (pane.dataset.cqRole === "review-requests") body.replaceChildren(renderCodeQuestionReviewRequestsBody(project, questionID));
    if (pane.dataset.cqRole === "history") body.replaceChildren(renderCodeQuestionReviewHistoryBody(project, questionID));
  });
  refreshCodeDecisionPrimaryPanes(questionID);
  saveWorkspaceState();
}

function renderCodeQuestionReviewRequestsBody(project, questionID) {
  const qid = String(questionID || "").trim();
  const wrap = document.createElement("div");
  wrap.className = "code-question-review-workspace";
  if (!qid) return wrap;
  const review = getReviewForQuestion(qid);
  const actor = codeQuestionActor();
  const targets = codeQuestionReviewTargets(qid);
  const latestConclusion = getAnalysisForQuestion(qid)?.conclusionRevisions?.at(-1) || null;
  const blockers = unresolvedBlockingRequests(review);
  const boundary = document.createElement("section");
  boundary.className = "code-question-review-boundary";
  boundary.innerHTML = `
    <p class="code-question-pane-status">Auditable professional review</p>
    <p>Review Requests reuse Project Coordination records. Responses are immutable; status transitions and approval remain separate recorded actions.</p>
    <p class="code-question-define-muted">${escapeHTML(String(blockers.length))} open blocking request${blockers.length === 1 ? "" : "s"} · approval ${review.approvals.length ? `recorded r${review.approvals.length}` : "not recorded"}</p>`;
  wrap.appendChild(boundary);

  const approval = document.createElement("section");
  approval.className = "code-question-review-approval";
  const approvalTitle = document.createElement("h3");
  approvalTitle.textContent = "Professional approval";
  const approvalCopy = document.createElement("p");
  approvalCopy.textContent = "Approval targets one preserved conclusion revision. Resolving a request never approves the conclusion.";
  const basis = document.createElement("textarea");
  basis.rows = 3;
  basis.maxLength = 4_000;
  basis.placeholder = "Record the review basis…";
  basis.setAttribute("aria-label", "Conclusion approval basis");
  const approve = document.createElement("button");
  approve.type = "button";
  approve.textContent = latestConclusion ? `Approve conclusion r${latestConclusion.revision}` : "Publish a conclusion before approval";
  approve.disabled = !latestConclusion || blockers.length > 0;
  approve.addEventListener("click", async () => {
    try {
      await executeCodeQuestionMutation("/projects/code-questions/conclusions/approve", {
        projectID: activeProjectIDForCodeQuestions(), questionID: qid,
        conclusionID: latestConclusion.id,
        approvalBasis: basis.value
      }, {
        commandKind: "codeQuestion.conclusion.approve",
        applyOptimistic: () => {
          const result = approveProfessionalConclusion(getReviewForQuestion(qid), latestConclusion, {
            basis: basis.value, actor
          });
          saveReviewForQuestion(qid, result.workspace);
        }
      });
      refreshCodeQuestionReviewPanes(qid);
    } catch (error) {
      void showWebNotice("Conclusion not approved", error.message);
    }
  });
  approval.append(approvalTitle, approvalCopy, basis, approve);
  if (blockers.length) {
    const warning = document.createElement("p");
    warning.className = "code-question-define-blockers";
    warning.textContent = "Approval is blocked until all blocking Review Requests are resolved or dismissed.";
    approval.appendChild(warning);
  }
  wrap.appendChild(approval);

  const composer = document.createElement("form");
  composer.className = "code-question-review-composer";
  composer.innerHTML = "<h3>Open Review Request</h3>";
  const type = document.createElement("select");
  type.setAttribute("aria-label", "Review Request type");
  codeQuestionReviewRequestTypes.forEach((value) => type.append(new Option(codeQuestionReviewTypeLabel(value), value)));
  const target = document.createElement("select");
  target.setAttribute("aria-label", "Review Request target");
  targets.forEach((item, index) => {
    const option = new Option(item.label, String(index));
    target.append(option);
  });
  const blocking = document.createElement("label");
  blocking.className = "code-question-review-blocking-choice";
  const blockingInput = document.createElement("input");
  blockingInput.type = "checkbox";
  blockingInput.checked = true;
  blocking.append(blockingInput, document.createTextNode(" Blocking for approval and issuance"));
  const title = document.createElement("input");
  title.required = true;
  title.maxLength = 200;
  title.placeholder = "What needs professional attention?";
  title.setAttribute("aria-label", "Review Request title");
  const body = document.createElement("textarea");
  body.rows = 4;
  body.maxLength = 20_000;
  body.placeholder = "Describe the fact, evidence, interpretation, or revision needed.";
  body.setAttribute("aria-label", "Review Request details");
  const open = document.createElement("button");
  open.type = "submit";
  open.textContent = "Open Review Request";
  composer.append(type, target, blocking, title, body, open);
  composer.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      const selected = targets[Number(target.value)] || targets[0];
      await executeCodeQuestionMutation("/projects/collaboration/threads/save", {
        projectID: activeProjectIDForCodeQuestions(), questionID: qid,
        requestType: type.value,
        targetKind: selected.kind, targetID: selected.id,
        targetAnchor: selected.anchor, blocking: blockingInput.checked,
        title: title.value, body: body.value, status: "open"
      }, {
        commandKind: "codeQuestion.review.manage",
        applyOptimistic: () => {
          const result = createReviewRequest(getReviewForQuestion(qid), {
            questionID: qid, requestType: type.value,
            targetKind: selected.kind, targetID: selected.id,
            targetLabel: selected.label, targetAnchor: selected.anchor,
            blocking: blockingInput.checked, title: title.value, body: body.value, actor
          });
          saveReviewForQuestion(qid, result.workspace);
        }
      });
      refreshCodeQuestionReviewPanes(qid);
    } catch (error) {
      void showWebNotice("Review Request not opened", error.message);
    }
  });
  wrap.appendChild(composer);

  const filters = document.createElement("div");
  filters.className = "code-question-review-filters";
  ["open", "waiting", "resolved", "dismissed"].forEach((status) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = `${projectReviewStatusLabel(status)} ${review.requests.filter((item) => item.status === status).length}`;
    button.setAttribute("aria-pressed", String(review.activeFilter === status));
    button.addEventListener("click", () => {
      saveReviewForQuestion(qid, { ...getReviewForQuestion(qid), activeFilter: status });
      refreshCodeQuestionReviewPanes(qid);
    });
    filters.appendChild(button);
  });
  wrap.appendChild(filters);
  const list = document.createElement("ol");
  list.className = "code-question-review-list";
  review.requests.filter((item) => item.status === review.activeFilter).slice().reverse().forEach((request) => {
    const item = document.createElement("li");
    item.className = `code-question-review-request is-${request.status}`;
    item.innerHTML = `
      <div class="code-question-review-request-head"><span>${escapeHTML(codeQuestionReviewTypeLabel(request.requestType))}</span><strong>${escapeHTML(projectReviewStatusLabel(request.status))}</strong></div>
      <h4>${escapeHTML(request.title)}</h4>
      <p>${escapeHTML(request.body || "No additional details recorded.")}</p>
      <p class="code-question-define-muted">${request.blocking ? "Blocking" : "Advisory"} · Round ${escapeHTML(String(request.reviewRound))} · ${escapeHTML(request.targetLabel)} · ${escapeHTML(request.updatedAt)}</p>`;
    const actions = document.createElement("div");
    actions.className = "code-question-review-request-actions";
    const transition = async (status, resolution = "") => {
      try {
        await executeCodeQuestionMutation("/projects/collaboration/threads/save", {
          projectID: activeProjectIDForCodeQuestions(), questionID: qid,
          threadID: request.id, expectedVersion: request.version,
          status, resolution
        }, {
          commandKind: "codeQuestion.review.manage",
          expectedVersion: request.version,
          applyOptimistic: () => {
            const result = transitionReviewRequest(getReviewForQuestion(qid), request.id, status, { resolution, actor });
            saveReviewForQuestion(qid, result.workspace);
          }
        });
        refreshCodeQuestionReviewPanes(qid);
      } catch (error) {
        void showWebNotice("Review status not changed", error.message);
      }
    };
    if (["resolved", "dismissed"].includes(request.status)) {
      const reopen = document.createElement("button");
      reopen.type = "button";
      reopen.textContent = "Reopen";
      reopen.addEventListener("click", () => void transition("open"));
      actions.append(reopen);
    } else {
      const waiting = document.createElement("button");
      waiting.type = "button";
      waiting.textContent = request.status === "waiting" ? "Mark open" : "Mark waiting";
      waiting.addEventListener("click", () => void transition(request.status === "waiting" ? "open" : "waiting"));
      const dismiss = document.createElement("button");
      dismiss.type = "button";
      dismiss.textContent = "Dismiss";
      dismiss.addEventListener("click", () => void transition("dismissed"));
      actions.append(waiting, dismiss);
      const resolution = document.createElement("form");
      resolution.className = "code-question-review-resolution";
      const resolutionText = document.createElement("input");
      resolutionText.required = true;
      resolutionText.maxLength = 2_000;
      resolutionText.placeholder = "Resolution statement";
      resolutionText.setAttribute("aria-label", `Resolution for ${request.title}`);
      const resolve = document.createElement("button");
      resolve.type = "submit";
      resolve.textContent = "Resolve";
      resolution.append(resolutionText, resolve);
      resolution.addEventListener("submit", (event) => {
        event.preventDefault();
        void transition("resolved", resolutionText.value);
      });
      actions.append(resolution);
      const commentForm = document.createElement("form");
      commentForm.className = "code-question-review-comment-form";
      const comment = document.createElement("input");
      comment.required = true;
      comment.maxLength = 10_000;
      comment.placeholder = "Add response to history";
      comment.setAttribute("aria-label", `Respond to ${request.title}`);
      const post = document.createElement("button");
      post.type = "submit";
      post.textContent = "Post";
      commentForm.append(comment, post);
      commentForm.addEventListener("submit", async (event) => {
        event.preventDefault();
        try {
          await executeCodeQuestionMutation("/projects/collaboration/comments/save", {
            projectID: activeProjectIDForCodeQuestions(), questionID: qid,
            threadID: request.id, body: comment.value
          }, {
            commandKind: "codeQuestion.review.manage",
            applyOptimistic: () => {
              const result = appendReviewComment(getReviewForQuestion(qid), request.id, { body: comment.value, actor });
              saveReviewForQuestion(qid, result.workspace);
            }
          });
          refreshCodeQuestionReviewPanes(qid);
        } catch (error) {
          void showWebNotice("Response not posted", error.message);
        }
      });
      actions.append(commentForm);
    }
    item.appendChild(actions);
    const comments = review.comments.filter((comment) => comment.requestID === request.id);
    if (comments.length) {
      const responses = document.createElement("ol");
      responses.className = "code-question-review-comments";
      comments.forEach((comment) => {
        const response = document.createElement("li");
        response.textContent = `${comment.body} — ${comment.createdBy.displayName}, ${comment.createdAt}`;
        responses.appendChild(response);
      });
      item.appendChild(responses);
    }
    list.appendChild(item);
  });
  if (!list.childElementCount) {
    const empty = document.createElement("li");
    empty.className = "code-question-define-empty-item";
    empty.textContent = `No ${review.activeFilter} Review Requests.`;
    list.appendChild(empty);
  }
  wrap.appendChild(list);
  if (project) void appendServerReviewRequestLinks(wrap, project, qid, targets);
  return wrap;
}

async function appendServerReviewRequestLinks(wrap, project, questionID, targets) {
  const identity = projectIdentity(project);
  const { foundation } = await loadProjectCoordinationFoundation(identity);
  if (!foundation || !wrap.isConnected) return;
  const targetIDs = new Set(targets.map((item) => item.id));
  const legacy = projectCollaborationArtifacts(foundation, "reviewThread")
    .filter((thread) => thread.questionID === questionID || targetIDs.has(thread.targetID))
    .map((thread) => adaptLegacyReviewThread(thread, questionID))
    .filter(Boolean);
  if (!legacy.length) return;
  const section = document.createElement("section");
  section.className = "code-question-review-server-links";
  section.innerHTML = "<h3>Shared Project Review Requests</h3><p class=\"code-question-define-muted\">Existing Coordination records retain their version and editing rules.</p>";
  legacy.forEach((thread) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = `${codeQuestionReviewTypeLabel(thread.requestType)} · ${thread.title} · ${projectReviewStatusLabel(thread.status)}`;
    button.addEventListener("click", () => void openProjectCoordinationThread(identity, thread.id));
    section.appendChild(button);
  });
  wrap.appendChild(section);
}

function renderCodeQuestionReviewHistoryBody(_project, questionID) {
  const qid = String(questionID || "").trim();
  const wrap = document.createElement("div");
  wrap.className = "code-question-review-history";
  const review = getReviewForQuestion(qid);
  wrap.innerHTML = `
    <section class="code-question-review-history-boundary">
      <p class="code-question-pane-status">Passive audit history</p>
      <p>History records what happened. Active requests and controls remain in the Review Requests pane.</p>
    </section>`;
  const list = document.createElement("ol");
  list.className = "code-question-review-history-list";
  review.history.slice().reverse().forEach((event) => {
    const item = document.createElement("li");
    const transition = event.from || event.to ? ` · ${event.from || "—"} → ${event.to || "—"}` : "";
    item.innerHTML = `<strong>${escapeHTML(event.action.replaceAll(".", " "))}</strong>${escapeHTML(transition)}<p>${escapeHTML(event.actor.displayName)} · ${escapeHTML(event.at)}</p>`;
    list.appendChild(item);
  });
  if (!list.childElementCount) {
    const empty = document.createElement("li");
    empty.textContent = "No review activity recorded yet.";
    list.appendChild(empty);
  }
  wrap.appendChild(list);
  return wrap;
}

function codeMemoContext(project, questionID) {
  const qid = String(questionID || "").trim();
  const definition = getDefinitionForQuestion(qid);
  const evidence = getEvidenceForQuestion(qid);
  const analysis = getAnalysisForQuestion(qid);
  const review = getReviewForQuestion(qid);
  const issue = getIssueForQuestion(qid);
  const question = questionsForActiveProject().find((item) => item.id === qid) || {};
  let binding = null;
  try {
    binding = buildAnalysisBinding(definition, evidence);
  } catch {
    // Readiness reports the missing dependency in its own bounded checklist.
  }
  const draft = issue.draftRevisions.at(-1) || null;
  const actor = { ...codeQuestionActor(), role: codeQuestionDefineRole() };
  const readiness = codeMemoReadiness({
    definition, evidence, analysis, review, draft, actor,
    currentDependencyHash: binding?.dependencyHash || null
  });
  return { qid, project, question, definition, evidence, analysis, review, issue, binding, draft, actor, readiness };
}

function codeMemoDerivedState(context) {
  const { issue, draft } = context;
  if (!draft) return "draft";
  const issued = issue.issuedRecords.find((item) => item.draftID === draft.id);
  if (issued) return issuedRecordStatus(issue, issued.id).state;
  const pending = issue.pendingIssuance.slice().reverse().find((item) => item.draftID === draft.id);
  if (pending?.state === "issuing") return "issuing";
  if (issue.memoApprovals.some((item) => item.draftID === draft.id && item.draftHash === draft.draftHash)) return "approved";
  if (issue.readinessRecord?.draftID === draft.id && issue.readinessRecord?.draftHash === draft.draftHash) return "ready-for-approval";
  return "draft";
}

function refreshCodeMemoPanes(questionID) {
  const safeID = String(questionID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  const project = openProjectDetails()[0] || null;
  track?.querySelectorAll?.(`.code-question-panel[data-question-id="${safeID}"]`).forEach((pane) => {
    const body = pane.querySelector(".code-question-panel-body");
    if (!body) return;
    if (pane.dataset.cqRole === "code-memo-draft") body.replaceChildren(renderCodeMemoDraftBody(project, questionID));
    if (pane.dataset.cqRole === "readiness") body.replaceChildren(renderCodeMemoReadinessBody(project, questionID));
    if (pane.dataset.cqRole === "versions") body.replaceChildren(renderCodeMemoVersionsBody(project, questionID));
  });
  refreshCodeDecisionPrimaryPanes(questionID);
  saveWorkspaceState();
}

function renderCodeMemoDraftBody(project, questionID) {
  const context = codeMemoContext(project, questionID);
  const wrap = document.createElement("div");
  wrap.className = "code-memo-workspace";
  const stateLabel = codeMemoDerivedState(context).replaceAll("-", " ");
  const boundary = document.createElement("section");
  boundary.className = "code-memo-boundary";
  boundary.innerHTML = `<p class="code-question-pane-status">Report · ${escapeHTML(stateLabel)}</p><p>A professional Report assembled from selected versions. Editing creates a new revision while prior versions remain available in Report history.</p>`;
  wrap.appendChild(boundary);

  const form = document.createElement("form");
  form.className = "code-memo-prepare-form";
  const title = document.createElement("input");
  title.required = true;
  title.maxLength = 300;
  title.setAttribute("aria-label", "Code Memo title");
  title.value = `${context.question.displayID || "Q"} · ${context.question.title || context.definition?.title || "Code Memo"}`;
  const narrative = document.createElement("textarea");
  narrative.rows = 6;
  narrative.maxLength = 20_000;
  narrative.setAttribute("aria-label", "Bounded authored narrative");
  narrative.placeholder = "Optional professional context, conditions, or implementation note. Source evidence and conclusion remain separate sections.";
  narrative.value = context.draft?.sections?.authoredNarrative || "";
  const include = document.createElement("label");
  include.className = "code-memo-analysis-choice";
  const includeInput = document.createElement("input");
  includeInput.type = "checkbox";
  includeInput.checked = context.draft?.includeAnalysis !== false;
  include.append(includeInput, document.createTextNode(" Include the selected bounded analysis summary"));
  const prepare = document.createElement("button");
  prepare.type = "submit";
  prepare.textContent = context.draft ? "Prepare new Report revision" : "Prepare Report";
  form.append(title, narrative, include, prepare);
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      await executeCodeQuestionMutation("/projects/code-questions/memos/prepare", {
        projectID: activeProjectIDForCodeQuestions(), questionID: context.qid,
        title: title.value, narrative: narrative.value,
        includeAnalysis: includeInput.checked
      }, { commandKind: "codeQuestion.memo.prepare" });
      refreshCodeMemoPanes(context.qid);
    } catch (error) {
      void showWebNotice("Report not prepared", error.message);
    }
  });
  wrap.appendChild(form);

  if (context.draft) {
    const preview = document.createElement("article");
    preview.className = "code-memo-preview";
    preview.setAttribute("aria-label", `Report revision ${context.draft.draftRevision}`);
    const projectInputs = Array.isArray(context.draft.sections?.projectInputs)
      ? context.draft.sections.projectInputs
      : [];
    const evidenceItems = Array.isArray(context.draft.sections?.evidence)
      ? context.draft.sections.evidence
      : [];
    const questionPresented = context.draft.sections?.questionPresented || context.definition?.questionText || "";
    const professionalConclusion = context.draft.sections?.professionalConclusion?.conclusionText ||
      context.analysis?.conclusionRevisions?.at(-1)?.conclusionText || "Not published";
    preview.innerHTML = `
      <header><p>Draft r${escapeHTML(String(context.draft.draftRevision))} · ${escapeHTML(context.draft.draftHash)}</p><h3>${escapeHTML(context.draft.title)}</h3></header>
      <section><h4>Question presented</h4><p>${escapeHTML(questionPresented)}</p></section>
      <section><h4>Project inputs</h4><ul>${projectInputs.map((item) => `<li><strong>${escapeHTML(item.inputKind)}</strong>: ${escapeHTML(item.statement)}</li>`).join("")}</ul></section>
      <section><h4>Approved evidence</h4><ol>${evidenceItems.map((item) => `<li>${escapeHTML(item.snapshot?.passageLocator || item.snapshotID)} · ${escapeHTML(item.role)}</li>`).join("")}</ol></section>
      ${context.draft.sections?.analysisSummary ? `<section><h4>Bounded analysis summary</h4><p>${escapeHTML(context.draft.sections.analysisSummary.conclusion)}</p></section>` : ""}
      <section><h4>Professional conclusion</h4><p>${escapeHTML(professionalConclusion)}</p></section>
      <section><h4>Authored narrative</h4><p>${escapeHTML(context.draft.sections?.authoredNarrative || context.draft.introduction || "No additional narrative.")}</p></section>`;
    wrap.appendChild(preview);
  }
  return wrap;
}

function renderCodeMemoReadinessBody(project, questionID) {
  const context = codeMemoContext(project, questionID);
  const wrap = document.createElement("div");
  wrap.className = "code-memo-readiness";
  const state = codeMemoDerivedState(context);
  wrap.innerHTML = `<section class="code-memo-boundary"><p class="code-question-pane-status">Readiness · ${escapeHTML(state.replaceAll("-", " "))}</p><p>Ready, approval, and issue are separate actions. This checklist is re-evaluated from current professional records.</p></section>`;
  const list = document.createElement("ol");
  list.className = "code-memo-readiness-list";
  context.readiness.checks.forEach((check) => {
    const item = document.createElement("li");
    item.className = check.ready ? "is-ready" : "is-blocked";
    item.innerHTML = `<strong>${check.ready ? "Ready" : "Blocked"} · ${escapeHTML(check.label)}</strong><p>${escapeHTML(check.message)}</p>`;
    list.appendChild(item);
  });
  wrap.appendChild(list);
  const ready = document.createElement("button");
  ready.type = "button";
  ready.textContent = "Mark ready for approval";
  ready.disabled = !context.draft || !context.readiness.ready || state !== "draft";
  ready.addEventListener("click", async () => {
    try {
      await executeCodeQuestionMutation("/projects/code-questions/memos/ready", {
        projectID: activeProjectIDForCodeQuestions(), questionID: context.qid,
        draftID: context.draft.id
      }, { commandKind: "codeQuestion.memo.ready" });
      refreshCodeMemoPanes(context.qid);
    } catch (error) {
      void showWebNotice("Code Memo not ready", error.message);
    }
  });
  wrap.appendChild(ready);

  const approval = document.createElement("form");
  approval.className = "code-memo-approval-form";
  const basis = document.createElement("textarea");
  basis.rows = 4;
  basis.maxLength = 4_000;
  basis.required = true;
  basis.setAttribute("aria-label", "Code Memo approval basis");
  basis.placeholder = "Record the exact review and approval basis…";
  const approve = document.createElement("button");
  approve.type = "submit";
  approve.textContent = "Approve Code Memo";
  approve.disabled = !context.draft || state !== "ready-for-approval";
  approval.append(basis, approve);
  approval.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      await executeCodeQuestionMutation("/projects/code-questions/memos/approve", {
        projectID: activeProjectIDForCodeQuestions(), questionID: context.qid,
        draftID: context.draft.id, approvalBasis: basis.value
      }, { commandKind: "codeQuestion.memo.approve" });
      refreshCodeMemoPanes(context.qid);
    } catch (error) {
      void showWebNotice("Code Memo not approved", error.message);
    }
  });
  wrap.appendChild(approval);
  if (context.issue.lastFailure) {
    const failure = document.createElement("section");
    failure.className = "code-memo-recovery";
    failure.innerHTML = `<strong>Approved — not issued</strong><p>${escapeHTML(context.issue.lastFailure.message)} The same approved draft may be retried safely.</p>`;
    wrap.appendChild(failure);
  }
  return wrap;
}

function updateQuestionIssuedVersion(questionID, issueVersion) {
  const projectID = activeProjectIDForCodeQuestions();
  const cq = codeQuestionWorkspaceState();
  const questions = (cq.questionsByProjectID?.[projectID] || []).map((question) =>
    question.id === questionID
      ? {
          ...question,
          latestIssuedVersion: issueVersion,
          revisionInProgress: false,
          listLabel: "Issued",
          lastActivityAt: new Date().toISOString()
        }
      : question
  );
  setCodeQuestionWorkspaceState({
    ...cq,
    questionsByProjectID: { ...(cq.questionsByProjectID || {}), [projectID]: questions }
  });
}

function downloadCodeMemoBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 2_000);
}

async function downloadIssuedCodeMemoFile(record, format, filename) {
  const account = activeAccount();
  if (!account) throw new Error("Sign in to download this Issued Record.");
  const response = await fetch("/projects/code-questions/records/file", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${account.sessionToken}`
    },
    body: JSON.stringify({
      auth: { accountUserID: account.userID },
      codeQuestionWorkspaceEnabled: codeQuestionWorkspaceEnabled(),
      projectID: activeProjectIDForCodeQuestions(),
      questionID: record.questionID,
      issuedRecordID: record.id,
      format
    })
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({}));
    throw new Error(payload.error || `Download failed: ${response.status}`);
  }
  downloadCodeMemoBlob(await response.blob(), filename);
}

function renderCodeMemoVersionsBody(project, questionID) {
  const context = codeMemoContext(project, questionID);
  const wrap = document.createElement("div");
  wrap.className = "code-memo-versions";
  const state = codeMemoDerivedState(context);
  const issuanceOnline = navigator.onLine !== false && serverReachable;
  wrap.innerHTML = `<section class="code-memo-boundary"><p class="code-question-pane-status">Issued Records · ${escapeHTML(state.replaceAll("-", " "))}</p><p>Issuance preserves a versioned Manifest v3 and exact PDF, HTML, and structured outputs. It is not agency approval or a compliance certificate.</p></section>`;
  if (!issuanceOnline) {
    const offlineBoundary = document.createElement("p");
    offlineBoundary.className = "code-question-define-stale";
    offlineBoundary.textContent = "Issuance requires an online server transaction. Draft work remains available, but Issue cannot be queued offline.";
    wrap.appendChild(offlineBoundary);
  }
  const issueButton = document.createElement("button");
  issueButton.type = "button";
  issueButton.textContent = context.issue.lastFailure ? "Retry approved issuance" : "Issue Code Memo";
  issueButton.disabled = !issuanceOnline || !context.draft || state !== "approved" || !context.readiness.ready;
  issueButton.addEventListener("click", async () => {
    if (navigator.onLine === false || !serverReachable) {
      void showWebNotice(
        "Code Memo not issued",
        "Issuance requires an online server transaction and cannot be queued offline."
      );
      return;
    }
    const projectID = activeProjectIDForCodeQuestions();
    const requestContext = codeQuestionRequestContext(projectID);
    try {
      assertCodeQuestionRequestContext(requestContext);
      const priorFailed = getIssueForQuestion(context.qid).pendingIssuance.slice().reverse().find((item) =>
        item.draftID === context.draft.id && item.sagaStatus === "failed"
      );
      const idempotencyKey = priorFailed?.idempotencyKey || `issue-${context.qid}-${context.draft.draftHash}`;
      issueButton.disabled = true;
      const begun = await postCodeQuestionForContext(requestContext, "/projects/code-questions/issue/start", {
        projectID, questionID: context.qid,
        draftID: context.draft.id, idempotencyKey
      });
      assertCodeQuestionRequestContext(requestContext);
      const completed = await postCodeQuestionForContext(requestContext, "/projects/code-questions/issue/complete", {
        projectID, questionID: context.qid,
        pendingID: begun.pending.id,
        supersessionReason: "Corrected and reissued through the professional review workflow."
      });
      assertCodeQuestionRequestContext(requestContext);
      await hydrateCodeQuestionState(projectID, context.qid, { force: true, render: false });
      assertCodeQuestionRequestContext(requestContext);
      updateQuestionIssuedVersion(context.qid, completed.issuedRecord.issueVersion);
      refreshCodeMemoPanes(context.qid);
    } catch (error) {
      if (
        codeQuestionRequestContextIsCurrent(requestContext) &&
        evictDeniedCodeQuestionCache(error, projectID, context.qid, { questionScoped: true })
      ) {
        await renderWorkspace();
      }
      issueButton.disabled = false;
      void showWebNotice("Code Memo not issued", error.message);
    }
  });
  wrap.appendChild(issueButton);
  const list = document.createElement("ol");
  list.className = "code-memo-version-list";
  context.issue.issuedRecords.slice().reverse().forEach((record) => {
    const status = issuedRecordStatus(context.issue, record.id);
    const item = document.createElement("li");
    item.className = `is-${status.state}`;
    item.innerHTML = `<strong>Issued Record v${escapeHTML(String(record.issueVersion))} · ${escapeHTML(status.state)}</strong><p>${escapeHTML(record.issuedAt)} · ${escapeHTML(record.manifestHash)}</p>${status.successorID ? `<p>Superseded by ${escapeHTML(status.successorID)} · ${escapeHTML(status.reason)}</p>` : ""}`;
    const downloads = document.createElement("div");
    downloads.className = "code-memo-downloads";
    const safe = `Permitext-Code-Memo-${context.question.displayID || context.qid}-v${record.issueVersion}`.replace(/[^a-z0-9-]+/gi, "-");
    const json = document.createElement("button");
    json.type = "button";
    json.textContent = "Download structured manifest";
    json.addEventListener("click", () => void downloadIssuedCodeMemoFile(record, "structured", `${safe}.json`)
      .catch((error) => showWebNotice("Download failed", error.message)));
    const html = document.createElement("button");
    html.type = "button";
    html.textContent = "Download HTML";
    html.addEventListener("click", () => void downloadIssuedCodeMemoFile(record, "html", `${safe}.html`)
      .catch((error) => showWebNotice("Download failed", error.message)));
    const pdf = document.createElement("button");
    pdf.type = "button";
    pdf.textContent = "Download PDF";
    pdf.addEventListener("click", () => void downloadIssuedCodeMemoFile(record, "pdf", `${safe}.pdf`)
      .catch((error) => showWebNotice("Download failed", error.message)));
    downloads.append(json, html, pdf);
    item.appendChild(downloads);
    if (status.state === "issued") {
      const correction = document.createElement("button");
      correction.type = "button";
      correction.textContent = "Prepare correction";
      correction.addEventListener("click", async () => {
        try {
          await executeCodeQuestionMutation("/projects/code-questions/memos/prepare", {
            projectID: activeProjectIDForCodeQuestions(), questionID: context.qid,
            title: `${context.draft?.title || context.question.title || "Code Memo"} · Correction`,
            narrative: context.draft?.sections?.authoredNarrative || "",
            includeAnalysis: context.draft?.includeAnalysis !== false,
            correctionOfIssuedRecordID: record.id
          }, { commandKind: "codeQuestion.memo.prepare" });
          refreshCodeMemoPanes(context.qid);
        } catch (error) {
          void showWebNotice("Correction not prepared", error.message);
        }
      });
      item.appendChild(correction);
    }
    list.appendChild(item);
  });
  if (!list.childElementCount) {
    const empty = document.createElement("li");
    empty.textContent = "No Issued Records yet.";
    list.appendChild(empty);
  }
  wrap.appendChild(list);
  return wrap;
}

function refreshCodeQuestionAnalysisPanes(questionID) {
  const safeID = String(questionID || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  track?.querySelectorAll?.(`.code-question-panel[data-question-id="${safeID}"]`).forEach((pane) => {
    const role = pane.dataset.cqRole;
    const body = pane.querySelector(".code-question-panel-body");
    if (!body) return;
    if (role === "approved-evidence") body.replaceChildren(renderCodeQuestionApprovedEvidenceBody(null, questionID));
    if (role === "bounded-analysis") body.replaceChildren(renderCodeQuestionBoundedAnalysisBody(null, questionID));
    if (role === "professional-conclusion") body.replaceChildren(renderCodeQuestionProfessionalConclusionBody(null, questionID));
  });
  refreshCodeDecisionPrimaryPanes(questionID);
  saveWorkspaceState();
}

async function toggleLocalCodeQuestionArchive(questionID) {
  const question = questionsForActiveProject().find((item) => item.id === questionID);
  if (!question) return;
  const archived = question.recordState !== "archived";
  const applyOptimistic = () => setQuestionsForActiveProject(questionsForActiveProject().map((item) => {
    if (item.id !== questionID) return item;
    return {
      ...item,
      recordState: archived ? "archived" : "active",
      listLabel: deriveQuestionListLabel({
        ...item,
        recordState: archived ? "archived" : "active"
      })
    };
  }));
  await executeCodeQuestionMutation(
    `/projects/code-questions/${archived ? "archive" : "restore"}`,
    {
      projectID: activeProjectIDForCodeQuestions(), questionID,
      expectedVersion: question.version || getDefinitionForQuestion(questionID)?.expectedVersion
    },
    {
      commandKind: archived ? "codeQuestion.archive" : "codeQuestion.restore",
      expectedVersion: question.version,
      applyOptimistic
    }
  );
  invalidateCodeQuestionListHydration(activeProjectIDForCodeQuestions());
}

function renderCodeQuestionShellChrome() {
  if (!codeQuestionWorkspaceEnabled()) {
    document.querySelector(".code-decision-context-bar")?.remove();
    document.querySelector(".code-question-stage-control")?.remove();
    document.body.classList.remove("code-question-workspace-enabled");
    return;
  }
  document.body.classList.add("code-question-workspace-enabled");
  const project = openProjectDetails()[0] || null;
  if (project) ensureCodeQuestionShellForProject(project);
  document.querySelector(".code-decision-context-bar")?.remove();
  document.querySelector(".code-question-stage-control")?.remove();
  // Preserve the Evidence destination label when the Code Question shell is active.
  if (toggleSavedButton) {
    toggleSavedButton.setAttribute("aria-label", "Evidence");
    toggleSavedButton.title = "Evidence";
  }
}

// Render entry points resolve once ordered shells are mounted. Navigation that
// needs a usable target awaits whenWorkspacePaneReady(id), never unrelated panes.
let workspacePaneHydrator = null;
let workspaceAccessState = null;
const workspacePaneReadyWaiters = new Set();

function workspacePrivatePresentationAllowed() {
  return !workspaceAccessState || workspaceAccessState.gate.allowed;
}

function finishWorkspacePaneReady(shell, ready) {
  for (const waiter of workspacePaneReadyWaiters) {
    if (waiter.shell !== shell) continue;
    workspacePaneReadyWaiters.delete(waiter);
    waiter.resolve(Boolean(ready && waiter.workspaceID === activeWorkspaceID && isCurrentAccountRequest(waiter.identity)));
  }
}

function whenWorkspacePaneReady(paneID) {
  const pane = Array.from(track.querySelectorAll(":scope > .workspace-panel"))
    .find((candidate) => candidate.dataset.paneId === paneID);
  if (!pane) return Promise.resolve(false);
  if (!pane.dataset.workspacePaneLoading) return Promise.resolve(true);
  if (pane.dataset.workspacePaneUnavailable === "true") return Promise.resolve(false);
  return new Promise((resolve) => workspacePaneReadyWaiters.add({
    shell: pane, workspaceID: activeWorkspaceID, identity: captureAccountRequest(), resolve
  }));
}

function workspaceAccessGateForRender() {
  const identity = captureAccountRequest();
  const workspaceID = activeWorkspaceID;
  const key = `${accountRuntimeGeneration}:${workspaceID}`;
  const authority = () => syncedContent?.userID === activeAccount()?.userID
    ? syncedContent?.workspacePresentationAccess || "unavailable" : "unavailable";
  if (workspaceAccessState?.key === key && isCurrentAccountRequest(workspaceAccessState.identity)) {
    const entry = workspaceAccessState;
    if (entry.currentGate.phase !== "pending" && entry.observedAuthority !== authority()) entry.startAttempt(false);
    return entry.gate;
  }
  workspaceAccessState?.gate.dispose();
  const entry = { key, identity, workspaceID, gate: null, currentGate: null, listeners: new Set(), observedAuthority: authority() };
  const current = () => workspaceAccessState === entry && workspaceID === activeWorkspaceID && isCurrentAccountRequest(identity);
  const notify = (listener) => {
    if (!current()) return;
    try { Promise.resolve(listener(entry.gate)).catch(() => {}); } catch {}
  };
  // The facade is stable for this workspace/account/session. Reverification
  // never strands public controls with an obsolete gate captured in a closure.
  entry.gate = {
    get allowed() {
      return current() && entry.currentGate.allowed && ["verified", "permitted-offline"].includes(authority());
    },
    get phase() {
      return entry.currentGate.phase !== "pending" && !entry.gate.allowed ? "unavailable" : entry.currentGate.phase;
    },
    get ready() { return entry.currentGate.ready; },
    subscribe(listener) {
      if (!current()) return () => {};
      entry.listeners.add(listener);
      if (entry.currentGate.phase !== "pending") notify(listener);
      return () => entry.listeners.delete(listener);
    },
    retry() {
      if (!current() || entry.currentGate.phase === "pending") return false;
      entry.startAttempt(true);
      void renderUtilityWorkspace({ skipDeletedProjectCleanup: true, persist: false }).catch(() => {});
      return true;
    },
    dispose() { entry.listeners.clear(); entry.currentGate?.dispose(); }
  };
  entry.startAttempt = (force) => {
    entry.currentGate?.dispose();
    entry.observedAuthority = authority();
    const attempt = createWorkspaceAccessGate({
      isCurrent: current,
      async verify() {
        let result = await (force ? loadSyncedContent({ force: true }) : ensureSyncedContentForRender());
        // A forced foreground pull can supersede the request we originally
        // awaited. Its early return is not a completed authorization result.
        while (current() && syncLoadPromise && isCurrentAccountRequest(syncLoadPromise.accountIdentity)) {
          const latest = syncLoadPromise;
          result = await latest;
        }
        if (!current()) return "unavailable";
        entry.observedAuthority = authority();
        if (!activeAccount()?.userID || result?.userID !== activeAccount().userID) return "unavailable";
        const phase = result?.workspacePresentationAccess;
        if (!["verified", "permitted-offline"].includes(phase)) return "unavailable";
        reconcileProjectWorkspaces();
        if (!current()) return "unavailable";
        (state.utilityInstances || []).filter((item) => item.key === "saved").forEach(scopeSavedInstanceToWorkspace);
        closeDeletedProjectDetails();
        enforceReaderPlanLimit();
        return phase;
      }
    });
    entry.currentGate = attempt;
    void attempt.ready.then(() => {
      if (entry.currentGate !== attempt || workspaceAccessState !== entry || !isCurrentAccountRequest(identity)) return;
      for (const listener of entry.listeners) notify(listener);
      // Recompute desired private descriptors only after completed verification.
      void renderUtilityWorkspace({ skipDeletedProjectCleanup: true, persist: false }).catch((error) => {
        console.warn("Workspace presentation could not refresh.", error);
      });
    });
  };
  workspaceAccessState = entry;
  entry.startAttempt(false);
  return entry.gate;
}

function maskUnverifiedWorkspacePane(panel) {
  panel.querySelectorAll(".inline-bookmark-toggle, .inline-research-toggle, .search-result-save").forEach((control) => {
    control.hidden = true;
    control.disabled = true;
    control.classList.remove("is-saved");
    control.removeAttribute("title");
    control.removeAttribute("aria-label");
  });
  panel.querySelectorAll(".reader-section-project-context, .search-recent-popover").forEach((host) => {
    clear(host);
    host.hidden = true;
  });
  if (panel.classList.contains("search-panel")) {
    const instance = (state.utilityInstances || []).find((item) => paneIDForUtilityInstance(item) === panel.dataset.paneId);
    if (instance && !String(instance.query || "").trim()) void renderSearchHistory(panel, instance);
  }
}

function workspacePaneRenderContext(renderGeneration) {
  return {
    key: `${accountRuntimeGeneration}:${activeWorkspaceID}`,
    workspaceID: activeWorkspaceID,
    identity: captureAccountRequest(),
    generation: renderGeneration
  };
}

function workspacePaneContextIsCurrent(context) {
  return context.generation === workspaceRenderGeneration &&
    context.workspaceID === activeWorkspaceID && isCurrentAccountRequest(context.identity);
}

function disposeUnpublishedWorkspacePane(pane) {
  if (!pane || pane.isConnected) return;
  cancelSearchPanelRequest(pane);
  disposeWorkspaceNodeAccess(pane);
  for (const mounts of [notebookMounts, reportDraftMounts, workboardMounts, projectInformationMounts]) {
    for (const [id, mounted] of mounts) {
      // A late result must never dispose a newer controller with the same ID.
      if (mounted.panel !== pane) continue;
      if (mounts === workboardMounts) disposeProjectWorkboardMount(mounted);
      else mounted.dispose?.();
      mounts.delete(id);
    }
  }
  if (pane.classList.contains("reader-panel")) cancelReaderPanelRequests(pane);
}

function createWorkspacePaneLoadingShell(descriptor) {
  const panel = document.createElement("article");
  panel.className = `workspace-panel ${descriptor.ownerClass || ""}`;
  panel.dataset.paneId = descriptor.id;
  panel.dataset.workspacePaneLoading = "true";
  panel.__workspaceAccessGate = descriptor.accessGate || null;
  panel.dataset.workspacePaneIdentity = descriptor.contentIdentity;
  panel.dataset.workspacePaneAccessIdentity = descriptor.accessIdentity;
  if (descriptor.projectID) panel.dataset.projectId = descriptor.projectID;
  // Mount cleanup uses the same ownership markers as the eventual editor.
  if (descriptor.ownerClass === "workboard-panel") {
    const root = document.createElement("div");
    root.className = "workboard-root";
    root.dataset.projectId = descriptor.projectID;
    root.hidden = true;
    panel.append(root);
  }
  const isReport = descriptor.ownerClass === "report-draft-panel";
  const isSectionDetail = (descriptor.ownerClass || "").includes("section-detail-panel");
  const header = isReport ? createReportPaneHeader(() => descriptor.close()) : document.createElement("header");
  if (!isReport) {
    if (isSectionDetail) header.className = "panel-header section-detail-chrome";
    const heading = document.createElement("h2");
    heading.className = "eyebrow panel-kind";
    heading.textContent = descriptor.label;
    const close = document.createElement("button");
    close.type = "button";
    close.className = isSectionDetail ? "section-detail-icon section-detail-close" : "icon-button utility-close";
    close.setAttribute("aria-label", `Close ${descriptor.label}`);
    close.innerHTML = circleXIconSVG();
    close.addEventListener("click", () => { void descriptor.close(); });
    header.append(heading, close);
  }
  const status = document.createElement("p");
  status.className = `${isReport ? "report-draft-status" : isSectionDetail ? "section-detail-content" : "empty-state"} workspace-pane-load-status`;
  status.setAttribute("role", "status");
  status.textContent = `Loading ${descriptor.label}…`;
  const retry = document.createElement("button");
  retry.type = "button";
  retry.className = "workspace-pane-retry";
  retry.textContent = "Retry";
  retry.hidden = true;
  retry.addEventListener("click", () => {
    if (descriptor.accessGate && !descriptor.accessGate.allowed) {
      if (!descriptor.accessGate.retry()) return;
    } else if (!workspacePaneHydrator?.retry(descriptor.id)) return;
    retry.hidden = true;
    panel.dataset.workspacePaneUnavailable = "false";
    panel.setAttribute("aria-busy", "true");
    status.textContent = `Loading ${descriptor.label}…`;
  });
  panel.setAttribute("aria-busy", "true");
  if (isReport) {
    const shell = document.createElement("div");
    shell.className = "report-draft-shell";
    shell.append(status, retry);
    panel.append(header, shell);
  } else {
    panel.append(header, status, retry);
  }
  applyPaneWeight(panel, descriptor.id);
  return panel;
}

function getWorkspacePaneHydrator() {
  if (workspacePaneHydrator) return workspacePaneHydrator;
  workspacePaneHydrator = createWorkspacePaneHydrator({
    isContextCurrent: workspacePaneContextIsCurrent,
    onReady(job, pane) {
      const shell = job.placeholder;
      if (!shell?.isConnected || shell.parentNode !== track || !pane) {
        disposeUnpublishedWorkspacePane(pane);
        return;
      }
      const scrollLeft = track.scrollLeft;
      pane.dataset.workspacePaneIdentity ||= job.descriptor.contentIdentity;
      pane.dataset.workspacePaneAccessIdentity = job.descriptor.accessIdentity;
      pane.classList.toggle("is-pinned", job.id === activePinnedPaneID());
      applyPaneWeight(pane, job.id);
      ensureWorkspacePanelAccessibleName(pane);
      preparePaneCollapse(pane);
      bindPaneDragging([pane]);
      pane.classList.toggle("is-workflow-hidden", !workflowPaneIsVisible(job.id));
      shell.replaceWith(pane);
      // The new header is prepared above; retained editors and menus need no rebuild.
      refreshColumnGroupPresentation({ preparePanels: false });
      if (job.id === activePinnedPaneID()) refreshPinnedPaneDivider();
      updateCollapsedPaneDividers();
      // Only the newly mounted Reader gets restoration listeners and frames.
      if (pane.classList.contains("reader-panel")) {
        bindReaderScrollIndicator(pane);
        updateReaderScrollIndicator(pane);
        pane.querySelectorAll("select").forEach(enhanceSelect);
      }
      if (job.descriptor.scrollPosition) {
        restoreReaderScrollPositions(new Map([[job.id, job.descriptor.scrollPosition]]));
      }
      if (job.descriptor.scrollTop != null) pane.scrollTop = job.descriptor.scrollTop;
      track.scrollLeft = scrollLeft;
      notifyWorkspaceLayoutChange();
      // Hydration can change column widths and cancel the shell's smooth scroll.
      // Finish the explicit open action against the final column geometry.
      if (pendingWorkspacePaneRevealID === job.id) {
        scrollPaneIntoView(job.id, "auto");
      }
      finishWorkspacePaneReady(shell, true);
    },
    onError(job) {
      const shell = job.placeholder;
      if (!shell?.isConnected) return;
      shell.setAttribute("aria-busy", "false");
      shell.dataset.workspacePaneUnavailable = "true";
      shell.querySelector(".workspace-pane-load-status").textContent = `Could not load ${job.descriptor.label}. Retry when ready.`;
      shell.querySelector(".workspace-pane-retry").hidden = false;
      finishWorkspacePaneReady(shell, false);
    },
    onDiscard(_job, pane) { disposeUnpublishedWorkspacePane(pane); }
  });
  return workspacePaneHydrator;
}

function restoreAssistantConversationOwners() {
  // Older layouts kept comparison chats as standalone panes. Give each one an
  // Assistant owner so its fixed history rail follows every move and resize.
  state.utilityInstances ||= [];
  for (const conversationID of supplementalResearchConversationIDs) {
    if (researchConversationPaneIsOpen() && conversationID === state.researchConversationID) continue;
    if (state.utilityInstances.some(item => item.key === "analysis" && item.conversationID === conversationID)) continue;
    const oldID = `research:conversation:${conversationID}`;
    const instance = newUtilityInstance("analysis", { id: `conversation-${conversationID}`, conversationID });
    state.utilityInstances.push(instance);
    const nextID = paneIDForUtilityInstance(instance);
    state.paneOrder = (state.paneOrder || []).map(id => id === oldID ? nextID : id);
    if (state.paneWeights?.[oldID]) { state.paneWeights[nextID] = state.paneWeights[oldID]; delete state.paneWeights[oldID]; }
    state.collapsedPaneIDs = (state.collapsedPaneIDs || []).map(id => id === oldID ? nextID : id);
    if (state.pinnedPaneID === oldID) state.pinnedPaneID = nextID;
    if (state.workflowMembership?.[oldID]) { state.workflowMembership[nextID] = state.workflowMembership[oldID]; delete state.workflowMembership[oldID]; }
    for (const group of state.columnGroups || []) {
      group.paneIDs = group.paneIDs.map(id => id === oldID ? nextID : id);
      if (group.columns?.[oldID]) { group.columns[nextID] = { kind: "utility", value: instance }; delete group.columns[oldID]; }
    }
  }
}

function workspacePaneDescriptors(options = {}) {
  restoreAssistantConversationOwners();
  if (workspaceColumnsRequireProject()) return [];
  const foundationScope = createInitialProjectFoundationScope();
  const descriptors = [];
  const add = (id, label, load, close, extra = {}) => descriptors.push({
    id, label, close, identity: id, publicContent: false, accessGate: options.accessGate || null, ...extra,
    async load(signal) {
      this.foundationStarted = true;
      if (this.foundationScope) signal.addEventListener("abort", () => this.foundationScope.release(id), { once: true });
      let pane;
      try { pane = await load(signal); }
      catch (error) { this.foundationScope?.release(id); throw error; }
      finally { if (this.foundationScope && !this.deferredFoundationRelease) this.foundationScope.release(id); }
      if (!pane && this.foundationScope) this.foundationScope.release(id);
      if (!pane) throw new Error("Pane is unavailable");
      return pane;
    }
  });
  const closeAndRender = (change) => async () => {
    change();
    saveWorkspaceState();
    await transitionWorkspace("utility");
  };
  const addWorkboard = (project, close) => add(paneIDForProjectWorkboard(project), "Workboard", () => renderProjectWorkboard(project), close,
    { ownerClass: "workboard-panel", projectID: workboardProjectID(project), accessCapabilities: ["projects"] });
  if (detachedProjectWindow && detachedProject) {
    addWorkboard(detachedProject, () => window.close());
    foundationScope.release("");
    return descriptors;
  }
  if (genericWorkboardIsOpen()) addWorkboard(genericWorkboardIdentity, closeGenericWorkboard);
  for (const project of openProjectDetails()) {
    const projectID = projectDetailKey(project);
    if (projectHasOpenNotebook(project)) {
      foundationScope.register(paneIDForProjectNotebook(project));
      add(paneIDForProjectNotebook(project), "Notes", () => renderProjectNotebook(project, { foundationScope }),
        () => closeProjectNotebook(project), { foundationScope, ownerClass: "notebook-panel", projectID, accessCapabilities: ["notebook"] });
    }
    // Report owns a separate screen; never insert it into the column track.
    if (releaseSurfaceVisibility.coordination && projectHasOpenCoordination(project)) {
      add(paneIDForProjectCoordination(project), "Coordination", () => renderProjectCoordination(project), () => closeProjectCoordination(project));
      const thread = openCoordinationThreadForProject(project);
      if (thread) add(paneIDForProjectCoordinationThread(project, thread.threadID), "Coordination thread",
        () => renderProjectCoordinationThread(project, thread.threadID), () => closeProjectCoordinationThread(project));
    }
  }
  for (const id of openCodeQuestionPaneIDs()) {
    add(id, "Code Question", () => renderCodeQuestionPane(id), closeAndRender(() => {
      setCodeQuestionWorkspaceState(closeCodeQuestionPane(codeQuestionWorkspaceState(), id, activeProjectIDForCodeQuestions()), { syncDeepLink: true });
    }), { identity: JSON.stringify([id, codeQuestionWorkspaceState(), [...codeQuestionIndexArchiveModeProjectIDs].sort()]) });
  }
  if (state.utilities.archive) add("utility:archive", "Archive", renderArchive, closeArchiveColumn);
  for (const instance of state.utilityInstances || []) {
    const savedFoundationScope = instance.key === "saved" && hasCapability("saved-work") ? foundationScope : null;
    savedFoundationScope?.register(paneIDForUtilityInstance(instance));
    if (instance.key !== "sdc") add(paneIDForUtilityInstance(instance), ({ search: "Search", saved: "Evidence", analysis: "Assistant" }[instance.key] || "Column"),
      (signal) => renderUtilityInstance(instance, { accessGate: options.accessGate, foundationScope: savedFoundationScope, signal }), () => closeUtilityInstance(instance),
      { foundationScope: savedFoundationScope, deferredFoundationRelease: Boolean(savedFoundationScope), publicContent: instance.key === "search", identity: instance.key === "analysis"
        ? researchAssistantContentIdentity(instance) : JSON.stringify([instance.id, instance.key, instance.projectID || "", instance.conversationID || ""]) });
    if (instance.key === "search" || instance.key === "sdc") {
      const detail = sectionDetailsBySearch()[instance.id];
      if (detail) add(paneIDForSectionDetail(instance.id), instance.key === "sdc" ? "Evidence detail" : "Section detail", () => renderSectionDetail(instance.id, detail),
        closeAndRender(() => removeSectionDetail(instance.id)), {
          ownerClass: `section-detail-panel${instance.key === "sdc" ? " is-saved-evidence-detail" : ""}`,
          identity: JSON.stringify(detail)
        });
    }
  }
  if (state.utilities.analysis || researchConversationPaneIsOpen()) add("utility:analysis", "Assistant", () => renderResearch("utility:analysis"), closeResearchWorkspace,
    { identity: researchAssistantContentIdentity() });
  for (const id of supplementalResearchConversationIDs) {
    if ((state.utilityInstances || []).some((item) => item.conversationID === id)) continue;
    add(paneIDForResearchConversation(id), "Assistant", () => renderResearchConversation(id, { supplemental: true }), () => closeResearchConversation(id));
  }
  if (state.utilities.settings) add("utility:settings", "Settings", renderSettings, closeAndRender(() => { state.utilities.settings = false; }));
  for (const reader of state.readers) {
    const id = paneIDForReader(reader);
    add(id, "Reader", (signal) => renderReader(reader, { scrollPosition: options.readerScrollPositions?.get(id), accessGate: options.accessGate, signal }), closeAndRender(() => {
      state.readers = state.readers.filter((item) => item.id !== reader.id);
      state.readers.forEach((item) => { if (item.referenceSourceReaderID === reader.id) item.referenceSourceReaderID = ""; });
      Object.keys(searchLinkedReadersBySearch()).forEach((searchID) => {
        if (state.searchLinkedReaders[searchID] === reader.id) delete state.searchLinkedReaders[searchID];
      });
    }), {
      publicContent: true,
      identity: workspaceReaderContentIdentity(reader),
      scrollPosition: options.readerScrollPositions?.get(id)
    });
  }
  foundationScope.release("");
  return descriptors;
}

async function mountWorkspacePanesIndependently(context, options = {}) {
  if (!workspacePaneContextIsCurrent(context)) return false;
  const current = new Map(Array.from(track.querySelectorAll(":scope > .workspace-panel")).map((pane) => [pane.dataset.paneId, pane]));
  const refresh = new Set(options.refreshPaneIDs || []);
  const descriptors = workspacePaneDescriptors(options);
  // Access changes invalidate locked surfaces and capability-dependent controls.
  // Do not key this to quota counters or whole entitlement payloads: ordinary
  // usage updates must not rebuild a healthy editor.
  const defaultAccessCapabilities = ["projects", "saved-work", "notebook", "professional-exports", "research", "code-question-workspace"];
  for (const descriptor of descriptors) {
    // Stateful editor constructors must depend only on their own access gate.
    // An unrelated add-on change must not dispose a dirty document controller.
    const accessIdentity = JSON.stringify((descriptor.accessCapabilities || defaultAccessCapabilities)
      .map((capability) => [capability, hasCapability(capability)]));
    descriptor.contentIdentity = descriptor.identity;
    // Verification unlocks adornments in place. Public code DOM does not depend
    // on private capability flags; private constructors still do.
    descriptor.accessIdentity = descriptor.publicContent ? "public" : accessIdentity;
    descriptor.identity = JSON.stringify([descriptor.contentIdentity, descriptor.accessIdentity]);
    const pane = current.get(descriptor.id);
    const sameIdentity = (!pane?.dataset.workspacePaneIdentity || pane.dataset.workspacePaneIdentity === descriptor.contentIdentity) &&
      (!pane?.dataset.workspacePaneAccessIdentity || pane.dataset.workspacePaneAccessIdentity === descriptor.accessIdentity);
    // Editor identity is its account/workspace/project, not synchronized document
    // contents. Existing controllers own dirty drafts and targeted refreshes.
    const privateBlocked = !descriptor.publicContent && options.accessGate && !options.accessGate.allowed;
    const reusable = pane && !pane.classList.contains("workspace-switch-placeholder") &&
      !(privateBlocked && !pane.dataset.workspacePaneLoading) && !refresh.has(descriptor.id) && sameIdentity;
    if (reusable && !pane.dataset.workspacePaneLoading) {
      descriptor.foundationScope?.release(descriptor.id);
      descriptor.existing = pane;
      if (descriptor.publicContent && options.accessGate && !options.accessGate.allowed) maskUnverifiedWorkspacePane(pane);
    }
    descriptor.placeholder = reusable ? pane : createWorkspacePaneLoadingShell(descriptor);
    if (refresh.has(descriptor.id) && descriptor.id === "utility:settings") descriptor.scrollTop = pane?.scrollTop;
    applyPaneWeight(descriptor.placeholder, descriptor.id);
  }
  appendPaneSequence(descriptors.map((descriptor) => descriptor.placeholder));
  const hydrator = getWorkspacePaneHydrator();
  for (const id of refresh) hydrator.cancel(id);
  // reconcile schedules loads on microtasks, after every desired shell is mounted.
  const runnable = descriptors.filter((descriptor) => descriptor.publicContent || !options.accessGate || options.accessGate.allowed);
  hydrator.reconcile(runnable, context);
  // Retained jobs do not invoke this render's descriptor loader. Release their
  // unused leases after newly scheduled loader microtasks have started.
  void Promise.resolve().then(() => {
    for (const descriptor of runnable) {
      if (!descriptor.foundationStarted) descriptor.foundationScope?.release(descriptor.id);
    }
  });
  for (const descriptor of descriptors) {
    if (runnable.includes(descriptor)) continue;
    descriptor.foundationScope?.release(descriptor.id);
    const shell = descriptor.placeholder;
    const unavailable = options.accessGate.phase !== "pending";
    shell.dataset.workspacePaneUnavailable = String(unavailable);
    shell.setAttribute("aria-busy", String(!unavailable));
    const status = shell.querySelector(".workspace-pane-load-status");
    if (status) status.textContent = unavailable
      ? "Private workspace content is unavailable. Check your account or connection."
      : "Checking workspace access…";
    const retry = shell.querySelector(".workspace-pane-retry");
    if (retry) retry.hidden = !unavailable;
    if (unavailable) finishWorkspacePaneReady(shell, false);
  }
  for (const waiter of workspacePaneReadyWaiters) {
    if (!waiter.shell.isConnected || waiter.workspaceID !== activeWorkspaceID || !isCurrentAccountRequest(waiter.identity)) {
      finishWorkspacePaneReady(waiter.shell, false);
    }
  }
  if (!options.shellReady) await hydrator.settled();
  return workspacePaneContextIsCurrent(context);
}

async function renderWorkspace(options = {}) {
  restoreResearchWorkspaceState();
  const renderGeneration = ++workspaceRenderGeneration;
  let accessGate = workspaceAccessGateForRender();
  const readerScrollPositions = suppressReaderScrollRestore ? new Map() : captureReaderScrollPositions();
  if (accessGate.allowed) {
    reconcileProjectWorkspaces();
    accessGate = workspaceAccessGateForRender();
    enforceProjectRequiredWorkspace();
    (state.utilityInstances || []).filter((item) => item.key === "saved").forEach(scopeSavedInstanceToWorkspace);
    enforceReaderPlanLimit();
    closeDeletedProjectDetails();
    renderCodeQuestionShellChrome();
  }
  const context = workspacePaneRenderContext(renderGeneration);
  updateReaderPlanControls();
  renderWorkspaceTabs();
  normalizePaneWeights(activePaneIDs());
  setUtilityButtonStates();
  if (state.utilities.settings) state.utilities.settings = false;
  if (!await mountWorkspacePanesIndependently(context, { ...options, readerScrollPositions, accessGate, shellReady: true })) return false;
  if (options.persist !== false) saveWorkspaceState();
  return true;
}

async function renderUtilityWorkspace(options = {}) {
  restoreResearchWorkspaceState();
  const renderGeneration = ++workspaceRenderGeneration;
  let accessGate = workspaceAccessGateForRender();
  if (accessGate.allowed) {
    if (!options.skipDeletedProjectCleanup || workspaceColumnsRequireProject()) reconcileProjectWorkspaces();
    accessGate = workspaceAccessGateForRender();
    enforceProjectRequiredWorkspace();
    enforceReaderPlanLimit();
    if (!options.skipDeletedProjectCleanup) closeDeletedProjectDetails();
    renderCodeQuestionShellChrome();
  }
  const context = workspacePaneRenderContext(renderGeneration);
  updateReaderPlanControls();
  renderWorkspaceTabs();
  normalizePaneWeights(activePaneIDs());
  setUtilityButtonStates();
  if (!await mountWorkspacePanesIndependently(context, { ...options, accessGate, shellReady: true })) return false;
  if (options.persist !== false) {
    if (options.deferStateSave) scheduleWorkspaceStateSaveAfterPaint();
    else saveWorkspaceState();
  }
  if (accessGate.allowed) startProjectArtifactCheckpointLoop();
  return true;
}

async function transitionWorkspace(mode = "default", options = {}) {
  if (mode === "utility") {
    await renderUtilityWorkspace(options);
    return;
  }
  await renderWorkspace();
}

async function toggleUtilityPane(key) {
  if (key === "settings") { toggleAccountDialog(); return; }
  if (workspaceColumnsRequireProject()) return;
  if (key === "analysis" && state.utilities.analysis) {
    await closeResearchWorkspace();
    return;
  }
  if (repeatableUtilityKeys.has(key)) {
    const instance = newUtilityInstance(key);
    const paneID = paneIDForUtilityInstance(instance);
    state.utilityInstances = [...(state.utilityInstances || []), instance];
    state.utilities[key] = false;
    state.paneWeights[paneID] = defaultPaneWidthForID(paneID);
    appendPaneIfMissing(paneID);
    if (key === "search") {
      await transitionWorkspace("utility", { deferStateSave: true });
    } else {
      saveWorkspaceState();
      await transitionWorkspace("utility");
    }
    scrollPaneIntoView(paneID);
    return;
  }

  const paneID = `utility:${key}`;
  const willOpen = !state.utilities[key];
  state.utilities[key] = willOpen;
  if (willOpen) {
    state.paneWeights[paneID] = defaultPaneWidthForID(paneID);
    if (key === "projects") {
      restoreProjectsStackOrder();
    } else if (key === "settings") {
      movePaneToFront(paneID);
    } else if (key === "archive") {
      placeArchiveAfterProjectsStack();
    } else {
      appendPaneIfMissing(paneID);
    }
  } else if (key === "projects") {
    delete state.paneWeights[paneID];
    openProjectDetails().forEach((detail) => {
      delete state.paneWeights[paneIDForProjectDetail(detail)];
      delete state.paneWeights[paneIDForProjectWorkboard(detail)];
      delete state.paneWeights[paneIDForProjectNotebook(detail)];
      delete state.paneWeights[paneIDForProjectReportDraft(detail)];
      delete state.paneWeights[paneIDForProjectCoordination(detail)];
      const coordinationThread = openCoordinationThreadForProject(detail);
      if (coordinationThread) {
        delete state.paneWeights[paneIDForProjectCoordinationThread(detail, coordinationThread.threadID)];
      }
    });
    delete state.paneWeights["utility:archive"];
    state.paneOrder = (state.paneOrder || []).filter((id) =>
      id !== paneID &&
      !isProjectDetailPaneID(id) &&
      !isProjectNotebookPaneID(id) &&
      !isProjectReportDraftPaneID(id) &&
      !isProjectCoordinationPaneID(id) &&
      !isProjectCoordinationThreadPaneID(id) &&
      (!isProjectWorkboardPaneID(id) || id === paneIDForProjectWorkboard(genericWorkboardIdentity)) &&
      id !== "utility:archive"
    );
  } else if (key === "archive") {
    state.paneOrder = (state.paneOrder || []).filter((id) => id !== "utility:archive");
  } else if (key === "analysis" && !willOpen) {
    researchOpenGeneration += 1;
    researchConversationPaneOpened = false;
    state.researchConversationID = "";
    activeResearchConversation = null;
    state.paneOrder = (state.paneOrder || []).filter((id) => id !== paneID && !id.startsWith("research:conversation:"));
    Object.keys(state.paneWeights).filter((id) => id.startsWith("research:conversation:")).forEach((id) => delete state.paneWeights[id]);
  }
  if (key === "archive") syncSavedArchiveButtonStates();
  saveWorkspaceState();
  await transitionWorkspace("utility");
  if (willOpen) {
    scrollPaneIntoView(paneID);
  }
}

async function resetVisibleColumnWidths() {
  if (reportScreen?.isOpen()) {
    const panel = document.querySelector(".report-workspace-view:not([hidden]) .report-draft-panel");
    if (panel?.querySelector(".report-workspace-columns")) resetReportColumnWidths(panel, syncReferenceReaderLayout);
    return;
  }
  const paneIDs = new Set(activePaneIDs().filter(workflowPaneIsVisible));
  for (const group of state.columnGroups || []) {
    for (const [id, column] of Object.entries(group.columns || {})) if (paneIDs.has(id)) column.width = defaultPaneWidthForID(id);
  }
  track.querySelectorAll(":scope > .workspace-panel:not(.is-workflow-hidden)").forEach(panel => {
    panel._collapseAnimation?.cancel(); panel._restoreCollapseChildWidths?.();
  });
  const currentLeft = track.scrollLeft;
  for (const id of paneIDs) state.paneWeights[id] = defaultPaneWidthForID(id);
  saveWorkspaceState();
  await transitionWorkspace("utility");
  requestAnimationFrame(() => { track.scrollLeft = Math.min(currentLeft, Math.max(0, track.scrollWidth - track.clientWidth)); });
}

async function closeAllColumns() {
  // Each surface retains its own unsaved-edit guard. Never close a retained
  // column in the other working view as a side effect of this view's action.
  const workspaceID = activeWorkspaceID;
  const identity = captureAccountRequest();
  const allDescriptors = workspacePaneDescriptors();
  allDescriptors.forEach(item => item.foundationScope?.release(item.id));
  const descriptors = allDescriptors.filter(item => workflowPaneIsVisible(item.id)).reverse();
  for (const descriptor of descriptors) {
    if (workspaceID !== activeWorkspaceID || !isCurrentAccountRequest(identity)) return false;
    if (await descriptor.close() === false) return false;
  }
  return true;
}

async function focusUtility(key, selector = "") {
  if (key === "settings") { if (!document.querySelector(".account-dialog")) toggleAccountDialog(); return; }
  if (workspaceColumnsRequireProject()) return;
  let paneID = "";
  if (repeatableUtilityKeys.has(key)) {
    let instance = (state.utilityInstances || []).find((item) => item.key === key &&
      (key !== "saved" || !workspaceProject() || !item.unassignedInbox));
    if (!instance) {
      await toggleUtilityPane(key);
      instance = (state.utilityInstances || []).find((item) => item.key === key);
    }
    paneID = instance ? paneIDForUtilityInstance(instance) : "";
  } else {
    if (!state.utilities[key]) await toggleUtilityPane(key);
    paneID = `utility:${key}`;
  }
  if (!paneID) return;
  scrollPaneIntoView(paneID);
  if (!await whenWorkspacePaneReady(paneID)) return;
  if (key === "analysis") startProjectArtifactCheckpointLoop({ immediate: true });
  requestAnimationFrame(() => {
    const pane = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
    const focusTarget = selector ? pane?.querySelector(selector) : pane?.querySelector("button, input, select, textarea");
    focusTarget?.focus({ preventScroll: true });
  });
}

async function openNewSearchColumn() {
  await toggleUtilityPane("search");
  const instance = (state.utilityInstances || []).filter((item) => item.key === "search").at(-1);
  if (!instance) return;
  const paneID = paneIDForUtilityInstance(instance);
  scrollPaneIntoView(paneID);
  rememberUtilityColumn(paneID);
}

const recentUtilityColumns = new Map();
function rememberUtilityColumn(paneID) {
  const key = (state.utilityInstances || []).find((item) => paneIDForUtilityInstance(item) === paneID)?.key;
  if (key === "search" || key === "analysis") {
    recentUtilityColumns.set(`${activeAccount()?.userID || "public"}:${activeWorkspaceID}:${key}`, paneID);
  }
}

async function openNewResearchColumn() {
  if (workspaceColumnsRequireProject()) return;
  const instance = newUtilityInstance("analysis");
  state.utilityInstances.push(instance);
  const paneID = paneIDForUtilityInstance(instance);
  appendPaneIfMissing(paneID);
  saveWorkspaceState();
  await transitionWorkspace("utility");
  rememberUtilityColumn(paneID);
  scrollPaneIntoView(paneID);
}

async function focusRecentUtilityColumn(key) {
  if (workspaceColumnsRequireProject()) return;
  const instances = (state.utilityInstances || []).filter((item) => item.key === key);
  const recent = recentUtilityColumns.get(`${activeAccount()?.userID || "public"}:${activeWorkspaceID}:${key}`);
  const instance = instances.find((item) => paneIDForUtilityInstance(item) === recent) || instances.at(-1);
  if (!instance) {
    if (key === "analysis" && state.utilities.analysis) return focusUtility(key);
    return key === "saved" ? focusUtility("saved") : key === "search" ? openNewSearchColumn() : openNewResearchColumn();
  }
  const paneID = paneIDForUtilityInstance(instance);
  rememberUtilityColumn(paneID);
  if (!await whenWorkspacePaneReady(paneID)) return;
  const panel = track.querySelector(`.workspace-panel[data-pane-id="${CSS.escape(paneID)}"]`);
  if (!panel) return;
  const group = columnGroupForPane(paneID);
  if (group?.collapsed) setColumnGroupCollapsed(group, false);
  if (paneIsCollapsed(paneID)) setPaneCollapsed(panel, false);
  scrollPaneIntoView(paneID);
  panel.querySelector('.search-input, .research-question-input, .research-conversation-open, button')?.focus({ preventScroll: true });
}

async function toggleProjectsColumns() {
  const instances = (state.utilityInstances || []).filter((item) => item.key === "saved");
  if (!instances.length) {
    await focusUtility("saved");
    return;
  }

  const projectHostPaneID = state.projectHostPaneID;
  const closeOrder = [...instances].sort((left, right) =>
    Number(paneIDForUtilityInstance(left) === projectHostPaneID) -
    Number(paneIDForUtilityInstance(right) === projectHostPaneID)
  );
  for (const instance of closeOrder) {
    if (!(await closeUtilityInstance(instance))) return;
  }
}

function workspaceCommandDefinitions() {
  if (workspaceColumnsRequireProject()) return [
    { label: "Create Project", hint: "Start a project workspace", run: () => createNewWorkspace() },
    { label: "Open Account", hint: "Plan, account, sync, and privacy", run: () => focusUtility("settings") }
  ];
  return [
    { label: "Open Search", hint: "Find sections across all codes", run: () => openNewSearchColumn() },
    { label: "Open Research", hint: "Ask a cited building-code question", run: () => focusUtility("analysis", ".research-question-input") },
    ...(isProAccount() || state.readers.length < 2
      ? [{ label: "New Reader", hint: "Open another code column", run: () => readerToolbarButtonForCurrentView().click() }]
      : []),
    { label: "Open Evidence and Projects", hint: "Review saved work and organize projects", run: () => focusUtility("saved") },
    { label: "Open Account", hint: "Plan, account, sync, and privacy", run: () => focusUtility("settings") },
    { label: "Reset Layout", hint: "Restore default panel widths", run: () => resetVisibleColumnWidths() },
    ...(defaultActivePaneIDs().length
      ? [{ label: "Close All", hint: "Close columns in this working view", run: () => closeAllColumns() }]
      : [])
  ];
}

function openWorkspaceCommandPalette() {
  document.querySelector(".command-palette-backdrop")?.remove();
  const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const commands = workspaceCommandDefinitions();
  const backdrop = document.createElement("div");
  backdrop.className = "command-palette-backdrop";
  const dialog = document.createElement("section");
  dialog.className = "command-palette";
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-modal", "true");
  dialog.setAttribute("aria-label", "Workspace commands");
  const input = document.createElement("input");
  input.type = "search";
  input.className = "command-palette-input";
  input.placeholder = "Type a command";
  input.setAttribute("aria-label", "Filter workspace commands");
  const list = document.createElement("div");
  list.className = "command-palette-list";
  let visibleCommands = commands;
  let selectedIndex = 0;

  const closePalette = ({ restoreFocus = true } = {}) => {
    backdrop.remove();
    if (restoreFocus && previousFocus?.isConnected) previousFocus.focus({ preventScroll: true });
  };
  const executeCommand = (command) => {
    closePalette({ restoreFocus: false });
    void Promise.resolve(command.run());
  };
  const renderCommands = () => {
    clear(list);
    const needle = input.value.trim().toLowerCase();
    visibleCommands = commands.filter((command) => `${command.label} ${command.hint}`.toLowerCase().includes(needle));
    selectedIndex = Math.min(selectedIndex, Math.max(0, visibleCommands.length - 1));
    visibleCommands.forEach((command, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "command-palette-item";
      button.classList.toggle("is-selected", index === selectedIndex);
      const label = document.createElement("strong");
      label.textContent = command.label;
      const hint = document.createElement("span");
      hint.textContent = command.hint;
      button.append(label, hint);
      button.addEventListener("click", () => executeCommand(command));
      list.append(button);
    });
  };
  input.addEventListener("input", () => {
    selectedIndex = 0;
    renderCommands();
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      closePalette();
    } else if (event.key === "ArrowDown" && visibleCommands.length) {
      event.preventDefault();
      selectedIndex = (selectedIndex + 1) % visibleCommands.length;
      renderCommands();
    } else if (event.key === "ArrowUp" && visibleCommands.length) {
      event.preventDefault();
      selectedIndex = (selectedIndex - 1 + visibleCommands.length) % visibleCommands.length;
      renderCommands();
    } else if (event.key === "Enter" && visibleCommands[selectedIndex]) {
      event.preventDefault();
      executeCommand(visibleCommands[selectedIndex]);
    }
  });
  backdrop.addEventListener("mousedown", (event) => {
    if (event.target === backdrop) closePalette();
  });
  backdrop.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closePalette();
      return;
    }
    trapWebModalFocus(dialog, event);
  });
  dialog.append(input, list);
  backdrop.append(dialog);
  document.body.append(backdrop);
  renderCommands();
  input.focus();
}

function bindWorkspaceKeyboardNavigation() {
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      if (workspaceContextMenu) {
        event.preventDefault();
        closeWorkspaceContextMenu();
        workspaceActionsButton?.focus();
        return;
      }
      const openTrust = document.querySelector(".reader-trust[open]");
      if (openTrust) {
        event.preventDefault();
        openTrust.open = false;
        openTrust.querySelector("summary")?.focus();
        return;
      }
    }
    const commandModifier = event.metaKey || event.ctrlKey;
    if (commandModifier && event.key.toLowerCase() === "k") {
      event.preventDefault();
      openWorkspaceCommandPalette();
      return;
    }
    if (commandModifier && event.key.toLowerCase() === "f" && !event.target.closest("input, textarea, [contenteditable='true']")) {
      const readerPanel = track.querySelector(".reader-panel:not(.is-workflow-hidden)");
      const searchToggle = readerPanel?.querySelector(".reader-internal-search-toggle");
      if (searchToggle) {
        event.preventDefault();
        if (searchToggle.getAttribute("aria-pressed") !== "true") searchToggle.click();
        requestAnimationFrame(() => readerPanel.querySelector(".reader-internal-search-input")?.focus());
      }
      return;
    }
    if (commandModifier && /^[1-5]$/.test(event.key)) {
      const pane = track.querySelectorAll(":scope > .workspace-panel:not(.is-workflow-hidden)")[Number(event.key) - 1];
      if (pane?.dataset.paneId) {
        event.preventDefault();
        scrollPaneIntoView(pane.dataset.paneId);
        pane.querySelector("button, input, select, textarea")?.focus({ preventScroll: true });
      }
      return;
    }
  });
}

function bindImmediateUtilityControls() {
  document.querySelectorAll('[data-workflow-view]').forEach(button => {
    if (button.dataset.bound) return;
    button.dataset.bound = 'true';
    button.addEventListener('click', () => void switchWorkflowView(button.dataset.workflowView));
  });
  const detailsButton = document.querySelector("#open-project-details");
  if (detailsButton && !detailsButton.dataset.bound) {
    detailsButton.dataset.bound = "true";
    detailsButton.addEventListener("click", () => void openProjectDetailsScreen());
  }
  [
    [toggleContextButton, "context"],
    [toggleFactsButton, "facts"],
    [toggleNotebookButton, "notebook"],
    [toggleReportButton, "report"]
  ].forEach(([button, tool]) => {
    if (!button || button.dataset.coldStartBound === "true") return;
    button.dataset.coldStartBound = "true";
    button.addEventListener("click", () => {
      if (notifyProjectRequiredForColumn()) return;
      void (["context", "facts"].includes(tool) ? toggleProjectInformation(tool) : tool === "notebook" ? openProjectNotebook(workspaceProject()) : tool === "report" ? openProjectReportDraft(workspaceProject()) : toggleProjectTool(tool));
    });
  });
  if (track.dataset.utilityFocusBound !== "true") {
    track.dataset.utilityFocusBound = "true";
    const remember = (event) => {
      const paneID = event.target.closest?.('.workspace-panel')?.dataset.paneId;
      if (paneID) rememberUtilityColumn(paneID);
    };
    track.addEventListener("focusin", remember);
    track.addEventListener("pointerdown", remember, { passive: true });
  }
  if (toggleSearchButton.dataset.coldStartBound !== "true") {
    toggleSearchButton.dataset.coldStartBound = "true";
    toggleSearchButton.addEventListener("click", () => {
      if (notifyProjectRequiredForColumn()) return;
      void focusRecentUtilityColumn("search");
    });
  }
  if (releaseSurfaceVisibility.workboard && toggleWorkboardButton?.dataset.coldStartBound !== "true") {
    toggleWorkboardButton.dataset.coldStartBound = "true";
    toggleWorkboardButton.addEventListener("pointerenter", () => void loadWorkboardModule().catch(() => {}), { once: true });
    toggleWorkboardButton.addEventListener("focus", () => void loadWorkboardModule().catch(() => {}), { once: true });
    toggleWorkboardButton.addEventListener("click", () => void toggleGenericWorkboard());
  }
  if (toggleAnalysisButton?.dataset.coldStartBound !== "true") {
    toggleAnalysisButton.dataset.coldStartBound = "true";
    toggleAnalysisButton.addEventListener("click", () => {
      if (notifyProjectRequiredForColumn()) return;
      void focusRecentUtilityColumn("analysis");
    });
  }
  if (toggleSavedButton.dataset.coldStartBound === "true") return;
  toggleSavedButton.dataset.coldStartBound = "true";
  toggleSavedButton.addEventListener("click", () => {
    if (notifyProjectRequiredForColumn()) return;
    void focusRecentUtilityColumn("saved");
  });
}

function refreshVisibleReaderTrust() {
  track.querySelectorAll(".reader-panel[data-reader-id]").forEach((panel) => {
    const reader = state.readers.find((item) => item.id === panel.dataset.readerId);
    if (reader) renderReaderTrust(panel, reader);
  });
}

function loadStartupCatalogs() {
  if (startupCatalogPromise) return startupCatalogPromise;
  codeTrustProfilesStatus = "loading";
  refreshVisibleReaderTrust();
  const chapterRequest = api("/code/chapters?view=startup").then((payload) => {
    chapters = payload.chapters || [];
  }).catch(() => {
    // Reader selectors fetch the requested code family independently. Search
    // retains its complete built-in code choices when this optional index fails.
    console.warn("Startup chapter metadata unavailable; requested code navigation remains available.");
  });
  const trustRequest = api("/code/libraries").then((payload) => {
    codeTrustProfiles = payload.codeTrustProfiles || [];
    codeTrustProfilesStatus = codeTrustProfiles.length ? "ready" : "unavailable";
  }).catch(() => {
    codeTrustProfilesStatus = "unavailable";
  }).finally(refreshVisibleReaderTrust);
  const request = Promise.all([chapterRequest, trustRequest]).finally(() => {
    if (startupCatalogPromise === request) startupCatalogPromise = null;
  });
  startupCatalogPromise = request;
  return request;
}

async function start() {
  void publicCodeRevision.probe();
  window.setInterval(() => { if (document.visibilityState === "visible") void publicCodeRevision.probe(); }, 60000);
  if (detachedWorkboardRoute && !detachedProjectWindow) {
    throw new Error("This detached Workboard session expired. Close this window and detach the Workboard again.");
  }
  if (!detachedProjectWindow) {
    bindImmediateUtilityControls();
    // Public metadata supplements the shell. Authentication restoration still
    // completes before any private workspace is rendered.
    void loadStartupCatalogs();
    await resumeClerkSignInReturn();
  }
  updateConnectionStatus();
  document.addEventListener("click", (event) => {
    if (
      activeCustomSelect &&
      !activeCustomSelect.custom.contains(event.target) &&
      !activeCustomSelect.menu.contains(event.target)
    ) {
      closeActiveCustomSelect();
    }
    document.querySelectorAll(".reader-trust[open]").forEach((trust) => {
      if (!trust.contains(event.target)) trust.open = false;
    });
    if (
      workspaceContextMenu &&
      !workspaceContextMenu.contains(event.target) &&
      !event.target.closest(".workspace-tab, .workspace-actions-button")
    ) {
      closeWorkspaceContextMenu();
    }
  });
  window.addEventListener("resize", repositionActiveCustomSelect);
  window.addEventListener("resize", keepFocusedWorkspacePaneVisible, { passive: true });
  window.addEventListener("resize", scheduleVisibleReaderScrollIndicatorUpdates, { passive: true });
  window.addEventListener("resize", syncReferenceReaderLayout, { passive: true });
  track.addEventListener("permitext:workspace-layout-change", scheduleVisibleReaderScrollIndicatorUpdates);
  bindWorkspaceKeyboardNavigation();
  window.addEventListener("storage", (event) => {
    if (event.key === null || event.key.startsWith("permitext.active-code-sources.v1.")) {
      activeCodeSourcesController.reload();
      if (event.key !== null) return;
    }
    if (event.key === foregroundSyncSignalKey && event.newValue) {
      try {
        void handleForegroundSyncSignal(JSON.parse(event.newValue));
      } catch {
        // Ignore malformed cross-tab sync signals.
      }
      return;
    }
    if (event.key === accountSessionKey) {
      let nextAccount = null;
      try {
        nextAccount = event.newValue ? JSON.parse(event.newValue) : null;
      } catch {
        nextAccount = null;
      }
      if (clientValuesMatch(state.account || null, nextAccount)) return;
      replaceActiveAccount(nextAccount);
      codeQuestionUnauthorizedAccountUserID = "";
      if (activeAccount()) {
        startForegroundSyncLoop({ immediate: true });
      } else {
        stopForegroundSyncLoop();
      }
      void renderWorkspace().then(() => resumePendingResearchIntent());
      return;
    }
    if (
      state.account?.userID &&
      event.key === codeQuestionAccountCacheKey(state.account.userID)
    ) {
      let incomingAccountState;
      try {
        incomingAccountState = normalizeCodeQuestionAccountState(
          event.newValue ? JSON.parse(event.newValue) : {},
          { accountUserID: state.account.userID }
        );
      } catch {
        return;
      }
      const currentAccountState = {
        ...emptyCodeQuestionAccountState(state.account.userID),
        accessByProjectID: Object.fromEntries(codeQuestionAccessByProject),
        outbox: state.codeQuestionOutbox || [],
        conflicts: state.codeQuestionConflicts || []
      };
      const incomingDomain = codeQuestionAccountDomainState(incomingAccountState, activeWorkspaceID);
      const currentDomain = codeQuestionAccountDomainState(currentAccountState, activeWorkspaceID, {
        workspace: state.codeQuestionWorkspace || emptyCodeQuestionWorkspaceState()
      });
      if (clientValuesMatch(incomingDomain, currentDomain)) return;
      loadCodeQuestionAccountStateIntoWorkspace(state.account.userID, {
        accountState: incomingAccountState,
        preservePresentation: true
      });
      void renderWorkspace({ persist: false });
      return;
    }
    if (event.key === baseWorkspaceKey) applySharedWorkspaceState(event.newValue);
    if (!detachedProjectWindow && event.key === workspaceRegistryKey && event.newValue) {
      try {
        const nextRegistry = normalizeWorkspaceRegistry(JSON.parse(event.newValue), {
          activeWorkspaceID
        });
        const activeStillExists = nextRegistry.workspaces.some((workspace) => workspace.id === activeWorkspaceID);
        workspaceRegistry = nextRegistry;
        if (activeStillExists) {
          workspaceRegistry.activeWorkspaceID = activeWorkspaceID;
          renderWorkspaceTabs();
        } else {
          void switchWorkspace(nextRegistry.activeWorkspaceID);
        }
      } catch {
        // Ignore malformed registry updates from another tab.
      }
    }
    if (!detachedProjectWindow && event.key === "permitext:pendingWorkboardReattach" && event.newValue) {
      try {
        void reattachProjectWorkboard(JSON.parse(event.newValue));
      } catch {
        localStorage.removeItem("permitext:pendingWorkboardReattach");
      }
    }
  });
  window.addEventListener("online", () => {
    void publicCodeRevision.probe({ force: true, reconnect: true });
    serverReachable = true;
    updateConnectionStatus();
    startForegroundSyncLoop({ immediate: true });
    void flushCodeQuestionOutbox();
    void flushPendingNotebookImages();
  });
  window.addEventListener("offline", () => {
    serverReachable = false;
    updateConnectionStatus();
    stopForegroundSyncLoop();
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState !== "visible") {
      flushSearchQueryPersistence();
      flushResearchDraftPersistence();
    }
    if (document.visibilityState === "visible") {
      void publicCodeRevision.probe();
      startForegroundSyncLoop({ immediate: true });
    } else {
      stopForegroundSyncLoop();
    }
  });
  window.addEventListener("pagehide", flushSearchQueryPersistence);
  window.addEventListener("pagehide", flushResearchDraftPersistence);
  window.addEventListener("pagehide", stopForegroundSyncLoop);
  window.addEventListener("pagehide", saveWorkspaceResumeForRefresh);
  window.addEventListener("beforeunload", saveWorkspaceResumeForRefresh);
  track.addEventListener("scroll", repositionActiveCustomSelect, { passive: true });
  track.addEventListener("scroll", scheduleVisibleReaderScrollIndicatorUpdates, { passive: true });
  bindHorizontalWheelScroll(track);
  if (detachedProjectWindow) {
    if (!detachedProject) throw new Error("This detached Workboard no longer has a project session.");
    window.addEventListener("pagehide", () => {
      if (window.opener && !window.opener.closed) {
        window.opener.postMessage(
          { type: "permitext:detachedWorkboardClosed", project: detachedProject },
          window.location.origin
        );
      }
    }, { once: true });
    await renderWorkspace();
    void flushPendingSyncAndRender().catch(() => {});
    return;
  }
  window.addEventListener("message", (event) => {
    if (event.origin !== window.location.origin) return;
    if (event.data?.type === "permitext:reattachWorkboard") {
      void reattachProjectWorkboard(event.data.project, event.source);
      return;
    }
    if (event.data?.type === "permitext:detachedWorkboardClosed") {
      state.detachedWorkboards = detachedWorkboards().filter((item) => !projectDetailMatches(event.data.project, item));
      syncProjectToolButtonStates(event.data.project);
      saveWorkspaceState();
      void transitionWorkspace("utility");
    }
  });
  window.addEventListener("hashchange", () => {
    if (!codeQuestionWorkspaceEnabled()) return;
    if (applyCodeQuestionDeepLinkFromLocation()) {
      void renderWorkspace();
    }
  });
  if (codeQuestionWorkspaceEnabled()) {
    applyCodeQuestionDeepLinkFromLocation();
  }
  try {
    const pendingReattach = JSON.parse(localStorage.getItem("permitext:pendingWorkboardReattach") || "null");
    if (pendingReattach) await reattachProjectWorkboard(pendingReattach);
  } catch {
    localStorage.removeItem("permitext:pendingWorkboardReattach");
  }
  document.querySelectorAll('[data-open-reader]').forEach(bindReaderToolbarButton);
  toggleArchiveButton?.addEventListener("click", () => {
    toggleUtilityPane("archive");
  });
  toggleSettingsButton.addEventListener("click", () => {
    toggleUtilityPane("settings");
  });
  workspaceActionsButton?.addEventListener("click", () => {
    if (workspaceContextMenu) {
      closeWorkspaceContextMenu();
      return;
    }
    openWorkspaceContextMenu(activeWorkspaceID, workspaceActionsButton);
  });
  mobileMoreButton?.addEventListener("click", openMobileMoreSheet);
  window.matchMedia("(max-width: 760px)").addEventListener("change", (event) => {
    if (!event.matches) closeMobileMoreSheet({ restoreFocus: false });
  });
  document.querySelector("#open-column-groups")?.addEventListener("click", () => openSavedColumnGroupsMenu());
  fitColumnsButton.addEventListener("click", () => {
    resetVisibleColumnWidths();
  });
  document.querySelector("#collapse-all-columns").addEventListener("click", () => setAllColumnsCollapsed(true));
  document.querySelector("#expand-all-columns").addEventListener("click", () => setAllColumnsCollapsed(false));
  collapseReadersButton.addEventListener("click", () => {
    closeAllColumns();
  });
  const deepLinkedSectionID = deepLinkedSectionIDFromLocation();
  consumeBrowserSectionURL();
  if (organizationInvitationTokenFromURL()) {
    state.utilities.settings = true;
    saveWorkspaceState();
  }
  await renderWorkspace();
  void refreshNotebookPendingStatus().catch(() => {});
  if (workspaceRestoreError) {
    void showWebNotice("Saved workspace recovery needed", "This browser could not restore your saved workspace. The original data is preserved. Reload to retry before making changes; this temporary workspace will not be saved. Avoid clearing site data.");
  }
  if (workspaceMigrationError && activeAccount()?.userID === initialPersistedAccount?.userID) {
    void showWebNotice("Saved workspace recovery needed", "This browser could not finish moving your existing workspace into account-specific storage. The original saved data is still present. Free browser storage, then reload to retry; avoid clearing site data.");
  }

  track.scrollLeft = Math.min(
    Number(state.trackScrollLeft) || 0,
    Math.max(0, track.scrollWidth - track.clientWidth)
  );
  if (deepLinkedSectionID) {
    try {
      await openDeepLinkedSectionInReader({sectionID: deepLinkedSectionID});
    } catch (error) {
      console.warn("Could not open shared section link.", error);
      window.history.replaceState({}, "", "/");
    }
  }
  await restoreWorkspaceAfterRefresh(Boolean(deepLinkedSectionID || organizationInvitationTokenFromURL()));
  void flushPendingSyncAndRender().catch(() => {});
  void flushCodeQuestionOutbox().catch(() => {});
  startForegroundSyncLoop();
  await refreshEntitlementAfterCheckoutReturn();
  await setupAccountProfile().catch(error => console.warn("Profile setup unavailable", error));
  await resumePendingResearchIntent();
  await resumePendingProSave();
  await resumeProUpgradeIntent();
}

function renderWorkspaceLoadError(error) {
  track.querySelectorAll(".search-panel").forEach(cancelSearchPanelRequest);
  clear(track);
  const panel = document.createElement("article");
  panel.className = "workspace-panel workspace-load-error";
  panel.setAttribute("role", "alert");
  const title = document.createElement("h1");
  title.tabIndex = -1;
  title.textContent = detachedWorkboardRoute ? "Workboard unavailable" : "Workspace unavailable";
  const message = document.createElement("p");
  message.textContent = detachedWorkboardRoute
    ? String(error?.message || "The Workboard could not be loaded.")
    : `Permitext could not load this workspace. ${String(error?.message || "Please try again.")}`;
  const retry = document.createElement("button");
  retry.type = "button";
  retry.className = "toolbar-button";
  retry.textContent = "Try again";
  retry.addEventListener("click", () => window.location.reload());
  panel.append(title, message, retry);
  track.append(panel);
  title.focus({ preventScroll: true });
}

window.addEventListener("error", (event) => {
  reportClientError("error", event.error, {
    name: event.error?.name || "ErrorEvent",
    message: event.message,
    source: event.filename,
    line: event.lineno,
    column: event.colno
  });
});
window.addEventListener("unhandledrejection", (event) => {
  const reason = event.reason instanceof Error ? event.reason : new Error(String(event.reason || "Unhandled rejection"));
  reportClientError("unhandledrejection", reason);
});

start().catch((error) => {
  console.error(error);
  reportClientError("startup", error);
  renderWorkspaceLoadError(error);
});

// Dismiss the Layout popover after an action, outside click, or Escape.
const layoutMenu = document.querySelector(".topbar-layout-menu");
layoutMenu.addEventListener("click", (event) => {
  if (event.target.closest("button")) layoutMenu.open = false;
});
document.addEventListener("click", (event) => {
  if (!layoutMenu.contains(event.target)) layoutMenu.open = false;
});
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && layoutMenu.open) {
    layoutMenu.open = false;
    layoutMenu.querySelector("summary").focus();
  }
});

// Close workspace disclosures when clicking elsewhere.
document.addEventListener("pointerdown", event => {
  document.querySelectorAll(".search-match-control[open], .report-draft-version-list[open], .notebook-note-menu[open]").forEach(control => {
    if (!control.contains(event.target)) control.open = false;
  });
});
